import{G as o,T as t,C as n}from"./canonicalScripts-BJzxcE-P.js";const r={S1:{id:"S1",categoryId:"scenarios",title:"The Drunk Customer",titleEs:"El Cliente Borracho",subtitle:"Be lovely, take nothing, get on with your day",subtitleEs:"Sé encantador, no le cobres nada y sigue con tu día",duration:"4 min",icon:"AlertTriangle",order:8,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:`Two o'clock on a Saturday in {locationName}. A hen crowd comes down the street and one of them peels off towards you — loud, slurring, half a bottle of something in her. "OI! What's that then?! Make me beautiful!" She has hold of your arm, she is far too close, and her mates are laughing instead of helping. She wants a demo. Her card is already out of her bag. Everything in you is shouting sale. Read the rest before you touch that card.`,textEs:'Las dos de la tarde de un sábado en {locationName}. Baja por la calle un grupo de despedida y una se separa y viene a por ti — a gritos, arrastrando las palabras, con media botella encima. "¡EY! ¿Y eso qué es? ¡Ponme guapa!" Te tiene cogido del brazo, está demasiado cerca, y sus amigas se ríen en vez de ayudar. Quiere una demo. Ya ha sacado la tarjeta del bolso. Todo tu cuerpo te está gritando venta. Léete el resto antes de tocar esa tarjeta.'},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["SEE WHICH KIND OF DRUNK SHE IS. Happy and daft, you can be lovely to her and move her along in thirty seconds. Looking for an argument — you are done, right now, before it turns into a scene with an audience.","PUT SOMETHING BETWEEN YOU. Half a step back, table in the middle. Someone who has been drinking has no idea where your personal space ends, so you draw the line for both of you.","NOTHING GOES ON HER FACE. If you are going to show her anything at all, show it on your own hand. Product on a drunk woman's face is a scene with three phones pointing at it, and you are the one in the frame.","TALK TO THE SOBER ONE. There is always one holding the bags and the phones. She decides where the group goes next, and she will like you for being the seller who did not take advantage of her mate.",'IF IT TURNS, STOP. Stop talking. Step back. Hand up. "Not today." Then get a colleague or your manager over. There is nothing on that table worth standing there for.'],itemsEs:["MIRA QUÉ CLASE DE BORRACHA ES. Si va contenta y tonta, puedes ser encantador con ella y despacharla con buen rollo en treinta segundos. Si va buscando bronca — se acabó, ya, antes de que se monte el numerito con público.","PON ALGO ENTRE LOS DOS. Medio paso atrás y la mesa por medio. Quien ha bebido no tiene ni idea de dónde acaba tu espacio, así que la raya la pintas tú por los dos.","EN LA CARA NO LE PONES NADA. Si le vas a enseñar algo, se lo enseñas en tu propia mano. Producto en la cara de una borracha es una escena con tres móviles grabando, y el que sale en el vídeo eres tú.","HABLA CON LA QUE ESTÁ SOBRIA. Siempre hay una que lleva los bolsos y los móviles. Es la que decide adónde va el grupo después, y le vas a caer bien por ser el vendedor que no se aprovechó de su amiga.",'SI SE TUERCE, PARA. Deja de hablar. Da un paso atrás. Mano arriba. "Hoy no." Y llama a un compañero o al encargado. No hay nada en esa mesa que merezca quedarse ahí aguantando.']},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Work on her face. Not the wrinkle, not the eye, nothing. Your own hand or nothing at all.","Take her card. Don't touch a drunk woman's card. Next week the bank pulls the money straight back out, the shop swallows it, and she goes home telling everyone she got done in {locationName}. All that work for nothing.","Laugh at her. Her mates can. You can't. Everybody else on that pavement is watching how you treat the one who can't look after herself, and deciding whether to stop at your table later.","Let yourself get boxed in. Keep the door, or a colleague's eyeline, over your shoulder. Never let the group close around you."],itemsEs:["Trabajarle la cara. Ni la arruga, ni el ojo, nada. Tu propia mano o nada.","Cogerle la tarjeta. A una borracha no le tocas la tarjeta. La semana que viene el banco saca el dinero otra vez, se lo come la tienda, y ella se va a casa contando por ahí que la timaron en {locationName}. Todo ese trabajo para nada.","Reírte de ella. Sus amigas pueden. Tú no. Todo el mundo en esa acera está mirando cómo tratas a la que no se puede cuidar sola, y decidiendo si luego para en tu mesa o no.","Dejar que te encierren. Ten la puerta, o la mirada de un compañero, por encima del hombro. Que el grupo no se te cierre alrededor."]},{type:"subheader",text:"Script — Too Much Fun For Me Today",textEs:"Guion — Hoy Eres Demasiado Fiesta Para Mí"},{type:"script",text:`YOU: "Whoa — you are TOO much fun for me today." [Half a step back, hands up, big smile] "Come and see us tomorrow morning when it's quiet — you'll get the full show."`,textEs:'TÚ: "Uy — hoy eres DEMASIADO fiesta para mí." [Medio paso atrás, manos arriba, sonrisa grande] "Pasaos mañana por la mañana, que está tranquilo — os hacemos el espectáculo entero."'},{type:"subheader",text:"Script — The Step Back",textEs:"Guion — El Paso Atrás"},{type:"script",text:`YOU: "Alright, alright — give me a bit of room, love." [Step back yourself, hands where she can see them] "I'm not doing this on you today. But your friend here looks ready." [Turn your whole body to the sober one, warm as anything] "Come on, you. Give me your hand."`,textEs:'TÚ: "Vale, vale — dame un poco de aire, guapa." [Retrocede tú también, las manos a la vista] "Hoy a ti no te lo hago. Pero tu amiga sí que tiene pinta de estar lista." [Gira el cuerpo entero hacia la que está sobria, con todo el cariño] "Venga, tú. Dame la mano."'},{type:"subheader",text:"Script — Getting Help",textEs:"Guion — Pedir Ayuda"},{type:"script",text:`YOU: "That's it for today. Step back for me, please." [Hand up, eyes on the nearest colleague or the security guard] "Marco! Give me a hand here!" [To the friends — calm, not cross] "Girls, take her for a coffee. Go on."`,textEs:'TÚ: "Ya está por hoy. Da un paso atrás, por favor." [Mano arriba, la mirada en el compañero o el de seguridad más cercano] "¡Marco! ¡Échame una mano!" [A las amigas — con calma, sin enfadarte] "Chicas, llevadla a tomar un café. Venga."'},{type:"subheader",text:"Script — The Card Goes Away",textEs:"Guion — La Tarjeta Se Guarda"},{type:"script",text:`YOU: "Put that away, put it away." [Laughing, a hand over hers, easing the card back towards her bag] "I'm not taking your money today, my love. Not like this. Go on — go and enjoy your afternoon."`,textEs:'TÚ: "Guárdala, guárdala." [Riéndote, la mano sobre la suya, empujándole la tarjeta otra vez hacia el bolso] "Hoy no te cobro nada, guapa. Así no. Anda — ve a disfrutar de la tarde."'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:"Know the shop's rule before it happens, because with a hen party shouting in your face you will not be thinking clearly. Then trust your gut — if she feels like trouble, she is trouble. And do the sums: twenty minutes on her is twenty minutes off the sober woman walking past who would have taken two. Letting this one go isn't losing a sale. It's refusing to buy a problem with the shop's money.",textEs:"Sábete la norma de la tienda antes de que pase, porque con una despedida de soltera gritándote en la cara no vas a pensar con claridad. Y luego fíate de tu instinto: si te huele a lío, es un lío. Y echa la cuenta: veinte minutos con ella son veinte minutos que le quitas a la mujer sobria que pasa por delante y que se habría llevado dos. Dejar ir a esta no es perder una venta. Es no comprar un problema con el dinero de la tienda."}],quiz:[{question:"She is slurring, her card is already out, and she wants it on her face. What do you take?",questionEs:"Arrastra las palabras, ya ha sacado la tarjeta y lo quiere en la cara. ¿Qué le coges?",options:["The card — she is an adult and she has decided","The card, but do the demo on her hand instead","Nothing today, and tell her mates she is being a nightmare","Nothing. Be lovely, send her off happy, back to work"],optionsEs:["La tarjeta — es adulta y ya lo ha decidido","La tarjeta, pero le haces la demo en la mano","Nada hoy, y les dices a sus amigas que es un desastre","Nada. Sé encantador, despídela contenta y a trabajar"],correctIndex:3,explanation:"Next week the bank pulls the money straight back out, the shop swallows it, and she tells everyone she got done. All that work for nothing.",explanationEs:"La semana que viene el banco saca el dinero otra vez, se lo come la tienda y ella va contando que la timaron. Todo ese trabajo para nada."},{question:"If you show her anything at all, where does the product go?",questionEs:"Si le enseñas algo, ¿dónde va el producto?",options:["On the wrinkle she keeps pointing at, carefully","On her hand, so she can wash it off afterwards","On your own hand, or nowhere at all","On her face but only a little, so she can see it works"],optionsEs:["En la arruga que no para de señalar, con cuidado","En su mano, así se lo puede lavar después","En tu propia mano, o en ningún sitio","En la cara pero solo un poco, para que vea que funciona"],correctIndex:2,explanation:"Product on a drunk woman is a scene with three phones pointing at it, and you are the one in the video.",explanationEs:"Producto en una borracha es un numerito con tres móviles apuntando, y el del vídeo eres tú."},{question:"Her mates are laughing at the state of her. What do you do?",questionEs:"Sus amigas se están riendo de cómo va. ¿Qué haces?",options:["Join in — matching the energy keeps the group with you","Stay out of it, be decent, and let the street see that","Tell them off, then get on with the demo you were doing","Use it — a bit of teasing is what gets a hen group buying"],optionsEs:["Apuntarte — seguirles el rollo te mantiene al grupo","No entrar, ser decente, y que la calle lo vea","Reñirles y seguir con la demo que estabas haciendo","Aprovecharlo — un poco de guasa es lo que hace comprar"],correctIndex:1,explanation:"Everybody on that pavement is watching how you treat the one who cannot look after herself, and deciding whether to stop at your table later.",explanationEs:"Todo el mundo en esa acera está mirando cómo tratas a la que no se puede cuidar sola, y decidiendo si luego para en tu mesa."}]},S2:{id:"S2",categoryId:"scenarios",title:"The Demo That Failed",titleEs:"La Demo Que Falló",subtitle:"The wrinkle didn't move, and four people are watching",subtitleEs:"La arruga no se ha movido y hay cuatro personas mirando",duration:"5 min",icon:"XCircle",order:1,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:`You're doing the wrinkle demo on a woman from Manchester. Sixty seconds go by. She takes the mirror, and the line is exactly where it was. She hands it back, folds her arms, and says it out loud so everyone hears: "See? Doesn't work. It's all a con, isn't it." There are four people stood behind her watching. You get one line to fight this. If that line doesn't move her, the demo is dead — and what you do in the ten seconds after that decides whether those four stay or all walk off with her.`,textEs:'Estás haciendo la demo de la arruga a una señora de Manchester. Pasan sesenta segundos. Coge el espejo y la línea sigue exactamente donde estaba. Te devuelve el espejo, se cruza de brazos y lo dice en alto para que lo oiga todo el mundo: "¿Ves? No funciona. Es todo un cuento, ¿no?" Detrás de ella hay cuatro personas mirando. Tienes una frase para pelearlo. Si esa frase no la mueve, la demo está muerta — y lo que hagas en los diez segundos siguientes decide si esas cuatro se quedan o se van todas con ella.'},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["DON'T PANIC — THEY'RE READING YOUR FACE. Go red and start talking fast and the little crowd has just watched a con come apart. Go curious instead — head on one side, looking at her skin like a puzzle — and you're a professional working something out.",`ONE LINE. THAT IS YOUR WHOLE FIGHT. Two seconds, not two minutes. "You're right, that's not what I wanted either — what did you put on this morning?" Agreeing costs you nothing, takes the fight out of the air, and buys you the only thing worth having here: a clean face and a second go.`,"IF SHE GIVES YOU THE SECOND GO, YOU'RE ALIVE. Clean the spot properly — cream, sun cream, foundation, primer, anything on top and the product never got near her. More product this time, more pressure, and narrate every step so the crowd hears you working. That second attempt is the demo they'll remember, because they watched you earn it.","IF SHE DOESN'T MOVE, IT'S DEAD. No second line, no third go, and nothing else comes off the table. There is no point trying to sell to a dead body — get them out of the shop and go and get the next one. The money is in the next one, and she is walking past you while you stand there arguing.","LEAVE CLEAN, BECAUSE OF THE FOUR PEOPLE WATCHING. This is one of only three times you let a customer walk, and it is the only one that ever happens with an audience — which is exactly why it has to look easy. Thank her, mean it, turn to the next face without a mark on you. Flail and all four leave with her."],itemsEs:["NO TE PONGAS NERVIOSO — TE ESTÁN MIRANDO LA CARA. Si te pones rojo y empiezas a hablar rápido, el corrillo acaba de ver cómo se cae un timo. Ponte curioso en cambio — la cabeza ladeada, mirándole la piel como si fuera un puzle — y eres un profesional resolviendo algo.",'UNA FRASE. ESA ES TODA TU PELEA. Dos segundos, no dos minutos. "Tienes razón, a mí tampoco me ha salido lo que quería — ¿qué te has puesto esta mañana?" Darle la razón no te cuesta nada, le quita la bronca al momento y te compra lo único que merece la pena aquí: la cara limpia y un segundo intento.',"SI TE DA EL SEGUNDO INTENTO, ESTÁS VIVO. Limpia bien la zona — crema, crema solar, base, prebase; si hay algo encima, el producto no le ha llegado ni a tocar la piel. Esta vez más producto y más presión, y ve contando cada paso para que el corrillo te oiga trabajar. Ese segundo intento es la demo que van a recordar, porque te han visto ganártela.","SI NO SE MUEVE, ESTÁ MUERTA. Ni una segunda frase, ni un tercer intento, ni sacas nada más de la mesa. No tiene sentido intentar venderle a un cuerpo muerto — los sacas de la tienda y vas a por el siguiente. El dinero está en el siguiente, y te está pasando por delante mientras tú discutes.","SAL LIMPIO, POR LAS CUATRO PERSONAS QUE MIRAN. Es una de las tres únicas veces que dejas marchar a una clienta, y la única que pasa delante de público — justo por eso tiene que parecer fácil. Dale las gracias, de verdad, y gírate a la siguiente cara sin una marca encima. Si te descompones, se van las cuatro con ella."]},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Pretend it worked. "You can't see it but I can" — every person watching knows you just lied, and that's your afternoon on that corner finished.`,"Reach for another product. The scrub is not a rescue boat. Dragging a corpse through a second pitch in front of an audience loses you the audience as well as her.","Blame her skin. Insult a woman's face in front of an audience and you lose the audience, not just her.",`Get defensive. "It works on everyone, I don't know what's wrong with you" is an excuse in a white coat. Curious beats defensive every single time.`,"Drop the price to save it. She hasn't said no to the money, she's said no to the product. Cheaper doesn't buy that back, and now four strangers know your numbers move when you panic."],itemsEs:['Hacer como que ha funcionado. "Tú no lo ves pero yo sí" — todos los que están mirando saben que acabas de mentir, y ahí se te acaba la tarde en esa esquina.',"Echar mano de otro producto. El exfoliante no es un bote salvavidas. Arrastrar un cadáver por un segundo discurso delante de público te cuesta el público además de ella.","Culpar a su piel. Insúltale la cara a una mujer delante de público y pierdes al público, no solo a ella.",'Ponerte a la defensiva. "Le funciona a todo el mundo, no sé qué te pasa a ti" es una excusa con bata blanca. Curioso le gana a defensivo siempre.',"Bajar el precio para salvarla. No le ha dicho que no al dinero, le ha dicho que no al producto. Más barato no te lo devuelve, y ahora cuatro desconocidos saben que tus números se mueven cuando te pones nervioso."]},{type:"subheader",text:"Script — Your One Line",textEs:"Guion — Tu Única Frase"},{type:"script",text:`YOU: "Yeah. I see it too, and I'm not going to stand here telling you it worked." [Look at her skin, not at her] "What did you put on this morning — cream? Sun cream? Make-up?" [She says yes] "There it is. That's a layer sitting between me and your skin. Thirty seconds to take it off and we go again." [That is the whole fight. Now watch her arms.]`,textEs:'TÚ: "Sí. Yo también lo veo, y no me voy a quedar aquí diciéndote que ha funcionado." [Mírale la piel, no a ella] "¿Qué te has puesto esta mañana — crema? ¿Crema solar? ¿Maquillaje?" [Dice que sí] "Ahí lo tienes. Eso es una capa entre tu piel y yo. Treinta segundos para quitártela y lo repetimos." [Esa es toda la pelea. Ahora mírale los brazos.]'},{type:"subheader",text:"Script — She Unfolds Her Arms",textEs:"Guion — Descruza los Brazos"},{type:"script",text:`YOU: "Good girl. Sit back for me." [Clean the whole spot properly and say out loud what you are doing] "More product this time, and I'm pressing harder." [To the four of them, not to her] "Anybody can sell when it works first time. You lot are getting the interesting bit." [Count it down out loud, and put the mirror in her hand the second it lands.]`,textEs:'TÚ: "Muy bien. Échate para atrás." [Limpia bien toda la zona y ve diciendo en alto lo que haces] "Esta vez más producto, y aprieto más." [A los cuatro, no a ella] "Vender cuando sale a la primera lo hace cualquiera. Vosotros os estáis llevando la parte interesante." [Cuenta atrás en voz alta, y ponle el espejo en la mano en cuanto salga.]'},{type:"subheader",text:"Script — When It's Dead, It's Dead",textEs:"Guion — Si Está Muerta, Está Muerta"},{type:"script",text:`YOU: "Fair enough. It didn't do what I said it would, and I'm not going to argue with a mirror." [Straight, warm, smile still on, not one sour word in it] "Keep your money, my love. Off you go." [And that is it. No second product, no cheaper number, no third go. She had her two seconds and she has spent them.]`,textEs:'TÚ: "Pues nada. No ha hecho lo que yo he dicho que haría, y no me voy a poner a discutir con un espejo." [Directo, con cariño, la sonrisa puesta, sin una gota de rencor] "Guárdate el dinero, guapa. Anda, ve." [Y ya está. Ni otro producto, ni un número más bajo, ni un tercer intento. Ha tenido sus dos segundos y ya los ha gastado.]'},{type:"subheader",text:"Script — Straight To The Next One",textEs:"Guion — Directo al Siguiente"},{type:"script",text:`YOU: [She has gone. Don't stand there watching her go — turn to the four people still stood behind you] "Right. You've been watching me for five minutes, so you already know I'll tell you the truth." [Hand out, big, not a flicker of the last two minutes on your face] "Give me your hand. Sixty seconds, and you tell me whether it's a con."`,textEs:'TÚ: [Se ha ido. No te quedes ahí mirando cómo se va — gírate hacia las cuatro personas que siguen detrás] "Venga. Lleváis cinco minutos mirándome, así que ya sabéis que os voy a decir la verdad." [La mano tendida, en grande, sin que se te note nada de los dos últimos minutos] "Dame la mano. Sesenta segundos, y me dices tú si es un cuento."'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:"A demo that dies in front of people is still the best advert you'll get all day — as long as you stay curious instead of scared, and as long as you know when to stop. You get one line. If she takes it, clean the skin, go again, and they'll talk about that demo for a week. If she doesn't take it, she is a dead body and there is nothing left in her for you: no scrub, no cheaper number, no third go. This is one of only three times you let a customer walk, and it's the only one that ever happens with an audience — which is exactly why you go quickly and quietly instead of flailing. They aren't judging whether the product worked. They're judging whether you fall apart when it doesn't. And stop it happening where you can: ask about cream before you touch a face, clean the spot properly, work somewhere you've actually looked at.",textEs:"Una demo que se muere delante de gente sigue siendo el mejor anuncio del día, siempre que te pongas curioso en vez de asustado y siempre que sepas cuándo parar. Tienes una frase. Si te la coge, limpias la piel, lo repites, y van a hablar de esa demo una semana. Si no te la coge, es un cuerpo muerto y ahí ya no queda nada para ti: ni exfoliante, ni un número más bajo, ni un tercer intento. Es una de las tres únicas veces que dejas marchar a una clienta, y la única que pasa delante de público — justo por eso te vas rápido y sin ruido en vez de descomponerte. No están juzgando si el producto ha funcionado. Están juzgando si te desmoronas cuando no funciona. Y evítalo cuando puedas: pregunta por la crema antes de tocar una cara, limpia bien la zona, trabaja en un sitio que hayas mirado de verdad."}],quiz:[{question:'She says "See? It does not work, it is a con" and four people are listening. How much fight have you got?',questionEs:'Suelta "¿Ves? No funciona, es un cuento" y hay cuatro personas escuchando. ¿Cuánta pelea te queda?',options:["One line. Agree, ask about the cream, offer one clean second go","As long as it takes, because you cannot let a crowd watch you lose one","None at all. Say nothing, put the mirror away and start tidying the table","Three or four more goes, until something on that face finally moves"],optionsEs:["Una frase. Le das la razón, preguntas por la crema y un segundo intento","El tiempo que haga falta, no puedes dejar que un corrillo te vea perder","Ninguna. No dices nada, guardas el espejo y te pones a recoger la mesa","Tres o cuatro intentos más, hasta que algo se mueva en esa cara"],correctIndex:0,explanation:"Two seconds, not two minutes. One line buys you a clean face and a second go — and if she will not take it, there is nothing else to buy.",explanationEs:"Dos segundos, no dos minutos. Una frase te compra la cara limpia y un segundo intento — y si no te la coge, ya no hay nada más que comprar."},{question:"Second go on clean skin, and the line still has not moved. What now?",questionEs:"Segundo intento con la piel limpia, y la línea sigue sin moverse. ¿Y ahora?",options:["Get the scrub into her hand — it is the one nobody argues with","Take a rung off the price so she has a reason to stay in the chair","She is a dead body. Thank her, walk her out, go to the next one","Keep working the same line until you get something out of it"],optionsEs:["Ponerle el exfoliante en la mano — ese no lo discute nadie","Bajar un escalón el precio para que se quede en la silla","Es un cuerpo muerto. Le das las gracias, la sacas y vas a por el siguiente","Seguir con la misma línea hasta sacarle algo"],correctIndex:2,explanation:"There is no point trying to sell to a dead body, and in front of a crowd you never pivot to another product. Get them out and go and get the next one.",explanationEs:"No tiene sentido intentar venderle a un cuerpo muerto, y delante de público nunca te cambias a otro producto. Los sacas y vas a por el siguiente."},{question:"Four strangers just watched a demo die. What are they actually judging?",questionEs:"Cuatro desconocidos acaban de ver morirse una demo. ¿Qué están juzgando en realidad?",options:["Whether the product does what you stood there and said it would do","How you handle it when it goes wrong right in front of them","Whether the woman was being fair to you about the whole thing","Whether the price you quoted at the start was an honest one"],optionsEs:["Si el producto hace lo que has dicho ahí de pie que hacía","Cómo lo gestionas cuando sale mal delante de ellos","Si la señora estaba siendo justa contigo con todo esto","Si el precio que has dicho al principio era honesto"],correctIndex:1,explanation:"They already assume the good demos are rigged. What nobody can fake is watching somebody leave a dead one without falling apart.",explanationEs:"Ya dan por hecho que las demos buenas están amañadas. Lo que no se puede fingir es ver a alguien dejar una demo muerta sin desmoronarse."}]},S3:{id:"S3",categoryId:"scenarios",title:"Hen Party / Group of Friends",titleEs:"Despedida de Soltera / Grupo de Amigas",subtitle:"Six of them, one of you, and an hour of pure noise",subtitleEs:"Seis de ellas, tú solo, y una hora de ruido puro",duration:"5 min",icon:"PartyPopper",order:7,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:`Six women in matching BRIDE SQUAD t-shirts land on your spot. Loud, delighted, half of them three drinks in already. The bride is the quiet one at the back. The loud one in the glasses appoints herself in charge and shouts "DO ALL OF US!" They all want doing at once, they're taking selfies, nobody is listening to anybody. This is either the biggest hour of your week or forty minutes of nothing.`,textEs:'Seis mujeres con camisetas iguales de BRIDE SQUAD caen sobre tu puesto. A gritos, encantadas de la vida, la mitad ya con tres copas. La novia es la callada del fondo. La escandalosa de las gafas se nombra jefa y grita "¡HÁZNOSLO A TODAS!" Quieren todas a la vez, se están haciendo fotos, no se escucha nadie. Esto es o la mejor hora de tu semana o cuarenta minutos tirados a la basura.'},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["COUNT THEM BEFORE YOU DO ANYTHING. Three or fewer, you do all of them — it's quick and they watch each other. Four or more, and this is six, you take ONE. Doing everybody and selling nothing is the worst feeling in this job, and it costs you the whole hour on top.","TAKE THE ONE THEY ALL LOOK AT. Every group has one. Usually the loud one, sometimes the bride. Watch where the eyes go after somebody speaks. Win her and the rest come with her. Leave her out and she'll kill it for fun.",`BE LOUDER THAN THEM, ONCE. Not angry — bigger. "RIGHT, LADIES! I'm doing ONE of you, properly, and the rest of you get to watch and shout." A group follows whoever takes the wheel in the first ten seconds.`,"MAKE THAT ONE DEMO ENORMOUS. You only get one, so give it everything — narrate the lot, get all six counting the sixty seconds out loud, and let them film each other's faces when the mirror comes out. Six women screaming in the street pulls in strangers you never even stopped.","PRICE THEM AS ONE GROUP, NOT AS SIX PEOPLE. When the money comes up, and it will come up loudly, give them a single number to split between them and one gift with the bride's name on it. Six separate conversations about money become one decision they all cheer for.",`ONLY OPEN IT UP IF THEY'RE GENUINELY GOING. Phones out, hands up, three of them shouting "me next" — that's real, take another one. Polite nodding is not, and neither is one of them being nice to you. If it goes flat after the first mirror, close the one in the chair and keep the rest of your hour.`],itemsEs:["CUÉNTALAS ANTES DE HACER NADA. Tres o menos, se las haces a todas — es rápido y se miran entre ellas. Cuatro o más, y esto son seis, coges a UNA. Hacérselo a todas y no vender nada es la peor sensación de este trabajo, y encima te cuesta la hora entera.","COGE A LA QUE MIRAN TODAS. En todo grupo hay una. Normalmente la escandalosa, a veces la novia. Fíjate adónde van los ojos cuando alguien dice algo. Gánatela y las demás vienen detrás. Déjala fuera y te lo revienta por diversión.",'SUBE LA VOZ MÁS QUE ELLAS, UNA VEZ. No enfadado — más grande. "¡VENGA, CHICAS! Se lo hago a UNA, pero bien, y las demás miráis y animáis." Un grupo se va detrás de quien coge el volante en los diez primeros segundos.',"QUE ESA DEMO SEA ENORME. Solo tienes una, así que dalo todo — cuéntalo todo, que las seis cuenten los sesenta segundos en voz alta y que se graben la cara unas a otras cuando sale el espejo. Seis mujeres chillando en plena calle te traen a desconocidos que ni has parado.","PONLES UN PRECIO DE GRUPO, NO SEIS PRECIOS. Cuando salga el dinero, y va a salir a gritos, dales un número que puedan repartirse entre ellas y un regalo con el nombre de la novia encima. Seis conversaciones sobre dinero se convierten en una sola decisión que aplauden todas.",'SOLO LO ABRES A LAS DEMÁS SI SE ESTÁN VOLVIENDO LOCAS DE VERDAD. Móviles fuera, manos arriba, tres gritando "ahora yo" — eso es real, coge a otra. Que asientan por educación no lo es, ni que una sea maja contigo. Si después del primer espejo se queda plano, cierras a la que tienes en la silla y te guardas el resto de la hora.']},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Do all six. At once, one after another, it makes no difference — six demos, six mirrors, an hour gone and nobody has paid you. That is the worst feeling in this job. One brilliant demo sells the group; six average ones sell nothing at all.","Skip the quiet one when you're choosing. The one who hasn't said a word is very often the one with the money and the least interest in arguing about it.","Go serious on them. Treat a hen do like a consultation and they're gone in thirty seconds. Match the noise.",`Argue with the one who's against it. Let her off instead — "you don't have to, just let me have your friends" — and she stops working against you.`],itemsEs:["Hacérselo a las seis. A la vez o una detrás de otra, da igual — seis demos, seis espejos, una hora fuera y nadie te ha pagado. Esa es la peor sensación de este trabajo. Una demo buenísima te vende al grupo; seis regulares no venden nada.","Pasar de la callada al elegir. La que no ha abierto la boca es muchas veces la que tiene el dinero y las menos ganas de discutirlo.","Ponerte serio con ellas. Trata una despedida de soltera como una consulta y las pierdes en treinta segundos. Ponte a su nivel de ruido.",'Discutir con la que va en contra. Suéltala: "tú no tienes que hacer nada, déjame solo a tus amigas" — y deja de trabajar en tu contra.']},{type:"subheader",text:"Script — Taking The Wheel",textEs:"Guion — Coger el Volante"},{type:"script",text:`YOU: "RIGHT — BRIDE SQUAD! Listen to me!" [Big, loud, arms out] "I'm doing ONE of you. One. Properly. And the rest of you are going to stand right here and watch what happens to her face." [Beat, then straight at the bride] "Who is it? The bride? OBVIOUSLY the bride. Everybody in close."`,textEs:'TÚ: "¡VENGA — BRIDE SQUAD! ¡Escuchadme!" [Grande, alto, los brazos abiertos] "Se lo hago a UNA. A una. Bien hecho. Y las demás os quedáis aquí mismo a ver lo que le pasa a esa cara." [Pausa, y directo a la novia] "¿Quién es? ¿La novia? PUES CLARO que la novia. Acercaos todas."'},{type:"subheader",text:"Script — The Countdown",textEs:"Guion — La Cuenta Atrás"},{type:"script",text:`YOU: "Everybody counts with me. Sixty seconds. Ready? THREE, TWO, ONE — GO!" [They count. You keep it moving] "FIFTY! FORTY-FIVE!" [When it lands] "STOP! Give her the mirror!" [They scream] "THAT'S what we do here." [Now read them. Screaming, shoving each other forward, phones out — take one more. Polite smiles and a nod — you've got your customer. Go and close her.]`,textEs:'TÚ: "Contáis todas conmigo. Sesenta segundos. ¿Listas? ¡TRES, DOS, UNO — YA!" [Cuentan. Tú las mantienes] "¡CINCUENTA! ¡CUARENTA Y CINCO!" [Cuando llega] "¡ALTO! ¡Dadle el espejo!" [Chillan] "ESO es lo que hacemos aquí." [Ahora léelas. Si chillan, se empujan para ponerse delante y sacan los móviles, coge a otra. Si sonríen por educación y asienten, ya tienes a tu clienta. Ve a cerrarla.]'},{type:"subheader",text:"Script — The Group Number",textEs:"Guion — El Número de Grupo"},{type:"script",text:`YOU: "Right. You lot are the best thing that's happened to me all week, so listen." [Voice down a bit, like it's a secret] "One syringe is {currency}300. For you: take two, pay {currency}300, and sort out between yourselves who's putting in what. And the bride doesn't pay for a scrub — that one's from me, wedding present. Who's in?" [Hands go up] "Beautiful. Card or cash, and whoever's short pays her mate back on the bus."`,textEs:'TÚ: "Venga. Sois lo mejor que me ha pasado en toda la semana, así que escuchad." [Baja un poco la voz, como si fuera un secreto] "Una jeringa son {currency}300. Para vosotras: os lleváis dos y pagáis {currency}300, y ya os apañáis entre vosotras quién pone qué. Y la novia no paga el scrub — ese va de mi parte, regalo de boda. ¿Quién se apunta?" [Se levantan manos] "Preciosas. Tarjeta o efectivo, y a la que le falte ya se lo devuelve a su amiga en el bus."'},{type:"subheader",text:"Script — The One Who Isn't Having It",textEs:"Guion — La Que No Está Por La Labor"},{type:"script",text:`YOU: "Totally fine, you don't have to do anything." [Warm, not a scrap of pressure, then straight back to the group] "Just let me have your friends for five minutes — look at the bride's face, she's glowing. Here, hold this for me while I finish her." [Give her something to hold. Nobody holding something walks off.]`,textEs:'TÚ: "Qué va, tranquila, tú no tienes que hacer nada." [Con cariño, sin una pizca de presión, y vuelves directo al grupo] "Déjame solo a tus amigas cinco minutos — mírale la cara a la novia, está radiante. Toma, sujétame esto mientras la termino." [Dale algo que sujetar. Nadie que esté sujetando algo se va.]'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:`A hen do is the best hour you'll get all week, and the fastest way to waste it is trying to do all of them. Three or fewer, do the lot. Four or more, you take one, you make that one enormous, and you only reach for a second if they are genuinely losing their minds. Doing everybody and selling nothing is the worst feeling in this job. Don't turn any of it into promises either — no "send me a friend and I'll sort you out next time", no discount owed to anybody after they leave, because you won't be here and a colleague has to have that argument at the counter. Do the lot today: the group number, the gift with the bride's name on it, the countdown, the photos. Then send them off loud and happy, because a group that leaves screaming is an advert walking down the middle of the street in matching t-shirts.`,textEs:'Una despedida de soltera es la mejor hora de tu semana, y la forma más rápida de tirarla es intentar hacérselo a todas. Tres o menos, se las haces a todas. Cuatro o más, coges a una, esa la haces enorme, y solo vas a por una segunda si se están volviendo locas de verdad. Hacérselo a todas y no vender nada es la peor sensación de este trabajo. Y no conviertas nada de esto en promesas: nada de "mándame a una amiga y la próxima te lo compenso", nada de descuentos que se le deban a alguien cuando ya se ha ido, porque tú no vas a estar y la discusión en el mostrador le toca a un compañero. Hazlo todo hoy: el precio de grupo, el regalo con el nombre de la novia, la cuenta atrás, las fotos. Y luego que se vayan a gritos y encantadas, porque un grupo que se va chillando es un anuncio andando por mitad de la calle con camisetas iguales.'}],quiz:[{question:'Six of them, all shouting "do me next". How do you run it?',questionEs:'Seis, y todas gritando "ahora yo". ¿Cómo lo montas?',options:["Six quick demos at once, so that nobody is left standing about waiting","One at a time, all six of them, so every single one of them gets her turn","One of them, huge, with the other five stood round watching and counting","Split them with a colleague so the six of you get through it faster"],optionsEs:["Seis demos rápidas a la vez, para que ninguna se quede esperando","De una en una, las seis, para que a todas les toque su turno","A una, enorme, con las otras cinco alrededor mirando y contando","Repartirlas con un compañero para acabar antes con las seis"],correctIndex:2,explanation:"Four or more and you take one. Six demos and nobody buys is the worst feeling in this job, and it costs you the whole hour as well.",explanationEs:"Cuatro o más y coges a una. Seis demos y que no compre nadie es la peor sensación de este trabajo, y encima te cuesta la hora entera."},{question:"Three friends stop instead of six. Does anything change?",questionEs:"Se paran tres amigas en vez de seis. ¿Cambia algo?",options:["No — one volunteer whatever the size of the group, every single time","Yes — with three you do two of them and leave the third one wanting it","No, but you halve each demo so all three of them fit into the same hour","Yes. Three or fewer and you do all of them"],optionsEs:["No — una voluntaria sea cual sea el grupo, siempre igual","Sí — con tres le haces a dos y dejas a la tercera con ganas","No, pero partes cada demo por la mitad para que quepan las tres","Sí. Tres o menos y se las haces a todas"],correctIndex:3,explanation:"Three or fewer, do all of them. The one-volunteer rule starts at four, and it starts there because six demos and no sale is an hour of your life gone.",explanationEs:"Tres o menos, se las haces a todas. Lo de una sola empieza en cuatro, y empieza ahí porque seis demos sin venta es una hora de tu vida tirada."},{question:"Your one demo lands, and the group goes polite and quiet. What now?",questionEs:"Tu única demo sale bien y el grupo se queda callado y educado. ¿Y ahora?",options:["Do the next one anyway — they are all stood there waiting for a turn","Close the one in the chair and keep the rest of your hour","Drop the price for the group to get the noise back up again","Start again on somebody else and put more energy into that one"],optionsEs:["Hacerle la demo a la siguiente igual — están ahí esperando turno","Cerrar a la que tienes en la silla y guardarte el resto de la hora","Bajar el precio al grupo para que vuelva a subir el ruido","Empezar otra vez con otra y meterle más energía a esa"],correctIndex:1,explanation:'You only open it up on real excitement — screaming, phones out, three of them shouting "me next". Polite nodding is not that, and it never turns into it.',explanationEs:'Solo lo abres a las demás si hay entusiasmo de verdad: chillidos, móviles fuera, tres gritando "ahora yo". Que asientan por educación no lo es, y no se convierte en eso.'}]},S5:{id:"S5",categoryId:"scenarios",title:"The Silent Close",titleEs:"El Cierre Silencioso",subtitle:"She hasn't said a word, and she's already bought it",subtitleEs:"No ha dicho ni una palabra, y ya se lo ha comprado",duration:"4 min",icon:"Eye",order:5,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:"A woman sits through your entire demo without making a sound. She watches you apply it. She sits out the sixty seconds. She takes the mirror, looks at her face for a long time, and says nothing. No wow, no lovely, no reaction at all. She hands the mirror back, touches the spot where you worked, and looks at the box on the table. Then at you. Still not a word. This is where most sellers panic and talk the sale to death.",textEs:'Una mujer se traga toda tu demo sin hacer un ruido. Te ve aplicarlo. Se aguanta los sesenta segundos. Coge el espejo, se mira la cara un buen rato y no dice nada. Ni un "anda", ni un "qué bien", nada. Te devuelve el espejo, se toca el sitio donde has trabajado y mira la caja que hay en la mesa. Luego te mira a ti. Sigue sin decir ni una palabra. Aquí es donde la mayoría se pone nerviosa y mata la venta a base de hablar.'},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["WATCH HER HANDS, NOT HER MOUTH. Still touching the spot. Still holding the mirror. Picking the box up. Those hands are talking to you, and they're saying yes.","COME DOWN TO HER LEVEL. If she's quiet, go quiet. Drop your voice, slow right down. Loud on top of quiet feels like a shove, and being shoved is the one thing that will get her out of that chair.","PUT THE BOX IN HER HANDS AND SAY NOTHING. No pitch, no price, no closing line. Hold it out, smile, wait. Something in her hands is much harder to give back than something on a table.",`IF YOU HAVE TO SPEAK, ASK SOMETHING SHE CAN NOD TO. "Shall I wrap one for you?" — not "so what do you think?". One takes a nod. The other takes a speech in front of a stranger, and she isn't going to make one.`,"LET THE SILENCE SIT. Nervous talking is the only thing that can lose this. She isn't ignoring you, she's deciding. Stand there, look pleased with yourself, and let her finish."],itemsEs:["MÍRALE LAS MANOS, NO LA BOCA. Que sigue tocándose la zona. Que sigue con el espejo. Que coge la caja. Esas manos te están hablando, y te están diciendo que sí.","BAJA TÚ A SU NIVEL. Si ella va callada, cállate tú. Baja la voz, ve mucho más despacio. Ruido encima de silencio parece un empujón, y que la empujen es lo único que la va a levantar de esa silla.","PONLE LA CAJA EN LAS MANOS Y NO DIGAS NADA. Sin discurso, sin precio, sin frase de cierre. Se la tiendes, sonríes y esperas. Lo que tiene en las manos cuesta mucho más devolverlo que lo que está en la mesa.",'SI TIENES QUE HABLAR, PREGÚNTALE ALGO QUE SE CONTESTE CON LA CABEZA. "¿Te envuelvo uno?", no "¿y qué te parece?". Lo primero se contesta asintiendo. Lo segundo pide un discurso delante de un desconocido, y no lo va a hacer.',"DEJA QUE EL SILENCIO SE QUEDE. Lo único que puede perder esto es que te pongas a hablar de los nervios. No te está ignorando, está decidiendo. Quédate ahí, con cara de contento, y déjala terminar."]},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Fill the gap with chatter. Every extra sentence gives her something new to think about, and none of it is the mirror.",`Ask "so what do you think?". You've just asked a quiet person to perform in public. She'll say "I'll think about it" to get out of it.`,"Get louder to bring her round. Every notch you go up, she goes one back. Now she's being sold at instead of looked after.","Decide she isn't interested. Quiet, plus touching the spot, plus looking at the box, is not a no. It's a yes she hasn't announced."],itemsEs:["Rellenar el hueco hablando. Cada frase de más le da algo nuevo en lo que pensar, y nada de eso es el espejo.",'Preguntar "¿y qué te parece?". Acabas de pedirle a una persona callada que actúe en público. Te va a decir "me lo pienso" solo para escaparse.',"Subir el tono para animarla. Cada punto que subes tú, ella retrocede otro. Ahora ya no la estás cuidando, se la estás colocando.","Dar por hecho que no le interesa. Callada, tocándose la zona y mirando la caja no es un no. Es un sí que todavía no ha anunciado."]},{type:"subheader",text:"Script — The Silent Hand-Off",textEs:"Guion — La Entrega Silenciosa"},{type:"script",text:"YOU: [Not a word. Put the box gently into her hands. Soft eye contact. Smile. Wait.] [If she's still holding it after three seconds, she's bought it — get the bag out and start wrapping.]",textEs:"TÚ: [Ni una palabra. Ponle la caja en las manos con suavidad. Contacto visual suave. Sonríe. Espera.] [Si a los tres segundos la sigue sujetando, se la ha comprado — saca la bolsa y empieza a envolver.]"},{type:"subheader",text:"Script — The Gentle Question",textEs:"Guion — La Pregunta Suave"},{type:"script",text:'YOU: [Voice right down, almost a whisper] "Shall I do you one?" [Then nod slowly, once, while you look at her. Say nothing else at all. The nod does the work.]',textEs:'TÚ: [La voz muy baja, casi un susurro] "¿Te preparo uno?" [Y asiente despacio, una vez, mirándola. No digas absolutamente nada más. El gesto hace el trabajo.]'},{type:"subheader",text:"Script — Give Her The Room",textEs:"Guion — Dale Aire"},{type:"script",text:`YOU: "I'm not going anywhere." [Half a step back. Busy yourself with something on the table for ten seconds — tidy the samples, wipe the mirror] [Then look up, warm] "Go on then. Which one?"`,textEs:'TÚ: "Yo no me muevo de aquí." [Medio paso atrás. Entretente diez segundos con algo de la mesa — coloca las muestras, limpia el espejo] [Y luego levanta la vista, con cariño] "Venga. ¿Cuál te llevas?"'},{type:"subheader",text:"Script — Two Boxes On The Table",textEs:"Guion — Dos Cajas en la Mesa"},{type:"script",text:`YOU: "One is {currency}300." [Pause. Let it sit there] "Two — one for you, one for whoever you're thinking about right now — is also {currency}300, because I put the second one in myself." [Set both boxes down in front of her. Don't touch them again. Don't say another word.]`,textEs:'TÚ: "Uno son {currency}300." [Pausa. Deja que se quede ahí] "Dos — uno para ti y otro para esa persona en la que estás pensando ahora mismo — también son {currency}300, porque el segundo lo pongo yo." [Deja las dos cajas delante de ella. No las vuelvas a tocar. No digas ni una palabra más.]'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:"Quiet is not no. Watch her hands, not her mouth. Still touching the spot? Still hanging on to the mirror? She's already bought it, she just hasn't told you. Put the box in her hands, smile, and say nothing at all. And keep the three-second hold in your head: if she holds it for three seconds without handing it back, stop talking and start bagging.",textEs:"El silencio no es un no. Mírale las manos, no la boca. ¿Sigue tocándose la zona? ¿Sigue aferrada al espejo? Ya se lo ha comprado, lo que pasa es que no te lo ha dicho. Ponle la caja en las manos, sonríe y no digas absolutamente nada. Y quédate con la regla de los tres segundos en la mano: si la sujeta tres segundos sin devolvértela, deja de hablar y empieza a envolver."}],quiz:[{question:"Two minutes of silence, but she is still touching the spot you worked on. What is that?",questionEs:"Dos minutos callada, pero sigue tocándose la zona que le has trabajado. ¿Qué es eso?",options:["A polite no she has not worked out how to say","Boredom — she is waiting for a gap to walk off in","Confusion — she needs the whole thing explaining to her again slowly","A yes she has not announced. Get the box into her hands"],optionsEs:["Un no educado que todavía no sabe cómo decirte","Aburrimiento — está esperando un hueco para irse","Confusión — necesita que se lo expliques todo otra vez y despacio","Un sí que no ha anunciado. Ponle la caja en las manos"],correctIndex:3,explanation:"Watch her hands, not her mouth. Still touching, still holding the mirror, still looking at the box — those hands are saying yes.",explanationEs:"Mírale las manos, no la boca. Que sigue tocándose, que sigue con el espejo, que mira la caja — esas manos dicen que sí."},{question:"You have to say something. Which question?",questionEs:"Tienes que decir algo. ¿Qué pregunta?",options:['"So, what do you think of it then?"','"Any questions before you decide?"','"Shall I wrap one for you?"','"Do you want a think and see how you feel?"'],optionsEs:['"¿Y qué te parece entonces?"','"¿Alguna duda antes de decidir?"','"¿Te envuelvo uno?"','"¿Quieres pensártelo y ver cómo lo ves?"'],correctIndex:2,explanation:"One of these takes a nod. The others ask a quiet person to make a speech in front of a stranger, and she will not.",explanationEs:"Una de estas se contesta asintiendo. Las otras le piden a una persona callada un discurso delante de un desconocido, y no lo va a hacer."},{question:"She goes quiet, you get nervous. What is the one thing that loses this sale?",questionEs:"Ella se calla y tú te pones nervioso. ¿Qué es lo único que puede perder esta venta?",options:["Standing there saying nothing while she decides","Filling the silence with another sentence, then another","Putting the box into her hands without a word said","Stepping back half a pace and tidying the table a moment"],optionsEs:["Quedarte ahí sin decir nada mientras ella decide","Rellenar el silencio con otra frase, y luego otra","Ponerle la caja en las manos sin decir nada","Dar medio paso atrás y ordenar la mesa un momento"],correctIndex:1,explanation:"Every extra sentence gives her something new to think about, and none of it is the mirror. Silence is not your enemy here.",explanationEs:"Cada frase de más le da algo nuevo en lo que pensar, y nada de eso es el espejo. Aquí el silencio no es tu enemigo."}]},S6:{id:"S6",categoryId:"scenarios",title:"The Tour Group on the Clock",titleEs:"El Grupo con el Tiempo Contado",subtitle:"Three and a half hours, four languages, one chair",subtitleEs:"Tres horas y media, cuatro idiomas, una silla",duration:"4 min",icon:"Timer",order:4,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:"A day-trip crowd spills into the main street in {locationName} — cruise passengers, coach parties, lanyards round every neck. They've got three and a half hours and then they're gone. One couple has barely any English, another pair are arguing about the way back to the port, somebody is photographing a bin. You step in front of one woman and she comes in — with three of her group trailing after her, all of them checking the time. Money and a clock, and four faces looking at you. You are not doing four demos in three minutes. You are doing ONE, and you are doing it in front of the other three.",textEs:"Cae un grupo de excursión en la calle principal de {locationName} — pasajeros de crucero, gente de autocar, acreditaciones colgadas de todos los cuellos. Tienen tres horas y media y se van. Una pareja casi no habla inglés, otra está discutiendo por dónde se vuelve al puerto y alguien está fotografiando una papelera. Te pones delante de una mujer y entra — con tres de su grupo detrás, todas mirando la hora. Dinero y un reloj, y cuatro caras mirándote. No vas a hacer cuatro demos en tres minutos. Vas a hacer UNA, y la vas a hacer delante de las otras tres."},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["ONE OUT OF THE CROWD. Three or fewer at your table, do all of them — it's quick. Four or more, and a coach party is always four or more, you take ONE and do her properly with the rest stood round watching. Do everybody and sell nothing and there goes your three and a half hours.",`HOOK HER IN FIVE SECONDS, NOT FIFTEEN. She's drowning in signs and noise. Hold the syringe up where she can see it and give her one sentence: "Sixty seconds, one wrinkle, gone — want to see?" Movement plus a question stops feet.`,`GIVE HER BOTH NUMBERS EARLY. Day-trippers have spent all morning comparing prices in three countries. "Back in Europe this is {currency}500. Here it's {currency}300." Now she's got somewhere to put your price.`,`CUT THE DEMO IN HALF. Three minutes becomes ninety seconds. Apply, count out loud, mirror, price, close. No routine talk, no ingredient talk. "{currency}300, every card there is, and you're out of here in two minutes."`,`MAKE THE CLOCK A REASON, NOT A THREAT. "You've got two hours left — do you want to spend them walking round looking like this, or like this?" Time is on your side as long as it stays a joke.`,"GET IT DONE TODAY. She's on a boat tonight and she isn't back on Thursday. Nothing gets held, nothing gets promised for later, nothing waits. It happens in the chair or it doesn't happen."],itemsEs:["UNA DE TODO EL GRUPO. Tres o menos en tu mesa, se las haces a todas — es rápido. Cuatro o más, y un grupo de autocar siempre son cuatro o más, coges a UNA y se la haces bien con las demás alrededor mirando. Hazlo con todas sin vender nada y ahí se te han ido las tres horas y media.",'ENGÁNCHALA EN CINCO SEGUNDOS, NO EN QUINCE. Está ahogada en carteles y ruido. Levanta la jeringa donde la vea y suéltale una sola frase: "Sesenta segundos, una arruga, fuera — ¿quieres verlo?" Movimiento más pregunta para los pies.','DALE LOS DOS NÚMEROS PRONTO. Los de excursión llevan toda la mañana comparando precios en tres países. "En Europa esto son {currency}500. Aquí son {currency}300." Ya tiene dónde colocar tu precio.','PARTE LA DEMO POR LA MITAD. Los tres minutos se quedan en noventa segundos. Aplica, cuenta en voz alta, espejo, precio, cierre. Nada de rutinas ni de ingredientes. "{currency}300, todas las tarjetas que existen, y te vas de aquí en dos minutos."','QUE EL RELOJ SEA UN MOTIVO, NO UNA AMENAZA. "Te quedan dos horas — ¿las quieres pasar dando vueltas con esta cara, o con esta otra?" El tiempo juega a tu favor mientras siga siendo una broma.',"QUE SE HAGA HOY. Esta noche está en un barco y el jueves no vuelve. Aquí no se guarda nada, no se promete nada para luego, no espera nada. O pasa en la silla o no pasa."]},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Open with a story. They haven't got time for your life. Hook, demo, price, done.",`Ask big questions. "What's your skincare routine?" is a two-minute answer you don't need. Assume she's interested and move.`,'Panic her about the time. "Hurry up, your coach!" makes her leave. The clock is a joke you share, not a stick you hit her with.',"Write her off as a looker. She's on holiday, she's got money on her, and she decided this morning that today is a spending day. Ask for the sale every time.","Make a drama of the language. Get the translator out, show her the product page in her own language, point at the mirror. It happens all day on this street and it has never once been the reason a sale did not happen."],itemsEs:["Empezar con una historia. No tienen tiempo para tu vida. Gancho, demo, precio, listo.",'Hacer preguntas grandes. "¿Cuál es tu rutina de piel?" es una respuesta de dos minutos que no te hace falta. Da por hecho que le interesa y tira.','Meterle prisa con el tiempo. "¡Corre, que se te va el autocar!" hace que se vaya. El reloj es una broma compartida, no un palo.','Descartarla porque "solo mira". Está de vacaciones, lleva dinero encima y esta mañana ya ha decidido que hoy se gasta. Pide la venta siempre.',"Montar un drama con el idioma. Saca el traductor, enséñale la ficha del producto en su idioma, señala el espejo. Pasa todos los días en esta calle y no ha sido nunca el motivo de que una venta no salga."]},{type:"subheader",text:"Script — The Ten-Second Hook",textEs:"Guion — El Gancho de Diez Segundos"},{type:"script",text:`YOU: "Excuse me — sixty seconds, one line, completely gone. Want to see it?" [Syringe up, eye contact, big smile] "Two minutes of your time, and I'm right here."`,textEs:'TÚ: "¡Perdona! Sesenta segundos, una línea, fuera del todo. ¿Quieres verlo?" [Jeringa en alto, contacto visual, sonrisa grande] "Dos minutos de tu tiempo, y estoy aquí mismo."'},{type:"subheader",text:"Script — The Speed Demo + Close",textEs:"Guion — La Demo Rápida + Cierre"},{type:"script",text:'YOU: "Right here, on this line. Now we count. Sixty, fifty-five, fifty…" [Keep the energy up, keep counting] "…ten, five, DONE. Look." [Mirror straight into her hand] "That was there a minute ago. {currency}300, I take every card there is. Shall I wrap one before your lot move off?"',textEs:'TÚ: "Aquí mismo, en esta línea. Ahora contamos. Sesenta, cincuenta y cinco, cincuenta..." [Mantén la energía, sigue contando] "...diez, cinco, ¡LISTO! Mira." [El espejo directo a su mano] "Eso estaba ahí hace un minuto. {currency}300, acepto todas las tarjetas que existen. ¿Te envuelvo uno antes de que se muevan los tuyos?"'},{type:"subheader",text:"Script — The Walk-Back Close",textEs:"Guion — El Cierre de Vuelta al Grupo"},{type:"script",text:`YOU: "Picture getting back on that coach and the woman next to you going 'what have you DONE?'" [Grin] "Everybody else is going home with a fridge magnet. {currency}300, all cards, thirty seconds and you're gone."`,textEs:`TÚ: "Imagínate volver al autocar y que la de al lado te diga '¿pero qué te has HECHO?'" [Sonríe] "Los demás se van a casa con un imán de nevera. {currency}300, todas las tarjetas, treinta segundos y te vas."`},{type:"subheader",text:"Script — When There's No Shared Language",textEs:"Guion — Cuando No Hay Idioma en Común"},{type:"script",text:`YOU: "No problem, no problem!" [Phone out, translator open, and keep smiling while you type — it takes ten seconds and it is not a drama] "Look. Sixty seconds. Line — gone." [Mirror. A mirror doesn't need translating.] "And here — the page, in your language." [Product page on the screen, phone into her hand] "{currency}300. Card? Cash? All good!" [Point at the terminal, big smile. Half this street sells in four languages a day.]`,textEs:'TÚ: "¡No pasa nada, no pasa nada!" [Saca el móvil, abre el traductor y sigue sonriendo mientras escribes — son diez segundos y no es ningún drama] "Mira. Sesenta segundos. La línea — fuera." [Espejo. Un espejo no necesita traducción.] "Y aquí — la página, en tu idioma." [La ficha del producto en la pantalla, el móvil a su mano] "{currency}300. ¿Tarjeta? ¿Efectivo? ¡Todo bien!" [Señala el datáfono, sonrisa grande. Media calle vende en cuatro idiomas al día.]'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:`Learn the arrivals. Know which mornings the big groups land and what time they have to be back on board, because "I've got to be at the port by four" tells you exactly how long you've got and how hard you can push. And use the souvenir line — these people are sick of buying tat they'll bin when they get home. A pot of something that lasts them months feels clever, and clever is exactly how she wants to feel handing over {currency}300 in a street she's never been in before.`,textEs:'Apréndete las llegadas. Sabe qué mañanas caen los grupos grandes y a qué hora tienen que estar de vuelta a bordo, porque "tengo que estar en el puerto a las cuatro" te dice exactamente cuánto tiempo tienes y cuánto puedes apretar. Y usa lo del souvenir — esta gente está harta de comprar cachivaches que acaban en un cajón. Un bote de algo que le dura meses le parece una compra lista, y lista es justo como quiere sentirse soltando {currency}300 en una calle en la que no ha estado nunca.'}],quiz:[{question:"Four of them come in together off the same coach. Who gets the demo?",questionEs:"Entran cuatro juntas del mismo autocar. ¿A quién le haces la demo?",options:["All four, but you halve each one so they still make the coach","Whoever asks loudest, and then the other three if there is time","One of them, done properly, with the other three stood watching","Nobody yet — get all four prices out first and see who bites"],optionsEs:["A las cuatro, pero partes cada demo para que lleguen al autocar","A la que más grite, y luego a las otras tres si te da tiempo","A una, bien hecha, con las otras tres alrededor mirando","A ninguna todavía — sueltas los cuatro precios y ves quién pica"],correctIndex:2,explanation:"Three or fewer, do all of them. Four or more, you take one — because doing everybody and selling nothing is how a whole afternoon disappears.",explanationEs:"Tres o menos, se las haces a todas. Cuatro o más, coges a una — porque hacérselo a todo el mundo y no vender nada es como se te va una tarde entera."},{question:"She has two hours before the coach goes. What does that clock do for you?",questionEs:"Le quedan dos horas para que salga el autocar. ¿Qué hace ese reloj por ti?",options:["It is a reason to do it now, said as a joke","It is a threat — remind her she will miss the coach","It is a problem — she has not got time for a demo","It is nothing to do with you, so never mention it at all"],optionsEs:["Es un motivo para hacerlo ya, dicho en broma","Es una amenaza — recuérdale que pierde el autocar","Es un problema — no tiene tiempo para una demo","No es asunto tuyo, así que ni lo menciones nunca"],correctIndex:0,explanation:'Time is on your side as long as it stays a joke you share. "Hurry up, your coach!" is a stick, and she leaves.',explanationEs:'El tiempo juega a tu favor mientras siga siendo una broma compartida. "¡Corre, que se te va el autocar!" es un palo, y se va.'},{question:"Cruise passenger, ninety seconds of attention. What do you cut?",questionEs:"Pasajera de crucero, noventa segundos de atención. ¿Qué recortas?",options:["The mirror — she has not got time to sit and look","The routine talk and the ingredients. Apply, count, mirror, price","The price — leave that until she has felt it properly","The demo itself — just tell her what it does and then take the money"],optionsEs:["El espejo — no tiene tiempo de sentarse a mirarse","La charla de rutinas y los ingredientes. Aplica, cuenta, espejo, precio","El precio — déjalo para cuando lo haya notado bien","La demo — le cuentas lo que hace y le cobras directamente"],correctIndex:1,explanation:"Three minutes becomes ninety seconds and the mirror never goes. What comes out is everything that was never selling anything.",explanationEs:"Los tres minutos se quedan en noventa segundos y el espejo no se quita nunca. Lo que sobra es todo lo que nunca vendió nada."},{question:"She loves it, then says she will pop back after lunch. What do you know?",questionEs:"Le encanta, y luego te dice que se pasa después de comer. ¿Qué sabes tú?",options:["She will, and she will bring somebody with her","She is being polite and does not want the thing","She means it, so make a note of what she wanted and who she was","She is on a boat tonight. It happens now or not at all"],optionsEs:["Que sí, y que se va a traer a alguien con ella","Que está siendo educada y no lo quiere","Que lo dice en serio, apunta qué quería y quién era","Que esta noche está en un barco. O pasa ahora o no pasa"],correctIndex:3,explanation:"She is not back on Thursday and she is not back after lunch. Nothing gets held and nothing waits — it goes in the bag in that chair.",explanationEs:"Ni vuelve el jueves ni vuelve después de comer. Aquí no se guarda nada y no espera nada — va a la bolsa en esa silla."}]},S7:{id:"S7",categoryId:"scenarios",title:"Children Interrupting",titleEs:"Niños Interrumpiendo",subtitle:"Two minutes of peace is the whole sale",subtitleEs:"Dos minutos de paz son toda la venta",duration:"4 min",icon:"Baby",order:3,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:"A mother stops with a four-year-old. She's interested — you can see it. But the kid is bored out of his mind. Two minutes in he's whining, hanging off her arm, and then he's on the floor going full tantrum. She's mortified, apologising to you, trying to calm him down and listen to you at the same time. She's already picking her bag up. And you haven't closed anything.",textEs:"Una madre se para con un niño de cuatro años. Está interesada — se le nota. Pero el crío se aburre como una ostra. A los dos minutos ya está lloriqueando, colgado del brazo de su madre, y luego se tira al suelo con una rabieta de las buenas. Ella está muerta de vergüenza, pidiéndote perdón, intentando calmarlo y escucharte a la vez. Ya está cogiendo el bolso. Y tú no has cerrado nada."},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["DEAL WITH THE CHILD FIRST. He is the one deciding whether this sale happens. Get down to his height, smile at him, put something in his hands. A busy kid is a calm mother.","HALVE YOUR PITCH. You've got half the normal time and half her attention. Get to the mirror. Everything else can go.",'GIVE HIM A JOB. "Can you count to sixty for me? Ready?" Kids will do almost anything for somebody who treats them like staff. A child counting is a child not screaming.',"KEEP SOMETHING IN THE DRAWER FOR THEM. Stickers, a little sample he can squash, a pen and a bit of paper. Five minutes of distraction is exactly as long as you need.","CLOSE IT WHILE YOU'VE GOT HER. Don't send her off to walk it round and think about it. She isn't coming back today — she's got a child and a timetable. It goes in the bag now, or you lose it now."],itemsEs:["OCÚPATE PRIMERO DEL NIÑO. Él es quien decide si esta venta pasa o no. Ponte a su altura, sonríele, ponle algo en las manos. Un crío entretenido es una madre tranquila.","PARTE TU DISCURSO POR LA MITAD. Tienes la mitad del tiempo normal y la mitad de su atención. Llega al espejo. Todo lo demás sobra.",'DALE UN TRABAJO. "¿Sabes contar hasta sesenta? ¿Preparado?" Los críos hacen casi cualquier cosa por alguien que los trata como personal. Un niño contando es un niño que no chilla.',"TEN ALGO EN EL CAJÓN PARA ELLOS. Pegatinas, una muestrita que pueda aplastar, un boli y un papel. Cinco minutos de distracción es exactamente lo que necesitas.","CIÉRRALO MIENTRAS LA TIENES. No la mandes a dar una vuelta a pensárselo. Hoy no vuelve — tiene un niño y unos horarios. O va a la bolsa ahora, o lo pierdes ahora."]},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Pretend the child isn't there. She feels judged and he gets louder, because louder is what works for him.","Comment on her parenting. Not even as a joke. That's a sale lost and a review earned.","Keep talking over the screaming. She can't hear you and she can't think. Stop, sort the kid out, then start again.",'Let her leave on a maybe. "Come back later" with a small child means never. Either it goes in the bag now or you wave her off and mean it.'],itemsEs:["Hacer como si el niño no estuviera. Ella se siente juzgada y él sube el volumen, porque subir el volumen es lo que a él le funciona.","Opinar sobre cómo educa a su hijo. Ni en broma. Eso es una venta perdida y una reseña ganada.","Seguir hablando por encima de los gritos. Ni te oye ni puede pensar. Para, arregla lo del niño, y empieza otra vez.",'Dejarla ir con un "ya veremos". "Vuelve luego" con un niño pequeño significa nunca. O va a la bolsa ahora, o te despides de ella de verdad.']},{type:"subheader",text:"Script — Give The Kid A Job",textEs:"Guion — Dale un Trabajo al Niño"},{type:"script",text:'YOU: "Hello! Do you want a job?" [Down on his level, straight to him, not to her] "Your job is to hold this —" [Give him the box] "— and when I say GO, you count with me. Can you get to sixty?" [He nods] "BRILLIANT. Ready? GO! Sixty, fifty-nine…" [Mum is now watching you instead of watching him, and she is extremely grateful]',textEs:'TÚ: "¡Hola! ¿Quieres un trabajo?" [A su altura, directo a él, no a ella] "Tu trabajo es sujetar esto —" [Dale la caja] "— y cuando yo diga YA, cuentas conmigo. ¿Llegas hasta sesenta?" [Dice que sí con la cabeza] "¡GENIAL! ¿Listo? ¡YA! Sesenta, cincuenta y nueve..." [Ahora la madre te mira a ti en vez de a él, y te lo está agradeciendo muchísimo]'},{type:"subheader",text:"Script — The Short Version",textEs:"Guion — La Versión Corta"},{type:"script",text:`YOU: "You've got your hands full, so I'm giving you the short version." [Fast demo, no talking round it] "There. {currency}300, lasts you months, two minutes a day. I'll put one in a bag while you get him off the floor — pay me and you're out of here before he starts again."`,textEs:'TÚ: "Vas hasta arriba, así que te doy la versión corta." [Demo rápida, sin rodeos] "Ya está. {currency}300, te dura meses, dos minutos al día. Te lo meto en la bolsa mientras lo levantas del suelo — me pagas y te vas de aquí antes de que empiece otra vez."'},{type:"subheader",text:"Script — Ask Her First",textEs:"Guion — Pregúntale a Ella Primero"},{type:"script",text:`YOU: [To her, quietly] "Can he have a sticker? Is that alright?" [She'll say yes, and she'll love you for asking] [To him, big] "Right! I've got the good ones. Which do you want — the dinosaur or the star?" [A choice, not a question he can say no to] [Back to her while he decides] "Okay. Sixty seconds. Watch this line here."`,textEs:'TÚ: [A ella, bajito] "¿Le puedo dar una pegatina? ¿Te parece bien?" [Va a decir que sí, y te va a adorar por preguntar] [A él, en grande] "¡Venga! Tengo de las buenas. ¿Cuál quieres, el dinosaurio o la estrella?" [Una elección, no una pregunta a la que pueda decir que no] [Otra vez a ella, mientras el crío decide] "Vale. Sesenta segundos. Mira esta línea de aquí."'},{type:"subheader",text:"Script — Hand Him To A Colleague",textEs:"Guion — Pásaselo a un Compañero"},{type:"script",text:`YOU: [To your colleague] "Marco! Have you still got the stickers?" [To the child] "Marco's got the special ones — go and see!" [To her, as he runs over and stays in sight] "Right. Two minutes of quiet. Let's not waste them. Give me your hand."`,textEs:'TÚ: [A tu compañero] "¡Marco! ¿Te quedan pegatinas?" [Al niño] "¡Marco tiene las especiales — ve a verlas!" [A ella, mientras el crío va corriendo y sigue a la vista] "Venga. Dos minutos de tranquilidad. No los desperdiciemos. Dame la mano."'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:"Keep a bag of kid stuff on the table — stickers, a mini colouring book, a sample sachet they can squash. It costs about {currency}5 and it buys you the only thing you actually need, which is her attention. And learn to read the mother before it goes wrong: the moment her eyes start flicking to him every few seconds, you've got about ninety seconds left. Go to the child then, not once he's on the floor. The good sellers on this street aren't just good at selling — they see what's about to happen and move first.",textEs:"Ten una bolsita de cosas de niños en la mesa — pegatinas, un mini cuaderno para colorear, una muestra que puedan aplastar. Te cuesta unos {currency}5 y te compra lo único que de verdad necesitas, que es la atención de ella. Y aprende a leer a la madre antes de que se tuerza: en cuanto los ojos se le empiezan a ir hacia el niño cada dos por tres, te quedan unos noventa segundos. Ve a por el crío en ese momento, no cuando ya está tirado en el suelo. Los buenos vendedores de esta calle no solo venden bien — ven lo que va a pasar y se mueven antes."}],quiz:[{question:"The four-year-old is winding up and mum is reaching for her bag. Who do you deal with first?",questionEs:"El niño de cuatro años se está calentando y la madre ya coge el bolso. ¿A quién atiendes primero?",options:["Mum — get to the mirror before the child kicks off","Neither — wait it out, they always calm down in the end","The child. A busy kid is a calm mother","Whoever is loudest, because that is what is stopping you"],optionsEs:["A la madre — llega al espejo antes de que estalle el crío","A ninguno — aguanta, al final siempre se calman","Al niño. Un crío entretenido es una madre tranquila","Al que grite más, que es lo que te está frenando"],correctIndex:2,explanation:"He is the one deciding whether this sale happens. Get down to his height and put something in his hands.",explanationEs:"Él es quien decide si esta venta pasa o no. Ponte a su altura y ponle algo en las manos."},{question:"What do you give the boy?",questionEs:"¿Qué le das al niño?",options:["A job — counting the sixty seconds out loud","A sweet, so he has something to get on with","A stern look, so mum knows you are on her side","The syringe to hold, because kids love shiny things"],optionsEs:["Un trabajo — contar los sesenta segundos en alto","Un caramelo, para que tenga algo que hacer","Una mirada seria, para que la madre vea que la apoyas","La jeringa para sujetarla, que a los críos les encanta"],correctIndex:0,explanation:"Kids will do almost anything for somebody who treats them like staff. A child counting is a child not screaming.",explanationEs:"Los críos hacen casi cualquier cosa por alguien que los trata como personal. Un niño contando es un niño que no chilla."},{question:"She likes it, but the child is on the floor screaming. What now?",questionEs:"A ella le gusta, pero el crío está en el suelo chillando. ¿Y ahora?",options:["Short version, price, bag — she pays and she is out",'"Have a walk round with him and pop back when he settles"','"Take my number and message me when you have decided"',"Wait quietly until she has him calm, then start the pitch again"],optionsEs:["Versión corta, precio, bolsa — paga y se va",'"Dad una vuelta y os pasáis cuando se calme"','"Apúntate mi número y me escribes cuando lo decidas"',"Esperar callado a que lo calme y empezar otra vez el discurso"],correctIndex:0,explanation:"She is not coming back today — she has a child and a timetable. It goes in the bag now, or you lose it now.",explanationEs:"Hoy no vuelve — tiene un niño y unos horarios. O va a la bolsa ahora, o lo pierdes ahora."}]},S9:{id:"S9",categoryId:"scenarios",title:"The Skeptical Man",titleEs:"El Hombre Escéptico",subtitle:"The one stood behind her with his arms crossed",subtitleEs:"El que está detrás de ella con los brazos cruzados",duration:"4 min",icon:"Frown",order:2,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:`A couple stops. She's interested — watching, asking what's in it, picking the boxes up. He's two steps back with his arms folded, looking at his phone, and every time she says something nice he says "it's a scam", "you don't need that", "come on, we're wasting time". She's going quiet because of him. But you can see she wants it. So what do you do with him?`,textEs:'Se para una pareja. Ella está interesada — mirando, preguntando qué lleva, cogiendo las cajas. Él está dos pasos atrás con los brazos cruzados, mirando el móvil, y cada vez que ella dice algo bueno él suelta "es un timo", "tú no necesitas eso", "venga, que estamos perdiendo el tiempo". Ella se está callando por él. Pero tú ves que lo quiere. ¿Qué haces con él?'},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:["DON'T ARGUE WITH HIM. The moment it's you against him, she has to pick, and she picks him. You are never winning that one and you don't need to.",`BRING HIM IN. THIS IS THE FIRST MOVE, NOT THE LAST ONE. He doesn't want a debate, he wants proof he can feel. "You look like a man who wants proof. Give me your hand." Nobody stays folded up with their arms crossed while somebody's working on their hand.`,'MAKE HIM THE EXPERT, NOT THE OBSTACLE. "You know her better than I do — does she look after her skin, or is this new?" Ask him something only he can answer and he stops being the bloke at the back.',`GIVE HIM A BET HE THINKS HE'S WINNING. "Sixty seconds. If she looks in that mirror and she isn't impressed, I'll tell her myself to walk away." He takes it because it sounds like a free win — and the second he takes it, he's in it with you.`,`ONLY IF HE IS PURE BAD ENERGY DO YOU GIVE HIM UP. Not bored, not quiet, not on his phone — those are the ones you bring in. Nasty, decided to have a bad afternoon, still swinging after you've tried all three: then "don't worry, it's ladies' business anyway", light and with a smile, and every scrap of you goes on her.`],itemsEs:["NO DISCUTAS CON ÉL. En cuanto esto es tú contra él, ella tiene que elegir, y lo elige a él. Esa no la ganas nunca, y tampoco te hace falta.",'MÉTELO DENTRO. ESTA ES LA PRIMERA JUGADA, NO LA ÚLTIMA. Él no quiere un debate, quiere una prueba que pueda notar. "Tienes pinta de ser de los que quieren pruebas. Dame la mano." Nadie sigue con los brazos cruzados mientras le están trabajando la mano.','HAZLO EL EXPERTO, NO EL OBSTÁCULO. "Tú la conoces mejor que yo — ¿ella se cuida la piel, o esto es nuevo?" Pregúntale algo que solo pueda contestar él y deja de ser el señor del fondo.','DALE UNA APUESTA QUE CREA QUE GANA. "Sesenta segundos. Si se mira en ese espejo y no le impresiona, le digo yo que se vaya." La acepta porque le suena a victoria gratis — y en cuanto la acepta, ya está dentro contigo.','SOLO SI VA CON MUY MALA LECHE LO SUELTAS. Aburrido no, callado no, con el móvil no — a esos los metes dentro. Borde de verdad, que ha decidido tener una mala tarde, y sigue dando guerra después de las tres jugadas: entonces "no te preocupes, que esto es cosa de chicas", ligero y con una sonrisa, y toda tu energía se va con ella.']},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Take him on. Winning the argument loses the sale. She isn't going to buy something her partner just got beaten over.","Write him off at the first shrug. A bloke on his phone with his arms crossed is bored, not hostile, and bored is the easiest thing on this street to fix. Put something in his hand before you decide he's a lost cause.",`Have a go at his manliness. "Real men look after their skin too." Now he's got something to defend and he'll defend it all afternoon.`,`Put them against each other. "Don't let him tell you what to buy" makes you the problem in their relationship, and they leave together.`,"Drop the price to shut him up. Now he knows being difficult moves your numbers, and he'll be difficult all the way down to the floor."],itemsEs:["Entrarle al trapo. Ganar la discusión te cuesta la venta. Ella no va a comprar algo por lo que le acabas de ganar a su pareja.","Descartarlo al primer gesto. Un tío con el móvil y los brazos cruzados está aburrido, no en tu contra, y el aburrimiento es lo más fácil de arreglar de esta calle. Ponle algo en la mano antes de darlo por perdido.",'Meterte con su hombría. "Los hombres de verdad también se cuidan la piel." Ahora tiene algo que defender, y lo va a defender toda la tarde.','Enfrentarlos. "No dejes que te diga lo que puedes comprar" te convierte a ti en el problema de esa pareja, y se van juntos.',"Bajar el precio para callarlo. Ahora ya sabe que ponerse borde te mueve los números, y se va a poner borde hasta el suelo."]},{type:"subheader",text:"Script — Give Me Your Hand",textEs:"Guion — Dame la Mano"},{type:"script",text:`YOU: "You look like a man who wants proof. Come here — give me your hand." [Don't ask twice. Hold your hand out and wait. Most of them give it to you] "Right. Feel that patch there? Now don't touch it for sixty seconds." [Work on it, chat to her while it sits] "Go on. Feel it now. That's the difference."`,textEs:'TÚ: "Tienes pinta de ser de los que quieren pruebas. Ven — dame la mano." [No lo pidas dos veces. Extiende la mano y espera. La mayoría te la da] "Vale. ¿Notas esa zona de ahí? Pues no te la toques durante sesenta segundos." [Trabájala, y mientras habla con ella] "Venga. Tócala ahora. Esa es la diferencia."'},{type:"subheader",text:"Script — Make Him The Advisor",textEs:"Guion — Conviértelo en el Asesor"},{type:"script",text:`YOU: [To him, as if she isn't there] "Help me out here — does she actually look after her skin, or is all this new to her?" [Whatever he says, agree with him] "See, that's what I thought. Then this is the easy one — she doesn't need six bottles." [To her] "He's right, you know." [He's now on your side of the table and he has no idea how he got there]`,textEs:'TÚ: [A él, como si ella no estuviera] "Échame un cable — ¿ella se cuida la piel de verdad, o esto es todo nuevo para ella?" [Diga lo que diga, dale la razón] "Ves, eso me parecía. Pues entonces este es el fácil — no necesita seis botes." [A ella] "Tiene razón, ¿eh?" [Ahora está de tu lado de la mesa y no tiene ni idea de cómo ha llegado ahí]'},{type:"subheader",text:"Script — Sixty Seconds, Then You Decide",textEs:"Guion — Sesenta Segundos y Decides Tú"},{type:"script",text:`YOU: "I can see you're looking after her. Fair enough." [To him, straight, no sarcasm] "Give me sixty seconds. If she looks in that mirror and she isn't impressed, I'll tell her myself to walk away and I'll hold the door for the pair of you." [He'll take that — it's a fair bet and he thinks he's winning it] "Right. Sixty seconds."`,textEs:'TÚ: "Ya veo que la cuidas. Y me parece bien." [A él, directo, sin ironía] "Dame sesenta segundos. Si se mira en ese espejo y no le impresiona, le digo yo que se vaya y os sujeto la puerta a los dos." [Va a aceptar — es una apuesta justa y cree que la gana] "Venga. Sesenta segundos."'},{type:"subheader",text:"Script — Last Resort, Letting Him Off",textEs:"Guion — Último Recurso, Soltarlo del Anzuelo"},{type:"script",text:`YOU: [Only once you've had his hand, asked his opinion and offered him the bet, and he is still swinging. Then, to him — light, with a smile, not a scrap of edge to it] "Don't worry, it's ladies' business anyway." [Straight back to her, warm, like he was never a problem] "Right, you. Sit down and give me two minutes." [He gets his phone back out and stops fighting you. Everything you have left now goes on her.]`,textEs:'TÚ: [Solo cuando ya le has cogido la mano, le has pedido su opinión y le has ofrecido la apuesta, y sigue dando guerra. Entonces sí, a él — ligero, con una sonrisa, sin una pizca de pica] "No te preocupes, que esto es cosa de chicas." [Y vuelves directo a ella, con cariño, como si él nunca hubiera sido un problema] "Venga, tú. Siéntate y dame dos minutos." [Él saca otra vez el móvil y deja de pelearse contigo. Todo lo que te queda se lo dedicas a ella.]'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:`Three moves before you give up on him, and every one of them puts him INSIDE it: his hand, his opinion, a bet he thinks he's winning. A bloke on his phone with his arms crossed is bored, and bored is the easiest thing on this street to fix — letting him off is what you do when nothing worked, not what you open with. Only when he's genuinely nasty, still swinging after all three, does he get "it's ladies' business anyway" and you put everything you've got on her. What you never do is win an argument in front of his partner. And when he does come round, don't gloat and don't make him say it out loud — let him be right about something on the way out, and he'll be the one carrying the bag.`,textEs:'Tres jugadas antes de darlo por perdido, y las tres lo meten DENTRO: su mano, su opinión, una apuesta que cree que gana. Un tío con el móvil y los brazos cruzados está aburrido, y el aburrimiento es lo más fácil de arreglar de esta calle — soltarlo es lo que haces cuando no ha funcionado nada, no por dónde empiezas. Solo cuando va con muy mala leche y sigue dando guerra después de las tres se lleva el "esto es cosa de chicas" y tú te vuelcas del todo con ella. Lo que no haces nunca es ganar una discusión delante de su pareja. Y cuando se venga abajo, no te regodees ni le hagas decirlo en voz alta — dale la razón en algo al salir, y será él quien lleve la bolsa.'}],quiz:[{question:"He is behind her, arms folded, muttering that it is a scam. What is your FIRST move?",questionEs:"Él está detrás con los brazos cruzados, murmurando que es un timo. ¿Cuál es tu PRIMERA jugada?",options:["Answer him properly — facts will settle him down","Talk over him and keep her eyes on the mirror",'"Give me your hand" — put something in it',"Tell her not to let him decide what she can spend"],optionsEs:["Contestarle en serio — los datos lo van a calmar","Hablar por encima de él y que ella mire el espejo",'"Dame la mano" — ponle algo en ella',"Decirle a ella que no deje que él decida su gasto"],correctIndex:2,explanation:"He does not want a debate, he wants proof he can feel. You bring him in first — nobody stays folded up while somebody is working on their hand.",explanationEs:"Él no quiere un debate, quiere una prueba que pueda notar. Primero lo metes dentro — nadie sigue con los brazos cruzados mientras le trabajan la mano."},{question:"He is on his phone and would clearly rather be anywhere else. Now what?",questionEs:"Está con el móvil y está claro que preferiría estar en otro sitio. ¿Y ahora?",options:["Bring him in — his hand, or an opinion only he can give you",`Let him off with "it is ladies' business anyway" and move on`,"Ignore him completely and speak only to her from here on","Ask him what he thinks it is worth and then price it there"],optionsEs:["Meterlo dentro — su mano, o una opinión que solo él te puede dar",'Soltarlo con "esto es cosa de chicas" y seguir a lo tuyo',"Ignorarlo del todo y hablar solo con ella a partir de ahora","Preguntarle cuánto cree que vale y ponerle ese precio"],correctIndex:0,explanation:"Bored is not hostile, and bored is the easiest thing on this street to fix. You only let him off when he is genuinely nasty and you have already tried everything else.",explanationEs:"Aburrido no es hostil, y el aburrimiento es lo más fácil de arreglar de esta calle. Solo lo sueltas si va con muy mala leche y ya lo has intentado todo."},{question:"He keeps needling, so you jump from {currency}300 to {currency}210 to shut him up. What have you taught him?",questionEs:"Sigue picando y saltas de {currency}300 a {currency}210 para callarlo. ¿Qué le acabas de enseñar?",options:["That you respect him and that you want him on your side","That the product was overpriced in the first place","That being difficult moves your numbers","That you would rather close today than hold your price"],optionsEs:["Que lo respetas y que lo quieres de tu lado","Que el producto estaba caro desde el principio","Que ponerse borde te mueve los números","Que prefieres cerrar hoy antes que aguantar el precio"],correctIndex:2,explanation:"Now he knows exactly which button moves the money, and he will press it all the way down to your floor.",explanationEs:"Ahora ya sabe qué botón mueve el dinero, y lo va a apretar hasta llegar a tu suelo."}]},S10:{id:"S10",categoryId:"scenarios",title:"The Returning Customer",titleEs:"La Clienta Que Vuelve",subtitle:"The easiest sale of your week walks back up on her own",subtitleEs:"La venta más fácil de la semana vuelve ella sola",duration:"5 min",icon:"RefreshCw",order:6,xpReward:100,sections:[{type:"header",text:"The Situation",textEs:"La Situación"},{type:"paragraph",text:`A woman you sold to three months ago walks straight back up to your table. She remembers your name. She gets her phone out and shows you a photo of her own face, and it does look good. "I finished the whole syringe," she says. "It worked. What else have you got?" This is the best thing that will happen to you today. She's already sold, she already trusts you, and she's holding her card. And here is the part that catches sellers out: this one is not yours to price.`,textEs:'Una mujer a la que vendiste hace tres meses se planta otra vez en tu mesa. Se acuerda de tu nombre. Saca el móvil y te enseña una foto de su propia cara, y la verdad es que está estupenda. "Me acabé la jeringa entera", te dice. "Funcionó. ¿Qué más tienes?" Es lo mejor que te va a pasar hoy. Ya está vendida, ya se fía de ti, y lleva la tarjeta en la mano. Y aquí está la parte que pilla a los vendedores: a esta no le pones tú el precio.'},{type:"subheader",text:"What To Do",textEs:"Qué Hacer"},{type:"numbered",items:['MAKE A PROPER NOISE ABOUT HER. "NO WAY, you came back! Let me look at you — I TOLD you!" Loud, delighted, in front of whoever else is in the shop. She came back for that feeling as much as for the product.',"DO THE DEMO ANYWAY, AND KEEP IT ON THE SYRINGE. She finished one, so that's the product she came back for and it's the one that matters. Don't skip it because she trusts you — the demo is what she came back for, two minutes of somebody making a fuss of her face.","THE PRICE IS NOT YOURS TO GIVE. This is the whole scenario, and it's the bit sellers get wrong because getting it wrong feels generous. A customer who came back gets priced by the manager — and if he's off the floor, by whoever out here has been doing this the longest. Say it to her like a compliment, because that is exactly what it is.","WAVE HIM OVER, DON'T WALK OFF. Never leave her stood at a table on her own while you go looking for somebody. Keep her sitting, keep the mirror in her hand, catch an eye and bring them to her.","ASK FOR THE PHOTO AND THE REVIEW WHILE SHE'S GLOWING. Bag in her hand, face done, still delighted — that's the only minute all year she says yes to a Google review. Ask warmly, once, and let it go if she'd rather not."],itemsEs:['MONTA UN BUEN ESCÁNDALO CON ELLA. "¡NO ME LO CREO, has vuelto! A ver, déjame verte — ¡TE LO DIJE!" Alto, encantado, delante de quien esté en la tienda. Ha vuelto por esa sensación tanto como por el producto.',"HAZLE LA DEMO IGUAL, Y QUE SEA LA JERINGA. Se ha acabado una entera, así que ese es el producto al que ha vuelto y es el que importa. No te la saltes porque se fíe de ti — la demo es a lo que ha vuelto, dos minutos de que alguien le haga caso a su cara.","EL PRECIO NO ES TUYO PARA DARLO. Este es el escenario entero, y es lo que se hace mal porque hacerlo mal parece generoso. A una clienta que vuelve le pone el precio el encargado — y si no está en la planta, quien lleve más tiempo aquí fuera haciendo esto. Díselo como un halago, porque es exactamente lo que es.","LLÁMALO CON LA MANO, NO TE VAYAS. No la dejes nunca sola de pie en la mesa mientras vas a buscar a alguien. Que siga sentada, con el espejo en la mano, y tú buscas una mirada y te lo traes a ella.","PÍDELE LA FOTO Y LA RESEÑA MIENTRAS ESTÁ RADIANTE. Con la bolsa en la mano, la cara hecha y todavía encantada — ese es el único minuto del año en el que dice que sí a una reseña de Google. Pídeselo con cariño, una vez, y déjalo estar si prefiere que no."]},{type:"subheader",text:"What NOT To Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Start from the beginning. "So, this is our hyaluronic syringe…" She bought one. You've just told her you don't remember her.`,"Put a number on her yourself. It feels like the generous thing to do and it's the one part of this that isn't yours. Even the family price is somebody else's to give.","Get greedy. She came back because you were straight with her. Pile three products on her and you spend all that trust in one go.","Forget what she bought. Her name, the product, where she's from — that's the whole trick, and nobody else on this street can copy it.",'Promise her something for next time. Not a held box, not a price kept warm, not "ask for me". You might not be on that shift, and a colleague has to stand there and explain.'],itemsEs:['Empezar desde el principio. "Bueno, esta es nuestra jeringa hialurónica..." Si ya se compró una. Le acabas de decir que no te acuerdas de ella.',"Ponerle tú el precio. Parece lo generoso y es la única parte de esto que no te toca a ti. Hasta el precio de la familia lo tiene que dar otro.","Ponerte codicioso. Ha vuelto porque fuiste honesto con ella. Échale tres productos encima y te gastas toda esa confianza de una sentada.","Olvidar qué se llevó. Su nombre, el producto, de dónde es — ese es todo el truco, y no hay nadie más en esta calle que pueda copiarlo.",'Prometerle algo para la próxima. Ni una caja guardada, ni un precio que le sigue valiendo, ni "pregunta por mí". Igual ese día no estás tú, y le toca a un compañero quedarse ahí dando explicaciones.']},{type:"subheader",text:"Script — The Welcome",textEs:"Guion — El Recibimiento"},{type:"script",text:`YOU: "NO. WAY. Maria!" [Genuinely delighted, and be loud about it] "Let me look at you — oh my God. I TOLD you. Look at that." [Let her enjoy it for a second] "You finished the whole thing? Good girl. Right — sit down. Same chair, same face, and I'm doing it again for nothing."`,textEs:'TÚ: "¡NO. ME. LO. CREO! ¡María!" [Encantado de verdad, y que se te oiga] "Déjame verte — madre mía. TE LO DIJE. Mira eso." [Deja que lo disfrute un segundo] "¿Te lo acabaste entero? Muy bien. Venga — siéntate. Misma silla, misma cara, y te lo vuelvo a hacer sin cobrarte nada."'},{type:"subheader",text:"Script — Straight Back In The Chair",textEs:"Guion — Otra Vez a la Silla"},{type:"script",text:`YOU: "You finished the whole thing — that's exactly why it worked on you. Most people leave half of it in a drawer and then come and tell me it does nothing." [Hands on, exactly like the first time, no shortcuts because she trusts you] "Sixty seconds. Same as before." [Mirror straight into her hand] "Look at that. Right — before I say one word about money, give me ten seconds."`,textEs:'TÚ: "Te lo acabaste entero — por eso te ha funcionado. La mayoría se deja la mitad en un cajón y luego viene a decirme que no hace nada." [Manos a la obra, igual que la primera vez, sin atajos por mucho que se fíe de ti] "Sesenta segundos. Como la otra vez." [El espejo directo a su mano] "Mira eso. Venga — antes de que diga una palabra del dinero, dame diez segundos."'},{type:"subheader",text:"Script — Getting The Boss",textEs:"Guion — Traerte al Jefe"},{type:"script",text:`YOU: "Right. You came back, so I'm not the one who decides what you pay today." [Straight, and make it sound like the best news she's had all week] "TONY! Come here a second — this is Maria, she finished a whole syringe, look at her face." [To her, while he's walking over] "He's the boss. He does the numbers for the people who come back, and he'll look after you better than I can." [Do not leave her side. He comes to the chair; she does not go to him. And if he isn't on the floor, you get whoever out here has been doing this the longest — never a number of your own.]`,textEs:'TÚ: "Venga. Como has vuelto, hoy no soy yo quien decide lo que pagas." [Directo, y que suene a la mejor noticia de su semana] "¡TONY! Ven un segundo — esta es María, se ha acabado una jeringa entera, mírale la cara." [A ella, mientras él viene] "Es el jefe. Él pone los números a la gente que vuelve, y te va a cuidar mejor que yo." [No te muevas de su lado. Él viene a la silla; ella no va a buscarlo. Y si no está en la planta, coges a quien lleve más tiempo aquí fuera haciendo esto — nunca un número tuyo.]'},{type:"subheader",text:"Script — One Favour Before She Goes",textEs:"Guion — Un Favor Antes de Que Se Vaya"},{type:"script",text:`YOU: "One favour before you go, and then I'll leave you alone." [Phone out, ready] "Can I get a photo of that face for the wall? And if you've got thirty seconds — a Google review, right now, while you're still happy with me." [She's holding the bag, she's just been looked after: this is the only minute she'll say yes in] "You're a star. Go on — enjoy the rest of your day."`,textEs:'TÚ: "Un favor antes de que te vayas, y ya te dejo en paz." [Móvil fuera, preparado] "¿Te puedo hacer una foto de esa cara para la pared? Y si tienes treinta segundos — una reseña en Google, ahora mismo, mientras sigues contenta conmigo." [Tiene la bolsa en la mano, la acaban de cuidar: este es el único minuto en el que va a decir que sí] "Eres un sol. Anda — ve a disfrutar del día."'},{type:"subheader",text:"Before You Walk Away",textEs:"Antes de Irte"},{type:"tip",text:`Keep a list on your phone: name, what they bought, when, and one personal thing — where she's from, the wedding, the sister with the same problem. Three months later you say "Maria! How was the wedding? Did the syringe last you the whole trip?" and she will not believe you remembered. That's the entire loyalty scheme and it costs nothing. Two rules go with it. One: the price is not yours. She came back, so the manager prices her, or whoever out here has been doing this the longest if he's off the floor. Handing her your own number feels like the generous thing and it's the one part of this you don't get to do. Two: nothing gets promised for next time. No held boxes, no price kept warm, no ask-for-me-by-name — you might be off that day and somebody else has to stand there and explain it. Give her everything today, and give it big.`,textEs:'Ten una lista en el móvil: nombre, qué se llevó, cuándo, y una cosa personal — de dónde es, la boda, la hermana con el mismo problema. Tres meses después le dices "¡María! ¿Qué tal la boda? ¿Te duró la jeringa todo el viaje?" y no se va a creer que te acordaras. Ese es todo el programa de fidelización, y no cuesta nada. Y con él van dos normas. Una: el precio no es tuyo. Ha vuelto, así que le pone el precio el encargado, o quien lleve más tiempo aquí fuera si él no está en la planta. Darle tu propio número parece lo generoso y es la única parte de esto que no te toca hacer. Dos: no se promete nada para la próxima. Ni cajas guardadas, ni precios que siguen en pie, ni "pregunta por mí" — igual ese día libras y le toca a otro quedarse ahí dando explicaciones. Dale todo hoy, y dáselo a lo grande.'}],quiz:[{question:"She is back three months later with a photo of her own face. Who decides what she pays today?",questionEs:"Vuelve tres meses después con una foto de su propia cara. ¿Quién decide hoy lo que paga?",options:["You do — you sold her the first one and you know what she is good for","The manager, or the most experienced person out on the floor","She does. Ask her what she thinks is fair and meet her there","Nobody yet — take her details and let her know a number later"],optionsEs:["Tú — le vendiste la primera y ya sabes hasta dónde llega","El encargado, o quien más experiencia tenga aquí en la planta","Ella. Le preguntas qué le parece justo y te quedas ahí","Nadie todavía — apuntas sus datos y ya le dices un número"],correctIndex:1,explanation:"A customer who came back is not yours to price. Get the boss to the chair — and if he is off the floor, whoever out here has been doing this the longest.",explanationEs:"A una clienta que vuelve no le pones tú el precio. Tráete al jefe a la silla — y si no está en la planta, a quien lleve más tiempo aquí fuera haciendo esto."},{question:"She trusts you completely and she has already got her card out. Do you still do the demo?",questionEs:"Se fía de ti del todo y ya ha sacado la tarjeta. ¿Le haces la demo igual?",options:["No — she has bought before, get straight to the price","No — doing it again suggests you do not believe her","Yes. Two minutes of somebody fussing over her face","Only if she asks, otherwise you are wasting her time"],optionsEs:["No — ya ha comprado antes, ve directo al precio","No — repetirla parece que no te la crees","Sí. Dos minutos de que alguien le haga caso a su cara","Solo si lo pide, si no le estás quitando el tiempo"],correctIndex:2,explanation:"The demo is what she came back for. Two minutes of somebody making a fuss of her face is the whole loyalty scheme.",explanationEs:"La demo es a lo que ha vuelto. Dos minutos de que alguien le haga caso a su cara son todo el programa de fidelización."},{question:"She is leaving with the bag. Which of these is safe to give her?",questionEs:"Se va con la bolsa. ¿Cuál de estas cosas puedes darle sin problema?",options:["A price you promise will still be waiting on her next trip","One held behind the till with her name written on it","Your name to ask for so she gets looked after next time","The whole lot today — gift in the bag, price done"],optionsEs:["Un precio que le prometes para su próximo viaje","Uno guardado en caja con su nombre escrito encima","Tu nombre para que pregunte y la cuiden la próxima","Todo hoy — regalo en la bolsa y precio cerrado"],correctIndex:3,explanation:"You might not be on that shift, and a colleague has to stand there and explain it. Give her everything today, and give it big.",explanationEs:"Igual ese día no estás tú y le toca a un compañero quedarse ahí dando explicaciones. Dale todo hoy, y dáselo a lo grande."}]}},l={O1:{id:"O1",categoryId:"objections",title:"I'm on a Budget",titleEs:"Ando Corto de Dinero / Tengo Presupuesto",subtitle:"A late-ladder objection — the fight is for the last price",subtitleEs:"Objeción de final de escalera — la pelea es por el último precio",duration:"4 min",icon:"Wallet",order:1,xpReward:100,sections:[{type:"header",text:"Where you actually are when you hear this",textEs:"Dónde estás de verdad cuando oyes esto"},{type:"paragraph",text:`Nobody says "I'm on a budget" at the first number. By the time those words come out you have already said {currency}300, you have probably put {currency}210 with the gift on the table, and you may well have taken the gift back off and shown her {currency}175. She is not arguing with your opening price — she heard it and walked straight past it. What she is doing now is telling you roughly where she can land, without saying a number out loud. That is information, and it is the best thing anybody has handed you all day.`,textEs:'Nadie dice "ando corta de dinero" con el primer número. Cuando le salen esas palabras ya le has dicho {currency}300, seguramente le has puesto encima de la mesa los {currency}210 con el regalo, y a lo mejor ya le has quitado el regalo y le has enseñado los {currency}175. No está discutiendo tu precio de salida — lo ha oído y ha pasado de largo. Lo que hace ahora es decirte más o menos dónde puede aterrizar, sin decir un número en voz alta. Eso es información, y es lo mejor que te ha dado nadie en todo el día.'},{type:"keypoint",text:"So do not spend your best line defending {currency}300. She has heard {currency}300. She said no to {currency}300. If you are fighting somebody over the price, you are not at the top of the ladder any more — you are near the bottom of it or on your way there, and the fight is for your LAST price, not your first one.",textEs:"Así que no gastes tu mejor frase defendiendo los {currency}300. Ya ha oído los {currency}300. Ya ha dicho que no a los {currency}300. Si estás peleando con alguien por el precio, ya no estás arriba de la escalera — estás abajo o vas de camino, y la pelea es por tu ÚLTIMO precio, no por el primero."},{type:"quote",text:"Your job is not to defend a number. It is to make the last number land like something you did for her — and to get the yes before she moves.",textEs:"Tu trabajo no es defender un número. Es que el último número le llegue como algo que has hecho por ella — y llevarte el sí antes de que se mueva."},{type:"subheader",text:"What she has actually told you",textEs:"Lo que te ha dicho en realidad"},{type:"bullets",items:["She is still standing there. Nobody haggles over something they do not want, so those words only ever come out of a woman who has already decided she likes it.",'"Budget" is a number she has not said out loud. It means "not that, but something" — your job is to find the rung, not to argue her back up to the one she has already refused.','Handing money over feels like losing something she already has, and what she gets back is a maybe. That is the whole reason "it lasts a year" works: it turns one painful number into a small one she pays once and then forgets.',"The number she is holding yours up against is nothing at all — she came in here to buy nothing. Put a real one beside it: the {currency}500 the same syringe costs in a shop back home, and everything she will hand over for creams that do nothing between now and next summer."],itemsEs:["Sigue ahí plantada. Nadie regatea por algo que no quiere, así que esas palabras solo le salen a una mujer que ya ha decidido que le gusta.",'"Presupuesto" es un número que no ha dicho en voz alta. Significa "eso no, pero algo sí" — tu trabajo es encontrar el escalón, no discutir para subirla otra vez al que ya ha rechazado.','Soltar el dinero se siente como perder algo que ya tiene, y lo que recibe a cambio es un quizá. Por eso funciona lo de "te dura un año": convierte un número que duele en uno pequeño que paga una vez y se olvida.',"El número con el que compara el tuyo es cero — ha entrado aquí a no comprar nada. Ponle uno de verdad al lado: los {currency}500 que cuesta esta misma jeringa en una tienda de su país, y todo lo que va a soltar en cremas que no hacen nada de aquí al verano que viene."]},{type:"subheader",text:"Script 1: The rung with a reason (short)",textEs:"Guion 1: El escalón con motivo (corto)"},{type:"script",text:'YOU: "On a budget — alright, talk to me, I like you." [Half a smile. Do not flinch, do not apologise for your own number, and do NOT move yet] "Look, I have already taken the gift off to get you to {currency}175, so I am not exactly miles away as it is. That is a year of your face, that one — sixty goes in there, one a week. Works out about {currency}3 a week." [Now stop talking. Let it sit. She has said one sentence about money; if you drop a rung on one sentence she learns the numbers fall whenever she mentions her budget, and she will mention it again]',textEs:'TÚ: "Que vas justa — vale, háblame, que me caes bien." [Media sonrisa. No te encojas, no pidas perdón por tu propio número, y NO te muevas todavía] "Mira, ya te he quitado el regalo para dejarte en {currency}175, o sea que tampoco ando tan lejos. Y eso es un año de tu cara — sesenta veces ahí dentro, una por semana. Te sale como a {currency}3 la semana." [Y ahora te callas. Déjalo ahí. Ha dicho una frase sobre dinero; si le bajas un escalón por una frase, aprende que los números caen cada vez que menciona su presupuesto, y lo va a mencionar otra vez]'},{type:"subheader",text:"Script 2: The maths at the rung you are standing on (medium)",textEs:"Guion 2: La cuenta en el escalón donde estás (medio)"},{type:"script",text:'YOU: "Come here a second — let me show you why your budget is not the problem you think it is." [Put the syringe back in her hand and leave it there] "Forget what it says on the box. You are at {currency}140 with me. Gift off, voucher on, and that is not a number I say to everybody who walks past." [Now the sum, slowly] "Sixty applications in there, one a week. That is you covered until next summer. So it is a bit over {currency}2 a go. Under {currency}3 a week. That is not a budget decision, my love, that is one coffee a week — except this one takes ten years off the side of your face." [Then stop talking. Let her do the sum on her own] "So — card or cash?"',textEs:'TÚ: "Ven un segundo — deja que te enseñe por qué lo del presupuesto no es el problema que te crees." [Vuelve a ponerle la jeringa en la mano y déjasela ahí] "Olvídate de lo que pone en la caja. Conmigo estás en {currency}140. Sin regalo, con el cupón, y ese no es un número que le diga a todo el que pasa." [Ahora la cuenta, despacio] "Ahí dentro hay sesenta aplicaciones, una por semana. Tienes hasta el verano que viene. O sea, poco más de {currency}2 cada vez. Menos de {currency}3 a la semana. Eso no es una decisión de presupuesto, cariño, eso es un café a la semana — solo que este te quita diez años de este lado de la cara." [Y ahora te callas. Deja que eche ella la cuenta] "Entonces, ¿tarjeta o efectivo?"'},{type:"subheader",text:"Script 3: Full market, and then it stops being yours (detailed)",textEs:"Guion 3: Mercado del todo, y ahí deja de ser tuyo (detallado)"},{type:"script",text:'YOU: "You are killing me here." [Hands up, big laugh, not a trace of an edge in it] "I have taken the gift off, I have put my voucher on you, and you are still coming at me. Go on then — say your number. Out loud." [Let her say it. Do NOT answer it. Look at the syringe. Look at the door. Breathe out like it costs you something] "Ooof. You are a hard one, you." [Hold it. Count to three in your head — the waiting is the whole trick, and most sellers cannot do it] "Right." [Voice right down, lean in, this bit is a secret] "That number is not mine to give you. But I am going to go and ask for it." [Up, brisk, already moving — the going IS the argument] "Give me two seconds, I am going to go and ask my manager. I am promising you nothing, alright? Do not move." [You go. You come back WITH the manager, and the number comes out of his mouth, not yours] "And look at what you are actually buying — a year of it, sixty goes, under {currency}2 each. If you genuinely would not use it, keep your money and no hard feelings. But you have not put that mirror down since you sat in my chair. Card or cash, my darling?"',textEs:'TÚ: "Me estás matando." [Manos arriba, risa grande, sin una pizca de mala leche] "Te he quitado el regalo, te he gastado el cupón, y todavía vienes a por mí. Venga — dime tu número. En voz alta." [Deja que lo diga. NO lo contestes. Mira la jeringa. Mira a la puerta. Suelta el aire como si te doliera] "Buf. Menuda eres tú." [Aguanta. Cuenta hasta tres por dentro — la espera es todo el truco, y casi ningún vendedor sabe hacerla] "Vale." [Baja la voz del todo, acércate, esto es un secreto] "Ese número no es mío para dártelo. Pero voy a ir a pedirlo." [Arriba, rápido, ya moviéndote — el ir ES el argumento] "Dame dos segundos, voy a preguntarle a mi encargado. No te prometo nada, ¿eh? No te muevas." [Vas. Y vuelves CON el encargado, y el número sale de su boca, no de la tuya] "Y mira lo que te llevas de verdad — un año entero, sesenta veces, menos de {currency}2 cada una. Si de verdad no lo fueras a usar, guárdate el dinero y sin rencores. Pero es que no has soltado el espejo desde que te has sentado en mi silla. ¿Tarjeta o efectivo, cariño?"'},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Open at the bottom because she looks like she is on a budget. Trainers, one carrier bag, a pushchair — none of that tells you what is in her account, and the woman who spends the most on you today will not look like it. Start at the top and walk down, every single time. Guess her wallet off her shoes and you will never find out what she would have paid.","Drop before she has asked. A price that falls on its own was never a price. Let her push first — and make her push twice before you move once.","Drop with nothing attached to it. Every rung needs a pause, a face and a reason: the gift coming off, the voucher, my last customer only took one. If the number simply falls, you have told her you were making it up, and now she will lean on you until the floor gives way.","Get to {currency}100 in ten seconds to be helpful. She will not believe it is your last price, and she is right not to. The floor is a floor — nobody gets there by asking twice.",'Point your last customer the wrong way. "The lady before you took three!" makes her feel behind. Turn her round — "my last one only took one, so I have got a bit of room for you" — and the same story hands her something instead of nagging her. Give.',"Send her off to add it up. There is nothing to add up and nowhere to do it but here. A budget gets answered with a number, in front of you, today — never at the door."],itemsEs:["Abrir por abajo porque tiene pinta de ir justa. Zapatillas, una sola bolsa, un carrito de bebé — nada de eso te dice lo que tiene en la cuenta, y la que más se te gaste hoy no lo va a parecer. Empieza arriba y baja andando, siempre. Adivínale la cartera por los zapatos y no sabrás nunca lo que habría pagado.","Bajar antes de que te lo pida. Un precio que cae solo nunca fue un precio. Que empuje ella primero — y que empuje dos veces antes de que tú te muevas una.","Bajar sin nada pegado al número. Cada escalón necesita una pausa, una cara y un motivo: que sale el regalo, que hay cupón, que mi última clienta se llevó solo una. Si el número cae y ya está, le has dicho que te lo estabas inventando, y ahora te va a apretar hasta que el suelo se hunda.","Plantarte en {currency}100 en diez segundos por hacer el favor. No se va a creer que es tu último precio, y hace bien. El suelo es el suelo — ahí no se llega por pedirlo dos veces.",'Usar a tu última clienta al revés. "¡La señora de antes se llevó tres!" la deja por detrás. Dale la vuelta — "la última se llevó solo una, así que tengo un poco de margen para ti" — y la misma historia le regala algo en vez de darle la lata. Regala.',"Mandarla a echar cuentas por ahí. No hay nada que calcular y no hay otro sitio para hacerlo que este. Un presupuesto se contesta con un número, delante de ti, hoy — nunca en la puerta."]},{type:"tip",text:"Do the sum on the rung you are standing on, never on the one she has already refused. Divide {currency}140, not {currency}300 — running the calculator on {currency}300 just plays her back a number she has said no to. {currency}140 across a year is pennies a day, under {currency}3 a week, a bit over {currency}2 an application. Say the small number once, then shut up and let her finish the sum herself. And wherever you end up on that ladder, it ends here — nobody leaves this shop to work it out at home.",textEs:"Haz la cuenta en el escalón donde estás, nunca en el que ya ha rechazado. Divide {currency}140, no {currency}300 — sacar la calculadora con los {currency}300 solo le repite un número al que ya ha dicho que no. {currency}140 repartidos en un año es calderilla al día, menos de {currency}3 a la semana, poco más de {currency}2 por aplicación. Di el número pequeño una vez, cállate y deja que termine ella la cuenta. Y acabes donde acabes en esa escalera, esto se acaba aquí — de esta tienda no sale nadie a hacer números en casa."}],quiz:[{question:"She has heard {currency}300, you took the gift off at {currency}175, and now she says she is on a budget. Where are you?",questionEs:"Ha oído los {currency}300, le has quitado el regalo en {currency}175, y ahora te dice que va justa. ¿Dónde estás?",options:["Low on the ladder — one rung and the floor left under you","Right at the start, because she has not named a number yet","Still at the top, holding {currency}300 until she gives in","At the end of it — she has just told you she cannot afford any of this"],optionsEs:["Abajo en la escalera — te quedan un escalón y el suelo","Al principio del todo, porque aún no ha dicho ningún número","Arriba todavía, aguantando los {currency}300 hasta que ceda","Al final de todo — acaba de decirte que no le llega para nada de esto"],correctIndex:0,explanation:"Nobody says it at the first number. By the time you hear it you have already walked her down, so what is left is the voucher rung and the floor underneath it.",explanationEs:"Nadie lo dice con el primer número. Cuando lo oyes ya la has bajado tú, así que lo que queda es el escalón del cupón y el suelo que hay debajo."},{question:'She has said "I am on a budget" once, and you are standing on {currency}175. What comes out of your mouth?',questionEs:'Ha dicho "voy justa de dinero" una vez, y tú estás en {currency}175. ¿Qué sale de tu boca?',options:["What {currency}175 actually buys her — a year of it — and then silence","The voucher: {currency}140, before she has even had to ask you twice","{currency}300 broken down by the day, so the big number sounds small","Straight to {currency}100, because that is where this is heading anyway"],optionsEs:["Lo que le da de verdad ese {currency}175 — un año — y luego silencio","El cupón: {currency}140, antes de que te lo haya pedido dos veces","Los {currency}300 partidos por días, para que el número suene pequeño","Directo a {currency}100, que al final es donde va a acabar esto"],correctIndex:0,explanation:'One sentence about money is not a push. Hold where you are, tell her what {currency}175 buys — a year of it, one a week — and then shut up. Drop a rung on the first mention and you have taught her that saying "budget" moves your numbers, so she will say it again. Make her ask twice before you move once, and the voucher lands like something instead of nothing.',explanationEs:'Una frase sobre dinero no es un empujón. Aguanta donde estás, dile lo que le da ese {currency}175 — un año, una vez por semana — y luego te callas. Si bajas un escalón a la primera, le has enseñado que decir "voy justa" mueve tus números, así que lo va a repetir. Que te lo pida dos veces antes de moverte una, y así el cupón le llega como algo y no como nada.'},{question:"She is at {currency}140 and leans on you one more time. Who says {currency}100?",questionEs:"Está en {currency}140 y te aprieta una vez más. ¿Quién dice los {currency}100?",options:["You do, quietly, with a reason — your last customer only took one, so there is room today","You do, but only after she has asked for it twice","A manager. You go and get one, and the number comes out of his mouth","Nobody — {currency}140 is the floor and there is nothing underneath it"],optionsEs:["Tú, en voz baja y con un motivo — tu última clienta se llevó solo una, así que hoy hay margen","Tú, pero solo después de que te lo haya pedido dos veces","Un encargado. Vas a buscarlo, y el número sale de su boca","Nadie — {currency}140 es el suelo y debajo no hay nada"],correctIndex:2,explanation:"One voucher, once, and it takes you to {currency}140. Below that the theatre changes: you go full market — her number out loud, the pause, the face, hands in the air — and then you go and fetch a manager. A seller who can reach the floor on their own has no floor, because she can always ask you for one more.",explanationEs:"Un cupón, una vez, y te lleva a {currency}140. Por debajo cambia el teatro: te vas a mercado del todo — su número en voz alta, la pausa, la cara, las manos arriba — y luego vas a buscar a un encargado. Un vendedor que puede llegar al suelo él solo no tiene suelo, porque ella siempre te puede pedir uno más."},{question:"One syringe, sixty applications, one a week, and you are standing at {currency}140. Which line shrinks it?",questionEs:"Una jeringa, sesenta aplicaciones, una por semana, y estás en {currency}140. ¿Qué frase lo hace pequeño?",options:['"Everybody tells me it is expensive, you are not the only one"','"Just tell me what you want to pay and I will see what I can do"','"A year in there, sixty goes — under {currency}3 a week"','"Honestly, it is not that expensive once you really think about it"'],optionsEs:['"Todo el mundo me dice que es caro, no eres la única"','"Dime tú lo que quieres pagar y yo miro qué puedo hacer"','"Un año ahí dentro — menos de {currency}3 a la semana"','"De verdad que no es tan caro si te paras a pensarlo un poco"'],correctIndex:2,explanation:"Do the sum on the rung you are on. {currency}140 over sixty applications is a bit over {currency}2 a go — a far smaller sentence than the same maths on a price she has already refused.",explanationEs:"Haz la cuenta en el escalón donde estás. {currency}140 entre sesenta aplicaciones es poco más de {currency}2 cada vez — una frase mucho más pequeña que la misma cuenta sobre un precio que ya ha rechazado."}]},O2:{id:"O2",categoryId:"objections",title:"Let Me Think About It",titleEs:"Déjame Pensarlo",subtitle:"Breaking through decision paralysis with urgency and risk removal",subtitleEs:"Rompiendo la parálisis de decisión con urgencia y eliminación de riesgo",duration:"4 min",icon:"Clock",order:2,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:`"Let me think about it" is the silent killer of street sales. It sounds polite, but it means one of three things: (1) They're scared to commit, (2) They don't feel enough urgency, or (3) They want to say no without being rude. Your job is to address all three without being pushy.`,textEs:'"Déjame pensarlo" es el asesino silencioso de las ventas en la calle. Suena educado, pero significa una de tres cosas: (1) Les da miedo comprometerse, (2) No sienten suficiente urgencia, o (3) Quieren decir que no sin ser groseros. Tu trabajo es abordar las tres sin ser agresivo.'},{type:"subheader",text:'The Psychology Behind "Let Me Think About It"',textEs:'La Psicología Detrás de "Déjame Pensarlo"'},{type:"bullets",items:['Decision Paralysis: Too many options or too much information freezes the brain. Street demos create instant desire, but the purchasing decision still requires a mental "leap."',`Fear of Regret: They imagine buying it, going home, and thinking "I shouldn't have spent that." You need to flip this — make them fear missing out MORE than buying.`,`Politeness Buffer: Most people won't say "no" to your face. They use "thinking about it" as an escape hatch. Your job is to take the escape hatch away, gently, before she uses it.`],itemsEs:['Parálisis de Decisión: Demasiadas opciones o demasiada información congela el cerebro. Las demos en la calle crean deseo instantáneo, pero la decisión de compra todavía requiere un "salto" mental.','Miedo al Arrepentimiento: Se imaginan comprándolo, llegando a casa, y pensando "no debí gastar eso." Necesitas voltear esto — haz que teman perderse la oportunidad MÁS que comprar.','Cortesía de Escape: La mayoría no te dirá "no" a la cara. Usan "pensarlo" como escapatoria. Tu trabajo es quitarles la escapatoria, con cariño, antes de que la usen.']},{type:"subheader",text:"Script 1: The Urgency Anchor (Short)",textEs:"Guion 1: El Ancla de Urgencia (Corto)"},{type:"script",text:`YOU: "I totally understand! But here's the thing — you're in {locationName} right now. The moment you cross that border, the exact same syringe is {currency}500 in a shop. This offer is right here, right now. And honestly? The results you just saw don't need thinking — they need action. Grab it while you're here!"`,textEs:'TÚ: "¡Totalmente entiendo! Pero fíjate — ahora mismo estás en {locationName}. En cuanto cruces esa frontera, esta misma jeringa cuesta {currency}500 en una tienda. Esta oferta es aquí, ahora. Y honestamente? Los resultados que acabas de ver no necesitan pensarse — necesitan acción. ¡Cógelo mientras estás aquí!"'},{type:"subheader",text:"First: the two yeses she already gave you",textEs:"Primero: los dos síes que ya te ha dado"},{type:"paragraph",text:'You got these during the demo, while her hand was still in yours — "Do you like it?" and "If you had it at home, would you use it?" Once she has said yes to both, there is nothing left for her to think ABOUT except the price. So do not argue with the thinking. Hand her back her own two answers and put the decision in front of her, now, while she is sitting down.',textEs:'Estos los conseguiste durante la demo, con su mano todavía en la tuya — "¿Te gusta?" y "Si lo tuvieras en casa, ¿lo usarías?" Una vez que ha dicho que sí a las dos, no le queda nada que pensar salvo el precio. Así que no discutas con el pensárselo. Devuélvele sus dos respuestas y ponle la decisión delante, ahora, mientras sigue sentada.'},{type:"script",text:'YOU: "Think about what, my darling? You told me you like it. You told me you would use it. It is not a mortgage." [Smile, and mean it — this is not a gotcha] "So the only thing left is the money, and that we can talk about right now. What were you hoping to pay?"',textEs:'TÚ: "¿Pensar el qué, cariño? Me has dicho que te gusta. Me has dicho que lo usarías. Que no es una hipoteca." [Sonríe, y de verdad — esto no es una encerrona] "Así que lo único que queda es el dinero, y eso lo hablamos ahora mismo. ¿Cuánto esperabas pagar?"'},{type:"keypoint",text:"If she never gave you the two yeses, that is the real problem and it happened back in the demo, not here. Nothing in this lesson works as well without them.",textEs:"Si nunca te dio los dos síes, ese es el problema de verdad y pasó en la demo, no aquí. Nada de esta lección funciona igual de bien sin ellos."},{type:"subheader",text:"Script 2: Nothing Left to Find Out (Medium)",textEs:"Guion 2: Ya No Queda Nada Por Averiguar (Medio)"},{type:"script",text:`YOU: "I get it, it's a big decision. Go on then — what is it? The price, the product, or you just want to sleep on it?" [Let them answer] "Here's the thing, though. You're not taking my word for anything. You didn't read a review, you didn't watch an advert — you watched it happen on your own face, sixty seconds ago, with your own eyes. There is nothing left to find out. The only thing sleeping on it changes is that you sleep with the line still there. So — are you going to THINK about looking younger, or are you going to do it?"`,textEs:'TÚ: "Lo entiendo, es una decisión importante. Venga, dime — ¿qué es? ¿El precio, el producto, o que quieres consultarlo con la almohada?" [Deja que contesten] "Pero mira una cosa. Aquí no te estás fiando de mí. No has leído una reseña ni has visto un anuncio — lo has visto pasar en tu propia cara, hace sesenta segundos, con tus propios ojos. Ya no queda nada por averiguar. Lo único que cambia si lo consultas con la almohada es que duermes con la línea todavía ahí. Así que — ¿vas a PENSAR en verte más joven, o lo vas a hacer?"'},{type:"subheader",text:"Script 3: The Scarcity + Social Proof Framework (Detailed)",textEs:"Guion 3: El Marco de Escasez + Prueba Social (Detallado)"},{type:"script",text:`YOU: "I hear you — thinking about it makes sense. But let me be real with you for a second." [Lean in, lower voice] "I had a lady yesterday, just like you. Beautiful skin, a little line here she didn't love. She said 'let me think about it.' She came back TWO HOURS later — the line was still gone, she couldn't stop touching her face — and we were sold out. She begged me to hold one. I couldn't. She left heartbroken. Now look at you — you saw your own wrinkles disappear in 60 seconds. You KNOW it works. This isn't a thinking decision, it's a feeling decision. And your skin is FEELING amazing right now. We only have a few units left today. I'm not saying that to pressure you — I'm saying it because I don't want YOU to be the one coming back in two hours and finding out we're gone. So what do you say — should I wrap one up for you?"`,textEs:`TÚ: "Te escucho — pensarlo tiene sentido. Pero déjame ser honesta contigo un segundo." [Acércate, baja la voz] "Tuve una señora ayer, igual que tú. Piel hermosa, una línea aquí que no le gustaba. Dijo 'déjame pensarlo.' Volvió DOS HORAS después — la línea todavía estaba ida, no podía dejar de tocar su cara — y ya nos habíamos agotado. Me rogó que le guardara uno. No pude. Se fue deshecha. Ahora mírate — viste tus propias arrugas desaparecer en 60 segundos. SABES que funciona. Esta no es una decisión de pensar, es una decisión de sentir. Y tu piel está sintiéndose INCREÍBLE ahora mismo. Solo nos quedan pocas unidades hoy. No te lo digo para presionarte — te lo digo porque no quiero que TÚ seas la que vuelva en dos horas y descubra que ya no hay. Entonces, ¿qué dices — te envuelvo uno?"`},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Say "OK, take your time" — You've just killed the sale. They'll walk away and the desire fades within minutes.`,"Lead with the discount — Come down the ladder when she tells you the price is the problem, not before. Drop it early and you have paid good money for a yes she was about to give you anyway.","Turn cold on her — Firm is fine, sour is not. The smile stays on while you hold the number, or she says no just to get away from you.","Hand her something to take away — A card, a sample, the price written down. It feels helpful and it walks her straight out of the door. Whatever you were going to give her, give it to her here, with the box already in her hand."],itemsEs:['Decir "OK, tómate tu tiempo" — Acabas de matar la venta. Se irán caminando y el deseo se desvanece en minutos.',"Empezar por el descuento — Baja la escalera cuando ella te diga que el problema es el precio, no antes. Si lo sueltas pronto, has pagado por un sí que te iba a dar igualmente.","Ponerte seca con ella — Firme sí, borde no. La sonrisa no se te cae mientras aguantas el número, o te dirá que no solo para quitarte de encima.","Darle algo para llevarse — Una tarjeta, una muestra, el precio apuntado. Parece un detalle y la saca directa por la puerta. Lo que le fueras a dar, se lo das aquí, con la caja ya en la mano."]},{type:"tip",text:`Create a genuine reason for urgency. Check your stock before each shift and know what's running low. "Only 3 left" is powerful ONLY when it's true. Customers can smell fake scarcity from a mile away. And give her the mirror twice — once before, once after, with the mirror in her own hand. A photo she might look at tonight is worth nothing to you. The face she is looking at right now is worth everything. Sell to that one.`,textEs:'Crea una razón genuina de urgencia. Revisa tu inventario antes de cada turno y sabe qué se está acabando. "Solo quedan 3" es poderoso SOLO cuando es verdad. Los clientes huelen la escasez falsa a kilómetros. Y dale el espejo dos veces — antes y después, y que lo sujete ella. Una foto que a lo mejor mira esta noche no te vale de nada. La cara que está mirando ahora mismo lo vale todo. Véndele a esa.'}],quiz:[{question:'She says "I will come back tomorrow." Which of these ends with her buying?',questionEs:'Te dice "mañana me paso". ¿Cuál de estas acaba con ella comprando?',options:['"Of course — take your time, no rush from me at all"',"Write the price on a card so she has it with her","Offer to hold one at the counter until she has made her mind up properly",'"Go on then — what is it? The price, the product, or the sleep?"'],optionsEs:['"Claro que sí — tómate tu tiempo, sin ninguna prisa"',"Apúntale el precio en una tarjeta para que se lo lleve","Ofrecerte a guardarle uno en el mostrador hasta que se decida del todo",'"Venga, dime — ¿qué es? ¿El precio, el producto o la almohada?"'],correctIndex:3,explanation:"Naming the real objection is the only way to answer it. Every other option here is a polite way of handing her the door.",explanationEs:"Ponerle nombre a la objeción de verdad es la única forma de contestarla. Todo lo demás aquí es abrirle la puerta con buenos modales."},{question:"She watched the line go on her own face a minute ago, and now she wants to sleep on it. What do you say?",questionEs:"Hace un minuto ha visto irse la línea en su propia cara, y ahora quiere consultarlo con la almohada. ¿Qué le dices?",options:['"Have a walk around and come back if you decide you want it"','"There is nothing left to find out — you saw it on your own face"','"I understand, it is a lot of money to spend on a holiday"','"Everybody says that, and most of them are sorry about it by the evening"'],optionsEs:['"Date una vuelta y vuelve si decides que lo quieres"','"Ya no queda nada por averiguar — lo has visto en tu propia cara"','"Te entiendo, es mucho dinero para gastarlo de vacaciones"','"Eso lo dice todo el mundo, y por la noche casi todas se arrepienten"'],correctIndex:1,explanation:"She did not read a review, she watched it happen. There is no new information waiting for her outside, only a feeling that fades.",explanationEs:"No ha leído una reseña, lo ha visto pasar. Fuera no le espera ninguna información nueva, solo que se le pase la sensación."},{question:"She is wavering and she has not once mentioned money. What is the mistake here?",questionEs:"Está dudando y no ha mencionado el dinero ni una vez. ¿Cuál es el error?",options:["Leading with a discount she never asked you for","Holding the number with the smile still on your face","Asking her straight out what is actually stopping her","Handing her the mirror a second time and letting her look"],optionsEs:["Empezar por un descuento que no te ha pedido","Aguantar el número con la sonrisa todavía puesta","Preguntarle a bocajarro qué es lo que la frena","Darle el espejo otra vez y dejar que se mire"],correctIndex:0,explanation:"Come down the ladder when she tells you the price is the problem. Drop early and you have paid good money for a yes she was going to give you anyway.",explanationEs:"Baja la escalera cuando ella te diga que el problema es el precio. Si lo sueltas antes, has pagado por un sí que te iba a dar igualmente."}]},O3:{id:"O3",categoryId:"objections",title:"My Husband/Wife Will Kill Me",titleEs:"Mi Esposo/a Me Mata",subtitle:"Turning spousal fear into a shared win",subtitleEs:"Convirtiendo el miedo al cónyuge en una victoria compartida",duration:"4 min",icon:"Heart",order:3,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"This one sounds like it is about the partner. It is not. He is playing golf, he is at the hotel, he is anywhere but here — and he is not thinking about her face. She already told you she likes it and she would use it, so the deciding is done. What she is actually asking for is permission, and the only person who can hand it to her is the woman holding the mirror. Give the decision back to her, right now, while she is still standing in front of you.",textEs:"Esta parece que va de la pareja. No va de eso. Él está jugando al golf, está en el hotel, está en cualquier sitio menos aquí — y no está pensando en la cara de ella. Ya te ha dicho que le gusta y que lo usaría, así que decidido está. Lo que está pidiendo en realidad es permiso, y la única persona que puede dárselo es la mujer que tiene el espejo en la mano. Devuélvele la decisión, ahora mismo, mientras la tienes delante."},{type:"subheader",text:'The Psychology Behind "My Partner Will Kill Me"',textEs:'La Psicología Detrás de "Mi Pareja Me Mata"'},{type:"bullets",items:["Social Accountability: People care more about what their partner thinks than what a stranger thinks. The fear of the conversation at home is stronger than the desire.",`The Two Yeses Already Happened: She said she likes it. She said she would use it. After that she cannot object to anything except the price — so "I'll ask him" is her looking for permission, not information.`,`The Door Dressed As A Reason: "I'll ask him" is the politest exit in the shop. The second she goes off to find him the sale is over, because the feeling she had in that chair is gone before she has crossed the road.`],itemsEs:["Responsabilidad Social: A la gente le importa más lo que piensa su pareja que lo que piensa un desconocido. El miedo a la conversación en casa es más fuerte que las ganas.",'Los Dos Síes Ya Están Dados: Te ha dicho que le gusta. Te ha dicho que lo usaría. Después de eso ya no puede objetar nada que no sea el precio — así que "se lo pregunto a él" es que busca permiso, no información.','La Puerta Disfrazada de Motivo: "Se lo pregunto a él" es la salida más educada de la tienda. En cuanto se va a buscarlo, la venta se acabó, porque lo que sintió en esa silla se le pasa antes de cruzar la calle.']},{type:"subheader",text:"Script 1: Ladies' Business (Short) — the one you use first",textEs:"Guion 1: Cosa de Chicas (Corto) — el que usas primero"},{type:"script",text:`YOU: "Ladies' business, my darling. He is playing golf — he is not thinking about your face." [Big smile, keep hold of her hand, no edge in it at all] "You said you like it, you said you would use it. So it is your call, not his. Spoil yourself. And if you really would not use it, keep your money — no hard feelings."`,textEs:'TÚ: "Cosa de chicas, cariño. Él está jugando al golf — no está pensando en tu cara." [Sonrisa grande, sin soltarle la mano, sin una pizca de mala leche] "Me has dicho que te gusta, me has dicho que lo usarías. Así que esto lo decides tú, no él. Date un capricho. Y si de verdad no lo fueras a usar, guárdate el dinero — sin rencores."'},{type:"keypoint",text:'Read that last line again, because it is the part everyone leaves out. "If you really would not use it, keep your money" is not a softener bolted on the end — being genuinely willing to walk away from her money is what makes the whole thing land. It also tells her, in one sentence, that you are not the person she was braced for.',textEs:'Léete otra vez la última frase, porque es la parte que todo el mundo se salta. "Si de verdad no lo fueras a usar, guárdate el dinero" no es un caramelito pegado al final — que estés dispuesto de verdad a renunciar a su dinero es lo que hace que todo esto funcione. Y además le dice, en una frase, que tú no eres el vendedor que ella se esperaba.'},{type:"subheader",text:"Script 2: The Gift Framing (Medium) — stay on the syringe",textEs:"Guion 2: Enmarcar como Regalo (Medio) — sin salirte de la jeringa"},{type:"script",text:'YOU: "I love that you care what they think! But listen — nobody at home is going to be cross about THIS. You get two syringes for the same money: one for you, one for your sister, your daughter, whoever you like. Same price, and now it is a present from {locationName} instead of a treat for yourself. Who gets the second one?"',textEs:'TÚ: "¡Me encanta que te importe lo que piensen! Pero mira — en casa nadie se va a enfadar por ESTO. Te llevas dos jeringas por el mismo dinero: una para ti y otra para tu hermana, tu hija, para quien tú quieras. El mismo precio, y ahora es un regalo de {locationName} en vez de un capricho tuyo. ¿Para quién es la segunda?"'},{type:"subheader",text:'Script 3: The "You Deserve This" Close (Detailed)',textEs:'Guion 3: El Cierre de "Te Mereces Esto" (Detallado)'},{type:"script",text:`YOU: "Okay, real talk. How many times have you put yourself last? Kids first, husband first, work first... when was the last time you did something JUST for you?" [Let them think] "Look at what just happened. In 60 seconds, you watched years come off your face. You felt that. I saw your face light up. Your partner loves you, right? They want you to feel beautiful. They want you to be confident. So here's what you do: you walk in tonight, you look them in the eye, and you say 'I treated myself today. Because I deserve it. And LOOK.'" [Point to their skin] "They won't be mad. They'll be amazed. And honestly? If someone gets mad at you for investing in yourself... that's a conversation worth having. So — are we wrapping this up as a 'me gift' or an 'us gift'?"`,textEs:`TÚ: "Vale, hablando en serio. ¿Cuántas veces te has puesto a ti al último? Los niños primero, el esposo primero, el trabajo primero... ¿cuándo fue la última vez que hiciste algo SOLO para ti?" [Déjalos pensar] "Mira lo que acaba de pasar. En 60 segundos, viste años desaparecer de tu cara. Sentiste eso. Vi tu cara iluminarse. Tu pareja te ama, ¿verdad? Quiere que te sientas hermosa. Quiere que estés segura de ti misma. Entonces esto es lo que haces: entras esta noche, lo miras a los ojos, y dices 'me di un gusto hoy. Porque me lo merezco. Y MIRA.'" [Señala su piel] "No estarán enfadados. Estarán asombrados. Y honestamente? Si alguien se enfada porque inviertes en ti misma... esa es una conversación que vale la pena tener. Entonces — ¿lo envolvemos como un 'regalo para mí' o un 'regalo para nosotros'?"`},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:['Badmouth their partner: "He sounds controlling!" — This creates division, not desire.',"Send her home to ask him: The second she leaves to check, you have lost her — and he is not sitting at home thinking about her face. It is her money and her mirror, so put the decision back in her hands while she is still standing in front of you.","Ignore the objection: Pretending they didn't mention a partner makes you tone-deaf.","Suggest they hide it: Dishonesty stories backfire. Give them an honest narrative that wins."],itemsEs:['Hablar mal de su pareja: "¡Suena controlador!" — Esto crea división, no deseo.',"Mandarla a casa a preguntarle: En cuanto se va a consultarlo, la has perdido — y él no está en casa pensando en la cara de ella. Es su dinero y su espejo, así que devuélvele la decisión mientras la tienes delante.","Ignorar la objeción: Pretender que no mencionaron pareja te hace parecer sordo.","Sugerir que lo escondan: Las historias de deshonestidad se voltean en contra. Dale una narrativa honesta que gane."]},{type:"tip",text:"Ladies' business goes first, every time. It is the shortest answer in the lesson and it is the one that works, because it hands the decision straight back to the person who has already said yes twice. The gift-for-two angle is your second move, not your opener — the second syringe for somebody at home turns a selfish purchase into a thoughtful one without the number moving at all. Stay on the syringe while you do it: piling a scrub and a nail kit on top is a different sale, and it is not the one you are in. What you never do, whatever she says next, is send her off to go and find him.",textEs:'Lo de "cosa de chicas" va primero, siempre. Es la respuesta más corta de la lección y es la que funciona, porque le devuelve la decisión a la persona que ya ha dicho que sí dos veces. Lo del regalo para dos es tu segunda jugada, no tu apertura — la segunda jeringa para alguien de casa convierte un capricho en un detalle sin que el número se mueva. Y quédate en la jeringa mientras lo haces: amontonarle un exfoliante y un kit de uñas encima es otra venta, y no es en la que estás. Lo que no haces nunca, diga lo que diga, es mandarla a buscarlo.'}],quiz:[{question:"She has said yes to both questions and then says she has to ask her husband. What do you say?",questionEs:"Ha dicho que sí a las dos preguntas y ahora te dice que se lo tiene que preguntar a su marido. ¿Qué le dices?",options:['"Take a photo of it and show him tonight, then decide together"','"Ring him right now and put him on speaker — I will talk him round myself"',`"Ladies' business, my darling. He is not thinking about your face."`,'"Fair enough — go and find him, I will still be here later"'],optionsEs:['"Hazle una foto y se la enseñas esta noche, y lo decidís juntos"','"Llámalo ahora mismo y ponlo en manos libres — ya lo convenzo yo"','"Cosa de chicas, cariño. Él no está pensando en tu cara."','"Muy bien — ve a buscarlo, yo sigo aquí luego"'],correctIndex:2,explanation:"He is playing golf. She already said she likes it and she would use it, so it is her call — and you put it back in her hands while she is still in front of you.",explanationEs:"Él está jugando al golf. Ya ha dicho que le gusta y que lo usaría, así que lo decide ella — y se lo devuelves mientras la tienes delante."},{question:'Why does that answer end with "if you really would not use it, keep your money"?',questionEs:'¿Por qué esa respuesta acaba con "si de verdad no lo fueras a usar, guárdate el dinero"?',options:["It softens the pitch so she does not feel pushed at all","Being willing to walk away from her money is what closes it","It gives her a polite way out so she can think it over","It covers the shop in case she changes her mind on the way home"],optionsEs:["Suaviza el discurso para que no se sienta presionada","Estar dispuesto a renunciar a su dinero es lo que cierra","Le da una salida educada para que se lo pueda pensar","Cubre a la tienda por si cambia de idea de camino a casa"],correctIndex:1,explanation:"It is not a softener bolted on the end. A seller who is genuinely fine either way is the only one she believes.",explanationEs:"No es un caramelito pegado al final. Al vendedor al que de verdad le da igual es al único al que se cree."},{question:"She likes it, she would use it, and now she is worrying about her partner. What is left for her to object to?",questionEs:"Le gusta, lo usaría, y ahora se preocupa por su pareja. ¿Qué le queda por objetar?",options:["Whether the product really works on her kind of skin","Whether she trusts you enough to hand over a card","Whether her partner is going to approve of the spend when she gets home","The price, and nothing else — the two yeses closed the rest"],optionsEs:["Si el producto funciona de verdad en su tipo de piel","Si se fía de ti lo suficiente como para darte la tarjeta","Si su pareja va a dar el visto bueno al gasto cuando llegue a casa","El precio y nada más — los dos síes cerraron todo lo demás"],correctIndex:3,explanation:"That is what the two yeses are for. Once she has said them she can only argue about the number, so treat the partner line as a price conversation.",explanationEs:"Para eso están los dos síes. Una vez dichos, solo puede discutir el número, así que trata lo de la pareja como una conversación de precio."}]},O4:{id:"O4",categoryId:"objections",title:"I Was Scammed Before",titleEs:"Ya Me Estafaron Antes",subtitle:"Rebuilding trust brick by brick with skeptical customers",subtitleEs:"Reconstruyendo confianza poco a poco con clientes escépticos",duration:"5 min",icon:"Shield",order:4,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"This is the hardest objection because it has NOTHING to do with you. Someone else broke their trust, and now you're standing in the wreckage. You can't argue someone out of trauma. You have to patiently prove you're different — without being defensive.",textEs:"Esta es la objeción más difícil porque NO tiene NADA que ver contigo. Alguien más rompió su confianza, y ahora estás parado en los escombros. No puedes argumentar a alguien fuera de un trauma. Tienes que probar pacientemente que eres diferente — sin ponerte a la defensiva."},{type:"subheader",text:'The Psychology Behind "I Was Scammed"',textEs:'La Psicología Detrás de "Ya Me Estafaron"'},{type:"bullets",items:[`Betrayal Trauma: Being scammed creates a lasting wound. Their brain now triggers "danger" signals at ANY sales situation. You're not just selling — you're doing trust therapy.`,"Hypervigilance: They'll look for ANY sign that confirms you're a scammer. Eye contact, tone, body language — everything is being judged.","Control Need: They need to feel in control of the interaction. Let them lead the pace. No pressure = no threat."],itemsEs:['Trauma de Traición: Ser estafado crea una herida duradera. Su cerebro ahora dispara señales de "peligro" en CUALQUIER situación de venta. No solo estás vendiendo — estás haciendo terapia de confianza.',"Hipervigilancia: Buscarán CUALQUIER señal que confirme que eres estafador. Contacto visual, tono, lenguaje corporal — todo está siendo juzgado.","Necesidad de Control: Necesitan sentir que controlan la interacción. Déjalos llevar el ritmo. Sin presión = sin amenaza."]},{type:"subheader",text:"Script 1: The Empathy-First Approach (Short)",textEs:"Guion 1: El Enfoque de Empatía Primero (Corto)"},{type:"script",text:`YOU: "I am SO sorry that happened to you. There are some bad people out there, and it makes my job harder because guys like that ruin it for everyone. Look — I won't ask you to trust me. Let me just show you how this works, and YOU decide. No pressure, no strings."`,textEs:'TÚ: "Siento MUCHO que te haya pasado eso. Hay gente mala ahí afuera, y me hace el trabajo más difícil porque tipos como ese lo arruinan para todos. Mira — no te voy a pedir que confíes en mí. Déjame solo mostrarte cómo funciona esto, y TÚ decides. Sin presión, sin compromiso."'},{type:"subheader",text:"Script 2: The Transparency Builder (Medium)",textEs:"Guion 2: El Constructor de Transparencia (Medio)"},{type:"script",text:`YOU: "I completely understand — you don't know me from a hole in the wall. Here's what I'll do: I'll demo the product on MYSELF first. You watch. Then if you want, I'll do a tiny patch on your hand — not even your face — so you can see the ingredients, feel the texture, and walk away if you don't like it. Zero commitment. I'm not even going to ask you to buy anything. I just want to show you something cool. Deal?"`,textEs:'TÚ: "Lo entiendo perfectamente — no me conoces de nada. Esto es lo que haré: primero haré la demo EN MÍ MISMO. Tú observas. Luego si quieres, haré un parche chiquito en tu mano — ni siquiera en tu cara — para que veas los ingredientes, sientas la textura, y te vayas si no te gusta. Cero compromiso. Ni siquiera te voy a pedir que compres algo. Solo quiero mostrarte algo cool. ¿Trato?"'},{type:"subheader",text:"Script 3: The Full Trust Rebuild (Detailed)",textEs:"Guion 3: La Reconstrucción Completa de Confianza (Detallado)"},{type:"script",text:`YOU: "Listen — I can see it in your eyes. Someone burned you. And I want you to know that I respect that you're still standing here, still listening, even after that happened. That takes guts." [Pause, make eye contact] "I'm going to be totally transparent with you. We're a registered company — we have a store, we have a website, we have reviews on Google. You can look us up right now on your phone if you want. I'll wait." [Let them check if they want] "But even better than that — let me show you the ingredient list." [Show the packaging] "See? Every ingredient listed. Nothing hidden. No secrets. This is hyaluronic acid — it's in every luxury skincare product in the world. The same stuff in {currency}500 La Mer creams. We just don't charge for the fancy bottle." [Do the demo on yourself] "Look — my wrinkle, right there. 60 seconds. Gone. Now, I want you to touch my face." [Let them touch] "Feel that? No residue, no stickiness, no makeup. Just skin. That's it. Now — if you want me to try a little on your hand, I'll do it. If you want to walk away with just the knowledge that you found something real today, that's fine too. But I want you to leave here knowing that not everyone is out to get you. Some of us actually love what we do."`,textEs:'TÚ: "Mira — lo puedo ver en tus ojos. Alguien te quemó. Y quiero que sepas que respeto que todavía estés aquí parado, todavía escuchando, incluso después de que eso pasó. Eso requiere valor." [Pausa, haz contacto visual] "Voy a ser totalmente transparente contigo. Somos una empresa registrada — tenemos tienda, tenemos sitio web, tenemos reseñas en Google. Puedes buscarnos ahora mismo en tu móvil si quieres. Espero." [Déjalos comprobar si quieren] "Pero aún mejor que eso — déjame mostrarte la lista de ingredientes." [Muestra el envase] "¿Ves? Cada ingrediente listado. Nada escondido. Sin secretos. Esto es ácido hialurónico — está en todos los productos de lujo para el cuidado de la piel del mundo. Lo mismo que en las cremas La Mer de {currency}500. Solo que nosotros no cobramos por el frasco bonito." [Haz la demo en ti mismo] "Mira — mi arruga, ahí mismo. 60 segundos. Desapareció. Ahora, quiero que toques mi cara." [Déjalos tocar] "¿Sientes? Sin residuo, sin pegajosidad, sin maquillaje. Solo piel. Eso es todo. Ahora — si quieres que pruebe un poquito en tu mano, lo haré. Si quieres irte con solo el conocimiento de que encontraste algo real hoy, está bien también. Pero quiero que salgas de aquí sabiendo que no todos están tratando de joderte. A algunos de nosotros nos encanta lo que hacemos."'},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Be defensive: "I'm not a scammer!" — This actually makes you sound MORE like one.`,"Rush them: Pressure triggers their trauma response. They'll shut down.",'Dismiss their experience: "That was different, this is real" — invalidates their pain.',"Ask for the sale too early: They need more time than a normal customer — a lot more. Patience wins."],itemsEs:['Ponerte a la defensiva: "¡No soy un estafador!" — Esto de hecho te hace sonar MÁS como uno.',"Apurarlos: La presión activa su respuesta de trauma. Se cerrarán.",'Menospreciar su experiencia: "Eso fue diferente, esto es real" — invalida su dolor.',"Pedir la venta demasiado pronto: Necesitan más tiempo que un cliente normal — bastante más. La paciencia gana."]},{type:"tip",text:"The hand-demo technique is CRITICAL with scammed customers. Offering to demo on their hand — not their face — gives them complete control. They can wash it off. They can walk away. That feeling of control is what rebuilds trust. Also, always have Google reviews pulled up on your phone. Real reviews from real people are worth 1,000 words.",textEs:"La técnica de demo en la mano es CRÍTICA con clientes estafados. Ofrecer hacer la demo en su mano — no en su cara — les da control completo. Se la pueden lavar. Se pueden ir. Esa sensación de control es lo que reconstruye confianza. Además, siempre ten las reseñas de Google abiertas en tu móvil. Reseñas reales de gente real valen más que mil palabras."}],quiz:[{question:"A man tells you he got done by a seller on a street like this one. What is the first move?",questionEs:"Un hombre te cuenta que un vendedor de una calle como esta le timó. ¿Cuál es la primera jugada?",options:["Demo it on your own hand and let him just watch",'"I am not a scammer — look me in the eye and you will see"','"That will have been a different product, this one is the real thing"',"Get to the price quickly so he can see you are hiding nothing at all"],optionsEs:["Haz la demo en tu propia mano y que él solo mire",'"No soy un estafador — mírame a los ojos y lo verás"','"Eso sería otro producto, este es el auténtico de verdad"',"Ve rápido al precio para que vea que no escondes absolutamente nada"],correctIndex:0,explanation:"You cannot argue somebody out of being burned. Take the risk off him completely and let him watch until he wants to join in.",explanationEs:"A nadie se le quita a base de argumentos el haberse quemado. Quítale el riesgo del todo y déjalo mirar hasta que quiera meterse."},{question:"He is still standing there but he will not let you near his face. What do you offer him?",questionEs:"Sigue ahí de pie pero no te deja acercarte a su cara. ¿Qué le ofreces?",options:["The full three-minute routine on his face, done very slowly","A leaflet with the ingredients so he can read it later on","A tiny patch on the back of his hand — he can wash it off","Your phone with the reviews on it, then leave him alone to read them"],optionsEs:["La rutina entera de tres minutos en la cara, muy despacio","Un folleto con los ingredientes para que lo lea más tarde","Una pizca en el dorso de la mano — se la puede lavar","El móvil con las reseñas y lo dejas solo para que las lea"],correctIndex:2,explanation:"The hand is his, not yours. Being able to wash it off is the whole point — control is what rebuilds the trust somebody else broke.",explanationEs:"La mano es suya, no tuya. Que se lo pueda lavar es justo lo importante — el control es lo que reconstruye la confianza que le rompió otro."},{question:"Which line makes you sound MORE like the seller who ripped him off?",questionEs:"¿Qué frase hace que suenes MÁS como el vendedor que le timó?",options:['"Have a look at the ingredients — every one of them is on the box"','"I am not a scammer, I promise you"','"I will do it on myself first, you just watch"','"You do not have to trust me — decide when you have seen it"'],optionsEs:['"Mira los ingredientes — están todos escritos en la caja"','"No soy un estafador, te lo prometo"','"Primero me lo hago a mí, tú solo mira"','"No tienes que fiarte de mí — decides cuando lo hayas visto"'],correctIndex:1,explanation:"Defending yourself is what a guilty man does. Show him instead, and let him decide with his own eyes.",explanationEs:"Defenderse es lo que hace el culpable. Enséñaselo y que decida con sus propios ojos."}]},O5:{id:"O5",categoryId:"objections",title:"Will This Work on Dark Skin?",titleEs:"¿Esto Funciona en Piel Morena/Oscura?",subtitle:"Addressing inclusive beauty concerns with science and respect",subtitleEs:"Abordando preocupaciones de belleza inclusiva con ciencia y respeto",duration:"4 min",icon:"Palette",order:5,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"This question comes from a real place — the beauty industry has historically ignored darker skin tones. Your customer isn't being difficult; they're protecting themselves from another disappointment. Answer with SCIENCE, not just reassurance.",textEs:"Esta pregunta viene de un lugar real — la industria de la belleza históricamente ha ignorado los tonos de piel más oscuros. Tu cliente no está siendo difícil; se está protegiendo de otra decepción. Responde con CIENCIA, no solo con tranquilidad."},{type:"subheader",text:"The Science: Why It Works on ALL Skin Tones",textEs:"La Ciencia: Por Qué Funciona en TODOS los Tonos de Piel"},{type:"bullets",items:["Hyaluronic Acid is a molecule, not a bleach: It doesn't change skin color. It binds to water molecules in your skin, plumping from the inside. It works the same on ALL skin types because water retention is universal.","Dead Sea minerals contain magnesium, potassium, calcium: These are minerals your skin NEEDS regardless of melanin levels. Darker skin actually often shows MORE dramatic results because the contrast between hydrated and dehydrated skin is more visible.","Glycolic acid exfoliates the top layer of dead skin: This works the same on all skin tones. It's not a skin lightener — it's a cell turnover accelerator."],itemsEs:["El Ácido Hialurónico es una molécula, no un blanqueador: No cambia el color de la piel. Se une a las moléculas de agua en tu piel, rellenando desde adentro. Funciona igual en TODOS los tipos de piel porque la retención de agua es universal.","Los minerales del Mar Muerto contienen magnesio, potasio, calcio: Son minerales que tu piel NECESITA sin importar los niveles de melanina. La piel morena de hecho a menudo muestra resultados MÁS dramáticos porque el contraste entre piel hidratada y deshidratada es más visible.","El ácido glicólico exfolia la capa superior de piel muerta: Funciona igual en todos los tonos de piel. No es un aclarador de piel — es un acelerador de renovación móvil."]},{type:"subheader",text:"Script 1: The Science Answer (Short)",textEs:"Guion 1: La Respuesta Científica (Corto)"},{type:"script",text:`YOU: "Great question! This is hyaluronic acid — it's a water molecule, not a bleach. It doesn't care about skin color. It works by binding water under your skin. Your melanin stays exactly the same. You just get smoother, plumper skin. Want me to show you on my hand?"`,textEs:'TÚ: "¡Excelente pregunta! Esto es ácido hialurónico — es una molécula de agua, no un blanqueador. No le importa el color de piel. Funciona uniendo agua debajo de tu piel. Tu melanina se queda exactamente igual. Solo te queda piel más suave y llena. ¿Quieres que te muestre en mi mano?"'},{type:"subheader",text:"Script 2: The Ingredient Education (Medium)",textEs:"Guion 2: La Educación de Ingredientes (Medio)"},{type:"script",text:`YOU: "I love that you asked that — it shows you know your skin. Let me break this down: our main ingredient is hyaluronic acid. It's literally already IN your body — in your joints, your eyes, your skin. All skin tones have it. What we do is add more of it topically so your skin holds more water. The result? Plumper, smoother skin — but your color doesn't change at all. In fact, a lot of our clients with darker skin say they see BETTER results because the glow is so visible. Here, let me show you the ingredient list — see? No hydroquinone, no bleach, nothing that changes pigmentation."`,textEs:'TÚ: "Me encanta que hayas preguntado eso — muestra que conoces tu piel. Déjame explicarte: nuestro ingrediente principal es ácido hialurónico. Literalmente ya está EN tu cuerpo — en tus articulaciones, tus ojos, tu piel. Todos los tonos de piel lo tienen. Lo que hacemos es agregar más tópicamente para que tu piel retenga más agua. ¿El resultado? Piel más llena y suave — pero tu color no cambia para nada. De hecho, muchos de nuestros clientes con piel morena dicen que ven MEJORES resultados porque el brillo es muy visible. Mira, déjame mostrarte la lista de ingredientes — ¿ves? Sin hidroquinona, sin blanqueador, nada que cambie la pigmentación."'},{type:"subheader",text:"Script 3: The Full Education + Demo (Detailed)",textEs:"Guion 3: La Educación Completa + Demo (Detallado)"},{type:"script",text:`YOU: "Listen, I totally get why you're asking. The beauty industry hasn't always served darker skin well, and that's a real problem. But I'm going to explain the science so you can make an informed decision." [Pull out the product] "This is the Hyaluronic Syringe. The active ingredient is hyaluronic acid — it's a sugar molecule that holds 1,000 times its weight in water. It doesn't interact with melanin AT ALL. Think about it this way: when you're dehydrated, your skin looks ashy, right? That's true for EVERY skin tone. When you rehydrate, that ashiness goes away and your natural glow comes back. That's ALL this does — extreme hydration." [Do a hand demo] "Look at my hand — no makeup, nothing. Watch this." [Apply, wait] "See how the skin looks plumper? That's water, not bleach. Your melanin is still there, your color is still beautiful — you're just adding hydration on top. Now here's the thing — darker skin actually shows results MORE dramatically because the contrast between dry skin and hydrated skin is more visible. The glow you get? Stunning. Here, feel it — no residue, no stickiness, no white cast. Just hydrated skin. So the real question isn't 'will it work on dark skin' — the question is 'how amazing will YOUR skin look when it's fully hydrated?' Let's find out?"`,textEs:`TÚ: "Mira, totalmente entiendo por qué preguntas. La industria de la belleza no siempre ha atendido bien a la piel morena, y eso es un problema real. Pero te voy a explicar la ciencia para que tomes una decisión informada." [Saca el producto] "Esta es la Jeringa Hialurónica. El ingrediente activo es ácido hialurónico — es una molécula de azúcar que retiene 1,000 veces su peso en agua. No interactúa con la melanina PARA NADA. Piénsalo así: cuando estás deshidratado, tu piel se ve opaca, ¿verdad? Eso es cierto para TODOS los tonos de piel. Cuando te rehidratas, esa opacidad se va y tu brillo natural vuelve. Eso es TODO lo que hace — hidratación extrema." [Haz demo en mano] "Mira mi mano — sin maquillaje, nada. Mira esto." [Aplica, espera] "¿Ves cómo la piel se ve más llena? Eso es agua, no blanqueador. Tu melanina sigue ahí, tu color sigue hermoso — solo estás agregando hidratación encima. Ahora, aquí está el punto — la piel morena de hecho muestra resultados MÁS dramáticos porque el contraste entre piel seca e hidratada es más visible. ¿El brillo que obtienes? Impresionante. Toca aquí — sin residuo, sin pegajosidad, sin capa blanca. Solo piel hidratada. Entonces la pregunta real no es 'funcionará en piel morena' — la pregunta es '¿qué tan increíble se verá TU piel cuando esté completamente hidratada?' ¿Descubrimos?"`},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Dismiss the question: "It works on everyone, don't worry" — This sounds like you don't understand their concern.`,"Pretend all skin is the same: Acknowledge that their question is valid and rooted in real industry history.","Show only white customer photos: Have diverse before/afters ready on your phone.",`Use medical/dermatologist claims unless true: Stay within your knowledge. Say "I've seen" not "Science proves."`],itemsEs:['Menospreciar la pregunta: "Funciona en todos, no te preocupes" — Suena como si no entendieras su preocupación.',"Pretender que toda la piel es igual: Reconoce que su pregunta es válida y tiene raíces en la historia real de la industria.","Mostrar solo fotos de clientes blancos: Ten fotos de antes/después diversas listas en tu móvil.",'Usar afirmaciones médicas/dermatológicas a menos que sean ciertas: Quédate dentro de tu conocimiento. Di "he visto" no "la ciencia prueba."']},{type:"tip",text:`Keep 3-4 before/after photos of dark-skinned clients on your phone (with permission). Nothing you say does the job a photo does — she can see it, so she does not have to take your word for anything. Also, if YOU have darker skin, demo on YOURSELF. Nothing beats seeing it work on someone who looks like you. If you don't, be honest: "I hear you — my skin's different. Let me show you on your hand so YOU can be the judge."`,textEs:'Guarda 3-4 fotos de antes/después de clientes de piel morena en tu móvil (con permiso). Nada de lo que digas hace lo que hace una foto — lo ve ella, así que no tiene que fiarse de tu palabra. Además, si TÚ tienes piel morena, haz la demo en TI MISMO. Nada supera verlo funcionar en alguien que se parece a ti. Si no, sé honesto: "Te entiendo — mi piel es diferente. Déjame mostrarte en tu mano para que TÚ seas el juez."'}],quiz:[{question:"A woman with deep brown skin asks whether it will do anything for her. What do you lead with?",questionEs:"Una mujer de piel morena oscura te pregunta si esto le va a hacer algo. ¿Por dónde empiezas?",options:['"It works on everyone, do not worry about that"','"You have got beautiful skin, you hardly need it"','"Honestly it is the same for everybody — skin is skin at the end of the day"','"Good question. It is water, not a bleach. Give me your hand."'],optionsEs:['"Funciona en todo el mundo, no te preocupes por eso"','"Tienes una piel preciosa, casi no te hace falta"','"De verdad, es igual para todas — la piel es la piel, al final"','"Buena pregunta. Es agua, no un blanqueador. Dame la mano."'],correctIndex:3,explanation:"Her question is real and it deserves a real answer, and then a hand. Hyaluronic acid binds water — it does not touch her colour.",explanationEs:"Su pregunta es de verdad y merece una respuesta de verdad, y luego la mano. El ácido hialurónico une agua — no le toca el color."},{question:"Why does that question deserve a proper answer instead of a quick reassurance?",questionEs:'¿Por qué esa pregunta merece una respuesta de verdad y no un "tranquila" rápido?',options:["She is protecting herself from being let down again","She is testing whether you know the ingredient list","She is opening the haggle and this is her first move","She wants to hear the word melanin before she will trust you"],optionsEs:["Se está protegiendo de que la vuelvan a decepcionar","Te está poniendo a prueba con la lista de ingredientes","Está abriendo el regateo y esta es su primera jugada",'Quiere oírte decir "melanina" antes de fiarse de ti'],correctIndex:0,explanation:"The industry has let her down before and she is bracing for it again. Waving the question away tells her you did not even hear it.",explanationEs:"El sector ya la ha decepcionado antes y viene preparada para que se repita. Quitarle importancia le dice que ni la has escuchado."},{question:"You have no before-and-after photos of darker skin on your phone. What do you do?",questionEs:"No tienes fotos de antes y después de piel morena en el móvil. ¿Qué haces?",options:["Show the ones you have got and hope she does not notice","Tell her you have seen it work on hundreds of women like her",'"My skin is not yours — let me do your hand, you be the judge"',"Go through the science again, in more detail, until she is happy"],optionsEs:["Enseñar las que tienes y esperar que no se dé cuenta","Decirle que lo has visto funcionar en cientos de mujeres así",'"Mi piel no es la tuya — te hago la mano y juzgas tú"',"Repetir la explicación científica con más detalle hasta que se quede a gusto"],correctIndex:2,explanation:"Honesty plus her own hand beats any photo you could show her. She judges it on her own skin, which is what she was asking for.",explanationEs:"La honestidad y su propia mano ganan a cualquier foto que le enseñes. Lo juzga en su piel, que es justo lo que estaba pidiendo."}]},O6:{id:"O6",categoryId:"objections",title:"Do You Test on Animals?",titleEs:"¿Prueban en Animales?",subtitle:"Turning ethical concerns into brand loyalty through transparency",subtitleEs:"Convirtiendo preocupaciones éticas en lealtad a la marca a través de la transparencia",duration:"3 min",icon:"Leaf",order:6,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"This isn't an objection — it's an OPPORTUNITY. Someone who cares about cruelty-free products is someone who will pay premium prices for ethical brands. They're pre-qualified buyers. Answer with pride, not defensiveness.",textEs:"Esto no es una objeción — es una OPORTUNIDAD. Alguien que le importa los productos libres de crueldad es alguien que pagará precios premium por marcas éticas. Son compradores pre-calificados. Responde con orgullo, no a la defensiva."},{type:"subheader",text:"The Psychology Behind the Animal Testing Question",textEs:"La Psicología Detrás de la Pregunta de Pruebas en Animales"},{type:"bullets",items:["Values-Based Purchasing: These customers vote with their wallet. They're not price-shopping; they're values-shopping. Win on ethics, and price becomes secondary.","Information Gap: Most people WANT to believe but have been lied to before. They need PROOF, not promises.","Identity Connection: Cruelty-free buyers see their purchases as an extension of their identity. Align with that identity and you become THEIR brand."],itemsEs:["Compra Basada en Valores: Estos clientes votan con su cartera. No buscan precio; buscan valores. Gana en ética, y el precio se vuelve secundario.","Brecha de Información: La mayoría QUIERE creer pero les han mentido antes. Necesitan PRUEBAS, no promesas.","Conexión de Identidad: Los compradores libres de crueldad ven sus compras como extensión de su identidad. Alíneate con esa identidad y te conviertes en SU marca."]},{type:"subheader",text:"Script 1: The Confident Confirmation (Short)",textEs:"Guion 1: La Confirmación Confidente (Corto)"},{type:"script",text:`YOU: "NO. And I'm proud of that. We're certified cruelty-free — Leaping Bunny approved. Nothing on animals, ever. Clean ingredients, real results. That's the whole brand story."`,textEs:'TÚ: "NO. Y estoy orgullosa de eso. Estamos certificados libres de crueldad — aprobados por Leaping Bunny. Nada en animales, nunca. Ingredientes limpios, resultados reales. Esa es toda la historia de la marca."'},{type:"subheader",text:"Script 2: The Brand Story (Medium)",textEs:"Guion 2: La Historia de la Marca (Medio)"},{type:"script",text:`YOU: "Absolutely not — and that was one of the reasons I chose to work with this brand. Look, here's our certification." [Show on phone/packaging] "We're Leaping Bunny certified, which means NO animal testing at ANY stage — not on ingredients, not on finished products, not in countries that require it. The whole line is vegan except for one product that has honey extract, and that's clearly labeled. Every ingredient comes from plant or mineral sources. We're basically selling you the Mediterranean in a bottle — no harm done."`,textEs:'TÚ: "Absolutamente no — y esa fue una de las razones por las que elegí trabajar con esta marca. Mira, aquí está nuestra certificación." [Muestra en móvil/envase] "Estamos certificados por Leaping Bunny, lo que significa NINGUNA prueba en animales en NINGUNA etapa — ni en ingredientes, ni en productos terminados, ni en países que lo requieren. Toda la línea es vegana excepto un producto que tiene extracto de miel, y está claramente etiquetado. Cada ingrediente viene de fuentes vegetales o minerales. Básicamente te estamos vendiendo el Mediterráneo en una botella — sin daño causado."'},{type:"subheader",text:"Script 3: The Full Ethical Framework (Detailed)",textEs:"Guion 3: El Marco Ético Completo (Detallado)"},{type:"script",text:`YOU: "I'm SO glad you asked. Hardly anybody does — the ones who do are my people." [Get the phone out, certification up on the screen] "No. Never. Look — there it is, Leaping Bunny, that's the one people fake. Nothing on animals at any stage. I wouldn't be standing here selling it otherwise." [Put the scrub in their hand] "Now let me tell you about this one, because I genuinely love it. That salt comes straight out of the Dead Sea. Not a version of it, not something dreamed up in a lab — scooped out of the sea and put in a jar. And the peeling? The acid in it comes out of sugar cane. That's the whole story, that's it." [Pause, look at them] "You're going to feel it in about ten seconds, and that's the bit I enjoy. Give me your hand."`,textEs:'TÚ: "Me ALEGRA que lo preguntes. Casi nadie lo pregunta — y quien lo pregunta es de los míos." [Saca el móvil, la certificación en pantalla] "No. Nunca. Mira — ahí lo tienes, Leaping Bunny, que es justo la que se inventa la gente. Nada en animales en ninguna fase. Si no, yo no estaría aquí vendiéndolo." [Ponle el exfoliante en la mano] "Y ahora te cuento este, porque a mí me encanta de verdad. Esa sal sale directa del Mar Muerto. No es una versión, no es algo inventado en un laboratorio — la sacan del mar y la meten en el bote. ¿Y el peeling? El ácido sale de la caña de azúcar. Esa es toda la historia, ya está." [Pausa, mírala] "Lo vas a notar en unos diez segundos, y esa es la parte que me gusta a mí. Dame la mano."'},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Say "I think so" or "I'm pretty sure": Either you KNOW or you DON'T. Guesswork kills credibility.`,'Get defensive: "Well, every company does some testing" — NO. Own your ethics proudly.',`Fake certifications: If you don't have Leaping Bunny, don't claim it. Say "We don't test on animals" instead.`,"Rush past the question: This customer CARES. Spend time on this — it builds loyalty."],itemsEs:['Decir "Creo que sí" o "Estoy bastante seguro": O SABES o NO SABES. Las suposiciones matan la credibilidad.','Ponerte a la defensiva: "Bueno, todas las empresas hacen algunas pruebas" — NO. Apropia tus éticas con orgullo.','Fingir certificaciones: Si no tienes Leaping Bunny, no lo alegues. Di "No hacemos pruebas en animales" en su lugar.',"Pasar rápido la pregunta: Este cliente le IMPORTA. Tómate tiempo en esto — construye lealtad."]},{type:"tip",text:"Download the Leaping Bunny app on your phone and show it in real-time. Nothing beats live verification. Also, learn ONE ingredient story per product — where it comes from, what it does, why it's better than synthetic alternatives. When you can tell the story of Dead Sea minerals or sugar cane glycolic acid with a bit of love, you stop sounding like someone reading the back of the box.",textEs:"Descarga la app de Leaping Bunny en tu móvil y muéstrala en tiempo real. Nada supera la verificación en vivo. Además, aprende UNA historia de ingrediente por producto — de dónde viene, qué hace, por qué es mejor que alternativas sintéticas. Cuando cuentas la historia de los minerales del Mar Muerto o del ácido glicólico de la caña de azúcar con un poco de cariño, dejas de sonar a alguien leyendo la parte de atrás de la caja."}],quiz:[{question:"She asks whether you test on animals. What is standing in front of you?",questionEs:"Te pregunta si probáis en animales. ¿Qué tienes delante?",options:["An objection you have to get past before you can sell","A pre-qualified buyer telling you what she cares about","A polite way of saying she is not going to buy anything","A trap — whatever you answer she will find a reason to walk off"],optionsEs:["Una objeción que hay que superar antes de poder vender","Una compradora ya cualificada diciéndote qué le importa","Una forma educada de decirte que no va a comprar nada","Una trampa — contestes lo que contestes, encontrará motivo para irse"],correctIndex:1,explanation:"People who buy on values do not price-shop. Answer this one properly and the price stops being the conversation.",explanationEs:"Quien compra por valores no anda mirando el precio. Contesta bien esta y el precio deja de ser la conversación."},{question:"You are not sure whether the brand really holds the certification she just named. What do you say?",questionEs:"No estás seguro de si la marca tiene de verdad la certificación que acaba de nombrar. ¿Qué dices?",options:['"I think so, yes — pretty sure we have got that one"','"Every company does a bit of testing somewhere, if we are honest about it"','"Yes, we have got all of them, do not you worry about that"','"We do not test on animals." Say the part you actually know.'],optionsEs:['"Creo que sí, bastante seguro de que tenemos esa"','"Todas las empresas prueban algo en algún sitio, si somos sinceros"','"Sí, las tenemos todas, no te preocupes por eso"','"Nosotros no probamos en animales." Di solo lo que sabes seguro.'],correctIndex:3,explanation:"Either you know or you do not. Guessing at a certificate in front of somebody who cares about it is the fastest way to lose her.",explanationEs:"O lo sabes o no lo sabes. Inventarte un certificado delante de quien le importa es la forma más rápida de perderla."},{question:"She cares about this and she has got time. How long do you spend on the answer?",questionEs:"A ella le importa y tiene tiempo. ¿Cuánto le dedicas a la respuesta?",options:["As long as she wants — this is the buyer who pays on values","Thirty seconds, then straight to the demo before you lose her","Just enough to answer it, then move her on to the price","Skip it and get her hand on the table — the feeling sells it anyway"],optionsEs:["Lo que ella quiera — esta es la que paga por valores","Treinta segundos y directo a la demo antes de perderla","Lo justo para contestar y llevarla enseguida al precio","Sáltatelo y ponle la mano en la mesa — la sensación vende sola"],correctIndex:0,explanation:"Rushing past it tells her you do not really care. Time spent here is the cheapest loyalty you will ever buy.",explanationEs:"Pasar de puntillas le dice que en realidad te da igual. El rato que gastas aquí es la fidelidad más barata que vas a comprar."}]},O7:{id:"O7",categoryId:"objections",title:"I Can Get This Cheaper on Amazon",titleEs:"En Amazon Está Más Barato",subtitle:"Turning price comparisons into trust and value conversations",subtitleEs:"Convirtiendo comparaciones de precio en conversaciones de confianza y valor",duration:"4 min",icon:"ShoppingCart",order:7,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"Amazon is the #1 objection tool for modern customers. But here's what they DON'T know: Amazon is flooded with counterfeit cosmetics, expired products, and diluted formulas. Your advantage isn't just price — it's authenticity, instant gratification, and the demo itself.",textEs:"Amazon es la herramienta de objeción #1 para clientes modernos. Pero esto es lo que NO saben: Amazon está inundado de cosméticos falsificados, productos vencidos, y fórmulas diluidas. Tu ventaja no es solo el precio — es autenticidad, gratificación instantánea, y la demo misma."},{type:"keypoint",text:"And know where you are standing before you answer. She almost never says this at your opening number — by the time the phone comes out you have usually walked her down a rung or two. Once you are at {currency}175, and certainly once your voucher is on it at {currency}140, you are not defending a higher price at all. You are the cheaper one, and the whole argument stops being an apology and turns into a win. Never quote her a number off a website you cannot see. Let her read her own screen out loud, then put yours next to it.",textEs:"Y mira dónde estás antes de contestar. Casi nunca te suelta esto con tu primer número — cuando sale el móvil, normalmente ya la has bajado un escalón o dos. En cuanto estás en {currency}175, y no digamos con el cupón puesto en {currency}140, no estás defendiendo un precio más alto: el barato eres tú, y todo el argumento deja de ser una disculpa y pasa a ser una victoria. No le cites nunca un número de una web que no estás viendo. Que lea ella su propia pantalla en voz alta, y tú pones el tuyo al lado."},{type:"subheader",text:"The Psychology Behind the Amazon Objection",textEs:"La Psicología Detrás de la Objeción de Amazon"},{type:"bullets",items:['Price Anchoring: Amazon = "cheap" in their mind. You need to re-anchor around VALUE and SAFETY.',"Comparison Shopping Habit: Everyone checks Amazon reflexively. It's not personal — it's muscle memory.","Risk Blindness: They see the price but not the counterfeit risk, the shipping wait, the inability to try before buying."],itemsEs:['Anclaje de Precio: Amazon = "barato" en su mente. Necesitas re-anclar alrededor de VALOR y SEGURIDAD.',"Hábito de Comparar: Todos revisan Amazon reflejamente. No es personal — es memoria muscular.","Ceguera al Riesgo: Ven el precio pero no el riesgo de falsificación, la espera de envío, la imposibilidad de probar antes de comprar."]},{type:"subheader",text:"Script 1: The Counterfeit Reality (Short)",textEs:"Guion 1: La Realidad de las Falsificaciones (Corto)"},{type:"script",text:`YOU: "Maybe — but here's the thing about Amazon skincare. The place is full of fakes. That 'deal' you find? Probably fake, expired, or diluted. This?" [Hold up sealed product] "Sealed, fresh, straight from the manufacturer. And you just watched it work on your own face. Can Amazon do that?"`,textEs:`TÚ: "Tal vez — pero esto es lo del skincare en Amazon. Aquello está lleno de falsificaciones. ¿Esa 'ganga' que encuentras? Probablemente falsa, vencida, o diluida. ¿Esto?" [Levanta producto sellado] "Sellado, fresco, directo del fabricante. Y acabas de verlo funcionar en tu propia cara. ¿Amazon puede hacer eso?"`},{type:"subheader",text:"Script 2: The Total Cost Analysis (Medium)",textEs:"Guion 2: El Análisis de Costo Total (Medio)"},{type:"script",text:'YOU: "Go on then, show me. What does your screen say?" [Look at it with her. Genuinely interested, no panic — never invent a number for a website she is holding in her hand] "Right. Now add the shipping. Add the week you sit waiting. Add the bit where you open the box and hope it is the real one. And here is what your screen cannot see: I am not at the price on my box either." [Voice down, lean in] "I have already taken the gift off for you — you are at {currency}175 with me. Sealed, fresh, in your bag, and you have already felt it on your own face. So have another look at that screen and tell me who is actually cheaper."',textEs:'TÚ: "Venga, enséñamelo. ¿Qué pone en tu pantalla?" [Míralo con ella. Con interés de verdad, sin ponerte nervioso — nunca te inventes un número de una web que ella tiene en la mano] "Vale. Ahora súmale el envío. Súmale la semana esperando. Y súmale el momento en que abres la caja y rezas para que sea el bueno. Y esto tu pantalla no lo ve: yo tampoco estoy al precio de mi caja." [Baja la voz, acércate] "Ya te he quitado el regalo — conmigo estás en {currency}175. Sellada, fresca, en tu bolsa, y ya la has notado en tu propia cara. Así que vuelve a mirar esa pantalla y dime quién es más barato de verdad."'},{type:"subheader",text:"Script 3: The Experience Reframe (Detailed)",textEs:"Guion 3: La Reconversión de Experiencia (Detallado)"},{type:"script",text:`YOU: "Amazon, right? Everyone goes there first. But let me ask you — when you buy skincare on Amazon, what are you actually buying? A photo, a description, and a prayer. You don't know if it's been sitting in a warehouse for 18 months. You don't know if it's been exposed to heat. You don't know if it's even REAL — because fake cosmetics are everywhere now." [Pull out your phone, show news about counterfeit cosmetics if you have it] "Now look at what just happened here. I put this on your face. You FELT the texture. You SAW the wrinkle disappear in 60 seconds. You're holding the sealed box in your hands. This is a full EXPERIENCE, not a transaction. And here's what people forget: the number on that screen is not the number you pay — add the shipping, add the week, add the risk. Now look at what I am doing on this side." [Voice down, quick look at the door] "I am not even at my box price with you. Gift off, my voucher on it — {currency}140. Real. Fresh. Sealed. In your bag before you have finished your coffee." [Pause] "Listen, I'm not here to rip you off. I'm here because this product changed MY skin, and I love sharing that. But I also know that the version on Amazon isn't this version. This is the real deal, right here, right now. So — do you want to risk your face on a website, or do you want to walk out looking 10 years younger TODAY?"`,textEs:'TÚ: "Amazon, ¿verdad? Todos van ahí primero. Pero déjame preguntarte — cuando compras skincare en Amazon, ¿qué estás comprando realmente? Una foto, una descripción, y una oración. No sabes si ha estado en un almacén por 18 meses. No sabes si ha estado expuesto al calor. No sabes si siquiera es REAL — porque los cosméticos falsos están por todos lados ahora." [Saca tu móvil, muestra noticias sobre cosméticos falsificados si tienes] "Ahora mira lo que acaba de pasar aquí. Te puse esto en la cara. SENTISTE la textura. VISTE la arruga desaparecer en 60 segundos. Estás sosteniendo la caja sellada en tus manos. Esto es una EXPERIENCIA completa, no una transacción. Y esto es lo que la gente olvida: el número de esa pantalla no es lo que acabas pagando — súmale el envío, súmale la semana, súmale el riesgo. Y ahora mira lo que estoy haciendo yo de este lado." [Baja la voz, mirada rápida a la puerta] "Es que ni siquiera estoy al precio de mi caja contigo. Sin regalo, con mi cupón — {currency}140. Real. Fresca. Sellada. En tu bolsa antes de que te acabes el café." [Pausa] "Escucha, no estoy aquí para estafarte. Estoy aquí porque este producto cambió MI piel, y me encanta compartir eso. Pero también sé que la versión en Amazon no es esta versión. Este es el producto real, aquí, ahora. Entonces — ¿quieres arriesgar tu cara en un sitio web, o quieres salir viéndote 10 años más joven HOY?"'},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Trash Amazon completely: Some people love Amazon. Don't make them feel stupid for using it.","Refuse to acknowledge the price difference: Admit it exists, then reframe around value.",`Say "you can't find this on Amazon" unless it's TRUE: Lying about availability destroys trust if they check.`,"Guess what her screen says: she is holding the phone, so ask her to read it out. You cannot be caught out by a number you never invented, and often enough the one she reads out is higher than the rung you are standing on.","Let a website move you down a rung: dropping because a page loaded is the page setting your prices. You move when SHE pushes, with a reason attached, exactly like any other rung."],itemsEs:["Hablar mal de Amazon por completo: Algunos aman Amazon. No los hagas sentirse tontos por usarlo.","Negar la diferencia de precio: Admítela, luego reconvertir alrededor del valor.",'Decir "no encuentras esto en Amazon" a menos que sea CIERTO: Mentir sobre disponibilidad destruye confianza si lo comprueban.',"Adivinar lo que pone en su pantalla: el móvil lo tiene ella, así que pídele que te lo lea. Con un número que no te has inventado no te pilla nadie, y muchas veces el que lee es más alto que el escalón donde estás.","Dejar que una web te baje un escalón: bajar porque se ha cargado una página es dejar que la página te ponga los precios. Tú te mueves cuando empuja ELLA, con un motivo pegado, igual que en cualquier otro escalón."]},{type:"tip",text:`Keep a screenshot on your phone of a news article about counterfeit cosmetics on Amazon. When you pull it up and say "Look, this was last month — millions in fake skincare seized," it becomes REAL. Also, the phrase "You're not paying for the product, you're paying for knowing it's real" is your best closer — it is about what is in the box, not about anything happening after they leave.`,textEs:'Guarda una captura de pantalla en tu móvil de un artículo de noticias sobre cosméticos falsificados en Amazon. Cuando la sacas y dices "Mira, esto fue el mes pasado — millones en skincare falso decomisado," se vuelve REAL. Además, la frase "No estás pagando por el producto, estás pagando por saber que es auténtico" es tu mejor cierre — va de lo que hay en la caja, no de nada que pase después de que se vayan.'}],quiz:[{question:'"I can get this cheaper on Amazon." What do you do first?',questionEs:'"Esto en Amazon está más barato." ¿Qué haces primero?',options:["Match the price so she has no reason to go looking","Tell her the site is full of rubbish and she should not use it","Agree the gap is real, then move it back to what she just felt","Tell her this exact one is not on there — she will not check anyway"],optionsEs:["Igualar el precio para que no tenga por qué mirar","Decirle que esa web está llena de porquería y que no la use","Darle la razón en la diferencia y volver a lo que acaba de notar","Decirle que este justo no está ahí — total, no lo va a mirar"],correctIndex:2,explanation:"Denying the price gap makes you a liar in one tap of her phone. Admit it, then put the demo she just watched next to a photo on a screen.",explanationEs:"Negar la diferencia te convierte en mentiroso con un toque en su móvil. Admítela y pon la demo que acaba de ver al lado de una foto en una pantalla."},{question:"What have you got in the next two minutes that a website has not?",questionEs:"¿Qué tienes tú en los próximos dos minutos que no tiene una web?",options:["Her own face in a mirror and a sealed box in her hand","A lower price than she will find anywhere else online","A story about a customer who was sent a fake last month","Faster delivery and no shipping to pay on top of the price"],optionsEs:["Su propia cara en un espejo y una caja sellada en la mano","Un precio más bajo del que va a encontrar en internet","La historia de una clienta a la que le mandaron una falsa","Entrega más rápida y sin gastos de envío encima del precio"],correctIndex:0,explanation:"You are not competing on price and you never were. You are selling the two minutes she cannot get anywhere else.",explanationEs:"No compites en precio, y nunca competiste. Vendes los dos minutos que no consigue en ningún otro sitio."},{question:"She gets her phone out to check the price on the site, right there in front of you. What now?",questionEs:"Saca el móvil para mirar el precio en la web, ahí mismo delante de ti. ¿Y ahora?",options:["Ask her to put it away and give you one minute first","Let her look, and put the mirror in her other hand","Tell her the signal is terrible here and she should try later","Jump to your floor price before the page has finished loading"],optionsEs:["Pedirle que lo guarde y que te dé un minuto antes","Déjala mirar y ponle el espejo en la otra mano","Decirle que aquí no hay cobertura y que lo mire luego","Irte a tu precio mínimo antes de que se le cargue la página"],correctIndex:1,explanation:"Blocking the phone looks like you have something to hide. Let her look while she is holding the mirror — the mirror wins.",explanationEs:"Taparle el móvil parece que escondes algo. Déjala mirar mientras sujeta el espejo — gana el espejo."}]},O9:{id:"O9",categoryId:"objections",title:"My Friend Said No",titleEs:"Mi Amiga Dijo Que No",subtitle:"Separating social influence from personal desire",subtitleEs:"Separando la influencia social del deseo personal",duration:"4 min",icon:"Users",order:9,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"Group dynamics are tricky. When a friend says no, the interested person often shuts down — not because they don't want it, but because social harmony feels more important than personal desire. Your job is to respect the group while empowering the individual.",textEs:"Las dinámicas de grupo son complicadas. Cuando una amiga dice que no, la persona interesada a menudo se cierra — no porque no lo quiera, sino porque la armonía social se siente más importante que el deseo personal. Tu trabajo es respetar al grupo mientras empoderas al individuo."},{type:"subheader",text:'The Psychology Behind "My Friend Said No"',textEs:'La Psicología Detrás de "Mi Amiga Dijo Que No"'},{type:"bullets",items:[`Social Conformity: People match group behavior to avoid conflict. The "no" friend becomes the group's representative.`,"Fear of Judgment: Buying when a friend said no feels like defiance. They need permission to disagree.","Shared Experience Pressure: Friends who travel together often feel purchases should be mutual decisions."],itemsEs:['Conformidad Social: La gente iguala el comportamiento del grupo para evitar conflicto. La amiga que dijo "no" se convierte en representante del grupo.',"Miedo al Juicio: Comprar cuando una amiga dijo que no se siente como desafío. Necesitan permiso para discrepar.","Presión de Experiencia Compartida: Amigas que viajan juntas a menudo sienten que las compras deben ser decisiones mutuas."]},{type:"subheader",text:"Script 1: The Individual Reframe (Short)",textEs:"Guion 1: La Reconversión Individual (Corto)"},{type:"script",text:`YOU: "Totally respect that! But quick question — is she the one wearing your skin for the next 40 years?" [Pause, smile] "This is YOUR face, YOUR decision. She can skip it and that's fine. But why should YOU miss out?"`,textEs:'TÚ: "¡Totalmente lo respeto! Pero pregunta rápida — ¿es ella la que va a usar tu piel por los próximos 40 años?" [Pausa, sonríe] "Esta es TU cara, TU decisión. Ella puede pasar y está bien. ¿Pero por qué TÚ deberías perdértelo?"'},{type:"subheader",text:"Script 2: Put the Friend in the Chair (Medium)",textEs:"Guion 2: Siéntala a Ella También (Medio)"},{type:"script",text:`YOU: "I get it — you came here together, you decide together. So let's include her." [Turn to the friend, all warmth] "Come here, give me your hand — thirty seconds, on me, so you feel what she just felt. Then YOU tell her." [Do the friend's hand right there, in front of them both] "And YOU — you saw the result on your own face. Don't let somebody else's 'no' steal your 'yes.' This is between you and your mirror."`,textEs:`TÚ: "Lo entiendo — habéis venido juntas, decidís juntas. Pues la metemos." [Vuélvete hacia la amiga, con todo el cariño] "Ven aquí, dame la mano — treinta segundos, invita la casa, para que notes lo que acaba de notar ella. Y luego se lo dices TÚ." [Hazle la mano a la amiga ahí mismo, delante de las dos] "Y TÚ — has visto el resultado en tu propia cara. No dejes que el 'no' de otra te robe tu 'sí'. Esto es entre tú y tu espejo."`},{type:"subheader",text:"Script 3: The Diplomatic Separation (Detailed)",textEs:"Guion 3: La Separación Diplomática (Detallado)"},{type:"script",text:`YOU: "I totally get it — you two are a team, and I respect that. But let me ask you both something: when you go home tonight, are you going to be looking at HER face in the mirror, or YOUR face?" [Look at the interested person] "Look, she loves you — that's why she's protective. But this isn't a timeshare, it's not a scam, it's skincare. You felt it work. You saw that line disappear. That's not peer pressure, that's physics." [Turn to the friend] "And honestly? I love that you have her back. That's real friendship. But real friendship also means supporting what makes your friend feel beautiful. She wants this. She's just waiting for your blessing. So what do you say — can your girl treat herself?" [Address the interested person] "Right, here's what we do: you take it, and she takes the credit for letting you." [Back to the friend, smiling] "Go on. Give her the nod. You get to be the hero all the way home."`,textEs:'TÚ: "Lo entiendo perfectamente — sois un equipo, y lo respeto. Pero dejadme preguntaros algo a las dos: cuando lleguéis a casa esta noche, ¿vais a estar mirando la cara de ELLA en el espejo, o la TUYA?" [Mira a la persona interesada] "Mira, ella te quiere — por eso es protectora. Pero esto no es un timeshare, no es una estafa, es cuidado de la piel. Sentiste que funcionó. Viste esa línea desaparecer. Eso no es presión de grupo, eso es física." [Vuélvete hacia la amiga] "¿Y honestamente? Me encanta que la cuidas. Esa es amistad real. Pero la amistad real también significa apoyar lo que hace sentir bella a tu amiga. Ella quiere esto. Solo está esperando tu bendición. Entonces, ¿qué dices? ¿Tu amiga puede darse un capricho?" [Dirígete a la persona interesada] "Venga, hacemos esto: tú te lo llevas, y el mérito se lo lleva ella por dejarte." [Vuelve a la amiga, sonriendo] "Venga. Dale el visto bueno. Vas a ser la heroína todo el camino de vuelta."'},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:[`Turn them against each other: "She's just jealous!" — Creates conflict, not sales.`,"Pressure the friend: Trying to hard-sell the resistant friend makes the whole group leave.","Ignore the friend completely: The friend has power. Win her over, or at least neutralize her.","Give each of them a different price: Whatever you hand one, the rest will want, and now you are defending several numbers at once. Make it ONE deal for the group and let them sort out between themselves who puts in what."],itemsEs:['Enfrentarlas: "¡Solo está celosa!" — Crea conflicto, no ventas.',"Presionar a la amiga: Tratar de venderle a la amiga resistente hace que todo el grupo se vaya.","Ignorar a la amiga por completo: La amiga tiene poder. Gánatela, o al menos neutralízala.","Darle a cada una un precio distinto: Lo que le des a una lo van a querer todas, y ya estás defendiendo varios números a la vez. Haz UN trato para el grupo y que se apañen entre ellas quién pone qué."]},{type:"tip",text:`Doing the friend's hand is the MASTER move. It costs you a minute, it makes her part of the thing instead of the one standing there with her arms folded, and it is very hard to veto something you have just felt on your own skin. And in any group, find the "alpha" early — the one the others look at before they answer. Win the alpha and you have won all of them, right there at the table.`,textEs:'Hacerle la mano a la amiga es la jugada MAESTRA. Te cuesta un minuto, la convierte en parte del asunto en vez de en la que está ahí con los brazos cruzados, y es muy difícil vetar algo que acabas de notar en tu propia piel. Y en cualquier grupo, localiza pronto a la "alfa" — a la que miran las demás antes de contestar. Gánate a la alfa y las tienes a todas, ahí mismo, en la mesa.'}],quiz:[{question:'Her friend folds her arms and says "do not bother, it is a con." What is the move?',questionEs:'Su amiga se cruza de brazos y suelta "ni te molestes, es un timo". ¿Cuál es la jugada?',options:["Tell the friend she is wrong and show her the certificate","Put the friend in the chair — thirty seconds on her hand","Ignore the friend and keep selling to the interested one","Ask the friend to step aside so your customer can decide alone"],optionsEs:["Decirle a la amiga que se equivoca y enseñarle el certificado","Sienta a la amiga — treinta segundos en su mano","Pasar de la amiga y seguir vendiéndole a la interesada","Pedirle a la amiga que se aparte para que decida sola tu clienta"],correctIndex:1,explanation:"It is very hard to veto something you have just felt on your own skin. It costs you a minute and it turns the blocker into part of it.",explanationEs:"Es muy difícil vetar algo que acabas de notar en tu propia piel. Te cuesta un minuto y convierte a la que estorba en parte del asunto."},{question:"Both friends want it and both want a deal. How do you price it?",questionEs:"Las dos amigas lo quieren y las dos quieren trato. ¿Cómo lo pones de precio?",options:["One number for the pair — let them split it themselves","Best price to the one who asked first, full price to the other","A bit off each, so both of them feel they got something","Two different numbers — whatever each one says she can pay"],optionsEs:["Un número para las dos — que se lo repartan ellas","Mejor precio a la que preguntó primero y precio normal a la otra","Un poco menos a cada una, para que las dos se lleven algo","Dos números distintos — lo que diga cada una que puede pagar"],correctIndex:0,explanation:"Whatever you give one, the other will want. One deal for the group and you are defending one number instead of three.",explanationEs:"Lo que le des a una lo va a querer la otra. Un trato para el grupo y defiendes un número en vez de tres."},{question:"One of them has not said a word while her friend does all the talking. What do you assume?",questionEs:"Una no ha abierto la boca mientras su amiga habla por las dos. ¿Qué das por hecho?",options:["She is bored and waiting for her friend to finish up","She is the one who will talk the other out of it later","She may be the one with the money and no urge to argue","She is not interested — put it all on the loud one instead"],optionsEs:["Que se aburre y espera a que su amiga termine","Que luego será la que le quite la idea a la otra","Que puede ser la del dinero y sin ganas de discutir","Que no le interesa — céntrate solo en la escandalosa"],correctIndex:2,explanation:"The quiet one is very often the one holding the card. Bring her in warmly rather than writing her off.",explanationEs:"La callada es muchas veces la que lleva la tarjeta. Métela en el asunto con cariño en vez de descartarla."}]},O10:{id:"O10",categoryId:"objections",title:"I Don't Have Cash / Card Not Working",titleEs:"No Tengo Efectivo / La Tarjeta No Funciona",subtitle:"Turning payment obstacles into closed sales through flexibility",subtitleEs:"Convirtiendo obstáculos de pago en ventas cerradas a través de flexibilidad",duration:"3 min",icon:"CreditCard",order:10,xpReward:100,sections:[{type:"header",text:"Reading the Objection",textEs:"Leer la Objeción"},{type:"paragraph",text:"This objection is often REAL — tourists run out of cash, cards get blocked abroad, or they hit daily limits. Unlike other objections, this isn't about desire — it's about logistics. Solve the logistics, close the sale.",textEs:"Esta objeción a menudo es REAL — los turistas se quedan sin efectivo, las tarjetas se bloquean en el extranjero, o alcanzan límites diarios. A diferencia de otras objeciones, esto no es sobre deseo — es sobre logística. Resuelve la logística, cierra la venta."},{type:"subheader",text:"The Psychology Behind Payment Objections",textEs:"La Psicología Detrás de las Objeciones de Pago"},{type:"bullets",items:["Embarrassment: People feel ashamed when their card declines. Handle it with total grace — it happens to everyone.","Decision Fatigue: They've already decided to buy; the payment issue is just a speed bump. Don't let it become a wall.",'Loss Aversion: If they head off on their own to "get cash," most of them never arrive back. That is exactly why you do not send them — you walk over there with them.'],itemsEs:["Vergüenza: La gente se siente avergonzada cuando su tarjeta se declina. Manéjalo con total elegancia — le pasa a todos.","Fatiga de Decisión: Ya decidieron comprar; el problema de pago es solo un bache. No dejes que se convierta en muro.",'Aversión a la Pérdida: Si se van solos a "sacar efectivo", la mayoría no aparece de vuelta. Justo por eso no los mandas — te vas con ellos.']},{type:"subheader",text:"Script 1: The Multiple Options (Short)",textEs:"Guion 1: Las Múltiples Opciones (Corto)"},{type:"script",text:'YOU: "No worries at all! We take everything — Apple Pay, Google Pay, all cards, cash, and we can even do split payment if you want to use two cards. What works best for you?"',textEs:'TÚ: "¡Para nada te preocupes! Aceptamos todo — Apple Pay, Google Pay, todas las tarjetas, efectivo, e incluso podemos hacer pago dividido si quieres usar dos tarjetas. ¿Qué te funciona mejor?"'},{type:"subheader",text:"Script 2: The Split Payment Solution (Medium)",textEs:"Guion 2: La Solución de Pago Dividido (Medio)"},{type:"script",text:`YOU: "Card problems abroad are the WORST, I know. Happened to me in Barcelona last month. Here's what we can do: split it across two cards — or have you got Apple Pay or Google Pay on your phone? Sometimes that goes through when the plastic won't. Let's try." [Try it] "And if it turns out to be cash you need, that's even easier. There's a machine two minutes that way." [Pick the bag up] "I'll walk you over and carry this. Come on."`,textEs:'TÚ: "Los problemas de tarjeta en el extranjero son lo PEOR, lo sé. Me pasó en Barcelona el mes pasado. Esto es lo que podemos hacer: lo dividimos entre dos tarjetas — ¿o tienes Apple Pay o Google Pay en el móvil? A veces pasa cuando el plástico no. Vamos a probar." [Pruébalo] "Y si al final lo que hace falta es efectivo, más fácil todavía. Hay un cajero a dos minutos por ahí." [Coge la bolsa] "Te acompaño y te la llevo yo. Venga."'},{type:"subheader",text:"Script 3: The Full Flexibility Framework (Detailed)",textEs:"Guion 3: El Marco de Flexibilidad Completa (Detallado)"},{type:"script",text:`YOU: "Okay, let's solve this together — because I don't want a little card hiccup to stop you from getting something you love." [Be calm, problem-solving tone] "Let's go through our options one by one. Option one: do you have another card? Debit, credit, even a prepaid travel card?" [If yes, try it] "Option two: Apple Pay, Google Pay, Samsung Pay — anything on your phone?" [If yes, set it up] "Option three: split it. Half on this card, half in cash — or any combination you like, I will make the numbers work." [Work with them] "Option four: cash — which honestly suits me even better. There's a machine two minutes that way. I'll walk you over and carry the bag. I'm not sending you, I'm coming with you." [Stay warm, keep the problem-solving tone] "So... which one are we doing? Because I'm not letting you walk away from results like these over a card glitch."`,textEs:'TÚ: "Vale, resolvamos esto juntos — porque no quiero que un pequeño problema de tarjeta te impida llevarte algo que amas." [Sé calmado, tono de resolución de problemas] "Revisemos nuestras opciones una por una. Opción uno: ¿tienes otra tarjeta? Débito, crédito, incluso una tarjeta de viaje prepagada?" [Si sí, inténtala] "Opción dos: Apple Pay, Google Pay, Samsung Pay — ¿algo en tu móvil?" [Si sí, configúralo] "Opción tres: lo partimos. La mitad en esta tarjeta, la mitad en efectivo — o como tú quieras, que yo cuadro los números." [Trabaja con ellos] "Opción cuatro: efectivo, que además a mí me viene hasta mejor. Hay un cajero a dos minutos por ahí — te acompaño yo y te llevo la bolsa. No te mando, voy contigo." [Sigue cercano, en modo resolución] "Entonces... ¿cuál hacemos? Porque no te voy a dejar marchar de unos resultados como estos por un fallo de tarjeta."'},{type:"subheader",text:"What NOT to Do",textEs:"Qué NO Hacer"},{type:"bullets",items:["Show frustration: A sigh or eye roll when their card declines kills the vibe instantly.",`Make them feel poor: "Oh, you don't have enough?" — Never. Assume it's a technical issue, not a financial one.`,'Say "come back later": They will not. Not with a plan, not without one. Work down the options in front of her instead — and if it comes to cash, you put the bag under your arm and walk to the machine with her.',"Send them off with a consolation prize: No sample, no card, nothing to take away — that is the same walk-out with a goodbye gift attached. If the money genuinely is not there, be lovely about it, hands empty, and get straight back on the floor."],itemsEs:["Mostrar frustración: Un suspiro o volteo de ojos cuando la tarjeta se declina mata el ambiente al instante.",'Hacerlos sentir pobres: "¿Oh, no tienes suficiente?" — Nunca. Asume que es un problema técnico, no financiero.','Decir "vuelve luego": No van a volver. Ni con plan ni sin plan. Ve bajando por las opciones delante de ella — y si al final toca efectivo, te pones la bolsa bajo el brazo y vas con ella al cajero.',"Despedirlos con un premio de consolación: Ni muestra, ni tarjeta, nada para llevarse — eso es la misma marcha con un regalito de despedida. Si de verdad no está el dinero, sé encantador, con las manos vacías, y vuelve al ruedo."]},{type:"tip",text:`Know exactly where the nearest cash machine is, because that is your best answer and not your last one: "Cash suits me even better, my love. There's a machine two minutes that way — I'll walk you over and carry the bag." You go WITH them. You never send them off on their own, however close it is, however sure she sounds, however busy the table is. Everything else stays right here in front of her: another card, the numbers typed in by hand, Apple Pay, Google Pay, two cards split. Work down that list out loud and one of them lands.`,textEs:'Sábete exactamente dónde está el cajero más cercano, porque esa es tu mejor respuesta y no la última: "En efectivo aún mejor, cariño. Hay un cajero a dos minutos — te acompaño yo y te llevo la bolsa." Vas CON ellos. Nunca los mandas solos, por cerca que esté, por muy segura que suene y por muy liada que esté la mesa. Todo lo demás se queda aquí delante de ella: otra tarjeta, los números metidos a mano, Apple Pay, Google Pay, dividirlo entre dos tarjetas. Ve bajando esa lista en voz alta y una de ellas entra.'}],quiz:[{question:"Her card is refused and she has not got another one. What do you say?",questionEs:"Le rechazan la tarjeta y no tiene otra. ¿Qué le dices?",options:['"Cash suits me even better — I will walk you over and carry the bag"','"There is a machine right across the street, I will hold this for you"','"Take my card and come back once the bank has sorted it out"','"No problem, we can put your name on one and keep it behind the till"'],optionsEs:['"En efectivo aún mejor — te acompaño yo y te llevo la bolsa"','"Hay un cajero justo enfrente, yo te lo guardo mientras tanto"','"Toma mi tarjeta y vuelve cuando el banco te lo arregle"','"Sin problema, le ponemos tu nombre y lo dejamos aquí en caja"'],correctIndex:0,explanation:"Cash is not a problem, it is a walk. You go with her and the bag goes with you — the one thing you never do is send her off on her own.",explanationEs:"El efectivo no es un problema, es un paseo. Vas con ella y la bolsa va contigo — lo único que no haces nunca es mandarla sola."},{question:"Why do you never send her to the cash machine on her own?",questionEs:"¿Por qué no la mandas nunca sola al cajero?",options:["She will spend the money on something else along the way there","The shop is not allowed to hold stock for anybody","She will find a friend who talks her out of it","Out of that door she is gone, however much she meant it"],optionsEs:["Se gastará el dinero en otra cosa por el camino hasta allí","La tienda no puede guardarle género a nadie","Se encontrará a una amiga que le quite la idea","En cuanto sale por esa puerta se acabó, lo dijera como lo dijera"],correctIndex:3,explanation:"The feeling she has in that chair does not survive a five-minute walk on her own. Keep her with you and keep the sale alive.",explanationEs:"Lo que siente en esa silla no aguanta cinco minutos de paseo ella sola. Que se quede contigo y la venta sigue viva."},{question:"Her card has just been refused in front of a queue and she has gone red. What do you do first?",questionEs:"Le acaban de rechazar la tarjeta delante de una cola y se ha puesto roja. ¿Qué haces primero?",options:["Ask her quietly whether she has got enough in the account","Laugh it off and try typing the numbers in by hand","Announce to the queue that the terminal has been playing up","Say nothing and let her work out what she wants to do next"],optionsEs:["Preguntarle bajito si le queda saldo en la cuenta","Quitarle hierro y probar metiendo los números a mano","Anunciarle a la cola que el datáfono va fatal hoy","No decir nada y dejar que ella decida qué hacer ahora"],correctIndex:1,explanation:"Assume it is the machine, never her money. Warm, quick and unbothered, and the embarrassment never gets a chance to start.",explanationEs:"Da por hecho que es la máquina, nunca su dinero. Con calor, rápido y sin darle importancia, y la vergüenza no llega ni a empezar."}]}},u={"close-market":{id:"close-market",categoryId:"closing",title:"It's a Market, Not a Pharmacy",titleEs:"Esto es un Mercado, No una Farmacia",subtitle:"The haggle is the product — and both of you already know it",subtitleEs:"El regateo es el producto — y los dos lo sabéis ya",duration:"6 min",icon:"Sparkles",order:1,xpReward:120,sections:[{type:"header",text:"It's a market, not a pharmacy",textEs:"Esto es un mercado, no una farmacia"},{type:"paragraph",text:"Nobody has told you this yet, so I will. Go outside and look at where you actually work. There is no white coat, no appointment, no little sticker with a fixed price on it. There is a chair, a table, a bit of product and a person with good energy stopping strangers in the street. That is a market stall. Behind a counter you wait to be asked and nobody touches anything until they have paid. On a stall you talk first, you put it in their hand, and the number is the start of the conversation instead of the end of it.",textEs:"Nadie te lo ha dicho todavía, así que te lo digo yo. Sal fuera y mira dónde trabajas de verdad. No hay bata blanca, no hay cita previa, no hay una etiqueta con un precio fijo. Hay una silla, una mesa, un poco de producto y una persona con buena energía parando a desconocidos en la calle. Eso es un puesto de mercado. Detrás de un mostrador esperas a que te pregunten y nadie toca nada hasta que ha pagado. En un puesto hablas tú primero, se lo pones en la mano, y el número es el principio de la conversación, no el final."},{type:"keypoint",text:"If you walked in here thinking pharmacy — quiet voice, careful words, one price — you are going to have a very slow week. And here is the bit that costs you money: the customer copies you. Stiff seller, stiff customer. You play, they play back. Your energy sets the temperature of the whole thing before a single number leaves your mouth.",textEs:"Si has entrado aquí pensando en una farmacia — voz bajita, palabras con cuidado, un solo precio — te espera una semana muy lenta. Y esto es lo que te cuesta dinero: el cliente te copia. Vendedor tieso, cliente tieso. Si tú juegas, ellos juegan. Tu energía marca la temperatura de todo antes de que salga un solo número de tu boca."},{type:"script",text:`"Come here one second — you're going to like this, I promise. Give me your hand."`,textEs:'"Ven un segundo — esto te va a gustar, te lo prometo. Dame la mano."'},{type:"subheader",text:"They already know the first price isn't the last price",textEs:"Ya saben que el primer precio no es el último"},{type:"paragraph",text:`This is what new sellers get wrong about haggling. They think it is something they are pulling on somebody. It isn't. This person walked up to a stall in the street — they have known how this works since they were a kid. So when they say "is that your best price?" they are not catching you out, they are joining in. If they honestly thought {currency}60 was carved in stone they would have said no thanks and kept walking. Instead they are standing there asking you a question. That is not resistance, that is the game starting. They know it is a performance. They enjoy it anyway — the same way you enjoy a haggle on holiday.`,textEs:'Esto es lo que los vendedores nuevos entienden mal del regateo. Se creen que se lo están colando a alguien. Y no. Esta persona se ha acercado a un puesto en la calle — sabe cómo funciona esto desde pequeña. Así que cuando te dice "¿es tu mejor precio?" no te está pillando, se está apuntando. Si de verdad pensara que los {currency}60 están grabados en piedra, habría dicho "no, gracias" y habría seguido andando. En vez de eso está ahí parada haciéndote una pregunta. Eso no es resistencia, es que empieza el juego. Saben que es una función. Y aun así les gusta — igual que a ti te gusta regatear cuando estás de viaje.'},{type:"script",text:`"Ha — of course that's not my best price. What do you think this is, a supermarket? Come on, talk to me."`,textEs:'"Ja — claro que no es mi mejor precio. ¿Qué te crees, que esto es un supermercado? Venga, habla conmigo."'},{type:"subheader",text:"Say the number and don't flinch",textEs:"Di el número y no te encojas"},{type:"keypoint",text:`Say it warm, say it flat, then shut up. Do not wince. Do not say "it's only". Do not say "I know it's a bit pricey, but". The second you flinch at your own number you have told them the number is wrong — and now they are not haggling with you, they are rescuing you, downwards. Serious and careful is what you do when you do not believe your own price.`,textEs:'Dilo con calor, dilo plano, y luego cállate. No hagas una mueca. No digas "son solo". No digas "ya sé que es un poco caro, pero". En cuanto te encoges con tu propio número, les has dicho que el número está mal — y ahora no están regateando contigo, te están rescatando, hacia abajo. Serio y prudente es lo que haces cuando no te crees tu propio precio.'},{type:"paragraph",text:"Your body says the same thing. Small and apologetic, and {currency}60 sounds like a lot of money. Easy, open, having a good day, and {currency}60 sounds like nothing at all.",textEs:"Tu cuerpo dice lo mismo. Pequeño y disculpándote, y {currency}60 suenan a mucho dinero. Suelto, abierto, pasándotelo bien, y {currency}60 no suenan a nada."},{type:"script",text:`If they go tense on the number: "Relax, I'm not a dentist. It's hand cream."`,textEs:'Si se tensan con el número: "Tranquila, que no soy dentista. Es crema de manos."'},{type:"subheader",text:"Every rung needs a reason",textEs:"Cada escalón necesita un motivo"},{type:"paragraph",text:"The ladder is a performance, and a performance needs a reason. If the price just falls, it was never a price. {currency}60 to {currency}30 in twenty seconds is not a discount, it is an announcement that you were making the numbers up. So every rung gets three things: a pause, a face, and a reason. Look at the product. Look at the door. Suck your teeth. Breathe out like it actually hurts. Then give the reason — and the reason is always about them, never about the product. The product never gets cheaper. The product stays brilliant. What changed is that today, for this one person, you have decided to do something.",textEs:"La escalera es una función, y una función necesita un motivo. Si el precio simplemente cae, nunca fue un precio. De {currency}60 a {currency}30 en veinte segundos no es un descuento, es anunciar que te estabas inventando los números. Así que cada escalón lleva tres cosas: una pausa, una cara y un motivo. Mira el producto. Mira a la puerta. Chasquea la lengua. Suelta el aire como si te doliera de verdad. Y luego da el motivo — y el motivo siempre es por ellos, nunca por el producto. El producto nunca baja de categoría. El producto sigue siendo buenísimo. Lo que ha cambiado es que hoy, por esta persona, has decidido hacer algo."},{type:"script",text:'"My last customer only took one. Let me do something nice for you."',textEs:'"Mi última clienta se llevó solo uno. Déjame hacerte algo bonito."'},{type:"subheader",text:"And make them ask twice before you move once",textEs:"Y que te lo pidan dos veces antes de moverte una"},{type:"paragraph",text:`First "ooh, that's a bit expensive" and the nervous seller jumps straight to the floor to feel safe. That is the most expensive habit in this shop. You have handed over {currency}30 nobody asked you for, and you have taught them the numbers move when they push — so they push again, and now your floor is not a floor. Get to your last price in ten seconds and they will not believe it is your last price. They are right not to.`,textEs:'Al primer "uy, es un poco caro" el vendedor nervioso salta directo al suelo para sentirse seguro. Es la costumbre más cara de esta tienda. Has regalado {currency}30 que nadie te había pedido, y les has enseñado que los números se mueven si empujan — así que empujan otra vez, y ahora tu suelo ya no es un suelo. Llega a tu último precio en diez segundos y no se van a creer que es tu último precio. Y hacen bien.'},{type:"script",text:`When they push early: "Whoa, whoa, whoa. I've known you thirty seconds and you're already trying to rob me."`,textEs:'Cuando empujan pronto: "Eh, eh, eh. Hace treinta segundos que te conozco y ya me estás robando."'},{type:"subheader",text:"The little conspiracy",textEs:"La pequeña conspiración"},{type:"paragraph",text:"The strongest rung on the ladder is not the cheapest one. It is the one that arrives with a secret. Voice down. Quick look at the door. Lean in a bit. Now it is the two of you on the same side — against the price list, against my boss, against everyone else walking in here today who is going to pay full. They are not buying a cheaper thing, they are buying a moment where somebody bent something just for them. And it survives the walk home: when they tell their friend about it tonight, they tell them the story. They never remember the number.",textEs:"El escalón más fuerte de la escalera no es el más barato. Es el que llega con un secreto. Baja la voz. Mirada rápida a la puerta. Acércate un poco. Ahora sois los dos del mismo lado — contra la lista de precios, contra mi jefe, contra todos los demás que entren hoy y paguen el precio entero. No están comprando algo más barato, están comprando un momento en el que alguien dobló algo solo por ellos. Y eso les dura hasta casa: cuando esta noche se lo cuenten a una amiga, le cuentan la historia. Del número no se acuerdan nunca."},{type:"script",text:`"You really love it, don't you — you haven't stopped touching your hands. Alright: {currency}30 for the one. But zip it, this stays between us."`,textEs:'"Te encanta de verdad, ¿eh? No paras de tocarte las manos. Venga: {currency}30 por uno. Pero chitón, que esto queda entre nosotros."'},{type:"subheader",text:"Let them win",textEs:"Déjales ganar"},{type:"paragraph",text:'Nobody at a market wants the lowest price. They want the story: "I got him down." So build them the moment where they get you. Ask for their number and make them say it out loud. Hold, hold, hold — then collapse all at once, hands in the air, like they have genuinely beaten something out of you. It costs you exactly the same as caving at the start and it feels completely different to the person paying. Nobody brags to their mates about a discount that was just sitting there.',textEs:'Nadie en un mercado quiere el precio más bajo. Quieren la historia: "le he tirado el precio". Así que constrúyeles el momento en el que te ganan. Pídeles su número y haz que lo digan en voz alta. Aguanta, aguanta, aguanta — y luego derrúmbate de golpe, manos arriba, como si de verdad te hubieran sacado algo. Te cuesta exactamente lo mismo que ceder al principio y se siente completamente distinto para quien paga. Nadie presume delante de sus amigas de un descuento que ya estaba ahí puesto.'},{type:"keypoint",text:"One rule: when you go, go. Half a surrender is worse than none — they can smell it, and they will keep pushing.",textEs:"Una regla: cuando cedas, cede. Media rendición es peor que ninguna — lo huelen, y siguen empujando."},{type:"script",text:`"Go on then, give me your number… Ooof. You're a hard one, you." … "Fine. FINE. You've killed me. Take it. But you're not telling anybody what you paid, alright?"`,textEs:'"Venga, dime tu número… Buf. Menuda eres tú." … "Vale. VALE. Me has matado. Llévatelo. Pero no le dices a nadie lo que has pagado, ¿eh?"'},{type:"divider"},{type:"header",text:"Where the game stops — and it is about money, not manners",textEs:"Dónde se acaba el juego — y es por dinero, no por modales"},{type:"paragraph",text:'Everything above is fair game. All of it. The price theatre, "just for you", "my last customer", "between us", how much you personally love the stuff — that is the market, do the lot, that is why people stop here instead of walking into a chemist.',textEs:'Todo lo de arriba vale. Todo. El teatro del precio, "solo para ti", "mi última clienta", "que quede entre nosotros", lo mucho que te gusta a ti el producto — eso es el mercado, hazlo todo, por eso la gente para aquí en vez de entrar en una farmacia.'},{type:"keypoint",text:"Two things sit outside the game, and not because anybody is offended — because they land back on the shop after you have clocked off. ONE: never promise anything the shop has to do once they are out that door. Money back, sort it at the border, come back next year and we'll swap it. You will not be there. The shop will, and somebody else has to have that argument. TWO: never tell anybody what it does to their body — what it treats, what it is safe with, what a doctor reckons about it. That is the one that turns a delighted customer into a real problem. Sell the shine, the look, the feeling, the price. Not medicine, and not promises with a date on them.",textEs:"Dos cosas se quedan fuera del juego, y no porque nadie se ofenda — porque caen sobre la tienda cuando tú ya te has ido a casa. UNA: no prometas nunca nada que la tienda tenga que cumplir cuando ya han salido por esa puerta. Devolver el dinero, arreglarlo en la frontera, vuelve el año que viene y te lo cambiamos. Tú no vas a estar. La tienda sí, y otra persona tiene que tener esa discusión. DOS: no le digas nunca a nadie lo que le hace a su cuerpo — qué cura, con qué es seguro, qué opina un médico. Esa es la que convierte a una clienta encantada en un problema de verdad. Vende el brillo, el aspecto, la sensación, el precio. Ni medicina, ni promesas con fecha."},{type:"script",text:`"Look, I'm not a doctor — I'm a stall on a corner with very good hand cream. But look at that shine on you."`,textEs:'"Mira, no soy médico — soy un puesto en una esquina con una crema de manos buenísima. Pero mírate qué brillo."'},{type:"tip",text:"The second they say yes, the haggle is over. Stop selling. Stop dropping. Do not sweeten it, do not throw in one more thing, do not get nervous and fill the silence with another gift nobody asked for — that is you still playing a game that ended a minute ago, and all it does is make them wonder what else was on the table. Switch straight into lovely: quick, easy, ask about their trip, go and get the machine. The theatre was for getting to yes. After yes, you are just a nice person taking their money.",textEs:"En cuanto dicen que sí, se acabó el regateo. Deja de vender. Deja de bajar. No lo endulces, no metas una cosa más, no te pongas nervioso y llenes el silencio con otro regalo que nadie te ha pedido — eso eres tú jugando todavía a un juego que se acabó hace un minuto, y lo único que consigue es que se pregunten qué más había encima de la mesa. Pasa directo a modo encantador: rápido, fácil, pregúntales por el viaje, ve a por el datáfono. El teatro era para llegar al sí. Después del sí, solo eres una persona simpática cobrándoles."}],quiz:[{question:'A customer asks "is that your best price?" What is actually happening?',questionEs:'Un cliente pregunta "¿es tu mejor precio?" ¿Qué está pasando de verdad?',options:["Resistance — they are about to walk away","Them joining in — the game has started","A sign you priced it too high for them","A cue to go straight to your floor price"],optionsEs:["Resistencia — están a punto de irse","Se están apuntando — empieza el juego","Señal de que les has pedido demasiado","Que vayas directo a tu precio mínimo"],correctIndex:1,explanation:"If they thought the price was fixed they would have said no thanks and kept walking. Standing there asking is the haggle starting.",explanationEs:'Si pensaran que el precio es fijo, habrían dicho "no, gracias" y habrían seguido andando. Que se queden preguntando es que empieza el regateo.'},{question:"Why does dropping from {currency}60 to {currency}30 in twenty seconds cost you?",questionEs:"¿Por qué te cuesta caro bajar de {currency}60 a {currency}30 en veinte segundos?",options:["It teaches them pushing moves the numbers","It breaks the minimum margin the shop sets","It makes the product look like poor quality","It leaves you nothing to give away later"],optionsEs:["Les enseñas que empujar mueve los números","Te saltas el margen mínimo que fija la tienda","Hace que el producto parezca de mala calidad","Te quedas sin nada que regalar más adelante"],correctIndex:0,explanation:"You handed over money nobody asked for, and taught them the numbers move when they push — so they push again, and your floor stops being a floor.",explanationEs:"Has regalado dinero que nadie te pidió y les has enseñado que los números se mueven si empujan — así que empujan otra vez, y tu suelo deja de ser un suelo."},{question:"Which is the strongest rung on the ladder?",questionEs:"¿Cuál es el escalón más fuerte de la escalera?",options:["The cheapest one, because it removes every objection","The first one, because it anchors everything after","The one that arrives like a secret, just for them","Whichever one matches their budget most closely"],optionsEs:["El más barato, porque quita todas las objeciones","El primero, porque ancla todo lo que viene después","El que llega como un secreto, solo para ellos","El que más se ajuste a lo que pueden gastarse"],correctIndex:2,explanation:"They are not buying a cheaper thing. They are buying a moment where somebody bent something just for them — and that is the bit they tell their friend about tonight.",explanationEs:"No están comprando algo más barato. Están comprando un momento en el que alguien dobló algo solo por ellos — y eso es lo que le cuentan esta noche a una amiga."},{question:"They say yes. What is the next thing you do?",questionEs:"Dicen que sí. ¿Qué es lo siguiente que haces?",options:["Throw in one more gift to lock it in","Confirm the price out loud so there is no confusion","Ask if they want to add a second product","Stop selling and go and get the card machine"],optionsEs:["Meter un regalo más para asegurarlo","Confirmar el precio en voz alta para que no haya líos","Preguntar si quieren añadir un segundo producto","Dejar de vender e ir a por el datáfono"],correctIndex:3,explanation:"The theatre was for getting to yes. Carrying on after it just makes them wonder what else was on the table.",explanationEs:"El teatro era para llegar al sí. Seguir después solo hace que se pregunten qué más había encima de la mesa."}]},"close-1":{id:"close-1",categoryId:"closing",title:"The Bring",titleEs:"Meterlos Dentro",subtitle:"The walk from the pavement to the chair",subtitleEs:"El camino de la acera a la silla",duration:"5 min",icon:"DoorOpen",order:2,xpReward:120,sections:[{type:"header",text:"The gap nobody teaches",textEs:"El hueco que nadie enseña"},{type:"paragraph",text:"You know how to stop someone. You know the product. The place most sales die is the bit between those two things — the short walk from where they are standing to the chair inside the shop. Get this wrong and you lose people you had already won.",textEs:"Sabes parar a alguien. Te sabes el producto. Donde más ventas se mueren es en lo que hay entre esas dos cosas — el trocito que va desde donde están de pie hasta la silla dentro de la tienda. Falla esto y pierdes a gente que ya tenías ganada."},{type:"keypoint",text:"The whole technique is an order of operations. Do the steps in the wrong order and each one stops working.",textEs:"Toda la técnica es un orden de operaciones. Haz los pasos en el orden equivocado y cada uno deja de funcionar."},{type:"subheader",text:"Step 1 — Get the look before you move",textEs:"Paso 1 — Consigue la mirada antes de moverte"},{type:"paragraph",text:"Before you approach anybody with the sample, get their attention. You want them looking at you BEFORE you take a single step. Not while you walk — before. And do it early, while they are still four or five metres off and still walking. Wait until they are a couple of metres away and you have left it too late: by the time they have registered you and turned their head they are already level with you, and then they are past you.",textEs:"Antes de acercarte a nadie con la muestra, consigue su atención. Quieres que te estén mirando ANTES de dar un solo paso. No mientras andas — antes. Y hazlo pronto, cuando todavía están a cuatro o cinco metros y siguen andando. Si esperas a que estén a un par de metros, ya llegas tarde: para cuando te han visto y han girado la cabeza ya están a tu altura, y acto seguido te han pasado de largo."},{type:"script",...o},{type:"paragraph",text:"If they look at you, now you raise the sample and start walking towards them. If they do not look, you have lost nothing — you did not commit. Walking at someone who has not looked at you is how you become a person to avoid.",textEs:"Si te miran, ahora levantas la muestra y empiezas a andar hacia ellos. Si no te miran, no has perdido nada — no te has comprometido. Andar hacia alguien que no te ha mirado es cómo te conviertes en una persona a evitar."},{type:"keypoint",text:"And when you do reach them, the sample itself is a coin toss — it does not matter which way it lands. They take it, lovely. They wave it away, nothing happens. You have not been rejected, because you never asked them for anything. Either way you are still stood in front of them and you carry straight on into the next step, exactly the same. Sellers lose people here by treating a refused sample as an answer. It is not an answer, it is a hand not moving.",textEs:"Y cuando llegues a su altura, la muestra es cara o cruz — da igual de qué lado caiga. Si la cogen, genial. Si la apartan con la mano, no pasa nada. No te han rechazado, porque no les has pedido nada. En los dos casos sigues plantado delante de ellos y pasas al siguiente paso igual. Aquí es donde los vendedores pierden gente: se toman una muestra rechazada como una respuesta. No es una respuesta, es una mano que no se ha movido."},{type:"subheader",text:"Step 2 — Say the objection before they can",textEs:"Paso 2 — Di la objeción antes que ellos"},{type:"paragraph",text:`The single most common thing a person says to get away from you is "sorry, I'm in a rush." So say it first. Once it has come out of your mouth, it is no longer available as an escape — they cannot use a reason you have already accepted.`,textEs:'Lo que más dice la gente para escaparse de ti es "perdona, voy con prisa". Así que dilo tú primero. Una vez que ha salido de tu boca, ya no les sirve de escape — no pueden usar una razón que tú ya has aceptado.'},{type:"script",...t},{type:"paragraph",text:'Two things are doing work in that sentence. The rush is pre-killed. And the question is a genuine compliment that they have to answer with a real answer — you cannot say yes or no to "what do you use?".',textEs:'Hay dos cosas trabajando en esa frase. La prisa está desactivada. Y la pregunta es un cumplido de verdad que les obliga a dar una respuesta real — a "¿qué usas?" no puedes contestar sí o no.'},{type:"subheader",text:"Step 3 — The gift, then turn around",textEs:"Paso 3 — El regalo, y date la vuelta"},{type:"paragraph",text:"Whatever they answer, you are impressed by it. Then you give them a reason to move that costs them nothing.",textEs:"Contesten lo que contesten, te parece impresionante. Luego les das un motivo para moverse que no les cuesta nada."},{type:"script",text:`"Really? No way. You know what — just because you look so amazing, I'm going to give you a small gift. I think you're going to love it."`,textEs:'"¿En serio? No me lo creo. ¿Sabes qué? Solo porque estás guapísima, te voy a hacer un regalito. Creo que te va a encantar."'},{type:"keypoint",text:"Now turn around and walk into the shop. Do NOT check whether they are following you. Checking asks permission, and asking permission gives them the chance to say no.",textEs:"Ahora date la vuelta y entra en la tienda. NO compruebes si te están siguiendo. Comprobar es pedir permiso, y pedir permiso les da la oportunidad de decir que no."},{type:"subheader",text:"Step 4 — Only now, look back",textEs:"Paso 4 — Ahora sí, mira atrás"},{type:"paragraph",text:"Once you are inside the shop — and only then — turn your head and see who came. If they are still on the pavement, call them in warmly. You are not begging; you are holding a door open.",textEs:"Una vez dentro de la tienda — y solo entonces — gira la cabeza y mira quién ha venido. Si siguen en la acera, llámalos con buen rollo. No estás suplicando; estás sujetando una puerta abierta."},{type:"script",...n},{type:"keypoint",text:"Then turn back round and keep walking. Do not stand there in the doorway watching them decide. Say it, turn, walk — and the walking is what does the persuading, because now there is nothing to say no to. A seller frozen in the door with a hopeful face is asking permission again, and you have just spent four steps not asking permission.",textEs:"Y date la vuelta otra vez y sigue andando. No te quedes ahí en la puerta mirando cómo lo deciden. Lo dices, te giras, andas — y lo que convence es el andar, porque ya no hay nada a lo que decir que no. Un vendedor congelado en la puerta con cara de ilusión está pidiendo permiso otra vez, y te acabas de pasar cuatro pasos sin pedir permiso."},{type:"paragraph",text:"You never walk beside them and you never escort them. You walk first and you call them to come. Walking them in makes it feel like being taken somewhere; walking ahead makes it feel like following someone who has something.",textEs:"Nunca andas a su lado y nunca los acompañas. Andas tú primero y los llamas. Acompañarlos hace que parezca que los están llevando a algún sitio; ir delante hace que parezca que siguen a alguien que tiene algo."},{type:"subheader",text:"Step 5 — Where you sit them",textEs:"Paso 5 — Dónde los sientas"},{type:"paragraph",text:"Put them in the chair facing into the shop — facing the wall — never facing the street. If they can see the pavement moving past, they start thinking about being back out on it. Take the street out of their eyeline and you have their whole attention.",textEs:"Siéntalos en la silla mirando hacia dentro de la tienda — hacia la pared — nunca hacia la calle. Si ven el movimiento de la acera, empiezan a pensar en volver a ella. Quita la calle de su campo de visión y tienes toda su atención."},{type:"keypoint",text:"Have the chairs ready before anybody gets to them. Sorting furniture while she stands there watching is ten seconds of nothing happening, and ten seconds of nothing happening is exactly long enough for her to remember she was on her way somewhere.",textEs:"Ten las sillas puestas antes de que llegue nadie. Colocar muebles mientras ella está ahí de pie mirando son diez segundos en los que no pasa nada, y diez segundos en los que no pasa nada son justo lo que necesita para acordarse de que iba a algún sitio."},{type:"keypoint",text:'And if there are two of them, set out two chairs. A partner left standing behind her has nothing to do but wait, and a bored man behind the chair is the most common reason a good demo ends in "come on, we should get going". Sit him down and he is part of it instead of waiting for it to finish.',textEs:'Y si son dos, saca dos sillas. Una pareja que se queda de pie detrás no tiene nada que hacer salvo esperar, y un hombre aburrido detrás de la silla es el motivo más habitual de que una buena demo acabe en "venga, que nos tenemos que ir". Siéntalo y pasa a formar parte, en vez de estar esperando a que acabe.'},{type:"divider"},{type:"header",text:"When there are two of them",textEs:"Cuando son dos"},{type:"paragraph",text:"One is interested and the other is already walking. This is the most common way a good stop dies. Deal with the one who is leaving, quickly and lightly.",textEs:"Uno está interesado y el otro ya se está yendo. Es la forma más habitual de que se muera una buena parada. Ocúpate del que se va, rápido y con ligereza."},{type:"script",text:`"It's two seconds of your time, I promise — she's going to love it."`,textEs:'"Son dos segundos, te lo prometo — le va a encantar."'},{type:"keypoint",text:'Then bring him IN. That is the first move and it is not the obvious one — sellers try to get shot of the partner because he looks like the problem. He is not the problem, he is bored. Sit him in the second chair, give him a job, and make him the expert on her face. A man with a job does not look at his watch. And when he says "yeah, that side is better", she has heard it from the one person in this shop she actually believes.',textEs:'Y luego mételo DENTRO. Ese es el primer movimiento y no es el que parece — los vendedores intentan quitarse a la pareja de encima porque parece el problema. No es el problema, está aburrido. Siéntalo en la segunda silla, dale un trabajo y hazlo el experto en la cara de ella. Un hombre con un trabajo no mira el reloj. Y cuando dice "sí, ese lado está mejor", ella lo ha oído de la única persona de la tienda a la que de verdad cree.'},{type:"script",text:`"Sit here, you're the judge — you know her face better than I do. You tell me which side wins."`,textEs:'"Siéntate aquí, tú eres el jurado — le conoces la cara mejor que yo. Tú me dices qué lado gana."'},{type:"paragraph",text:"Only if that does not take — if the energy is genuinely bad rather than busy — do you give him permission to stand back instead of arguing with him. Said light, with a smile, it takes the pressure off him completely. And notice he is still in the shop: standing back is not the same as going.",textEs:"Solo si eso no prende — si la energía es mala de verdad y no es que tengan prisa — le das permiso para apartarse en vez de discutir con él. Dicho ligero, con una sonrisa, le quita la presión del todo. Y fíjate en que sigue dentro de la tienda: apartarse no es irse."},{type:"script",text:`"Don't worry, it's ladies' business anyway."`,textEs:'"No te preocupes, esto es cosa de chicas de todas formas."'},{type:"keypoint",text:"And the last resort, only once he has properly decided to be difficult: let him go, and put everything on the person who is still listening to you. Third move, never the first. Reach for it before you have tried the chair and the job and you have thrown away the second-best salesperson in the building.",textEs:"Y el último recurso, solo cuando él ha decidido de verdad ponerse difícil: déjalo ir, y ponlo todo en la persona que todavía te escucha. Tercer movimiento, nunca el primero. Si tiras de él antes de haber probado la silla y el trabajo, has tirado a la basura al segundo mejor vendedor del edificio."},{type:"tip",text:"There are a hundred tricks on top of this, and you will build your own. But this is the skeleton: get the look, kill the rush, ask a real question, promise a gift, turn and walk, then look back. Learn it in that order before you start improvising on it.",textEs:"Encima de esto hay cien trucos, y te construirás los tuyos. Pero este es el esqueleto: consigue la mirada, mata la prisa, haz una pregunta de verdad, promete un regalo, date la vuelta y anda, y luego mira atrás. Apréndetelo en ese orden antes de ponerte a improvisar."}],quiz:[{question:"When do you take your first step towards someone?",questionEs:"¿Cuándo das el primer paso hacia alguien?",options:["As soon as you have picked out who to approach","Only after they have looked at you","While you are still saying your opening line","When they slow down or stop walking"],optionsEs:["En cuanto has elegido a quién acercarte","Solo después de que te hayan mirado","Mientras todavía estás diciendo tu frase de apertura","Cuando aflojan el paso o se paran"],correctIndex:1,explanation:'Get their attention first — "Hi guys, how you doing?" — and wait. Walking at someone who has not looked at you makes you a person to avoid.',explanationEs:'Consigue primero su atención — "Hola chicos, ¿qué tal?" — y espera. Andar hacia alguien que no te ha mirado te convierte en una persona a evitar.'},{question:`Why do you say "I know you're in a rush" yourself?`,questionEs:'¿Por qué dices tú mismo "sé que vas con prisa"?',options:["It shows respect and makes you seem polite","It makes the conversation feel shorter than it is","It takes away the excuse they were about to use","It gives you a natural reason to speak faster"],optionsEs:["Demuestra respeto y te hace parecer educado","Hace que la conversación parezca más corta de lo que es","Les quita la excusa que estaban a punto de usar","Te da un motivo natural para hablar más rápido"],correctIndex:2,explanation:"The rush is the most common escape line there is. Once you have said it and accepted it, they cannot use it against you.",explanationEs:"La prisa es la excusa de escape más común que hay. Una vez que la has dicho y la has aceptado, ya no pueden usarla contra ti."},{question:"After you offer the gift and turn around, what do you do?",questionEs:"Después de ofrecer el regalo y darte la vuelta, ¿qué haces?",options:["Glance back to check they are coming","Wait at the door and hold it open for them","Walk beside them so they do not feel alone","Walk in without checking they follow you"],optionsEs:["Miras atrás para comprobar que vienen","Esperas en la puerta y se la sujetas abierta","Andas a su lado para que no se sientan solos","Entras sin comprobar si te están siguiendo"],correctIndex:3,explanation:"Checking asks permission, and asking permission gives them a chance to say no. You look back only once you are already inside.",explanationEs:"Comprobar es pedir permiso, y pedir permiso les da la oportunidad de decir que no. Miras atrás solo cuando ya estás dentro."},{question:"Which way should the chair face?",questionEs:"¿Hacia dónde debe mirar la silla?",options:["Into the shop, away from the street","Towards the street so they feel free to go","Towards the counter and the card machine","Whichever way has the best light for the demo"],optionsEs:["Hacia dentro de la tienda, lejos de la calle","Hacia la calle para que se sientan libres de irse","Hacia la caja y el datáfono","Hacia donde haya mejor luz para la demo"],correctIndex:0,explanation:"If they can see the pavement moving past, they start thinking about being back out on it. Take the street out of their eyeline.",explanationEs:"Si ven pasar el movimiento de la acera, empiezan a pensar en volver a ella. Quita la calle de su campo de visión."},{question:"Her partner is stood behind the chair with his arms folded. First move?",questionEs:"Su pareja está detrás de la silla con los brazos cruzados. ¿Primer movimiento?",options:["Send him off to have a look round the centre while you work","Sit him down and give him a job — he is your judge","Ignore him completely and keep every word on her face","Tell him it is ladies’ business and turn your back on him"],optionsEs:["Mandarlo a dar una vuelta por el centro mientras trabajas","Sentarlo y darle un trabajo — es tu jurado","Ignorarlo del todo y ponerlo todo en la cara de ella","Decirle que esto es cosa de chicas y darle la espalda"],correctIndex:1,explanation:"He is not the problem, he is bored. In the chair with a job he becomes a second person selling to her — and she believes him. Standing back is the second move, and letting him go is the last one.",explanationEs:"No es el problema, está aburrido. En la silla y con un trabajo se convierte en una segunda persona vendiéndole a ella — y a él sí le cree. Apartarse es el segundo movimiento, y dejarlo ir es el último."}]},"close-demo":{id:"close-demo",categoryId:"closing",title:"The Demo And The Two Yeses",titleEs:"La Demo y los Dos Síes",subtitle:"One hand, one eye, one mirror — and two words you will need later",subtitleEs:"Una mano, un ojo, un espejo — y dos palabras que vas a necesitar después",duration:"9 min",icon:"Hand",order:3,xpReward:120,sections:[{type:"header",text:"The demo is not a demonstration",textEs:"La demo no es una demostración"},{type:"paragraph",text:"She is in the chair, facing the wall, and you have got about two minutes. Everything before this was getting her here. Everything after this is a number. The bit in the middle is not you showing off a product — it is you taking a stranger's hand, doing one eye, putting a mirror in front of her, and getting two words out of her mouth that you are going to hand straight back to her the moment she wobbles on the price. Do those four things in that order and the rest of the sale is arithmetic.",textEs:"Está en la silla, mirando a la pared, y tienes unos dos minutos. Todo lo de antes era para traerla hasta aquí. Todo lo de después es un número. Lo del medio no es que tú enseñes un producto — es que coges la mano de una desconocida, le haces un ojo, le pones un espejo delante y le sacas dos palabras de la boca que le vas a devolver en cuanto tiemble con el precio. Haz esas cuatro cosas en ese orden y el resto de la venta es aritmética."},{type:"subheader",text:"Take the hand. Do not ask twice.",textEs:"Coge la mano. No lo pidas dos veces."},{type:"paragraph",text:'You already asked once, out on the pavement, and she came in. That was your permission and you have got it. So you do not stand there going "would it be alright if I…?" — the second ask tells her there is something here to be nervous about, and now she is nervous. Put your hand out, palm up, and say it like it is the best part of your day. She gives it to you. They always do.',textEs:'Ya lo pediste una vez, fuera en la acera, y ella entró. Ese era tu permiso y ya lo tienes. Así que no te quedes ahí con un "¿te importa si...?" — la segunda vez que lo pides le estás diciendo que aquí hay algo por lo que ponerse nerviosa, y ya la has puesto nerviosa. Saca la mano, la palma hacia arriba, y dilo como si fuera lo mejor de tu día. Te la da. Siempre te la dan.'},{type:"script",text:'"Give me your hand — this is the good bit."',textEs:'"Dame la mano — esta es la parte buena."'},{type:"keypoint",text:"Touch is not a bonus here, it is the job. You cannot sell somebody their own face from a metre away. The second her hand is in yours she has stopped being a person walking past a kiosk and started being a person having something done for her — and people who are having something done for them do not walk out halfway through.",textEs:"Aquí tocar no es un extra, es el trabajo. No le puedes vender a alguien su propia cara desde un metro. En cuanto tiene la mano en la tuya deja de ser una persona que pasa por delante de un kiosco y pasa a ser una persona a la que le están haciendo algo — y a quien le están haciendo algo no se levanta y se va a la mitad."},{type:"subheader",text:"One eye. Never two.",textEs:"Un ojo. Nunca dos."},{type:"paragraph",text:"Do one eye and stop. Not because you are being stingy — because the eye you have not touched is the best salesperson in this shop. It is sitting right there next to the one you did, on the same face, in the same light, and it argues for you without you opening your mouth. Do both for free and you have given away the whole result for nothing, and left yourself with a conversation instead of a comparison.",textEs:"Haz un ojo y para. No por tacaño — porque el ojo que no has tocado es el mejor vendedor de esta tienda. Está justo al lado del que sí has hecho, en la misma cara, con la misma luz, y discute por ti sin que tú abras la boca. Hazle los dos gratis y has regalado el resultado entero, y te has quedado con una conversación en vez de con una comparación."},{type:"script",text:`"Look up for me — perfect. Now don't move. I'm only doing one, and you'll see why in a minute."`,textEs:'"Mira hacia arriba — perfecto. Ahora no te muevas. Solo hago uno, y ahora verás por qué."'},{type:"keypoint",text:`"I never do the other eye" is the owner's own line, and it is not stinginess — the second eye is a card, and you play it later. There is exactly one moment it comes out, and it is not kindness: it is the cover for the price coming down, at the top of the ladder, while she is thinking about standing up. That is in Asking For The Money. Until then, the untouched eye stays untouched and keeps arguing for you.`,textEs:'"Yo nunca hago el otro ojo" es la frase del jefe, y no es tacañería — el segundo ojo es una carta, y se juega después. Sale en un momento exacto, y no es por amabilidad: es la tapadera para que baje el precio, arriba en la escalera, mientras ella piensa en levantarse. Eso está en Pedir el Dinero. Hasta entonces, el ojo sin tocar sigue sin tocar y sigue discutiendo por ti.'},{type:"paragraph",text:"And talk the whole way through it. Silence while you are touching somebody's face is a very long time. But this is not filler — there is a speech, it is short, and it is the same every time. Get these across while your hands are busy and you have answered half the objections before they arrive.",textEs:"Y habla todo el rato. El silencio mientras le tocas la cara a alguien se hace larguísimo. Pero esto no es relleno — hay una explicación, es corta, y es la misma siempre. Suéltale esto mientras tienes las manos ocupadas y habrás contestado la mitad de las objeciones antes de que lleguen."},{type:"bullets",items:["ONCE A WEEK. That is the whole commitment, and it is the number you are going to ask her to promise you in a minute.","ONE SYRINGE, ONE YEAR. There are about sixty applications in there. Say it — a year of this in something the size of a pen is the value argument, and you are making it before she has heard a price.","SHE DOES NOT TOUCH IT. Not once it is on. If she touches it she destroys the result, and that is not a warning, it is you telling her the product is serious.","FIVE HOURS OF WORK. It needs at least five hours to do its thing. Which is also why she is not touching it.","AT HOME: DO NOT WASH IT OFF, DO NOT RUB IT OFF. People rub. Say it out loud or she goes home and undoes it in the shower, and then it is your product that did not work."],itemsEs:["UNA VEZ A LA SEMANA. Ese es todo el compromiso, y es el número que le vas a pedir que te prometa dentro de un minuto.","UNA JERINGA, UN AÑO. Ahí dentro hay unas sesenta aplicaciones. Dilo — un año de esto en algo del tamaño de un boli es el argumento de valor, y lo estás soltando antes de que haya oído un precio.","NO SE LO TOCA. Nada de tocarlo una vez puesto. Si se lo toca, destroza el resultado, y eso no es un aviso: es que le estás diciendo que el producto va en serio.","CINCO HORAS TRABAJANDO. Necesita cinco horas mínimo para hacer lo suyo. Que es también por lo que no se lo toca.","EN CASA: NI LAVARLO NI FROTARLO. La gente frota. Dilo en voz alta o se va a casa y lo deshace en la ducha, y entonces es tu producto el que no ha funcionado."]},{type:"subheader",text:"The tightening — relax her about it before she asks",textEs:"La tirantez — tranquilízala antes de que pregunte"},{type:"paragraph",text:"She is going to feel it pull. Some of them love it, some of them go quiet and start worrying they are going to walk around like that forever. Do not wait to be asked — get in first, and make it small.",textEs:"Va a notar cómo tira. A algunas les encanta, otras se quedan calladas preocupadas por si van a ir así toda la vida. No esperes a que te pregunten — adelántate y quítale importancia."},{type:"script",text:`"You feel that tightening? Good — that is it working. And no, you do not have to live like this." [Laugh] "It's the gym, isn't it. You train, the muscles are sore for a bit, and then they're better. Same thing. Give it five hours and it settles."`,textEs:'"¿Notas que tira? Bien — eso es que está funcionando. Y no, no vas a vivir así." [Ríete] "Es como el gimnasio, ¿no? Entrenas, te quedan agujetas un rato, y luego estás mejor. Es lo mismo. Dale cinco horas y se asienta."'},{type:"subheader",text:"And while your hands are busy, find out who they are",textEs:"Y con las manos ocupadas, entérate de quiénes son"},{type:"paragraph",text:"This is the part that looks like small talk and is not. You have got two minutes of somebody's undivided attention and a partner standing behind them with nothing to do. Where are you from? Where are you staying? How long have you been here? And to him, because he is the one who can kill this with one word: what team does he support. Then give something back — you have got family from there, you have been, you loved it. Now you are not a seller any more, you are the one who knows the place.",textEs:"Esta es la parte que parece charla y no lo es. Tienes dos minutos de atención absoluta de alguien y una pareja detrás sin nada que hacer. ¿De dónde sois? ¿Dónde os alojáis? ¿Cuánto lleváis aquí? Y a él, porque es el que puede cargarse esto con una palabra: de qué equipo es. Y luego devuelve algo — tienes familia de allí, has estado, te encantó. Ya no eres un vendedor, eres el que conoce el sitio."},{type:"script",text:`"Where are you two from? …No way — my cousin lives twenty minutes from there, I was over last summer. And you, sir, who do you support? …Don't tell her I laughed." [To him] "You watch this side, you're my witness."`,textEs:'"¿De dónde sois vosotros? …¡No me digas! Mi primo vive a veinte minutos de ahí, estuve el verano pasado. Y tú, jefe, ¿de qué equipo eres? …No le digas que me he reído." [A él] "Tú vigila este lado, que eres mi testigo."'},{type:"keypoint",text:"Nobody who is laughing is checking their watch, and nobody who has just told you about their holiday walks out on you thirty seconds later. The husband is the one to win here — bored, he is the reason she stands up. Given a job and a football team, he is a second person selling to her, and she believes him.",textEs:"Nadie que se está riendo mira el reloj, y nadie que acaba de contarte lo de sus vacaciones se levanta y se va treinta segundos después. Al que hay que ganarse aquí es al marido — aburrido, es el motivo por el que ella se levanta. Con un trabajo y un equipo de fútbol, es una segunda persona vendiéndole a ella, y a él sí le cree."},{type:"subheader",text:"Take the promise BEFORE you show her anything",textEs:"Cógele la promesa ANTES de enseñarle nada"},{type:"paragraph",text:"Still one eye done, mirror still face down. Before she has seen a single thing, you ask her to commit to using it — and because she has not seen the result yet, it costs her nothing to say yes. That is exactly why you ask now. Ninety seconds later she is looking at her own face with a promise already out of her mouth.",textEs:"Todavía con un ojo hecho y el espejo boca abajo. Antes de que haya visto absolutamente nada, le pides que se comprometa a usarlo — y como todavía no ha visto el resultado, decir que sí no le cuesta nada. Por eso se lo pides ahora. Noventa segundos después está mirándose la cara con una promesa ya fuera de su boca."},{type:"script",text:`"Let me ask you something before you look. If everything I've just told you is sunshine and rainbows — if it does exactly what I say it does — would you actually use it once a week at home? …Yeah? Good. Remember you said that."`,textEs:'"Déjame preguntarte una cosa antes de que mires. Si todo lo que te acabo de contar es de color de rosa — si hace exactamente lo que te digo — ¿lo usarías de verdad una vez a la semana en casa? …¿Sí? Bien. Acuérdate de que lo has dicho."'},{type:"tip",text:'This is the second of the two yeses, collected early. When you ask it again after the mirror it is no longer a question — it is a confirmation, and she has now said it twice. "Remember you said that" is the whole reason it is worth taking here.',textEs:'Este es el segundo de los dos síes, cogido antes de tiempo. Cuando se lo vuelvas a preguntar después del espejo ya no es una pregunta — es una confirmación, y ya lo ha dicho dos veces. El "acuérdate de que lo has dicho" es justo por lo que merece la pena cogerlo aquí.'},{type:"subheader",text:"The mirror — and then your mouth shuts",textEs:"El espejo — y luego te callas"},{type:"paragraph",text:"This is the moment sellers talk over, and it costs them the sale. You hand her the mirror and you stop. Not a little pause — a proper silence, three or four seconds, while she finds it herself. The first sound in that gap has to come out of her, not out of you. If you narrate it, it is your opinion. If she finds it, it is a fact.",textEs:"Este es el momento que los vendedores pisan hablando, y les cuesta la venta. Le das el espejo y te callas. No una pausita — un silencio de verdad, tres o cuatro segundos, mientras lo encuentra ella sola. El primer sonido de ese hueco tiene que salir de ella, no de ti. Si se lo cuentas tú, es tu opinión. Si lo encuentra ella, es un hecho."},{type:"script",text:`"Promise me you won't scream." (Give her the mirror. Say nothing.) … "Now look at the other one. Go on — compare them."`,textEs:'"Prométeme que no vas a gritar." (Dale el espejo. No digas nada.) … "Ahora mira el otro. Venga — compáralos."'},{type:"tip",text:"Whatever she says first is what she actually walked in with — the bags, the tired look, the line she keeps pointing at. Keep it. You will be putting her own word back in front of her in about ninety seconds.",textEs:"Lo primero que diga es con lo que ha entrado de verdad — las bolsas, la cara de cansada, la arruguita que no para de señalar. Guárdatelo. Le vas a poner su propia palabra delante otra vez dentro de noventa segundos."},{type:"divider"},{type:"header",text:"The two yeses — this is the whole lesson",textEs:"Los dos síes — esta es toda la lección"},{type:"paragraph",text:"Mirror still in her hand. Before any number, before the ladder, before anything at all, you ask her two questions. They are small, they are closed, and both times you wait for the actual word.",textEs:"El espejo todavía en su mano. Antes de ningún número, antes de la escalera, antes de nada, le haces dos preguntas. Son pequeñas, son cerradas, y las dos veces esperas a que salga la palabra."},{type:"script",text:'"Do you like it?"',textEs:'"¿Te gusta?"'},{type:"paragraph",text:`Then wait. Do not fill it. Do not answer it for her with "you love it, don't you?" — that is you saying yes, not her, and you cannot quote yourself back at somebody. A nod is not enough either. You want the word, out loud, in her voice, because in two minutes you are going to repeat it to her.`,textEs:'Y espera. No lo rellenes. No se lo contestes tú con un "te encanta, ¿a que sí?" — ese sí lo dices tú, no ella, y a nadie le puedes citar tus propias palabras. Con que asienta tampoco vale. Quieres la palabra, en voz alta, con su voz, porque dentro de dos minutos se la vas a repetir.'},{type:"script",text:'"And if you had it at home — would you actually use it? Be honest with me."',textEs:'"¿Y si lo tuvieras en casa — lo usarías de verdad? Sé sincera conmigo."'},{type:"paragraph",text:'"Be honest with me" is the bit doing the work. It hands her a clean, easy way to say no — which is precisely why she says yes. And on the rare day she says "honestly, probably not", she has just saved you six minutes and told you to stop selling and start chatting. Nothing lost.',textEs:'El "sé sincera conmigo" es lo que trabaja ahí. Le da una forma limpia y fácil de decir que no — que es justo por lo que dice que sí. Y el día raro que te diga "la verdad, seguramente no", te acaba de ahorrar seis minutos y te ha dicho que dejes de vender y te pongas a charlar. No has perdido nada.'},{type:"keypoint",text:"Once she has said both of them out loud, she has nothing left to object to except the price. That is the entire point of them. She cannot tell you it does not work — she just watched it work on her own face and said she liked it. She cannot tell you she would not use it — she said she would. All that is left is a number, and a number is the one thing you have a whole ladder for.",textEs:"En cuanto ha dicho los dos en voz alta, no le queda nada que objetar salvo el precio. Ese es todo el sentido. No te puede decir que no funciona — acaba de verlo funcionar en su propia cara y ha dicho que le gusta. No te puede decir que no lo usaría — ha dicho que sí. Solo queda un número, y un número es justo para lo que tienes una escalera entera."},{type:"tip",text:"Yes, both of them are closed questions, and yes, you were taught to ask open ones. That is for the chat outside, where you are digging for information. Here you are not after a conversation — you are after a word on the record, in her own voice. Closed is the point.",textEs:"Sí, las dos son preguntas cerradas, y sí, te enseñaron a hacerlas abiertas. Eso es para la charla de fuera, donde estás rascando información. Aquí no buscas conversación — buscas una palabra grabada, con su propia voz. Que sea cerrada es lo que la hace funcionar."},{type:"divider"},{type:"subheader",text:"What it costs you to skip them",textEs:"Lo que te cuesta saltártelos"},{type:"paragraph",text:`Every answer you get taught for later leans on those two words. "I have to think about it" — about what, exactly? If she never said she liked it, you have got nothing to give back, and you are down to arguing about a cream. "I'll ask my husband" — ask him what? You never got her to say she wanted it herself, so now it genuinely is his decision. Skip the two yeses and you spend the last five minutes defending a product, when you should be haggling over a number with somebody who has already decided she wants it.`,textEs:'Todas las respuestas que te enseñan para después se apoyan en esas dos palabras. "Me lo tengo que pensar" — ¿pensar el qué, exactamente? Si nunca dijo que le gustaba, no tienes nada que devolverle, y te quedas discutiendo sobre una crema. "Se lo pregunto a mi marido" — ¿preguntarle el qué? Nunca conseguiste que dijera que lo quería ella, así que ahora sí que es decisión de él. Sáltate los dos síes y te pasas los últimos cinco minutos defendiendo un producto, cuando deberías estar regateando un número con alguien que ya ha decidido que lo quiere.'},{type:"script",text:`And when it comes: "You told me you like it. You told me you'd use it. So it isn't a question of whether — it's just which of the two suits you better."`,textEs:'Y cuando llegue el momento: "Me has dicho que te gusta. Me has dicho que lo usarías. Así que no es si sí o si no — es simplemente cuál de las dos te va mejor."'},{type:"paragraph",text:"And say the thing out loud, because it is true and because naming it is what turns a conversation into a haggle. Once she has said both yeses there is exactly one subject left in the room, and pretending otherwise just gives her somewhere else to go.",textEs:"Y dilo en voz alta, porque es verdad y porque nombrarlo es lo que convierte una conversación en un regateo. En cuanto ha dicho los dos síes solo queda un tema en la sala, y disimular solo le da otro sitio al que irse."},{type:"script",text:`"Come on, my love — the only thing left here is the money. You told me you can use it. You told me you like it. So it's the money, and the money we can talk about."`,textEs:'"Venga, cariño — aquí lo único que queda es el dinero. Me has dicho que lo puedes usar. Me has dicho que te gusta. Así que es el dinero, y del dinero sí podemos hablar."'},{type:"keypoint",text:"That sentence is the door into the ladder, and the ladder is a different lesson — Asking For The Money. Everything up to here was making sure that when you start walking the price down, you are haggling with somebody who has already decided she wants it. That is the only kind of haggle worth having.",textEs:"Esa frase es la puerta de entrada a la escalera, y la escalera es otra lección — Pedir el Dinero. Todo lo de hasta aquí era para asegurarte de que, cuando empieces a bajar el precio, estás regateando con alguien que ya ha decidido que lo quiere. Ese es el único regateo que merece la pena."},{type:"divider"},{type:"subheader",text:"And the rare one: cutting it",textEs:"Y la rara: cortar la demo"},{type:"paragraph",text:`Most times you finish what you started. That is the default and it is the owner's default too — a demo you abandoned halfway is a demo you paid for and never cashed. But every so often you are working a corpse: she is already half out of the chair, the husband has panicked "come on, let's go" for the seventh time, and the vibe has gone out of the room. You can feel it. That is not a customer you are going to close, and every minute you spend grinding it is a minute you are not spending on somebody who wants to be sat there.`,textEs:'La mayoría de las veces terminas lo que has empezado. Ese es el que vale por defecto y es el del jefe también — una demo que abandonas a la mitad es una demo que has pagado y no has cobrado. Pero de vez en cuando estás trabajando un cadáver: ella ya está medio levantada de la silla, el marido se ha puesto nervioso con un "venga, que nos vamos" por séptima vez, y el buen rollo se ha ido de la sala. Se nota. Esa no es una clienta que vayas a cerrar, y cada minuto que le dedicas es un minuto que no le dedicas a alguien que sí quiere estar ahí sentado.'},{type:"keypoint",text:"Cut it, and cut it warm. You do not hand her anything to take away, you do not put a number on a bit of paper, you do not book her in for another day — that is the walkaway wearing a nice coat, and it costs you a customer who might still have bought. You just stop, you smile, you thank her, and you go and find the next one. Thirty seconds, no sulking.",textEs:"Córtala, y córtala con buen rollo. No le das nada para llevarse, no le apuntas un número en un papel, no la citas para otro día — eso es la fuga con un abrigo bonito, y te cuesta una clienta que a lo mejor todavía compraba. Simplemente paras, sonríes, le das las gracias y vas a por la siguiente. Treinta segundos, y sin enfadarte."},{type:"tip",text:'Be honest with yourself about which one you are in, because "the vibe was not there" is the easiest excuse in this shop to reach for. Bored is not the same as dead. If she is still in the chair and still answering you, she is alive and the demo carries on.',textEs:'Sé sincero contigo mismo sobre en cuál de las dos estás, porque "no había buen rollo" es la excusa más fácil de coger en esta tienda. Aburrida no es lo mismo que muerta. Si sigue en la silla y sigue contestándote, está viva y la demo continúa.'},{type:"tip",text:"The whole demo in six moves: the hand, one eye, keep talking, the mirror, the silence, the two yeses. Then, and only then, the number. If a sale went wrong and you cannot work out where, start by asking yourself which of those six you skipped.",textEs:"La demo entera en seis movimientos: la mano, un ojo, sigue hablando, el espejo, el silencio, los dos síes. Y entonces, y solo entonces, el número. Si una venta se te ha torcido y no sabes dónde, empieza por preguntarte cuál de esos seis te saltaste."},{type:"tip",text:'Carry makeup remover wipes and toner, and prep the face BEFORE you start. Most demos that "do not work" are not the product at all — they are sunscreen, moisturiser or foundation sitting between your finger and her skin, and you cannot see any of it until nothing happens. Thirty seconds of wiping is the difference between the line moving and you standing there explaining why it has not.',textEs:'Lleva toallitas desmaquillantes y tónico, y prepárale la cara ANTES de empezar. La mayoría de las demos que "no funcionan" no son culpa del producto — son la crema solar, la hidratante o la base puestas entre tu dedo y su piel, y no lo ves hasta que no pasa nada. Treinta segundos de limpiar son la diferencia entre que la arruga se mueva y que te quedes ahí explicando por qué no.'}],quiz:[{question:"You are mid-demo. One eye done, mirror still face down. When do you ask her whether she would use it once a week at home?",questionEs:"Estás a media demo. Un ojo hecho, el espejo todavía boca abajo. ¿Cuándo le preguntas si lo usaría una vez a la semana en casa?",options:["Right now, before she sees anything — a promise costs her nothing yet","Only at the very end, once she has heard what it costs","Never — asking gives her an opening to say no to you","After the mirror, and never before, or the question means nothing"],optionsEs:["Ahora mismo, antes de que vea nada — una promesa todavía no le cuesta nada","Solo al final del todo, cuando ya sepa lo que vale","Nunca — preguntarlo le abre la puerta a decirte que no","Después del espejo, y nunca antes, o la pregunta no vale nada"],correctIndex:0,explanation:'Ask it before the reveal and it is free to say yes to — she has not seen the result, so agreeing costs her nothing. Ninety seconds later she is looking at her own face with a promise already out of her mouth, and when you ask it again after the mirror it is a confirmation rather than a question. "Remember you said that" is the whole reason you take it early.',explanationEs:'Pregúntalo antes del momento del espejo y decir que sí le sale gratis — todavía no ha visto el resultado, así que aceptar no le cuesta nada. Noventa segundos después está mirándose la cara con una promesa ya fuera de su boca, y cuando se lo vuelvas a preguntar después del espejo es una confirmación, no una pregunta. El "acuérdate de que lo has dicho" es justo por lo que se coge antes.'},{question:"She has gone quiet — she can feel it tightening and she is starting to look worried. What do you say?",questionEs:"Se ha quedado callada — nota que tira y está empezando a preocuparse. ¿Qué le dices?",options:["Nothing — draw attention to it and she will only worry more",'"That is normal for most skin types, it should settle down eventually."','"That is it working — and no, you do not live like this. It is the gym: sore for a bit, then better."','"Let me take it off and we will try something gentler on you instead."'],optionsEs:["Nada — si se lo señalas solo se va a preocupar más",'"Eso es normal en casi todas las pieles, debería asentarse con el tiempo."','"Eso es que funciona — y no, no vas a vivir así. Es el gimnasio: agujetas un rato y luego mejor."','"Déjame quitártelo y probamos algo más suave contigo."'],correctIndex:2,explanation:"Get in before she asks, and make it small. The gym line does two things at once: it explains the sensation as the product working, and it promises her she is not walking around like this — five hours and it settles. Saying nothing leaves her worrying, hedging sounds like you are not sure, and taking it off throws away the demo you have just done.",explanationEs:"Adelántate a la pregunta y quítale importancia. La frase del gimnasio hace dos cosas a la vez: explica la sensación como que el producto está trabajando, y le promete que no va a ir así por la vida — cinco horas y se asienta. Callarte la deja preocupada, andarte con rodeos suena a que no lo tienes claro, y quitárselo tira a la basura la demo que acabas de hacer."},{question:"One eye done, mirror in her hand, she is delighted. What comes out of your mouth next?",questionEs:"Un ojo hecho, el espejo en su mano, está encantada. ¿Qué es lo siguiente que sale de tu boca?",options:["The whole price ladder, starting from the Europe number","An offer to do the other eye for her as well","Do you like it — and would you use it at home","The full list of what is in it and how it works"],optionsEs:["La escalera de precios entera, empezando por Europa","Ofrecerle hacerle también el otro ojo","¿Te gusta? — y ¿lo usarías en casa?","La lista completa de lo que lleva y cómo funciona"],correctIndex:2,explanation:"The two yeses come before any number. Once she has said both out loud, the only thing left she can object to is the price — and the price is what the ladder is for.",explanationEs:"Los dos síes van antes de cualquier número. Cuando ha dicho los dos en voz alta, lo único que le queda por objetar es el precio — y para el precio está la escalera."},{question:'She says "yes, I like it" — then only nods when you ask if she would use it. What now?',questionEs:'Dice "sí, me gusta" — y luego solo asiente cuando le preguntas si lo usaría. ¿Y ahora?',options:["Take the nod, it means the same thing, and go to the price","Ask again, lightly, and wait until she says the word",'Answer it for her — "of course you would" — and carry on',"Move on fast, before she has a chance to change her mind"],optionsEs:["Coge el gesto, significa lo mismo, y ve al precio","Vuelve a preguntar, con ligereza, y espera a que lo diga",'Contéstalo tú — "claro que sí" — y sigue adelante',"Pasa rápido, antes de que le dé tiempo a cambiar de idea"],correctIndex:1,explanation:"You need the word, out loud, in her voice — because in two minutes you are going to repeat it back to her. You cannot hand somebody a nod, and you certainly cannot quote yourself.",explanationEs:"Necesitas la palabra, en voz alta, con su voz — porque dentro de dos minutos se la vas a repetir. Un gesto no se le puede devolver, y citarte a ti mismo menos todavía."},{question:"She asks you to do the other eye too, before she has bought anything. What do you say?",questionEs:"Te pide que le hagas el otro ojo también, antes de haber comprado nada. ¿Qué le dices?",options:[`"If you buy it, I'll do the other one, yeah?"`,"Do it — a delighted customer argues better than an untouched eye","Do it, then climb a rung to cover the product you have used up","Say no flatly and change the subject before she can ask again"],optionsEs:['"Si te lo llevas, te hago el otro, ¿vale?"',"Hazlo — una clienta encantada convence más que un ojo sin tocar","Hazlo, y luego sube un escalón para cubrir lo que has gastado","Dile que no en seco y cambia de tema antes de que insista"],correctIndex:0,explanation:"You never give it away, but you do not refuse it either — you put a price on it. The untouched eye is the best salesperson in the shop, so the only thing that buys it is the sale itself.",explanationEs:"No lo regalas nunca, pero tampoco lo niegas — le pones precio. El ojo sin tocar es el mejor vendedor de la tienda, así que lo único que lo compra es la venta."}]},"close-2":{id:"close-2",categoryId:"closing",title:"Asking For The Money",titleEs:"Pedir el Dinero",subtitle:"The moment most sellers get quiet, and should not",subtitleEs:"El momento en que la mayoría se calla, y no debería",duration:"6 min",icon:"Coins",order:4,xpReward:120,sections:[{type:"header",text:"Ask which, never whether",textEs:"Pregunta cuál, nunca si"},{type:"paragraph",text:"Almost everybody pays by card. So do not ask them whether they are buying — assume they are, and ask a small, easy question about how. A question about the method is a question that only makes sense if the sale is already happening.",textEs:"Casi todo el mundo paga con tarjeta. Así que no les preguntes si van a comprar — dalo por hecho y hazles una pregunta pequeña y fácil sobre cómo. Una pregunta sobre el método solo tiene sentido si la venta ya está pasando."},{type:"script",text:`"I guess you're paying by card, aren't you? Visa or Mastercard?"`,textEs:'"Supongo que pagas con tarjeta, ¿no? ¿Visa o Mastercard?"'},{type:"subheader",text:"Then do NOT go silent",textEs:"Y luego NO te calles"},{type:"paragraph",text:`You will have been told to ask for the sale and then shut up. Not here. The silence is where they start reconsidering. They answer something vague — "I don't know… Visa" — and you keep moving immediately.`,textEs:'Te habrán dicho que pidas la venta y luego te calles. Aquí no. El silencio es donde empiezan a replanteárselo. Contestan algo vago — "no sé... Visa" — y tú sigues moviéndote al momento.'},{type:"script",text:`"Perfect, don't worry — I'll bring it over to you."`,textEs:'"Perfecto, no te preocupes — te la traigo yo."'},{type:"keypoint",text:"Then go and get the card machine. The next thing that happens is a machine arriving, not a pause for them to fill.",textEs:"Y ve a por el datáfono. Lo siguiente que pasa es que llega una máquina, no una pausa que tengan que rellenar."},{type:"divider"},{type:"header",text:"When they stall instead of saying yes",textEs:"Cuando dudan en vez de decir que sí"},{type:"paragraph",text:'"Let me think about it" is not new information. Everything you need to answer it, they have already told you in the last two minutes. So ask them, straight and friendly, what there actually is to think about.',textEs:'"Me lo tengo que pensar" no es información nueva. Todo lo que necesitas para responder ya te lo han dicho ellos en los últimos dos minutos. Así que pregúntales, directo y con buen rollo, qué hay que pensar exactamente.'},{type:"script",text:'"What do you actually need to think about?"',textEs:'"¿Qué te tienes que pensar exactamente?"'},{type:"paragraph",text:"And then, without waiting long, hand their own words back to them:",textEs:"Y luego, sin esperar mucho, devuélveles sus propias palabras:"},{type:"script",text:`"You already told me you like it. You told me you'd use it. You're not going to walk up and down the street and come back to a different price — you know exactly what it does. It's just whether you want to treat yourself or not. It's not a mortgage."`,textEs:'"Ya me has dicho que te gusta. Me has dicho que lo usarías. No vas a dar una vuelta por la calle y volver con otro precio — sabes perfectamente lo que hace. Es simplemente si quieres darte un capricho o no. Tampoco es una hipoteca."'},{type:"paragraph",text:"Notice what that does. Every single clause is something they said, not something you are claiming. You are not arguing with them — you are reminding them that they already decided, and shrinking the decision down to its real size.",textEs:"Fíjate en lo que hace eso. Cada frase es algo que dijeron ellos, no algo que afirmas tú. No estás discutiendo con ellos — les estás recordando que ya lo habían decidido, y reduciendo la decisión a su tamaño real."},{type:"tip",text:`"It's not a mortgage" is the whole tone of this shop in four words. You are not pressuring anybody. You are pointing out that this is a small, pleasant decision and they are treating it like a big frightening one.`,textEs:'"Tampoco es una hipoteca" es todo el tono de esta tienda en cuatro palabras. No estás presionando a nadie. Estás señalando que esta es una decisión pequeña y agradable y la están tratando como si fuera enorme y aterradora.'},{type:"divider"},{type:"header",text:"The other eye is not a favour — it is how you close",textEs:"El otro ojo no es un favor — es cómo cierras"},{type:"paragraph",text:"She has not said no. She has gone quiet, she is looking at her bag, her weight has shifted forward in the chair — and you are stood at {currency}175. This is the moment the second eye comes out, and it has nothing to do with being generous.",textEs:"No ha dicho que no. Se ha quedado callada, está mirando el bolso, ha echado el peso hacia delante en la silla — y tú estás en {currency}175. Este es el momento en el que sale el segundo ojo, y no tiene nada que ver con ser generoso."},{type:"script",text:'"You know what, let me fix your other eye real quick."',textEs:'"¿Sabes qué? Déjame arreglarte el otro ojo rapidito."'},{type:"keypoint",text:"And while you are doing that eye, the voucher comes out. That is the entire point of the move. Her chin is up, your hands are on her face, the room feels finished and nobody is negotiating anything — and that is exactly when the number moves: {currency}175 down to {currency}140, the extra 20%. A price drop that arrives inside a moment about something else does not land like a price drop. It lands like somebody looking after her.",textEs:"Y mientras le haces ese ojo, sale el cupón. Ese es todo el sentido del movimiento. Ella tiene la barbilla arriba, tú tienes las manos en su cara, la sala parece terminada y nadie está negociando nada — y justo ahí se mueve el número: de {currency}175 a {currency}140, el 20% extra. Una bajada de precio que llega dentro de un momento que va de otra cosa no suena a bajada de precio. Suena a que alguien la está cuidando."},{type:"script",text:`"You know what — I'll do that for you. But you're being greedy. I can only do it on the regular size."`,textEs:'"¿Sabes qué? Te lo hago. Pero eres una avariciosa. Solo te lo puedo hacer en el tamaño normal."'},{type:"keypoint",text:`Three other ways the second eye comes up. She has paid — she gets it done, no argument, no theatre, just do it. She asks for it before she has bought anything — you do not refuse and you do not give it away, you put a price on it: "If you buy it, I'll do the other one, yeah?" And the rare one: she has been abandoned in the middle of the demo, the husband has gone, the friends have gone, there is nobody behind her at all. That is the single place in this whole shop where the door is the right answer — "Go think about it, see how it looks, come back later. I'll fix your other eye, even if you don't buy anything." She leaves with one eye done and a reason to walk back in. That is a hook, not a polite exit, and it is not available to you on any other day.`,textEs:'Otras tres formas en las que aparece el segundo ojo. Ha pagado — se lo haces, sin discutir, sin teatro, se lo haces y ya. Te lo pide antes de comprar nada — ni se lo niegas ni se lo regalas, le pones precio: "Si te lo llevas, te hago el otro, ¿vale?". Y la rara: está abandonada en mitad de la demo, el marido se ha ido, las amigas se han ido, no hay nadie detrás de ella. Ese es el único sitio de toda esta tienda donde la puerta es la respuesta correcta — "Piénsatelo, mira cómo queda, y vuelve luego. Te arreglo el otro ojo, aunque no te lleves nada". Se va con un ojo hecho y con un motivo para volver a entrar. Eso es un anzuelo, no una salida educada, y no lo tienes disponible ningún otro día.'},{type:"divider"},{type:"header",text:"One voucher. After that you call a manager",textEs:"Un cupón. Después llamas al encargado"},{type:"paragraph",text:"There is no voucher. You make it up on the spot, because a price that just falls was never a price — the voucher is the reason it fell. And you get one. {currency}175 to {currency}140, the extra 20%, once, inside the second eye. Usually you do not need anything else.",textEs:"No hay ningún cupón. Te lo inventas sobre la marcha, porque un precio que simplemente cae nunca fue un precio — el cupón es el motivo por el que ha caído. Y tienes uno. De {currency}175 a {currency}140, el 20% extra, una vez, dentro del segundo ojo. Normalmente no necesitas nada más."},{type:"keypoint",text:"There is no second voucher. Invent another one and you have just told her the first one was invented too — and from that second on, every number that comes out of your mouth is made up. If {currency}140 does not do it, the theatre changes: now you go full market. Her number out loud, the pause, the face, hands in the air. And the last rung is not yours. {currency}100 comes from a manager, and you go and get one.",textEs:"No hay un segundo cupón. Invéntate otro y acabas de decirle que el primero también te lo inventaste — y a partir de ese segundo, cada número que sale de tu boca es inventado. Si {currency}140 no lo consigue, cambia el teatro: ahora te vas a mercado del todo. Su número en voz alta, la pausa, la cara, las manos arriba. Y el último escalón no es tuyo. Los {currency}100 los da un encargado, y vas tú a buscarlo."},{type:"script",text:`"Right, you're killing me. Give me two seconds — I'm going to go and ask my manager. I'm promising you nothing, alright?"`,textEs:'"Vale, me estás matando. Dame dos segundos — voy a preguntarle a mi encargado. No te prometo nada, ¿eh?"'},{type:"tip",text:"A seller who can reach the floor on their own has no floor. That is the whole reason the last rung belongs to somebody else — the moment she works out that {currency}100 is in your pocket, that is where every customer starts, and where every one of them finishes.",textEs:"Un vendedor que puede llegar al mínimo él solo no tiene mínimo. Ese es todo el motivo de que el último escalón sea de otra persona — en cuanto ella pilla que los {currency}100 los llevas tú en el bolsillo, ahí es donde empieza cada cliente, y donde acaba cada uno de ellos."}],quiz:[{question:"What is the assumptive card close actually asking?",questionEs:"¿Qué está preguntando de verdad el cierre asumiendo la tarjeta?",options:["Whether they would like to buy the product today","Which card they are going to pay with","Whether they would prefer to pay in cash","How much they were planning to spend"],optionsEs:["Si les gustaría comprar el producto hoy","Con qué tarjeta van a pagar","Si prefieren pagar en efectivo","Cuánto tenían pensado gastarse"],correctIndex:1,explanation:"You ask WHICH, never WHETHER. A question about the payment method only makes sense if the sale is already happening.",explanationEs:"Preguntas CUÁL, nunca SI. Una pregunta sobre el método de pago solo tiene sentido si la venta ya está pasando."},{question:`What do you do straight after they answer "I don't know… Visa"?`,questionEs:'¿Qué haces justo después de que contesten "no sé... Visa"?',options:["Stay quiet and let them settle into the decision","Ask them to confirm they are happy to go ahead","Repeat the offer once more so it is clear","Say you will bring the machine, and go get it"],optionsEs:["Te quedas callado y dejas que asienten la decisión","Les pides que confirmen que quieren seguir adelante","Repites la oferta una vez más para que quede claro","Dices que traes el datáfono, y vas a por él"],correctIndex:3,explanation:"The silence is where they reconsider. Keep moving — the next thing that happens should be a machine arriving, not a pause.",explanationEs:"El silencio es donde se lo replantean. Sigue moviéndote — lo siguiente que pasa debe ser que llega una máquina, no una pausa."},{question:'What makes the answer to "let me think about it" work?',questionEs:'¿Qué hace que funcione la respuesta a "me lo tengo que pensar"?',options:["Every point in it is something they already said","It offers them a better price to decide now","It warns them the offer disappears at closing time","It compares them to other customers who bought"],optionsEs:["Cada punto es algo que ya dijeron ellos mismos","Les ofrece un precio mejor por decidir ahora","Les avisa de que la oferta se acaba al cerrar","Los compara con otros clientes que sí compraron"],correctIndex:0,explanation:"You are not arguing or adding pressure — you are handing their own words back and shrinking the decision to its real size.",explanationEs:"No estás discutiendo ni añadiendo presión — les devuelves sus propias palabras y reduces la decisión a su tamaño real."},{question:"She has gone quiet at {currency}175 and her hand is on her bag. What do you do?",questionEs:"Se ha quedado callada en {currency}175 y tiene la mano en el bolso. ¿Qué haces?",options:["Drop to {currency}140 and tell her that is your last price","Ask her straight out what number she had in her head","Fix her other eye — and move the number while you do it","Say nothing and give her room to make up her own mind"],optionsEs:["Bajar a {currency}140 y decirle que es tu último precio","Preguntarle a bocajarro qué número tenía en la cabeza","Hacerle el otro ojo — y mover el número mientras se lo haces","No decir nada y darle espacio para que lo decida ella"],correctIndex:2,explanation:"Chin up, your hands on her face, nobody negotiating anything — that is when the price moves. The drop arrives inside a moment that is about something else, so it lands like you looking after her.",explanationEs:"Barbilla arriba, tus manos en su cara, nadie negociando nada — ahí es cuando se mueve el precio. La bajada llega dentro de un momento que va de otra cosa, así que suena a que la estás cuidando."},{question:"The voucher has been and gone and she is still not moving. Now what?",questionEs:"El cupón ya ha salido y ella sigue sin moverse. ¿Y ahora qué?",options:["Invent a second voucher — it worked the first time","Take her to {currency}100 yourself and get the sale done","Stop the ladder there and leave the number where it is","Go full market, then fetch a manager for the last rung"],optionsEs:["Inventarte un segundo cupón — funcionó la primera vez","Llevarla tú a {currency}100 y cerrar la venta de una vez","Parar la escalera ahí y dejar el número donde está","Ir a mercado del todo, y buscar al encargado para el final"],correctIndex:3,explanation:"One voucher, once. A second one tells her the first was invented too. The bottom rung belongs to a manager — a seller who can reach the floor alone has no floor.",explanationEs:"Un cupón, una vez. Un segundo le dice que el primero también te lo inventaste. El escalón de abajo es del encargado — un vendedor que llega al mínimo solo no tiene mínimo."}]},"close-3":{id:"close-3",categoryId:"closing",title:"The Counter",titleEs:"El Cobro",subtitle:"The ninety seconds between yes and paid",subtitleEs:"Los noventa segundos entre el sí y el pago",duration:"4 min",icon:"CreditCard",order:5,xpReward:120,sections:[{type:"header",text:"Charge them where they are sitting",textEs:"Cóbrales donde están sentados"},{type:"paragraph",text:"We do not walk anybody to a till. The card machine goes to the customer, in the chair, where they already said yes. Every metre between the yes and the payment is a metre they can change their mind in — and standing a person up is the single easiest way to lose a sale you had already made.",textEs:"Aquí no llevamos a nadie a la caja. El datáfono va al cliente, a la silla, donde ya han dicho que sí. Cada metro entre el sí y el pago es un metro para que cambien de opinión — y levantar a una persona es la forma más fácil que hay de perder una venta que ya tenías hecha."},{type:"subheader",text:"The dead air while the terminal thinks",textEs:"El silencio mientras el datáfono piensa"},{type:"paragraph",text:"It genuinely does not matter what you say here. Joke with them. Have some fun. Ask about their trip. The content is irrelevant and the silence is not — a customer left alone with their own thoughts while a machine beeps is a customer doing arithmetic.",textEs:"Aquí de verdad da igual lo que digas. Bromea con ellos. Pásalo bien. Pregúntales por su viaje. El contenido es irrelevante y el silencio no lo es — un cliente a solas con sus pensamientos mientras pita una máquina es un cliente haciendo cuentas."},{type:"divider"},{type:"header",text:"Someone else walks in mid-sale",textEs:"Entra alguien más en mitad de la venta"},{type:"paragraph",text:'Acknowledge them immediately and warmly, and give them a number — "two seconds" — so they know they have not been ignored. Then go straight back to the person in the chair.',textEs:'Reconócelos al momento y con buen rollo, y dales un número — "dos segundos" — para que sepan que no los estás ignorando. Y vuelve directo a la persona de la silla.'},{type:"script",text:`"Hi darling, how are you doing? Don't worry, I'll be two seconds with you."`,textEs:'"Hola guapa, ¿qué tal? No te preocupes, estoy contigo en dos segundos."'},{type:"paragraph",text:"If you cannot hold both, call a colleague over. And if the person who walked in is a returning customer, call the manager — a customer who came back is worth more than the one you are closing, and they should be handled by whoever can look after them properly.",textEs:"Si no puedes con los dos, llama a un compañero. Y si quien ha entrado es un cliente que repite, llama al encargado — un cliente que vuelve vale más que el que estás cerrando, y debe atenderlo quien pueda cuidarlo como toca."},{type:"keypoint",text:"That holds for the woman who bought from us six months ago and has walked back in with the empty box, too. She is not your sale to price. Get the manager; if he is not on the floor, get whoever out there has been doing this the longest. Somebody who came back once will do it again if the right person looks after her, and quoting her a number off your own bat is how that stops happening.",textEs:"Eso vale también para la señora que nos compró hace seis meses y ha vuelto a entrar con la caja vacía. No es tu venta y no eres tú quien le pone precio. Busca al encargado; si no está en la sala, busca al que lleve más tiempo en esto de los que estén. Quien ha vuelto una vez vuelve otra si la atiende la persona adecuada, y soltarle tú un número por tu cuenta es justo lo que hace que deje de pasar."},{type:"divider"},{type:"header",text:"When the card says no",textEs:"Cuando la tarjeta dice que no"},{type:"paragraph",text:"Work down this list in order, staying completely relaxed. They are already embarrassed — your job is to make it a non-event.",textEs:"Ve bajando por esta lista en orden, con toda la calma. Ellos ya están incómodos — tu trabajo es que no sea nada."},{type:"numbered",items:['"No problem at all — do you have another card on you?"','"Let me try typing the numbers in by hand — the chip does this sometimes."','"Have you got Apple Pay or Google Pay on your phone? That works too."','"Shall we split it — half on this card, half on the other one?" Two cards, or a card and whatever cash she has on her.',`Cash, and this is your best answer, not your last one: "Cash suits me even better, my love. There's a machine two minutes that way — I'll walk you over and carry the bag." You go WITH her. Never send her off on her own, however close it is and however busy the table is.`,"If the money genuinely is not there, be lovely about it, hands empty, and get straight back on the floor."],itemsEs:['"No pasa nada — ¿llevas otra tarjeta encima?"','"Déjame probar metiendo los números a mano — el chip hace esto a veces."','"¿Tienes Apple Pay o Google Pay en el móvil? Eso también nos vale."','"¿Lo partimos — la mitad en esta tarjeta y la mitad en la otra?" Dos tarjetas, o una tarjeta y el efectivo que lleve encima.','Efectivo, y esta es tu mejor respuesta, no la última: "En efectivo aún mejor, cariño. Hay un cajero a dos minutos — te acompaño yo y te llevo la bolsa." Vas CON ella. Nunca la mandes sola, por cerca que esté y por muy liada que esté la mesa.',"Si el dinero de verdad no está, sé un encanto, con las manos vacías, y vuelve directo al suelo."]},{type:"keypoint",text:"Sometimes you take the loss and that is that. What they remember is how you handled it — and people come back to the seller who was lovely about their card being declined.",textEs:"A veces encajas la pérdida y ya está. Lo que recuerdan es cómo lo gestionaste — y la gente vuelve al vendedor que fue encantador cuando le rechazaron la tarjeta."},{type:"divider"},{type:"header",text:"Before they walk out",textEs:"Antes de que se vayan"},{type:"paragraph",text:"Ask them for a Google review while they are still holding the bag and still delighted. That moment — paid, happy, product in hand — is the only moment they will ever say yes to it. Ask warmly, once, and let it go if they would rather not.",textEs:"Pídeles una reseña en Google mientras todavía tienen la bolsa en la mano y siguen encantados. Ese momento — pagado, contentos, producto en mano — es el único en el que van a decir que sí. Pídelo con cariño, una vez, y déjalo estar si prefieren que no."},{type:"tip",text:"This is new and we are just starting with it, so build the habit now: the review ask is part of the sale, not something extra you do if you remember.",textEs:"Esto es nuevo y estamos empezando con ello, así que coge el hábito ya: pedir la reseña es parte de la venta, no algo extra que haces si te acuerdas."},{type:"keypoint",text:"And if what she just bought was a syringe, she is not walking out yet — you are one step from finished, not finished. Bag in her hand, review asked, delighted: that is the moment you hand her to the upseller, and it is the last thing your job contains. The whole move is the next lesson, and it takes about thirty seconds.",textEs:"Y si lo que acaba de comprar es una jeringa, todavía no se va — estás a un paso de terminar, no has terminado. Bolsa en la mano, reseña pedida, encantada: ese es el momento de pasarla al vendedor de arriba, y es lo último que contiene tu trabajo. El movimiento entero es la siguiente lección, y son unos treinta segundos."}],quiz:[{question:"Where does the payment happen?",questionEs:"¿Dónde se hace el pago?",options:["At the till, so the sale is properly recorded","Wherever there is space away from other customers","In the chair — the machine goes to the customer","At the door, once everything is bagged up"],optionsEs:["En la caja, para que la venta quede bien registrada","Donde haya sitio, lejos de otros clientes","En la silla — el datáfono va al cliente","En la puerta, cuando ya está todo embolsado"],correctIndex:2,explanation:"Every metre between the yes and the payment is a metre they can change their mind in. Standing a customer up loses sales you had already made.",explanationEs:"Cada metro entre el sí y el pago es un metro para que cambien de opinión. Levantar a un cliente pierde ventas que ya tenías hechas."},{question:"What should you say while the terminal is processing?",questionEs:"¿Qué deberías decir mientras el datáfono procesa?",options:["Anything at all — just do not leave silence","Repeat what they have bought and what it cost","Nothing, so they can concentrate on the PIN","Explain the returns policy and the guarantee"],optionsEs:["Cualquier cosa — pero no dejes silencio","Repite lo que han comprado y lo que ha costado","Nada, para que se concentren en el PIN","Explica la política de devoluciones y la garantía"],correctIndex:0,explanation:"The content is irrelevant. A customer left alone with their thoughts while a machine beeps is a customer doing arithmetic.",explanationEs:"El contenido es irrelevante. Un cliente a solas con sus pensamientos mientras pita una máquina es un cliente haciendo cuentas."},{question:"A returning customer walks in while you are closing someone. What is the move?",questionEs:"Entra un cliente que repite mientras estás cerrando a alguien. ¿Qué haces?",options:["Finish the sale first and hope they wait","Hand the returning customer to the manager","Ask the person in the chair to give you a minute","Serve them both at once and keep it moving"],optionsEs:["Terminas la venta y esperas que aguanten","Pasas el cliente que repite al encargado","Le pides a la persona de la silla un minuto","Atiendes a los dos a la vez y sigues adelante"],correctIndex:1,explanation:"Greet them warmly and give them a number, then get the manager. A customer who came back is worth more than the one you are closing.",explanationEs:"Salúdalos con buen rollo y dales un número, y luego llama al encargado. Un cliente que vuelve vale más que el que estás cerrando."},{question:"The card is declined and they have no other card. What comes next?",questionEs:"Rechazan la tarjeta y no tienen otra. ¿Qué viene después?",options:["Ask whether they can get cash from a machine","Offer to hold the product until tomorrow","Drop to a lower rung so the amount goes through","Numbers by hand, then Apple or Google Pay"],optionsEs:["Preguntar si pueden sacar efectivo de un cajero","Ofrecerte a guardarles el producto hasta mañana","Bajar un escalón para que pase el importe","Probar los números a mano, y luego Apple o Google Pay"],correctIndex:3,explanation:"Manual entry first — the chip fails sometimes — then the phone wallets. If none of it works, let it go warmly.",explanationEs:"Primero a mano — el chip falla a veces — y luego los monederos del móvil. Si no funciona nada, déjalo ir con buena cara."},{question:"The syringe is paid for and the bag is in her hand. Are you finished?",questionEs:"La jeringa está pagada y tiene la bolsa en la mano. ¿Has terminado?",options:["No — she gets handed to the upseller before she goes","Yes, unless she asks you about one of the other products","Yes — it is closed, and the next thing is the next stop","No — you show her the peeling while she is still warm"],optionsEs:["No — la pasas al vendedor de arriba antes de que se vaya","Sí, salvo que ella te pregunte por alguno de los otros","Sí — está cerrada, y lo siguiente es la siguiente parada","No — le enseñas el peeling mientras sigue calentita"],correctIndex:0,explanation:"A syringe sale ends with the handover, not with the bag. And it is a handover, not a second pitch — you do not start selling her another product yourself.",explanationEs:"Una venta de jeringa acaba con el relevo, no con la bolsa. Y es un relevo, no una segunda venta — no te pones tú a venderle otro producto."}]},"close-handover":{id:"close-handover",categoryId:"closing",title:"Your Job Ends At The Syringe",titleEs:"Tu Trabajo Acaba en la Jeringa",subtitle:"She paid. Now you give her a gift and fetch the specialist",subtitleEs:"Ha pagado. Ahora le haces un regalo y vas a por el especialista",duration:"5 min",icon:"Users",order:6,xpReward:120,sections:[{type:"header",text:"The syringe is the win",textEs:"La jeringa es la victoria"},{type:"paragraph",text:"Nobody has ranked the products for you, so here it is. The syringe is the star. It is what we sell, it is what we focus on, and it is what a shift is actually measured on. The peeling sits in the middle. The scrub, the body butter and the nail kit are beginner kit — they are there for somebody learning how to sell and for the nice energy a small easy sale puts in the room, and they are not the target.",textEs:"Nadie te ha puesto los productos en orden, así que ahí va. La jeringa es la estrella. Es lo que vendemos, es en lo que nos centramos, y es con lo que de verdad se mide un turno. El peeling está en medio. El exfoliante, la manteca corporal y el kit de uñas son material de principiante — están para quien está aprendiendo a vender y para el buen rollo que mete en la sala una venta pequeña y fácil, y no son el objetivo."},{type:"keypoint",text:"Nobody is going to tell you off for a nail kit. Sell them all day, they are lovely, they warm the shop up. But do not go home proud of a nail-kit day — that is a day you aimed low. Every hour you are on that floor you are hunting one thing, and it is the syringe.",textEs:"Nadie te va a reñir por un kit de uñas. Véndelos todo el día, son estupendos, calientan la tienda. Pero no te vayas a casa orgulloso de un día de kits de uñas — ese es un día en el que has apuntado bajo. Cada hora que estás en esa sala estás cazando una cosa, y es la jeringa."},{type:"subheader",text:"And when the syringe is paid for, you stop selling",textEs:"Y cuando la jeringa está pagada, dejas de vender"},{type:"paragraph",text:"This is the bit that is going to feel wrong, because everything in you says she is warm, she has her card out, go again. Do not. You do not walk her back to the table for a scrub, you do not slide the peeling in front of her, you do not sell her a second anything. Your job on this customer is finished at the syringe — and what comes next is not another product from you, it is a different person doing a different job.",textEs:"Esta es la parte que te va a chirriar, porque todo en ti dice que está calentita, que tiene la tarjeta fuera, que vayas otra vez. No lo hagas. No la llevas de vuelta a la mesa a por un exfoliante, no le pones el peeling delante, no le vendes un segundo nada. Tu trabajo con esta clienta se acaba en la jeringa — y lo que viene después no es otro producto tuyo, es otra persona haciendo otro trabajo."},{type:"keypoint",text:"Two reasons, and the first one is money. A second pitch out of the same mouth undoes the first one: she was delighted, and now she is sat there working out how much more you were planning to get out of her, and whether the price she just paid was the real one. The second reason is simpler — the thing that comes next is not yours to sell.",textEs:"Dos motivos, y el primero es dinero. Una segunda venta saliendo de la misma boca deshace la primera: estaba encantada, y ahora está ahí sentada calculando cuánto más pensabas sacarle, y si el precio que acaba de pagar era el de verdad. El segundo motivo es más simple — lo que viene después no te toca venderlo a ti."},{type:"divider"},{type:"header",text:"Who you are handing her to",textEs:"A quién se la pasas"},{type:"paragraph",text:"The upseller. He sells the red and infrared LED devices, and they are a different world from anything in this manual: the alternative to a facelift. It gets the body making its own collagen and elastin, and it lifts the face. That is the whole of what you need to know about it, and it is genuinely all you should say about it.",textEs:"El vendedor de arriba. Él vende los aparatos de LED rojo e infrarrojo, y son otro mundo comparados con todo lo que hay en este manual: la alternativa a un lifting. Hace que el cuerpo fabrique su propio colágeno y su propia elastina, y levanta la cara. Eso es todo lo que necesitas saber, y de verdad es todo lo que deberías decir."},{type:"keypoint",text:"You are not the expert on it and you do not want to be. Start explaining how it works and you will get it half right in front of a customer, and he then has to walk over and quietly unpick what you just said before he can start. Two sentences from you, then his name, then get out of the way. And you never put a number on it — that is his product and his price, the same way the bottom of your own ladder belongs to a manager.",textEs:"Tú no eres el experto en eso y no quieres serlo. Ponte a explicar cómo funciona y lo dirás a medias delante de una clienta, y luego él tiene que llegar y deshacer en voz baja lo que acabas de decir antes de poder empezar. Dos frases tuyas, luego su nombre, y quítate de en medio. Y nunca le pongas un número — ese es su producto y su precio, igual que el final de tu propia escalera es del encargado."},{type:"divider"},{type:"header",text:"The handover, word for word",textEs:"El relevo, palabra por palabra"},{type:"paragraph",text:"Everything about how this is said exists to keep it on the giving side. She has just handed you money. If the next thing out of your mouth is another product, you are asking her for money again thirty seconds later. So you are not introducing a second sale — you are giving her something, and you are giving her somebody.",textEs:"Todo lo que tiene que ver con cómo se dice esto existe para mantenerlo en el lado de dar. Ella te acaba de dar dinero. Si lo siguiente que sale de tu boca es otro producto, le estás pidiendo dinero otra vez treinta segundos después. Así que no le presentas una segunda venta — le das algo, y le das a alguien."},{type:"paragraph",text:"First, he is a specialist. Not your colleague, not the other seller — a specialist, who is only here for a short time, and who is amazing at what he does. Say it like you are slightly lucky to have him today, because that is how she is going to hear it.",textEs:"Primero, es un especialista. No tu compañero, no el otro vendedor — un especialista, que solo está aquí una temporada corta, y que es buenísimo en lo suyo. Dilo como si tuvieras un poco de suerte de tenerlo hoy, porque así es como lo va a oír ella."},{type:"script",text:`"Listen — we've got a specialist in with us at the moment, he's only here a short while. He is unbelievable at what he does."`,textEs:'"Oye — ahora mismo tenemos aquí a un especialista, está solo una temporadita. Es una barbaridad lo bueno que es en lo suyo."'},{type:"paragraph",text:"Then the gift, and the reason for it is her, not the shop. She bought, so she gets spoiled. That sentence is doing the heavy lifting in the whole handover.",textEs:"Luego el regalo, y el motivo es ella, no la tienda. Ha comprado, así que la mimamos. Esa frase es la que hace el trabajo pesado de todo el relevo."},{type:"script",text:`"And just because you got this, I'm going to spoil you with a small gift."`,textEs:'"Y solo porque te has llevado esto, te voy a mimar con un regalito."'},{type:"paragraph",text:'Then the question, which is the piece that actually does the work. You are not asking whether she is interested. You are asking which — the same shape as "Visa or Mastercard?", and it works for the same reason.',textEs:'Luego la pregunta, que es la pieza que de verdad trabaja. No le preguntas si le interesa. Le preguntas cuál — la misma forma que "¿Visa o Mastercard?", y funciona por el mismo motivo.'},{type:"script",text:`"Quick one — what's more important to you, if you could get it lifted? The cheeks? The neck? … Would that make you happy?"`,textEs:'"Una cosita rápida — ¿qué es más importante para ti, si te lo pudieran levantar? ¿Los pómulos? ¿El cuello? … ¿Eso te haría feliz?"'},{type:"keypoint",text:"Look at what she has just done. She has named, out loud, the part of her own face she has been unhappy about for years — before the specialist has even walked over. He arrives already knowing what she wants, from her own mouth, and she has already said yes to being happy about it. That is his two yeses, collected by you, in one sentence.",textEs:"Mira lo que acaba de hacer. Ha dicho en voz alta la parte de su propia cara con la que lleva años sin estar contenta — antes de que el especialista se haya acercado siquiera. Él llega sabiendo ya lo que ella quiere, de su propia boca, y ella ya ha dicho que sí a estar contenta con eso. Esos son sus dos síes, recogidos por ti, en una frase."},{type:"paragraph",text:`Then you leave, and you come back with him. Never shout him across the shop, never say "he'll look after you" and walk off — you bring him to her, you say his name, and you let him take it from there.`,textEs:'Luego te vas, y vuelves con él. Nunca lo llames a gritos desde el otro lado de la tienda, nunca digas "él te atiende" y te largues — se lo traes tú, dices su nombre, y dejas que él siga desde ahí.'},{type:"script",text:'"Let me check with him — have you got one second?"',textEs:'"Déjame preguntarle a él — ¿tienes un segundo?"'},{type:"tip",text:"If she says no to the question, nothing has gone wrong. She has bought the syringe, she is happy, you gave her something and she did not want it — that is a good sale that ended a sentence earlier than it might have. Stay warm, finish the bag, and go and stop somebody else.",textEs:"Si dice que no a la pregunta, no ha pasado nada malo. Ha comprado la jeringa, está contenta, le has ofrecido algo y no lo ha querido — eso es una buena venta que ha acabado una frase antes de lo que podía. Sigue amable, termina con la bolsa, y ve a parar a otra persona."},{type:"tip",text:"The whole thing costs you about thirty seconds: specialist, gift, cheeks or neck, one second. Selling the syringe is the win — the handover is the last thing you do to it, and it is the half of the job the shop was never being paid for.",textEs:"Todo esto te cuesta unos treinta segundos: especialista, regalo, pómulos o cuello, un segundo. Vender la jeringa es la victoria — el relevo es lo último que le haces, y es la mitad del trabajo que la tienda no estaba cobrando."}],quiz:[{question:"She has just paid for a syringe and she is delighted. What do you sell her next?",questionEs:"Acaba de pagar una jeringa y está encantada. ¿Qué le vendes ahora?",options:["A scrub — she is warm and the second sale is the easy one","The peeling, so she has something for the weeks in between","Nothing. You hand her over to the upseller","A second syringe at a better price for a friend of hers"],optionsEs:["Un exfoliante — está calentita y la segunda venta es la fácil","El peeling, para que tenga algo para las semanas de en medio","Nada. Se la pasas al vendedor de arriba","Una segunda jeringa a mejor precio para una amiga suya"],correctIndex:2,explanation:"Your job on this customer ends at the syringe. A second pitch out of the same mouth undoes the first one — she starts wondering how much more you were planning to get out of her.",explanationEs:"Tu trabajo con esta clienta acaba en la jeringa. Una segunda venta saliendo de la misma boca deshace la primera — se pone a calcular cuánto más pensabas sacarle."},{question:"You are about to go and get him. What have you called him?",questionEs:"Estás a punto de ir a buscarlo. ¿Cómo lo has llamado?",options:["A specialist, only here for a short time","Your colleague, who handles the other products we do","The manager, so she knows he can move on the price","A mate of yours who happens to be very good at this"],optionsEs:["Un especialista, que está aquí poco tiempo","Tu compañero, que lleva los otros productos que tenemos","El encargado, para que sepa que él puede tocar el precio","Un amigo tuyo al que se le da muy bien esto"],correctIndex:0,explanation:'A specialist is not another seller, and "only here a short time" puts a clock on him. Say it like you are slightly lucky to have him today.',explanationEs:'Un especialista no es otro vendedor, y "está aquí poco tiempo" le pone un reloj. Dilo como si tuvieras algo de suerte de tenerlo hoy.'},{question:"Why is the LED handed over as a gift instead of the next thing on the list?",questionEs:"¿Por qué el LED se pasa como un regalo y no como lo siguiente de la lista?",options:["Because the specialist would rather not talk about money","She just paid you. A gift gives; another product asks again","Because a gift is easier to explain than what it actually does","Because she will feel she owes you something in return for it"],optionsEs:["Porque el especialista prefiere no hablar de dinero todavía","Te acaba de pagar. Un regalo da; otro producto vuelve a pedir","Porque un regalo es más fácil de explicar que lo que hace","Porque va a sentir que te debe algo a cambio de habérselo dado"],correctIndex:1,explanation:"Thirty seconds after she handed you money, another product is you asking for money again. A gift keeps the whole thing on the side where you are giving.",explanationEs:"Treinta segundos después de darte dinero, otro producto es pedirle dinero otra vez. Un regalo mantiene todo esto en el lado en el que das tú."},{question:'What does "the cheeks or the neck?" do that "are you interested?" does not?',questionEs:'¿Qué hace "¿los pómulos o el cuello?" que no hace "¿te interesa?"',options:["It keeps her talking so the specialist has time to get there","It tells the specialist what she paid for the syringe already","It makes the device sound like it was built for her face alone","She names the thing herself, and answers which, not whether"],optionsEs:["La mantiene hablando para que al especialista le dé tiempo","Le dice al especialista lo que ya ha pagado por la jeringa","Hace que el aparato suene hecho solo para su cara y ninguna más","Ella nombra la cosa, y contesta cuál, no si sí o si no"],correctIndex:3,explanation:"She says out loud the part of her face she has been unhappy about for years, before he has even walked over. He arrives already knowing what she wants.",explanationEs:"Dice en voz alta la parte de su cara con la que lleva años sin estar contenta, antes de que él se haya acercado. Él llega sabiendo ya lo que quiere."}]},"close-fault":{id:"close-fault",categoryId:"closing",title:"It Is Not On You — If You Did Everything",titleEs:"No Es Culpa Tuya — Si Lo Hiciste Todo",subtitle:"Most of them say no. That is the job, not your failure",subtitleEs:"La mayoría dice que no. Eso es el trabajo, no tu fracaso",duration:"5 min",icon:"Shield",order:7,xpReward:120,sections:[{type:"header",text:"Most of them are going to say no",textEs:"La mayoría te va a decir que no"},{type:"paragraph",text:"Nobody tells you this on your first day, so here it is, straight. Most of the people you step in front of will not stop. Of the ones who do stop and sit down, most will not buy. That is not you being bad at this. That is the shape of the job, and it is the same shape for the best seller in the centre. If you are waiting for a day where everybody says yes, you are going to have a miserable career waiting for it.",textEs:"Nadie te cuenta esto el primer día, así que te lo cuento yo, claro. La mayoría de la gente a la que te pongas delante no va a parar. Y de los que paran y se sientan, la mayoría no va a comprar. Eso no es que se te dé mal. Esa es la forma que tiene este trabajo, y es la misma para el mejor vendedor del centro. Si esperas un día en el que todo el mundo diga que sí, vas a esperar sentado toda tu carrera."},{type:"keypoint",text:"So why tell you? Because of what it means about the person already sitting in your chair. If most people never stop, and most of the ones who stop never buy, then somebody with your product in their hand is a rare thing. Not a lead. Not one of many. Rare. You do not hurry that person, you do not get bored halfway through them, and you certainly do not let them wander off to think about it — because there is no queue of them behind you.",textEs:'¿Y por qué contártelo? Por lo que dice de la persona que ya está sentada en tu silla. Si casi nadie para, y de los que paran casi nadie compra, entonces alguien con tu producto en la mano es algo raro. No es "un cliente más". Es raro. A esa persona no la metes prisa, no te aburres a mitad de camino, y desde luego no la dejas irse a pensárselo — porque no hay una cola de ellas esperando detrás.'},{type:"subheader",text:"The only question worth asking after a no",textEs:"La única pregunta que vale la pena tras un no"},{type:"paragraph",text:'When somebody walks without buying, there is exactly one useful question, and it is not "what is wrong with me". It is: did I actually give that everything? Not "was I nice". Not "did I try". Everything. Because the difference between a seller who gets better and one who does the same year forever is that the first one answers this honestly and the second one does not ask.',textEs:'Cuando alguien se va sin comprar, hay exactamente una pregunta útil, y no es "qué me pasa a mí". Es: ¿le he dado de verdad todo lo que tengo? No "he sido amable". No "lo he intentado". Todo. Porque la diferencia entre un vendedor que mejora y uno que hace lo mismo durante años es que el primero se responde en serio y el segundo ni se lo pregunta.'},{type:"checklist",items:["Did I say anything wrong, or promise something I should not have?","Did I skip a step — the hand, the mirror, the two yeses, the ask?","Did I go quiet after the price, or did I fill the silence and lose it?","Did I get lazy in the middle, once I decided they were not buying?","Did I go all the way down the ladder, or stop early to save myself the effort?"],itemsEs:["¿He dicho algo que no debía, o he prometido algo que no toca?","¿Me he saltado un paso — la mano, el espejo, los dos síes, el pedir?","¿Me he callado después del precio, o lo he llenado de ruido y lo he perdido?","¿Me he vuelto perezoso a mitad, cuando ya decidí que no iban a comprar?","¿He bajado toda la escalera, o he parado antes para ahorrarme el esfuerzo?"]},{type:"paragraph",text:"If one of those is a yes, that is your lesson and it is a good day — you just found the thing to fix, for free, without it costing you anything but one sale. Write it in the journal and take it out to the next one.",textEs:"Si alguna de esas es un sí, ahí tienes tu lección y ha sido un buen día — acabas de encontrar gratis lo que hay que arreglar, y solo te ha costado una venta. Apúntalo en el diario y sácalo con el siguiente."},{type:"subheader",text:'And if the answer is "I did all of it"',textEs:'Y si la respuesta es "lo he hecho todo"'},{type:"keypoint",text:"Then it is not on you. It genuinely is not. You did the demo properly, you said the right things, you asked for the money, you worked the whole ladder, you stayed warm to the last second — and they still walked. That is a bad customer, and bad customers are part of the game. Put it down. Do not carry it to the next person, because they can smell it on you and it will cost you that one too.",textEs:"Entonces no es culpa tuya. De verdad que no. Has hecho la demo bien, has dicho lo que había que decir, has pedido el dinero, has trabajado la escalera entera, has estado simpático hasta el último segundo — y aun así se han ido. Eso es un mal cliente, y los malos clientes forman parte del juego. Suéltalo. No te lo lleves al siguiente, porque te lo huelen encima y te va a costar también esa."},{type:"tip",text:'Notice this only works one way round. It is what you tell yourself AFTER, once you have honestly been through the list. The moment you start saying "most people say no anyway" BEFORE the demo, it has stopped being perspective and turned into an excuse — and excuses are the thing that makes a seller slow.',textEs:'Fíjate en que esto solo vale en un sentido. Es lo que te dices DESPUÉS, cuando has repasado la lista de verdad. En cuanto empiezas a decirte "total, la mayoría dice que no" ANTES de la demo, ha dejado de ser perspectiva y se ha convertido en excusa — y las excusas son lo que vuelve lento a un vendedor.'},{type:"script",text:'"I did everything. They still said no. Next one." — said out loud, once, and then you are back on the floor.',textEs:'"Lo he hecho todo. Aun así han dicho que no. Al siguiente." — dicho en voz alta, una vez, y vuelves a la sala.'},{type:"paragraph",text:"That is the whole trick, and it is why the good sellers last. They are not the ones who never get rejected — everybody gets rejected all day. They are the ones who have made themselves immune to their own mistakes, so that when a no comes, there is nothing on it for them to feel bad about.",textEs:"Ese es todo el truco, y por eso duran los buenos vendedores. No son los que nunca reciben un no — todo el mundo recibe noes todo el día. Son los que se han hecho inmunes a sus propios errores, así que cuando llega un no, no hay nada ahí de lo que sentirse mal."}],quiz:[{question:"Why are you told that most people will not buy?",questionEs:"¿Por qué te dicen que la mayoría no va a comprar?",options:["So a quiet day feels less like your fault","So you fight for the rare one already in your chair","So you learn to spot the buyers and skip the rest","So you know when a shift is not worth finishing"],optionsEs:["Para que un día flojo pese menos sobre ti","Para que pelees por el raro que ya tienes sentado","Para aprender a ver quién compra y saltarte al resto","Para saber cuándo un turno ya no merece la pena"],correctIndex:1,explanation:"If almost nobody stops, and almost none of those buy, the person holding your product is rare. That is the point of the number — not comfort, urgency.",explanationEs:"Si casi nadie para, y de esos casi ninguno compra, la persona que tiene tu producto en la mano es rara. Ese es el sentido del dato — no consuelo, urgencia."},{question:"A customer walks without buying. What do you ask yourself?",questionEs:"Un cliente se va sin comprar. ¿Qué te preguntas?",options:["Whether they were ever really going to buy","Whether the price is too high for this centre","Whether I gave that one absolutely everything","Whether I should change how I open tomorrow"],optionsEs:["Si de verdad iban a comprar en algún momento","Si el precio es demasiado alto para este centro","Si a ese le he dado absolutamente todo lo que tengo","Si mañana debería cambiar cómo abro"],correctIndex:2,explanation:"Wrong words, a skipped step, filling the silence, going lazy halfway, stopping early on the ladder. If one of those is a yes, you just found what to fix.",explanationEs:"Palabras equivocadas, un paso saltado, llenar el silencio, aflojar a mitad, parar antes de tiempo en la escalera. Si alguna es un sí, ya sabes qué arreglar."},{question:"You went through the list honestly and did everything right. Whose fault is the lost sale?",questionEs:"Repasas la lista con sinceridad y lo hiciste todo bien. ¿De quién es la venta perdida?",options:["Still partly yours — there is always something","Nobody’s, so there is nothing to learn from it","The shop’s, for pricing the product where it is","Not yours. A bad customer is part of the game"],optionsEs:["Un poco tuya todavía — siempre hay algo","De nadie, así que no hay nada que aprender","De la tienda, por poner el precio donde está","Tuya no. Un mal cliente es parte del juego"],correctIndex:3,explanation:"Put it down and do not carry it to the next person — they can smell it on you. But it only counts after the list, never before the demo.",explanationEs:"Suéltalo y no te lo lleves al siguiente — te lo huelen encima. Pero solo vale después de la lista, nunca antes de la demo."}]}},d={"connect-1":[{question:"What does the 'C' in the SCAN system stand for?",questionEs:"¿Qué significa la 'C' del sistema SCAN?",options:["Carry (shopping bags)","Clothing (what they wear)","Complexion (their skin type)","Confidence (how they walk)"],optionsEs:["Carry (bolsas de la compra)","Clothing (la ropa que llevan)","Complexion (su tipo de piel)","Confidence (cómo caminan)"],correctIndex:0,explanation:"C stands for 'Carry' — what shopping bags or items they're carrying. Bags from luxury stores signal buying mood and spending power.",explanationEs:"La 'C' es de 'Carry' (cargar): qué bolsas o cosas llevan encima. Bolsas de tiendas de lujo indican que están en modo compra y que tienen poder adquisitivo."},{question:"You are new on this floor. Which of these people do you stop?",questionEs:"Eres nuevo en esta planta. ¿A cuál de estas personas paras?",options:["The one with the luxury shopping bags, window-shopping slowly","All of them — as a beginner you stop everybody, for the practice","Nobody walking fast, so a good opener is not wasted on a rush","Only the ones who already look like they came out to spend money"],optionsEs:["A la de las bolsas de lujo, que mira escaparates sin prisa","A todas — de novato paras a todo el mundo, por practicar","A nadie que vaya rápido, para no gastar una buena entrada","Solo a quien ya tiene pinta de haber salido a gastar dinero"],correctIndex:1,explanation:"As a newbie you try to stop everybody, for the sake of practising. With time you start to understand who to stop and who not to — but that is something experience gives you, not a list anybody hands you. Filtering by bags, clothes or walking pace costs you the practice AND the customers.",explanationEs:"De novato intentas parar a todo el mundo, por practicar. Con el tiempo empiezas a entender a quién parar y a quién no — pero eso te lo da la experiencia, no una lista que te dé nadie. Filtrar por bolsas, ropa o lo rápido que andan te cuesta la práctica Y los clientes."},{question:"You notice she has beautiful nails and her hair is done. What is that worth to you?",questionEs:"Te fijas en que lleva las uñas preciosas y el pelo hecho. ¿Para qué te sirve eso?",options:["It tells you she will spend, so give her the top price and hold it","It tells you nothing about her wallet — it is a compliment you have been handed","It proves she already buys skincare, so skip the demo and go to the number","It means she is high maintenance, so keep the pitch short"],optionsEs:["Te dice que va a gastar, así que dale el precio de arriba y aguántalo","De su cartera no te dice nada — es un cumplido que te acaban de regalar","Demuestra que ya compra cosmética, así que sáltate la demo y ve al número","Significa que es exigente, así que hazle el discurso corto"],correctIndex:1,explanation:"What you spot is an opener, not a credit check. 'Your nails are unreal — who does them?' is a question she has to answer with a real answer, and that is the whole value of noticing. Guess her budget off her hands and you will be wrong about the woman who spends the most on you all week.",explanationEs:"Lo que ves es una entrada, no un informe bancario. '¿Esas uñas? Quién te las hace' es una pregunta que tiene que contestar de verdad, y ese es todo el valor de fijarte. Adivínale el presupuesto por las manos y te vas a equivocar justo con la que más se gaste contigo en toda la semana."}],"connect-2":[{question:"What is generally considered the #1 indicator of spending power?",questionEs:"¿Qué se considera, por lo general, el indicador número uno del poder adquisitivo?",options:["Handbag brand","Sunglasses brand","Watch quality","Shoe quality"],optionsEs:["La marca del bolso","La marca de las gafas de sol","La calidad del reloj","La calidad de los zapatos"],correctIndex:2,explanation:"Watch quality is typically the most reliable indicator of spending power because watches are worn for function AND status, and luxury watches are expensive enough to separate serious wealth from average income.",explanationEs:"La calidad del reloj suele ser el indicador más fiable del poder adquisitivo, porque el reloj se lleva por función Y por estatus, y uno de lujo es lo bastante caro como para distinguir la riqueza de verdad de un sueldo normal."},{question:"Why is the 'already buying' signal so powerful?",questionEs:"¿Por qué la señal de 'ya está comprando' es tan potente?",options:["They're guaranteed to be rich, so the exact price you name never really matters","They have no spending limit at all today and will happily empty their wallet","They'll buy literally anything from anyone, so your actual pitch barely even matters","They're in buying mode with mental momentum, budget flexibility, and trust in the location"],optionsEs:["Seguro que son ricos, así que el precio exacto que digas nunca importa de verdad","No tienen ningún límite de gasto hoy y van a vaciar la cartera encantados","Le compran cualquier cosa a cualquiera, así que tu discurso en realidad casi ni cuenta","Están en modo compra, con inercia mental, margen en el presupuesto y confianza en la zona"],correctIndex:3,explanation:"Someone already carrying shopping bags has buying momentum, budget flexibility, trust in the location, and has dedicated time to shopping. Their wallet is already metaphorically open.",explanationEs:"Alguien que ya lleva bolsas de la compra tiene inercia de compra, margen en el presupuesto, confianza en la zona y ha reservado tiempo para comprar. Su cartera ya está, metafóricamente, abierta."},{question:"What should you do when spending signals contradict each other?",questionEs:"¿Qué debes hacer cuando las señales de gasto se contradicen entre sí?",options:["Always assume the worst — mixed signals mean they have no money","Read deeper — contradictions often reveal personality type and priorities","Always trust the most expensive item — it reveals their true budget","Ignore all the signals — just pitch your cheapest product to them"],optionsEs:["Piensa siempre lo peor: las señales mezcladas significan que no tienen dinero","Leer más a fondo: las contradicciones suelen revelar el tipo de persona y sus prioridades","Fíate siempre de lo más caro: eso revela su presupuesto real","Ignora todas las señales: ofréceles sin más tu producto más barato"],correctIndex:1,explanation:"Contradictory signals require deeper reading. An expensive watch with budget clothing might mean someone who values specific quality over fashion. Read their energy and demeanor alongside material signals.",explanationEs:"Las señales contradictorias piden una lectura más profunda. Un reloj caro con ropa barata puede ser alguien que valora una calidad concreta por encima de la moda. Lee su energía y su actitud junto con las señales materiales."}],"connect-3":[{question:"Which approach works best with French tourists?",questionEs:"¿Qué enfoque funciona mejor con los turistas franceses?",options:["High energy with loud enthusiasm and non-stop excitement all the way","Professional expertise with product knowledge and room for questions","Playful teasing with cheeky jokes, light banter, and plenty of easy laughs","Exclusive VIP treatment with constant flattery and special status"],optionsEs:["Mucha energía, entusiasmo a tope y emoción sin parar de principio a fin","Profesionalidad, conocimiento del producto y espacio para preguntar","Bromas pícaras, chistes con guasa, cachondeo suave y muchas risas fáciles","Trato VIP exclusivo, con halagos constantes y un estatus especial"],correctIndex:1,explanation:"French tourists know their skincare. Give them the substance — what is in it, why it works — and let them ask you everything they want, right there at the table. Hype makes them suspicious. So does 'have a think about it', which is not respect, it is you holding the door open for them.",explanationEs:"Los turistas franceses saben de cosmética. Dales la sustancia — qué lleva, por qué funciona — y deja que te pregunten todo lo que quieran, ahí mismo, en la mesa. El bombo les hace desconfiar. Y un 'piénsatelo' también: eso no es respeto, es que les estás abriendo la puerta."},{question:"Why does the Europe-price comparison work especially well with Spanish tourists?",questionEs:"¿Por qué la comparación con el precio de Europa funciona tan bien con los turistas españoles?",options:["Spanish tourists hate spending, so only the very cheapest option on the table appeals","Spanish shoppers ignore quality completely, so a low price is all that they notice","The gap between the two prices is big enough to feel like a win worth acting on","Spanish visitors distrust luxury brands, so they steer clear of anything premium"],optionsEs:["Los turistas españoles odian gastar, así que solo les atrae la opción más barata","A los compradores españoles les da igual la calidad, solo se fijan en el precio bajo","La diferencia entre los dos precios es lo bastante grande como para merecer la pena","Los visitantes españoles desconfían del lujo, así que evitan cualquier cosa premium"],correctIndex:2,explanation:"The distance between the Europe price and the {locationName} price is wide enough that acting on it feels worth doing. Spanish tourists respond well to value framing — 'smart shopping' in {locationName}.",explanationEs:"La distancia entre el precio de Europa y el de {locationName} es lo bastante amplia como para que merezca la pena aprovecharla. Los turistas españoles responden muy bien al enfoque de valor: 'compra inteligente' en {locationName}."},{question:"What should you do when uncertain about someone's cultural background?",questionEs:"¿Qué debes hacer cuando no tienes claro el origen cultural de alguien?",options:["Ask them directly where they're from before you say anything else","Start with moderate distance and minimal touch, letting them close the gap","Use one identical approach for everyone and ignore the personal signals","Guess their culture from their appearance and commit fully to that approach"],optionsEs:["Pregúntales directamente de dónde son antes de decir nada más","Empieza con una distancia media y poco contacto, y deja que sean ellos quienes se acerquen","Usa el mismo enfoque idéntico con todo el mundo e ignora las señales de cada uno","Adivina su cultura por su aspecto y apuesta del todo por ese enfoque"],correctIndex:1,explanation:"When uncertain, start with moderate distance and minimal touch. Watch their body language — if they lean in, you can move closer. Let them set the proximity comfort level.",explanationEs:"Si no lo tienes claro, empieza con distancia media y poco contacto. Observa su lenguaje corporal: si se inclinan hacia ti, puedes acercarte más. Deja que ellos marquen el nivel de cercanía cómodo."}],"connect-4":[{question:"How can you identify who the actual decision-maker is in a couple?",questionEs:"¿Cómo identificas quién toma de verdad la decisión en una pareja?",options:["The partner who talks the most and asks the most questions is always the one deciding","The man in the couple is always the one who makes the final decision, whatever she thinks","Watch who the driver looks at after your pitch — if they seek eye contact, that person decides","Whoever physically walks into the shop first is always the real decision-maker when it counts most"],optionsEs:["La pareja que más habla y más preguntas hace es siempre quien acaba decidiendo","El hombre de la pareja es siempre quien toma la decisión final, piense lo que piense ella","Fíjate a quién mira el que lleva la voz cantante tras tu discurso: si busca su mirada, esa persona decide","Quien entra físicamente primero en la tienda es siempre quien decide de verdad cuando más importa"],correctIndex:2,explanation:"The person doing most of the talking (the driver) often seeks eye contact with their partner after your pitch. If they look to their partner and ask 'What do you think?' — that partner is the decision-maker.",explanationEs:"Quien lleva la voz cantante suele buscar la mirada de su pareja después de tu discurso. Si mira a su pareja y le pregunta '¿Tú qué opinas?', esa pareja es quien decide."},{question:"What is the best way to engage a skeptical male partner?",questionEs:"¿Cuál es la mejor forma de ganarte al hombre escéptico de la pareja?",options:["Pressure him with guilt, imply he's cheap if he refuses to buy","Name the price immediately, challenge him to prove he can afford it","Include him early, appeal to logic, make him feel like his opinion matters","Ignore him completely, focus only on the woman, and bypass his opinion"],optionsEs:["Presiónalo con culpa e insinúa que es un tacaño si no compra","Suéltale el precio de golpe y rétalo a demostrar que puede pagarlo","Inclúyelo pronto, apela a la lógica y haz que sienta que su opinión cuenta","Ignóralo por completo, céntrate solo en ella y sáltate su opinión"],correctIndex:2,explanation:"Engage the skeptical partner early, appeal to his logic with practical benefits, and make him feel like his opinion matters. Transform him from potential veto into active supporter.",explanationEs:"Mete pronto en la conversación a la pareja escéptica, apela a su lógica con ventajas prácticas y haz que sienta que su opinión importa. Conviértelo de posible veto en aliado activo."},{question:"Why is giving a couple space after presenting the offer important?",questionEs:"¿Por qué es importante dar espacio a una pareja después de presentar la oferta?",options:["It frees you up to go and approach other customers walking past","It works because couples will never decide to buy anything immediately","It lets them have a private conversation where one often convinces the other","It proves to them that you don't really care about closing the sale"],optionsEs:["Te deja libre para ir a abordar a otros clientes que pasan","Funciona porque las parejas nunca deciden comprar nada al momento","Les permite hablar en privado, y ahí uno suele convencer al otro","Les demuestra que en realidad te da igual cerrar la venta"],correctIndex:2,explanation:"After presenting the offer, stepping back lets the couple have a private conversation. Often one partner convinces the other during that 30-second gap. Hovering creates pressure that kills this natural persuasion process.",explanationEs:"Después de presentar la oferta, dar un paso atrás deja que la pareja hable en privado. A menudo uno convence al otro en esos 30 segundos. Quedarte encima genera una presión que se carga ese proceso natural de persuasión."}],"connect-5":[{question:"What makes a compliment feel genuine rather than fake?",questionEs:"¿Qué hace que un cumplido suene genuino y no falso?",options:["Being specific about something the person chose","Repeating several quick compliments one after another","Using bigger and more elaborate flattering words","Praising their physical body and natural looks"],optionsEs:["Ser concreto sobre algo que esa persona ha elegido","Soltar varios cumplidos rápidos uno detrás de otro","Usar palabras más rebuscadas y aduladoras","Halagar su cuerpo y su físico natural"],correctIndex:0,explanation:"Specific compliments about choices people make (accessories, style, grooming) feel observant and real. Generic or physical compliments often feel fake or inappropriate.",explanationEs:"Los cumplidos concretos sobre las elecciones de la persona (complementos, estilo, cómo va arreglada) suenan observadores y reales. Los cumplidos genéricos o sobre el físico suelen sonar falsos o fuera de lugar."},{question:"How should mirroring be done to avoid detection?",questionEs:"¿Cómo hay que hacer el 'mirroring' para que no se note?",options:["Match only the words they say and never their body language","Announce that you're mirroring them so they know you want rapport","Copy their every movement instantly and exactly as they make it","Wait 2-3 seconds after they shift, then adjust your posture subtly"],optionsEs:["Imita solo las palabras que dicen y nunca su lenguaje corporal","Anúnciales que los estás imitando para que sepan que buscas conexión","Copia cada movimiento al instante y exactamente igual que ellos","Espera 2-3 segundos después de que se muevan y ajusta tu postura con sutileza"],correctIndex:3,explanation:"Mirroring should be delayed by 2-3 seconds and done subtly. Immediate, exact copying feels like mimicry and backfires. Natural, delayed matching creates subconscious similarity.",explanationEs:"El mirroring debe hacerse con 2-3 segundos de retardo y con sutileza. Copiar al instante y de forma exacta parece burla y sale mal. Imitar de forma natural y con retardo crea una sensación de parecido inconsciente."},{question:"Which type of humor is safest and most disarming in sales?",questionEs:"¿Qué tipo de humor es el más seguro y el que más desarma en una venta?",options:["Edgy shock-value humor","Customer-mocking humor","Politically-charged humor","Self-deprecating humor"],optionsEs:["El humor provocador y de choque","El humor que se burla del cliente","El humor con carga política","El humor a costa de ti mismo"],correctIndex:3,explanation:"Self-deprecating humor is safest because it shows confidence and vulnerability without risking offense. Political, sarcastic, or edgy humor can alienate customers.",explanationEs:"El humor a costa de ti mismo es el más seguro porque muestra confianza y vulnerabilidad sin riesgo de ofender. El humor político, sarcástico o provocador puede alejar al cliente."}],"connect-6":[{question:"What is the main difference between open and closed questions?",questionEs:"¿Cuál es la diferencia principal entre las preguntas abiertas y las cerradas?",options:["Open questions always belong right at the close of the sale; closed ones go in your first opening line","Open questions sound pushy and nosy to tourists; closed ones come across as far more polite","Open questions only suit experienced sellers; closed ones are for the ones just starting out","Open questions invite detailed responses and reveal information; closed questions get yes/no answers"],optionsEs:["Las abiertas van siempre justo en el cierre de la venta; las cerradas en tu primera frase de enganche","Las abiertas suenan agresivas y cotillas al turista; las cerradas parecen mucho más educadas","Las abiertas solo valen para vendedores con experiencia; las cerradas para los que empiezan de cero","Las preguntas abiertas invitan a respuestas detalladas y sacan información; las cerradas solo dan un sí o un no"],correctIndex:3,explanation:"Open questions (What, How, Why) invite detailed responses that reveal information. Closed questions (Do, Are, Have) get yes/no answers that end conversation.",explanationEs:"Las preguntas abiertas (Qué, Cómo, Por qué) invitan a respuestas detalladas que sacan información. Las cerradas (¿Tienes?, ¿Eres?, ¿Has?) solo dan un sí o un no que corta la conversación."},{question:"What does the 'question ladder' refer to?",questionEs:"¿A qué se refiere la 'escalera de preguntas'?",options:["Building from light surface questions to deeper personal ones as trust develops","Running through a fixed list of ten set questions in strict order","Firing off as many quick questions as you can before they leave","Sticking to product questions only and skipping anything personal or social"],optionsEs:["Ir de preguntas ligeras y de superficie a otras más personales según se gana confianza","Recitar una lista fija de diez preguntas siempre en el mismo orden","Soltar todas las preguntas rápidas que puedas antes de que se vaya","Quedarte solo en preguntas del producto y saltarte lo personal o social"],correctIndex:0,explanation:"The question ladder means starting with light observational questions, then moving to contextual, personal, and finally decision-oriented questions as trust builds. Skipping levels feels invasive.",explanationEs:"La escalera de preguntas consiste en empezar con preguntas ligeras de observación y luego pasar a las contextuales, las personales y, por último, las de decisión, según se va ganando confianza. Saltarse escalones resulta invasivo."},{question:"How can you avoid 'interrogation mode' when asking questions?",questionEs:"¿Cómo evitas el 'modo interrogatorio' al hacer preguntas?",options:["Share information between questions and follow conversational threads naturally","Read each question straight off a printed list, one after another, in a strict fixed order","Ask a single question at the start and then never follow it up with any other one at all","Drop all of the questions entirely and just talk non-stop about the product instead"],optionsEs:["Suelta información entre pregunta y pregunta y sigue el hilo de la charla con naturalidad","Lee cada pregunta directa de una lista impresa, una tras otra, en un orden fijo y estricto","Haz una sola pregunta al principio y luego no la sigas nunca con ninguna otra más","Deja del todo las preguntas y ponte a hablar sin parar solo del producto"],correctIndex:0,explanation:"Avoid interrogation by sharing between questions, following conversational threads (not rigid lists), using statements that invite response, and keeping the tone light and warm.",explanationEs:"Evita el interrogatorio soltando información entre preguntas, siguiendo el hilo de la conversación (no una lista rígida), usando frases que inviten a responder y manteniendo un tono ligero y cercano."}],"connect-7":[{question:"When is the optimal time to close based on buying signals?",questionEs:"¿Cuál es el momento óptimo para cerrar según las señales de compra?",options:["After the first signal shows any small flicker of interest","After they say out loud that they want it","After you have run through every single product feature","After the second buying signal confirms genuine interest"],optionsEs:["Cuando la primera señal muestra el mínimo destello de interés","Cuando dicen en voz alta que se lo quieren llevar","Cuando ya has repasado todas y cada una de las características","Cuando la segunda señal de compra confirma que hay interés de verdad"],correctIndex:3,explanation:"The second buying signal is the sweet spot. The first signal could be politeness; the second confirms genuine interest. Closing after the third signal may be too late.",explanationEs:"La segunda señal de compra es el punto justo. La primera puede ser pura cortesía; la segunda confirma que hay interés de verdad. Esperar a la tercera puede ser demasiado tarde."},{question:"Which of these is a strong PHYSICAL buying signal?",questionEs:"¿Cuál de estas es una señal de compra FÍSICA fuerte?",options:["Folding their arms tightly across their chest","Glancing down at their phone while you talk","Touching their face while looking at the product","Stepping back and away from the product stand"],optionsEs:["Cruzar los brazos con fuerza sobre el pecho","Echar un vistazo al móvil mientras le hablas","Tocarse la cara mientras mira el producto","Dar un paso atrás alejándose del puesto"],correctIndex:2,explanation:"Touching the face (cheeks, chin, under eyes) while looking at the product means they're imagining themselves using it. This is one of the strongest positive buying signals.",explanationEs:"Tocarse la cara (mejillas, barbilla, bajo los ojos) mientras mira el producto significa que se está imaginando usándolo. Es una de las señales de compra positivas más fuertes."},{question:"What should you do when you spot a buying signal?",questionEs:"¿Qué debes hacer cuando detectas una señal de compra?",options:["Switch to closing mode and stop adding new information","Push hard and ask outright whether they will buy","Drop the price right away to lock in the sale","Keep piling on more features to build up their interest"],optionsEs:["Pasa al modo cierre y deja de dar información nueva","Presiona fuerte y pregúntale directamente si va a comprar","Baja el precio enseguida para asegurar la venta","Sigue amontonando más características para reforzar su interés"],correctIndex:0,explanation:"When you spot a buying signal, switch from convincing to closing. Summarize value, present options, and ask for the decision. Every new feature you mention creates potential objections.",explanationEs:"Cuando detectas una señal de compra, pasa de convencer a cerrar. Resume el valor, presenta las opciones y pide la decisión. Cada característica nueva que mencionas abre la puerta a una objeción."}],"connect-8":[{question:"Which approach works best with an Analytical buyer?",questionEs:"¿Qué enfoque funciona mejor con un comprador Analítico?",options:["High energy, big stories, and lots of exciting enthusiasm","Speed, blunt directness, and results with zero small talk","Facts, evidence, and respect for their decision-making process","Warm feelings, personal connection, and friendly emotional rapport"],optionsEs:["Mucha energía, historias grandes y un entusiasmo contagioso","Rapidez, franqueza directa y resultados sin nada de cháchara","Datos, pruebas y respeto por su forma de decidir","Cercanía, conexión personal y una relación cálida y emotiva"],correctIndex:2,explanation:"Analytical buyers want facts, evidence and proof, and they need to understand how a thing works before they commit. Respect that by walking them through it properly — not by sending them off to think about it. Answer every question, then ask for the decision while the product is still in their hands.",explanationEs:"Los compradores analíticos quieren datos, pruebas y evidencias, y necesitan entender cómo funciona una cosa antes de comprometerse. Respétalo explicándoselo bien, no mandándolos a pensárselo. Responde a todas sus preguntas y luego pide la decisión con el producto todavía en sus manos."},{question:"How should you handle a Driver personality type?",questionEs:"¿Cómo debes tratar a un perfil de personalidad Dominante?",options:["Be fast, direct, and results-focused with binary choices","Tell long stories and paint colourful pictures for them","Build slow rapport and chat warmly before you pitch","Give them lots of detailed facts and fine print"],optionsEs:["Sé rápido, directo y céntrate en resultados con opciones binarias","Cuéntale historias largas y píntale escenas llenas de color","Crea confianza poco a poco y charla antes de vender","Dale un montón de datos detallados y letra pequeña"],correctIndex:0,explanation:"Drivers are time-pressed and decisive. They want quick results, clear options, and respect for their schedule. Skip the small talk, get to the demo and close fast.",explanationEs:"Los Dominantes van con prisa y son decididos. Quieren resultados rápidos, opciones claras y que respetes su tiempo. Sáltate la cháchara, ve a la demo y cierra rápido."},{question:"Why is it important to adapt your style to different personality types?",questionEs:"¿Por qué es importante adaptar tu estilo a los distintos tipos de personalidad?",options:["Because the manager simply insists on it, and following the rules is what keeps you in your job","Because it keeps every pitch feeling fresh for you, and a bit of variety makes the day interesting","Because one single pitch already works just fine on everyone, and adapting only ends up slowing you down","Because different types respond to different communication styles, and mismatching creates resistance"],optionsEs:["Porque el jefe lo exige y punto, y seguir las normas es lo que te mantiene en el puesto","Porque mantiene cada pitch fresco para ti, y un poco de variedad hace el día más entretenido","Porque un mismo pitch ya vale igual para todos, y adaptarte solo acaba haciéndote ir más lento","Porque cada tipo responde a un estilo de comunicación distinto, y equivocarte genera rechazo"],correctIndex:3,explanation:"Different personality types process information and make decisions differently. Using the wrong approach with the wrong type creates resistance — like speaking the wrong language. Adaptation is the key to precision selling.",explanationEs:"Cada tipo de personalidad procesa la información y decide de forma diferente. Usar el enfoque equivocado con el tipo equivocado genera rechazo, como hablar en otro idioma. Adaptarse es la clave de la venta de precisión."}],"prod-1":[{question:"Why should you always state the Europe price before the local price?",questionEs:"¿Por qué debes decir siempre el precio de Europa antes que el precio local?",options:["Because hearing the bigger figure first gives tourists time to slowly get used to spending money","Because the first price heard becomes the mental anchor that makes the local price feel like a bargain","Because leading with the higher number convinces tourists that your products must be exclusive and premium","Because starting with the European figure lets you quietly check what the tourist can actually afford"],optionsEs:["Porque oír primero la cifra más grande da al turista tiempo para hacerse poco a poco a gastar","Porque el primer precio que oyen se convierte en el ancla mental que hace que el precio local parezca un chollo","Porque empezar por el número más alto convence al turista de que tu producto es exclusivo y premium","Porque empezar por la cifra europea te deja comprobar con discreción cuánto se puede permitir realmente"],correctIndex:1,explanation:"The first price heard becomes the mental anchor. When a customer hears {currency}500 first, {currency}300 feels like a bargain. If they hear {currency}300 first, they evaluate it against their general sense of skincare pricing, which is less favorable.",explanationEs:"El primer precio que oyen se convierte en el ancla mental. Cuando un cliente oye primero {currency}500, {currency}300 le parece un chollo. Si oye {currency}300 primero, lo compara con su idea general de lo que cuesta la cosmética, y sale peor parado."},{question:"Why does the two-price contrast protect the product's perceived value?",questionEs:"¿Por qué el contraste de los dos precios protege el valor percibido del producto?",options:["It slightly confuses the tourist so they stop comparing prices carefully","It makes the little shop sound special and more memorable to tourists","It frames the lower figure as where you are, not as a lesser product","It lets you push the price higher later without any real pushback"],optionsEs:["Lía un poco al turista para que deje de comparar precios con cuidado","Hace que la tiendecita suene especial y más memorable para el turista","Presenta la cifra baja como el sitio donde estás, no como un producto peor","Te permite subir el precio más adelante sin que haya quejas de verdad"],correctIndex:2,explanation:"Naming the Europe price shows that the very same product carries a higher figure elsewhere. The {locationName} price then reads as where the customer happens to be standing, not as a markdown or a lower-grade product. Value perception stays intact.",explanationEs:"Decir el precio de Europa demuestra que ese mismo producto lleva una cifra más alta en otro sitio. Así, el precio de {locationName} se entiende como el sitio donde está el cliente, no como una rebaja ni como un producto de peor calidad. La percepción de valor se mantiene."},{question:"Which of these is a price anchoring mistake?",questionEs:"¿Cuál de estas es un error de anclaje de precios?",options:["Using the contrast between the two prices to show value","Opening with the higher Europe price before the local one","Letting the customer hear both figures before you close","Starting with the low price or apologizing for the cost"],optionsEs:["Usar el contraste entre los dos precios para mostrar el valor","Abrir con el precio alto de Europa antes que el local","Dejar que el cliente oiga las dos cifras antes de cerrar","Empezar por el precio bajo o disculparte por lo que cuesta"],correctIndex:3,explanation:"Starting with the low price sets a low anchor, making upsells feel expensive. Apologizing for the price ('I know it's expensive') undermines the value. Both destroy effective anchoring.",explanationEs:"Empezar por el precio bajo fija un ancla baja y hace que las ventas adicionales parezcan caras. Disculparte por el precio ('ya sé que es caro') tira por tierra el valor. Las dos cosas cargan el anclaje."}],"prod-2":[{question:"What cognitive shift happens when you offer two options instead of one?",questionEs:"¿Qué cambio mental ocurre cuando ofreces dos opciones en vez de una?",options:["The customer shifts from 'That's lovely' to 'That's way beyond my budget'","The customer just reaches for the cheaper of the two options","The customer freezes up and cannot decide between the two at all","The customer shifts from 'Should I buy?' to 'Which one should I choose?'"],optionsEs:["El cliente pasa de 'Qué bonito' a 'Esto se sale de mi presupuesto'","El cliente va directo a la más barata de las dos opciones","El cliente se bloquea y no consigue decidir entre las dos","El cliente pasa de '¿Compro?' a '¿Cuál de las dos elijo?'"],correctIndex:3,explanation:"Two options change the mental frame from a yes/no purchase decision (where 'no' is the default) to a comparison between options (where buying is assumed and they're just picking which one).",explanationEs:"Dos opciones cambian el marco mental: de una decisión de comprar o no (donde el 'no' es lo que sale por defecto) a una comparación entre opciones (donde se da por hecho que compra y solo elige cuál)."},{question:"What is the decoy effect?",questionEs:"¿Qué es el efecto señuelo?",options:["Showing only the most expensive option first to set a high starting point","Adding a cheap freebie so the customer feels they are getting a bonus","Slipping in a clever trick that quietly pressures the customer into buying","Adding a third option designed to make one of the main options more attractive"],optionsEs:["Enseñar solo la opción más cara primero para fijar un punto de partida alto","Añadir un regalito barato para que el cliente sienta que se lleva un extra","Colar un truco astuto que presiona al cliente sin que se dé cuenta","Añadir una tercera opción pensada para que una de las principales resulte más atractiva"],correctIndex:3,explanation:"The decoy effect involves adding an option that exists only to flatter another one. A single Scrub at {currency}60 makes the Buy 1 Get 1 duo — also {currency}60 — look unmissable, and that in turn makes the {currency}120 trio feel like the real value. Most customers pick the middle option.",explanationEs:"El efecto señuelo consiste en añadir una opción que solo existe para hacer brillar a otra. Un solo Scrub a {currency}60 hace que el dúo 2x1 —también a {currency}60— parezca imperdible, y eso a su vez hace que el trío de {currency}120 parezca el verdadero chollo. La mayoría se queda con la opción del medio."},{question:"A customer tells you her budget is tight. What is the right move with your two options?",questionEs:"Una clienta te dice que va justa de dinero. ¿Qué haces con tus dos opciones?",options:["Put the two up side by side exactly as you always do and let her weigh them against each other","Push the premium one harder, because a budget objection is only ever a value problem in disguise","Take the cheaper option down a rung, and attach a reason to it so the number is not just falling","Drop straight to the cheapest thing you sell, before she has actually asked you for anything at all"],optionsEs:["Ponerle las dos al lado exactamente como siempre y dejar que las compare entre ellas","Insistir más con la premium, porque una objeción de presupuesto solo es un problema de valor disfrazado","Bajar un escalón la opción barata, y pegarle un motivo para que el número no caiga porque sí","Bajar directo a lo más barato que vendes, antes de que ella te haya pedido nada en absoluto"],correctIndex:2,explanation:"Budget does not get said at the top of the ladder. By the time those words are out you have walked her down already, so you are not defending your first price any more — you are working towards your last one. That means move. But never for free: gift comes off, voucher goes on, the Scrub goes back as credit. A number that drops with no story behind it teaches her the numbers fall whenever she pushes, and then she pushes all the way to your floor.",explanationEs:"Lo del presupuesto no se dice arriba de la escalera. Cuando te suelta eso ya la has bajado, así que ya no defiendes tu primer precio — vas camino del último. O sea que te mueves. Pero nunca gratis: se quita el regalo, se pone el cupón, el Exfoliante vuelve como crédito. Un número que cae sin una historia detrás le enseña que los números bajan cada vez que empuja, y entonces empuja hasta tu suelo."}],"prod-3":[{question:"What is the gradual descent technique?",questionEs:"¿En qué consiste la técnica del descenso gradual?",options:["A rushed series of random price cuts that keep dropping lower until the customer finally agrees to buy","A tactic where you mirror the customer's very first offer and settle on that exact number right away","A method where you open at your lowest price and slowly raise it as the customer's interest grows","A structured staircase where each step removes a gift to lower the price while keeping value perception intact"],optionsEs:["Una serie apresurada de rebajas al azar que van bajando cada vez más hasta que el cliente por fin acepta comprar","Una táctica en la que copias la primera oferta del cliente y te quedas con esa cifra exacta al momento","Un método en el que empiezas por tu precio más bajo y lo vas subiendo a medida que crece el interés del cliente","Una escalera estructurada en la que cada peldaño retira un regalo para bajar el precio sin perder la percepción de valor"],correctIndex:3,explanation:"The gradual descent is a structured approach: present the full offer, then remove a gift (Step 2), then the voucher close (Step 3), each feeling like a personalized solution rather than desperate discounting.",explanationEs:"El descenso gradual es un método estructurado: presentas la oferta completa, luego retiras un regalo (paso 2) y después haces el cierre con el vale (paso 3); cada paso parece una solución personalizada y no un descuento desesperado."},{question:"What does the 'store credit' reframing accomplish?",questionEs:"¿Qué consigues al reformular la rebaja como un 'saldo a tu favor'?",options:["It makes the customer feel smart for saving rather than poor for hesitating","It makes the customer feel confused about what the final price actually includes","It makes the customer feel pressured into spending more than they had planned to","It makes the customer feel guilty for having asked about a discount at all"],optionsEs:["Hace que el cliente se sienta listo por ahorrar en vez de sentirse mal por dudar","Hace que el cliente se sienta confundido sobre lo que incluye de verdad el precio final","Hace que el cliente se sienta presionado a gastar más de lo que tenía pensado","Hace que el cliente se sienta culpable por haber pedido siquiera un descuento"],correctIndex:0,explanation:"Reframing a removed gift as 'store credit' (e.g., 'let me take the Scrub out and give you its value back as credit') makes the price reduction feel like a creative solution on their behalf, not just removing value.",explanationEs:"Reformular un regalo retirado como 'saldo a tu favor' (por ejemplo: 'te quito el Exfoliante y te devuelvo su valor como saldo') hace que la rebaja parezca una solución ingeniosa pensada para el cliente, y no un simple recorte de valor."},{question:"Why should you never go below your minimum floor price?",questionEs:"¿Por qué no debes bajar nunca de tu precio mínimo?",options:["It protects margins, value perception, and your commission — and sets a dangerous precedent if broken","It slows the sale, drains your energy, and bores the customer — so you lose all your momentum","It annoys the manager, breaks store policy, and could get you fired — so it isn't worth the risk","It spoils the market for other sellers, undercuts nearby shops, and drags down the whole street's prices"],optionsEs:["Protege el margen, la percepción de valor y tu comisión, y sienta un precedente peligroso si lo rompes","Ralentiza la venta, te agota y aburre al cliente, así que pierdes todo el impulso del cierre","Molesta al jefe, incumple las normas de la tienda y podría costarte el puesto, así que no vale la pena","Estropea el mercado para los demás vendedores, hunde a las tiendas de al lado y tira abajo los precios de toda la calle"],correctIndex:0,explanation:"Going below minimum destroys profitability, devalues the product in the customer's eyes, sets a bad precedent, and reduces your commission. The floor exists for good business reasons.",explanationEs:"Bajar del mínimo destroza la rentabilidad, devalúa el producto a ojos del cliente, sienta un mal precedente y reduce tu comisión. El precio mínimo existe por buenas razones de negocio."}],"prod-4":[{question:"Which three psychological principles does the voucher close combine?",questionEs:"¿Qué tres principios psicológicos combina el cierre con el vale?",options:["Intimidation, guilt, and public shame","Scarcity, exclusivity, and reciprocity","Flattery, entertainment, and repetition","Cold logic, patience, and plain honesty"],optionsEs:["Intimidación, culpa y vergüenza pública","Escasez, exclusividad y reciprocidad","Halago, entretenimiento y repetición","Lógica fría, paciencia y pura honestidad"],correctIndex:1,explanation:"The voucher close combines scarcity (one-time only), exclusivity (just for you), and reciprocity (I'm doing you a favor — you should commit). This triple combination is why it's so effective.",explanationEs:"El cierre con el vale combina escasez (solo por esta vez), exclusividad (solo para ti) y reciprocidad (te estoy haciendo un favor, así que comprométete). Esa triple combinación es lo que lo hace tan eficaz."},{question:"Why should you drop your voice during the voucher close?",questionEs:"¿Por qué debes bajar la voz durante el cierre con el vale?",options:["To signal that what you're saying is exclusive and secretive, making it feel more special","To keep rival sellers from overhearing, so nobody nearby can copy your best closing line","To calm the nervous customer down, so they stop focusing so much on the price","To pressure the customer into deciding fast, before they get a chance to think it over"],optionsEs:["Para dar a entender que lo que dices es exclusivo y confidencial, y que así parezca más especial","Para que los vendedores rivales no te oigan, y que nadie de al lado pueda copiar tu mejor frase de cierre","Para calmar al cliente nervioso, para que deje de fijarse tanto en el precio","Para presionar al cliente a decidir rápido, antes de que le dé tiempo a pensárselo"],correctIndex:0,explanation:"Lowering your volume signals exclusivity and confidentiality. It makes the offer feel like an insider secret rather than a public announcement, increasing its perceived value and personal nature.",explanationEs:"Bajar el volumen transmite exclusividad y confidencialidad. Hace que la oferta parezca un secreto entre tú y el cliente, y no un anuncio público, lo que aumenta su valor percibido y su carácter personal."},{question:"When should you NOT use the voucher close?",questionEs:"¿Cuándo NO debes usar el cierre con el vale?",options:["When it's the end of a long shift and you're tired — it wastes your last bit of energy","When the customer clearly loves the product but is only stalling on the price — it seals the deal","When the customer shows no interest in the product — it devalues the product unnecessarily","When the customer directly asks you for a discount — it gives your margin away too early"],optionsEs:["Cuando es el final de un turno largo y estás cansado, porque malgastas tus últimas energías","Cuando el cliente adora el producto pero solo se resiste por el precio, porque ahí es donde cierra la venta","Cuando el cliente no muestra ningún interés por el producto, porque lo devalúa sin necesidad","Cuando el cliente te pide directamente un descuento, porque regalas tu margen demasiado pronto"],correctIndex:2,explanation:"The voucher close should only be used when the customer genuinely loves the product but needs a final nudge. Using it on uninterested customers devalues the product and wastes your most powerful closing tool.",explanationEs:"El cierre con el vale solo debe usarse cuando el cliente adora de verdad el producto pero necesita un último empujón. Usarlo con clientes que no tienen interés devalúa el producto y desperdicia tu herramienta de cierre más potente."}],"prod-5":[{question:"She has just paid for the syringe. What is an 'upsell' in this shop?",questionEs:"Acaba de pagar la jeringa. ¿Qué es una 'venta adicional' en esta tienda?",options:["A handover — you pass her to the upseller, who sells the LED devices","The scrub, offered while her card is still on the table in front of you","A second syringe at half price, wrapped up as a thank-you for buying","Whatever else is on your tray, offered in the same breath as the receipt"],optionsEs:["Un traspaso — se la pasas al upseller, que vende los aparatos de LED","El exfoliante, ofrecido con la tarjeta todavía encima de la mesa","Una segunda jeringa a mitad de precio, envuelta como agradecimiento","Lo que quede en tu bandeja, ofrecido en el mismo aliento que el ticket"],correctIndex:0,explanation:"An upsell here is not you pitching a second product — it is a handover. You sold the syringe, which IS the win, and the next thing that happens to her is a different person selling red and infrared LED devices. That is a different job.",explanationEs:"Una venta adicional aquí no eres tú soltando un segundo producto — es un traspaso. Has vendido la jeringa, que YA es la victoria, y lo siguiente que le pasa es otra persona vendiendo aparatos de LED rojo e infrarrojo. Ese es otro trabajo."},{question:"How do you build the specialist up before she meets him?",questionEs:"¿Cómo le montas al especialista antes de que lo conozca?",options:["Tell her the LED prices first so the number does not surprise her later","Explain how red and infrared light works, so she arrives already convinced","A specialist, only here a short time, and amazing at what he does","Say he is a colleague who happens to be free and can have a quick look"],optionsEs:["Dile antes los precios del LED para que la cifra no la sorprenda luego","Explícale cómo funciona la luz roja e infrarroja, y así llega ya convencida","Un especialista, aquí por poco tiempo, y un crack en lo suyo","Di que es un compañero que está libre y le puede echar un vistazo"],correctIndex:2,explanation:"You are not introducing a colleague — you are telling her she is about to meet somebody people wait for. Short time, specialist, amazing at it. You never price his product and you never do his demo: two sentences about him and one question.",explanationEs:"No estás presentando a un compañero — le estás diciendo que va a conocer a alguien por el que la gente espera. Poco tiempo, especialista, un crack. Nunca le pones precio a lo suyo ni le haces su demo: dos frases sobre él y una pregunta."},{question:"Which question do you ask her, and why that one?",questionEs:"¿Qué pregunta le haces, y por qué esa?",options:['"Would you like me to introduce you to him?" — she can say no to it','"Have you got five minutes to meet a colleague?" — it asks for her time','"Do you want to hear about our LED devices?" — it names the product early','"If you could get it lifted — cheeks, or neck?" — both answers are a yes'],optionsEs:['"¿Te lo presento?" — a eso te puede decir que no','"¿Tienes cinco minutos para conocer a un compañero?" — le pides su tiempo','"¿Quieres que te hable de nuestros LED?" — nombra el producto demasiado pronto','"Si pudieras levantarlo: ¿pómulos o cuello?" — las dos respuestas son un sí'],correctIndex:3,explanation:"She is never asked whether she wants to meet him. She is asked which part of her own face she would lift — and whichever she picks, she has said it out loud. By the time you walk off to fetch him she has answered a question that only makes sense if she stays in that chair.",explanationEs:"Nunca se le pregunta si quiere conocerlo. Se le pregunta qué parte de su cara se levantaría — y elija la que elija, lo ha dicho en voz alta. Para cuando te vas a buscarlo, ya ha contestado a una pregunta que solo tiene sentido si se queda en esa silla."}],"prod-6":[{question:"Which product should you lead with for a customer with visible under-eye bags?",questionEs:"¿Con qué producto deberías empezar con un cliente que tiene bolsas visibles bajo los ojos?",options:["Scrub","Nail Kit","Syringe","Peeling"],optionsEs:["Exfoliante","Kit de uñas","Jeringa","Peeling"],correctIndex:2,explanation:"Visible eye concerns (bags, crow's feet, tired eyes) make the Syringe the optimal lead product. The immediate visual result and high perceived value make it the perfect match.",explanationEs:"Los problemas visibles en los ojos (bolsas, patas de gallo, ojos cansados) hacen de la Jeringa el producto ideal para empezar. El resultado visual inmediato y su alto valor percibido la convierten en la elección perfecta."},{question:"Her partner is stood behind the chair with his arms crossed. What is your first move?",questionEs:"Su pareja está detrás de la silla con los brazos cruzados. ¿Cuál es tu primer movimiento?",options:["Switch to the Scrub, because it is the one men go for","Pull a second chair over and give him a job in the demo","Ignore him completely and keep your eyes on her","Let him go — a man with folded arms is not going to change"],optionsEs:["Cámbiate al Exfoliante, que es el que va con los hombres","Acerca una segunda silla y dale un papel en la demo","Ignóralo del todo y no le quites ojo a ella","Déjalo — un hombre de brazos cruzados no va a cambiar"],correctIndex:1,explanation:"You bring him in before anything else — sit him down and make him the judge: 'you know her face better than I do, you tell me which side wins.' A bored man behind a chair is the most common reason a good demo ends in 'come on, we should get going'. Changing product is answering a question he has not asked, and letting him go is the last move, not the first.",explanationEs:"Lo metes dentro antes que nada — siéntalo y hazlo juez: 'tú le conoces la cara mejor que yo, dime qué lado gana'. Un hombre aburrido detrás de una silla es el motivo más habitual de que una buena demo acabe en 'venga, que nos vamos'. Cambiar de producto es responder a una pregunta que no ha hecho, y dejarlo estar es el último movimiento, no el primero."},{question:"Why should you adapt product recommendations by tourist origin?",questionEs:"¿Por qué deberías adaptar tus recomendaciones de producto según el origen del turista?",options:["Because copying each tourist's accent and gestures is what makes them trust you fastest","Because different cultures have different skincare priorities, knowledge levels, and buying motivations","Because leaning on national stereotypes is the quickest shortcut to guessing what people want","Because tourists only buy when you deliver the whole pitch in their native language"],optionsEs:["Porque imitar el acento y los gestos de cada turista es lo que hace que confíen en ti más rápido","Porque cada cultura tiene distintas prioridades de cuidado de la piel, distintos conocimientos y distintas motivaciones de compra","Porque apoyarte en los estereotipos nacionales es el atajo más rápido para adivinar lo que quiere la gente","Porque los turistas solo compran cuando les sueltas todo el discurso en su propio idioma"],correctIndex:1,explanation:"Different nationalities have different skincare cultures, ingredient knowledge, and buying motivations. French tourists appreciate science; British tourists love sensory experiences; Eastern European tourists respond to premium positioning. Matching to cultural context increases relevance.",explanationEs:"Cada nacionalidad tiene su propia cultura del cuidado de la piel, sus conocimientos sobre ingredientes y sus motivaciones de compra. A los turistas franceses les convence la ciencia; a los británicos les encantan las experiencias sensoriales; a los de Europa del Este les atrae el posicionamiento premium. Ajustarte al contexto cultural aumenta la relevancia."}],"prod-7":[{question:"What is the four-step objection handling framework?",questionEs:"¿Cuál es el método de cuatro pasos para gestionar objeciones?",options:["Argue → Convince → Pressure them hard → Close","Acknowledge → Reframe → Provide solution → Close","Interrupt → Discount → Give up → Walk away","Agree → Agree again → Agree once more → Accept the no"],optionsEs:["Discutir → Convencer → Presionarles fuerte → Cerrar","Reconocer → Reformular → Dar una solución → Cerrar","Interrumpir → Rebajar → Rendirse → Marcharse","Dar la razón → Dársela otra vez → Y otra más → Aceptar el no"],correctIndex:1,explanation:"The framework is: Acknowledge (validate their concern), Reframe (show a new perspective), Provide solution (proof, demo, or alternative), and Close (give them a path forward).",explanationEs:"El método es: Reconocer (validar su preocupación), Reformular (mostrar una nueva perspectiva), Dar una solución (una prueba, una demostración o una alternativa) y Cerrar (ofrecerle un camino a seguir)."},{question:"How should you respond to 'I already have cream at home'?",questionEs:"¿Cómo deberías responder a un 'ya tengo crema en casa'?",options:["Insist that they stop using their old cream right away and switch over entirely to yours","Tell them their current cream is obviously much worse and that yours will fully replace it","Differentiate your product as a complementary prep step that makes their cream work better","Agree that they clearly don't need anything more and simply wish them a good day"],optionsEs:["Insiste en que deje ya su crema de siempre y se pase del todo a la tuya ahora mismo","Dile que su crema de ahora es claramente mucho peor y que la tuya la sustituye entera","Diferencia tu producto como un paso de preparación complementario que hace que su crema funcione mejor","Dale la razón en que no necesita nada más y simplemente deséale un buen día"],correctIndex:2,explanation:"Don't compete with their cream — complement it. Position your product as the prep step that makes their existing cream work far better. They're not replacing; they're enhancing.",explanationEs:"No compitas con su crema: compleméntala. Posiciona tu producto como el paso previo que hace que su crema de siempre funcione mucho mejor. No están sustituyendo nada, lo están potenciando."},{question:"Why is 'I completely understand' such a powerful phrase in objection handling?",questionEs:"¿Por qué 'te entiendo perfectamente' es una frase tan potente al gestionar objeciones?",options:["It validates the customer's concern without agreeing with it, creating psychological safety","It concedes the objection outright, letting you back away from the whole sale quite politely","It quietly shuts down the conversation, giving you an easy exit from a really tough customer","It flatters the customer so much that they end up feeling awkward about ever objecting again"],optionsEs:["Valida la preocupación del cliente sin darle la razón, y crea una sensación de seguridad psicológica","Concede la objeción del todo, y te deja retirarte de toda la venta con bastante elegancia","Zanja la conversación sin ruido, y te da una salida fácil de un cliente de verdad difícil","Halaga tanto al cliente que acaba dándole apuro volver a ponerte una objeción otra vez"],correctIndex:0,explanation:"'I completely understand' validates the customer's feelings without conceding the point. It creates psychological safety that opens them up to hearing your perspective.",explanationEs:"'Te entiendo perfectamente' valida lo que siente el cliente sin ceder en el fondo del asunto. Crea una seguridad psicológica que le abre a escuchar tu punto de vista."}],"prod-8":[{question:"She has paid, she is delighted, she is holding the bag. You take her number. When does the first message go out?",questionEs:"Ha pagado, está encantada, tiene la bolsa en la mano. Le coges el número. ¿Cuándo le mandas el primer mensaje?",options:["Tonight, so it lands when she has a quiet moment to read it","In three days, once she has had a chance to try it properly","Right there, in front of her, before she stands up","Whenever she messages you first — you never open the conversation"],optionsEs:["Esta noche, para que le llegue en un rato tranquilo","En tres días, cuando ya lo haya probado en condiciones","Ahí mismo, delante de ella, antes de que se levante","Cuando escriba ella — tú nunca abres la conversación"],correctIndex:2,explanation:"Send it there or you will not send it at all — and if she has typed a digit wrong, that is the only moment anyone will ever find out. Two lines: who you are and where you are.",explanationEs:"Se lo mandas ahí o no se lo mandas nunca — y si se ha equivocado en un dígito, ese es el único momento en que alguien va a enterarse. Dos líneas: quién eres y dónde estás."},{question:"The sale is done but the moment has gone a bit flat — she is already half-turned towards the door. Do you ask for the number?",questionEs:"La venta está hecha pero el momento se ha quedado plano — ya está medio girada hacia la puerta. ¿Le pides el número?",options:["No — skip it, and let her leave on a good ending instead","Yes, always: a number is a number and you can warm her up later","Yes, but ask for her email as well so you have a second way in","Yes, and tell her you will send a reminder when it is time to reorder"],optionsEs:["No — sáltatelo, y deja que se vaya con un buen final","Sí, siempre: un número es un número y ya la calentarás luego","Sí, y pídele también el correo para tener una segunda vía","Sí, y dile que le avisarás cuando toque reponer"],correctIndex:0,explanation:"A number squeezed out of somebody halfway to the door never gets used, and asking turns a lovely ending into a bit of admin. Take it when the moment offers it and let it go when it does not.",explanationEs:"Un número sacado a la fuerza a alguien que ya va hacia la puerta no se usa nunca, y pedirlo convierte un final bonito en papeleo. Cógelo cuando el momento lo ofrece y déjalo cuando no."},{question:"What is the whole referral strategy in this job?",questionEs:"¿Cuál es toda la estrategia de recomendaciones en este trabajo?",options:["A message on day seven asking if she knows anyone who would like it","A card with your number on it that she can pass to a friend","A discount she can offer to somebody she sends to the shop","Two promises, asked once, while the bag is still in her hand"],optionsEs:["Un mensaje al séptimo día preguntando si conoce a alguien a quien le guste","Una tarjeta con tu número para que se la pase a una amiga","Un descuento que pueda ofrecer a quien mande a la tienda","Dos promesas, pedidas una vez, con la bolsa aún en la mano"],correctIndex:3,explanation:"Use it once a week, and tell your friends where you got it. Said light, half a joke, at the top of her mood — then never mentioned again. The same sentence eleven days later is a stranger asking a favour.",explanationEs:"Que lo use una vez por semana, y que cuente a sus amigas dónde lo ha comprado. Dicho suave, medio en broma, en su mejor momento — y no se vuelve a mencionar. Esa misma frase once días después es un desconocido pidiendo un favor."}],"psych-1":[{question:"What does 'aggressive' actually mean in this job?",questionEs:"¿Qué significa 'agresivo' de verdad en este trabajo?",options:["Pushing harder and for longer than the seller on the next kiosk over","Certainty. Not begging, not apologising, not chasing anybody","Raising your voice so nobody walking past can pretend they did not hear","Never taking a no, and following them a few steps to make the point"],optionsEs:["Apretar más y más rato que el vendedor del puesto de al lado","Seguridad. Sin rogar, sin pedir perdón y sin perseguir a nadie","Levantar la voz para que nadie que pase pueda fingir que no te ha oído","No aceptar un no, y seguirles unos pasos para dejarlo claro"],correctIndex:1,explanation:"The word scares people, and in this job it does not mean pushing. It means going at it with certainty: you run this bit of pavement, and you are offering something most people walk straight past. Warm, quick, enjoying yourself — not apologising and not chasing.",explanationEs:"La palabra asusta, y en este trabajo no significa presionar. Significa ir con seguridad: este trozo de acera lo llevas tú, y estás ofreciendo algo por delante de lo que casi todo el mundo pasa de largo. Cálido, rápido, disfrutando — sin pedir perdón y sin perseguir a nadie."},{question:"Why does the 'Luxury Aggressor' use statements instead of questions when approaching?",questionEs:"¿Por qué el 'Agresor de Lujo' usa afirmaciones en vez de preguntas al abordar?",options:["Because questions sound rude while statements sound polite","Because statements are simply faster to say aloud","Because tourists secretly prefer being given firm orders","Because statements command while questions invite rejection"],optionsEs:["Porque las preguntas suenan groseras y las afirmaciones educadas","Porque una afirmación es sencillamente más rápida de decir","Porque en el fondo al turista le gusta que le manden","Porque la afirmación manda mientras la pregunta invita al rechazo"],correctIndex:3,explanation:"Questions like 'Can I show you something?' give the customer an easy escape ('No thanks'). Statements like 'I'll show you something amazing' lead the customer rather than asking permission.",explanationEs:"Preguntas como '¿Puedo enseñarte una cosa?' le dan al cliente una salida fácil ('No, gracias'). Afirmaciones como 'Te voy a enseñar algo increíble' guían al cliente en vez de pedirle permiso."},{question:"What should you do after delivering your opening line?",questionEs:"¿Qué debes hacer justo después de soltar tu frase de apertura?",options:["Keep talking to fill the silence","Pause and let the silence work","Show the product right away","Follow up with another question"],optionsEs:["Seguir hablando para no dejar ningún silencio","Hacer una pausa y dejar que el silencio trabaje","Enseñarle el producto de inmediato, sin esperar","Rematar enseguida con otra pregunta más"],correctIndex:1,explanation:"The Luxury Aggressor pauses after the opener. Silence creates anticipation and shows confidence. Rushing signals nervousness.",explanationEs:"El Agresor de Lujo hace una pausa tras la apertura. El silencio crea expectación y transmite seguridad. Ir con prisas delata nervios."}],"psych-2":[{question:"Why is the 4-minute rotation system effective for energy management?",questionEs:"¿Por qué el sistema de rotación de 4 minutos funciona tan bien para gestionar la energía?",options:["It works like interval training — high intensity followed by recovery","It simply hands you more breaks — less time actually selling","It frees you to check your phone — a distraction between pitches","It lowers how many tourists you must stop — an easier target"],optionsEs:["Funciona como el entrenamiento por intervalos: mucha intensidad y luego recuperación","Simplemente te da más descansos: menos tiempo vendiendo de verdad","Te deja mirar el móvil: una distracción entre pitch y pitch","Reduce a cuántos turistas tienes que parar: un objetivo más fácil"],correctIndex:0,explanation:"The 4-minute rotation creates an interval-training effect. You give 100% energy for 4 minutes, then recover inside. This oscillation prevents the burnout that kills performance.",explanationEs:"La rotación de 4 minutos crea un efecto de entrenamiento por intervalos. Das el 100% de energía durante 4 minutos y luego te recuperas dentro. Ese vaivén evita el desgaste que hunde tu rendimiento."},{question:"What should you eat during your lunch break to maintain afternoon energy?",questionEs:"¿Qué deberías comer en la pausa del mediodía para mantener la energía por la tarde?",options:["Light protein, salads, and fruit","Pasta and bread for lasting carbs","Nothing at all to stay sharp","A heavy plate to feel full"],optionsEs:["Proteína ligera, ensaladas y fruta","Pasta y pan para tener hidratos","Nada de nada para seguir despierto","Un plato contundente para quedarte lleno"],correctIndex:0,explanation:"Heavy meals redirect blood from your brain to your stomach, causing afternoon fog. Light protein, salads, and fruit provide sustained energy without the crash.",explanationEs:"Las comidas pesadas mandan la sangre del cerebro al estómago y te dejan atontado por la tarde. La proteína ligera, las ensaladas y la fruta te dan energía sostenida sin bajón."},{question:"How does 'faking' energy actually work according to psychological research?",questionEs:"Según la investigación en psicología, ¿cómo funciona de verdad 'fingir' energía?",options:["It only works for veterans who have sold for many years","It's really just lying to yourself until the shift ends","It doesn't really work because customers can always tell you're faking","Your body can trick your brain into actually feeling more energetic"],optionsEs:["Solo funciona para los veteranos que llevan muchos años vendiendo","No es más que mentirte a ti mismo hasta que acaba el turno","En realidad no funciona, porque el cliente siempre nota que finges","Tu cuerpo puede engañar a tu cerebro para sentirte de verdad con más energía"],correctIndex:3,explanation:"Research on embodied cognition shows that acting energetic (power poses, smiling, speaking loudly) actually changes your brain chemistry and creates real energy.",explanationEs:"La investigación sobre cognición corporeizada demuestra que actuar con energía (posturas de poder, sonreír, hablar alto) cambia de verdad tu química cerebral y genera energía real."}],"psych-3":[{question:"What is the ideal duration for maintaining eye contact with a customer?",questionEs:"¿Cuánto tiempo es lo ideal para mantener el contacto visual con un cliente?",options:["2-3 seconds at a time","Ten seconds or more to dominate","Constant contact for the whole pitch","Tiny split-second glances to avoid pressure"],optionsEs:["Unos 2-3 segundos cada vez","Diez segundos o más para dominar","Contacto fijo durante todo el pitch","Miraditas de un instante para no agobiar"],correctIndex:0,explanation:"The sweet spot for eye contact is 2-3 seconds at a time. Too short signals nervousness; too long feels aggressive. Brief, confident connection builds trust.",explanationEs:"El punto justo del contacto visual son 2-3 segundos cada vez. Muy poco delata nervios; demasiado resulta agresivo. Una conexión breve y segura genera confianza."},{question:"Why is upspeak (rising intonation at the end of statements) harmful in sales?",questionEs:"¿Por qué la entonación ascendente al final de las frases perjudica en ventas?",options:["It undermines your authority by making statements sound like questions","It makes you sound far too friendly and soft to ever be taken seriously","It buries your actual words so much that customers simply cannot make them out","It comes across as plain rude in the eyes of most tourist cultures out there"],optionsEs:["Debilita tu autoridad porque hace que las afirmaciones suenen a preguntas","Hace que suenes demasiado simpático y blando como para que te tomen en serio","Entierra tanto tus palabras que el cliente directamente no consigue entenderlas","Resulta simplemente grosera a ojos de la mayoría de culturas turistas de fuera"],correctIndex:0,explanation:"Upspeak makes statements sound like questions, which subconsciously undermines your authority and certainty. End sentences with a stable or slightly lower pitch.",explanationEs:"La entonación ascendente hace que las afirmaciones parezcan preguntas, lo que mina de forma inconsciente tu autoridad y tu certeza. Termina las frases con un tono estable o un poco más grave."},{question:"What is the purpose of a 'confidence anchor'?",questionEs:"¿Para qué sirve un 'ancla de confianza'?",options:["To show your rank inside the company to teammates","To impress customers by wearing an expensive piece of jewelry","To help you remember your daily sales targets","To trigger a confident state through a practiced physical gesture"],optionsEs:["Para enseñar a tus compañeros tu rango dentro de la empresa","Para impresionar al cliente llevando una joya cara y llamativa","Para ayudarte a recordar tus objetivos de venta del día","Para activar un estado de seguridad con un gesto físico ya practicado"],correctIndex:3,explanation:"A confidence anchor is a physical gesture paired with a powerful memory that, after repeated practice, can trigger a confident state on demand.",explanationEs:"Un ancla de confianza es un gesto físico unido a un recuerdo potente que, tras practicarlo mucho, puede activar un estado de seguridad cuando quieras."}],"psych-4":[{question:"You are about to walk up to somebody and you catch yourself thinking 'most of them say no anyway'. What is that thought?",questionEs:"Vas a acercarte a alguien y te pillas pensando 'total, casi todos dicen que no'. ¿Qué es ese pensamiento?",options:["Healthy perspective that keeps the pressure off you","An excuse, before you have done anything to earn it","A sign you should pick an easier-looking customer","The right frame if the shop has been quiet all morning"],optionsEs:["Perspectiva sana que te quita presión de encima","Una excusa, antes de haber hecho nada para ganártela","Señal de que deberías elegir un cliente más fácil","El enfoque correcto si la tienda lleva toda la mañana muerta"],correctIndex:1,explanation:"The numbers are real and they help — AFTER a demo you gave everything to. Said beforehand, the same sentence just gives you permission to go at this one at half speed, which is the most expensive habit a seller can pick up.",explanationEs:"Los números son reales y ayudan — DESPUÉS de una demo en la que lo has dado todo. Dicho antes, esa misma frase solo te da permiso para ir a medio gas con esta, que es la costumbre más cara que puede coger un vendedor."},{question:"She walks out without buying. What happens in your head, in what order?",questionEs:"Se va sin comprar. ¿Qué pasa en tu cabeza, y en qué orden?",options:["Wipe it immediately, then go through what happened at the end of the shift","Decide whether she was ever a real buyer, then forget the whole thing","Run the five questions while she reaches the door, then wipe it and turn round","Wipe it immediately — replaying it at all is what drags a seller down"],optionsEs:["Bórralo ya, y repasa lo que pasó al final del turno","Decide si alguna vez iba a comprar de verdad, y olvídalo todo","Repasa las cinco preguntas mientras llega a la puerta, bórralo y date la vuelta","Bórralo ya — darle vueltas es justo lo que hunde a un vendedor"],correctIndex:2,explanation:"Check, then reset — and only in that order. Reset without the check is just forgetting, and a seller who forgets every no makes the same mistake for a year without ever noticing it.",explanationEs:"Comprobar, luego borrar — y solo en ese orden. Borrar sin comprobar es olvidar, y un vendedor que olvida cada no repite el mismo fallo durante un año sin enterarse."},{question:"You run the five questions and every one comes back clean. She still walked. Now what?",questionEs:"Repasas las cinco preguntas y todas salen limpias. Aun así se ha ido. ¿Ahora qué?",options:["Put it down — that one is not on you, and go to the next person","Assume you are missing something and run the list again","Ask a colleague to watch your next demo before you take another customer","Take the rest of the hour off the floor to get your head straight"],optionsEs:["Suéltalo — esa no va contigo, y a por la siguiente persona","Da por hecho que se te escapa algo y repasa la lista otra vez","Pide a un compañero que mire tu próxima demo antes de coger a otra clienta","Tómate el resto de la hora fuera del suelo para despejarte"],correctIndex:0,explanation:"That is the whole deal. If the list is clean you did the job, and the reason is hers — a rush, an empty wallet, a rule about not buying on holiday, or simply a bad customer. They exist, and they are part of the game.",explanationEs:"Ese es el trato entero. Si la lista sale limpia, has hecho tu trabajo, y el motivo es suyo — prisa, cartera vacía, la norma de no comprar de viaje, o sencillamente una mala clienta. Existen, y forman parte del juego."}],"psych-5":[{question:"Your mood spreads to the customer. In what order does that happen?",questionEs:"Tu ánimo se le pega al cliente. ¿En qué orden pasa eso?",options:["Through rewards, incentives, and social pressure between people","Through logic, evidence, and rational persuasion between people","Through habit, repetition, and daily routine between people","Through mimicry, feedback, and synchronization between people"],optionsEs:["Mediante las recompensas, los incentivos y la presión social entre personas","Mediante la lógica, las pruebas y la persuasión racional entre personas","Mediante el hábito, la repetición y la rutina diaria entre personas","Mediante la imitación, la retroalimentación y la sincronización entre personas"],correctIndex:3,explanation:"Mood is catching, and it goes in this order: they copy your face without meaning to, their own face feeds the mood back to them, and thirty seconds later you are both in the same one. Which is why the seller sets the temperature, not the customer.",explanationEs:"El ánimo se pega, y va en este orden: te copian la cara sin querer, su propia cara les devuelve el ánimo, y treinta segundos después estáis los dos en el mismo. Por eso la temperatura la pone el vendedor, no el cliente."},{question:"When is calm, warm energy most appropriate?",questionEs:"¿Cuándo es más adecuada una energía tranquila y cálida?",options:["With loud teenagers, big crowds, and stag parties","With couples, older customers, and serious buyers","With young groups, party tourists, and holiday shoppers","With rushed passers-by, curious kids, and bargain hunters"],optionsEs:["Con adolescentes ruidosos, grandes multitudes y despedidas de soltero","Con parejas, clientes mayores y compradores serios","Con grupos jóvenes, turistas de fiesta y compradores de vacaciones","Con transeúntes con prisa, niños curiosos y cazadores de gangas"],correctIndex:1,explanation:"Calm, warm energy works best with couples, older customers, and serious buyers. It creates trust and sophistication. Match the customer's energy, then slightly elevate it.",explanationEs:"La energía tranquila y cálida funciona mejor con parejas, clientes mayores y compradores serios. Crea confianza y sofisticación. Iguala la energía del cliente y luego súbela un poco."},{question:"Why should you never vent frustration on the sales floor?",questionEs:"¿Por qué nunca deberías desahogar tu frustración en la zona de venta?",options:["It looks unprofessional but has no real effect on your sales","It poisons the energy ecosystem for everyone, including customers","It only affects your own mood, not the people around you","It only annoys your teammates, but customers never pick up on it"],optionsEs:["Queda poco profesional, pero no tiene ningún efecto real en tus ventas","Envenena el ecosistema de energía para todos, incluidos los clientes","Solo afecta a tu propio estado de ánimo, no a la gente de alrededor","Solo molesta a tus compañeros, pero los clientes nunca se dan cuenta"],correctIndex:1,explanation:"The shop is an energy ecosystem. Complaining on the floor creates negative emotional contagion that affects teammates and customers alike. Vent in the back room, never in customer areas.",explanationEs:"La tienda es un ecosistema de energía. Quejarte en la zona de venta genera un contagio emocional negativo que afecta tanto a tus compañeros como a los clientes. Desahógate en la trastienda, nunca en las zonas de clientes."}],"psych-6":[{question:"How does sleep deprivation specifically affect sales performance?",questionEs:"¿Cómo afecta concretamente la falta de sueño a tu rendimiento en ventas?",options:["It reduces emotional resilience, verbal fluency, and facial expressiveness","It actually boosts your drive, your focus, and your hunger to close more sales","It just leaves you a bit tired but keeps your actual selling as sharp as ever","It only ever hurts you on the big closes, never on the smaller everyday ones"],optionsEs:["Reduce tu resistencia emocional, tu fluidez verbal y tu expresividad facial","En realidad te sube el empuje, la concentración y las ganas de cerrar más ventas","Solo te deja un poco cansado, pero tu venta sigue tan afilada como siempre","Solo te perjudica en los cierres grandes, nunca en los pequeños del día a día"],correctIndex:0,explanation:"Sleep deprivation affects the prefrontal cortex, reducing emotional resilience and verbal fluency, and flattening your facial expressions. These are exactly the skills you need for sales.",explanationEs:"La falta de sueño afecta a la corteza prefrontal: reduce tu resistencia emocional y tu fluidez verbal, y apaga tus expresiones faciales. Son justo las habilidades que necesitas para vender."},{question:"Why is exercise particularly valuable for salespeople?",questionEs:"¿Por qué el ejercicio es especialmente valioso para quien vende?",options:["It impresses your manager and proves you take the job seriously","It builds energy, lung capacity for voice projection, and confidence","It makes you look better in the uniform and in customer photos","It gives you stories and small talk to share with your customers"],optionsEs:["Impresiona a tu encargado y demuestra que te tomas el trabajo en serio","Te da energía, capacidad pulmonar para proyectar la voz y confianza","Hace que te veas mejor con el uniforme y en las fotos con clientes","Te da anécdotas y temas de conversación para compartir con los clientes"],correctIndex:1,explanation:"Exercise builds baseline energy, improves breathing for better voice projection, and builds confidence through physical capability — all directly relevant to sales performance.",explanationEs:"El ejercicio te da energía de base, mejora la respiración para proyectar mejor la voz y refuerza la confianza a través de la capacidad física: todo directamente relacionado con tu rendimiento en ventas."},{question:"What type of lunch should you eat to maintain afternoon energy?",questionEs:"¿Qué tipo de comida deberías tomar para mantener la energía por la tarde?",options:["Light protein, salad, and fruit","Pizza, pasta, and fizzy drinks","Burgers, chips, and dessert","Bread, cheese, and pastries"],optionsEs:["Proteína ligera, ensalada y fruta","Pizza, pasta y refrescos con gas","Hamburguesas, patatas fritas y postre","Pan, queso y bollería"],correctIndex:0,explanation:"Heavy meals redirect blood from the brain to the stomach, causing afternoon fog. Light protein, salads, and fruit give you sustained energy without the crash.",explanationEs:"Las comidas pesadas desvían la sangre del cerebro al estómago y provocan la niebla mental de la tarde. La proteína ligera, la ensalada y la fruta te dan energía sostenida sin el bajón."}],"psych-7":[{question:"Which Cialdini principle is activated when you give a customer a free hand massage before pitching?",questionEs:"¿Qué principio de Cialdini se activa cuando le haces a un cliente un masaje de manos gratis antes de empezar a venderle?",options:["Commitment","Consistency","Reciprocity","Social proof"],optionsEs:["Compromiso","Coherencia","Reciprocidad","Prueba social"],correctIndex:2,explanation:"Reciprocity is the principle that people feel obliged to give back when they receive something. A free hand massage is a gift that creates a psychological pull to reciprocate — by listening to your pitch or making a purchase.",explanationEs:"La reciprocidad es el principio por el que la gente se siente obligada a devolver algo cuando recibe un detalle. Un masaje de manos gratis es un regalo que crea un tirón psicológico a corresponder: escuchando tu argumentario o comprando."},{question:"How does the {locationName} price activate the scarcity principle?",questionEs:"¿Cómo activa el precio de {locationName} el principio de escasez?",options:["It makes each customer feel personally chosen, as if the low price were a private favour just for them","It creates a price that exists only here in {locationName} and cannot be found anywhere back home","It makes the product itself feel rare and scarce, as if the stock could sell out at any moment","It pressures customers to decide right now, as if the price might disappear before they walk away"],optionsEs:["Hace que cada cliente se sienta elegido en persona, como si el precio bajo fuera un favor solo para él","Crea un precio que solo existe aquí, en {locationName}, y que no puede encontrar en su país","Hace que el producto en sí parezca raro y escaso, como si las existencias pudieran agotarse ya","Presiona al cliente para que decida ahora mismo, como si el precio pudiera desaparecer enseguida"],correctIndex:1,explanation:"The {locationName} price creates genuine scarcity — the {currency}300 price only exists here. Customers cannot get this price back home, which makes the opportunity geographically limited and rare.",explanationEs:"El precio de {locationName} crea una escasez real: el precio de {currency}300 solo existe aquí. El cliente no puede conseguir este precio en su país, lo que hace que la oportunidad esté limitada geográficamente y sea rara."},{question:"Why is getting a small 'yes' early in the interaction powerful?",questionEs:"¿Por qué es tan potente conseguir un pequeño 'sí' al principio de la interacción?",options:["It activates consistency — people want to act in alignment with their commitments","It activates authority — people obey anyone who sounds confident and in control","It activates liking — people buy more from someone they find friendly and warm","It activates scarcity — people rush to grab whatever they fear they might lose"],optionsEs:["Activa la coherencia: la gente quiere actuar en línea con sus compromisos","Activa la autoridad: la gente obedece a quien suena seguro y con el control","Activa la simpatía: la gente compra más a quien le resulta cercano y agradable","Activa la escasez: la gente corre a por lo que teme poder perder"],correctIndex:0,explanation:"The principle of consistency means that once people commit to something — even a small yes — they want to act in alignment with that commitment. Small initial agreements make larger agreements more likely.",explanationEs:"El principio de coherencia significa que, una vez que la gente se compromete con algo (aunque sea un pequeño sí), quiere actuar en línea con ese compromiso. Los pequeños acuerdos iniciales hacen más probables los acuerdos más grandes."}],"psych-8":[{question:"What are the four stages of developing sales intuition?",questionEs:"¿Cuáles son las cuatro fases para desarrollar la intuición en ventas?",options:["Conscious Incompetence, Conscious Competence, Unconscious Competence, and Mastery","Classroom Learning, Daily Practising, Patient Teaching, and Natural Leading","Blissful Ignorance, Painful Awareness, Steady Improvement, and Complete Perfection","Nervous Beginner, Capable Intermediate, Confident Advanced, and Seasoned Expert"],optionsEs:["Incompetencia consciente, competencia consciente, competencia inconsciente y maestría","Aprender en el aula, practicar a diario, enseñar con paciencia y liderar con soltura","Ignorancia feliz, toma de conciencia dolorosa, mejora constante y perfección total","Principiante nervioso, intermedio capaz, avanzado seguro y experto veterano"],correctIndex:0,explanation:"The four stages are Conscious Incompetence (new, thinking hard), Conscious Competence (seeing patterns with effort), Unconscious Competence (intuitive knowing), and Mastery (where you can also teach others).",explanationEs:"Las cuatro fases son: incompetencia consciente (novato, pensando mucho), competencia consciente (ves patrones con esfuerzo), competencia inconsciente (saber intuitivo) y maestría (donde además puedes enseñar a los demás)."},{question:"What does it mean when a customer touches their face while looking at the product?",questionEs:"¿Qué significa que un cliente se toque la cara mientras mira el producto?",options:["They're feeling anxious about the price — a clear warning signal","They're just checking their own makeup — a signal to ignore","They're getting bored and want to leave — a bad sign to read","They're imagining themselves using it — a very positive signal"],optionsEs:["Le está entrando agobio por el precio: una clara señal de alarma","Solo se está revisando el maquillaje: una señal para ignorar","Se está aburriendo y quiere irse: una mala señal que interpretar","Se está imaginando usándolo: una señal muy positiva"],correctIndex:3,explanation:"Face-touching while looking at a product is a strong positive signal. It shows the customer is unconsciously imagining themselves using it — a key buying indicator.",explanationEs:"Que se toque la cara mientras mira el producto es una señal muy positiva. Indica que el cliente, sin darse cuenta, se está imaginando usándolo: un indicador clave de compra."},{question:"A demo ended with no sale. What do you actually ask yourself?",questionEs:"Una demo ha acabado sin venta. ¿Qué te preguntas de verdad?",options:["Whether she was ever going to buy, so you can spot the type next time","Whether the rota is against you and you keep getting the dead hours","Did I say something wrong, skip a step, fill the silence, get lazy?","Nothing — most people say no anyway, so there is nothing to look at"],optionsEs:["Si iba a comprar en algún momento, para reconocer el tipo la próxima","Si el cuadrante va en tu contra y te tocan siempre las horas muertas","¿Dije algo mal, me salté un paso, llené el silencio, me relajé?","Nada — la mayoría dice que no igual, así que no hay nada que mirar"],correctIndex:2,explanation:"Run the honest checklist first: wrong words, skipped step, filled the silence, went lazy halfway, stopped early on the ladder. If the honest answer really is 'I did all of it', then it is not on you — that was a bad customer and it is part of the game. What you cannot do is work out in advance who was never going to buy. Nobody can; that only comes with time.",explanationEs:'Pásate primero la lista honesta: palabras equivocadas, un paso saltado, el silencio llenado, relajarte a media demo, quedarte corto en la escalera. Si la respuesta sincera es "lo hice todo", entonces no es cosa tuya — era un mal cliente y es parte del juego. Lo que no puedes es adivinar de antemano quién no iba a comprar nunca. Nadie puede; eso solo llega con el tiempo.'}],"stop-1":[{question:"A woman is walking towards you down the mall, still a good few strides off. When do you first speak to her?",questionEs:"Una mujer viene hacia ti por el pasillo, todavía a unas cuantas zancadas. ¿Cuándo le hablas por primera vez?",options:["Now — four or five metres out, while she is still walking towards you","When she is close enough to touch, so she cannot pretend she did not hear you","After she has passed you, calling to her back and hoping that she turns round","Never — you hold the sample up and wait quietly for her to notice you first"],optionsEs:["Ahora — a cuatro o cinco metros, mientras sigue caminando hacia ti","Cuando la tengas tan cerca que no pueda fingir que no te ha oído","Después de que pase, llamándola por la espalda y esperando que se gire","Nunca — levantas la muestra y esperas callado a que se fije en ti"],correctIndex:0,explanation:"You want her eyes on you before you take a single step, and four or five metres is where that is still possible. Leave it until she is nearly level with you and by the time she has registered you and turned her head, she has already gone past.",explanationEs:"Quieres que te mire antes de dar un solo paso, y a cuatro o cinco metros todavía te da tiempo. Si esperas a tenerla casi a tu altura, para cuando te ha visto y ha girado la cabeza ya te ha pasado de largo."},{question:"She looked at you, you moved in and offered her the sample — she waves it away without breaking stride. What now?",questionEs:"Te ha mirado, te has acercado y le ofreces la muestra — la aparta con la mano sin dejar de andar. ¿Y ahora qué?",options:["Let her go and look for the next one — a refused sample is a no, and no means no","Push it at her again and keep pushing until she takes the thing out of your hand","Apologise for bothering her, step out of her way and let her carry on past you","Carry straight on into the rush line and the question, exactly the same"],optionsEs:["Déjala ir y busca a la siguiente — muestra rechazada es un no, y un no es un no","Insístele con la muestra y sigue insistiendo hasta que te la coja de la mano","Pídele perdón por molestar, apártate y déjala seguir su camino","Sigues igual con lo de la prisa y la pregunta, exactamente lo mismo"],correctIndex:3,explanation:`The sample is a coin toss and it does not matter which way it lands. She takes it, lovely. She waves it away, nothing happens — you were not rejected, because you never asked her for anything. The follow-up runs in both cases: "Listen, I know you're in a rush — but can I ask you something really quick? It's just that you look so good, I have to ask what you normally use on your skin."`,explanationEs:'La muestra es cara o cruz y da igual de qué lado caiga. Si la coge, genial. Si la aparta con la mano, no pasa nada — no te ha rechazado, porque no le has pedido nada. Lo que viene después va igual en los dos casos: "Mira, sé que vas con prisa — ¿pero te puedo preguntar una cosa rapidísima? Es que te veo tan bien que tengo que preguntarte qué usas normalmente para la piel."'},{question:`You have just said "You know what — just because you look so amazing, I'm going to give you a small gift, you're going to love it." What is the very next thing you do?`,questionEs:'Acabas de decir "¿Sabes qué? Solo porque estás guapísima, te voy a hacer un regalito, te va a encantar." ¿Qué es lo siguiente que haces?',options:["Ask her whether she has got two minutes to come in and have a quick look","Turn round and walk into the shop without looking back at her","Stay where you are and watch to see whether she starts to follow you in","Hold the gift towards the door and wave her through it ahead of you"],optionsEs:["Preguntarle si tiene dos minutos para entrar y echar un vistazo rápido","Darte la vuelta y entrar en la tienda sin mirar atrás","Quedarte donde estás y mirar a ver si empieza a seguirte","Señalarle la puerta con el regalo y dejarla pasar delante de ti"],correctIndex:1,explanation:`Turn around and walk. You do not give a damn whether she follows you — checking asks permission, and asking permission gives her the chance to say no. And if she does not follow, nothing happens: you get to your station, turn round and say "Come on guys, it's two seconds, I promise. Come." Then you turn round and walk again.`,explanationEs:'Date la vuelta y anda. Te da igual si te sigue — comprobarlo es pedir permiso, y pedir permiso le da la oportunidad de decir que no. Y si no te sigue, no pasa nada: llegas a tu sitio, te giras y dices "Venga chicos, son dos segundos, os lo prometo. Venid." Y luego te das la vuelta y sigues andando.'}],"stop-2":[{question:"What makes a compliment feel genuine rather than fake?",questionEs:"¿Qué hace que un cumplido suene sincero y no falso?",options:["Using longer, more elaborate and flowery phrasing","Complimenting a feature they didn't choose, like their height","Being specific about something the person chose","Giving several quick compliments one after another"],optionsEs:["Usar frases más largas, rebuscadas y floridas","Alabar un rasgo que no ha elegido, como su altura","Ser concreto con algo que la persona ha elegido","Soltar varios cumplidos rápidos, uno tras otro"],correctIndex:2,explanation:"Specific compliments about choices people make (clothes, accessories, grooming) feel like real observations. Generic or physical compliments often feel like lines or flattery.",explanationEs:"Los cumplidos concretos sobre lo que la gente elige (ropa, complementos, su arreglo personal) suenan a observación de verdad. Los cumplidos genéricos o sobre el físico suelen sonar a piropo o a peloteo."},{question:"What is the recommended approach when complimenting men?",questionEs:"¿Cuál es la mejor forma de hacerle un cumplido a un hombre?",options:["Focus on style choices, accessories, or partner compliments that include them indirectly","Compliment their physique very directly, since men always respond best to exactly that","Skip men altogether as targets, because they hardly ever buy cosmetics out on the street","Use the exact same compliment lines you already use with women, every single time"],optionsEs:["Céntrate en su estilo, sus complementos o en halagar a su pareja incluyéndolo a él de forma indirecta","Alábale el físico muy directamente, que es lo que mejor les funciona a los hombres","Pasa de los hombres como objetivo, que casi nunca compran cosmética en plena calle","Usa exactamente las mismas frases de halago que usas con las mujeres, siempre igual"],correctIndex:0,explanation:"Men are often less accustomed to receiving compliments from strangers. Focus on style choices, accessories, or compliment their partner while engaging them as the observer.",explanationEs:"Los hombres no están tan acostumbrados a que un desconocido les eche un cumplido. Céntrate en su estilo o sus complementos, o halaga a su pareja haciéndole a él de cómplice."},{question:"When should you avoid using a compliment opener?",questionEs:"¿Cuándo es mejor no usar un cumplido para abrir?",options:["When the customer already looks quite angry or in a real hurry to get by","When the customer happens to be walking with a whole group of friends","When you cannot find something genuinely specific to compliment","When the weather is bad and everybody is hurrying past you quickly"],optionsEs:["Cuando el cliente ya parece bastante enfadado o con muchísima prisa","Cuando el cliente va caminando con todo un grupo de amigos","Cuando no encuentras nada concreto y sincero que halagar","Cuando hace mal tiempo y todo el mundo pasa a tu lado con prisa"],correctIndex:2,explanation:"If you cannot find something genuinely specific to compliment, it is better to use a different stopping technique. Fake compliments are detected instantly and destroy trust.",explanationEs:"Si no encuentras nada concreto y sincero que halagar, mejor tira de otra técnica para parar. Los cumplidos falsos se notan al instante y se cargan la confianza."}],"stop-3":[{question:"What is the humor stop formula?",questionEs:"¿Cuál es la fórmula de la parada con humor?",options:["Light observational humor + self-awareness about selling + quick transition to value","Physical comedy + exaggerated funny faces + a long drawn-out comedic routine","Rapid-fire jokes one after another + big loud laughs + a really hard push to buy right now","Gentle teasing of the customer + a cheeky wink + going straight to the price"],optionsEs:["Humor ligero de observación + reírte de que estás vendiendo + salto rápido al valor","Comedia física + caras graciosas exageradas + un numerito largo de humor","Chistes sin parar uno tras otro + risas fuertes + un empujón muy fuerte para que compre ya","Piques suaves al cliente + un guiño pícaro + directo al precio"],correctIndex:0,explanation:"The humor stop uses light observational humor, acknowledges the awkwardness of street selling, and quickly transitions to value. You're not doing stand-up — you're breaking tension with a smile.",explanationEs:"La parada con humor usa un humor ligero de observación, reconoce lo raro que es vender en la calle y salta rápido al valor. No estás haciendo un monólogo: rompes el hielo con una sonrisa."},{question:"Which type of humor is universally safest in sales?",questionEs:"¿Qué tipo de humor es el más seguro en ventas?",options:["Self-deprecating humor","Provocative edgy humor","Sharp political humor","Cutting sarcastic humor"],optionsEs:["El humor autocrítico","El humor provocador y salvaje","El humor político y afilado","El humor sarcástico y cortante"],correctIndex:0,explanation:"Self-deprecating humor is safest because it shows confidence and vulnerability without risking offense. You're the punchline, never the customer.",explanationEs:"El humor autocrítico es el más seguro porque muestra seguridad y cercanía sin arriesgarte a ofender. El blanco de la broma eres tú, nunca el cliente."},{question:"What should you do if a customer doesn't laugh at your first humorous attempt?",questionEs:"¿Qué haces si el cliente no se ríe con tu primer intento de humor?",options:["Double down and push a few more jokes right at them","Escalate straight to a bigger, far more extreme joke","Pivot immediately to a warm, professional tone","Just turn around, walk off, and give up on them"],optionsEs:["Insiste y suéltale unos cuantos chistes más","Sube la apuesta con un chiste aún más bestia","Cambia enseguida a un tono cálido y profesional","Date media vuelta, lárgate y olvídate de ese cliente"],correctIndex:2,explanation:"If humor doesn't land on the first attempt, pivot immediately. Don't keep trying — it becomes awkward. Read the customer's receptivity and adapt your approach.",explanationEs:"Si el humor no cuela a la primera, cambia de tercio al momento. No insistas: se vuelve incómodo. Lee cómo está el cliente y adapta tu enfoque."}],"stop-4":[{question:"You are inventing the urgency — every line in this lesson does. So where is the line you do not cross?",questionEs:"La urgencia te la estás inventando — todas las frases de esta lección lo hacen. ¿Dónde está la línea que no se cruza?",options:["Only say it if you can prove it — if the stock is not really low, do not say it is","Only use urgency on a customer who has already said she likes the product","Never promise something the shop has to honour after she has walked out","There is no line — say whatever gets her to yes, that is the job"],optionsEs:["Dilo solo si lo puedes demostrar — si de verdad no queda poco stock, no lo digas","Usa la urgencia solo con una clienta que ya te ha dicho que le gusta el producto","No prometas nunca algo que la tienda tenga que cumplir cuando ella ya se haya ido","No hay línea — di lo que haga falta para que diga que sí, ese es el trabajo"],correctIndex:2,explanation:'"Two left" is theatre and she half knows it — every seller in the world talks their product up. What you cannot do is write a cheque the shop has to cash tomorrow: something held for her, a price waiting for her next visit, a promise about after she has gone. That is the one that comes back on the shop. Everything this side of it is yours to play with.',explanationEs:'"Quedan dos" es teatro y ella medio lo sabe — todos los vendedores del mundo hablan bien de su producto. Lo que no puedes hacer es firmar un cheque que la tienda tenga que pagar mañana: algo guardado para ella, un precio esperándola en su próxima visita, una promesa para cuando ya se haya ido. Eso es lo que le vuelve a la tienda. Todo lo de este lado es tuyo para jugar.'},{question:"The {currency}300 price exists here but not back home. Which type of urgency is that?",questionEs:"El precio de {currency}300 existe aquí pero no en su país. ¿Qué tipo de urgencia es esa?",options:["Season-based urgency","Location-based urgency","Quantity-based urgency","Time-based urgency"],optionsEs:["Urgencia por temporada","Urgencia por ubicación","Urgencia por cantidad","Urgencia por tiempo"],correctIndex:1,explanation:"This is location-based urgency. The syringe is {currency}300 here and only here. Once the customer crosses the border it is back to {currency}500. Genuine scarcity, and they can check it.",explanationEs:"Es urgencia por ubicación. La jeringa son {currency}300 aquí y solo aquí. En cuanto el cliente cruza la frontera, vuelve a {currency}500. Escasez real, y lo pueden comprobar."},{question:"Why does urgency help customers who genuinely want your product?",questionEs:"¿Por qué la urgencia ayuda a los clientes que de verdad quieren tu producto?",options:["It pressures them into rushing a purchase that they will most likely regret later on","It makes them feel guilty enough to go and buy something they really do not need","It helps them overcome procrastination and make a decision they already want to make","It confuses them so much that they stop thinking clearly and just end up paying up"],optionsEs:["Les mete presión para correr una compra de la que seguramente se arrepientan luego","Les hace sentir tan culpables que compran algo que de verdad no necesitan para nada","Les ayuda a vencer la pereza de decidir y a dar el paso que ya quieren dar","Les lía tanto que dejan de pensar con claridad y acaban soltando el dinero sin más"],correctIndex:2,explanation:"Urgency helps customers overcome natural procrastination. Many customers who leave to 'think about it' never return. Ethical urgency helps them make the decision they already want to make.",explanationEs:"La urgencia ayuda al cliente a vencer esa tendencia natural a dejarlo para luego. Muchos que se van a 'pensárselo' no vuelven. La urgencia ética les ayuda a tomar la decisión que ya quieren tomar."}],"stop-5":[{question:"What is the formula for a product-specific stop?",questionEs:"¿Cuál es la fórmula de una parada centrada en un producto?",options:["List every single product → Show the whole catalogue → Ask them to pick one","Lead with the price → Offer a quick discount → Push hard for them to decide","Ask outright if they want to buy → Wait around for a yes → Start the demo","Observe a trait → Connect it to the product → Deliver a personalized opener"],optionsEs:["Enumera todos los productos → Enséñales el catálogo entero → Que elijan uno","Empieza por el precio → Ofrece un descuento rápido → Aprieta para que decidan","Pregunta directo si quieren comprar → Espera a que digan sí → Empieza la demo","Observa un rasgo → Conéctalo con el producto → Suelta una frase de apertura personalizada"],correctIndex:3,explanation:"The formula is: observe a visible trait, connect it naturally to a specific product, then deliver a personalized opener. This makes the stop feel relevant, not random.",explanationEs:"La fórmula es: observa un rasgo visible, conéctalo de forma natural con un producto concreto y suelta una frase de apertura personalizada. Así la parada suena relevante y no al azar."},{question:"It is your first week and you are picking who to stop. How do you choose?",questionEs:"Es tu primera semana y estás eligiendo a quién parar. ¿Cómo eliges?",options:["You stop everybody — that is the whole job right now","Only the ones with visible bags or tired-looking eyes","Only people walking slowly, never anybody in a hurry","Only women, because the syringe is not a man's product"],optionsEs:["Los paras a todos — ahora mismo ese es todo el trabajo","Solo a quien tenga bolsas o los ojos cansados a la vista","Solo a quien vaya andando despacio, nunca a nadie con prisa","Solo a mujeres, porque la jeringa no es un producto de hombre"],correctIndex:0,explanation:"A beginner stops everybody, for the practice. Every filter you invent in your first fortnight costs you reps AND costs you customers — the one who spends the most on you today will not look like it. Knowing who to leave comes with time, and nobody can hand it to you as a list.",explanationEs:"Un novato para a todo el mundo, para practicar. Cada filtro que te inventes en tu primera quincena te cuesta práctica Y te cuesta clientas — la que más se gaste hoy contigo no lo va a aparentar. Saber a quién dejar pasar llega con el tiempo, y no hay lista que nadie te pueda dar."},{question:"Why should you start with one product in your stop rather than offering multiple products?",questionEs:"¿Por qué conviene empezar con un solo producto en la parada en vez de ofrecer varios?",options:["Customers only ever end up wanting one product anyway","Your other products really should always stay hidden away","One single product is honestly much faster to memorize","Multiple options confuse the stop; simplify to amplify"],optionsEs:["Total, el cliente solo acaba queriendo un producto","Tus otros productos deberían quedar siempre bien escondidos","Un solo producto se memoriza la verdad mucho más rápido","Varias opciones lían la parada; simplifica para potenciar"],correctIndex:3,explanation:"Leading with multiple products confuses the stop. Start with one clear, targeted product to get them inside — and out on that floor the one you are aiming at is the syringe. Once they are sitting down, the demo and the ladder do the rest.",explanationEs:"Abrir con varios productos lía la parada. Empieza con uno claro y bien dirigido para meterlos dentro — y ahí fuera al que apuntas es a la jeringa. Una vez sentados, la demo y la escalera hacen el resto."}],"stop-6":[{question:"Someone has said no to your stop and is already walking. What is your last line actually for?",questionEs:"Alguien ha dicho que no a tu parada y ya se está yendo. ¿Para qué sirve de verdad tu última frase?",options:["Buying one more second with them, right now","Making sure they can find you again another day","Getting a number so you can follow it up later","Leaving them something to take away and read"],optionsEs:["Ganar un segundo más con ellos, ahora mismo","Asegurarte de que puedan encontrarte otro día","Sacarles un número para seguirlo más adelante","Dejarles algo para llevarse y leer luego"],correctIndex:0,explanation:"There is no follow-up in this job. They are a stranger on a pavement and you will almost certainly never see them again, so a line that works 'later' does nothing at all. The only last line worth saying is one that turns them round on the spot. And if the no is real, let it be real — say something warm and get straight back to the pavement.",explanationEs:"En este trabajo no hay seguimiento. Es un desconocido en una acera y casi seguro que no lo vuelves a ver, así que una frase que funciona 'más adelante' no hace nada. La única última frase que merece la pena es la que les da la vuelta ahí mismo. Y si el no es de verdad, que sea de verdad — algo cálido y vuelta a la acera."},{question:"What do you put in their hands as they walk away?",questionEs:"¿Qué les pones en la mano cuando se van?",options:["A card with the price, so they can think it over","Nothing at all — nothing goes in their pocket","A free sample so they try it and come back","Your number, in case they change their mind"],optionsEs:["Una tarjeta con el precio, para que se lo piensen","Nada de nada — no se llevan nada en el bolsillo","Una muestra gratis para que la prueben y vuelvan","Tu número, por si cambian de idea"],correctIndex:1,explanation:"A card, a flyer, a sample, a number — anything that goes in their pocket is permission to go and decide somewhere you are not standing, and they will not come back. Whatever you were going to hand over, hand it over here, with the box already in her hand.",explanationEs:"Una tarjeta, un folleto, una muestra, un número — cualquier cosa que se meta en el bolsillo es permiso para ir a decidir donde tú no estás, y no vuelven. Lo que le fueras a dar, dáselo aquí, con la caja ya en la mano."},{question:"How many recovery attempts should you generally make before letting go?",questionEs:"¿Cuántos intentos de recuperación conviene hacer, por lo general, antes de dejarlo?",options:["Five or more, since statistics prove persistence always pays","One to two attempts maximum, then let go gracefully","Never any — respect the very first no completely","As many as it takes until they finally buy"],optionsEs:["Cinco o más, que las estadísticas dicen que insistir compensa","Uno o dos intentos como mucho, y luego lo dejas con elegancia","Ninguno; respeta del todo el primer no","Los que hagan falta hasta que por fin compren"],correctIndex:1,explanation:"One recovery attempt is professional persistence. Two is acceptable if they seem receptive. Three or more is pushing into harassment territory. Know when to walk away gracefully.",explanationEs:"Un intento de recuperación es insistencia profesional. Dos vale si les ves receptivos. Tres o más ya es pasarte y entrar en el terreno del agobio. Sabe cuándo retirarte con elegancia."}],"stop-7":[{question:"Why is copying the top performer's style verbatim usually ineffective?",questionEs:"¿Por qué copiar al pie de la letra el estilo del mejor vendedor no suele funcionar?",options:["Because customers always prefer a brand-new, unfamiliar approach","Because the top performer is simply born naturally talented","Because the top performer's style fits THEIR personality, not yours","Because copying a colleague's style is basically unethical"],optionsEs:["Porque los clientes siempre prefieren un enfoque nuevo y desconocido","Porque el mejor vendedor simplemente ha nacido con un talento natural","Porque el estilo del mejor encaja con SU personalidad, no con la tuya","Porque copiar el estilo de un compañero es básicamente poco ético"],correctIndex:2,explanation:"The top performer has found a style that fits their unique personality, humor, energy, and voice. Your style should be the best version of YOU, not a clone of someone else.",explanationEs:"El mejor vendedor ha encontrado un estilo que encaja con su personalidad, su humor, su energía y su voz. Tu estilo debe ser la mejor versión de TI, no una copia de otro."},{question:"What is the recommended method for testing different stopping styles?",questionEs:"¿Cuál es el mejor método para probar distintos estilos de parada?",options:["Copy a different teammate's style each single day","Randomly switch your style every hour of the day","Systematically test one style per week and track your results","Stick only with whatever style feels comfortable right away"],optionsEs:["Copia el estilo de un compañero distinto cada día","Cambia de estilo al azar cada hora del día","Prueba un estilo por semana de forma sistemática y anota tus resultados","Quédate solo con el estilo que te resulte cómodo de entrada"],correctIndex:2,explanation:"Systematic testing over weeks with tracked results lets you compare what works. Test high energy, calm energy, direct and indirect approaches, then blend what worked best into your unique hybrid.",explanationEs:"Probar de forma sistemática durante semanas y anotar los resultados te deja comparar qué funciona. Prueba con mucha energía, con calma, de forma directa e indirecta, y luego mezcla lo que mejor te haya funcionado en tu propio híbrido."},{question:"Why is recording yourself valuable for style development?",questionEs:"¿Por qué grabarte es tan útil para desarrollar tu estilo?",options:["To build a fun highlight reel for social media that shows off all your funniest street moments","To prove to your manager that you really are working hard out there on the street throughout every single shift","To see your blind spots — body language, voice, timing, and facial expressions you don't notice in the moment","To send the finished clips over to customers afterward so they always remember your friendly face"],optionsEs:["Para montar un vídeo chulo para redes luciendo todos tus momentos más graciosos en la calle","Para demostrarle al jefe que de verdad estás currando de firme ahí fuera en la calle en todos tus turnos","Para ver tus puntos ciegos: lenguaje corporal, voz, ritmo y gestos de la cara que no notas en el momento","Para mandarles luego los vídeos ya montados a los clientes y que recuerden siempre tu cara amable"],correctIndex:2,explanation:"Recording reveals blind spots you can't see yourself — posture, facial expressions, voice tone, pacing, and awkward transitions. Watching footage is the fastest way to spot improvement opportunities.",explanationEs:"Grabarte revela puntos ciegos que tú solo no ves: la postura, los gestos de la cara, el tono de voz, el ritmo y las transiciones raras. Ver los vídeos es la forma más rápida de detectar dónde mejorar."}]},s={"connect-1":{id:"connect-1",categoryId:"connecting",title:"The 15-Second Scan",titleEs:"El Escaneo de 15 Segundos",subtitle:"Read them before you open your mouth",subtitleEs:"Léelos antes de abrir la boca",duration:"8 min",icon:"Eye",order:1,xpReward:100,sections:[{type:"header",text:"See Everything Before You Say Anything",textEs:"Ve Todo Antes de Decir Nada"},{type:"paragraph",text:"The 15 seconds before you speak are worth more than the 15 minutes after. In that window, you gather the intelligence that shapes your entire approach. What you observe determines what you say, how you say it, and whether you'll close. Master salespeople don't just look at customers — they READ them.",textEs:"Los 15 segundos antes de hablar valen más que los 15 minutos después. En esa ventana, recopilas la información que define todo tu enfoque. Lo que observas determina qué dices, cómo lo dices y si cerrarás la venta. Los vendedores expertos no solo miran a los clientes — los LEEN."},{type:"keypoint",text:"Every detail is telling you something. The watch on their wrist, the bags in their hands, the person beside them, the speed they are walking. You are not building a file on anybody — you are working out which sentence to open with, and you have got about a second to do it.",textEs:"Cada detalle te está diciendo algo. El reloj en la muñeca, las bolsas en las manos, la persona que va al lado, la velocidad a la que andan. No estás haciendo una ficha de nadie — estás decidiendo con qué frase abrir, y tienes como un segundo para hacerlo."},{type:"divider"},{type:"subheader",text:"What to Look At, in the Order Your Eyes Move",textEs:"Qué Mirar, en el Orden en que se te Van los Ojos"},{type:"paragraph",text:"Five looks, a second each, before you say a word. SCAN is just how you remember them:",textEs:"Cinco miradas, un segundo cada una, antes de decir nada. SCAN es solo la forma de acordarte:"},{type:"bullets",items:["S — STYLE: Shoes and coat tell you more than the face does. Good shoes, good coat, that is the money. Hiking boots and a rucksack is a different conversation, not a worse one — just a faster, funnier one.","C — CARRY: Bags in their hands means they are already spending today and somebody already got a yes out of them this morning. That is the easiest customer alive. No bags at all means the day has not started yet — perfect timing.","A — ACCESSORIES: Watch, rings, sunglasses, handbag. People spend on what they care about. Somebody wearing a serious watch cares how they look, and that is the whole pitch handed to you.","N — NETWORK: Who is with them tells you who you actually have to win. On their own, they decide fast. In a couple, the other one can kill it with one word — get them in early. In a group of six, they sell each other and you barely have to talk.","P — PACE & POSTURE: How fast they are walking tells you how good your first line has to be. Strolling and looking around, almost anything works. Marching with somewhere to be, you get one sentence and it had better be a good one."],itemsEs:["S — STYLE (ESTILO): Los zapatos y el abrigo te dicen más que la cara. Buenos zapatos, buen abrigo: ahí está el dinero. Botas de montaña y mochila es otra conversación, no peor — solo más rápida y más divertida.","C — CARRY (BOLSAS): Bolsas en la mano quiere decir que ya están gastando hoy y que alguien ya les ha sacado un sí esta mañana. Ese es el cliente más fácil que hay. Sin ninguna bolsa quiere decir que el día no ha empezado — momento perfecto.","A — ACCESSORIES (COMPLEMENTOS): Reloj, anillos, gafas de sol, bolso. La gente se gasta el dinero en lo que le importa. Quien lleva un reloj serio se preocupa por cómo se ve, y ahí tienes el argumento regalado.","N — NETWORK (CON QUIÉN VAN): Con quién van te dice a quién tienes que ganarte de verdad. Solos, deciden rápido. En pareja, el otro te lo tira abajo con una palabra — métele dentro desde el principio. En un grupo de seis, se venden entre ellos y tú casi no hablas.","P — PACE & POSTURE (RITMO Y POSTURA): Lo rápido que andan te dice lo buena que tiene que ser tu primera frase. Si van paseando y mirando, te vale casi cualquier cosa. Si van a paso ligero y con un sitio al que llegar, tienes una frase y más te vale que sea buena."]},{type:"tip",text:"Practise on strangers when you are not even working. Ten minutes outside a café, call it on everybody who walks past — money, mood, who they are with, how fast. Say it out loud in your head before they reach you. You will be wrong a lot at first. Then one day you are not.",textEs:"Practica con desconocidos aunque no estés trabajando. Diez minutos en la terraza de un café y ve cantándolo con cada persona que pasa — dinero, humor, con quién va, a qué velocidad. Dítelo por dentro antes de que lleguen a tu altura. Al principio fallarás mucho. Y un día dejas de fallar."},{type:"divider"},{type:"subheader",text:"What the Scan Is For — and What It Is Not For",textEs:"Para Qué Sirve el Escaneo — y Para Qué No"},{type:"comparison",left:{label:"WHAT IT BUYS YOU",text:"Your first sentence, and nothing else. Bags in her hands, you open on what she has already been buying. A serious watch, you open on quality and never on a bargain. Marching with somewhere to be, your line has to land in four words instead of twelve. The scan tells you HOW, never WHO."},leftEs:{label:"PARA QUÉ SIRVE",text:"Para tu primera frase, y para nada más. Bolsas en la mano, abres por lo que ya ha estado comprando. Un reloj serio, abres por calidad y nunca por ganga. A paso ligero y con prisa, tu frase tiene que caber en cuatro palabras en vez de doce. El escaneo te dice CÓMO, nunca A QUIÉN."},right:{label:"WHAT IT DOES NOT BUY YOU",text:"Permission to skip anybody. There is no such thing as a person who is not worth your fifteen seconds, and least of all while you are learning — you stop everybody, for the practice, and knowing who not to stop is something the years give you, not a list you get handed in week one."},rightEs:{label:"PARA QUÉ NO SIRVE",text:"Para saltarte a nadie. No existe la persona que no merezca tus quince segundos, y menos aún mientras estás aprendiendo — paras a todo el mundo, para practicar, y saber a quién no parar te lo dan los años, no una lista que te entregan la primera semana."}},{type:"keypoint",text:"And when the scan gives you nothing — no bags, no watch, nothing you can hang a line on — you go anyway, with a plain warm opener. Half the people who end up sitting in your chair looked like absolutely nothing from four metres away. You never find that out by watching them walk past.",textEs:"Y cuando el escaneo no te da nada — ni bolsas, ni reloj, nada de donde tirar — vas igual, con una apertura sencilla y cálida. La mitad de la gente que acaba sentada en tu silla no parecía nada desde cuatro metros. Eso no lo averiguas nunca mirando cómo pasan de largo."},{type:"divider"},{type:"subheader",text:"What Their Grooming Hands You",textEs:"Lo Que su Arreglo te Regala"},{type:"paragraph",text:"People spend money on the part of themselves they care about, and they wear the answer where you can see it. This is not a scoring system and it is not a shortlist — it is a shortcut to the right opening line:",textEs:"La gente se gasta el dinero en la parte de sí misma que le importa, y lleva la respuesta puesta donde tú la ves. Esto no es una puntuación ni una lista de elegidos — es un atajo hacia la frase correcta con la que abrir:"},{type:"bullets",items:["NAILS SHE LOOKS AFTER: natural or painted, she has already decided her hands matter. 'You always keep them natural? Come here, I want to show you something.'","HAIR THAT HAS BEEN DONE: cut, coloured, blow-dried. Somebody who sits still for two hours in a salon will sit still for two minutes in your chair — say so, cheekily.","SKIN WITH A ROUTINE BEHIND IT: compliment it first, honestly, then go at the one thing nobody does. Somebody who already has a routine is somebody with a gap in it.","MAKEUP DONE WELL: she does this every morning and the eyes are where the time goes. Open there — it is the exact spot you are about to work on.","AND NONE OF IT RUNS BACKWARDS: bitten nails and a scraped-back ponytail tell you which line to open with, never to save your breath. Half of them are wearing a long flight, not a lack of interest, and you have no way of telling which from four metres."],itemsEs:['UÑAS QUE SE CUIDA: naturales o pintadas, ya ha decidido que sus manos importan. "¿Siempre las llevas naturales? Ven, que te quiero enseñar una cosa."',"PELO ARREGLADO: cortado, teñido, con brushing. Quien se está quieta dos horas en la peluquería se está quieta dos minutos en tu silla — díselo, con guasa.","PIEL CON UNA RUTINA DETRÁS: primero el cumplido, de verdad, y luego vas a por lo único que no hace nadie. Quien ya tiene una rutina es quien tiene un hueco en ella.","MAQUILLAJE BIEN PUESTO: esto lo hace cada mañana y donde se le va el tiempo es en los ojos. Abre por ahí — es justo la zona en la que vas a trabajar.","Y NADA DE ESTO FUNCIONA AL REVÉS: las uñas mordidas y la coleta tirante te dicen con qué frase abrir, nunca que te ahorres el aliento. La mitad llevan puesto un vuelo largo, no falta de interés, y desde cuatro metros no hay forma de saber cuál es cuál."]},{type:"divider"},{type:"subheader",text:"Mistakes to Avoid",textEs:"Errores a Evitar"},{type:"bullets",items:["DON'T JUDGE BY ETHNICITY: Never assume spending power based on someone's nationality or ethnicity. You will miss incredible sales and look foolish.","DON'T PRE-JUDGE AGE: Young people often have more disposable income than older people (fewer dependents, different priorities). Don't skip someone because they look young.","DON'T IGNORE MIXED SIGNALS: A person in hiking boots with a Rolex is a complex profile — high spending power but practical mindset. Adapt accordingly.","DON'T STARE: Your scan should be quick and subtle. Lingering eye contact before approaching feels creepy, not observant."],itemsEs:["NO JUZGUES POR ETNIA: Nunca asumas el poder adquisitivo basándote en la nacionalidad o etnia de alguien. Perderás ventas increíbles y te verás ridículo.","NO PRE-JUZGUES POR EDAD: Los jóvenes a menudo tienen más ingresos disponibles que los adultos mayores (menos dependientes, prioridades diferentes). No ignores a alguien porque se vea joven.","NO IGNORES LAS SEÑALES MIXTAS: Una persona con botas de excursionismo y un Rolex es un perfil complejo — alto poder adquisitivo pero mentalidad práctica. Adáptate en consecuencia.","NO TE QUEDES MIRANDO: Tu escaneo debe ser rápido y sutil. El contacto visual prolongado antes de acercarte se siente inquietante, no observador."]},{type:"script",text:"'I love your bag — is that from [brand]?' A specific, genuine compliment based on your observation instantly builds rapport. It shows you've actually SEEN them, not just targeted them randomly.",textEs:"'Me encanta tu bolso — ¿es de [marca]?' Un cumplido específico y genuino basado en tu observación construye rapport al instante. Demuestra que realmente los HAS VISTO, no que solo los elegiste al azar."},{type:"quote",text:"The best salespeople don't have better pitches. They have better eyes. They see what others miss.",textEs:"Los mejores vendedores no tienen mejores pitches. Tienen mejores ojos. Ven lo que otros pasan por alto.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"connect-2":{id:"connect-2",categoryId:"connecting",title:"Reading Spending Power",titleEs:"Leyendo el Poder Adquisitivo",subtitle:"Detailed signals: brand logos, watch quality, bag condition, and more",subtitleEs:"Señales detalladas: logos de marca, calidad del reloj, condición del bolso, y más",duration:"10 min",icon:"Gem",order:2,xpReward:150,sections:[{type:"header",text:"Know Who Can Spend Before They Open Their Wallet",textEs:"Sabe Quién Puede Gastar Antes de Que Abra su Cartera"},{type:"paragraph",text:"Reading spending power isn't about snobbery — it's about precision. And it does not tell you who to write off. Everybody hears the top of the ladder, because that is the method. What it tells you is where the fight is going to happen: with a careful spender you are not going to be arguing about {currency}300, you are going to be fighting for {currency}140, sometimes {currency}100 — and you fight just as hard for that one. Reading it the other way round costs you just as much: pitch the {currency}30 scrub at somebody in a real Cartier and you have left the whole syringe on the table.",textEs:"Leer el poder adquisitivo no va de esnobismo — va de precisión. Y no te dice a quién descartar. Todo el mundo oye la parte de arriba de la escalera, porque ese es el método. Lo que te dice es dónde va a estar la pelea: con alguien que mira el dinero no vas a discutir por {currency}300, vas a pelear por {currency}140, a veces por {currency}100 — y peleas igual de fuerte por esa. Leerlo al revés te cuesta lo mismo: le ofreces el exfoliante de {currency}30 a alguien con un Cartier de verdad y has dejado la jeringa entera encima de la mesa."},{type:"keypoint",text:"Spending power signals are everywhere — but they're subtle. A fake designer bag looks similar to a real one to the untrained eye. Learn the difference.",textEs:"Las señales de poder adquisitivo están en todas partes — pero son sutiles. Una bolsa de diseñador falsa se ve similar a una real para el ojo inexperto. Aprende la diferencia."},{type:"divider"},{type:"subheader",text:"The Hierarchy of Signals (Most to Least Reliable)",textEs:"La Jerarquía de Señales (De Más a Menos Confiables)"},{type:"numbered",items:["WATCH QUALITY: This is the #1 indicator. A genuine Rolex, Cartier, Omega, or Patek Philippe signals serious wealth. But also look for quality mid-range watches (Longines, TAG Heuer, Tissot) which signal comfortable middle-to-upper income. No watch, or a basic digital watch, signals budget consciousness or practical mindset.","SHOE QUALITY: Shoes reveal spending habits more honestly than almost anything else. Well-maintained leather shoes or designer sneakers (clean, current season) signal investment in quality. Scuffed, worn, or budget shoes suggest either limited budget or different priorities.","HANDBAG AUTHENTICITY: Learn to spot quality leather, hardware weight, stitching precision, and logo placement. Real luxury bags have perfect stitching, heavy zippers, and consistent logo patterns. But remember: some wealthy people carry simple bags. Use this signal in combination with others.","NAIL AND TEETH QUALITY: Professional manicures and dental work (straight, white teeth) require ongoing investment. These are lifestyle signals — the person regularly invests in self-maintenance.","CLOTHING FABRIC AND FIT: Natural fibers (wool, silk, cashmere, quality cotton) drape differently than synthetics. Well-fitted clothing suggests either expensive purchases or tailoring — both indicate quality consciousness.","CURRENT SHOPPING BAGS: Bags from luxury or high-end stores in the area are immediate, context-specific spending signals. Someone already carrying Chanel and ski boutique bags is primed to buy more."],itemsEs:["CALIDAD DEL RELOJ: Este es el indicador #1. Un Rolex, Cartier, Omega o Patek Philippe genuinos indican gran riqueza. Pero también busca relojes de gama media de calidad (Longines, TAG Heuer, Tissot) que indican ingresos medio-altos cómodos. No llevar reloj, o llevar uno digital básico, indica consciencia de presupuesto o mentalidad práctica.","CALIDAD DEL CALZADO: Los zapatos revelan los hábitos de gasto más honestamente que casi cualquier otra cosa. Zapatos de cuero bien mantenidos o tenis de diseñador (limpios, temporada actual) indican inversión en calidad. Zapatos raspados, gastados o económicos sugieren presupuesto limitado o prioridades diferentes.","AUTENTICIDAD DEL BOLSO: Aprende a identificar la calidad del cuero, el peso de las herrajes, la precisión de la costura y la colocación del logo. Las bolsas de lujo reales tienen costura perfecta, cierres pesados y patrones de logo consistentes. Pero recuerda: algunas personas adineradas cargan bolsas sencillas. Usa esta señal en combinación con otras.","CALIDAD DE UÑAS Y DIENTES: Las manicuras profesionales y el trabajo dental (dientes rectos, blancos) requieren inversión continua. Estas son señales de estilo de vida — la persona invierte regularmente en su mantenimiento personal.","TELA Y CORTE DE LA ROPA: Las fibras naturales (lana, seda, cachemira, algodón de calidad) caen diferente que las sintéticas. La ropa bien ajustada sugiere compras caras o hecha a medida — ambas indican consciencia de calidad.","BOLSAS DE COMPRAS ACTUALES: Bolsas de tiendas de lujo o gama alta en la zona son señales de gasto inmediatas y específicas al contexto. Alguien que ya carga bolsas de Chanel y boutiques de esquí está listo para comprar más."]},{type:"divider"},{type:"subheader",text:"Tourist Origin: Typical Spending Patterns",textEs:"Origen del Turista: Patrones de Gasto Típicos"},{type:"paragraph",text:"These are generalizations based on aggregate patterns. ALWAYS read the individual, not just their nationality. But knowing typical patterns helps you calibrate:",textEs:"Estas son generalizaciones basadas en patrones agregados. SIEMPRE lee al individuo, no solo su nacionalidad. Pero conocer los patrones típicos te ayuda a calibrar:"},{type:"bullets",items:["SPANISH TOURISTS: Often day-trippers or weekend visitors. Shopping-focused, price-conscious but will spend for genuine value. Love the price-gap angle. Respond well to energy and warmth.","FRENCH TOURISTS: Sophisticated about skincare (French beauty culture). Appreciate product knowledge and quality. Less impressed by hype, more by substance. May seem reserved initially — don't mistake this for disinterest.","BRITISH TOURISTS: Direct communicators. Appreciate humor and straightforwardness. Often generous spenders once convinced. May need more product education (less familiar with some skincare categories).","EASTERN EUROPEAN TOURISTS: Often big spenders in luxury categories. Strong responders to premium positioning. Appreciate exclusivity and status signaling. Direct and decisive when interested.","ASIAN TOURISTS: Often highly educated about skincare ingredients and technology. Respect demonstrations and visible results. May be methodical in decision-making. Group dynamics matter — friends influence heavily.","SOUTH AMERICAN TOURISTS: Warm, social, relationship-oriented. Respond to emotional connection and personal attention. Often generous gift-buyers. Family-oriented purchasing (buying for multiple people)."],itemsEs:["TURISTAS ESPAÑOLES: A menudo excursionistas de un día o visitantes de fin de semana. Enfocados en compras, conscientes del precio pero gastarán por valor genuino. Aman el ángulo de la diferencia de precio. Responden bien a la energía y calidez.","TURISTAS FRANCESES: Sofisticados en cuidado de la piel (cultura de belleza francesa). Aprecian el conocimiento de productos y la calidad. Menos impresionados por el hype, más por la sustancia. Pueden parecer reservados al principio — no confundas esto con desinterés.","TURISTAS BRITÁNICOS: Comunicadores directos. Aprecian el humor y la franqueza. A menudo gastan generosamente una vez convencidos. Pueden necesitar más educación sobre productos (menos familiarizados con algunas categorías de cuidado de la piel).","TURISTAS DEL ESTE DE EUROPA: A menudo grandes gastadores en categorías de lujo. Responden fuertemente al posicionamiento premium. Aprecian la exclusividad y las señales de estatus. Directos y decisivos cuando están interesados.","TURISTAS ASIÁTICOS: A menudo muy educados sobre ingredientes y tecnología de cuidado de la piel. Respetan las demostraciones y resultados visibles. Pueden ser metódicos al tomar decisiones. La dinámica de grupo importa — los amigos influyen fuertemente.","TURISTAS SUDAMERICANOS: Cálidos, sociales, orientados a las relaciones. Responden a la conexión emocional y la atención personal. A menudo compradores de regalos generosos. Compras orientadas a la familia (comprando para varias personas)."]},{type:"tip",text:"The price gap is your universal equalizer — but do not expect it to close a careful spender on its own. {currency}500 into {currency}300 opens the conversation for everybody; it does not finish it for the one who is watching her money. She is going to keep talking to you until you are down at {currency}140, and that is fine, because that is where she buys. Lead with the Europe price, deliver the {locationName} price as a gift rather than a discount, and keep the rest of the ladder for the fight that is actually coming.",textEs:"La diferencia de precio es tu igualador universal — pero no esperes que cierre sola a quien mira el dinero. De {currency}500 a {currency}300 abre la conversación con cualquiera; no la termina con la que va contando. Esa va a seguir hablando contigo hasta que estés en {currency}140, y no pasa nada, porque ahí es donde compra. Empieza por el precio de Europa, dale el precio de {locationName} como un regalo y no como un descuento, y guárdate el resto de la escalera para la pelea que viene de verdad."},{type:"divider"},{type:"subheader",text:"The 'Already Buying' Signal",textEs:"La Señal de 'Ya Está Comprando'"},{type:"paragraph",text:"This is one of the most powerful spending indicators: someone who is ALREADY in buying mode. When a tourist is carrying multiple shopping bags, they have:",textEs:"Este es uno de los indicadores de gasto más poderosos: alguien que YA está en modo de compra. Cuando un turista carga múltiples bolsas de compras, tiene:"},{type:"bullets",items:["Mental buying momentum: The decision to spend has already been made. Their wallet is open, their inhibitions are lowered.","Budget flexibility: Someone who has already spent {currency}500 today is more likely to spend {currency}100 more than someone who hasn't spent anything.","Trust in the location: They're already committed to shopping in {locationName}. Your shop is just another stop on their buying journey.","Time investment: They've dedicated time to shopping. Stopping for a 5-minute demo fits their current activity."],itemsEs:["Momento de compra mental: La decisión de gastar ya se tomó. Su cartera está abierta, sus inhibiciones están bajas.","Flexibilidad de presupuesto: Alguien que ya gastó {currency}500 hoy es más propenso a gastar {currency}100 más que alguien que no ha gastado nada.","Confianza en el lugar: Ya están comprometidos con comprar en {locationName}. Tu tienda es solo otra parada en su viaje de compras.","Inversión de tiempo: Han dedicado tiempo a las compras. Detenerse para una demo de 5 minutos encaja con su actividad actual."]},{type:"script",text:"'I see you've been shopping! You clearly know how to find the best spots in {locationName}. Let me show you something that most tourists don't know about — it's my favorite hidden gem here.' This connects their existing buying behavior to your offer.",textEs:"'¡Veo que has estado comprando! Claramente sabes encontrar los mejores lugares en {locationName}. Déjame mostrarte algo que la mayoría de turistas no conocen — es mi joya escondida favorita aquí.' Esto conecta su comportamiento de compra existente con tu oferta."},{type:"divider"},{type:"subheader",text:"When Signals Contradict",textEs:"Cuando las Señales se Contradicen"},{type:"paragraph",text:"Sometimes spending signals conflict. A person in budget clothing wearing an expensive watch. Someone with designer shoes but no shopping bags. These contradictions require deeper reading:",textEs:"A veces las señales de gasto entran en conflicto. Una persona con ropa económica usando un reloj caro. Alguien con zapatos de diseñador pero sin bolsas de compras. Estas contradicciones requieren lectura más profunda:"},{type:"bullets",items:["EXPENSIVE WATCH + BUDGET CLOTHES: Often a successful person who doesn't care about fashion but values one signature piece. Pitch based on product RESULTS, not luxury status.","DESIGNER EVERYTHING BUT NO SHOPPING BAGS: Could be window-shopping without buying, OR just starting their day. Time your approach carefully.","BUDGET SIGNALS BUT CONFIDENT DEMEANOR: Sometimes the wealthiest people dress simply. If their energy is confident and open, pitch normally. Let the demo do the work.","ALL SIGNALS POINT TO WEALTH BUT THEY'RE HESITANT: Wealthy people can also be cautious or comparison shoppers. Don't pressure. Build trust through expertise."],itemsEs:["RELOJ CARO + ROPA ECONÓMICA: A menudo una persona exitosa a quien no le importa la moda pero valora una pieza insignia. Haz tu pitch basado en RESULTADOS del producto, no en estatus de lujo.","TODO DE DISEÑADOR PERO SIN BOLSAS DE COMPRAS: Podrían estar viendo escaparates sin comprar, O apenas empezando su día. Temporiza tu acercamiento cuidadosamente.","SEÑALES ECONÓMICAS PERO PORTE CONFIADO: A veces las personas más adineradas visten sencillo. Si su energía es confiada y abierta, haz tu pitch normalmente. Deja que la demo haga el trabajo.","TODAS LAS SEÑALES INDICAN RIQUEZA PERO ESTÁN DUDOSOS: Las personas adineradas también pueden ser cautelosas o comparar opciones. No presiones. Construye confianza a través de tu experiencia."]},{type:"tip",text:"When in doubt, lead with the syringe (flagship). A recoil at {currency}300 is not a reason to change product — the syringe has four more rungs underneath it before you ever reach for the peeling or the scrub, and the bottom of it is {currency}100. Work those first. It's harder to lift someone who started at {currency}30 than to walk down someone who started at {currency}300.",textEs:"Cuando dudes, empieza por la jeringa (el producto estrella). Que se echen atrás con {currency}300 no es motivo para cambiar de producto — la jeringa tiene cuatro escalones más por debajo antes de que toques el peeling o el exfoliante, y el último es {currency}100. Trabájalos primero. Es más difícil subir a quien empezó en {currency}30 que bajar a quien empezó en {currency}300."},{type:"quote",text:"Reading spending power isn't about judging worth. It's about matching the right offer to the right person at the right time. Everyone deserves your best service — but not everyone needs your most expensive product.",textEs:"Leer el poder adquisitivo no se trata de juzgar el valor. Se trata de emparejar la oferta correcta con la persona correcta en el momento correcto. Todos merecen tu mejor servicio — pero no todos necesitan tu producto más caro.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What is generally considered the #1 indicator of spending power?",options:["Handbag brand","Shoe quality","Watch quality","Clothing brand logos"],correctIndex:2,explanation:"Watch quality is typically the most reliable indicator of spending power because watches are worn for function AND status, and luxury watches are expensive enough to separate serious wealth from average income."},{question:"Why is the 'already buying' signal so powerful?",options:["It means they're rich","They're in buying mode with mental momentum, budget flexibility, and trust in the location","They have no budget limit","They'll buy anything"],correctIndex:1,explanation:"Someone already carrying shopping bags has buying momentum, budget flexibility, trust in the location, and has dedicated time to shopping. Their wallet is already metaphorically open."},{question:"What should you do when spending signals contradict each other?",options:["Always trust the most expensive signal","Always assume they have no money","Read deeper — contradictions often reveal personality type and priorities","Ignore the signals and pitch the cheapest product"],correctIndex:2,explanation:"Contradictory signals require deeper reading. An expensive watch with budget clothing might mean someone who values specific quality over fashion. Read their energy and demeanor alongside material signals."}]},"connect-3":{id:"connect-3",categoryId:"connecting",title:"Cultural Intelligence",titleEs:"Inteligencia Cultural",subtitle:"Selling to Spanish, French, British, and Eastern European tourists — key differences and phrases",subtitleEs:"Vendiendo a turistas españoles, franceses, británicos y del este de Europa",duration:"10 min",icon:"Globe",order:3,xpReward:150,sections:[{type:"header",text:"Every Culture Buys Differently. Know the Difference.",textEs:"Cada Cultura Compra Diferente. Conoce la Diferencia."},{type:"paragraph",text:"{locationName} is a crossroads — Spanish, French, British, Eastern European, and Asian tourists all converge on the same street. Selling the same product to a Frenchwoman from Paris requires a different approach than selling to a British family or a solo Spanish shopper. Cultural intelligence isn't stereotyping — it's understanding how cultural background shapes communication style, decision-making, and buying psychology.",textEs:"{locationName} es una encrucijada — turistas españoles, franceses, británicos, del este de Europa y asiáticos convergen en la misma calle. Vender el mismo producto a una francesa de París requiere un enfoque diferente que vender a una familia británica o a un comprador español solitario. La inteligencia cultural no es estereotipar — es entender cómo el trasfondo cultural moldea el estilo de comunicación, la toma de decisiones y la psicología de compra."},{type:"keypoint",text:"A technique that closes a Spanish customer might repel a French one. Humor that charms a British tourist might confuse an Eastern European. Adapt your approach to the person in front of you.",textEs:"Una técnica que cierra con un cliente español podría repeler a uno francés. El humor que encanta a un turista británico podría confundir a un europeo del este. Adapta tu enfoque a la persona frente a ti."},{type:"divider"},{type:"subheader",text:"Spanish Tourists: Warmth, Energy, and Value",textEs:"Turistas Españoles: Calidez, Energía y Valor"},{type:"paragraph",text:"Spanish tourists often arrive in groups — families, couples, friends. They're typically shopping-oriented, respond well to high energy, and appreciate genuine warmth. The price gap between Europe and {locationName} resonates strongly with them.",textEs:"Los turistas españoles a menudo llegan en grupos — familias, parejas, amigos. Típicamente están orientados a las compras, responden bien a la energía alta y aprecian la calidez genuina. La diferencia de precio entre Europa y {locationName} les resuena con fuerza."},{type:"bullets",items:["COMMUNICATION STYLE: Warm, expressive, relationship-oriented. They appreciate personal connection before business. Ask about their trip, their day, their plans.","DECISION-MAKING: Often consensus-based (especially in groups). The group dynamic matters — get everyone involved.","PRICE SENSITIVITY: Value-conscious but will spend for quality. The price-gap narrative works brilliantly — frame it as 'smart shopping.'","KEY PHRASES: 'Hola!' (always greet warmly), 'Ahorras mucho aquí en {locationName}' (You save a lot here in {locationName}), 'Es de muy buena calidad' (It's very good quality), 'Regalo perfecto' (Perfect gift).","APPROACH: High energy, warm smile, personal questions. Show enthusiasm. Spanish customers often mirror your energy — bring it."],itemsEs:["ESTILO DE COMUNICACIÓN: Cálido, expresivo, orientado a las relaciones. Aprecian la conexión personal antes de los negocios. Pregúntales sobre su viaje, su día, sus planes.","TOMA DE DECISIONES: A menudo basada en consenso (especialmente en grupos). La dinámica de grupo importa — involucra a todos.",'SENSIBILIDAD AL PRECIO: Conscientes del valor pero gastarán por calidad. La narrativa de la diferencia de precio funciona brillantemente — preséntalo como "compras inteligentes".','FRASES CLAVE: "¡Hola!" (siempre saluda cálidamente), "Ahorras mucho aquí en {locationName}" (Ahorras mucho aquí en {locationName}), "Es de muy buena calidad" (Es de muy buena calidad), "Regalo perfecto" (Regalo perfecto).',"ENFOQUE: Alta energía, sonrisa cálida, preguntas personales. Muestra entusiasmo. Los clientes españoles a menudo reflejan tu energía — llévala."]},{type:"script",text:"'Hola! ¿Qué tal vuestro día en {locationName}? Me encanta tu bolso — claramente sabes encontrar las mejores tiendas. Déjame enseñarte algo que la mayoría de turistas no conocen. Es mi producto favorito aquí.' (Hello! How's your day in {locationName}? I love your bag — you clearly know how to find the best shops. Let me show you something most tourists don't know about. It's my favorite product here.)",textEs:"'¡Hola! ¿Qué tal vuestro día en {locationName}? Me encanta tu bolso — claramente sabes encontrar las mejores tiendas. Déjame enseñarte algo que la mayoría de turistas no conocen. Es mi producto favorito aquí.' (¡Hola! ¿Cómo va su día en {locationName}? Me encanta tu bolso — claramente sabes encontrar las mejores tiendas. Déjame mostrarte algo que la mayoría de turistas no conocen. Es mi producto favorito aquí.)"},{type:"divider"},{type:"subheader",text:"French Tourists: Sophistication, Knowledge, and Subtlety",textEs:"Turistas Franceses: Sofisticación, Conocimiento y Sutileza"},{type:"paragraph",text:"French culture has deep skincare knowledge. French customers often know about ingredients, brands, and beauty science. They appreciate quality demonstrations but can be skeptical of hype. Subtlety works better than high-pressure energy.",textEs:"La cultura francesa tiene un conocimiento profundo de cuidado de la piel. Los clientes franceses a menudo saben sobre ingredientes, marcas y ciencia de la belleza. Aprecian las demostraciones de calidad pero pueden ser escépticos del hype. La sutileza funciona mejor que la energía de alta presión."},{type:"bullets",items:["COMMUNICATION STYLE: Measured, thoughtful, appreciate expertise. Show product knowledge. Don't oversell — let the product speak.","DECISION-MAKING: Individual or couple-based. They think before deciding. Give them space to consider. Pressure backfires.","PRICE SENSITIVITY: Quality over price. A French customer will pay {currency}300 for something that works vs. {currency}50 for something cheap. Frame it as investment, not discount.","KEY PHRASES: 'Bonjour!' (essential greeting), 'C'est un produit exceptionnel' (It's an exceptional product), 'Résultats immédiats' (Immediate results), 'Sans parabènes, sans chimie' (Without parabens, without chemicals).","APPROACH: Professional, knowledgeable, respectful. Demonstrate the product with confidence. Answer technical questions well. Give them time to decide."],itemsEs:["ESTILO DE COMUNICACIÓN: Medido, reflexivo, aprecian la experiencia. Muestra conocimiento de productos. No vendas en exceso — deja que el producto hable.","TOMA DE DECISIONES: Individual o en pareja. Piensan antes de decidir. Dale espacio para considerar. La presión tiene el efecto contrario.","SENSIBILIDAD AL PRECIO: Calidad sobre precio. Un cliente francés pagará {currency}300 por algo que funciona vs. {currency}50 por algo barato. Preséntalo como inversión, no como descuento.",`FRASES CLAVE: "¡Bonjour!" (saludo esencial), "C'est un produit exceptionnel" (Es un producto excepcional), "Résultats immédiats" (Resultados inmediatos), "Sans parabènes, sans chimie" (Sin parabenos, sin químicos).`,"ENFOQUE: Profesional, conocedor, respetuoso. Demuestra el producto con confianza. Responde bien las preguntas técnicas. Dale tiempo para decidir."]},{type:"script",text:"'Bonjour! Vous connaissez les produits de la Mer Morte? C'est exceptionnel — les minéraux sont les plus concentrés au monde. Regardez ce résultat, c'est immédiat.' (Hello! Do you know Dead Sea products? It's exceptional — the minerals are the most concentrated in the world. Look at this result, it's immediate.)",textEs:"'¡Bonjour! ¿Conoces los productos del Mar Muerto? Es excepcional — los minerales son los más concentrados del mundo. Mira este resultado, es inmediato.' (¡Hola! ¿Conoces los productos del Mar Muerto? Es excepcional — los minerales son los más concentrados del mundo. Mira este resultado, es inmediato.)"},{type:"divider"},{type:"subheader",text:"British Tourists: Directness, Humor, and Straight Talk",textEs:"Turistas Británicos: Directitud, Humor y Sinceridad"},{type:"paragraph",text:"British tourists generally appreciate directness, humor, and no-nonsense communication. They can be skeptical of 'sales talk' and respond well to someone who feels genuine rather than performative. Self-deprecating humor works brilliantly.",textEs:'Los turistas británicos generalmente aprecian la directitud, el humor y la comunicación sin rodeos. Pueden ser escépticos del "discurso de ventas" y responden bien a alguien que se siente genuino en lugar de performático. El humor autocrítico funciona brillantemente.'},{type:"bullets",items:["COMMUNICATION STYLE: Direct, humorous, appreciates authenticity. Don't be too 'salesy.' Be a real person having a real conversation.","DECISION-MAKING: Usually couple-based. The partner's opinion matters heavily. Involve them with humor and direct questions.","PRICE SENSITIVITY: Reasonably price-aware but responsive to genuine value. The price-gap angle works well. They love a 'bargain' but hate feeling 'sold to.'","APPROACH: Friendly, slightly cheeky, direct. 'I know you weren't planning to stop, but I promise this is worth two minutes of your time.' British customers respect honesty and humor."],itemsEs:['ESTILO DE COMUNICACIÓN: Directo, humorístico, aprecia la autenticidad. No seas demasiado "vendedor". Sé una persona real teniendo una conversación real.',"TOMA DE DECISIONES: Generalmente en pareja. La opinión de la pareja importa mucho. Involúcralos con humor y preguntas directas.",'SENSIBILIDAD AL PRECIO: Razonablemente conscientes del precio pero responden al valor genuino. El ángulo de la diferencia de precio funciona bien. Aman una "ganga" pero odian sentirse "vendidos".','ENFOQUE: Amigable, ligeramente atrevido, directo. "Sé que no planeabas detenerte, pero te prometo que esto vale dos minutos de tu tiempo." Los clientes británicos respetan la honestidad y el humor.']},{type:"script",text:"'I know, I know — you're thinking 'not another salesperson.' But I promise you, this is actually worth stopping for. Two minutes, and if you don't love it, you can tell me I'm terrible at my job. Fair deal?' This disarms skepticism with humor and directness.",textEs:`'Ya lo sé, ya lo sé — estás pensando "otro vendedor no, por favor". Pero te prometo que esto sí merece la pena. Dos minutos, y si no te encanta, me dices que soy malísimo en mi trabajo. ¿Trato justo?' Esto desarma el escepticismo con humor y franqueza.`},{type:"divider"},{type:"subheader",text:"Eastern European Tourists: Exclusivity, Status, and Results",textEs:"Turistas del Este de Europa: Exclusividad, Estatus y Resultados"},{type:"paragraph",text:"Eastern European tourists often respond to premium positioning, exclusivity, and visible results. They're typically decisive buyers — when interested, they move fast. They appreciate being treated as VIPs.",textEs:"Los turistas del este de Europa a menudo responden al posicionamiento premium, la exclusividad y los resultados visibles. Típicamente son compradores decisivos — cuando están interesados, actúan rápido. Aprecian ser tratados como VIPs."},{type:"bullets",items:["COMMUNICATION STYLE: Direct, relationship-oriented, appreciate status and exclusivity. Frame the product as premium and exclusive.","DECISION-MAKING: Often individual or with a trusted companion. Once convinced, they decide quickly. Don't slow them down with too many options.","PRICE SENSITIVITY: Less price-sensitive when the value is clear. Premium framing actually INCREASES appeal. They want the BEST.","APPROACH: Confident, premium, results-focused. Show the demo. Let the result speak. Frame it as the #1 product, the flagship, the best-seller."],itemsEs:["ESTILO DE COMUNICACIÓN: Directo, orientado a las relaciones, aprecian el estatus y la exclusividad. Presenta el producto como premium y exclusivo.","TOMA DE DECISIONES: A menudo individual o con un compañero de confianza. Una vez convencidos, deciden rápido. No los ralentices con demasiadas opciones.","SENSIBILIDAD AL PRECIO: Menos sensibles al precio cuando el valor es claro. El marco premium realmente INCREMENTA el atractivo. Quieren el MEJOR.","ENFOQUE: Confiado, premium, enfocado en resultados. Muestra la demo. Deja que el resultado hable. Preséntalo como el producto #1, el estrella, el más vendido."]},{type:"script",text:"'This is our number one product across all of Europe. Everyone who tries it is shocked by the result. Here, look in the mirror — you see the difference? That's after two minutes. Imagine after one month.' Results-driven, premium-framed, confident delivery.",textEs:"'Este es nuestro producto número uno en toda Europa. Todos los que lo prueban se sorprenden con el resultado. Mira, ve al espejo — ¿ves la diferencia? Eso es después de dos minutos. Imagina después de un mes.' Entrega enfocada en resultados, con marco premium, confiada."},{type:"divider"},{type:"subheader",text:"Personal Space and Touch: Cultural Differences",textEs:"Espacio Personal y Contacto: Diferencias Culturales"},{type:"paragraph",text:"Physical proximity and touch are interpreted differently across cultures:",textEs:"La proximidad física y el contacto se interpretan diferente entre culturas:"},{type:"bullets",items:["SOUTHERN EUROPEANS (Spanish, Italian, Portuguese): Generally comfortable with closer proximity and light touch (shoulder, hand). Warm, expressive gestures are welcome.","NORTHERN EUROPEANS (British, German, Scandinavian): Prefer more personal space. Touch should be minimal and only after rapport is established. Respect their bubble.","FRENCH: Moderate personal space. Appreciate elegance and grace in movement. Touch is acceptable during the demo but keep it professional.","EASTERN EUROPEANS: Generally comfortable with warmth and proximity once rapport is established. Build trust first, then be warm."],itemsEs:["EUROPEOS DEL SUR (Españoles, Italianos, Portugueses): Generalmente cómodos con proximidad más cercana y contacto ligero (hombro, mano). Los gestos cálidos y expresivos son bienvenidos.","EUROPEOS DEL NORTE (Británicos, Alemanes, Escandinavos): Prefieren más espacio personal. El contacto debe ser mínimo y solo después de establecer rapport. Respeta su burbuja.","FRANCESES: Espacio personal moderado. Aprecian la elegancia y gracia en el movimiento. El contacto es aceptable durante la demo pero mantenlo profesional.","EUROPEOS DEL ESTE: Generalmente cómodos con calidez y proximidad una vez establecido el rapport. Construye confianza primero, luego sé cálido."]},{type:"tip",text:"When uncertain about someone's cultural background, start with moderate distance and minimal touch. If they lean in, move closer. If they stay back, respect their space. Let THEM close the distance.",textEs:"Cuando no estés seguro del trasfondo cultural de alguien, empieza con distancia moderada y contacto mínimo. Si se acercan, acércate tú también. Si se mantienen atrás, respeta su espacio. Deja que ELLOS cierren la distancia."},{type:"divider"},{type:"subheader",text:"Language Tips: Key Phrases That Open Doors",textEs:"Consejos de Idioma: Frases Clave que Abren Puertas"},{type:"paragraph",text:"Even a few words in someone's native language creates instant connection. It shows respect and effort. Here are essential phrases:",textEs:"Incluso unas pocas palabras en el idioma nativo de alguien crea conexión instantánea. Demuestra respeto y esfuerzo. Aquí están las frases esenciales:"},{type:"bullets",items:["SPANISH: 'Hola' (Hello), '¿Cómo estás?' (How are you?), 'Mira' (Look), 'Increíble' (Incredible), 'Regalo' (Gift), 'Precio especial' (Special price), 'Para ti' (For you), 'Gracias' (Thank you)","FRENCH: 'Bonjour' (Hello), 'Regardez' (Look), 'Incroyable' (Incredible), 'Résultat immédiat' (Immediate result), 'Cadeau' (Gift), 'Prix spécial' (Special price), 'Merci' (Thank you)","ENGLISH: You're likely already fluent, but British-specific phrases help: 'Brilliant,' 'Lovely,' 'Absolutely,' 'Cheers' — mirror their vocabulary.","RUSSIAN (common with Eastern European visitors): 'Zdravstvuyte' (Hello), 'Smotrite' (Look), 'Potryasayushche' (Amazing) — even attempting a greeting creates goodwill."],itemsEs:['ESPAÑOL: "Hola" (Hola), "¿Cómo estás?" (¿Cómo estás?), "Mira" (Mira), "Increíble" (Increíble), "Regalo" (Regalo), "Precio especial" (Precio especial), "Para ti" (Para ti), "Gracias" (Gracias)','FRANCÉS: "Bonjour" (Hola), "Regardez" (Mira), "Incroyable" (Increíble), "Résultat immédiat" (Resultado inmediato), "Cadeau" (Regalo), "Prix spécial" (Precio especial), "Merci" (Gracias)','INGLÉS: Probablemente ya dominas el inglés, pero las frases específicas británicas ayudan: "Brilliant," "Lovely," "Absolutely," "Cheers" — refleja su vocabulario.','RUSO (común entre visitantes del este de Europa): "Zdravstvuyte" (Hola), "Smotrite" (Mira), "Potryasayushche" (Increíble) — incluso intentar un saludo genera buena voluntad.']},{type:"divider"},{type:"subheader",text:"When You Share No Language At All",textEs:"Cuando No Compartís Ni Un Idioma"},{type:"paragraph",text:"This is not the disaster a new seller thinks it is. A demo is a mirror and two hands, and most of what sells is happening on her face rather than in your sentences. For the rest of it you are not short of options:",textEs:"Esto no es el desastre que se imagina un vendedor nuevo. Una demo es un espejo y dos manos, y casi todo lo que vende está pasando en su cara y no en tus frases. Para lo demás no te faltan recursos:"},{type:"bullets",items:["GOOGLE TRANSLATE, out loud and with no embarrassment about it. Type it, turn the phone round, let her type back. Half the time it gets a laugh, and the laugh is worth more than the sentence was.","THE PRODUCT PAGES EXIST ONLINE IN OTHER LANGUAGES. Pull one up and put the phone in her hand. She reads it in her own language while you get on with the eye.","NUMBERS NEED NO TRANSLATION. Show her the figure, then show her the next one as you come down. Nobody in the history of this shop has needed 300 turning into 210 explained to them.","AND THE REST IS TOUCHING, SMILING AND POINTING. The warmth is the language. Do it slower, not louder."],itemsEs:["GOOGLE TRANSLATE, en voz alta y sin ninguna vergüenza. Lo escribes, le giras el móvil, y que te conteste ella escribiendo. La mitad de las veces te llevas una risa, y la risa vale más que la frase.","LAS PÁGINAS DE PRODUCTO ESTÁN ONLINE EN OTROS IDIOMAS. Abre una y ponle el móvil en la mano. Ella lo lee en su idioma mientras tú sigues con el ojo.","LOS NÚMEROS NO NECESITAN TRADUCCIÓN. Le enseñas la cifra, y luego la siguiente según vas bajando. En la historia de esta tienda nadie ha necesitado que le expliquen que 300 pasa a 210.","Y EL RESTO ES TOCAR, SONREÍR Y SEÑALAR. La calidez es el idioma. Hazlo más despacio, no más alto."]},{type:"tip",text:"What you never do is apologise for it, and you never go off hunting for a colleague who speaks her language while she sits there on her own. Get the phone out and carry on. She did not come in for a conversation, she came in because you promised her something on her face.",textEs:"Lo que no haces nunca es pedir perdón por ello, y tampoco te vas a buscar a un compañero que hable su idioma dejándola ahí sentada sola. Saca el móvil y sigue. No ha entrado a charlar, ha entrado porque le has prometido algo en su cara."},{type:"quote",text:"Language is the road map of a culture. It tells you where its people come from and where they are going. Speaking even a few words in someone's language is a sign of respect that opens wallets.",textEs:"El idioma es el mapa de una cultura. Te dice de dónde vienen sus personas y a dónde van. Hablar incluso unas pocas palabras en el idioma de alguien es una señal de respeto que abre carteras.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Which approach works best with French tourists?",options:["High energy and lots of enthusiasm","Professional expertise with product knowledge and space to decide","Self-deprecating humor and cheekiness","Exclusivity and VIP treatment"],correctIndex:1,explanation:"French tourists appreciate expertise, product knowledge, and space to consider. They're often knowledgeable about skincare and respond to substance over hype. Pressure backfires."},{question:"Why does the price-gap narrative work especially well with Spanish tourists?",options:["They don't care about quality, only about the lowest price","They're value-conscious — {currency}500 at {currency}300 feels smart","They only buy cheap products and avoid premium brands","They don't understand luxury pricing"],correctIndex:1,explanation:"Spanish tourists are value-conscious, so hearing {currency}500 in Europe and {currency}300 here makes the buy feel significant. They respond well to value framing — 'smart shopping' in {locationName}."},{question:"What should you do when uncertain about someone's cultural background?",options:["Guess based on appearance","Start with moderate distance and minimal touch, letting them close the gap","Ask directly where they're from","Use the same approach for everyone"],correctIndex:1,explanation:"When uncertain, start with moderate distance and minimal touch. Watch their body language — if they lean in, you can move closer. Let them set the proximity comfort level."}]},"connect-4":{id:"connect-4",categoryId:"connecting",title:"The Partner Dynamic",titleEs:"La Dinámica de Pareja",subtitle:"How to read couples, engage the skeptical partner, and close together",subtitleEs:"Cómo leer parejas, involucrar al escéptico y cerrar juntos",duration:"8 min",icon:"Users",order:4,xpReward:100,sections:[{type:"header",text:"A Couple Is Two Sales or Two Vetoes — Never One of Each",textEs:"Una Pareja Son Dos Ventas o Dos Vetos — Nunca Una de Cada"},{type:"paragraph",text:'A person on their own decides on their own. A couple decides out loud, in front of you, and that changes everything. Bring both of them in and they talk each other INTO it — she wants it, he says "go on, treat yourself", and now the decision has two people behind it instead of one. Leave one of them standing there like furniture and you have created a silent veto: bored, ignored, and one sigh away from "come on, we said we were meeting them at six." The mechanism is that simple, and it is why you never let a partner go quiet.',textEs:'Una persona sola decide sola. Una pareja decide en voz alta, delante de ti, y eso lo cambia todo. Métetelos a los dos y se convencen el uno al otro — ella lo quiere, él dice "venga, date un capricho", y ahora la decisión tiene a dos personas detrás en vez de a una. Deja a uno ahí de pie como un mueble y te has fabricado un veto silencioso: aburrido, ignorado, y a un suspiro de "venga, que habíamos quedado a las seis". El mecanismo es así de simple, y por eso nunca dejas que una pareja se calle.'},{type:"keypoint",text:"The golden rule: never make one partner feel irrelevant. The person standing quietly might be the one who ultimately decides. Bring them in. Make them feel seen. Their involvement is the key to the sale.",textEs:"La regla de oro: nunca hagas que una pareja se sienta irrelevante. La persona que está de pie en silencio podría ser quien decide al final. Tráelos adentro. Haz que se sientan vistos. Su involucramiento es la clave de la venta."},{type:"divider"},{type:"subheader",text:"Reading the Decision-Maker",textEs:"Leyendo al Tomador de Decisiones"},{type:"paragraph",text:"In most couples, one person drives the interaction while the other observes. But the driver isn't always the decision-maker. Watch for these signals:",textEs:"En la mayoría de las parejas, una persona lidera la interacción mientras la otra observa. Pero quien lidera no siempre es quien decide. Observa estas señales:"},{type:"bullets",items:["THE DRIVER: Does most of the talking, asks questions, engages with you directly. They're interested and leading the exploration. Often the one who will USE the product.","THE DECISION-MAKER: May be quieter but their reactions carry more weight. Watch who the driver looks at after your pitch. If they seek eye contact with their partner before responding, the partner is the decision-maker.","THE INFLUENCER: Sometimes there's a third dynamic — one person uses the product, but a third person (friend, adult child) influences the decision. Read the group's attention patterns."],itemsEs:["QUIEN LIDERA: Hace la mayor parte de la conversación, hace preguntas, se involucra contigo directamente. Están interesados y lideran la exploración. A menudo quien USARÁ el producto.","EL TOMADOR DE DECISIONES: Puede ser más callado pero sus reacciones tienen más peso. Observa a quién mira quien lidera después de tu pitch. Si busca contacto visual con su pareja antes de responder, la pareja es quien decide.","EL INFLUENCIADOR: A veces hay una tercera dinámica — una persona usa el producto, pero una tercera persona (amigo, hijo adulto) influye en la decisión. Lee los patrones de atención del grupo."]},{type:"tip",text:"A classic tell: after you present the offer, the interested partner looks at the other and says 'What do you think?' That's the moment of truth. How the partner responds determines the sale. Prepare for that moment.",textEs:'Una señal clásica: después de presentar la oferta, la pareja interesada mira a la otra y dice "¿Qué piensas?" Ese es el momento de la verdad. Cómo responde la pareja determina la venta. Prepárate para ese momento.'},{type:"divider"},{type:"subheader",text:"Engaging the Skeptical Partner",textEs:"Involucrando a la Pareja Escéptica"},{type:"paragraph",text:"The skeptical partner is often a man watching his female partner's interaction. He may seem bored, suspicious, or protective. Your job is to transform him from potential veto into active supporter. Here's how:",textEs:"La pareja escéptica a menudo es un hombre observando la interacción de su pareja femenina. Puede parecer aburrido, sospechoso o protector. Tu trabajo es transformarlo de veto potencial a partidario activo. Así es como:"},{type:"numbered",items:["INCLUDE HIM EARLY: Don't wait until the close. From the moment they're inside, make eye contact with him. Ask his opinion. 'Sir, you see what I mean about the eye area? You know how she sometimes says she looks tired even after sleeping well?' This makes him an expert on HIS partner, not just an observer of your sale.","APPEAL TO HIS LOGIC: A partner who has started doing sums out loud is not a top-of-the-ladder problem — by then you have already walked down, so answer him with the number you are actually standing on. 'One syringe is her whole year — about sixty treatments in there. At {currency}140 that is a bit over {currency}2 a go, and it is still working in June.' Logic defuses skepticism.","MAKE HIM THE HERO: Frame the purchase as something HE can give her. 'Imagine her waking up every morning looking this fresh — and she'll know it's because of you.' Men love being the source of their partner's happiness.","HUMOR DISARMS: A light joke directed at him breaks tension. 'Sir, don't worry — we're not changing her face, just making her eyes look like she slept twelve hours.' Humor makes him smile, and a smiling man doesn't veto."],itemsEs:['INCLÚYELO DESDE EL PRINCIPIO: No esperes hasta el cierre. Desde el momento en que están dentro, haz contacto visual con él. Pregúntale su opinión. "Señor, ¿ve lo que digo sobre el área del ojo? ¿Sabe cómo ella a veces dice que se ve cansada incluso después de dormir bien?" Esto lo convierte en experto sobre SU pareja, no solo en observador de tu venta.','APELA A SU LÓGICA: Una pareja que se pone a echar cuentas en voz alta no es un problema de arriba de la escalera — a esas alturas ya has bajado, así que contéstale con el número en el que estás de verdad. "Una jeringa le dura el año entero — ahí dentro hay unos sesenta tratamientos. A {currency}140 sale a poco más de {currency}2 cada uno, y en junio sigue funcionando." La lógica desactiva el escepticismo.','HÁZLO EL HÉROE: Presenta la compra como algo que ÉL puede darle. "Imagínatela despertando cada mañana viéndose así de fresca — y ella sabrá que es gracias a ti." A los hombres les encanta ser la fuente de la felicidad de su pareja.','EL HUMOR DESARMA: Una broma ligera dirigida a él rompe la tensión. "Señor, no se preocupe — no le cambiamos la cara, solo hacemos que sus ojos se vean como si hubiera dormido doce horas." El humor lo hace sonreír, y un hombre que sonríe no veta.']},{type:"script",text:"'Sir, be honest — do you see the difference? Look at the lift, the smoothness. You're going home with a younger version of your wife!' This makes him an active evaluator (his opinion matters) while framing the result as something he benefits from too.",textEs:"'Señor, sea honesto — ¿ve la diferencia? Mire el lifting, la suavidad. ¡Se va a casa con una versión más joven de su esposa!' Esto lo convierte en evaluador activo (su opinión importa) mientras presenta el resultado como algo de lo que él también se beneficia."},{type:"divider"},{type:"subheader",text:"Body Language Between Couples",textEs:"Lenguaje Corporal entre Parejas"},{type:"paragraph",text:"Couples communicate through body language constantly. Learn to read these signals:",textEs:"Las parejas se comunican a través del lenguaje corporal constantemente. Aprende a leer estas señales:"},{type:"bullets",items:["POSITIVE SIGNALS: Standing close together, making eye contact with each other while you talk, one touching the other lightly while considering, both leaning in during the demo, shared smiles or laughter. These couples are likely to buy.","NEGATIVE SIGNALS: Standing apart, crossed arms (especially the partner), checking phone while you talk, one person walking away to look at other products, eye-rolling, sighing. These are vetos in progress.","MIXED SIGNALS: She's interested but he's checking his watch. She's asking questions but he's stepping back. This requires immediate intervention — engage the skeptical partner NOW before they veto."],itemsEs:["SEÑALES POSITIVAS: Pararse cerca, hacerse contacto visual mientras hablas, uno tocando al otro ligeramente mientras consideran, ambos inclinándose durante la demo, sonrisas o risas compartidas. Estas parejas probablemente comprarán.","SEÑALES NEGATIVAS: Pararse separados, brazos cruzados (especialmente la pareja), revisar el teléfono mientras hablas, una persona alejándose a ver otros productos, poner los ojos en blanco, suspirar. Estos son vetos en progreso.","SEÑALES MIXTAS: Ella está interesada pero él revisa su reloj. Ella hace preguntas pero él se echa para atrás. Esto requiere intervención inmediata — involucra a la pareja escéptica AHORA antes de que vete."]},{type:"divider"},{type:"subheader",text:"Handling Different Couple Types",textEs:"Manejando Diferentes Tipos de Pareja"},{type:"bullets",items:["THE ENTHUSIASTIC COUPLE: Both are interested, both ask questions. Easy mode — deliver your best pitch, give them space to discuss, and close naturally.","THE INTERESTED WOMAN + RELUCTANT MAN: Common scenario. Your mission: convert him. Use logic, humor, and make him feel included. Don't let him feel like a wallet.","THE INTERESTED MAN + OBSERVING WOMAN: Less common but happens. Men buying for their partners can be decisive. Make sure SHE likes it by involving her in the demo directly.","THE FRIEND COUPLE: Two friends traveling together. Friend dynamics are social and fun. Group energy works — involve both, create a shared experience, suggest they both try it."],itemsEs:["LA PAREJA ENTUSIASTA: Ambos están interesados, ambos hacen preguntas. Modo fácil — da tu mejor pitch, dales espacio para discutir, y cierra naturalmente.","LA MUJER INTERESADA + HOMBRE RENUENTE: Escenario común. Tu misión: convértelo. Usa lógica, humor, y haz que se sienta incluido. No dejes que se sienta como una cartera.","EL HOMBRE INTERESADO + MUJER OBSERVADORA: Menos común pero pasa. Los hombres comprando para sus parejas pueden ser decisivos. Asegúrate de que A ELLA le guste involucrándola directamente en la demo.","LA PAREJA DE AMIGOS: Dos amigos viajando juntos. La dinámica de amigos es social y divertida. La energía de grupo funciona — involucra a ambos, crea una experiencia compartida, sugiere que ambos lo prueben."]},{type:"tip",text:"When a couple is deciding, GIVE THEM A BEAT — but give it to them at your table, not out on the pavement. Put the box in her hands, take half a step back, busy yourself with something. 'I'm right here.' Let them have the little conversation they need to have, because one of them nearly always talks the other into it. What you never do is send them off to have it somewhere else.",textEs:'Cuando una pareja está decidiendo, DALES UN SEGUNDO — pero dáselo en tu mesa, no en mitad de la calle. Ponle la caja en las manos, medio paso atrás, y entretente con algo. "Estoy aquí mismo." Que tengan la conversación que necesitan tener, porque casi siempre uno convence al otro. Lo que no haces nunca es mandarlos a tenerla a otra parte.'},{type:"divider"},{type:"subheader",text:"The 'Gift' Angle for Couples",textEs:"El Ángulo de 'Regalo' para Parejas"},{type:"paragraph",text:"Couples are primed for gift purchases. Even when shopping for themselves, they often frame purchases as gifts to each other:",textEs:"Las parejas están preparadas para compras de regalos. Incluso cuando compran para ellos mismos, a menudo presentan las compras como regalos mutuos:"},{type:"script",text:"'This would make an incredible Christmas gift for her — but honestly? Use it together. The Scrub and Body Butter work for men too. Make it a couples' spa night at home.' This transforms a single purchase into a shared experience and removes the 'selfish purchase' barrier.",textEs:"'Esto sería un regalo de Navidad increíble para ella — pero ¿honestamente? Usadlo juntos. El Scrub y la Body Butter también funcionan para hombres. Hagan una noche de spa en casa.' Esto transforma una compra individual en una experiencia compartida y elimina la barrera de la 'compra egoísta'."},{type:"quote",text:"The couple isn't two individual sales. It's one sale with two gatekeepers. Unlock both, and the sale opens.",textEs:"La pareja no son dos ventas individuales. Es una venta con dos guardias. Desbloquea a ambos, y la venta se abre.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"How can you identify who the actual decision-maker is in a couple?",options:["The person who talks the most is always the decision-maker","Watch who the driver looks at after your pitch — if they seek eye contact, that person decides","The man always decides","The person who walks into the shop first decides"],correctIndex:1,explanation:"The person doing most of the talking (the driver) often seeks eye contact with their partner after your pitch. If they look to their partner and ask 'What do you think?' — that partner is the decision-maker."},{question:"What is the best way to engage a skeptical male partner?",options:["Ignore him and focus entirely on the woman","Include him early, appeal to logic, make him feel like his opinion matters","Tell him the price first to see if he can afford it","Make him feel guilty for not buying"],correctIndex:1,explanation:"Engage the skeptical partner early, appeal to his logic with practical benefits, and make him feel like his opinion matters. Transform him from potential veto into active supporter."},{question:"Why is giving a couple space after presenting the offer important?",options:["It shows you don't care about the sale","It lets them have a private conversation where one often convinces the other","It gives you time to approach other customers","Couples never buy immediately"],correctIndex:1,explanation:"After presenting the offer, stepping back lets the couple have a private conversation. Often one partner convinces the other during that 30-second gap. Hovering creates pressure that kills this natural persuasion process."}]},"connect-5":{id:"connect-5",categoryId:"connecting",title:"Building Instant Rapport",titleEs:"Crear Rapport al Instante",subtitle:"10 specific techniques to connect with anyone in 60 seconds",subtitleEs:"10 técnicas específicas para conectar con cualquiera en 60 segundos",duration:"10 min",icon:"MessageCircle",order:5,xpReward:150,sections:[{type:"header",text:"Rapport Is the Bridge Between Stranger and Customer",textEs:"El Rapport Es el Puente Entre Extraño y Cliente"},{type:"paragraph",text:"Rapport is that magical moment when a stranger shifts from 'Who is this person talking to me?' to 'I like this person, I'll hear them out.' It happens fast — within 30 to 60 seconds — and once established, it transforms the entire interaction. Without rapport, you're a salesperson. With rapport, you're a friendly expert they trust.",textEs:"El rapport es ese momento mágico cuando un extraño pasa de '¿Quién es esta persona que me habla?' a 'Me cae bien esta persona, le voy a escuchar.' Sucede rápido — en 30 a 60 segundos — y una vez establecido, transforma toda la interacción. Sin rapport, eres un vendedor. Con rapport, eres un experto amigable en quien confían."},{type:"keypoint",text:"Rapport isn't one technique — it's a combination of signals that tell the customer's brain: 'This person is safe. This person is like me. This person cares.' Stack multiple rapport techniques for maximum effect.",textEs:"El rapport no es una sola técnica — es una combinación de señales que le dicen al cerebro del cliente: 'Esta persona es segura. Esta persona es como yo. A esta persona le importo.' Combina múltiples técnicas de rapport para máximo efecto."},{type:"divider"},{type:"subheader",text:"Technique 1: Mirroring",textEs:"Técnica 1: El Espejo"},{type:"paragraph",text:"Mirroring is subtly matching the customer's body language, speech pace, energy level, and vocabulary. When done naturally (not mimicry), it creates subconscious similarity. The customer's brain registers: 'This person is like me.'",textEs:"El espejo es emparejar sutilmente el lenguaje corporal, ritmo de habla, nivel de energía y vocabulario del cliente. Cuando se hace de forma natural (no imitación burda), crea una similitud subconsciente. El cerebro del cliente registra: 'Esta persona es como yo.'"},{type:"bullets",items:["BODY LANGUAGE: If they stand with hands in pockets, relax your arms. If they lean in during the demo, lean in too. Match their posture generally.","SPEECH PACE: Fast talker? Speed up slightly. Slow, measured speaker? Slow down. Matching pace creates conversational harmony.","ENERGY LEVEL: Enthusiastic customer? Match their enthusiasm. Reserved customer? Warm but calm. Energy mismatch creates discomfort.","VOCABULARY: If they say 'cream,' say 'cream.' If they say 'moisturizer,' say 'moisturizer.' Using their words shows you listen."],itemsEs:["LENGUAJE CORPORAL: Si están de pie con las manos en los bolsillos, relaja tus brazos. Si se inclinan durante la demostración, inclínate tú también. Empareja su postura en general.","RITMO DE HABLA: ¿Habla rápido? Acelera un poco. ¿Habla lento y pausado? Baja el ritmo. Emparejar el ritmo crea armonía en la conversación.","NIVEL DE ENERGÍA: ¿Cliente entusiasta? Empareja su entusiasmo. ¿Cliente reservado? Cálido pero calmado. El desajuste de energía genera incomodidad.","VOCABULARIO: Si dicen 'crema', di 'crema'. Si dicen 'hidratante', di 'hidratante'. Usar sus palabras demuestra que escuchas."]},{type:"tip",text:"Mirroring should feel natural, not obvious. Wait 2-3 seconds after they change posture, then shift yours. If they notice you're copying them, it backfires completely. Subtlety is everything.",textEs:"El espejo debe sentirse natural, no obvio. Espera 2-3 segundos después de que cambien de postura, y luego ajusta la tuya. Si se dan cuenta de que los estás copiando, tiene el efecto contrario. La sutileza lo es todo."},{type:"divider"},{type:"subheader",text:"Technique 2: Name Usage",textEs:"Técnica 2: Usar el Nombre"},{type:"paragraph",text:"A person's name is the sweetest sound in any language. When you learn their name, use it naturally 2-3 times during the interaction. Not excessively — that feels manipulative — but enough to create personal connection.",textEs:"El nombre de una persona es el sonido más dulce en cualquier idioma. Cuando sepas su nombre, úsalo de forma natural 2-3 veces durante la interacción. No en exceso — eso se siente manipulador — pero lo suficiente para crear conexión personal."},{type:"script",text:"'Maria, come look in the mirror — you won't believe what you see.' 'So Maria, which option feels better for you?' 'It was wonderful meeting you, Maria. Enjoy {locationName}!' Three uses: one during the experience, one during the close, one at goodbye. Perfect.",textEs:"'María, ven a ver el espejo — no vas a creer lo que ves.' 'Entonces, María, ¿cuál opción se siente mejor para ti?' 'Fue un placer conocerte, María. ¡Disfruta {locationName}!' Tres usos: uno durante la experiencia, uno durante el cierre, uno en la despedida. Perfecto."},{type:"divider"},{type:"subheader",text:"Technique 3: Genuine Compliments",textEs:"Técnica 3: Cumplidos Genuinos"},{type:"paragraph",text:"A compliment does two jobs at once: it is a nice thing to hear, and it makes them answer you. 'You look so good — what do you normally use on your skin?' cannot be answered with a yes or a no. That is why it stops people when 'excuse me, madam' does not.",textEs:"Un cumplido hace dos cosas a la vez: es agradable de oír y les obliga a contestarte. 'Te veo muy bien, ¿qué usas normalmente para la piel?' no se contesta con un sí o un no. Por eso para a la gente cuando 'perdone, señora' no la para."},{type:"bullets",items:["TELL THEM THEY LOOK GOOD: Straight out. 'Listen, I know you're in a rush — but can I ask you something really quick? It's just that you look so good, I have to ask what you normally use on your skin.' It works because it is warm and it is fast, and because the tail on the end cannot be answered with a nod. It is the best opening line on this street.","OR PICK SOMETHING THEY CHOSE: The scarf, the coat, the bag, the nails. Works just as well and you can see it from three metres. Use whichever one you spot first — do not stand there hunting for the perfect one.","THE ONLY ONES THAT GO WRONG: Anything you would not say with their husband standing next to you — weight, age, anything about their body. That is the whole rule; everything else is fair. Then: eye contact, smile, say it, move. Do not hang about waiting for a thank you."],itemsEs:["DILES QUE ESTÁN GUAPÍSIMAS: A pelo. 'Mira, sé que vas con prisa — ¿pero te puedo preguntar una cosa rapidísima? Es que te veo tan bien que tengo que preguntarte qué usas normalmente para la piel.' Funciona porque es cálido y es rápido, y porque el final no se contesta con un gesto de cabeza. Es la mejor apertura de esta calle.","O ALGO QUE HAYAN ELEGIDO ELLAS: El pañuelo, el abrigo, el bolso, las uñas. Funciona igual de bien y lo ves desde tres metros. Usa lo primero que pilles — no te quedes ahí buscando el detalle perfecto.","LAS ÚNICAS QUE SALEN MAL: Cualquier cosa que no dirías con su marido al lado — el peso, la edad, nada del cuerpo. Esa es toda la norma; el resto vale. Y luego: mirada, sonrisa, lo dices y sigues. No te quedes ahí esperando las gracias."]},{type:"divider"},{type:"subheader",text:"Technique 4: Finding Common Ground",textEs:"Técnica 4: Encontrar Terreno Común"},{type:"paragraph",text:"Shared experiences create instant connection. Travelers in {locationName} have common ground waiting to be discovered:",textEs:"Las experiencias compartidas crean conexión instantánea. Los viajeros en {locationName} tienen terreno común esperando ser descubierto:"},{type:"bullets",items:["THE LOCATION: 'Is this your first time in {locationName}? I love it here — I never get tired of this place.'","THE WEATHER: 'Beautiful day for shopping! Better than yesterday's rain, right?'","SHARED ORIGINS: 'Oh, you're from Madrid? I have family there!' Even distant connections create bonds.","THE EXPERIENCE: 'Everyone who tries this is shocked — you're going to have the same reaction.' Shared anticipation of the demo result."],itemsEs:["EL LUGAR: '¿Es tu primera vez en {locationName}? Me encanta esto — no me canso de este sitio.'","EL CLIMA: '¡Hermoso día para comprar! Mejor que la lluvia de ayer, ¿o no?'","ORÍGENES COMPARTIDOS: 'Oh, ¿eres de Madrid? ¡Tengo familia ahí!' Incluso las conexiones lejanas crean lazos.","LA EXPERIENCIA: 'Todos los que prueban esto se sorprenden — vas a tener la misma reacción.' La anticipación compartida del resultado de la demostración."]},{type:"divider"},{type:"subheader",text:"Technique 5: Humor",textEs:"Técnica 5: Humor"},{type:"paragraph",text:"Humor breaks tension, creates positive emotion, and makes you memorable. The key is LIGHT humor — nothing edgy, political, or potentially offensive. Self-deprecating humor is safest and most disarming.",textEs:"El humor rompe la tensión, crea emoción positiva y te hace memorable. La clave es humor LIGERO — nada atrevido, político o potencialmente ofensivo. El humor autocrítico es el más seguro y el más desarmante."},{type:"script",text:"'I promise this is worth two minutes of your time. If you don't love it, you can tell me I'm terrible at my job.' 'Promise not to scream when you see this result — my last customer actually did, and her husband got jealous.' Humor makes people smile, and smiling people buy.",textEs:"'Te prometo que esto vale dos minutos de tu tiempo. Si no te encanta, puedes decirme que soy terrible en mi trabajo.' 'Promete no gritar cuando veas este resultado — mi última cliente en realidad lo hizo, y su esposo se puso celoso.' El humor hace que la gente sonría, y la gente que sonríe compra."},{type:"divider"},{type:"subheader",text:"Techniques 6-10: Advanced Rapport Builders",textEs:"Técnicas 6-10: Constructores Avanzados de Rapport"},{type:"bullets",items:["6. VULNERABILITY: Brief, genuine honesty creates deep trust. 'When I first started, I didn't believe the hype either. Then I tried it myself and became obsessed.' This shows you're a real person, not a sales robot.","7. CURIOSITY: Ask questions that show genuine interest in THEM, not just their wallet. 'What do you usually use on your skin? You clearly take care of yourself.' People love talking about themselves.","8. AGREEMENT FRAMES: Start with something they can't disagree with. '{locationName} is beautiful, isn't it?' 'You clearly have great taste.' 'Taking care of your skin is important.' Each agreement creates momentum toward the sale.","9. STORYTELLING: Share a 30-second story about another customer. 'A woman came in yesterday saying she'd think about it. She came back an hour later and bought two for her sisters.' Stories bypass skepticism and go straight to imagination.","10. APPROPRIATE TOUCH: A light hand on the forearm during a key moment, or guiding their hand during the demo. Only when rapport is established and culturally appropriate. Touch accelerates trust when done right, destroys it when done wrong."],itemsEs:["6. VULNERABILIDAD: La honestidad breve y genuina crea confianza profunda. 'Cuando empecé, yo tampoco me creía el hype. Luego lo probé yo misma y me obsesioné.' Esto demuestra que eres una persona real, no un robot de ventas.","7. CURIOSIDAD: Haz preguntas que demuestren interés genuino en ELLOS, no solo en su cartera. '¿Qué sueles usar en tu piel? Claramente te cuidas.' A la gente le encanta hablar de sí misma.","8. MARCOS DE ACUERDO: Empieza con algo con lo que no puedan estar en desacuerdo. '{locationName} es hermosa, ¿o no?' 'Claramente tienes excelente gusto.' 'Cuidar tu piel es importante.' Cada acuerdo crea impulso hacia la venta.","9. NARRACIÓN: Comparte una historia de 30 segundos sobre otro cliente. 'Una mujer vino ayer diciendo que lo pensaría. Volvió una hora después y compró dos para sus hermanas.' Las historias evaden el escepticismo y van directo a la imaginación.","10. TOQUE APROPIADO: Una mano ligera en el antebrazo durante un momento clave, o guiando su mano durante la demostración. Solo cuando el rapport está establecido y es culturalmente apropiado. El toque acelera la confianza cuando se hace bien, la destruye cuando se hace mal."]},{type:"tip",text:"Rapport is not a script — it's a state of being. The most powerful rapport tool is genuine LIKING. Actually care about the person in front of you. Be curious about their life. When your interest is real, everything else falls into place.",textEs:"El rapport no es un guion — es un estado de ser. La herramienta de rapport más poderosa es el genuino AGRADO. Que de verdad te importe la persona que tienes delante. Sé curioso sobre su vida. Cuando tu interés es real, todo lo demás cae en su lugar."},{type:"quote",text:"People don't care how much you know until they know how much you care. Rapport is the proof of caring.",textEs:"A la gente no le importa cuánto sabes hasta que sabe cuánto te importa. El rapport es la prueba de que te importa.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What makes a compliment feel genuine rather than fake?",options:["Using more elaborate words","Being specific about something the person chose","Complimenting their physical body","Complimenting them multiple times rapidly"],correctIndex:1,explanation:"Specific compliments about choices people make (accessories, style, grooming) feel observant and real. Generic or physical compliments often feel fake or inappropriate."},{question:"How should mirroring be done to avoid detection?",options:["Copy their movements immediately and exactly","Wait 2-3 seconds after they shift, then adjust your posture subtly","Mirror only their speech, not body language","Tell them you're mirroring to build rapport"],correctIndex:1,explanation:"Mirroring should be delayed by 2-3 seconds and done subtly. Immediate, exact copying feels like mimicry and backfires. Natural, delayed matching creates subconscious similarity."},{question:"Which type of humor is safest and most disarming in sales?",options:["Political humor","Self-deprecating humor","Sarcasm about the customer","Edgy jokes"],correctIndex:1,explanation:"Self-deprecating humor is safest because it shows confidence and vulnerability without risking offense. Political, sarcastic, or edgy humor can alienate customers."}]},"connect-6":{id:"connect-6",categoryId:"connecting",title:"Asking Questions That Reveal Everything",titleEs:"Haciendo Preguntas que lo Revelan Todo",subtitle:"Open vs closed questions, the question ladder, and avoiding interrogation mode",subtitleEs:"La curiosidad gana más que el carisma",duration:"8 min",icon:"MessageCircle",order:6,xpReward:100,sections:[{type:"header",text:"Questions Are Your Intelligence-Gathering Tool",textEs:"Las Preguntas Son Tu Herramienta de Recolección de Inteligencia"},{type:"paragraph",text:"The salesperson who asks the best questions learns the most. And the salesperson who learns the most sells the most. Questions reveal spending power, skin concerns, buying motivation, decision dynamics, and objections — all before you present the offer. Master question-asking and you'll never be surprised by a 'no.'",textEs:"El vendedor que hace las mejores preguntas aprende más. Y el vendedor que más aprende, más vende. Las preguntas revelan poder adquisitivo, preocupaciones de la piel, motivación de compra, dinámicas de decisión y objeciones — todo antes de presentar la oferta. Domina el arte de preguntar y nunca te sorprenderá un 'no'."},{type:"keypoint",text:"Your goal with questions isn't interrogation — it's conversation. Questions should feel natural, flow with the chat, and make the customer feel understood, not interviewed.",textEs:"Tu objetivo con las preguntas no es un interrogatorio — es conversación. Las preguntas deben sentirse naturales, fluir con la charla, y hacer que el cliente se sienta entendido, no entrevistado."},{type:"divider"},{type:"subheader",text:"Open vs. Closed Questions",textEs:"Preguntas Abiertas vs. Cerradas"},{type:"comparison",left:{label:"Closed Questions (Weak)",text:"'Do you use cream?' — Yes/No answer. Ends conversation. Reveals nothing. 'Are you enjoying your holiday?' — 'Yes.' Nowhere to go next. 'Have you been to {locationName} before?' — 'Yes.' Nothing to work with."},leftEs:{label:"Preguntas Cerradas (Débiles)",text:"'¿Usas crema?' — Respuesta sí/no. Termina la conversación. No revela nada. '¿Estás disfrutando las vacaciones?' — 'Sí.' No hay por dónde seguir. '¿Has estado en {locationName} antes?' — 'Sí.' Nada con qué trabajar."},right:{label:"Open Questions (Powerful)",text:"'What do you use on your skin?' — Reveals routine, spending, and concerns. 'What do you think of the result?' — Gets them talking about feelings. 'What brings you to {locationName}?' — Opens connection opportunities."},rightEs:{label:"Preguntas Abiertas (Potentes)",text:"'¿Qué usas para la piel?' — Revela rutina, gasto y preocupaciones. '¿Qué te parece el resultado?' — Les hace hablar de lo que sienten. '¿Qué te trae por {locationName}?' — Abre oportunidades de conexión."}},{type:"tip",text:"Start with open questions. Use closed questions only to confirm what you've learned ('So you use a night cream already — that's great'). Open questions gather intelligence; closed questions confirm understanding.",textEs:"Empieza con preguntas abiertas. Usa preguntas cerradas solo para confirmar lo que has aprendido ('Así que ya usas una crema de noche — eso es genial'). Las preguntas abiertas recopilan inteligencia; las preguntas cerradas confirman entendimiento."},{type:"keypoint",text:"ONE BIG EXCEPTION, and it is the most important question in the shop. In the demo, with the mirror in her hand, you ask 'Do you like it?' and then 'If you had it at home, would you use it?' — both closed, both on purpose. You are not after a conversation there. You are after the word yes, out loud, in her own voice, because in two minutes you are going to hand it straight back to her. Open questions are for the pavement, where you are still learning who she is. The two yeses are for the chair, where you are putting something on the record. See The Demo And The Two Yeses.",textEs:"UNA EXCEPCIÓN GRANDE, y es la pregunta más importante de la tienda. En la demo, con el espejo en su mano, le preguntas '¿Te gusta?' y luego '¿Si lo tuvieras en casa, lo usarías?' — las dos cerradas, y a propósito. Ahí no buscas conversación. Buscas la palabra sí, en voz alta, con su propia voz, porque dentro de dos minutos se la vas a devolver. Las preguntas abiertas son para la acera, donde todavía estás averiguando quién es. Los dos síes son para la silla, donde estás dejando algo grabado. Mira La Demo y los Dos Síes."},{type:"divider"},{type:"subheader",text:"The Question Ladder: From Surface to Deep",textEs:"La Escalera de Preguntas: De Superficial a Profundo"},{type:"paragraph",text:"Don't start with personal questions. Build from light to deep, like climbing a ladder. Each level requires trust earned at the previous level.",textEs:"No empieces con preguntas personales. Construye de ligero a profundo, como subir una escalera. Cada nivel requiere la confianza ganada en el nivel anterior."},{type:"numbered",items:["LEVEL 1 — OBSERVATIONAL (0-30 seconds): 'I love your scarf — is that from a local designer?' 'How's your day in {locationName} going?' Light, surface-level, easy to answer. Creates initial comfort.","LEVEL 2 — CONTEXTUAL (30 seconds - 2 minutes): 'What brings you to {locationName}?' 'Are you here for skiing or shopping?' 'What do you usually use on your skin?' Slightly more personal but still easy. Reveals context.","LEVEL 3 — PERSONAL (2-5 minutes): 'What are your main skin concerns?' 'How much time do you spend on your skincare routine?' 'When was the last time you really treated yourself?' Requires some trust. Reveals motivation and concerns.","LEVEL 4 — DECISION-ORIENTED (During the close): 'Which option feels better for you?' 'What would make this perfect for you?' 'If price weren't an issue, which would you choose?' Reveals objections and buying signals."],itemsEs:["NIVEL 1 — OBSERVACIONAL (0-30 segundos): 'Me encanta tu bufanda — ¿es de un diseñador local?' '¿Cómo va tu día en {locationName}?' Ligero, superficial, fácil de responder. Crea comodidad inicial.","NIVEL 2 — CONTEXTUAL (30 segundos - 2 minutos): '¿Qué te trae a {locationName}?' '¿Estás aquí para esquiar o de compras?' '¿Qué sueles usar en tu piel?' Un poco más personal pero aún fácil. Revela contexto.","NIVEL 3 — PERSONAL (2-5 minutos): '¿Cuáles son tus principales preocupaciones de piel?' '¿Cuánto tiempo dedicas a tu rutina de cuidado de la piel?' '¿Cuándo fue la última vez que realmente te consentiste?' Requiere algo de confianza. Revela motivación y preocupaciones.","NIVEL 4 — ORIENTADO A LA DECISIÓN (Durante el cierre): '¿Cuál opción se siente mejor para ti?' '¿Qué haría esto perfecto para ti?' 'Si el precio no fuera un problema, ¿cuál elegirías?' Revela objeciones y señales de compra."]},{type:"tip",text:"Never skip levels. Asking a Level 3 question ('What are your main skin concerns?') before establishing any rapport feels invasive. Climb the ladder naturally.",textEs:"Nunca te saltes niveles. Hacer una pregunta de Nivel 3 ('¿Cuáles son tus principales preocupaciones de piel?') antes de establecer cualquier rapport se siente invasivo. Sube la escalera naturalmente."},{type:"divider"},{type:"subheader",text:"Questions That Make Them Feel Smart",textEs:"Preguntas Que Los Hacen Sentir Inteligentes"},{type:"paragraph",text:"The best questions elevate the customer. They make the person feel knowledgeable, sophisticated, and perceptive. When someone feels smart, they're more confident — and confident buyers spend more.",textEs:"Las mejores preguntas elevan al cliente. Hacen que la persona se sienta conocedora, sofisticada y perceptiva. Cuando alguien se siente inteligente, está más seguro — y los compradores seguros gastan más."},{type:"bullets",items:["'You clearly take care of your skin — what products do you swear by?' — Acknowledges their expertise while gathering data.","'I can tell you know quality — what do you look for in skincare?' — Flatters their discernment.","'Most people don't know this, but the Dead Sea minerals are the most concentrated on Earth. Have you heard about them before?' — Gives them a chance to show knowledge OR learn something impressive.","'You seem like someone who does their research. What have you heard about collagen treatments?' — Positions them as informed and thoughtful."],itemsEs:["'Claramente cuidas tu piel — ¿en qué productos confías?' — Reconoce su experiencia mientras recopilas datos.","'Se nota que conoces la calidad — ¿qué buscas en el cuidado de la piel?' — Halaga su discernimiento.","'La mayoría no lo sabe, pero los minerales del Mar Muerto son los más concentrados de la Tierra. ¿Habías escuchado sobre ellos?' — Les da la oportunidad de demostrar conocimiento O aprender algo impresionante.","'Pareces alguien que investiga. ¿Qué has escuchado sobre los tratamientos de colágeno?' — Los posiciona como informados y reflexivos."]},{type:"divider"},{type:"subheader",text:"Questions to Uncover Objections Early",textEs:"Preguntas Para Descubrir Objeciones a Tiempo"},{type:"paragraph",text:"If you know the objection before you present the offer, you can address it proactively. These questions reveal hidden concerns:",textEs:"Si conoces la objeción antes de presentar la oferta, puedes abordarla proactivamente. Estas preguntas revelan preocupaciones ocultas:"},{type:"bullets",items:["'When you buy skincare, what matters most to you — ingredients, results, or value?' — Reveals their buying criteria.","'Are you shopping for yourself or looking for gifts too?' — Reveals budget flexibility and motivation.","'What's your usual budget range for skincare treatments?' — Direct but effective when asked warmly after rapport is built.","'Have you tried anything like this before? What was your experience?' — Reveals past objections and expectations."],itemsEs:["'Cuando compras productos de cuidado de la piel, ¿qué es lo más importante para ti — ingredientes, resultados o valor?' — Revela sus criterios de compra.","'¿Estás comprando para ti o también buscando regalos?' — Revela flexibilidad de presupuesto y motivación.","'¿Cuál es tu rango de presupuesto habitual para tratamientos de cuidado de la piel?' — Directo pero efectivo cuando se pregunta cálidamente después de haber construido rapport.","'¿Has probado algo como esto antes? ¿Cuál fue tu experiencia?' — Revela objeciones y expectativas pasadas."]},{type:"divider"},{type:"subheader",text:"Avoiding Interrogation Mode",textEs:"Evitando el Modo Interrogatorio"},{type:"paragraph",text:"Questions can backfire if they feel like an interview. Here's how to keep it conversational:",textEs:"Las preguntas pueden tener efecto contrario si se sienten como una entrevista. Aquí te decimos cómo mantenerlo conversacional:"},{type:"bullets",items:["SHARE BETWEEN QUESTIONS: Don't ask three questions in a row. Share something about yourself or the product between each question. It should feel like a conversation, not a survey.","USE STATEMENTS INSTEAD: Instead of 'Do you have dry skin?' say 'The mountain air here can really dry out your skin.' This invites them to respond without feeling questioned.","FOLLOW THE THREAD: When they mention something interesting, follow it. Don't rigidly stick to your question list. If they mention their daughter, ask about her. That's where the real connection lives.","KEEP IT LIGHT: Heavy, serious questioning creates pressure. Maintain a warm, playful tone throughout."],itemsEs:["COMPARTE ENTRE PREGUNTAS: No hagas tres preguntas seguidas. Comparte algo sobre ti o el producto entre cada pregunta. Debe sentirse como una conversación, no una encuesta.","USA DECLARACIONES EN LUGAR DE PREGUNTAS: En vez de '¿Tienes la piel seca?' di 'El aire de montaña aquí puede resecar mucho la piel.' Esto los invita a responder sin sentirse cuestionados.","SIGUE EL HILO: Cuando mencionen algo interesante, síguelo. No te aferres rígido a tu lista de preguntas. Si mencionan a su hija, pregunta por ella. Ahí es donde vive la conexión real.","MÁNTENLO LIGERO: Un cuestionamiento pesado y serio crea presión. Mantén un tono cálido y juguetón durante todo el proceso."]},{type:"script",text:"'So what brings you to {locationName}?' — 'A few days away with my husband.' — 'Oh amazing! Where are you staying? I love it here. And after a full day out, your skin must be so dry — travelling is brutal on it. What do you usually use to rehydrate?' See how each question follows naturally from the last? That's conversational questioning.",textEs:"'Entonces, ¿qué te trae a {locationName}?' — 'Unos días fuera con mi marido.' — '¡Ah, qué bien! ¿Dónde os alojáis? Me encanta esto. Y después de un día entero fuera, tu piel debe de estar resecísima — viajar es brutal para la piel. ¿Qué sueles usar para rehidratar?' ¿Ves cómo cada pregunta sigue naturalmente de la anterior? Eso es cuestionar de forma conversacional."},{type:"quote",text:"The best salespeople don't talk customers into buying. They ask customers into revealing what they truly want. Then they simply provide it.",textEs:"Los mejores vendedores no convencen a los clientes para que compren. Le preguntan a los clientes hasta revelar lo que realmente quieren. Y luego simplemente se lo proporcionan.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What is the main difference between open and closed questions?",options:["Open questions are longer","Open questions invite detailed responses and reveal information; closed questions get yes/no answers","Closed questions are more polite","Open questions are only for experienced sellers"],correctIndex:1,explanation:"Open questions (What, How, Why) invite detailed responses that reveal information. Closed questions (Do, Are, Have) get yes/no answers that end conversation."},{question:"What does the 'question ladder' refer to?",options:["Asking as many questions as possible","Building from light surface questions to deeper personal ones as trust develops","Only asking questions about the product","A specific list of 10 questions every seller must ask"],correctIndex:1,explanation:"The question ladder means starting with light observational questions, then moving to contextual, personal, and finally decision-oriented questions as trust builds. Skipping levels feels invasive."},{question:"How can you avoid 'interrogation mode' when asking questions?",options:["Only ask one question per interaction","Share information between questions and follow conversational threads naturally","Write all questions down and read them","Avoid questions altogether"],correctIndex:1,explanation:"Avoid interrogation by sharing between questions, following conversational threads (not rigid lists), using statements that invite response, and keeping the tone light and warm."}]},"connect-7":{id:"connect-7",categoryId:"connecting",title:"Spotting Buying Signals",titleEs:"Detectar Señales de Compra",subtitle:"Body language and verbal cues that scream 'I'm ready to buy'",subtitleEs:"Gestos y frases que gritan 'estoy lista para comprar'",duration:"8 min",icon:"Target",order:7,xpReward:100,sections:[{type:"header",text:"The Customer Is Always Telling You What They Want — If You're Listening",textEs:"El Cliente Siempre Te Está Diciendo Lo Que Quiere — Si Estás Escuchando"},{type:"paragraph",text:"The biggest mistake in sales is talking past the buying signal. The customer leans in, touches the product, asks about price — and the salesperson keeps pitching instead of closing. Buying signals are the green lights of sales. They tell you the customer is ready. Your job is to see them and act.",textEs:"El error más grande en ventas es seguir hablando después de la señal de compra. El cliente se inclina, toca el producto, pregunta por el precio — y el vendedor sigue presentando en vez de cerrar. Las señales de compra son las luces verdes de las ventas. Te dicen que el cliente está listo. Tu trabajo es verlas y actuar."},{type:"keypoint",text:"Buying signals happen before the customer verbally commits. If you wait for them to say 'I'll take it,' you've waited too long. Close when you SEE the signal, not when you HEAR the decision.",textEs:"Las señales de compra suceden antes de que el cliente se comprometa verbalmente. Si esperas a que digan 'Me lo llevo', has esperado demasiado. Cierra cuando VEAS la señal, no cuando ESCUCHES la decisión."},{type:"divider"},{type:"subheader",text:"Physical Buying Signals",textEs:"Señales de Compra Físicas"},{type:"paragraph",text:"The body reveals the decision before the mouth does. Watch for these physical cues:",textEs:"El cuerpo revela la decisión antes que la boca. Estate atento a estas señales físicas:"},{type:"bullets",items:["LEANING IN: When a customer physically moves closer to you, the product, or the mirror, they're interested. Leaning back or stepping away means resistance. Leaning in means engagement.","TOUCHING THE FACE: Touching cheeks, chin, or under the eyes while looking at the product or mirror = they're imagining themselves using it. This is one of the strongest positive signals.","HOLDING THE PRODUCT: If they pick up the bottle, read the label, or turn it over in their hands, they're taking ownership mentally. Encourage this — let them hold it.","MIRROR CHECKING: Looking at themselves in the mirror repeatedly during or after the demo is a strong buying signal. They like what they see and are imagining the result.","RELAXED SHOULDERS: Tense shoulders signal hesitation. When shoulders drop and relax, resistance is dropping too.","OPEN PALMS: Showing open palms while discussing the product indicates openness and receptivity. Closed fists or crossed arms signal the opposite.","NODDING: Nodding while you speak (especially during the offer) indicates agreement. Multiple nods = building commitment."],itemsEs:["INCLINARSE HACIA ADELANTE: Cuando un cliente se acerca físicamente a ti, al producto o al espejo, está interesado. Inclinarse hacia atrás o alejarse significa resistencia. Inclinarse hacia adelante significa compromiso.","TOCARSE LA CARA: Tocarse las mejillas, la barbilla o debajo de los ojos mientras miran el producto o el espejo = se están imaginando usándolo. Esta es una de las señales positivas más fuertes.","SOSTENER EL PRODUCTO: Si toman el frasco, leen la etiqueta o lo giran en sus manos, se están apropiando mentalmente. Anima esto — déjalos sostenerlo.","REVISARSE EN EL ESPEJO: Mirarse en el espejo repetidamente durante o después de la demostración es una fuerte señal de compra. Les gusta lo que ven y se están imaginando el resultado.","HOMBROS RELAJADOS: Hombros tensos señalan duda. Cuando los hombros bajan y se relajan, la resistencia también disminuye.","PALMAS ABIERTAS: Mostrar las palmas abiertas mientras discuten el producto indica apertura y receptividad. Puños cerrados o brazos cruzados señalan lo opuesto.","ASENTIR: Asentir mientras hablas (especialmente durante la oferta) indica acuerdo. Múltiples asentimientos = construyendo compromiso."]},{type:"divider"},{type:"subheader",text:"Verbal Buying Signals",textEs:"Señales de Compra Verbales"},{type:"paragraph",text:"Words are data. These phrases almost always indicate buying intent:",textEs:"Las palabras son datos. Estas frases casi siempre indican intención de compra:"},{type:"bullets",items:["'HOW LONG DOES IT LAST?' — They're calculating value per use. This is a value-oriented buyer calculating ROI.","'DO YOU SHIP?' — They're imagining owning it but worried about logistics. Solve the logistics, close the sale.","'HOW OFTEN DO I USE IT?' — They're fitting it into their lifestyle. Mental ownership has begun.","'WHAT DO YOU THINK?' (to partner) — They're seeking validation for a decision they've already made. Engage the partner positively.","'CAN I GET THIS IN...?' — They're personalizing the purchase. Color, size, scent — doesn't matter. Personalization = commitment.","'IS THIS THE LAST ONE?' — Scarcity concern means they want it. Create gentle urgency.","'WHAT'S THE RETURN POLICY?' — Risk management. They're close but need a safety net.","'DO YOU HAVE A CARD?' — This is as close to 'I'll take it' as you can get without hearing the words. Close immediately."],itemsEs:["'¿CUÁNTO DURA?' — Están calculando el valor por uso. Este es un comprador orientado al valor calculando el ROI.","'¿HACEN ENVÍOS?' — Se están imaginando teniéndolo pero preocupados por la logística. Resuelve la logística, cierra la venta.","'¿CON QUÉ FRECUENCIA LO USO?' — Lo están integrando a su estilo de vida. La apropiación mental ha comenzado.","'¿TÚ QUÉ PIENSAS?' (a su pareja) — Buscan validación para una decisión que ya tomaron. Involucra a la pareja positivamente.","'¿PUEDO LLEVAR ESTO EN...?' — Están personalizando la compra. Color, tamaño, aroma — no importa. Personalización = compromiso.","'¿ESTE ES EL ÚLTIMO?' — La preocupación por escasez significa que lo quieren. Crea urgencia sutil.","'¿CUÁL ES LA POLÍTICA DE DEVOLUCIÓN?' — Gestión de riesgo. Están cerca pero necesitan una red de seguridad.","'¿TIENES TARJETA?' — Esto es tan cerca de 'Me lo llevo' como puedes estar sin escuchar las palabras. Cierra inmediatamente."]},{type:"divider"},{type:"subheader",text:"The Micro-Signals: Blink-and-You-Miss-Them",textEs:"Las Micro-Señales: Parpadeas y Te las Pierdes"},{type:"paragraph",text:"These happen in fractions of a second. Train yourself to notice:",textEs:"Estas suceden en fracciones de segundo. Entrénate para notarlas:"},{type:"bullets",items:["EYEBROW FLASH: A quick raise of both eyebrows when you mention a benefit or show the result. Surprise and interest. Follow up immediately.","PUPIL DILATION: When people see something they want, their pupils dilate. Hard to spot but reliable.","LIP PRESS: Pressing lips together while considering = internal deliberation. Stay quiet and let them think.","BREATH HOLD + RELEASE: Holding breath during the price reveal, then releasing = relief. They can afford it.","QUICK GLANCE AT WALLET/BAG: Checking if they have payment ready. Almost always a buying signal."],itemsEs:["DESTELLO DE CEJAS: Un levantamiento rápido de ambas cejas cuando mencionas un beneficio o muestras el resultado. Sorpresa e interés. Da seguimiento inmediatamente.","DILATACIÓN PUPILAR: Cuando la gente ve algo que quiere, sus pupilas se dilatan. Difícil de notar pero confiable.","PRESIÓN DE LABIOS: Presionar los labios juntos mientras consideran = deliberación interna. Mantente callado y déjalos pensar.","AGUANTAR LA RESPIRACIÓN + SOLTAR: Aguantar la respiración durante la revelación del precio, y luego soltar = alivio. Pueden pagarlo.","MIRADA RÁPIDA A LA CARTERA/BOLSA: Verificando si tienen el pago listo. Casi siempre es una señal de compra."]},{type:"divider"},{type:"subheader",text:"When to Close: Timing Is Everything",textEs:"Cuándo Cerrar: El Momento Lo Es Todo"},{type:"paragraph",text:"Closing too early feels pushy. Closing too late loses momentum. The sweet spot is the SECOND buying signal. Here's why:",textEs:"Cerrar demasiado temprano se siente agresivo. Cerrar demasiado tarde pierde el impulso. El punto ideal es la SEGUNDA señal de compra. Aquí te explicamos por qué:"},{type:"numbered",items:["FIRST SIGNAL: 'Interesting.' They lean in. Good, but not enough. Keep building value.","SECOND SIGNAL: They touch the product and ask 'How long does it last?' NOW. This is your moment. The second signal confirms genuine interest, not just politeness.","THIRD SIGNAL: They're asking about payment or shipping. If you haven't closed by now, close immediately — every word past this point risks the sale."],itemsEs:["PRIMERA SEÑAL: 'Interesante.' Se inclinan. Bueno, pero no suficiente. Sigue construyendo valor.","SEGUNDA SEÑAL: Tocan el producto y preguntan '¿Cuánto dura?' AHORA. Este es tu momento. La segunda señal confirma interés genuino, no solo cortesía.","TERCERA SEÑAL: Están preguntando sobre pago o envío. Si no has cerrado para ahora, cierra inmediatamente — cada palabra después de este punto arriesga la venta."]},{type:"script",text:"Customer: 'How long does one syringe last?' (Buying signal!) You: 'A full year — about sixty treatments in that one syringe. At {currency}300 that is five a go. Shall I wrap one for you?' Direct close. Don't oversell past this point — and if she comes back at you on the number, that is when the ladder starts, not before.",textEs:"Cliente: '¿Cuánto dura una jeringa?' (¡Señal de compra!) Tú: 'Un año entero — unos sesenta tratamientos en esa jeringa. A {currency}300 sale a cinco cada uno. ¿Te la envuelvo?' Cierre directo. No vendas de más a partir de aquí — y si te discute el número, ahí es donde empieza la escalera, no antes."},{type:"tip",text:"When you spot a buying signal, STOP TALKING ABOUT FEATURES. Switch to closing mode. Summarize the value, present the options, and ask for the decision. Every additional feature you mention past the buying signal creates new objections.",textEs:"Cuando detectes una señal de compra, DEJA DE HABLAR SOBRE CARACTERÍSTICAS. Cambia al modo de cierre. Resume el valor, presenta las opciones, y pide la decisión. Cada característica adicional que menciones después de la señal de compra crea nuevas objeciones."},{type:"divider"},{type:"subheader",text:"False Signals: When Interest Isn't Buying Intent",textEs:"Señales Falsas: Cuando el Interés No es Intención de Compra"},{type:"paragraph",text:"Not every positive signal means a sale is imminent. Learn to distinguish genuine buying signals from polite interest:",textEs:"No toda señal positiva significa que una venta es inminente. Aprende a distinguir las señales de compra genuinas del interés cortés:"},{type:"comparison",left:{label:"Genuine Buying Signal",text:"They ask specific questions about usage, logistics, or value. Their questions are about OWNING the product. They're problem-solving for purchase."},leftEs:{label:"Señal de Compra Genuina",text:"Hacen preguntas específicas sobre uso, logística o valor. Sus preguntas son sobre POSEER el producto. Están resolviendo problemas para la compra."},right:{label:"Polite Interest (Not Ready)",text:"They say 'It's nice' or 'I'll think about it.' Their questions are general. No specifics about owning. They're being polite, not buying."},rightEs:{label:"Interés Educado (No Está Listo)",text:"Dicen 'está bien' o 'me lo pensaré'. Sus preguntas son generales. Nada concreto sobre llevárselo. Están siendo educados, no comprando."}},{type:"quote",text:"The moment you see the buying signal, your job changes from convincing to facilitating. Make it easy for them to say yes.",textEs:"En el momento en que ves la señal de compra, tu trabajo cambia de convencer a facilitar. Haz que sea fácil para ellos decir sí.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"When is the optimal time to close based on buying signals?",options:["After the first positive signal","After the second buying signal confirms genuine interest","Only after they explicitly say they want to buy","After you've listed all product features"],correctIndex:1,explanation:"The second buying signal is the sweet spot. The first signal could be politeness; the second confirms genuine interest. Closing after the third signal may be too late."},{question:"Which of these is a strong PHYSICAL buying signal?",options:["Checking their phone","Touching their face while looking at the product","Crossing their arms","Stepping backward"],correctIndex:1,explanation:"Touching the face (cheeks, chin, under eyes) while looking at the product means they're imagining themselves using it. This is one of the strongest positive buying signals."},{question:"What should you do when you spot a buying signal?",options:["Keep listing more product features","Switch to closing mode and stop adding new information","Lower the price immediately","Ask if they're ready to buy in a pushy way"],correctIndex:1,explanation:"When you spot a buying signal, switch from convincing to closing. Summarize value, present options, and ask for the decision. Every new feature you mention creates potential objections."}]},"connect-8":{id:"connect-8",categoryId:"connecting",title:"Handling Different Personality Types",titleEs:"Manejando Diferentes Tipos de Personalidad",subtitle:"The four you meet all day: the Interrogator, the Rusher, the Sweetheart, the Showman",subtitleEs:"Los cuatro que te encuentras todo el día: el Interrogador, el Acelerado, el Simpático, el Showman",duration:"10 min",icon:"Users",order:8,xpReward:150,sections:[{type:"header",text:"One Pitch Does NOT Fit All",textEs:"Una Presentación No Le Queda a Todos"},{type:"paragraph",text:"You have already noticed it. Some of them want the whole ingredient list before they will let you touch their hand. Some want the price and the door. Some have to like you first and then they buy anything. And some are not really buying a cream at all, they are buying a story to tell at brunch. Same shop, same products, four completely different conversations.",textEs:"Ya te has dado cuenta. Algunos quieren la lista de ingredientes entera antes de dejarte tocarles la mano. Otros quieren el precio y la puerta. Otros primero tienen que caerte bien y luego te compran lo que sea. Y otros no están comprando una crema: están comprando una historia para contar en el brunch. La misma tienda, los mismos productos, cuatro conversaciones completamente distintas."},{type:"keypoint",text:"Four people you will meet today: the Interrogator, the Rusher, the Sweetheart and the Showman. Work out which one is standing in front of you in the first ten seconds and the rest of it writes itself. Get it wrong and you will be giving a chemistry lecture to somebody who just wanted a laugh.",textEs:"Cuatro personas que te vas a encontrar hoy: el Interrogador, el Acelerado, el Simpático y el Showman. Averigua cuál tienes delante en los primeros diez segundos y lo demás se escribe solo. Fállalo y estarás dando una clase de química a alguien que solo quería reírse un rato."},{type:"divider"},{type:"subheader",text:"Type 1: The Interrogator",textEs:"Tipo 1: El Interrogador"},{type:"paragraph",text:"Wants the ingredient list before they want anything else. Reads the box. Asks you three questions before you have finished the first sentence. They are not having a go at you and they are not going to walk — they just need to know what is in it before they will enjoy it.",textEs:"Quiere la lista de ingredientes antes que ninguna otra cosa. Se lee la caja. Te hace tres preguntas antes de que termines la primera frase. No va a por ti y no se va a marchar — simplemente necesita saber qué lleva antes de poder disfrutarlo."},{type:"bullets",items:["HOW YOU SPOT ONE: Picks the box up and turns it over. Asks what is in it before asking what it costs. Goes quiet and reads. That silence is not boredom, it is homework.","WHAT WORKS: Know your product and answer straight. 'Dead Sea mineral salt — magnesium, calcium, potassium. One jar is 8 to 12 months of weekly treatments, which is under {currency}2 a go.' Numbers you actually know, said without hesitating.","WHAT KILLS IT: Waffle, or rushing them, or making something up. This is the one customer who will catch you out — and if they catch you once, you have lost the whole thing.","HOW YOU CLOSE: Let the box do the last bit. 'Read it properly, I am in no hurry. I am not going anywhere.' Then go quiet. They close themselves more often than you would think."],itemsEs:["CÓMO LOS PILLAS: Coge la caja y le da la vuelta. Pregunta qué lleva antes de preguntar cuánto cuesta. Se queda callado leyendo. Ese silencio no es aburrimiento, son deberes.","LO QUE FUNCIONA: Sábete el producto y contesta a pelo. 'Sal mineral del Mar Muerto: magnesio, calcio, potasio. Un bote son de 8 a 12 meses de tratamientos semanales, o sea menos de {currency}2 cada vez.' Números que te sepas de verdad, dichos sin dudar.","LO QUE LO MATA: Enrollarte, meterle prisa o inventarte algo. Este es el cliente que te va a pillar — y si te pilla una vez, ya lo has perdido del todo.","CÓMO CIERRAS: Que la caja haga el último trozo. 'Léetelo bien, que yo no tengo ninguna prisa. Yo no me muevo de aquí.' Y te callas. Se cierran solos más veces de las que te imaginas."]},{type:"script",text:"'Go on then, ask me. Dead Sea mineral salt — magnesium, calcium, potassium. Once a week, five minutes, and one jar sees you through the best part of a year. That is under {currency}2 a time. Here, the list is on the box, have a proper look while I do your other hand.' Straight answers, no waffle, and the demo keeps going while they read.",textEs:"'Venga, pregúntame. Sal mineral del Mar Muerto: magnesio, calcio, potasio. Una vez por semana, cinco minutos, y un bote te dura casi el año entero. Eso son menos de {currency}2 cada vez. Toma, la lista está en la caja, míratela con calma mientras te hago la otra mano.' Respuestas directas, sin rollo, y la demo sigue mientras leen."},{type:"divider"},{type:"subheader",text:"Type 2: The Rusher",textEs:"Tipo 2: El Acelerado"},{type:"paragraph",text:"Wants the price and the door. No chat, no story, no building up to it. They are not rude — they are somewhere else in their head already, and every extra sentence you add is a reason to leave.",textEs:"Quiere el precio y la puerta. Sin charla, sin historia, sin ir calentándolo. No es un borde — ya está en otro sitio con la cabeza, y cada frase de más que le sueltas es un motivo para irse."},{type:"bullets",items:["HOW YOU SPOT ONE: Walking with somewhere to be. Looks at the watch. Answers you in three words. Already half turned back towards the street.","WHAT WORKS: Beat them to it. 'I know you're in a rush.' Then: two minutes, one hand, done. Give the result before you give the speech.","WHAT KILLS IT: Chat. Three options. Anything that starts 'so what happens is...'. They will not tell you they are bored, they will just be gone.","HOW YOU CLOSE: Two numbers, one question, nothing else. '{currency}210 with the gift, or {currency}300 for the two. Which one?' Then shut up and get the machine."],itemsEs:["CÓMO LOS PILLAS: Andan con un sitio al que llegar. Miran el reloj. Te contestan con tres palabras. Ya están medio girados hacia la calle.","LO QUE FUNCIONA: Adelántate. 'Sé que vas con prisa.' Y luego: dos minutos, una mano, listo. Dale el resultado antes que el discurso.","LO QUE LO MATA: La cháchara. Tres opciones. Cualquier cosa que empiece por 'lo que pasa es que...'. No te van a decir que se aburren, simplemente ya no están.","CÓMO CIERRAS: Dos números, una pregunta y nada más. '{currency}210 con el regalo, o {currency}300 las dos. ¿Cuál?' Y te callas y vas a por el datáfono."]},{type:"script",text:"'I know you are in a hurry. Two minutes. One eye. You will see the result yourself in the mirror. If you don't love it, no problem. If you do, I have two price options that take 30 seconds to explain. Sound fair?' Direct, time-bound, respectful of their schedule.",textEs:"'Sé que tienes prisa. Dos minutos. Un ojo. Verás el resultado tú misma en el espejo. Si no te encanta, no hay problema. Si sí, tengo dos opciones de precio que toman 30 segundos en explicar. ¿Te parece justo?' Directo, con tiempo definido, respetuoso de su agenda."},{type:"divider"},{type:"subheader",text:"Type 3: The Sweetheart",textEs:"Tipo 3: El Simpático"},{type:"paragraph",text:"Has to like you first. Once she does, she will buy almost anything you put in her hand. She is not deciding about a cream, she is deciding about you — and she made her mind up in the first thirty seconds, before you said a single thing about the product.",textEs:"Primero le tienes que caer bien. En cuanto le caes bien, se lleva casi cualquier cosa que le pongas en la mano. No está decidiendo sobre una crema, está decidiendo sobre ti — y lo decidió en los primeros treinta segundos, antes de que dijeras nada del producto."},{type:"bullets",items:["HOW YOU SPOT ONE: Asks you where you are from. Wants to know how long you have worked here. Laughs early. Looks at her partner before she answers you. Usually the best half hour of your shift.","WHAT WORKS: Be a person. Talk about their trip, tell them about yours, get a laugh in before you get a product in. The demo should feel like a five-minute spa moment in the middle of a day of shopping.","WHAT KILLS IT: Going cold on her the second the money comes up. She will feel the switch, and after that everything you say sounds like it was always the plan.","HOW YOU CLOSE: Warm and easy, with the partner in on it. 'Look at that. Go on, treat yourself — which one do you fancy?' Never hard, never fast."],itemsEs:["CÓMO LOS PILLAS: Te pregunta de dónde eres. Quiere saber cuánto llevas trabajando aquí. Se ríe pronto. Mira a su pareja antes de contestarte. Suele ser la mejor media hora de tu turno.","LO QUE FUNCIONA: Sé una persona. Habla de su viaje, cuéntale el tuyo, sácale una risa antes de sacarle un producto. La demo tiene que parecer cinco minutos de spa en mitad de un día de compras.","LO QUE LO MATA: Ponerte frío en cuanto sale el dinero. Nota el cambio, y a partir de ahí todo lo que digas suena a que ese era el plan desde el principio.","CÓMO CIERRAS: Con calidez y sin prisa, y con la pareja metida en el ajo. 'Mira eso. Venga, date el capricho, ¿cuál te apetece?' Nunca duro, nunca rápido."]},{type:"script",text:"'Where are you two from? ... No way, I have got family there. Right, sit down, you are getting my favourite one — five minutes of spa in the middle of your shopping day. Do not thank me, just enjoy it.' The person comes first, the product comes second, and she has already decided by the time you get to it.",textEs:"'¿De dónde sois vosotros dos? ... ¡Anda, si tengo familia allí! Venga, siéntate, que te voy a hacer el que más me gusta a mí — cinco minutos de spa en mitad del día de compras. No me des las gracias, tú disfruta.' Primero la persona, después el producto, y para cuando llegas al producto ya lo tiene decidido."},{type:"divider"},{type:"subheader",text:"Type 4: The Showman",textEs:"Tipo 4: El Showman"},{type:"paragraph",text:"Not buying a cream. Buying a story to tell at brunch. Talks the whole way through, jumps subject three times a minute, and is already imagining who she is going to show it to. Give her the story and she will sell herself the product.",textEs:"No está comprando una crema. Está comprando una historia para contar en el brunch. Habla todo el rato, cambia de tema tres veces por minuto y ya se está imaginando a quién se lo va a enseñar. Dale la historia y ella sola se vende el producto."},{type:"bullets",items:["HOW YOU SPOT ONE: Talks more than you do. Gets loud when it works. Says 'oh my god, my sister would LOVE this' before you have mentioned anybody else.","WHAT WORKS: Go up to meet her, do not stand there being calm at her. Make it an event. Get the mirror out with a bit of theatre. Let her talk — every sentence she says out loud is one you do not have to.","WHAT KILLS IT: Talking over her stories to get back to the script. She needs to feel like the most interesting person on the street, because right now she is.","HOW YOU CLOSE: Straight into the gift. 'Your sister is going to be furious. Shall we do two and save her the trouble?' Her own excitement does the closing."],itemsEs:["CÓMO LOS PILLAS: Habla más que tú. Sube el volumen cuando funciona. Te suelta 'ay, madre, a mi hermana le ENCANTARÍA' antes de que tú hayas nombrado a nadie.","LO QUE FUNCIONA: Súbete tú a su nivel, no te quedes ahí tranquilo mirándola. Móntalo como un evento. Saca el espejo con un poco de teatro. Déjala hablar — cada frase que suelta es una que no tienes que decir tú.","LO QUE LO MATA: Pisarle las historias para volver a tu guion. Necesita sentirse la persona más interesante de la calle, porque ahora mismo lo es.","CÓMO CIERRAS: Directo al regalo. 'Tu hermana se va a poner de mala leche. ¿Nos llevamos dos y le ahorramos el disgusto?' Su propia emoción hace el cierre."]},{type:"script",text:"'Wait until you tell your friends about this! They are going to be SO jealous. You will be at brunch like 'Oh this? Just something I picked up in {locationName}.' So — are we doing the full experience or starting with the essentials? Let us make it fun!' Enthusiastic, story-driven, playful.",textEs:"'¡Espera a que les cuentes a tus amigas sobre esto! Van a estar TAN celosas. Vas a estar en el brunch como '¿Oh, esto? Algo que compré en {locationName}.' Entonces — ¿hacemos la experiencia completa o empezamos con lo esencial? ¡Hagámoslo divertido!' Entusiasta, impulsado por historias, juguetón."},{type:"divider"},{type:"subheader",text:"Quick Reference: Adapting Your Style",textEs:"Referencia Rápida: Adaptando Tu Estilo"},{type:"bullets",items:["THE INTERROGATOR → Know your product, answer straight, then go quiet","THE RUSHER → Fast, two numbers, one question","THE SWEETHEART → Be a person first, sell second","THE SHOWMAN → Match the volume, give her the story"],itemsEs:["EL INTERROGADOR → Sábete el producto, contesta a pelo y luego cállate","EL ACELERADO → Rápido, dos números, una pregunta","EL SIMPÁTICO → Primero sé una persona, luego vende","EL SHOWMAN → Súbete al volumen y dale la historia"]},{type:"tip",text:"Most people are two of these at once. An Interrogator in a hurry wants the facts fast. A Sweetheart who is also a Showman wants forty minutes and will spend three hundred. Read whichever one is louder, then borrow from the other.",textEs:"Casi todo el mundo es dos de estos a la vez. Un Interrogador con prisa quiere los datos rápido. Un Simpático que además es Showman quiere cuarenta minutos y se gasta trescientos. Lee el que suene más fuerte y cógele algo al otro."},{type:"quote",text:"One pitch, said the same way to everybody who walks past, misses most of them. Same words, four different speeds.",textEs:"Un solo discurso, dicho igual a todo el que pasa, se deja a la mayoría por el camino. Las mismas palabras, a cuatro velocidades distintas.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"The Interrogator picks up the box and starts reading. What do you do?",options:["Talk over the reading so you keep control of the conversation","Answer straight, then let them read and go quiet","Move them off the ingredients and back onto how it feels","Tell them everybody asks that and it is all completely natural"],correctIndex:1,explanation:"The silence is homework, not boredom. Know your product, answer without hesitating, then stop talking. They close themselves more often than you would think."},{question:"What does the Rusher want from you?",options:["A bit of chat first so the sale does not feel cold","Three options laid out so they can weigh them up properly","Two numbers and one question","A long, careful explanation of how the treatment works"],correctIndex:2,explanation:"Beat them to the rush, give the result before the speech, then two numbers and one question. Every extra sentence is a reason to leave."},{question:"What is the Showman actually buying?",options:["The lowest price she can talk you down to today","Proof that the ingredients are worth what you are asking","A story she can tell at brunch","A quiet treatment with as little fuss as possible"],correctIndex:2,explanation:"She is not buying a cream. Match her volume, make it an event, and let her talk — every sentence she says out loud is one you do not have to."}]},"prod-1":{id:"prod-1",categoryId:"products",title:"Price Anchoring Psychology",titleEs:"Psicología del Anclaje de Precio",subtitle:"Why stating the Europe price first works — the contrast principle and anchoring mistakes",subtitleEs:"El primer precio mencionado es el punto de referencia mental",duration:"10 min",icon:"TrendingUp",order:1,xpReward:150,sections:[{type:"header",text:"The First Number They Hear Becomes Their Reference Point",textEs:"El Primer Número que Escuchan Se Convierte en su Punto de Referencia"},{type:"paragraph",text:"Price anchoring is one of the most powerful tools in sales psychology. The first price a customer hears becomes their mental anchor — the reference point against which all other prices are judged. If you start with {currency}50, {currency}300 sounds expensive. If you start with {currency}500, {currency}300 sounds like a bargain. The product hasn't changed. Only the anchor has. This is why we ALWAYS state the Europe price before the {locationName} price.",textEs:"El anclaje de precio es una de las herramientas más poderosas de la psicología de ventas. El primer precio que escucha un cliente se convierte en su ancla mental — el punto de referencia contra el cual se juzgan todos los demás precios. Si empiezas con {currency}50, {currency}300 suena caro. Si empiezas con {currency}500, {currency}300 suena una ganga. El producto no ha cambiado. Solo cambió el ancla. Por eso SIEMPRE decimos el precio de Europa antes que el de {locationName}."},{type:"keypoint",text:"The anchor sets the frame. Frame the product as a {currency}500 item that happens to cost {currency}300 in {locationName}, and it feels like a steal. Frame it as a {currency}300 item, and it feels like a purchase decision. Always anchor HIGH.",textEs:"El ancla marca el marco. Enmarca el producto como algo de {currency}500 que por casualidad cuesta {currency}300 en {locationName}, y se siente como un robo. Enmárcalo como algo de {currency}300, y se siente como una decisión de compra. Siempre ancla ALTO."},{type:"divider"},{type:"subheader",text:"The Contrast Principle: How {currency}500 Makes {currency}300 Feel Cheap",textEs:"El Principio de Contraste: Cómo {currency}500 Hace que {currency}300 se Sienta Barato"},{type:"paragraph",text:"The contrast principle states that we perceive things differently depending on what we compare them to. A 20kg weight feels light if you first lift a 40kg weight. A {currency}300 price feels cheap if you first hear {currency}500. This isn't manipulation — it's how human perception works.",textEs:"El principio de contraste establece que percibimos las cosas de manera diferente dependiendo de con qué las comparemos. Una pesa de 20kg se siente ligera si primero levantaste una de 40kg. Un precio de {currency}300 se siente barato si primero escuchaste {currency}500. Esto no es manipulación — así funciona la percepción humana."},{type:"script",text:"'Across Europe, this treatment goes for around {currency}500. It's expensive because it works instantly and lasts long-term. But here in {locationName} — you know how special it is here — instead of {currency}500, we charge only {currency}300.' The customer doesn't hear '{currency}300 product.' They hear '{currency}500 product for {currency}300.' That's a {currency}200 win.",textEs:"'En toda Europa, este tratamiento cuesta alrededor de {currency}500. Es caro porque funciona al instante y dura a largo plazo. Pero aquí en {locationName} — ya sabes lo especial que es este lugar — en vez de {currency}500, cobramos solo {currency}300.' El cliente no escucha 'producto de {currency}300.' Escucha 'producto de {currency}500 por {currency}300.' Eso es un ahorro de {currency}200."},{type:"bullets",items:["STEP 1 — ESTABLISH EUROPE PRICE: 'Around Europe this goes for {currency}200' (Peeling) or '{currency}500' (Syringe) or '{currency}80 each' (Scrub/Butter/Nail Kit). This is the anchor.","STEP 2 — SAY WHY IT COSTS THAT: One line, no more — 'because it works,' 'because it lasts a year,' 'because you see it in two minutes.' That is what holds the big number up.","STEP 3 — SWING IT ACROSS: 'But here in {locationName}...' That is the whole bridge. Say it like you are letting them in on where the good prices live. No apology, no explanation — just the pause, then the number.","STEP 4 — STATE THE LOCAL PRICE: '...it's only {currency}300.' After hearing {currency}500, {currency}300 doesn't just sound lower. It sounds like a completely different category of purchase."],itemsEs:["PASO 1 — ESTABLECE EL PRECIO DE EUROPA: 'En Europa esto cuesta alrededor de {currency}200' (Peeling) o '{currency}500' (Jeringa) o '{currency}80 cada uno' (Exfoliante/Body Butter/Kit de Uñas). Esta es el ancla.","PASO 2 — DI POR QUÉ CUESTA ESO: Una frase, no más — 'porque funciona', 'porque te dura un año', 'porque lo ves en dos minutos'. Eso es lo que sostiene el número grande.","PASO 3 — PÁSALO AL OTRO LADO: 'Pero aquí en {locationName}...' Ese es todo el puente. Dilo como quien les está contando dónde viven los precios buenos. Sin disculpas, sin explicaciones — solo la pausa, y luego el número.","PASO 4 — DI EL PRECIO LOCAL: '...es solo {currency}300.' Después de escuchar {currency}500, {currency}300 no solo suena más bajo. Suena como una categoría de compra completamente diferente."]},{type:"divider"},{type:"subheader",text:"When to Deliver the Price Gap",textEs:"Cuándo Dar la Diferencia de Precio"},{type:"paragraph",text:"The price gap is your credibility booster. It shows what this costs elsewhere without devaluing the product. But timing matters:",textEs:"La diferencia de precio es tu potenciador de credibilidad. Enseña lo que esto cuesta en otros sitios sin devaluar el producto. Pero el momento importa:"},{type:"bullets",items:["BEST: Immediately after the Europe price, with no pause in between. 'Around Europe it's {currency}500... but here in {locationName}, it's {currency}300.' The two numbers land together, before they question product quality.","GOOD: During the initial stop. 'Come try this — the prices here in {locationName} are amazing!' Sets expectation early.","LESS EFFECTIVE: After they've already heard the price. If you say 'It's {currency}300' first, then bring up the Europe price, it feels like an excuse, not a comparison."],itemsEs:["MEJOR: Justo después del precio de Europa, sin pausa entre medias. 'En Europa cuesta {currency}500... pero aquí en {locationName}, cuesta {currency}300.' Los dos números caen juntos, antes de que cuestionen la calidad del producto.","BUENO: Durante la parada inicial. '¡Ven a probar esto — los precios aquí en {locationName} son increíbles!' Establece la expectativa desde el principio.","MENOS EFECTIVO: Después de que ya escucharon el precio. Si dices 'Es {currency}300' primero, y luego sacas el precio de Europa, se siente como una excusa, no como una comparación."]},{type:"tip",text:"Never apologize for the price. Never say 'I know it's expensive' or 'It's a lot, but...' These phrases undermine the anchor. State the Europe price confidently, give the {locationName} price matter-of-factly, and let the contrast do the work.",textEs:"Nunca te disculpes por el precio. Nunca digas 'Sé que es caro' o 'Es mucho, pero...' Estas frases debilitan el ancla. Di el precio de Europa con confianza, da el precio de {locationName} con naturalidad, y deja que el contraste haga el trabajo."},{type:"divider"},{type:"subheader",text:"Anchoring Mistakes That Backfire",textEs:"Errores de Anclaje que se Vuelven en tu Contra"},{type:"bullets",items:["STARTING WITH THE LOW PRICE: 'It's only {currency}50!' Now {currency}50 is the anchor, and if you try to upsell to {currency}120, it feels like a huge jump. Always anchor high first.","MENTIONING THE COST PRICE: 'We buy this for {currency}30 and sell it for {currency}60.' This destroys perceived value. Customers don't care about your margins. They care about what they get.","APOLOGETIC FRAMING: 'I know it's expensive, but...' This tells the customer they should feel bad about the price. Instead: 'This is a premium product because it delivers premium results.'","COMPARING TO CHEAP ALTERNATIVES: 'This is better than drugstore cream.' Now you've anchored to drugstore prices. Compare to luxury alternatives instead: 'This replaces a {currency}200 salon treatment.'","GIVING THE DISCOUNT FIRST: 'It's 50% off!' Now they wonder what the original price was and why it's discounted so heavily. Lead with full price, then reveal the savings."],itemsEs:["EMPEZAR CON EL PRECIO BAJO: '¡Es solo {currency}50!' Ahora {currency}50 es el ancla, y si intentas vender algo adicional por {currency}120, se siente como un salto enorme. Siempre ancla alto primero.","MENTIONAR EL PRECIO DE COSTO: 'Compramos esto en {currency}30 y lo vendemos en {currency}60.' Esto destruye el valor percibido. A los clientes no les importan tus márgenes. Les importa lo que reciben.","ENMARCADO APOLOGÉTICO: 'Sé que es caro, pero...' Esto le dice al cliente que debería sentirse mal por el precio. En su lugar: 'Este es un producto premium porque ofrece resultados premium.'","COMPARAR CON ALTERNATIVAS BARATAS: 'Esto es mejor que la crema de la farmacia.' Ahora anclaste a precios de farmacia. Compara con alternativas de lujo en su lugar: 'Esto reemplaza un tratamiento de salón de {currency}200.'","DAR EL DESCUENTO PRIMERO: '¡50% de descuento!' Ahora se preguntan cuál era el precio original y por qué está tan rebajado. Empieza con el precio completo, luego revela el ahorro."]},{type:"comparison",left:{label:"Weak Anchoring",text:"'This peeling is {currency}100. It's a good deal.' No contrast. No frame. The customer evaluates {currency}100 against their general sense of what skincare should cost."},leftEs:{label:"Anclaje Débil",text:"'Este peeling cuesta {currency}100. Es buen precio.' Sin contraste. Sin marco. El cliente evalúa {currency}100 contra su idea general de lo que debería costar el cuidado de la piel."},right:{label:"Strong Anchoring",text:"'Around Europe this goes for {currency}200. But here in {locationName}, it's only {currency}100 — that's 50% off the Europe price just for being here.' The customer evaluates {currency}100 against {currency}200. It feels like a {currency}100 win."},rightEs:{label:"Anclaje Fuerte",text:"'Por Europa esto cuesta {currency}200. Pero aquí en {locationName}, son solo {currency}100 — un 50% menos que el precio de Europa solo por estar aquí.' El cliente evalúa {currency}100 contra {currency}200. Se siente como ganar {currency}100."}},{type:"quote",text:"The price is not a number — it's a story. Tell the story right, and the number becomes small. Tell it wrong, and the number becomes a wall.",textEs:"El precio no es un número — es una historia. Cuenta la historia bien, y el número se vuelve pequeño. Cuéntala mal, y el número se convierte en una pared.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Why should you always state the Europe price before the local price?",options:["Because Europe prices are more accurate","Because the first price heard becomes the mental anchor that makes the local price feel like a bargain","Because customers prefer European pricing","Because it's required by law"],correctIndex:1,explanation:"The first price heard becomes the mental anchor. When a customer hears {currency}500 first, {currency}300 feels like a bargain. If they hear {currency}300 first, they evaluate it against their general sense of skincare pricing, which is less favorable."},{question:"What is the role of the price comparison in price anchoring?",options:["It hides the local price until they have already agreed to buy","It gives them a reference point without cheapening the product","It leaves you room to drop further later in the haggle","It proves the product is worth more than we charge for it"],correctIndex:1,explanation:"The gap reads as where they happen to be standing, not as money off. Sounding special is exactly the effect you want — it just is not the mechanism. A discounted product is a cheaper product in their head; a {locationName} price is not."},{question:"Which of these is a price anchoring mistake?",options:["Starting with the Europe price","Giving the Europe price and the {locationName} price side by side","Starting with the low price or apologizing for the cost","Using the contrast principle"],correctIndex:2,explanation:"Starting with the low price sets a low anchor, making upsells feel expensive. Apologizing for the price ('I know it's expensive') undermines the value. Both destroy effective anchoring."}]},"prod-2":{id:"prod-2",categoryId:"products",title:"The Two-Choice Framework",titleEs:"El Marco de Dos Opciones",subtitle:"Why two options beat one — changing 'yes or no' into 'which one'",subtitleEs:"Por qué dos opciones ganan a una — cambiar '¿sí o no?' por '¿cuál?'",duration:"10 min",icon:"GitFork",order:2,xpReward:150,sections:[{type:"header",text:"Two Choices Turn a Decision Into a Selection",textEs:"Dos Opciones Convierten una Decisión en una Selección"},{type:"paragraph",text:"When you offer one option, the customer's brain asks: 'Should I buy this or not?' That's a yes/no question, and 'no' is the default — it's easier, safer, requires no action. When you offer two options, the brain asks a different question: 'Which one should I choose?' The decision to buy is assumed. Now they're just picking between A and B. This simple reframing dramatically increases conversion.",textEs:"Cuando ofreces una opción, el cerebro del cliente se pregunta: '¿Debería comprar esto o no?' Esa es una pregunta de sí/no, y 'no' es la respuesta por defecto — es más fácil, más seguro, no requiere acción. Cuando ofreces dos opciones, el cerebro hace una pregunta diferente: '¿Cuál debería elegir?' La decisión de comprar se da por sentada. Ahora solo están eligiendo entre A y B. Este simple reencuadre aumenta drásticamente la conversión."},{type:"keypoint",text:"A single offer invites rejection. Two offers invite comparison. Comparison assumes purchase. The psychology is subtle but profound — and it works on virtually every human decision.",textEs:"Una sola oferta invita al rechazo. Dos ofertas invitan a la comparación. La comparación asume compra. La psicología es sutil pero profunda — y funciona en prácticamente toda decisión humana."},{type:"divider"},{type:"subheader",text:"The Psychology: 'Which One' vs. 'Yes or No'",textEs:"La Psicología: '¿Cuál?' vs. '¿Sí o No?'"},{type:"paragraph",text:"Ask somebody if they want it and they can just say no, because no is free. Ask them which one they want and they are already picking. You never put 'do you buy' in the air. You put 'the single or the double' in the air, and let them answer the easy one.",textEs:"Pregúntale a alguien si lo quiere y te puede decir que no sin más, porque el no sale gratis. Pregúntale cuál quiere y ya está eligiendo. Nunca pones en el aire '¿lo compras?'. Pones en el aire '¿la individual o la doble?', y les dejas contestar a la fácil."},{type:"script",text:"Single option: 'The syringe is {currency}210.' Customer thinks: '{currency}210? That's a lot. I don't know if I need this. No thanks.' Two options: 'You can take the single syringe for {currency}210 with a gift, or the double for {currency}300 and treat your forehead and upper lip too. Which works better for you?' Customer thinks: 'Hmm, do I want the single or double? The double makes more sense...' See the difference? They went from 'Should I buy?' to 'Which one?'",textEs:"Opción única: 'La jeringa cuesta {currency}210.' El cliente piensa: '¿{currency}210? Eso es mucho. No sé si necesito esto. No, gracias.' Dos opciones: 'Puedes llevarte la jeringa individual por {currency}210 con un regalo, o la doble por {currency}300 y tratar tu frente y labio superior también. ¿Cuál te funciona mejor?' El cliente piensa: 'Hmm, ¿quiero la individual o la doble? La doble tiene más sentido...' ¿Ves la diferencia? Pasaron de '¿Debería comprar?' a '¿Cuál?'"},{type:"divider"},{type:"subheader",text:"Option Structure: How to Build Your Two Choices",textEs:"Estructura de Opciones: Cómo Construir tus Dos Opciones"},{type:"paragraph",text:"Not any two options work. The structure matters. Here's how to build effective choices:",textEs:"No cualquier par de opciones funciona. La estructura importa. Así es como construir opciones efectivas:"},{type:"numbered",items:["OPTION 1 — THE VALUE CHOICE: Lower price point with a smaller gift or no gift. Example: Syringe at {currency}210 + one gift. This is the cheaper of your two OPENING options — it is not the answer to a small budget. That answer lives further down the ladder.","OPTION 2 — THE FULL CHOICE: Standard or higher price with a bigger gift or added value. This captures buyers who want the complete experience. Example: Syringe at {currency}300 + second syringe free.","THE CONTRAST: The gap between options should be clear but not extreme. {currency}210 vs {currency}300 is a meaningful difference. Do not put {currency}210 next to {currency}175 — that is the next rung down, and a rung is something you walk to with a reason, never a second item on a menu.","THE DEFAULT: If you sense hesitation, guide them toward Option 1: 'Most people start with Option 1 — it's a great entry point.' This simplifies their decision."],itemsEs:["OPCIÓN 1 — LA OPCIÓN DE VALOR: Precio más bajo con un regalo más pequeño o sin regalo. Ejemplo: Jeringa en {currency}210 + un regalo. Esta es la más barata de tus dos opciones DE SALIDA — no es la respuesta a un presupuesto justo. Esa respuesta está más abajo en la escalera.","OPCIÓN 2 — LA OPCIÓN COMPLETA: Precio estándar o más alto con un regalo más grande o valor añadido. Esto capta a quien quiere la experiencia completa. Ejemplo: Jeringa en {currency}300 + segunda jeringa gratis.","EL CONTRASTE: La diferencia entre opciones debe ser clara pero no extrema. {currency}210 frente a {currency}300 es una diferencia que se nota. No pongas {currency}210 al lado de {currency}175 — ese es el escalón siguiente, y a un escalón se baja con un motivo, nunca es el segundo plato de una carta.","LA OPCIÓN POR DEFECTO: Si sientes hesitación, guíalos hacia la Opción 1: 'La mayoría empieza con la Opción 1 — es un excelente punto de entrada.' Esto simplifica su decisión."]},{type:"divider"},{type:"subheader",text:"Two-Choice Examples by Product",textEs:"Ejemplos de Dos Opciones por Producto"},{type:"bullets",items:["SYRINGE: Option 1 — {currency}210 (single syringe + gift). Option 2 — {currency}300 (two syringes + Day & Night Cream free). One is entry-level value; the other is the complete experience.","PEELING: Option 1 — {currency}100 (single peeling + Dead Sea Scrub gift). Option 2 — {currency}150 (peeling + Day & Night Cream free). Budget-conscious vs. skincare routine builders.","SCRUB & BUTTER: Option 1 — {currency}60 (Buy 1 Get 1 — Scrub + Body Butter). Option 2 — {currency}120 (Buy 2 Get 1 — trio with Nail Kit or Cleanser). Casual buyer vs. serious self-care or gift shopper.","NAIL KIT: Option 1 — {currency}60 (Buy 1 Get 1 — mix with Scrub or Butter). Option 2 — {currency}120 (Buy 2 Get 1 — three full kits for gifting)."],itemsEs:["JERINGA: Opción 1 — {currency}210 (jeringa individual + regalo). Opción 2 — {currency}300 (dos jeringas + Crema Día y Noche gratis). Una es valor de entrada; la otra es la experiencia completa.","PEELING: Opción 1 — {currency}100 (peeling individual + Exfoliante del Mar Muerto de regalo). Opción 2 — {currency}150 (peeling + Crema Día y Noche gratis). Conscientes del presupuesto vs. constructores de rutina de cuidado de la piel.","EXFOLIANTE & MANTEQUILLA: Opción 1 — {currency}60 (Compra 1 Lleva 1 — Exfoliante + Mantequilla Corporal). Opción 2 — {currency}120 (Compra 2 Lleva 1 — trío con Kit de Uñas o Limpiador). Comprador casual vs. cuidado personal serio o comprador de regalos.","KIT DE UÑAS: Opción 1 — {currency}60 (Compra 1 Lleva 1 — mezcla con Exfoliante o Mantequilla). Opción 2 — {currency}120 (Compra 2 Lleva 1 — tres kits completos para regalo)."]},{type:"divider"},{type:"subheader",text:"The Decoy Effect (Advanced)",textEs:"El Efecto Señuelo (Avanzado)"},{type:"paragraph",text:"A more advanced technique involves adding a third option that's designed to make one of the two main options more attractive:",textEs:"Una técnica más avanzada implica agregar una tercera opción diseñada para hacer una de las dos opciones principales más atractiva:"},{type:"script",text:"'We have three options. A single Scrub on its own is {currency}60. The Scrub + Body Butter duo is also {currency}60 — Buy 1, Get 1. Or the full trio with the Nail Kit is {currency}120.' The single at {currency}60 makes the duo look unmissable. The {currency}120 trio then makes the {currency}60 duo look like a smart, budget-friendly choice. Most people pick the middle — which is exactly what you want.",textEs:"'Tenemos tres opciones. Un Exfoliante solo cuesta {currency}60. El dúo de Exfoliante + Body Butter también son {currency}60 — Compra 1, Lleva 1. O el trío completo con el Kit de Uñas son {currency}120.' El individual a {currency}60 hace que el dúo parezca imperdible. Luego el trío de {currency}120 hace que el dúo de {currency}60 parezca una elección inteligente y ajustada al presupuesto. La mayoría elige la del medio — que es exactamente lo que quieres."},{type:"tip",text:"The two-choice framework only works when BOTH options are genuinely good values. If Option 1 is a terrible deal designed to push people to Option 2, customers sense the manipulation. Make both options attractive, just for different types of buyers.",textEs:"El marco de dos opciones solo funciona cuando AMBAS opciones son genuinamente buenas ofertas. Si la Opción 1 es un mal trato diseñado para empujar a la gente a la Opción 2, los clientes sienten la manipulación. Haz ambas opciones atractivas, solo para diferentes tipos de compradores."},{type:"divider"},{type:"subheader",text:"When Two Choices Become One",textEs:"Cuando Dos Opciones Se Convierten en Una"},{type:"paragraph",text:"Sometimes the customer's situation clearly points to one option. When this happens, guide them to it rather than forcing a comparison that doesn't make sense:",textEs:"A veces la situación del cliente apunta claramente a una opción. Cuando esto pasa, guíalos hacia ella en lugar de forzar una comparación que no tiene sentido:"},{type:"bullets",items:['CLEAR BUDGET CONSTRAINT: She has told you money is tight. Do not read that as "show her Option 1" — {currency}210 is your second opening offer, not a budget answer and it will not touch her. It means this conversation is going to finish around {currency}140, maybe {currency}100. Present the two options anyway, because that is the method, then walk the ladder properly: she asks, you pause, you give a reason, you move one rung. Nobody gets shown the door for having a small budget.',"CLEAR GIFT SHOPPER: If they're buying for three sisters, Option 2 (Buy 2 Get 1) is obvious. Don't overcomplicate.","CLEAR PREMIUM BUYER: If they are carrying luxury bags and do not blink at the number, lead with Option 2 and stay at the top of the ladder. Somebody who came out to spend does not need a discount — and once the syringe is sold you hand her to the specialist, you do not go reaching for something else off your own tray.","UNCERTAIN BUYER: When they are genuinely unsure, default to Option 1. It is easier to say yes to, and she can still move up while she is sitting in front of you."],itemsEs:['PRESUPUESTO JUSTO Y CLARO: Te ha dicho que el dinero va contado. No lo leas como "enséñale la Opción 1" — {currency}210 es tu segunda oferta de salida, no la respuesta a un presupuesto ajustado y a ella no la toca. Significa que esta conversación va a terminar por {currency}140, quizá por {currency}100. Preséntale las dos opciones igualmente, porque ese es el método, y luego baja la escalera como toca: ella pide, tú haces una pausa, das un motivo y bajas un escalón. A nadie se le enseña la puerta por tener poco presupuesto.',"COMPRADOR DE REGALOS CLARO: Si están comprando para tres hermanas, la Opción 2 (Compra 2 Lleva 1) es obvia. No la compliques.","COMPRADOR PREMIUM CLARO: Si vienen cargados de bolsas de lujo y no pestañean con el número, empieza por la Opción 2 y quédate arriba en la escalera. Quien ha salido a gastar no necesita un descuento — y una vez vendida la jeringa se la pasas al especialista, no vas a por otra cosa de tu propia bandeja.","COMPRADOR INCIERTO: Cuando de verdad no lo tengan claro, tira de la Opción 1 por defecto. Es más fácil decirle que sí, y todavía puede subir mientras la tienes delante."]},{type:"quote",text:"Give them one option and they decide whether to buy. Give them two options and they decide which to buy. That's the difference between a conversation and a close.",textEs:"Dales una opción y deciden si comprar. Dales dos opciones y deciden cuál comprar. Esa es la diferencia entre una conversación y un cierre.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What cognitive shift happens when you offer two options instead of one?",options:["The customer thinks the prices are too high","The customer shifts from 'Should I buy?' to 'Which one should I choose?'","The customer gets confused","The customer always picks the cheaper option"],correctIndex:1,explanation:"Two options change the mental frame from a yes/no purchase decision (where 'no' is the default) to a comparison between options (where buying is assumed and they're just picking which one)."},{question:"What is the decoy effect?",options:["A technique where you trick the customer","Adding a third option designed to make one of the main options more attractive","Giving away free products","Only showing the expensive option first"],correctIndex:1,explanation:"The decoy effect involves adding an option that exists only to flatter another one. A single Scrub at {currency}60 makes the Buy 1 Get 1 duo — also {currency}60 — look unmissable, and that in turn makes the {currency}120 trio feel like the real value. Most customers pick the middle option."},{question:"What should you do when a customer clearly has budget constraints?",options:["Still present both options equally","Immediately pivot to the lower-priced option","Insist on the premium option","End the conversation"],correctIndex:1,explanation:"When budget constraints are clear, immediately pivot to the lower-priced option. Forcing a comparison that doesn't make sense for their situation creates awkwardness and can lose the sale entirely."}]},"prod-3":{id:"prod-3",categoryId:"products",title:"Adaptive Pricing Mastery",titleEs:"Dominio de Precios Adaptativo",subtitle:"Reading body language for price comfort, the gradual descent technique, and never going below minimum",subtitleEs:"Lee al cliente, ajusta el precio",duration:"10 min",icon:"TrendingUp",order:3,xpReward:150,sections:[{type:"header",text:"The Best Closers Read the Room and Adjust in Real Time",textEs:"Los Mejores Cerradores Leen el Ambiente y se Adaptan en Tiempo Real"},{type:"paragraph",text:"Presenting the offer isn't the end — it's the beginning of the close. Adaptive pricing is the art of reading the customer's reaction to your price and adjusting the offer on the fly. This is what separates good sellers from great ones. Anyone can memorize a script. Only masters can feel the room and adapt.",textEs:"Presentar la oferta no es el final — es el principio del cierre. Los precios adaptativos son el arte de leer la reacción del cliente a tu precio y ajustar la oferta sobre la marcha. Esto es lo que separa a los buenos vendedores de los grandes. Cualquiera puede memorizar un guion. Solo los maestros pueden sentir el ambiente y adaptarse."},{type:"keypoint",text:'The gradual descent: start high, wait to be ASKED, then remove a gift and come down one rung with a reason attached — and NEVER below your floor. Two things sellers get wrong here. They move on a facial expression instead of a question, which hands over money nobody asked for. And they answer "I am on a budget" as if it arrived at the top of the ladder. It never does. By the time anyone says that out loud you have already come down, so you are not defending {currency}300 — you are fighting for {currency}140, and sometimes for {currency}100.',textEs:'El descenso gradual: empieza arriba, espera a que te lo PIDAN, y entonces quita un regalo y baja un escalón con un motivo detrás — y NUNCA por debajo de tu mínimo. Aquí hay dos cosas que se hacen mal. Bajar por una cara en vez de por una pregunta, que es regalar dinero que nadie te ha pedido. Y contestar al "voy justa de dinero" como si eso llegara arriba de la escalera. No llega nunca. Cuando alguien dice eso en voz alta ya has bajado, así que no estás defendiendo {currency}300 — estás peleando por {currency}140, y a veces por {currency}100.'},{type:"divider"},{type:"subheader",text:"Reading Body Language for Price Comfort",textEs:"Leyendo el Lenguaje Corporal para Medir Confort con el Precio"},{type:"paragraph",text:"The moment you state the price, watch their body. It tells you everything:",textEs:"En el momento que digas el precio, observa su cuerpo. Te lo dice todo:"},{type:"bullets",items:["COMFORT SIGNAL: Brief nod, relaxed shoulders, slight smile, maintaining eye contact. They can afford it. Move to close.","SHOCK SIGNAL: Eyes widen, sharp breath intake, head pulls back slightly. The price is higher than expected. You need to reframe value or prepare to descale.","HIDDEN SHOCK: They maintain composure but glance at their partner, or their smile becomes fixed. They feel pressure to appear comfortable but are actually concerned. Watch for partner reactions.","THE HARD NO SIGNAL: Immediate step back, arms fold, head shake. That is the number, not the product — she has just shown you where the top of her range is. Do not explain the product again and do not apologise. Go down a rung, take something out, give her a reason.","THOUGHTFUL SIGNAL: They look down, touch chin, purse lips. They're calculating. Give them silence and space. This is often a buying signal disguised as hesitation."],itemsEs:["SEÑAL DE CONFORT: Asentimiento breve, hombros relajados, leve sonrisa, manteniendo contacto visual. Pueden pagarlo. Ve al cierre.","SEÑAL DE SORPRESA: Ojos se abren, respiración brusca, cabeza se echa hacia atrás ligeramente. El precio es más alto de lo esperado. Necesitas reencuadrar el valor o prepararte para reducir.","SORPRESA OCULTA: Mantienen la compostura pero miran a su pareja, o su sonrisa se vuelve rígida. Sienten presión por parecer cómodos pero en realidad están preocupados. Observa las reacciones de su pareja.","SEÑAL DE NO ROTUNDO: Paso atrás inmediato, brazos cruzados, negar con la cabeza. Eso es el número, no el producto — acaba de enseñarte dónde está el techo de lo suyo. No le vuelvas a explicar el producto y no pidas perdón. Baja un escalón, quita algo, dale un motivo.","SEÑAL DE REFLEXIÓN: Miran hacia abajo, tocan la barbilla, fruncen los labios. Están calculando. Dale silencio y espacio. Esta suele ser una señal de compra disfrazada de duda."]},{type:"tip",text:"Price reactions happen in the first 2 seconds after you state the number. Train yourself to watch their face during those 2 seconds, not to keep talking. The information you gather determines your next move.",textEs:"Las reacciones al precio ocurren en los primeros 2 segundos después de que dices el número. Entrénate para observar su rostro durante esos 2 segundos, no para seguir hablando. La información que recopiles determinará tu siguiente movimiento."},{type:"divider"},{type:"subheader",text:"The Gradual Descent Technique",textEs:"La Técnica del Descenso Gradual"},{type:"paragraph",text:"This is your pricing staircase. Each step down removes value (gifts) to lower the price. The customer feels like they're getting a deal, not that you were overcharging:",textEs:"Esta es tu escalera de precios. Cada paso hacia abajo remueve valor (regalos) para bajar el precio. El cliente siente que está obteniendo un trato, no que tú estabas cobrando de más:"},{type:"numbered",items:["STEP 1 — FULL OFFER: Present both options at full value. 'Option 1: {currency}210 with a gift. Option 2: {currency}300 with two syringes and creams.' Say it warm, say it flat, then stop talking. This is your ceiling and everybody starts here — including the woman who has already told you money is tight.","STEP 2 — REMOVE THE GIFT, ONCE SHE ASKS: A face is not an ask. Wait until she has actually asked you for a better price, and asked twice. Then pause, look at the box, breathe out like it hurts, and give her a reason: 'Go on then — my last customer only took the one. I'll pull the gift out, that's {currency}35, and do it at {currency}175 for you.' She saves money; you lose a gift, not margin.","STEP 3 — THE VOUCHER CLOSE, {currency}140: This is where the budget conversation actually happens — not up at {currency}300. She has pushed again, so drop your voice, glance at the door, make it a secret: 'Alright, I can do something a bit crazy, just this once. With a voucher, {currency}140. But you're being greedy — and only on the single, not the combo.' There is no real voucher. It is the reason you needed in order to come down, invented on the spot, and it never leaves the shop with her.","STEP 4 — THE FLOOR, {currency}100, AND IT IS NOT YOURS TO GIVE: {currency}140 is the voucher rung and it is the last one you own. Below it you go full market and you CALL A MANAGER — the floor comes from him, not from you. That is not red tape, it is what makes it a floor: a seller who can reach {currency}100 on his own has no floor at all, and she will find that out. While you wait, the arithmetic does more work than the theatre — one syringe, about sixty treatments, a whole year, under {currency}2 a go. Never cross the floor. If she has fought you all the way to {currency}100 and still says no, and you have honestly given it everything, that is the one time you let her go — a last resort, never a plan."],itemsEs:["PASO 1 — OFERTA COMPLETA: Presenta las dos opciones a valor completo. 'Opción 1: {currency}210 con regalo. Opción 2: {currency}300 con dos jeringas y cremas.' Dilo con calor, dilo plano y luego cállate. Este es tu techo y aquí empieza todo el mundo — también la que ya te ha dicho que va justa de dinero.","PASO 2 — QUITA EL REGALO, CUANDO TE LO PIDA: Una cara no es una petición. Espera a que te pida un precio mejor de verdad, y que te lo pida dos veces. Entonces haz una pausa, mira la caja, suelta el aire como si doliera y dale un motivo: 'Venga, va — mi última clienta se llevó solo una. Te quito el regalo, que son {currency}35, y te la dejo en {currency}175.' Ella ahorra dinero; tú pierdes un regalo, no margen.","PASO 3 — EL CIERRE CON CUPÓN, {currency}140: Aquí es donde pasa de verdad la conversación del presupuesto — no arriba en {currency}300. Ha vuelto a empujar, así que baja la voz, mira a la puerta y haz que sea un secreto: 'Vale, puedo hacer una cosa un poco loca, solo por esta vez. Con un cupón, {currency}140. Pero estás siendo codiciosa — y solo en la individual, no en el combo.' No existe ningún cupón. Es el motivo que necesitabas para bajar, inventado en el momento, y no sale nunca de la tienda con ella.","PASO 4 — EL SUELO, {currency}100, Y NO ES TUYO PARA DARLO: los {currency}140 son el escalón del cupón y el último que llevas tú. Por debajo vas a mercado total y LLAMAS A UN ENCARGADO — el suelo lo pone él, no tú. Eso no es burocracia, es lo que lo convierte en suelo: un vendedor que llega a {currency}100 él solito no tiene suelo ninguno, y ella se va a enterar. Mientras esperas, las cuentas trabajan más que el teatro — una jeringa, unos sesenta tratamientos, un año entero, menos de {currency}2 cada vez."]},{type:"script",text:"'Option 1 is {currency}210 with the gift. Option 2 is {currency}300 and the second syringe comes with it.' [Now stop talking.] — 'Is that the best you can do?' That is once. Laugh it off: 'Whoa, whoa. I've known you thirty seconds and you're already robbing me.' — She asks again. That is twice, and NOW you move, once, with a reason on it: [pause, look at the box, breathe out] 'Go on then. My last customer only took the one. I'll pull the gift out, that's {currency}35, and do it at {currency}175 for you.' Then stop talking again. One ask, one laugh, one rung.",textEs:"'La Opción 1 son {currency}210 con el regalo. La Opción 2 son {currency}300 y la segunda jeringa va incluida.' [Y ahora te callas.] — '¿Es lo mejor que puedes hacer?' Eso es una. Quítatelo de encima con guasa: 'Eh, eh. Hace treinta segundos que te conozco y ya me estás robando.' — Te lo vuelve a pedir. Eso son dos, y AHORA te mueves, una vez, con un motivo encima: [pausa, mira la caja, suelta el aire] 'Venga, va. Mi última clienta se llevó solo una. Te quito el regalo, que son {currency}35, y te la dejo en {currency}175.' Y te callas otra vez. Una petición, una risa, un escalón."},{type:"script",text:"And when she pushes a third time — this is the one that matters, because this is where the money conversation actually ends. Voice down, quick look at the door, lean in: 'Alright. I can do something a bit crazy, just this once. With a voucher — {currency}140. But you're being greedy, and I can only do it on the single one.' Then hands off the table and let her have it. You are not announcing a discount, you are letting her win something. If she has genuinely fought you past that, {currency}100 is the wall — one syringe, sixty treatments, under {currency}2 a go — and you hand it over like it hurt.",textEs:"Y cuando empuje una tercera vez — esta es la que importa, porque aquí es donde se acaba de verdad la conversación del dinero. Baja la voz, mirada rápida a la puerta, acércate un poco: 'Vale. Puedo hacer una cosa un poco loca, solo por esta vez. Con un cupón — {currency}140. Pero estás siendo codiciosa, y solo te lo puedo hacer en la individual.' Y luego manos fuera de la mesa y déjaselo. No estás anunciando un descuento, le estás dejando ganar algo. Si de verdad te ha peleado más allá de eso, {currency}100 es el muro — una jeringa, sesenta tratamientos, menos de {currency}2 cada vez — y se lo entregas como si te doliera."},{type:"divider"},{type:"subheader",text:"When to Drop the Gift vs. When to Add Value",textEs:"Cuándo Quitar el Regalo vs. Cuándo Agregar Valor"},{type:"paragraph",text:"Sometimes you descale (remove gifts, lower price). Sometimes you upscale (add value, maintain price). Know which to use:",textEs:"A veces reduces (quitas regalos, bajas el precio). A veces aumentas (agregas valor, mantienes el precio). Saber cuál usar:"},{type:"comparison",left:{label:"Descale (Drop Price)",text:'Use when: she has ASKED you for a better price — and asked twice. Not when she pulls a face, not when she goes quiet, not when she looks like she cannot afford it. A face is not an ask, and money you hand over unasked teaches her the numbers move whenever she pushes. Then read what "money is tight" actually means: not that you should jump, but that this one is going to finish at {currency}140 or {currency}100. So go one rung at a time, put a reason on every rung, and keep something in your hand for the next ask.'},leftEs:{label:"Reducir (Bajar Precio)",text:'Úsalo cuando: te haya PEDIDO un precio mejor — y te lo haya pedido dos veces. No cuando pone una cara, no cuando se queda callada, no cuando parece que no puede pagarlo. Una cara no es una petición, y el dinero que sueltas sin que te lo pidan le enseña que los números se mueven cada vez que empuja. Y luego lee lo que significa de verdad "voy justa": no que tengas que saltar, sino que esta acaba en {currency}140 o en {currency}100. Así que baja de escalón en escalón, pon un motivo en cada uno y guárdate algo para la siguiente petición.'},right:{label:"Upscale (Add Value)",text:"Use when: Customer shows no price sensitivity, carries luxury bags, expresses love for the product, is buying gifts for multiple people. Add a cream, add a second syringe, create a bundle. They're willing to spend — help them."},rightEs:{label:"Subir (Añadir Valor)",text:"Úsalo cuando: el cliente no muestra sensibilidad al precio, lleva bolsas de lujo, dice que le encanta el producto, está comprando regalos para varias personas. Añade una crema, añade una segunda jeringa, monta un pack. Están dispuestos a gastar — ayúdales."}},{type:"divider"},{type:"subheader",text:"The Psychology of 'Store Credit' Reframing",textEs:"La Psicología del Reencuadre de 'Crédito de Tienda'"},{type:"paragraph",text:"One of the most effective techniques is reframing a removed gift as 'store credit.' Instead of saying 'I'll remove the Scrub,' say 'I'll take the Scrub out and put its value straight back to you as store credit to bring your price down.' This feels like you're being creative on their behalf, not just removing value.",textEs:"Una de las técnicas más efectivas es reencuadrar un regalo removido como 'crédito de tienda.' En lugar de decir 'Quito el Exfoliante,' di 'Saco el Exfoliante y te devuelvo su valor como crédito de tienda para bajar tu precio.' Esto se siente como si estuvieras siendo creativo en su beneficio, no solo removiendo valor."},{type:"script",text:"That is the peeling coming off its {currency}100 offer, where the Scrub rides along as the gift: 'Listen, I know, I know. Let me make it easy — I'll take the Scrub out and put its value straight back to you as credit. That brings it to {currency}70 for you.' The word 'credit' makes them feel clever for saving. Not skint for hesitating. One rung, and only after they have asked.",textEs:"Eso es el peeling bajando de su oferta de {currency}100, donde el Exfoliante va incluido como regalo: 'Mira, ya lo sé, ya lo sé. Deja que te lo ponga fácil — te saco el Exfoliante y te devuelvo su valor como crédito. Eso te lo deja en {currency}70.' La palabra 'crédito' les hace sentirse listos por ahorrar. No pobres por dudar. Un escalón, y solo después de que lo hayan pedido."},{type:"divider"},{type:"subheader",text:"The Wall",textEs:"El Muro"},{type:"paragraph",text:"Your floor is the wall. Below it you are working for free, and they can smell it on you. Here is why it matters:",textEs:"Tu mínimo es el muro. Por debajo de ahí estás trabajando gratis, y se te nota. Por esto importa:"},{type:"bullets",items:["MARGIN PROTECTION: Going below minimum destroys profitability. You didn't set the floor randomly — it protects the business.","VALUE PERCEPTION: Desperate discounting tells the customer (and yourself) that the product wasn't worth the original price. Protect the product's value.","PRECEDENT: If you go below minimum once, the customer tells friends. Word spreads. The floor becomes the ceiling.","YOUR COMMISSION: Every euro below minimum comes out of your potential earnings. Respect your own paycheck."],itemsEs:["PROTECCIÓN DE MARGEN: Bajar del mínimo destruye la rentabilidad. No pusiste el piso al azar — protege el negocio.","PERCEPCIÓN DE VALOR: Los descuentos desesperados le dicen al cliente (y a ti mismo) que el producto no valía el precio original. Protege el valor del producto.","PRECEDENTE: Si bajas del mínimo una vez, el cliente se lo cuenta a sus amigos. Se corre la voz. El piso se convierte en el techo.","TU COMISIÓN: Cada euro bajo el mínimo sale de tus ganancias potenciales. Respeta tu propio salario."]},{type:"tip",text:"Know your minimums by heart: Syringe {currency}100 (absolute floor — {currency}140 is the voucher close, one rung above it), Peeling {currency}50, Scrub {currency}30 (single), Nail Kit {currency}30 (single). That is the wall. Learn to say no with a smile instead of an apology: 'You are killing me. Honestly, at that price I am paying for the privilege — this is where I stop.' Say it once, laugh, and go quiet. The silence does the rest.",textEs:"Aprende de memoria tus mínimos: Jeringa {currency}100 (mínimo absoluto — {currency}140 es el cierre con cupón, un escalón por encima), Peeling {currency}50, Exfoliante {currency}30 (individual), Kit de Uñas {currency}30 (individual). Ese es el muro. Aprende a decir que no con una sonrisa, no pidiendo perdón: 'Me estás matando. De verdad, a ese precio pago yo por trabajar — aquí es donde me planto.' Dilo una vez, ríete y cállate. El silencio hace el resto."},{type:"quote",text:"Adaptive pricing isn't about being cheap. It's about being flexible within your boundaries. The customer who respects your floor price is the customer who values what you sell.",textEs:"Los precios adaptativos no se tratan de ser barato. Se trata de ser flexible dentro de tus límites. El cliente que respeta tu precio mínimo es el cliente que valora lo que vendes.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What is the gradual descent technique?",options:["Randomly lowering the price until they agree","A structured staircase where each step removes gifts to lower the price while maintaining value perception","Starting with the lowest price and going up","Matching the customer's first offer"],correctIndex:1,explanation:"The gradual descent is a structured approach: present full offer, then remove gift (Step 2), then voucher close (Step 3), each feeling like a personalized solution rather than desperate discounting."},{question:"What does 'store credit' reframing accomplish?",options:["It tricks the customer into paying more","It makes the customer feel smart for saving rather than poor for hesitating","It adds actual store credit to their account","It confuses the customer"],correctIndex:1,explanation:"Reframing a removed gift as 'store credit' (e.g., 'let me take the Scrub out and give you its value back as credit') makes the price reduction feel like a creative solution on their behalf, not just removing value."},{question:"Why should you never go below your minimum floor price?",options:["Because the manager will be angry","It protects margins, value perception, and your commission — and sets a dangerous precedent if broken","Because customers will always demand it","Because the products are too expensive"],correctIndex:1,explanation:"Going below minimum destroys profitability, devalues the product in customers' eyes, sets a bad precedent, and reduces your commission. The floor exists for good business reasons."}]},"prod-4":{id:"prod-4",categoryId:"products",title:"The Voucher Close",titleEs:"El Cierre con Voucher",subtitle:"Psychological breakdown of why it works — scarcity, exclusivity, and reciprocity combined",subtitleEs:"Usa vouchers para cerrar rápido",duration:"8 min",icon:"Ticket",order:4,xpReward:100,sections:[{type:"header",text:"Your Final Weapon, Used Wisely",textEs:"Tu Arma Final, Usada con Sabiduría"},{type:"paragraph",text:"The voucher close is the ace up your sleeve. When the customer loves the product, appreciates the value, but just can't quite pull the trigger — the voucher close provides the gentle nudge. Done right, it feels like an insider secret. Done wrong, it feels like a cheap trick. Master the psychology and the delivery.",textEs:"El cierre con voucher es el as en la manga. Cuando el cliente ama el producto, aprecia el valor, pero simplemente no logra dar el paso — el cierre con voucher proporciona el empujoncito gentil. Bien hecho, se siente como un secreto de iniciados. Mal hecho, se siente como un truco barato. Domina la psicología y la entrega."},{type:"keypoint",text:"The voucher close combines three psychological principles simultaneously: scarcity (one-time only), exclusivity (just for you), and reciprocity (I'm doing you a favor — you should commit). This triple-whammy is why it's so effective.",textEs:"El cierre con voucher combina tres principios psicológicos simultáneamente: escasez (solo una vez), exclusividad (solo para ti), y reciprocidad (te estoy haciendo un favor — tú deberías comprometerte). Este triple golpe es por lo que es tan efectivo."},{type:"divider"},{type:"subheader",text:"Why the Voucher Close Works: The Psychology",textEs:"Por Qué Funciona el Cierre con Voucher: La Psicología"},{type:"paragraph",text:"Let's break down exactly what's happening in the customer's mind during a voucher close:",textEs:"Analicemos exactamente qué está pasando en la mente del cliente durante un cierre con voucher:"},{type:"bullets",items:["SCARCITY: 'This is a one-time thing.' The customer knows the opportunity won't come again. Loss aversion kicks in — the pain of missing out feels worse than the pain of spending.","EXCLUSIVITY: 'Just for you.' The customer feels special, not sold to. They're receiving insider treatment. This creates a personal bond — they don't want to disappoint you after you 'went to bat' for them.","RECIPROCITY: You've just done them a favor by finding a special price. Human psychology compels them to reciprocate — by saying yes. The 'two promises' at the end activate this reciprocity explicitly.","AUTHORITY: 'I just checked' implies you have the power to make this happen. You're not just a salesperson — you're a decision-maker who chose to help them.","COMMITMENT: 'Promise me you'll actually use it' creates a verbal commitment. Once someone promises something, they're more likely to follow through."],itemsEs:["ESCASEZ: 'Esto es de una sola vez.' El cliente sabe que la oportunidad no volverá. La aversión a la pérdida entra en acción — el dolor de perderse algo se siente peor que el dolor de gastar.","EXCLUSIVIDAD: 'Solo para ti.' El cliente se siente especial, no vendido. Están recibiendo trato de iniciado. Esto crea un vínculo personal — no quieren decepcionarte después de que 'pusiste el pecho' por ellos.","RECIPROCIDAD: Acabas de hacerles un favor al encontrar un precio especial. La psicología humana los obliga a reciprocar — diciendo que sí. Las 'dos promesas' al final activan esta reciprocidad explícitamente.","AUTORIDAD: 'Acabo de revisar' implica que tienes el poder de hacer esto posible. No eres solo un vendedor — eres un tomador de decisiones que eligió ayudarlos.","COMPROMISO: 'Prométeme que realmente lo usarás' crea un compromiso verbal. Una vez que alguien promete algo, es más probable que lo cumpla."]},{type:"divider"},{type:"subheader",text:"The Exact Script and Delivery",textEs:"El Guión Exacto y la Entrega"},{type:"paragraph",text:"Delivery is everything. The words are only half the formula. Here's how to deliver the voucher close:",textEs:"La entrega lo es todo. Las palabras son solo la mitad de la fórmula. Así es cómo entregar el cierre con voucher:"},{type:"numbered",items:["STEP 1 — DROP YOUR VOICE: Lower your volume slightly. This signals that what you're about to say is exclusive, maybe even a little secretive. Loud announcements feel public and therefore less special.","STEP 2 — THE SETUP: 'Alright, alright... listen, I just checked something, and I can do a small crazy offer for you. But you can't be greedy, okay?' This frames the offer as something YOU'RE doing for THEM, not a standard discount.","STEP 3 — THE LIMITATION: 'I can't do this on the big option — only on the single one.' Limitations increase perceived value. If you could do it on everything, it's not special. Limiting it makes it feel real.","STEP 4 — THE PRICE: 'So remember I told you without the gift it's {currency}175? If you use this small 20% discount voucher, it brings it down to {currency}140. But this is a one-time thing — next time, it goes back to normal.'","STEP 5 — THE TWO PROMISES: 'You just promise me two things, okay? One: you'll actually use it. Two: if you're happy, you'll tell your friends about us.' This creates commitment and plants a referral seed.","STEP 6 — THE WHATSAPP BRIDGE: 'You use WhatsApp, right? Perfect. You'll have my number and email — just let me know if you need anything.' Transforms transaction into relationship."],itemsEs:["PASO 1 — BAJA LA VOZ: Baja ligeramente tu volumen. Esto señala que lo que estás a punto de decir es exclusivo, tal vez incluso un poco secreto. Los anuncios en voz alta se sienten públicos y por tanto menos especiales.","PASO 2 — LA PREPARACIÓN: 'Está bien, está bien... escucha, acabo de revisar algo, y puedo hacer una pequeña oferta loca para ti. Pero no puedes ser codicioso, ¿vale?' Esto enmarca la oferta como algo que TÚ estás haciendo por ELLOS, no como un descuento estándar.","PASO 3 — LA LIMITACIÓN: 'No puedo hacer esto en la opción grande — solo en la individual.' Las limitaciones aumentan el valor percibido. Si pudieras hacerlo en todo, no sería especial. Limitarlo lo hace sentir real.","PASO 4 — EL PRECIO: 'Entonces recuerda que te dije que sin el regalo es {currency}175? Si usas este pequeño voucher de descuento del 20%, lo baja a {currency}140. Pero esto es de una sola vez — la próxima vez, vuelve a lo normal.'","PASO 5 — LAS DOS PROMESAS: 'Solo me prometes dos cosas, ¿vale? Una: que realmente lo usarás. Dos: si estás feliz, le contarás a tus amigos sobre nosotros.' Esto crea compromiso y siembra una semilla de referido.","PASO 6 — EL PUENTE DE WHATSAPP: '¿Usas WhatsApp, verdad? Perfecto. Tendrás mi número y email — solo avísame si necesitas algo.' Transforma la transacción en relación."]},{type:"script",text:"'Alright, alright... listen, I just checked, and I can do something a little crazy for you. But you can't be greedy, okay? I can't do this on the double syringe, only on the single one. So remember I told you it's {currency}175 without the gift? If you use this small 20% voucher, I can bring it down to {currency}140. But this is a one-time thing — next time, it goes back to normal. You just promise me two things: you'll actually use it, and if you love it, you'll tell your friends. Deal?'",textEs:"'Está bien, está bien... escucha, acabo de revisar, y puedo hacer algo un poco loco para ti. Pero no puedes ser codicioso, ¿vale? No puedo hacer esto en la jeringa doble, solo en la individual. Entonces recuerda que te dije que es {currency}175 sin el regalo? Si usas este pequeño voucher del 20%, puedo dejarlo en {currency}140. Pero esto es de una sola vez — la próxima vez, vuelve a lo normal. Solo me prometes dos cosas: que realmente lo usarás, y si te encanta, le contarás a tus amigos. ¿Trato?'"},{type:"divider"},{type:"subheader",text:"Script Variations for Different Situations",textEs:"Variaciones del Guión para Diferentes Situaciones"},{type:"bullets",items:["THE FRIENDLY VERSION: 'Okay, I'm going to do something I probably shouldn't... but you seem so lovely, and I really want you to have this. Just don't tell my boss!' Playful, conspiratorial.","THE STRAIGHT VERSION: 'Alright, let me check something... right. I have got one voucher left and it only works on the single. That takes it to {currency}140. That is the number, I cannot do better than that.' For the one who does not want the wink.","THE URGENT VERSION: 'I only have one voucher left today, and honestly, I've been saving it for someone who really appreciates the product. That's you. {currency}140, just this once.' Scarcity + personalization.","THE RELATIONSHIP VERSION: 'I want you to be a happy customer who comes back. So here's what I'll do — {currency}140 on the single one, and you have my WhatsApp for anything you need later.' Long-term focus."],itemsEs:["LA VERSIÓN AMIGABLE: 'Vale, voy a hacer algo que probablemente no debería... pero pareces tan encantador, y realmente quiero que tengas esto. ¡Solo no le digas a mi jefe!' Juguetona, conspirativa.","LA VERSIÓN DIRECTA: 'Vale, déjame mirar una cosa... eso es. Me queda un cupón y solo vale para la individual. Eso la deja en {currency}140. Ese es el número, no te lo puedo dejar mejor.' Para el que no quiere el guiño.","LA VERSIÓN URGENTE: 'Solo me queda un voucher hoy, y honestamente, lo he estado guardando para alguien que realmente aprecie el producto. Ese eres tú. {currency}140, solo esta vez.' Escasez + personalización.","LA VERSIÓN DE RELACIÓN: 'Quiero que seas un cliente contento que vuelva. Así que esto es lo que haré — {currency}140 en la individual, y tendrás mi WhatsApp para cualquier cosa que necesites después.' Enfoque a largo plazo."]},{type:"divider"},{type:"subheader",text:"When to Use the Voucher Close vs. When It Hurts",textEs:"Cuándo Usar el Cierre con Voucher vs. Cuándo Perjudica"},{type:"comparison",left:{label:"Use the Voucher Close",text:"Customer loves the product but hesitates on price. They've seen the demo, they're engaged, but need a final nudge. They say 'I need to think about it.' You sense genuine interest held back by budget."},leftEs:{label:"Usa el Cierre con Voucher",text:"El cliente ama el producto pero duda con el precio. Han visto la demostración, están comprometidos, pero necesitan un empujón final. Dicen 'Necesito pensarlo.' Sientes interés genuino frenado por el presupuesto."},right:{label:"Don't Use the Voucher Close",text:"Customer shows no interest in the product. They haven't engaged with the demo. Price isn't the issue — the product is. Using the voucher close here devalues the product for no reason. Save it for the right moment."},rightEs:{label:"No Uses el Cierre del Cupón",text:"El cliente no muestra ningún interés en el producto. No ha entrado en la demo. El problema no es el precio — es el producto. Usar aquí el cierre del cupón devalúa el producto sin ningún motivo. Guárdalo para el momento adecuado."}},{type:"tip",text:"The voucher close loses power if overused. If you offer it to every single customer, it becomes your default price, not a special deal. Use it selectively — on customers who genuinely need that final push, not as your opening offer.",textEs:"El cierre con voucher pierde poder si se usa en exceso. Si se lo ofreces a cada cliente, se convierte en tu precio por defecto, no en una oferta especial. Úsalo selectivamente — en clientes que genuinamente necesitan ese empujón final, no como tu oferta inicial."},{type:"quote",text:"The voucher close isn't a discount. It's a key to a locked door. The customer is already inside the room, looking at what they want. You're just handing them the key to take it home.",textEs:"El cierre con voucher no es un descuento. Es una llave para una puerta cerrada. El cliente ya está dentro del cuarto, mirando lo que quiere. Solo le estás entregando la llave para llevárselo a casa.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Which three psychological principles does the voucher close combine?",options:["Fear, guilt, and shame","Scarcity, exclusivity, and reciprocity","Love, hope, and charity","Pride, envy, and greed"],correctIndex:1,explanation:"The voucher close combines scarcity (one-time only), exclusivity (just for you), and reciprocity (I'm doing you a favor — you should commit). This triple combination is why it's so effective."},{question:"Why should you drop your voice during the voucher close?",options:["To intimidate the customer","To signal that what you're saying is exclusive and secretive, making it feel more special","Because you're whispering a secret","To save your voice"],correctIndex:1,explanation:"Lowering your volume signals exclusivity and confidentiality. It makes the offer feel like an insider secret rather than a public announcement, increasing its perceived value and personal nature."},{question:"When should you NOT use the voucher close?",options:["When the customer genuinely loves the product but hesitates on price","When the customer shows no interest in the product — it devalues the product unnecessarily","When the customer asks for a discount","When it's the end of your shift"],correctIndex:1,explanation:"The voucher close should only be used when the customer genuinely loves the product but needs a final nudge. Using it on uninterested customers devalues the product and wastes your most powerful closing tool."}]},"prod-5":{id:"prod-5",categoryId:"products",title:"The Handover",titleEs:"El Traspaso",subtitle:"She bought the syringe. Your job is finished — now you pass her to the specialist",subtitleEs:"Ha comprado la jeringa. Tu trabajo se acaba ahí — ahora se la pasas al especialista",duration:"6 min",icon:"Users",order:5,xpReward:100,sections:[{type:"header",text:"Your Job Ends at the Syringe",textEs:"Tu Trabajo se Acaba en la Jeringa"},{type:"paragraph",text:"She has paid for the syringe. Somewhere in your head there is a voice saying go on then, sell her the scrub as well. Kill that voice. The syringe WAS the job and the job is done, and the next thing that happens to this woman is not another pot out of your tray — it is a different person, selling something you do not sell.",textEs:"Ha pagado la jeringa. En algún sitio de tu cabeza hay una voz que dice venga, véndele también el exfoliante. Mata esa voz. La jeringa ERA el trabajo y el trabajo está hecho, y lo siguiente que le pasa a esta mujer no es otro bote de tu bandeja — es otra persona, vendiendo algo que tú no vendes."},{type:"keypoint",text:"An upsell in this shop is not you pitching a second product. It is a handover. If they sold a syringe, the whole point is to pass it to an upseller — and selling the syringe is the win. That is what your shift is counted in. What comes after it belongs to somebody else.",textEs:"Una venta adicional en esta tienda no eres tú soltando un segundo producto. Es un traspaso. Si has vendido una jeringa, la gracia es pasársela al que hace la venta adicional — y vender la jeringa es la victoria. Eso es lo que cuenta en tu turno. Lo que viene después es de otro."},{type:"divider"},{type:"subheader",text:"What the Specialist Sells",textEs:"Lo Que Vende el Especialista"},{type:"paragraph",text:"Red and infrared LED devices. It is the alternative to a facelift: it gets the body making its own collagen and elastin, and it lifts the face. That is the whole of what you need to know and the whole of what you ever say about it — you are not the one selling it, and a half-remembered version out of your mouth makes his job harder, not easier.",textEs:"Aparatos de LED rojo e infrarrojo. Es la alternativa al lifting: hace que el cuerpo produzca su propio colágeno y elastina, y levanta la cara. Eso es todo lo que necesitas saber y todo lo que dices de ello — no eres tú quien lo vende, y una versión a medias saliendo de tu boca le complica el trabajo, no se lo facilita."},{type:"keypoint",text:'And to her he is a specialist, never "the upseller". That is the word for the staff room. In front of a customer he is the one who does this, he is only here for a short while, and you are lucky he has a second.',textEs:'Y para ella es un especialista, nunca "el de la venta adicional". Esa palabra es para la trastienda. Delante de una clienta él es el que hace esto, está aquí poco tiempo, y tienes suerte de que tenga un segundo.'},{type:"tip",text:'You never put a price on it, you never promise a discount on it, and you never start explaining how it works. You are the person who tells her he is worth two minutes. He is the person who sells it. If she asks what it costs: "That is his — he will tell you in one second."',textEs:'Tú no le pones precio, no prometes ningún descuento y no te pones a explicar cómo funciona. Tú eres quien le dice que él merece dos minutos. Él es quien lo vende. Si te pregunta cuánto cuesta: "Eso es suyo — te lo dice él en un segundo."'},{type:"divider"},{type:"subheader",text:"The Handover, Line by Line",textEs:"El Traspaso, Frase por Frase"},{type:"paragraph",text:"Four beats and about thirty seconds, and all of it happens while she is still sitting down and still delighted. Do not stand her up first. A woman on her feet with a bag in her hand is a woman already halfway to the door.",textEs:"Cuatro tiempos y unos treinta segundos, y todo pasa mientras sigue sentada y sigue encantada. No la levantes primero. Una mujer de pie con la bolsa en la mano ya va camino de la puerta."},{type:"numbered",items:["BUILD HIM UP BEFORE SHE MEETS HIM: he is a specialist, he is only with us a short time, and he is amazing at what he does. You are not introducing a colleague — you are telling her she is about to meet somebody people wait for.",`MAKE IT A GIFT, NOT A PITCH: "Just because you got this, I'm going to spoil you with a small gift." She has just spent money. The very next thing out of your mouth should be you giving her something, not asking her for more. And the gift is his two minutes on her face — not something to drop in her bag on the way out.`,'ASK THE QUESTION THAT DOES THE WORK: "What is more important for you, if you could get it lifted? The cheeks? The neck?" Two options and both of them are a yes. Whichever she picks, she has said out loud what she would change about her own face.','THEN GO AND GET HIM: "Would that make you happy? Let me check with him, if you have one second." You walk, you bring him back, he takes it from there. She stays exactly where she is.'],itemsEs:["MÓNTALO ANTES DE QUE LO CONOZCA: es un especialista, está con nosotros poco tiempo y es un crack en lo suyo. No estás presentando a un compañero — le estás diciendo que va a conocer a alguien por el que la gente espera.",'QUE SEA UN REGALO, NO UNA VENTA: "Solo porque te has llevado esto, te voy a mimar con un regalito." Acaba de gastarse el dinero. Lo siguiente que salga de tu boca tiene que ser tú dándole algo, no pidiéndole más. Y el regalo son sus dos minutos en su cara — no algo que meterle en la bolsa al salir.','HAZ LA PREGUNTA QUE TRABAJA SOLA: "¿Qué es más importante para ti, si pudieras levantarlo? ¿Los pómulos? ¿El cuello?" Dos opciones y las dos son un sí. Elija la que elija, ha dicho en voz alta qué se cambiaría de su propia cara.','Y AHORA VE A BUSCARLO: "¿Eso te haría feliz? Déjame consultarlo con él, si tienes un segundo." Andas, lo traes, y él coge el relevo. Ella se queda exactamente donde está.']},{type:"script",text:`"Listen — before you go. There is a guy here, a specialist, he is only with us a short time and honestly, he is amazing at what he does. And just because you got this, I'm going to spoil you with a small gift. Tell me one thing: what is more important for you, if you could get it lifted — the cheeks, or the neck? … Would that make you happy? Let me check with him, if you have one second."`,textEs:'"Escucha — antes de que te vayas. Aquí hay un chico, un especialista, está con nosotros poco tiempo y de verdad, es un crack en lo suyo. Y solo porque te has llevado esto, te voy a mimar con un regalito. Dime una cosa: ¿qué es más importante para ti, si pudieras levantarlo — los pómulos, o el cuello? … ¿Eso te haría feliz? Déjame consultarlo con él, si tienes un segundo."'},{type:"keypoint",text:"Notice that she is never asked whether she wants to meet him. She is asked which part of her own face she would lift. By the time you walk off to fetch him she has already answered a question that only makes sense if she is staying in that chair.",textEs:"Fíjate en que nunca se le pregunta si quiere conocerlo. Se le pregunta qué parte de su cara se levantaría. Para cuando te vas a buscarlo, ya ha contestado a una pregunta que solo tiene sentido si se queda en esa silla."},{type:"divider"},{type:"subheader",text:"What You Do Not Do After a Syringe",textEs:"Lo Que No Haces Después de una Jeringa"},{type:"bullets",items:['DO NOT SELL A SECOND PRODUCT: no scrub, no body butter, no nail kit, no "since you are already having the eyes done". You are not building a basket. You are passing her on.',"DO NOT SEND HER TO HIM: you go and get him. She stays sitting, with the bag in her hand. Anybody who stands up to be walked somewhere can just as easily walk out.","DO NOT PRICE HIS PRODUCT: you have no ladder for it and no permission to invent one. Guess a number and you have either undercut him or frightened her.","DO NOT DO HIS DEMO FOR HIM: two sentences about him and one question. Talk for two minutes about LED and you are doing his job badly, in front of him.","DO NOT LET IT COOL: this happens on top of her mood, in the same breath as the sale. Once she has stood up, straightened her coat and thanked you, the moment has gone."],itemsEs:['NO LE VENDAS UN SEGUNDO PRODUCTO: ni exfoliante, ni manteca corporal, ni kit de uñas, ni "ya que te estás haciendo los ojos". No estás llenando una cesta. La estás pasando.',"NO LA MANDES A ÉL: vas tú a buscarlo. Ella se queda sentada, con la bolsa en la mano. Quien se levanta para que lo lleven a algún sitio también se puede ir por la puerta.","NO LE PONGAS PRECIO A SU PRODUCTO: no tienes escalera para eso ni permiso para inventarte una. Si te sacas un número, o le has bajado el precio a él o la has asustado a ella.","NO LE HAGAS LA DEMO: dos frases sobre él y una pregunta. Ponte dos minutos a hablar de LED y estarás haciendo su trabajo mal, y delante de él.","NO DEJES QUE SE ENFRÍE: esto va encima de su subidón, en el mismo aliento que la venta. Cuando ya se ha levantado, se ha colocado el abrigo y te ha dado las gracias, el momento se ha ido."]},{type:"divider"},{type:"subheader",text:"And Which Product Were You Selling Anyway?",textEs:"¿Y Qué Producto Estabas Vendiendo, en Realidad?"},{type:"paragraph",text:"Half the reason sellers reach for a second product is that nobody ever told them straight which one matters. So, straight: there is a hierarchy, and it is not four equal things on a tray.",textEs:"La mitad de las veces que un vendedor va a por un segundo producto es porque nadie le ha dicho claro cuál importa. Pues claro: hay una jerarquía, y no son cuatro cosas iguales en una bandeja."},{type:"bullets",items:["THE SYRINGE IS THE STAR: it is what we sell, what we focus on, and what a good day is made of. Every stop you make out on that floor is aimed at it.","THE PEELING IS IN BETWEEN: a real sale and a good one, but not the one the shift is measured by.","THE SCRUB, THE BODY BUTTER AND THE NAIL KIT ARE BEGINNER PRODUCTS: they exist so you learn how to sell and so the shop has some nice energy in it. They are not the target. A seller who spends a happy year selling nail kits has spent a year not learning the job."],itemsEs:["LA JERINGA ES LA ESTRELLA: es lo que vendemos, en lo que nos centramos, y de lo que está hecho un buen día. Cada parada que haces ahí fuera apunta a eso.","EL PEELING ESTÁ EN MEDIO: una venta de verdad y una buena venta, pero no es la que mide el turno.","EL EXFOLIANTE, LA MANTECA CORPORAL Y EL KIT DE UÑAS SON PRODUCTOS DE PRINCIPIANTE: están para que aprendas a vender y para que la tienda tenga buen rollo. No son el objetivo. Un vendedor que se pasa un año la mar de contento vendiendo kits de uñas se ha pasado un año sin aprender el oficio."]},{type:"tip",text:"The handover is not a consolation prize for finishing early. It is the most valuable thirty seconds in the shop, because it is the only moment the specialist ever gets with a customer who has already said yes to something once today. Hand her over well and he will want your customers. That is worth having.",textEs:"El traspaso no es un premio de consolación por terminar pronto. Son los treinta segundos más valiosos de la tienda, porque es el único momento en que el especialista pilla a una clienta que ya le ha dicho que sí a algo hoy. Pásasela bien y va a querer a tus clientas. Eso vale mucho."},{type:"quote",text:"Selling the syringe is the win. What happens after it is somebody else's job — and the fastest way to lose both sales is to try to do his as well as yours.",textEs:"Vender la jeringa es la victoria. Lo que pasa después es trabajo de otro — y la forma más rápida de perder las dos ventas es intentar hacer la suya además de la tuya.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"prod-6":{id:"prod-6",categoryId:"products",title:"Product Comparison Guide",titleEs:"Guía de Comparación de Productos",subtitle:"The syringe is the product — this is how you change the way in for each person",subtitleEs:"La jeringa es el producto — esto es cómo cambias la forma de entrar con cada persona",duration:"10 min",icon:"GitCompare",order:6,xpReward:150,sections:[{type:"header",text:"One Product. A Lot of Different Ways In.",textEs:"Un Producto. Muchas Formas Distintas de Entrar."},{type:"paragraph",text:"A 25-year-old travelling on her own and a couple in their fifties on a luxury trip do not get the same words out of you. A French customer who wants to know what is in it does not get the same pitch as a British couple buying Christmas presents. But they all get the same product first. This lesson is not four doors — it is one door and a dozen ways to knock on it.",textEs:"Una chica de 25 años que viaja sola y una pareja de cincuenta y tantos en un viaje de lujo no reciben las mismas palabras de tu boca. Un cliente francés que quiere saber qué lleva dentro no recibe el mismo discurso que una pareja británica comprando regalos de Navidad. Pero todos reciben el mismo producto primero. Esta lección no son cuatro puertas — es una puerta y doce formas de llamar a ella."},{type:"keypoint",text:"The syringe is what we sell and what we focus on. The peeling is in between. The scrub, the body butter and the nail kit are beginner products — they are there so you learn how to sell and so the shop has some nice energy in it. So the question is almost never WHICH product. It is which sentence gets this particular person into the chair for the eyes.",textEs:"La jeringa es lo que vendemos y en lo que nos centramos. El peeling está en medio. El exfoliante, la manteca corporal y el kit de uñas son productos de principiante — están para que aprendas a vender y para que la tienda tenga buen rollo. Así que la pregunta casi nunca es QUÉ producto. Es qué frase sienta a esta persona concreta en la silla para los ojos."},{type:"divider"},{type:"subheader",text:"Which Door You Open On",textEs:"Por Qué Puerta Entras"},{type:"paragraph",text:"Same product every time. What changes is the first sentence:",textEs:"El mismo producto siempre. Lo que cambia es la primera frase:"},{type:"numbered",items:["VISIBLE EYE CONCERNS? (Bags, crow's feet, tired eyes.) Straight at it, warmly. One eye, two minutes, the mirror. The result does the arguing for you and you barely have to talk.","NOTHING OBVIOUS TO FIX? Still the syringe — you just come in somewhere else. 'You look after yourself, I can see it. Let me show you the one thing nobody does.' Nobody needs a problem to want a better face.","YOUNG + GOOD SKIN? Do not sell her a wrinkle she has not got. The angle is the glow and the late night, not the years — and it is still the eyes she sits down for.","LUXURY SIGNALS? (Good watch, good bag, already carrying shopping.) Premium all the way, no discount language in your opener. Somebody who came out to spend does not want to hear about a bargain in the first ten seconds.","SKEPTICAL PARTNER STANDING THERE? You do not change the product, you change who you are talking to. Get him in early — a chair, a hand, a question — before he gets bored. Only if he is genuinely bad energy do you turn fully to her.","BUYING GIFTS? Sell her the eyes first, for herself, while she is in the chair. Gifts are what you talk about after somebody has already said yes to something.","STILL LEARNING, OR THE FLOOR HAS GONE FLAT? That is what the scrub and the nail kit are for. Quick, sensory, easy to say yes to, and the fastest way there is to learn what a yes feels like in your hands."],itemsEs:["¿OJOS VISIBLEMENTE AFECTADOS? (Bolsas, patas de gallo, ojos cansados.) Directo, con buen rollo. Un ojo, dos minutos, el espejo. El resultado discute por ti y casi no tienes ni que hablar.",'¿NADA EVIDENTE QUE ARREGLAR? Igualmente la jeringa — solo entras por otro sitio. "Se nota que te cuidas. Déjame enseñarte lo único que no hace nadie." Nadie necesita un problema para querer una cara mejor.',"¿JOVEN + BUENA PIEL? No le vendas una arruga que no tiene. El ángulo es el brillo y la noche larga, no los años — y sigue sentándose por los ojos.","¿SEÑALES DE LUJO? (Buen reloj, buen bolso, ya viene cargada de bolsas.) Todo premium, y en tu apertura ni una palabra de descuentos. Quien ha salido a gastar no quiere oír hablar de gangas en los primeros diez segundos.","¿PAREJA ESCÉPTICA AHÍ PLANTADA? No cambias de producto, cambias con quién hablas. Métele pronto — una silla, una mano, una pregunta — antes de que se aburra. Solo si de verdad tiene mala energía te giras del todo hacia ella.","¿COMPRANDO REGALOS? Véndele primero los ojos, para ella, mientras está en la silla. De regalos se habla cuando alguien ya ha dicho que sí a algo.","¿TODAVÍA APRENDIENDO, O LA SALA ESTÁ MUERTA? Para eso están el exfoliante y el kit de uñas. Rápidos, sensoriales, fáciles de aceptar, y la forma más rápida que hay de aprender cómo se siente un sí en las manos."]},{type:"divider"},{type:"subheader",text:"Skin Type Matching",textEs:"Emparejamiento por Tipo de Piel"},{type:"paragraph",text:"Different skin types respond to different products. Here's how to match:",textEs:"Diferentes tipos de piel responden a diferentes productos. Así es como emparejarlos:"},{type:"bullets",items:["DRY SKIN: Peeling (removes dead layers, allows better cream absorption) + Scrub (Dead Sea minerals hydrate) + Body Butter (rich moisture). Avoid: nothing — all products work for dry skin.","OILY SKIN: Peeling (weekly deep clean, reduces oil buildup) + Syringe (eye area typically not oily). Scrub is fine in moderation. Body Butter may feel heavy — suggest smaller amounts.","SENSITIVE SKIN: Lead with the gentle approach and go slowly. Emphasize the 'natural, no chemicals' angle. A tiny bit on the inside of the wrist first, and stop at the first sign of anything.","MATURE SKIN (50+): Syringe (collagen stimulation, visible anti-aging) + Peeling (restores glow that diminishes with age) + rich Body Butter. Focus on results and investment in self-care.","YOUNG SKIN (20s): Same syringe, different words — the eyes are the first place a late night shows on anybody, and she can see the difference in the mirror as fast as her mother can. Peeling is the glow story. The nail kit is a lovely easy yes while you are still finding your feet."],itemsEs:["PIEL SECA: Peeling (elimina capas muertas, permite mejor absorción de la crema) + Exfoliante (los minerales del Mar Muerto hidratan) + Crema Corporal (humedad intensa). Evitar: nada — todos los productos funcionan para piel seca.","PIEL GRASA: Peeling (limpieza profunda semanal, reduce acumulación de grasa) + Jeringa (el área de los ojos típicamente no es grasa). El exfoliante está bien con moderación. La crema corporal puede sentirse pesada — sugiere cantidades más pequeñas.",'PIEL SENSIBLE: Empieza con el enfoque suave y ve despacio. Enfatiza el ángulo de "natural, sin químicos". Primero un poquito en la parte de dentro de la muñeca, y a la mínima cosa, lo dejas.',"PIEL MADURA (50+): Jeringa (estimulación de colágeno, anti-edad visible) + Peeling (restaura el brillo que disminuye con la edad) + Crema Corporal rica. Enfócate en resultados e inversión en el cuidado personal.","PIEL JOVEN (20s): La misma jeringa, otras palabras — los ojos son el primer sitio donde se le nota a cualquiera una noche larga, y ella ve la diferencia en el espejo igual de rápido que su madre. El peeling es la historia del brillo. El kit de uñas es un sí fácil y majo mientras te vas soltando."]},{type:"divider"},{type:"subheader",text:"Age-Appropriate Recommendations",textEs:"Recomendaciones Apropiadas por Edad"},{type:"comparison",left:{label:"Younger Customers (20s-30s)",text:"Same syringe, different words. Talk about the glow, the late night, the photograph — not the years, which she does not think she has yet. The eyes still get her into the chair, because the result is instant and she can see it herself. Avoid heavy anti-aging language."},leftEs:{label:"Clientes Jóvenes (20-30s)",text:"La misma jeringa, otras palabras. Háblale del brillo, de la noche larga, de la foto — no de los años, que ella cree que todavía no tiene. Los ojos siguen siendo lo que la sienta, porque el resultado es instantáneo y lo ve ella misma. Evita el lenguaje duro de antiedad."},right:{label:"Mature Customers (40s+)",text:"Straight at it. The visible difference in the mirror, one eye against the other, an investment in herself. She knows her own skin and notices every change, so the demo argues for you — say less and get out of its way."},rightEs:{label:"Clientes Maduras (40+)",text:"Directo. La diferencia visible en el espejo, un ojo contra el otro, una inversión en ella misma. Conoce su piel y nota cada cambio, así que la demo discute por ti — habla menos y quítate de en medio."}},{type:"divider"},{type:"subheader",text:"Tourist Origin → Which Angle",textEs:"Origen del Turista → Qué Ángulo"},{type:"paragraph",text:"Same syringe, same chair, same ladder. What moves is what you put the weight on:",textEs:"La misma jeringa, la misma silla, la misma escalera. Lo que cambia es dónde pones el peso:"},{type:"bullets",items:["SPANISH: the gap. What it costs back home against what it costs here — 'smart shopping in {locationName}' — and a warm, chatty demo while you say it.","FRENCH: substance. What is in it, where it comes from, why it does what it does. Let them ask you everything they want, right there at the table. Hype makes them suspicious.","BRITISH: warmth and a laugh. Big sensory demo, a bit of cheek, and they will do half the selling for you in front of their own friends.","EASTERN EUROPEAN: premium. Best-seller, luxury treatment, and no apologising for the number when you say it.","ASIAN: the result. Get the mirror up early, one eye against the other, and let them look for as long as they want.","GERMAN/DUTCH: practical value. How little you use, how long one syringe lasts, nothing wasted."],itemsEs:['ESPAÑOLES: la diferencia. Lo que cuesta en casa contra lo que cuesta aquí — "compra inteligente en {locationName}" — y una demo cálida y de charla mientras se lo dices.',"FRANCESES: la sustancia. Qué lleva, de dónde viene, por qué hace lo que hace. Deja que te pregunten todo lo que quieran, ahí mismo en la mesa. El bombo les hace desconfiar.","BRITÁNICOS: calidez y risas. Demo sensorial a lo grande, un poco de guasa, y te hacen media venta ellos mismos delante de sus amigos.","EUROPEOS DEL ESTE: premium. Lo más vendido, tratamiento de lujo, y sin pedir perdón por el número cuando lo dices.","ASIÁTICOS: el resultado. Saca el espejo pronto, un ojo contra el otro, y déjales mirar todo el rato que quieran.","ALEMANES/NEERLANDESES: valor práctico. Lo poco que se usa, lo que dura una jeringa, que no se desperdicia nada."]},{type:"divider"},{type:"subheader",text:"Decision Tree Summary",textEs:"Resumen del Árbol de Decisión"},{type:"paragraph",text:"Here's the ultra-quick version for the door:",textEs:"Aquí está la versión ultra rápida para la puerta:"},{type:"bullets",items:["ANYBODY, ANY DAY → SYRINGE ({currency}300 asking). That is the default and it does not need a reason.","EYES DOING THE SELLING FOR YOU → SYRINGE, straight at it. One eye, the mirror, done.","YOUNG AND GLOWING → SYRINGE, glow angle. The peeling ({currency}150 asking) is the fallback, not the opener.","SKEPTICAL MAN → SAME PRODUCT, DIFFERENT AUDIENCE. Bring him in before he gets bored.","SYRINGE SOLD → HAND HER TO THE SPECIALIST. Not to another product of yours.","STILL LEARNING, OR THE FLOOR HAS GONE FLAT → SCRUB OR NAIL KIT ({currency}60 for two, {currency}120 for three). Quick yeses, real practice."],itemsEs:["CUALQUIERA, CUALQUIER DÍA → JERINGA ({currency}300 de salida). Ese es el defecto y no necesita motivo.","LOS OJOS VENDEN SOLOS → JERINGA, directo. Un ojo, el espejo, listo.","JOVEN Y CON BUENA PIEL → JERINGA, ángulo de brillo. El peeling ({currency}150 de salida) es el plan B, no la apertura.","HOMBRE ESCÉPTICO → EL MISMO PRODUCTO, OTRO PÚBLICO. Métele antes de que se aburra.","JERINGA VENDIDA → PÁSASELA AL ESPECIALISTA. No a otro producto tuyo.","TODAVÍA APRENDIENDO, O LA SALA MUERTA → EXFOLIANTE O KIT DE UÑAS ({currency}60 dos, {currency}120 tres). Síes rápidos, práctica de verdad."]},{type:"tip",text:"None of this is rigid, and none of it is permission to skip the syringe. A 25-year-old with tired eyes is a syringe customer. A 60-year-old who loves her nails is a syringe customer who will also love the nail kit — after. Read the person, then pick your first sentence.",textEs:"Nada de esto es rígido, y nada de esto es permiso para saltarte la jeringa. Una chica de 25 con los ojos cansados es clienta de jeringa. Una señora de 60 a la que le encantan sus uñas es clienta de jeringa a la que además le va a encantar el kit de uñas — después. Lee a la persona, y luego elige tu primera frase."},{type:"quote",text:"Anyone can recite four products. The skill is looking at somebody for ten seconds and knowing which sentence gets them into the chair — because the product was never in doubt.",textEs:"Recitar cuatro productos lo hace cualquiera. La gracia está en mirar a alguien diez segundos y saber qué frase lo sienta en la silla — porque el producto nunca estuvo en duda.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"prod-7":{id:"prod-7",categoryId:"products",title:"Objection Handling Library",titleEs:"Biblioteca de Manejo de Objeciones",subtitle:"20 common objections and exactly how to respond to each one",subtitleEs:"Respuestas listas para cada excusa",duration:"10 min",icon:"Shield",order:7,xpReward:150,sections:[{type:"header",text:"Every Objection Is an Opportunity Dressed as a Problem",textEs:"Cada Objeción es una Oportunidad Disfrazada de Problema"},{type:"paragraph",text:"Objections aren't rejections — they're questions wearing disguise. When a customer says 'It's too expensive,' what they often mean is 'I don't understand the value yet.' When they say 'I need to ask my husband,' they might mean 'I need validation for a decision I already want to make.' Learning to translate objections and respond to the real concern underneath is a superpower.",textEs:'Las objeciones no son rechazos — son preguntas disfrazadas. Cuando un cliente dice "Es muy caro," lo que suele querer decir es "Todavía no entiendo el valor." Cuando dicen "Necesito preguntarle a mi esposo," podrían querer decir "Necesito validación para una decisión que ya quiero tomar." Aprender a traducir objeciones y responder a la preocupación real que hay debajo es un superpoder.'},{type:"keypoint",text:"Four beats, every time: take it → turn it round → show them something → put the question back. You never argue and you never go stiff. You take the objection like you have heard it a hundred times, because you have.",textEs:"Cuatro tiempos, siempre: encájalo → dale la vuelta → enséñales algo → devuélveles la pregunta. Ni discutes ni te pones tieso. Coges la objeción como quien la ha oído cien veces, porque la has oído."},{type:"divider"},{type:"subheader",text:"Price Objections",textEs:"Objeciones de Precio"},{type:"bullets",items:["'IT'S TOO EXPENSIVE' → 'Listen, I know, I know. But look at where we are: {currency}140 for the whole year. Sixty treatments in that syringe — a bit over {currency}2 each, cheaper than your coffee, and it is still working in June. Which of the two suits you better?' (Nobody says this at the top of the ladder, so say the number you are ACTUALLY on and shrink that one. Standing on {currency}175? Say {currency}175 — just under {currency}3 a treatment. The arithmetic only works if it matches the rung.)","'I CAN GET CHEAPER ONLINE' → 'Course you can. Can you try it first though? See it on your own face, in two minutes, before you spend a penny? That is what you are paying for. Try getting that off a website.' (Trying it is the bit the internet cannot do.)","'I WASN'T PLANNING TO SPEND THIS MUCH TODAY' → 'Nobody ever is — my last customer wasn't either! She tried it, saw her own eye in the mirror, and that was the end of it. This is not something you replace next month. Want to see what she saw?' (Normalise it, then hand it straight back to curiosity.)","'I DON'T HAVE CASH' → 'Not a problem at all — cards, Apple Pay, Google Pay, whatever you have got on you.' (Kill the payment barrier before it grows legs.)"],itemsEs:['"ES DEMASIADO CARO" → "Mira, ya lo sé, ya lo sé. Pero fíjate dónde estamos: {currency}140 por todo el año. Sesenta tratamientos en esa jeringa — poco más de {currency}2 cada uno, más barato que tu café, y en junio sigue funcionando. ¿Cuál de las dos te va mejor?" (Esto no lo dice nadie arriba de la escalera, así que di el número en el que ESTÁS de verdad y encoge ese. ¿Estás en {currency}175? Di {currency}175 — algo menos de {currency}3 por tratamiento. Las cuentas solo funcionan si cuadran con el escalón.)','"LO ENCUENTRO MÁS BARATO EN INTERNET" → "Claro que sí. ¿Pero lo puedes probar antes? ¿Verlo en tu propia cara, en dos minutos, antes de soltar un euro? Eso es lo que estás pagando. A ver quién te da eso en una página web." (Probarlo es lo que internet no puede hacer.)','"NO TENÍA PENSADO GASTARME TANTO HOY" → "Nadie lo tiene pensado — ¡mi última clienta tampoco! Lo probó, se vio el ojo en el espejo, y se acabó la historia. Esto no es algo que cambies el mes que viene. ¿Quieres ver lo que vio ella?" (Normalízalo y devuélvelo directo a la curiosidad.)','"NO LLEVO EFECTIVO" → "No pasa nada — tarjeta, Apple Pay, Google Pay, lo que lleves encima." (Quita la barrera del pago antes de que crezca.)']},{type:"divider"},{type:"subheader",text:"Product Skepticism Objections",textEs:"Objeciones de Escepticismo sobre el Producto"},{type:"bullets",items:["'I ALREADY HAVE CREAM AT HOME' → 'Good — this is not a cream! Completely different thing. Your cream hydrates; this takes the dead layer off first so your cream actually gets in. They go together. This is the step your routine is missing.' (Differentiate, do not compete.)","'I'VE NEVER HEARD OF THIS BRAND' → 'That is exactly why I am standing out here! We are small — you will not find us in a supermarket. Smaller name, better stuff in the tube. Don't take my word for it, give me your hand.' (Small is the advantage, then get off the subject and onto the demo.)","'I DON'T BELIEVE IT WORKS' → 'Good. I love a sceptic, it means you are actually paying attention. Don't believe me — believe the mirror. Two minutes, one hand. If you don't see it, I will be the first to tell you to keep your money. Deal?' (Agree with them, then put the proof in their hand.)","'IT'S PROBABLY FULL OF CHEMICALS' → 'Other way round — no parabens, nothing harsh, no needles anywhere near you. Here, the list is on the box, have a proper look at it.' (Answer it flat and give them the box.)"],itemsEs:['"YA TENGO CREMA EN CASA" → "Mejor — ¡esto no es una crema! Es otra cosa. Tu crema hidrata; esto quita antes la capa muerta para que tu crema entre de verdad. Van juntas. Este es el paso que le falta a tu rutina." (Diferénciate, no compitas.)','"NUNCA HE OÍDO ESTA MARCA" → "¡Por eso mismo estoy yo aquí fuera! Somos pequeños, no nos vas a encontrar en un supermercado. Nombre más pequeño, mejor producto dentro del tubo. No me creas a mí: dame la mano." (Lo pequeño es la ventaja, y de ahí directo a la demo.)','"NO ME CREO QUE FUNCIONE" → "Bien. Me encantan los escépticos, quiere decir que estás atenta de verdad. No me creas a mí, cree al espejo. Dos minutos, una mano. Si no lo ves, seré la primera en decirte que te guardes el dinero. ¿Trato?" (Dales la razón y ponles la prueba en la mano.)','"SEGURO QUE ESTÁ LLENO DE QUÍMICOS" → "Al revés — sin parabenos, nada agresivo, y ni una aguja cerca de ti. Toma, la lista está en la caja, míratela bien." (Contéstalo a pelo y dales la caja.)']},{type:"divider"},{type:"subheader",text:"Decision Delay Objections",textEs:"Objeciones de Demora en la Decisión"},{type:"bullets",items:["'I NEED TO ASK MY HUSBAND/WIFE' → 'Of course. But do YOU like it? Because if you like it, let us get him over here. Sir! Come and see what I have just done to one of your wife's eyes!' (Get the partner into the conversation before anybody walks anywhere.)","'I'LL THINK ABOUT IT AND COME BACK' → 'What is there to think about? You told me you like it, you told me you would use it. You are not going to walk up the street and come back to a better price. It's not a mortgage at the end of the day.' (Hand them back their own words and shrink the decision to its real size.)","'I NEED TO COMPARE PRICES' → 'Compare it to what? There is nothing else like it on this street. And this price lives here — cross the border and you are back to {currency}500.' (Let the location do the work for you.)","'I DON'T HAVE TIME RIGHT NOW' → 'I know, I know, you are in a rush. Sixty seconds. Not two minutes — sixty seconds, one hand. If you don't feel it straight away you walk off and I will not say another word.' (Put a number on it and the barrier shrinks.)"],itemsEs:['"TENGO QUE PREGUNTARLE A MI MARIDO/MUJER" → "Claro. ¿Pero a TI te gusta? Porque si a ti te gusta, lo llamamos. ¡Señor! ¡Venga a ver lo que le acabo de hacer a su mujer en un ojo!" (Mete a la pareja en la conversación antes de que nadie se mueva de ahí.)','"ME LO PIENSO Y VUELVO" → "¿Qué te tienes que pensar? Me has dicho que te gusta, me has dicho que lo usarías. No vas a dar una vuelta por la calle y volver con un precio mejor. Tampoco es una hipoteca." (Devuélveles sus propias palabras y reduce la decisión a su tamaño real.)','"QUIERO COMPARAR PRECIOS" → "¿Compararlo con qué? En esta calle no hay nada parecido. Y este precio vive aquí: cruzas la frontera y vuelves a {currency}500." (Que trabaje el sitio por ti.)','"AHORA NO TENGO TIEMPO" → "Ya lo sé, ya lo sé, vas con prisa. Sesenta segundos. Ni dos minutos: sesenta segundos y una mano. Si no lo notas al momento, te vas y no te digo ni una palabra más." (Ponle un número y la barrera se encoge.)']},{type:"divider"},{type:"subheader",text:"Lifestyle & Practical Objections",textEs:"Objeciones de Estilo de Vida y Practicidad"},{type:"bullets",items:["'I DON'T HAVE TIME FOR A SKINCARE ROUTINE' → 'Perfect, neither do I. Once a week, five minutes, one bottle sees you through the year. That is the whole thing. Less faff than painting your nails.' (Turn the objection into the argument.)","'I'M TRAVELLING AND DON'T WANT TO CARRY MORE' → 'It is smaller than your sunglasses, look. And honestly, after a week of planes and air conditioning your skin wants it more than usual. Goes in the hand luggage and you forget it is there.' (Make the travel the reason.)","'I'M ALLERGIC TO EVERYTHING' → 'Thanks for telling me — let us go slowly, then. A tiny bit on the inside of your wrist first, and we see how you get on. Anything at all and we stop there.' (Slow right down. Do not sell through it.)","'I NEVER BUY FROM STREET SELLERS' → 'Fair enough — but I am not selling you anything out here, am I? Come inside, sit down, let me do one hand. If you hate it you have lost two minutes.' (Do not argue with it. Move the whole thing indoors.)"],itemsEs:['"NO TENGO TIEMPO PARA UNA RUTINA DE PIEL" → "Perfecto, yo tampoco. Una vez por semana, cinco minutos, un bote te dura el año. Eso es todo. Menos lío que pintarte las uñas." (Convierte la objeción en el argumento.)','"ESTOY DE VIAJE Y NO QUIERO CARGAR MÁS" → "Es más pequeño que tus gafas de sol, mira. Y encima, después de una semana de aviones y aire acondicionado tu piel lo pide más que nunca. Va en el equipaje de mano y ni te enteras." (Que el viaje sea el motivo.)','"SOY ALÉRGICA A TODO" → "Gracias por decírmelo, pues vamos despacio. Primero un poquito en la parte de dentro de la muñeca y vemos qué tal. A la mínima cosa, lo dejamos." (Baja el ritmo del todo. No vendas por encima de eso.)','"YO NUNCA COMPRO A VENDEDORES DE CALLE" → "Me parece bien — pero aquí fuera no te estoy vendiendo nada, ¿no? Pasa, siéntate y te hago una mano. Si no te gusta, has perdido dos minutos." (No discutas con eso. Métete dentro con todo.)']},{type:"divider"},{type:"subheader",text:"Emotional Objections",textEs:"Objeciones Emocionales"},{type:"bullets",items:["'I FEEL GUILTY SPENDING MONEY ON MYSELF' → 'I hear that ten times a day, and always from the ones who do everything for everybody else. When was the last time you bought something that was only for you? Exactly. It's not a mortgage.' (Permission, said light.)","'I BOUGHT SOMETHING LAST TIME AND NEVER USED IT' → 'Then promise me two things: that you actually use it, and that if you love it you tell your friends. That is the whole deal.' (Two small promises land better than one big reassurance.)","'I'M NOT THE TYPE TO BUY LUXURY THINGS' → 'Neither am I, and look at me. The ones who never treat themselves are the ones who enjoy it most when they do. This is not about being posh. It is about liking what you see in the mirror.' (Take the posh out of it.)","'MY PRODUCT AT HOME WORKS FINE' → 'Then keep using it! This does not replace it, it goes before it. A good cream on a face that has just been cleared is a completely different thing.' (Complement, do not compete.)"],itemsEs:['"ME SIENTO CULPABLE GASTANDO EN MÍ" → "Eso lo oigo diez veces al día, y siempre de las que lo hacen todo por los demás. ¿Cuándo fue la última vez que te compraste algo solo para ti? Exacto. Tampoco es una hipoteca." (Permiso, dicho ligero.)','"LA ÚLTIMA VEZ COMPRÉ ALGO Y NO LO USÉ" → "Pues prométeme dos cosas: que lo usas de verdad, y que si te encanta se lo cuentas a tus amigas. Ese es todo el trato." (Dos promesas pequeñas calan más que una gran garantía.)','"NO SOY DE COMPRAR COSAS DE LUJO" → "Yo tampoco, y mírame. Las que nunca se dan un capricho son las que más lo disfrutan cuando lo hacen. Esto no va de ser pija. Va de que te guste lo que ves en el espejo." (Quítale lo pijo.)','"LO QUE USO EN CASA ME VA BIEN" → "¡Pues sigue usándolo! Esto no lo sustituye, va antes. Una buena crema sobre una cara recién limpia es otra cosa completamente distinta." (Complementa, no compitas.)']},{type:"divider"},{type:"subheader",text:"The Meta-Framework for ALL Objections",textEs:"El Meta-Marco para TODAS las Objeciones"},{type:"paragraph",text:"No matter what the objection is, follow this structure:",textEs:"No importa cuál sea la objeción, sigue esta estructura:"},{type:"numbered",items:["TAKE IT: 'Listen, I know, I know...' 'Ah, don't worry about that.' 'Fair enough.' You have heard it a hundred times. Let them see that on your face.","TURN IT ROUND: Give them another way to look at it. Per week, not per bottle. A year, not a purchase. Two minutes, not a commitment.","SHOW THEM SOMETHING: The mirror, their own hand, the box, the last customer. Anything at all beats more talking.","PUT THE QUESTION BACK: 'Which one suits you better?' 'Want to see what I mean?' Never leave a silence they can fill with a no."],itemsEs:['ENCÁJALO: "Mira, ya lo sé, ya lo sé..." "Ah, no te preocupes por eso." "Me parece bien." Lo has oído cien veces. Que se te note en la cara.',"DALE LA VUELTA: Dales otra forma de mirarlo. Por semana, no por bote. Un año, no una compra. Dos minutos, no un compromiso.","ENSÉÑALES ALGO: El espejo, su propia mano, la caja, la clienta anterior. Cualquier cosa es mejor que seguir hablando.",'DEVUÉLVELES LA PREGUNTA: "¿Cuál te va mejor?" "¿Quieres ver a qué me refiero?" Nunca dejes un silencio que puedan rellenar con un no.']},{type:"tip",text:"The move is: do not flinch. Whatever they throw at you, you take it like you have heard it a hundred times — because you have. 'Listen, I know, I know...' 'Ah, don't worry about that.' 'It's not a mortgage at the end of the day.' You are not agreeing with them and you are not arguing with them. You are waving it off warm and carrying straight on to the next thing.",textEs:'La jugada es: no te achantes. Te tiren lo que te tiren, lo coges como quien lo ha oído cien veces — porque lo has oído. "Mira, ya lo sé, ya lo sé..." "Ah, no te preocupes por eso." "Tampoco es una hipoteca." Ni les das la razón ni discutes con ellos. Lo apartas con buen rollo y sigues directo a lo siguiente.'},{type:"quote",text:"An objection is not a wall. It's a door with a question mark on it. Knock correctly, and it opens to a sale.",textEs:"Una objeción no es una pared. Es una puerta con un signo de interrogación. Toca correctamente, y se abre a una venta.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What are the four beats of an objection?",options:["Argue → Convince → Wear them down → Close the sale anyway","Take it → Turn it round → Show them → Ask again","Ignore → Discount → Give up → Walk away","Agree → Agree → Agree → Accept no"],correctIndex:1,explanation:"Take it like you have heard it a hundred times, give them another way to look at it, show them something instead of saying more, then put the question back so they cannot fill the silence with a no."},{question:"How should you respond to 'I already have cream at home'?",options:["Tell them their cream is inferior","Differentiate your product as a complementary prep step that makes their cream work better","Offer to throw in a free cream","End the conversation"],correctIndex:1,explanation:"Don't compete with their cream — complement it. Position your product as the prep step that makes the cream she already owns work properly. They're not replacing; they're enhancing."},{question:"They hit you with an objection. What is the first thing you do?",options:["Explain in detail why the objection is mistaken","Take it like you have heard it a hundred times","Drop a rung on the price before they ask you to","Repeat the objection back to them word for word"],correctIndex:1,explanation:"Do not flinch. 'Listen, I know, I know...' 'Ah, don't worry about that.' You are not agreeing and you are not arguing — you are waving it off warm and carrying straight on."}]},"prod-8":{id:"prod-8",categoryId:"products",title:"The Number, And Then Let It Go",titleEs:"El Número, y Luego Suéltalo",subtitle:"Take it if the moment offers it, send one message while she is standing there, then get back on the floor",subtitleEs:"Cógelo si el momento lo pide, manda un mensaje mientras sigue ahí, y vuelve a la sala",duration:"4 min",icon:"MessageSquare",order:8,xpReward:150,sections:[{type:"header",text:"There Is No Follow-Up in This Job",textEs:"En Este Trabajo No Hay Seguimiento"},{type:"paragraph",text:"Somewhere in your head there is a picture of a client book: names, notes, birthdays, a message on day three and another on day seven. Forget it. That is a job in a salon where people live down the road. Yours is a kiosk in a shopping centre and the woman in your chair flies home on Tuesday. You will almost certainly never see her again, and no message you send her next week will change that.",textEs:"En algún sitio de tu cabeza hay una foto de un libro de clientes: nombres, notas, cumpleaños, un mensaje el día tres y otro el día siete. Olvídalo. Eso es un trabajo en un salón donde la gente vive en la misma calle. El tuyo es un kiosco en un centro comercial y la mujer de tu silla vuela a casa el martes. Con toda probabilidad no la vas a volver a ver, y ningún mensaje que le mandes la semana que viene va a cambiar eso."},{type:"keypoint",text:"Which is exactly why the only follow-up that ever works happens while she is still standing in front of you. Everything you were going to do on day three, you do in the ninety seconds after she pays — or you do not do it at all.",textEs:"Y justo por eso el único seguimiento que funciona ocurre mientras ella todavía está delante de ti. Todo lo que ibas a hacer el día tres, lo haces en los noventa segundos después de que pague — o no lo haces nunca."},{type:"divider"},{type:"subheader",text:"The Order of Those Ninety Seconds",textEs:"El Orden de Esos Noventa Segundos"},{type:"numbered",items:["THE HANDOVER, IF IT WAS A SYRINGE. The specialist gets her while she is still sitting and still delighted, and nothing else on this page happens before that. Your job ended at the syringe — see The Handover for the words.","THEN THE NUMBER, if the moment offers it. Never instead of the handover, and never while you are waiting for him.","THEN THE TWO PROMISES, once, light, half a joke.","THEN BACK OUT ON THE FLOOR. In that order, every time. Take the number first and you have used up her ninety seconds on the least valuable thing in them."],itemsEs:["EL TRASPASO, SI HA SIDO UNA JERINGA. El especialista la pilla mientras sigue sentada y sigue encantada, y nada de esta página pasa antes de eso. Tu trabajo se acabó en la jeringa — las palabras están en El Traspaso.","LUEGO EL NÚMERO, si el momento lo pide. Nunca en lugar del traspaso, y nunca mientras estás esperando a que venga él.","LUEGO LAS DOS PROMESAS, una vez, ligeras, medio en broma.","Y LUEGO OTRA VEZ FUERA. En ese orden, siempre. Si coges el número primero, te has gastado sus noventa segundos en lo que menos vale de todo."]},{type:"divider"},{type:"subheader",text:"Take the Number Only If the Moment Offers It",textEs:"Coge el Número Solo Si el Momento lo Pide"},{type:"paragraph",text:"She is paid, delighted, holding the bag, laughing at something you said. THAT is when you ask, and only then. If the moment is flat, skip it — a number squeezed out of somebody who is already halfway to the door is a number that never gets used, and asking for it turns a lovely ending into a bit of admin.",textEs:"Ha pagado, está encantada, tiene la bolsa en la mano y se está riendo de algo que has dicho. ESE es el momento de pedirlo, y solo ese. Si el momento está plano, sáltatelo — un número sacado a alguien que ya está a medio camino de la puerta es un número que no se usa nunca, y pedirlo convierte un final bonito en papeleo."},{type:"script",text:"'You use WhatsApp, right? Give me your number — I'll send you mine right now, so if you ever have a question about how to use it you've got a human instead of a website.'",textEs:'"¿Usas WhatsApp, no? Dame tu número — te mando el mío ahora mismo, así si algún día tienes una duda de cómo usarlo tienes a una persona y no a una página web."'},{type:"keypoint",text:"Then send it THERE, in front of her, before she stands up. One message, two lines, done: who you are and where you are. If you wait until later you will not do it, and if she has typed a digit wrong nobody will ever find out.",textEs:"Y mándalo AHÍ, delante de ella, antes de que se levante. Un mensaje, dos líneas, y ya: quién eres y dónde estás. Si lo dejas para luego no lo vas a hacer, y si se ha equivocado en un número no se va a enterar nadie."},{type:"script",text:"'Hi [Name] — it's [Your Name] from the shop in {locationName}. Save that. Any questions at all, message me. Enjoy it!'",textEs:'"Hola [Nombre] — soy [Tu Nombre], de la tienda de {locationName}. Guárdalo. Cualquier duda, me escribes. ¡Disfrútalo!"'},{type:"divider"},{type:"subheader",text:"The Two Promises — Your Whole Referral Strategy",textEs:"Las Dos Promesas — Toda tu Estrategia de Recomendación"},{type:"paragraph",text:"You do not chase referrals for weeks. You ask once, at the top of her mood, while the bag is still in her hand — and then you never mention it again. Two things, said light, half a joke:",textEs:"No persigues recomendaciones durante semanas. Lo pides una vez, en lo más alto de su alegría, con la bolsa todavía en la mano — y luego no lo vuelves a mencionar. Dos cosas, dichas ligeras, medio en broma:"},{type:"script",text:"'Promise me two things. One: you actually use it — once a week, not once a year. Two: if you love it, you tell your friends where you got it.'",textEs:'"Prométeme dos cosas. Una: que lo usas de verdad — una vez a la semana, no una vez al año. Dos: que si te encanta, le cuentas a tus amigas dónde lo has comprado."'},{type:"tip",text:"That is the entire ask, and the reason it works is the timing, not the wording. Somebody who is delighted and holding a bag will say yes to it and mean it. The same sentence, sent as a message eleven days later, is just a stranger asking a favour.",textEs:"Eso es toda la petición, y lo que la hace funcionar es el momento, no las palabras. Alguien encantado y con la bolsa en la mano te va a decir que sí y lo va a decir en serio. Esa misma frase, mandada por mensaje once días después, es un desconocido pidiendo un favor."},{type:"divider"},{type:"subheader",text:"If She Messages You, Be a Person",textEs:"Si Te Escribe, Sé una Persona"},{type:"paragraph",text:"Some of them do write. Not many, but some — a question about how often, a photo of their eyes, a friend arriving next week. Answer them properly and quickly, like a human being, and lead with the help rather than the sell. That is the whole policy. What you do not do is turn it into a campaign: no schedule, no templates, no chasing people who did not reply. One unanswered message is her telling you she is done, and the correct response is to leave her alone.",textEs:"Alguna sí escribe. No muchas, pero alguna — una duda de cada cuánto, una foto de los ojos, una amiga que llega la semana que viene. Contéstales bien y rápido, como una persona, y empieza por ayudar y no por vender. Esa es toda la política. Lo que no haces es convertirlo en una campaña: sin calendario, sin plantillas, sin perseguir a quien no ha contestado. Un mensaje sin respuesta es ella diciéndote que ya está, y lo correcto es dejarla en paz."},{type:"keypoint",text:"And never promise anything the shop has to honour on a day you might not be working — no held stock, no kept price, no gift waiting at the counter. You will be somewhere else and a colleague will be having that argument for you.",textEs:"Y no prometas nunca nada que la tienda tenga que cumplir un día en el que a lo mejor tú no trabajas — ni producto guardado, ni un precio reservado, ni un regalo esperando en el mostrador. Tú estarás en otro sitio y un compañero tendrá esa discusión por ti."},{type:"quote",text:"The number is a nice thing to have. It is not the sale, it was never the sale, and it never goes before the handover — thirty seconds spent tidying your contacts is thirty seconds you were not on the floor stopping somebody.",textEs:"El número está bien tenerlo. No es la venta, nunca fue la venta, y nunca va antes del traspaso — treinta segundos ordenando contactos son treinta segundos que no has pasado en la calle parando a alguien.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"psych-1":{id:"psych-1",categoryId:"psychology",title:"The 'Luxury Aggressor' Identity",titleEs:"La Identidad del 'Agresor de Lujo'",subtitle:"How to think of yourself as a premium brand ambassador, not a pushy seller",subtitleEs:"No eres un vendedor insistente. Eres un curador de transformación.",duration:"8 min",icon:"Crown",order:1,xpReward:100,sections:[{type:"header",text:"You Are Not a Pushy Seller. You Are a Curator of Transformation.",textEs:"No eres un vendedor insistente. Eres un curador de transformacion."},{type:"paragraph",text:"The word 'aggressive' scares people. In this job it does not mean pushing. It means going at it with certainty. You are not begging anybody for anything — you run this bit of pavement, and you are offering something that most people walk straight past. Warm, quick, enjoying yourself. Not apologising and not chasing.",textEs:"La palabra 'agresivo' asusta a la gente. En este trabajo no significa presionar. Significa ir con seguridad. No le estás rogando nada a nadie — este trozo de acera lo llevas tú, y estás ofreciendo algo por delante de lo que casi todo el mundo pasa de largo. Cálido, rápido, disfrutando. Sin pedir perdón y sin perseguir a nadie."},{type:"keypoint",text:"The mindset shift: You're not interrupting someone's day — you're enhancing it. The products you sell deliver visible, immediate results. You're doing them a favor by stopping them.",textEs:"El cambio de mentalidad: No estas interrumpiendo el día de alguien — lo estas mejorando. Los productos que vendes ofrecen resultados visibles e inmediatos. Les estas haciendo un favor al detenerlos."},{type:"divider"},{type:"subheader",text:"The Three Pillars of the Luxury Aggressor",textEs:"Los Tres Pilares del Agresivo de Lujo"},{type:"numbered",items:["CERTAINTY: You know the product works. You've seen the reactions. That belief radiates from you before you open your mouth.","PRESENCE: You stand tall. You make eye contact. Your voice is clear and warm. You occupy space like you belong there — because you do.","APPETITE: You go at everybody. Not out of desperation — out of appetite. You are not stood there deciding who deserves you, you are working, and there is another one thirty seconds behind this one. Knowing who to skip is something the years give you. Nobody hands it to you in week one, and the sellers who try to shortcut it spend the shift with their hands in their pockets."],itemsEs:["CERTEZA: Sabes que el producto funciona. Has visto las reacciones. Esa creencia irradia de ti antes de que abras la boca.","PRESENCIA: Te paras derecho. Haces contacto visual. Tu voz es clara y calida. Ocupas el espacio como si pertenecieras ahi — porque asi es.","HAMBRE: Vas a por todo el mundo. No por desesperación — por hambre. No estás ahí decidiendo quién te merece, estás trabajando, y treinta segundos detrás de este viene otro. Saber a quién saltarte te lo dan los años. Nadie te lo da la primera semana, y los que intentan atajarlo se pasan el turno con las manos en los bolsillos."]},{type:"divider"},{type:"subheader",text:"The Mirror Drill",textEs:"El Ejercicio del Espejo"},{type:"paragraph",text:"Before your next shift, stand in front of the mirror and say your opener out loud twenty times. Not an affirmation — the actual line you are going to use on a stranger in an hour:",textEs:"Antes de tu siguiente turno, ponte delante del espejo y di tu apertura en voz alta veinte veces. No es un mantra — es la frase de verdad que le vas a soltar a un desconocido dentro de una hora:"},{type:"script",text:"'Listen, I know you're in a rush — but can I ask you something really quick? It's just that you look so good, I have to ask what you normally use on your skin.'",textEs:"'Mira, sé que vas con prisa — ¿pero te puedo preguntar una cosa rapidísima? Es que te veo tan bien que tengo que preguntarte qué usas normalmente para la piel.'"},{type:"tip",text:"Twenty times. Somewhere around the twelfth it stops sounding like a line and starts sounding like you, and that is the entire point of the drill. A stranger can hear the difference from three metres away.",textEs:"Veinte veces. Por la número doce deja de sonar a frase hecha y empieza a sonar a ti, y ese es todo el objetivo del ejercicio. Un desconocido nota la diferencia desde tres metros."},{type:"divider"},{type:"subheader",text:"Practical Techniques",textEs:"Técnicas Practicas"},{type:"bullets",items:["Dress the part: You are the first thing they judge. Clean shoes, hair done, shirt right. Look like somebody worth stopping for and they stop.","Language matters: Say 'I'd love to show you something' not 'Can I show you something?' The first is an invitation. The second is a question they can reject.","Posture check: Shoulders back, chin up, smile in your eyes. Practice power poses in the stockroom before your shift.","The pause: After you deliver your opener, pause. Let silence work. The Luxury Aggressor doesn't rush — they command attention, then let it land."],itemsEs:["Viste el papel: Lo primero que juzgan eres tú. Zapatos limpios, el pelo arreglado, la camisa en su sitio. Parece alguien por quien merece la pena pararse y se paran.","El lenguaje importa: Di 'Me encantaria mostrarte algo' no 'Puedo mostrarte algo?' La primera es una invitacion. La segunda es una pregunta que pueden rechazar.","Revisa tu postura: Hombros hacia atras, barbilla arriba, sonrisa en tus ojos. Practica poses de poder en el almacen antes de tu turno.","La pausa: Después de lanzar tu apertura, pausa. Deja que el silencio haga su trabajo. El Agresivo de Lujo no se apresura — comanda la atención, y luego deja que caiga."]},{type:"divider"},{type:"subheader",text:"When Rejection Hits",textEs:"Cuando el Rechazo Golpea"},{type:"paragraph",text:"Even the Luxury Aggressor gets ignored. The difference? They don't flinch. A rejected invitation isn't a reflection on you — it's a reflection on their timing, mood, or preoccupations. Maintain your posture. Smile at the next person. Your energy doesn't dip because one person said no.",textEs:"Incluso el Agresivo de Lujo es ignorado. La diferencia? No se inmutan. Una invitacion rechazada no es un reflejo de ti — es un reflejo de su tiempo, su estado de animo o sus preocupaciones. Manten tu postura. Sonrie a la siguiente persona. Tu energía no decae porque una persona dijo no."},{type:"quote",text:"The difference between a pushy seller and a luxury ambassador is belief. The pushy seller hopes someone will buy. The ambassador knows they will.",textEs:"La diferencia entre un vendedor insistente y un embajador de lujo es la creencia. El vendedor insistente espera que alguien compre. El embajador sabe que lo haran.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"},{type:"tip",text:"Watch the best seller on this street for one shift. Not the words — how they stand while they wait, how fast they let somebody go, what they do with their hands. Take the two things that would feel natural coming out of you and leave the rest.",textEs:"Observa un turno entero al que mejor vende de esta calle. No las palabras — cómo se planta mientras espera, lo rápido que deja marchar a alguien, qué hace con las manos. Cógete las dos cosas que te saldrían naturales a ti y deja el resto."}]},"psych-2":{id:"psych-2",categoryId:"psychology",title:"Energy is Your #1 Weapon",titleEs:"La Energía es tu Arma #1",subtitle:"Managing energy throughout a shift — rituals, micro-breaks, and the art of faking it till you make it",subtitleEs:"Tu energía vende antes que tus palabras",duration:"8 min",icon:"Zap",order:2,xpReward:100,sections:[{type:"header",text:"Energy Sells Before Words Do",textEs:"Tu Energía Vende Antes que tus Palabras"},{type:"paragraph",text:"Customers feel your energy before you have said a word. Before they hear your voice, before they see your smile, they sense your vibration. Tired, heavy energy repels. Light, excited energy attracts. This isn't mystical — it's neuroscience. Humans have mirror neurons that cause us to emotionally sync with people around us. Your mood literally becomes their mood.",textEs:"Los clientes te notan la energía antes de que digas nada. Antes de escuchar tu voz, antes de ver tu sonrisa, sienten tu vibracion. La energía cansada y pesada repele. La energía ligera y entusiasmada atrae. No es mistico — es neurociencia. Los seres humanos tenemos neuronas espejo que nos hacen sincronizarnos emocionalmente con las personas a nuestro alrededor. Tu estado de animo literalmente se convierte en el de ellos."},{type:"keypoint",text:"Energy is more important than script, product knowledge, or pricing. A salesperson with great energy and average skills will outsell a tired expert every single time.",textEs:"La energía es mas importante que el guion, el conocimiento del producto o los precios. Un vendedor con gran energía y habilidades promedio vendera mas que un experto cansado, cada vez."},{type:"divider"},{type:"subheader",text:"The Energy Lifecycle of a Shift",textEs:"El Ciclo de Energía de un Turno"},{type:"paragraph",text:"Most salespeople's energy follows a predictable curve: high at opening, dipping after the first hour, crashing mid-day, then a small recovery before closing. Top performers break this curve deliberately. Here's how:",textEs:"La energía de la mayoria de los vendedores sigue una curva predecible: alta al inicio, bajando después de la primera hora, cayendo a mitad del día, y luego una pequena recuperacion antes de cerrar. Los mejores rompen esta curva deliberadamente. Asi es como:"},{type:"numbered",items:["PRE-SHIFT (30 min before): Fuel your body. Eat a light, protein-rich meal — not heavy carbs that make you sluggish. Hydrate. Listen to music that pumps you up. Do 2 minutes of jumping jacks or shadow boxing to wake up your nervous system.","OPENING HOUR (peak alertness): Use this wisely. Your first stops set the tone for the whole day. Smile at EVERY person who passes, even if you don't stop them. This builds momentum.","MID-MORNING (first dip): This is when the 4-minute rotation saves you. Use your inside time to recharge — not by scrolling your phone, but by taking 5 deep breaths, drinking water, and celebrating any small win so far.","LUNCH PERIOD: Eat light. A heavy meal will kill your afternoon. Salads, protein, fruit. Avoid the pasta and bread trap.","AFTERNOON SAG (the danger zone 2-4pm): This is where sales are won or lost. Stand up straighter. Move faster. Speak louder. Consciously elevate every physical action — your brain follows your body.","POWER HOUR (last 90 minutes): End strong. The final push of the day often has the best customers — they're done shopping and ready to be sold to. Bring everything you have left."],itemsEs:["PRE-TURNO (30 min antes): Abastece tu cuerpo. Come una comida ligera rica en proteinas — no carbohidratos pesados que te hagan sentir lento. Hidratate. Escucha musica que te motive. Haz 2 minutos de jumping jacks o shadow boxing para despertar tu sistema nervioso.","HORA DE APERTURA (alerta maxima): Usala sabiamente. Tus primeras detenciones marcan el tono para todo el día. Sonrie a CADA persona que pase, incluso si no las detienes. Esto genera momentum.","MEDIA MANANA (primer bajon): Aquí es cuando la rotacion de 4 minutos te salva. Usa tu tiempo adentro para recargarte — no mirando el móvil, sino tomando 5 respiraciones profundas, bebiendo agua y celebrando cualquier pequena victoria hasta ahora.","PERIODO DE COMIDA: Come ligero. Una comida pesada matara tu tarde. Ensaladas, proteina, fruta. Evita la trampa de la pasta y el pan.","BAJON DE LA TARDE (la zona de peligro 2-4pm): Aquí es donde las ventas se ganan o se pierden. Parate mas derecho. Muevete mas rápido. Habla mas fuerte. Eleva conscientemente cada acción física — tu cerebro sigue a tu cuerpo.","HORA DE PODER (ultimos 90 minutos): Termina fuerte. El empuje final del día a menudo tiene a los mejores clientes — ya terminaron de comprar y están listos para ser vendidos. Pon todo lo que te queda."]},{type:"divider"},{type:"subheader",text:"The 4-Minute Rotation Advantage",textEs:"La Ventaja de la Rotacion de 4 Minutos"},{type:"paragraph",text:"The 4-minute door rotation isn't just fair — it's energy management genius. Knowing you only have 4 minutes outside before switching keeps your intensity high. It's like interval training for sales. You sprint, recover, sprint again. This prevents the burnout that kills most street sellers by hour 3.",textEs:"La rotacion de puerta de 4 minutos no es solo justa — es una genialidad de manejo de energía. Saber que solo tienes 4 minutos afuera antes de cambiar mantiene tu intensidad alta. Es como entrenamiento por intervalos para ventas. Corres, recuperas, corres de nuevo. Esto previene el agotamiento que mata a la mayoria de los vendedores de calle a la hora 3."},{type:"tip",text:"During your 4 minutes outside, give 100% energy to every person you stop. During your inside time, consciously lower your shoulders, unclench your jaw, and breathe. This oscillation keeps you fresh all day.",textEs:"Durante tus 4 minutos afuera, da el 100% de tu energía a cada persona que detengas. Durante tu tiempo adentro, baja conscientemente tus hombros, relaja la mandibula y respira. Esta oscilacion te mantiene fresco todo el día."},{type:"divider"},{type:"subheader",text:"The 'Fake It Till You Make It' Technique",textEs:"La Técnica 'Finge Hasta Que Lo Logres'"},{type:"paragraph",text:"Some days you just don't have it. You didn't sleep well. You're fighting with your partner. You're hungover. Here's the truth: your body can trick your brain. Act energetic and the energy turns up afterwards — every seller on this floor has done it on a Monday and felt it work. Stand tall → feel more confident. Smile → feel happier. Speak loudly → feel more alert.",textEs:"Hay días en los que simplemente no lo tienes. No has dormido bien. Estás discutiendo con tu pareja. Vas con resaca. La verdad es esta: tu cuerpo puede engañar a tu cerebro. Actúa con energía y la energía llega después — todo el mundo en este suelo lo ha hecho un lunes y ha notado que funciona. Ponte recto → te sientes más seguro. Sonríe → te sientes más contento. Habla alto → te sientes más despierto."},{type:"script",text:"'Even on my worst days, I play a character. I am High-Energy Salesperson. I smile bigger. I move faster. I speak with more enthusiasm. And within 30 minutes, I'm not playing anymore — I actually feel it.'",textEs:"'Incluso en mis peores días, interpreto un personaje. Soy el Vendedor de Alta Energía. Sonrio mas grande. Me muevo mas rápido. Hablo con mas entusiasmo. Y dentro de 30 minutos, ya no estoy actuando — realmente lo siento.'"},{type:"bullets",items:["POWER POSE: Two minutes before your shift, hands on hips, chest open, chin up. Feels ridiculous, works anyway — you walk out onto the pavement already standing like somebody worth stopping for.","THE SMILE LOOP: Force a wide smile for 10 seconds. Your brain releases dopamine and serotonin. Repeat every hour.","MUSIC TRIGGERS: Create a 3-song playlist that always hypes you up. Listen during breaks.","VOICE PROJECTION: Speak 20% louder than normal. Projecting energy through your voice makes you feel more energetic."],itemsEs:["POSE DE PODER: Dos minutos antes del turno, manos en las caderas, pecho abierto, barbilla arriba. Es ridículo y funciona igual — sales a la acera ya plantado como alguien por quien merece la pena pararse.","EL CICLO DE SONRISA: Fuerza una sonrisa amplia por 10 segundos. Tu cerebro libera dopamina y serotonina. Repite cada hora.","DETONANTES MUSICALES: Crea una lista de 3 canciones que siempre te motiven. Escuchalas durante los descansos.","PROYECCION DE VOZ: Habla 20% mas fuerte de lo normal. Proyectar energía a traves de tu voz te hace sentir mas energetico."]},{type:"divider"},{type:"subheader",text:"Hydration, Nutrition & Physical Maintenance",textEs:"Hidratacion, Nutricion y Mantenimiento Físico"},{type:"paragraph",text:"Coffee is not hydration. Energy drinks create crashes. Sugar spikes then drops. The best fuel for a sales shift is:",textEs:"El cafe no es hidratacion. Las bebidas energeticas crean bajones. El azucar sube y luego cae. El mejor combustible para un turno de ventas es:"},{type:"bullets",items:["Water, not coffee. Your voice goes rough by two o'clock otherwise, and your voice is what you sell with.","Something to pick at between customers — nuts, a bit of fruit. Small and often beats one big go.","Eat light at lunch. A proper plate of pasta at midday and you have sold your afternoon to somebody else."],itemsEs:["Agua, no café. Si no, a las dos de la tarde tienes la voz rota, y la voz es con lo que vendes.","Algo para picar entre clientes — frutos secos, un poco de fruta. Poco y a menudo gana a un atracón.","Come ligero a mediodía. Un buen plato de pasta a la hora de comer y le has vendido la tarde a otro."]},{type:"tip",text:"Bring a water bottle to the floor. Sip between customers. Being well-hydrated improves your voice quality, skin appearance, and mental sharpness — all things customers notice subconsciously.",textEs:"Lleva un botella de agua al piso de ventas. Sorbe entre clientes. Estar bien hidratado mejora la calidad de tu voz, la apariencia de tu piel y tu agudeza mental — todo cosas que los clientes notan subconscientemente."},{type:"quote",text:"Your energy introduces you before you even speak. Make sure it's saying the right thing.",textEs:"Tu energía te presenta antes de que siquiera hables. Asegurate de que este diciendo lo correcto.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Why is the 4-minute rotation system effective for energy management?",options:["It gives you more breaks","It works like interval training — high intensity followed by recovery","It lets you check your phone","It reduces the number of customers you need to stop"],correctIndex:1,explanation:"The 4-minute rotation creates an interval-training effect. You give 100% energy for 4 minutes, then recover inside. This oscillation prevents the burnout that kills performance."},{question:"What should you eat during your lunch break to maintain afternoon energy?",options:["Pasta and bread for carbs","A heavy meal to feel satisfied","Light protein, salads, and fruit","Skip lunch to stay sharp"],correctIndex:2,explanation:"Heavy meals redirect blood from your brain to your stomach, causing afternoon fog. Light protein, salads, and fruit provide sustained energy without the crash."},{question:"How does 'faking' energy actually work according to psychological research?",options:["It doesn't work — customers can tell","Your body can trick your brain into actually feeling more energetic","It only works for experienced sellers","It's about lying to yourself"],correctIndex:1,explanation:"Research on embodied cognition shows that acting energetic (power poses, smiling, speaking loudly) actually changes your brain chemistry and creates real energy."}]},"psych-3":{id:"psych-3",categoryId:"psychology",title:"Confidence When You Don't Feel It",titleEs:"Confianza Cuando No La Sientes",subtitle:"Body language hacks, the 'act as if' technique, and why customers can smell insecurity",subtitleEs:"Trucos de lenguaje corporal, la técnica de 'actúa como si', y por qué el cliente huele la inseguridad",duration:"10 min",icon:"Shield",order:3,xpReward:150,sections:[{type:"header",text:"Confidence Is a Skill, Not a Trait",textEs:"La Confianza es una Habilidad, no un Rasgo"},{type:"paragraph",text:"The most dangerous myth in sales is that confident people are 'born that way.' Nonsense. Confidence is a set of behaviors practiced until they become automatic. Every 'naturally confident' salesperson you admire has bombed hundreds of times. The difference is they kept going until confidence became their default setting.",textEs:"El mito mas peligroso en ventas es que la gente confiada 'nacio asi.' Tonterias. La confianza es un conjunto de comportamientos practicados hasta que se vuelven automaticos. Cada vendedor 'naturalmente confiado' que admiras ha fracasado cientos de veces. La diferencia es que siguieron adelante hasta que la confianza se convirtio en su configuracion por defecto."},{type:"keypoint",text:"Customers don't buy from people who seem unsure. If you hesitate, if your voice shakes, if you avoid eye contact — the customer feels that something is wrong, even if they can't name it. Confidence is the container that makes everything else you do work.",textEs:"Los clientes no compran a gente que parece insegura. Si dudas, si tu voz tiembla, si evitas el contacto visual — el cliente siente que algo esta mal, incluso si no puede nombrarlo. La confianza es el contenedor que hace que todo lo demas que haces funcione."},{type:"divider"},{type:"subheader",text:"Body Language Hacks",textEs:"Hacks de Lenguaje Corporal"},{type:"paragraph",text:"Your body speaks louder than your words. Before you even open your mouth, customers have judged your credibility from your posture, movement, and facial expression. Here are the specific adjustments that create instant confidence perception:",textEs:"Tu cuerpo habla mas fuerte que tus palabras. Antes de que siquiera abras la boca, los clientes han juzgado tu credibilidad por tu postura, movimiento y expresion facial. Aquí están los ajustes especificos que crean percepcion de confianza instantanea:"},{type:"bullets",items:["SHOULDER POSITION: Roll your shoulders back and down. This opens your chest, improves breathing, and signals dominance without aggression. Practice this every time you walk through the door.","EYE CONTACT: Maintain eye contact for 2-3 seconds at a time. Breaking eye contact too quickly signals nervousness. Holding too long feels aggressive. The sweet spot is brief, confident connection.","SMILE WITH YOUR EYES: A genuine smile crinkles the corners of your eyes (Duchenne smile). A fake mouth-only smile triggers customer's distrust. Think of something that genuinely makes you happy before you approach.","OPEN PALMS: Keep your hands visible with palms slightly open. This is an ancient biological signal of 'I have no weapons.' It triggers subconscious trust.","SLOW MOVEMENTS: Nervous people move quickly and jerkily. Confident people move deliberately. Slow your gestures by 20%. Pause between movements.","STABLE POSTURE: Avoid shifting your weight from foot to foot. Plant your feet shoulder-width apart. This 'grounded' posture signals stability and certainty."],itemsEs:["POSICION DE HOMBROS: Lleva tus hombros hacia atras y abajo. Esto abre tu pecho, mejora la respiracion y senala dominancia sin agresion. Practica esto cada vez que caminas por la puerta.","CONTACTO VISUAL: Manten el contacto visual por 2-3 segundos a la vez. Romper el contacto visual demasiado rápido senala nerviosismo. Mantenerlo demasiado tiempo se siente agresivo. El punto ideal es una conexion breve y confiada.","SONRIE CON TUS OJOS: Una sonrisa genuina arruga las esquinas de tus ojos (sonrisa de Duchenne). Una sonrisa falsa de solo boca desencadena desconfianza en el cliente. Piensa en algo que genuinamente te hace feliz antes de acercarte.","PALMAS ABIERTAS: Manten tus manos visibles con las palmas ligeramente abiertas. Esta es una senal biologica antigua de 'no tengo armas.' Desencadena confianza subconsciente.","MOVIMIENTOS LENTOS: La gente nerviosa se mueve rápido y a tirones. La gente confiada se mueve deliberadamente. Ralentiza tus gestos un 20%. Pausa entre movimientos.","POSTURA ESTABLE: Evita cambiar tu peso de pie a pie. Planta tus pies al ancho de los hombros. Esta postura 'enraizada' senala estabilidad y certeza."]},{type:"divider"},{type:"subheader",text:"The 'Act As If' Technique",textEs:"La Técnica 'Actua Como Si'"},{type:"paragraph",text:"Pick the most confident salesperson you know — at your shop, in a luxury store, or even a character from a movie. Study them. How do they stand? How do they speak? What would THEY do in your situation? Then act as if you are them.",textEs:"Elige al vendedor mas confiado que conozcas — en tu tienda, en una tienda de lujo, o incluso un personaje de pelicula. Estudialo. Como se paran? Como hablan? Que harian ELLOS en tu situacion? Entonces actua como si fueras ellos."},{type:"script",text:"'When I first started, I wasn't confident at all. So I picked a character — I imagined I was a famous actress playing the role of a badass saleswoman. I copied her posture, her voice, her walk. After two weeks, I wasn't acting anymore. I had become her.'",textEs:"'Cuando empece, no era nada confiada. Asi que elegi un personaje — imagine que era una actriz famosa interpretando el papel de una vendedora increible. Copie su postura, su voz, su caminar. Después de dos semanas, ya no estaba actuando. Me había convertido en ella.'"},{type:"tip",text:"This is not about being fake. It's about rapid behavioral learning. By mimicking confident behaviors, you build the neural pathways that make confidence natural. Within 30 days of consistent practice, the 'act' becomes authentic.",textEs:"Esto no se trata de ser falso. Se trata de aprendizaje conductual rápido. Al imitar comportamientos confiados, construyes las vias neuronales que hacen que la confianza sea natural. Dentro de 30 días de practica constante, el 'acto' se vuelve autentico."},{type:"divider"},{type:"subheader",text:"Confidence Through Preparation",textEs:"Confianza a Traves de la Preparacion"},{type:"paragraph",text:"The deepest source of confidence is knowing you're ready. A prepared salesperson walks differently. But ready on day one and ready two weeks in are two different lists, and ticking nothing off the second one on your first shift is not a sign you are behind — it is a sign you are on the right list. Start here:",textEs:"La fuente más profunda de confianza es saber que estás listo. Un vendedor preparado camina diferente. Pero estar listo el primer día y estarlo a las dos semanas son dos listas distintas, y no marcar nada de la segunda en tu primer turno no significa que vayas atrasado — significa que vas por la lista correcta. Empieza por esta:"},{type:"checklist",items:["I know where to stand, how to get their attention while they are still four or five metres off, and the 3-second rule once they look at me","I have 3 different openers ready to go without thinking about them","I can run the whole first sequence out loud, in order, without looking at anything — greeting, sample, the rush line, the gift, turn and walk","I know which colleague I am handing people to when they come in, and I have told them I am about to start bringing people over"],itemsEs:["Sé dónde colocarme, cómo llamarles la atención cuando todavía están a cuatro o cinco metros, y la regla de los 3 segundos en cuanto me miran","Tengo 3 aperturas distintas listas para soltarlas sin pensar","Puedo soltar la secuencia entera en voz alta, en orden, sin mirar nada — saludo, muestra, lo de la prisa, el regalo, me giro y ando","Sé a qué compañero le paso a la gente cuando entra, y le he avisado de que voy a empezar a traerle gente"]},{type:"keypoint",text:"For your first two weeks that IS the whole list. You stop, you bring them in, you hand them to a colleague. No demo, no ladder, no price. Anybody who tells you that is not really selling has never tried to walk forty strangers through a door in a day — it is the hardest part of the job and everything else is built on top of it.",textEs:"Durante tus primeras dos semanas ESA es la lista entera. Paras, los metes dentro, se los pasas a un compañero. Sin demo, sin escalera, sin precio. Quien te diga que eso no es vender de verdad no ha intentado nunca meter a cuarenta desconocidos por una puerta en un día — es la parte más difícil del trabajo y todo lo demás se construye encima."},{type:"divider"},{type:"subheader",text:"When You Start Doing Demos Yourself",textEs:"Cuando Empieces a Hacer Demos Tú"},{type:"paragraph",text:"These four are not day-one items and they are not week-one items either. They start mattering the day a colleague hands the chair back to you. Each one lives in a lesson further up the ladder, named below, and you tick it once you have done that lesson — not before:",textEs:"Estos cuatro no son del primer día, y de la primera semana tampoco. Empiezan a importar el día en que un compañero te devuelve la silla. Cada uno vive en una lección más arriba en la escalera, que te indicamos abajo, y lo marcas cuando hayas hecho esa lección — no antes:"},{type:"checklist",items:["I can pitch the syringe from memory without hesitation, and the other three after it — Price Anchoring Psychology","I know every price point and offer combination by heart — Price Anchoring Psychology and The Two-Choice Framework","I know 5 common objections and my responses to each — Objection Handling Library","I've rehearsed my voucher close until it feels natural — The Voucher Close"],itemsEs:["Puedo presentar la jeringa de memoria sin dudar, y los otros tres después — Psicología del Anclaje de Precio","Me sé todos los precios y combinaciones de oferta de memoria — Psicología del Anclaje de Precio y El Marco de Dos Opciones","Me sé 5 objeciones comunes y mi respuesta para cada una — Biblioteca de Manejo de Objeciones","He ensayado mi cierre con cupón hasta que sale natural — El Cierre con Voucher"]},{type:"divider"},{type:"subheader",text:"Vocal Confidence Techniques",textEs:"Técnicas de Confianza Vocal"},{type:"bullets",items:["VOLUME: Speak 15-20% louder than your normal conversational voice. Quiet voices signal uncertainty. Projected voices command attention.","PACE: Nervous people talk fast. Slow your speech by 20%. Pauses feel longer to you than to the listener. A 2-second pause sounds thoughtful, not awkward.","TONE DOWN: End sentences with a slightly lower pitch. Upspeak (rising intonation at the end of statements) sounds like you're asking a question, which undermines authority.","BREATHING: Take a full breath before speaking. Shallow breathing creates shaky voices. Deep diaphragmatic breathing creates resonance and stability."],itemsEs:["VOLUMEN: Habla 15-20% mas fuerte que tu voz normal de conversación. Las voces bajas senalan incertidumbre. Las voces proyectadas comandan atención.","RITMO: La gente nerviosa habla rápido. Ralentiza tu habla un 20%. Las pausas se sienten mas largas para ti que para el oyente. Una pausa de 2 segundos suena pensativa, no incomoda.","TONO DESCENDENTE: Termina las oraciones con un tono ligeramente mas bajo. El tono ascendente (entonacion ascendente al final de las afirmaciones) suena como si estuvieras preguntando, lo que socava la autoridad.","RESPIRACION: Toma una respiracion completa antes de hablar. La respiracion superficial crea voces temblorosas. La respiracion diafragmatica profunda crea resonancia y estabilidad."]},{type:"tip",text:"Record yourself pitching on your phone. Listen back. Most people are shocked at how uncertain they sound. Do this weekly and track your improvement. Within a month, you'll hear the transformation.",textEs:"Grabate haciendo tu presentacion con el móvil. Escuchate de vuelta. La mayoria de la gente se sorprende de lo inseguro que suena. Haz esto semanalmente y rastrea tu mejora. Dentro de un mes, escucharas la transformacion."},{type:"quote",text:"Confidence is not 'they will like me.' Confidence is 'I'll be fine if they don't.'",textEs:"La confianza no es 'les voy a caer bien.' La confianza es 'voy a estar bien si no es asi.'",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"},{type:"divider"},{type:"subheader",text:"What to Do When Confidence Crashes",textEs:"Que Hacer Cuando la Confianza Se Derrumba"},{type:"paragraph",text:"Everyone has moments where their confidence evaporates — a string of rejections, a rude customer, a bad demo. When this happens, you need an emergency protocol:",textEs:"Todos tienen momentos donde su confianza se evapora — una serie de rechazos, un cliente grosero, una mala demo. Cuando esto sucede, necesitas un protocolo de emergencia:"},{type:"numbered",items:["STEP AWAY: Ask for a quick 2-minute bathroom break. Splash cold water on your face. The physical reset triggers a mental reset.","RECALL A WIN: Think of your best sale ever. Feel that moment again. Remember that you ARE capable.","ADJUST ONE THING: Don't try to fix everything. Pick ONE behavior — maybe your posture, maybe your smile — and focus only on that for the next 3 customers.","LOWER THE STAKES: Tell yourself 'I'm just practicing.' This removes the pressure and lets you be playful again."],itemsEs:["ALAJATE: Pide un rápido descanso de 2 minutos al bano. Echate agua fria en la cara. El reinicio físico desencadena un reinicio mental.","RECUERDA UNA VICTORIA: Piensa en tu mejor venta de todos los tiempos. Siente ese momento de nuevo. Recuerda que SI eres capaz.","AJUSTA UNA COSA: No intentes arreglarlo todo. Elige UN comportamiento — quizas tu postura, quizas tu sonrisa — y enfocate solo en eso para los siguientes 3 clientes.","REDUCE LAS APUESTAS: Dite a ti mismo 'solo estoy practicando.' Esto elimina la presion y te deja ser jugueton de nuevo."]},{type:"tip",text:"Create a 'confidence anchor' — a physical gesture paired with a powerful memory. For example, touching your thumb and forefinger together while remembering your best sale. After practicing this 20 times, the gesture alone triggers confidence.",textEs:"Crea un 'ancla de confianza' — un gesto físico emparejado con un recuerdo poderoso. Por ejemplo, juntar tu pulgar e indice mientras recuerdas tu mejor venta. Después de practicar esto 20 veces, el gesto solo desencadena confianza."}],quiz:[{question:"What is the ideal duration for maintaining eye contact with a customer?",options:["As long as possible to show dominance","Brief glances to avoid intimidation","2-3 seconds at a time","Only when closing the sale"],correctIndex:2,explanation:"The sweet spot for eye contact is 2-3 seconds at a time. Too short signals nervousness; too long feels aggressive. Brief, confident connection builds trust."},{question:"Why is upspeak (rising intonation at the end of statements) harmful in sales?",options:["It makes you sound friendly","It undermines your authority by making statements sound like questions","It's harder for customers to hear","It's culturally inappropriate"],correctIndex:1,explanation:"Upspeak makes statements sound like questions, which subconsciously undermines your authority and certainty. End sentences with a stable or slightly lower pitch."},{question:"What is the purpose of a 'confidence anchor'?",options:["To impress customers with jewelry","To trigger a confident state through a practiced physical gesture","To show your rank in the company","To remember your sales targets"],correctIndex:1,explanation:"A confidence anchor is a physical gesture paired with a powerful memory that, after repeated practice, can trigger a confident state on demand."}]},"psych-4":{id:"psych-4",categoryId:"psychology",title:"Rejection-Proof Mindset",titleEs:"Mentalidad a Prueba de Rechazo",subtitle:"The real numbers, the honest check, and when you actually get to put a no down",subtitleEs:"Los números de verdad, la comprobación honesta, y cuándo puedes soltar un no",duration:"8 min",icon:"Shield",order:4,xpReward:100,sections:[{type:"header",text:"Most of Them Say No — And You Still Have One Question to Answer",textEs:"La Mayoría Dice Que No — Y Aun Así Te Queda Una Pregunta"},{type:"paragraph",text:"If you step in front of 100 people in a day, around 80 will not even look at you, 15 will say 'no thanks', and a handful will buy. Those are the real numbers and nobody tells you them on your first day. But do not read them as comfort, because they are not comfort. Read them the other way round: if almost nobody stops, and most of the ones who do stop never buy, then the person already sitting in your chair is a rare thing. There is no queue of them behind her. You do not hurry her, you do not get bored halfway through her, and you do not let her wander off to have a think about it.",textEs:"Si te pones delante de 100 personas en un día, unas 80 ni te van a mirar, 15 te dirán 'no, gracias', y unas pocas comprarán. Esos son los números de verdad y nadie te los cuenta el primer día. Pero no los leas como consuelo, porque no son consuelo. Léelos al revés: si casi nadie para, y de los que paran casi ninguno compra, entonces la persona que ya está sentada en tu silla es algo raro. No hay una cola de ellas esperando detrás. Ni la metes prisa, ni te aburres a mitad de camino, ni la dejas irse a pensárselo."},{type:"keypoint",text:"Good sellers do know their numbers, and knowing them helps: if you close 1 in 15, then fourteen noes in a row is the shape of the job and not a verdict on you. But that only holds up if you genuinely gave those fourteen everything you had. The number is not a licence. Said BEFORE a demo, 'most of them say no anyway' is not perspective — it is an excuse, and it is the most expensive sentence a seller can learn.",textEs:"Los buenos vendedores sí se saben sus números, y saberlos ayuda: si cierras 1 de cada 15, catorce noes seguidos son la forma del trabajo y no un veredicto sobre ti. Pero eso solo se sostiene si de verdad les diste todo a esos catorce. El número no es una licencia. Dicho ANTES de una demo, 'total, la mayoría dice que no' no es perspectiva — es una excusa, y es la frase más cara que puede aprender un vendedor."},{type:"divider"},{type:"subheader",text:"Before You Put It Down: The Honest Check",textEs:"Antes de Soltarlo: La Comprobación Honesta"},{type:"paragraph",text:"When somebody walks without buying, there is exactly one useful question and it is not 'what is wrong with me'. It is: did I actually give that everything? Not 'was I nice'. Not 'did I try'. Everything. Answer it honestly and one of two things happens — either you have just found something to fix for the price of a single sale, which is cheap, or the answer really is 'I did all of it', and then it is not on you at all.",textEs:"Cuando alguien se va sin comprar, hay exactamente una pregunta útil y no es 'qué me pasa a mí'. Es: ¿le he dado de verdad todo lo que tengo? No 'he sido amable'. No 'lo he intentado'. Todo. Contéstala en serio y pasa una de dos cosas — o acabas de encontrar algo que arreglar al precio de una sola venta, que es barato, o la respuesta es de verdad 'lo he hecho todo', y entonces no es culpa tuya en absoluto."},{type:"checklist",items:["Did I say anything wrong, or promise something I should not have?","Did I skip a step — the hand, the one eye, the mirror, the two yeses, the ask?","Did I go quiet after the price, or get nervous and fill the silence?","Did I get lazy in the middle, once I had decided they were not buying?","Did I work the whole ladder, or stop early to save myself the effort?"],itemsEs:["¿He dicho algo que no debía, o he prometido algo que no toca?","¿Me he saltado un paso — la mano, el ojo, el espejo, los dos síes, el pedir?","¿Me he callado después del precio, o me he puesto nervioso y lo he llenado de ruido?","¿Me he vuelto perezoso a mitad, cuando ya había decidido que no iban a comprar?","¿He trabajado la escalera entera, o he parado antes para ahorrarme el esfuerzo?"]},{type:"keypoint",text:"If one of those is a yes, that is your lesson and it was a good day — you got it for free and it cost you one sale. Write it down and take it out to the next person. If none of them is a yes, put it down and go. That is the deal, and it only works in that order.",textEs:"Si alguna de esas es un sí, ahí tienes tu lección y ha sido un buen día — te la has llevado gratis y solo te ha costado una venta. Apúntala y sácala con la siguiente persona. Si ninguna es un sí, suéltalo y sigue. Ese es el trato, y solo funciona en ese orden."},{type:"comparison",left:{label:"Amateur Mindset",text:"'I'm terrible. 20 people said no today. I suck at this. Maybe I'm not cut out for sales.' No list, no check — just a story of failure that gets carried to the next customer."},leftEs:{label:"Mentalidad de Aficionado",text:"'Soy un desastre. Hoy me han dicho que no 20 personas. Se me da fatal. A lo mejor no sirvo para vender.' Sin lista, sin comprobación — solo una historia de fracaso que se lleva al siguiente cliente."},right:{label:"Pro Mindset",text:"'Twenty noes today. I ran the list on every one of them and I did the job. My ratio holds at 1 in 15. A couple more stops and I am probably due.' Each rejection is data — once it has been checked."},rightEs:{label:"Mentalidad Profesional",text:"'Hoy veinte noes. He repasado la lista con cada uno y he hecho mi trabajo. Mi ratio se mantiene en 1 de cada 15. Un par de paradas más y me toca.' Cada rechazo es un dato — una vez comprobado."}},{type:"divider"},{type:"subheader",text:"The 'Next One' Mentality",textEs:"La Mentalidad del 'Siguiente'"},{type:"paragraph",text:"The reset is the habit that keeps you alive through eight hours of this — but it comes SECOND, never first. The order is: they walk, you run the five questions in your head while they are still reaching the door, and only then do you wipe it and turn to the next person. Reset without the check is just forgetting, and a seller who forgets every no makes the same mistake for a year without noticing. Reset after the check is what lets you stay warm all day.",textEs:"El reinicio es el hábito que te mantiene vivo durante ocho horas de esto — pero va el SEGUNDO, nunca el primero. El orden es: se van, repasas las cinco preguntas en la cabeza mientras todavía llegan a la puerta, y solo entonces lo borras y te giras hacia la siguiente persona. Reiniciar sin comprobar es simplemente olvidar, y un vendedor que se olvida de cada no comete el mismo fallo durante un año sin enterarse. Reiniciar después de comprobar es lo que te deja seguir simpático todo el día."},{type:"script",text:"'I used to replay every rejection in my head. I'd still be thinking about the rude woman from 20 minutes ago while missing the friendly couple right in front of me. Now I have a rule: the moment someone walks away, I literally say 'next' under my breath. It clears my mental slate.'",textEs:"'Solia reproducir cada rechazo en mi cabeza. Seguia pensando en la mujer grosera de hace 20 minutos mientras perdia a la pareja amigable justo enfrente de mi. Ahora tengo una regla: en el momento en que alguien se aleja, literalmente digo 'siguiente' en voz baja. Limpia mi pizarra mental.'"},{type:"tip",text:"Practise it as two beats, not one. Beat one: the five questions, honestly, in the time it takes them to reach the door. Beat two: say 'next' under your breath and mean it. Most sellers only ever learn beat two, and that is exactly why somebody can work this floor for a year and finish it no better than they started.",textEs:"Practícalo en dos tiempos, no en uno. Tiempo uno: las cinco preguntas, en serio, en lo que tardan en llegar a la puerta. Tiempo dos: dices 'siguiente' en voz baja y lo dices de verdad. La mayoría solo aprende el tiempo dos, y por eso alguien puede pasarse un año en esta sala y acabarlo igual que lo empezó."},{type:"divider"},{type:"subheader",text:"When the List Comes Back Clean",textEs:"Cuando la Lista Sale Limpia"},{type:"paragraph",text:"You have been through the five and there is nothing on any of them. You did the demo properly, you got the two yeses, you asked for the money, you worked the ladder all the way to the bottom, you stayed warm to the last second — and she still walked. Fine. Then it is one of these, and not one of them is a thing you could have done differently:",textEs:"Has repasado las cinco y no hay nada en ninguna. Hiciste la demo bien, conseguiste los dos síes, pediste el dinero, bajaste la escalera hasta abajo del todo, estuviste simpático hasta el último segundo — y aun así se fue. Vale. Entonces es una de estas, y ninguna es algo que tú pudieras haber hecho distinto:"},{type:"bullets",items:["They are genuinely in a rush: a meeting, a reservation, a coach going in ten minutes. Nothing you say beats a departure time.","They have already spent it: budget exhaustion is real, and the best demo in the world will not open an empty wallet.","They do not buy anything on a trip: some people have that rule and they keep it, and it was decided before they met you.","They walked in on somebody else's bad day: a row an hour ago, bad news this morning. They were never really in the chair.","They are just a bad customer: enjoyed the free treatment, said yes to everything, was never going to pay. They exist. Part of the game."],itemsEs:["Van de verdad con prisa: una reunión, una reserva, un autobús que sale en diez minutos. Contra una hora de salida no hay frase que valga.","Ya se lo han gastado: el presupuesto agotado es real, y la mejor demo del mundo no abre una cartera vacía.","No compran nada de viaje: hay gente con esa regla y la cumple, y eso lo decidieron antes de conocerte.","Te han caído en el mal día de otro: una bronca hace una hora, una mala noticia esta mañana. Nunca estuvieron de verdad en la silla.","Son simplemente un mal cliente: han disfrutado del tratamiento gratis, han dicho que sí a todo y nunca iban a pagar. Los hay. Forma parte del juego."]},{type:"keypoint",text:"That is the absolution — and notice where it sits. At the END, after the list, never before the demo. You do not get to reach for it first. A seller who starts the shift already telling themselves 'most of them say no anyway' has taken the comfort without doing the work, and it will cost them every close-run sale of the day. The full version of this lives in It Is Not On You — If You Did Everything.",textEs:"Esa es la absolución — y fíjate dónde está. Al FINAL, después de la lista, nunca antes de la demo. No puedes echar mano de ella la primera. Un vendedor que empieza el turno diciéndose 'total, la mayoría dice que no' se ha quedado el consuelo sin hacer el trabajo, y le va a costar todas las ventas ajustadas del día. La versión completa está en No Es Culpa Tuya — Si Lo Hiciste Todo."},{type:"divider"},{type:"subheader",text:"How Top Sellers Process a Bad Day",textEs:"Como los Mejores Vendedores Procesan un Mal Día"},{type:"paragraph",text:"Even the best have terrible days. Here's the protocol that separates pros from amateurs:",textEs:"Incluso los mejores tienen días terribles. Aquí esta el protocolo que separa a los profesionales de los aficionados:"},{type:"numbered",items:["DON'T TAKE IT HOME: The moment you clock out, the day is done. Don't replay rejections in your head all evening. That day doesn't exist anymore.","FIND ONE WIN: Even on the worst day, find ONE thing you did well. Maybe your opener was smooth. Maybe your demo was great even though they didn't buy. Focus on that.","ANALYZE PATTERNS: If you're getting rejected more than usual, look for patterns. Is your energy low? Are you stopping the wrong people? Is your opener tired? Fix the mechanics, not your self-worth.","SLEEP IT OFF: A bad day feels like a crisis at 6pm and often feels like nothing the next morning. Never make career decisions based on one bad shift.","TALK TO TEAMMATES: Everyone has bad days. Sharing yours normalizes it. Hearing that your colleague also got rejected 30 times makes you feel less alone."],itemsEs:["NO TE LO LLEVES A CASA: En el momento en que fichas tu salida, el día se acabo. No repitas los rechazos en tu cabeza toda la noche. Ese día ya no existe.","ENCUENTRA UNA VICTORIA: Incluso en el peor día, encuentra UNA cosa que hiciste bien. Quizas tu apertura fue fluida. Quizas tu demo estuvo genial aunque no compraron. Enfocate en eso.","ANALIZA PATRONES: Si te están rechazando mas de lo usual, busca patrones. Esta baja tu energía? Estas deteniendo a las personas equivocadas? Tu apertura esta cansada? Arregla la mecanica, no tu autoestima.","DUERMETELO: Un mal día se siente como una crisis a las 6pm y a menudo no significa nada a la manana siguiente. Nunca tomes decisiones de carrera basadas en un mal turno.","HABLA CON TUS COMPANEROS: Todos tienen malos días. Compartir los tuyos lo normaliza. Escuchar que tu companero también fue rechazado 30 veces te hace sentir menos solo."]},{type:"divider"},{type:"subheader",text:"Turning a Bad Day Around",textEs:"Cambiar un Mal Día"},{type:"paragraph",text:"Sometimes you can actually SAVE a bad day. Here's the emergency turnaround protocol:",textEs:"A veces puedes realmente SALVAR un mal día. Aquí esta el protocolo de emergencia para darle la vuelta:"},{type:"bullets",items:["CHANGE ONE THING: If you've been using the same opener all day and getting rejected, switch it completely. New energy breaks the pattern.","TARGET DIFFERENT PEOPLE: If you've been stopping solo women and failing, try couples. Or vice versa. Different demographics respond to different energies.","GO BACK TO BASICS: When everything falls apart, simplify. Stop overthinking. Smile, make eye contact, deliver your cleanest opener. Fundamentals fix slumps.","ASK A TEAMMATE TO WATCH YOU: Sometimes you have a blind spot. A colleague might notice you're rushing, or your posture has collapsed, or you're not making eye contact. External feedback is gold."],itemsEs:["CAMBIA UNA COSA: Si has estado usando la misma apertura todo el día y te rechazan, cambiala completamente. La energía nueva rompe el patron.","APUNTA A DIFERENTES PERSONAS: Si has estado deteniendo a mujeres solas y fallando, prueba con parejas. O viceversa. Diferentes demografias responden a diferentes energias.","VUELVE A LO BASICO: Cuando todo se desmorona, simplifica. Deja de pensar demasiado. Sonrie, haz contacto visual, lanza tu apertura mas limpia. Los fundamentos arreglan los bajones.","PIDE A UN COMPANERO QUE TE OBSERVE: A veces tienes un punto ciego. Un colega podría notar que te estas apresurando, o que tu postura se ha derrumbado, o que no estas haciendo contacto visual. La retroalimentacion externa es oro."]},{type:"quote",text:"The only difference between a top seller and a quitter is that the top seller kept going through the days they wanted to quit.",textEs:"La única diferencia entre un top vendedor y alguien que se rinde es que el top vendedor siguio adelante en los días que quiso rendirse.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"},{type:"tip",text:"Track your numbers daily. Write down: stops, demos, closes, total revenue. Over time, you'll see your personal ratio. When you KNOW that you close 1 in 15, the 14 rejections before your next sale become... expected. Peaceful, even.",textEs:"Rastrea tus numeros diariamente. Anota: detenciones, demos, cierres, ingreso total. Con el tiempo, veras tu ratio personal. Cuando SABES que cierras 1 de cada 15, los 14 rechazos antes de tu siguiente venta se vuelven... esperados. Pacificos, incluso."}],quiz:[{question:"If your close rate is 5%, how should you view a string of 10 rejections?",options:["As proof you're having a bad day","As statistical progress toward your next sale","As a sign you need to change your pitch completely","As a reason to take a long break"],correctIndex:1,explanation:"With a 5% close rate, every 'no' is simply 5% of a 'yes.' A string of rejections is expected statistical progress toward your next close, not evidence of failure."},{question:"What is the 'next one' mentality?",options:["Always focusing on the next customer while ignoring the current one","Instantly resetting your focus to the next person after each rejection","Trying to stop the next person you see regardless of quality","Planning your next day during your shift"],correctIndex:1,explanation:"The 'next one' mentality is an instantaneous mental reset. The moment a customer walks away, that interaction is erased and total focus shifts to the next person approaching."},{question:"Which of these is the LEAST likely reason a customer says 'no'?",options:["They're in a hurry or have a reservation","They don't buy anything while traveling","You personally are unlikeable","They're overwhelmed from shopping"],correctIndex:2,explanation:"Rejection is almost never personal. Customers say no due to timing, budget, mood, travel habits, or overwhelm. Believing it's about your personality is the amateur mindset that destroys performance."}]},"psych-5":{id:"psych-5",categoryId:"psychology",title:"The Mirror Effect",titleEs:"El Efecto Espejo",subtitle:"Emotional contagion. Why YOUR mood becomes THEIR mood. The shop as an energy ecosystem.",subtitleEs:"La gente compra de gente que le gusta",duration:"8 min",icon:"Heart",order:5,xpReward:100,sections:[{type:"header",text:"Your Mood Is Contagious — Choose What You Spread",textEs:"Tu Estado de Ánimo es Contagioso — Elige Qué Transmitir"},{type:"paragraph",text:"Have you ever walked into a room and instantly felt tense? Or walked into another room and felt relaxed? That's emotional contagion — the phenomenon where humans automatically 'catch' the emotions of those around them. On the sales floor, YOU are the source of emotional contagion. Your frustration, excitement, calm, or anxiety spreads to customers like a virus.",textEs:"¿Alguna vez entraste a un cuarto y de inmediato sentiste tensión? O entraste a otro y sentiste relajación? Eso es contagio emocional — el fenómeno por el cual los humanos 'captan' automáticamente las emociones de quienes nos rodean. En el piso de ventas, TÚ eres la fuente del contagio emocional. Tu frustración, emoción, calma o ansiedad se transmite a los clientes como un virus."},{type:"keypoint",text:"Emotional contagion happens through micro-expressions, vocal tone, body posture, and even pheromones. Customers don't consciously read your mood — they FEEL it. A frustrated seller creates guarded customers. An excited seller creates curious customers.",textEs:"El contagio emocional ocurre a través de microexpresiones, tono de voz, postura corporal e incluso feromonas. Los clientes no leen tu estado de ánimo conscientemente — lo SIENTEN. Un vendedor frustrado genera clientes a la defensiva. Un vendedor entusiasmado genera clientes curiosos."},{type:"divider"},{type:"subheader",text:"You Catch It Off Each Other",textEs:"Se Contagia y Ya Está"},{type:"paragraph",text:"You already know this one. Stand next to somebody in a foul mood for two minutes and you are in one. Customers catch yours before you have opened your mouth — from three metres, straight off your face. Come out heavy and they go guarded. Come out light and they come closer. That is the whole lesson.",textEs:"Esto ya te lo sabes. Ponte dos minutos al lado de alguien de mal humor y ya estás de mal humor. Los clientes te lo pillan antes de que abras la boca — desde tres metros, directamente de la cara. Sal pesado y se ponen a la defensiva. Sal ligero y se acercan. Esa es toda la lección."},{type:"paragraph",text:"When you approach a customer with tight facial muscles and a flat voice, they unconsciously mirror that tension. Their guard goes up. When you approach with genuine warmth and energy, they mirror that openness. The sale becomes possible.",textEs:"Cuando te acercas a un cliente con los músculos faciales tensos y una voz plana, ellos reflejan esa tensión inconscientemente. Se ponen a la defensiva. Cuando te acercas con calidez genuina y energía, reflejan esa apertura. La venta se vuelve posible."},{type:"tip",text:"Before you approach ANY customer, check your face. Are you smiling? Is your forehead relaxed? Are your eyes soft? Customers decide whether to trust you in the first 2 seconds — mostly from your facial expression.",textEs:"Antes de acercarte a CUALQUIER cliente, revisa tu cara. ¿Estás sonriendo? ¿Tu frente está relajada? ¿Tus ojos son suaves? Los clientes deciden si confiar en ti en los primeros 2 segundos — principalmente por tu expresión facial."},{type:"divider"},{type:"subheader",text:"Managing Frustration on the Floor",textEs:"Manejando la Frustración en el Piso de Ventas"},{type:"paragraph",text:"Frustration is the most dangerous emotion on the sales floor. It spreads fast and kills sales. After three rejections in a row, frustration builds. Your shoulders tense. Your smile fades. Your voice tightens. Now the fourth customer feels that heaviness and rejects you too. It's a spiral.",textEs:"La frustración es la emoción más peligrosa en el piso de ventas. Se propaga rápido y mata las ventas. Después de tres rechazos seguidos, la frustración crece. Tus hombros se tensan. Tu sonrisa se desvanece. Tu voz se tensa. Ahora el cuarto cliente siente esa pesadez y también te rechaza. Es una espiral."},{type:"bullets",items:["RECOGNIZE THE SPIRAL: The first step is awareness. Notice when your shoulders tense, when your breathing becomes shallow, when you start thinking 'this is pointless.'","BREAK THE PHYSICAL PATTERN: Frustration lives in your body. Shake your hands out. Roll your shoulders. Take 3 deep breaths. Physical reset creates emotional reset.","CHANGE YOUR SELF-TALK: Instead of 'this sucks,' try 'I'm due for a win.' Instead of 'nobody's buying today,' try 'the right customer is coming.' Your brain believes what you tell it.","SEEK POSITIVE INPUT: Talk to an upbeat teammate. Their energy will pull you out of the frustration spiral. Energy is contagious in BOTH directions."],itemsEs:["RECONOCE LA ESPIRAL: El primer paso es la conciencia. Nota cuándo se tensan tus hombros, cuándo tu respiración se vuelve superficial, cuándo empiezas a pensar 'esto no tiene sentido'.","ROMPE EL PATRÓN FÍSICO: La frustración vive en tu cuerpo. Sacude las manos. Gira los hombros. Toma 3 respiraciones profundas. El reinicio físico crea el reinicio emocional.",`CAMBIA TU DIÁLOGO INTERNO: En lugar de 'esto es una porquería', prueba 'me toca ganar'. En lugar de 'nadie compra hoy', prueba "el cliente indicado está por llegar". Tu cerebro cree lo que le dices.`,"BUSCA ESTÍMULOS POSITIVOS: Habla con un compañero con buena energía. Su energía te sacará de la espiral de frustración. La energía es contagiosa en AMBAS direcciones."]},{type:"divider"},{type:"subheader",text:"Excitement vs. Calm: When to Use Which",textEs:"Entusiasmo vs. Calma: Cuándo Usar Cada Uno"},{type:"comparison",left:{label:"High Energy / Excitement",text:"Best for: groups, holiday crowds, the first sale of the day, younger customers, anybody already laughing. Creates urgency and fun. Risks: it can flatten a quiet, analytical buyer, and it tips into pushy the moment you keep it up after they have gone still."},leftEs:{label:"Alta Energía / Entusiasmo",text:"Ideal para: grupos, multitudes de vacaciones, la primera venta del día, clientes jóvenes, cualquiera que ya venga riéndose. Crea urgencia y diversión. Riesgos: puede aplastar a una clienta callada y analítica, y se vuelve agresiva en cuanto sigues con ella después de que se hayan quedado quietos."},right:{label:"Calm / Warm Energy",text:"Best for: couples, older customers, somebody who came in wary, the one who asks a lot of questions. Creates trust and sophistication. Risks: it reads as flat if you are not genuinely present, and without real listening behind it, it is not calm — it is just slow."},rightEs:{label:"Energía Tranquila / Cercana",text:"Ideal para: parejas, clientes mayores, alguien que ha entrado con la mosca detrás de la oreja, el que pregunta mucho. Genera confianza y elegancia. Riesgos: parece falta de energía si no estás de verdad presente, y sin escucha real detrás no es calma — es lentitud."}},{type:"keypoint",text:"And never read the clock as an instruction. A dead hour is not permission to drop into second gear — it is the hour you try hardest, because the two people who walk past in it might be all you get today, and you work somebody you would happily wave through on a Saturday. A packed hour is the opposite: tighten everything, do not grind water, because the second you finish this one there is another one outside the door.",textEs:"Y no leas nunca el reloj como si fuera una instrucción. Una hora muerta no es permiso para meter segunda — es la hora en la que más lo intentas, porque las dos personas que pasen igual son todo lo que te va a dar el día, y trabajas a alguien al que un sábado dejarías pasar sin más. Una hora a tope es lo contrario: aprieta todo, no le des vueltas al agua, porque en cuanto termines con esta hay otra fuera esperando."},{type:"tip",text:"Match the customer's energy, then lift it a notch. If they are calm and thoughtful, be calm and warm — with a spark under it. If they are loud and laughing, meet them there and go one better. What you are matching is the person in front of you, never the state of the shop behind you.",textEs:"Iguala la energía del cliente y luego súbela un punto. Si viene tranquila y reflexiva, ve tranquilo y cálido — pero con una chispa debajo. Si viene alto y riéndose, ponte a su altura y súbelo un poco más. Lo que igualas es a la persona que tienes delante, nunca cómo esté la tienda detrás de ti."},{type:"divider"},{type:"subheader",text:"The Shop as an Energy Ecosystem",textEs:"La Tienda como un Ecosistema de Energía"},{type:"paragraph",text:"The shop isn't just a collection of individuals — it's an energy ecosystem. When one person is closing a sale with excitement, that energy lifts everyone. When one person is slumped and frustrated, that energy drags everyone down. Top shops understand this and protect the collective energy fiercely.",textEs:"La tienda no es solo un conjunto de individuos — es un ecosistema de energía. Cuando alguien cierra una venta con emoción, esa energía levanta a todos. Cuando alguien está decaído y frustrado, esa energía arrastra a todos. Las mejores tiendas entienden esto y protegen ferozmente la energía colectiva."},{type:"bullets",items:["CELEBRATE WINS LOUDLY: When a teammate closes, cheer for them. The celebration creates positive emotional contagion for the whole shop.","NEVER VENT ON THE FLOOR: If you need to complain, do it in the back room. Complaining in the customer area poisons the energy ecosystem.","HELP THE STRUGGLING TEAMMATE: If you see a colleague's energy crashing, switch with them. Give them a moment to reset. The whole shop benefits when everyone's energy is up.","PROTECT THE FIRST HOUR: No breaks, no negativity, no slacking in the first hour. It sets the energy tone for the entire day."],itemsEs:["CELEBRA LAS VICTORIAS EN VOZ ALTA: Cuando un compañero cierra una venta, apláudelo. La celebración crea contagio emocional positivo para toda la tienda.","NUNCA DESAHÓGATE EN EL PISO: Si necesitas quejarte, hazlo en el cuarto de atrás. Quejarte en el área de clientes envenena el ecosistema de energía.","AYUDA AL COMPAÑERO QUE LUCHA: Si ves que la energía de un colega se está derrumbando, cúbrele. Dale un momento para reiniciarse. Toda la tienda se beneficia cuando la energía de todos está al alza.","PROTEGE LA PRIMERA HORA: Sin descansos, sin negatividad, sin flojera en la primera hora. Establece el tono energético para todo el día."]},{type:"quote",text:"You're not just selling a product. You're selling a feeling. And the feeling starts with you.",textEs:"No solo estás vendiendo un producto. Estás vendiendo una sensación. Y la sensación empieza contigo.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"},{type:"subheader",text:"Daily Energy Audit",textEs:"Auditoría Diaria de Energía"},{type:"paragraph",text:"At the end of each shift, ask yourself these three questions:",textEs:"Al final de cada turno, hazte estas tres preguntas:"},{type:"numbered",items:["What energy did I bring to the floor today? Was I excited, calm, frustrated, distracted?","How did customers respond to my energy? Were they open and warm, or guarded and distant?","What one thing can I do tomorrow to bring better energy? (Sleep earlier, eat better, listen to music, talk to a friend before work?)"],itemsEs:["¿Qué energía traje al piso hoy? ¿Estaba emocionado, calmado, frustrado, distraído?","¿Cómo respondieron los clientes a mi energía? ¿Estuvieron abiertos y cálidos, o a la defensiva y distantes?","¿Qué puedo hacer mañana para traer mejor energía? (¿dormir más temprano, comer mejor, escuchar música, hablar con un amigo antes del trabajo?)"]},{type:"tip",text:"Keep a small notebook and track your mood and your sales for two weeks. You'll likely discover a clear pattern: your best sales days correlate strongly with your best energy days. This data becomes powerful motivation to prioritize your own wellbeing.",textEs:"Lleva una libreta pequeña y registra tu estado de ánimo y tus ventas durante dos semanas. Es probable que descubras un patrón claro: tus mejores días de venta se correlacionan fuertemente con tus mejores días de energía. Estos datos se convierten en una motivación poderosa para priorizar tu propio bienestar."}],quiz:[{question:"When does a customer first pick up your mood?",options:["Once you have been chatting for a minute or two","Before you have said a word","Only when you tell them how your day is going","After the demo, when they see the result in the mirror"],correctIndex:1,explanation:"They catch it off your face from three metres, before you open your mouth. Come out heavy and they go guarded; come out light and they come closer."},{question:"When is calm, warm energy most appropriate?",options:["With young groups and holiday shoppers","With couples, older customers, and serious buyers","Never — high energy always wins","Only when you're tired"],correctIndex:1,explanation:"Calm, warm energy works best with couples, older customers, and serious buyers. It creates trust and sophistication. Match the customer's energy, then slightly elevate it."},{question:"Why should you never vent frustration on the sales floor?",options:["The manager will hear you","It poisons the energy ecosystem for everyone including customers","Customers might complain","It's unprofessional but doesn't affect sales"],correctIndex:1,explanation:"The shop is an energy ecosystem. Complaining on the floor creates negative emotional contagion that affects teammates and customers. Vent in the back room, never in customer areas."}]},"psych-6":{id:"psych-6",categoryId:"psychology",title:"Your Life Outside Work",titleEs:"Tu Vida Fuera del Trabajo",subtitle:"Exercise, sleep, nutrition, social life — how taking care of yourself makes you a better seller",subtitleEs:"El descanso es parte del rendimiento",duration:"8 min",icon:"Sparkles",order:6,xpReward:100,sections:[{type:"header",text:"The Best Salespeople Take Care of Themselves",textEs:"Los Mejores Vendedores se Cuidan a Sí Mismos"},{type:"paragraph",text:"A seller on four hours' sleep, a bad lunch and no daylight is a seller who is slow on the door and flat in the chair. Everything you turn up with was built outside the shop. And you are on commission: a bad night costs you real money the next day. That is the whole argument.",textEs:"Un vendedor con cuatro horas de sueño, una mala comida y sin ver la luz del día es un vendedor lento en la puerta y apagado en la silla. Todo lo que traes puesto se ha construido fuera de la tienda. Y estás a comisión: una mala noche te cuesta dinero de verdad al día siguiente. Ese es todo el argumento."},{type:"keypoint",text:"You are on commission, so the maths is not complicated: tired means slower on the door, flatter in the chair, quicker to give up on the ladder. Every one of those is a sale you would otherwise have had, and the sales you lose that way are not on the customer. Sleep is not self-care here. It is stock.",textEs:"Estás a comisión, así que la cuenta no tiene misterio: cansado significa más lento en la puerta, más apagado en la silla y más rápido en rendirte con la escalera. Cada una de esas cosas es una venta que habrías tenido, y las ventas que pierdes así no son culpa del cliente. Aquí dormir no es cuidarse. Es mercancía."},{type:"divider"},{type:"subheader",text:"Sleep: The Foundation of Everything",textEs:"Sueño: La Base de Todo"},{type:"paragraph",text:"Sleep deprivation affects the prefrontal cortex — the part of your brain responsible for decision-making, emotional regulation, and social interaction. In other words, it destroys the exact skills you need for sales. After a poor night's sleep:",textEs:"La privación de sueño afecta la corteza prefrontal — la parte de tu cerebro responsable de la toma de decisiones, la regulación emocional y la interacción social. En otras palabras, destruye exactamente las habilidades que necesitas para vender. Después de una mala noche de sueño:"},{type:"bullets",items:["Your skin gets thinner. The same no that bounced off you at ten in the morning stings at six.","Your facial expressions become flatter and less genuine. Customers notice.","Your verbal fluency decreases. Words don't come as easily.","Your motivation and drive plummet. You stop more hesitantly."],itemsEs:["Se te pone la piel más fina. El mismo no que a las diez de la mañana te resbalaba, a las seis escuece.","Tus expresiones faciales se vuelven más planas y menos genuinas. Los clientes se dan cuenta.","Tu fluidez verbal disminuye. Las palabras no salen tan fácilmente.","Tu motivación y empuje se desploman. Te detienes de forma más vacilante."]},{type:"tip",text:"Aim for 7-8 hours of sleep. If you have a late night before an early shift, a 20-minute power nap before work can restore significant cognitive function. The 20-minute length is critical — longer naps create grogginess.",textEs:"Apunta a 7-8 horas de sueño. Si tienes una noche larga antes de un turno temprano, una siesta rápida de 20 minutos antes del trabajo puede restaurar una función cognitiva significativa. La duración de 20 minutos es crítica — siestas más largas crean aturdimiento."},{type:"divider"},{type:"subheader",text:"Exercise: Your Energy Multiplier",textEs:"Ejercicio: Tu Multiplicador de Energía"},{type:"paragraph",text:"You don't need to be an athlete. You need consistent movement that builds energy and reduces stress. The best exercise for salespeople is anything that gets your heart rate up and your mood elevated.",textEs:"No necesitas ser atleta. Necesitas movimiento consistente que genere energía y reduzca el estrés. El mejor ejercicio para vendedores es cualquiera que acelere tu ritmo cardíaco y eleve tu estado de ánimo."},{type:"bullets",items:["CARDIO (running, cycling, dancing): Builds baseline energy and lung capacity. Better breathing = better voice projection and calmer nerves.","STRENGTH TRAINING: Builds confidence through physical capability. Standing tall with good posture is easier with a strong back and core.","YOGA / STRETCHING: Reduces physical tension that accumulates during shifts. A relaxed body creates a relaxed presence.","WALKING: Even a 20-minute walk after work helps process the day's stress and transition out of 'work mode.'"],itemsEs:["CARDIO (correr, ciclismo, bailar): Construye energía base y capacidad pulmonar. Mejor respiración = mejor proyección de voz y nervios más calmados.","ENTRENAMIENTO DE FUERZA: Construye confianza a través de la capacidad física. Mantenerse erguido con buena postura es más fácil con una espalda y núcleo fuertes.","YOGA / ESTIRAMIENTOS: Reduce la tensión física que se acumula durante los turnos. Un cuerpo relajado crea una presencia relajada.","CAMINAR: Incluso una caminata de 20 minutos después del trabajo ayuda a procesar el estrés del día y a salir del 'modo trabajo'."]},{type:"tip",text:"The best time to exercise for sales performance is BEFORE your shift, even if just 10 minutes of jumping jacks and stretching. This elevates your energy when you need it most. If mornings are impossible, exercise on your days off to build baseline energy.",textEs:"El mejor momento para ejercitarte para el rendimiento en ventas es ANTES de tu turno, aunque sean solo 10 minutos de jumping jacks y estiramientos. Esto eleva tu energía cuando más la necesitas. Si las mañanas son imposibles, haz ejercicio en tus días libres para construir energía base."},{type:"divider"},{type:"subheader",text:"Nutrition: Fuel for Performance",textEs:"Nutrición: Combustible para el Rendimiento"},{type:"paragraph",text:"What you eat directly affects your brain function, mood stability, and energy levels. A sugary breakfast creates a mid-morning crash. A heavy lunch creates afternoon fog. Smart nutrition is strategic.",textEs:"Lo que comes afecta directamente tu función cerebral, estabilidad del estado de ánimo y niveles de energía. Un desayuno azucarado causa un bajón a media mañana. Un almuerzo pesado causa niebla mental en la tarde. La nutrición inteligente es estratégica."},{type:"numbered",items:["BREAKFAST: Protein + complex carbs. Eggs with whole grain toast, Greek yogurt with nuts, or a protein smoothie. Avoid pastries and sugary cereals — they create a crash by 10am.","DURING SHIFT: Light snacks. Nuts, fruit, protein bars. Avoid heavy meals during breaks. A salad with chicken is perfect. Pizza will make you sluggish.","HYDRATION: Water is your #1 performance tool. Dehydration causes fatigue, headaches, and poor concentration. Keep a water bottle on the floor.","AFTER WORK: Eat to recover, not to reward. A nutritious dinner helps you sleep better and wake up with more energy. The 'I deserve junk food after a hard day' mindset sabotages tomorrow's performance."],itemsEs:["DESAYUNO: Proteína + carbohidratos complejos. Huevos con pan integral, yogur griego con nueces, o un licuado de proteína. Evita pan dulce y cereales azucarados — te causan un bajón a las 10am.","DURANTE EL TURNO: Snacks ligeros. Nueces, fruta, barras de proteína. Evita comidas pesadas durante los descansos. Una ensalada con pollo es perfecta. La pizza te hará sentir lento.","HIDRATACIÓN: El agua es tu herramienta de rendimiento #1. La deshidratación causa fatiga, dolores de cabeza y mala concentración. Mantén una botella de agua en el piso.","DESPUÉS DEL TRABAJO: Come para recuperarte, no para recompensarte. Una cena nutritiva te ayuda a dormir mejor y despertar con más energía. La mentalidad de 'me merezco comida chatarra después de un día duro' sabotea el rendimiento de mañana."]},{type:"divider"},{type:"subheader",text:"Social Life & Mental Health",textEs:"Vida Social y Salud Mental"},{type:"paragraph",text:"Sales is emotionally demanding. You're performing all day — smiling, engaging, handling rejection. You need people who recharge you, not drain you. A supportive social circle is essential for long-term performance.",textEs:"Las ventas exigen emocionalmente. Estás actuando todo el día — sonriendo, interactuando, manejando el rechazo. Necesitas personas que te recarguen, no que te drenen. Un círculo social de apoyo es esencial para el rendimiento a largo plazo."},{type:"bullets",items:["SPEND TIME WITH PEOPLE WHO ENERGIZE YOU: After a day of giving energy to customers, you need people who fill your cup. Limit time with people who complain, criticize, or drain you.","PROCESS REJECTION WITH FRIENDS: Talk about your bad days. Normalize the experience. A friend who says 'that sounds tough, but I know you'll crush it tomorrow' is worth their weight in gold.","HAVE NON-SALES CONVERSATIONS: Don't let your whole identity become selling. Talk about movies, sports, philosophy, travel. A well-rounded mind is a more interesting salesperson.","CREATE RITUALS: Weekly dinner with friends, a hobby class, a sports team. Scheduled activities ensure you're building a life outside work, not just recovering from it."],itemsEs:["PASATIEMPO CON PERSONAS QUE TE ENERGIZAN: Después de un día dando energía a clientes, necesitas personas que te llenen el tanque. Limita el tiempo con personas que se quejan, critican o te drenan.","PROCESA EL RECHAZO CON AMIGOS: Habla de tus malos días. Normaliza la experiencia. Un amigo que dice 'suena difícil, pero sé que la romperás mañana' vale su peso en oro.","TEN CONVERSACIONES QUE NO SEAN DE VENTAS: No dejes que toda tu identidad se convierta en vender. Habla de películas, deportes, filosofía, viajes. Una mente cultivada es un vendedor más interesante.","CREA RITUALES: Cena semanal con amigos, una clase de hobby, un equipo deportivo. Las actividades programadas aseguran que estás construyendo una vida fuera del trabajo, no solo recuperándote de él."]},{type:"divider"},{type:"subheader",text:"Where You Actually Learn This",textEs:"Dónde se Aprende Esto de Verdad"},{type:"paragraph",text:"You will not find this job in a book. You will find it about four metres away from you, every single shift:",textEs:"Este trabajo no lo vas a encontrar en un libro. Lo tienes a unos cuatro metros de ti, en cada turno:"},{type:"bullets",items:["WATCH THE BEST SELLER ON THIS STREET FOR ONE SHIFT: Not what they say — what they do with their hands, and how quickly they let somebody go. Four hours of that beats four books.","GO AND BE A CUSTOMER SOMEWHERE: A shop, a market, a bar. Notice the exact thing that made you stop, and the exact thing that made you want to leave. Steal the first one, never do the second.","STEAL FROM OTHER TRADES: How a good waiter reads a table before anybody has ordered. How a doorman greets somebody he has never met. Same job as yours, different uniform."],itemsEs:["OBSERVA UN TURNO ENTERO AL QUE MEJOR VENDE DE ESTA CALLE: No lo que dice — lo que hace con las manos, y lo rápido que deja marchar a alguien. Cuatro horas de eso valen más que cuatro libros.","VE A SER CLIENTE A ALGÚN SITIO: Una tienda, un mercado, un bar. Fíjate en qué te hizo pararte exactamente, y en qué te dio ganas de irte. Róbate lo primero y no hagas nunca lo segundo.","RÓBALE A OTROS OFICIOS: Cómo un buen camarero lee una mesa antes de que nadie haya pedido. Cómo un portero saluda a alguien a quien no ha visto en su vida. El mismo trabajo que el tuyo con otro uniforme."]},{type:"tip",text:"One thing a week. Watch one person, or go and be a customer once, and take exactly one thing away from it. In six months that is twenty-odd moves that are yours, and not one of them came out of a book.",textEs:"Una cosa por semana. Observa a una persona, o vete a ser cliente una vez, y llévate exactamente una cosa. En seis meses eso son veintitantas jugadas que son tuyas, y ninguna ha salido de un libro."},{type:"quote",text:"Taking care of yourself isn't selfish — it's your most profitable investment. A well-rested, well-fed, well-exercised salesperson is a money-making machine.",textEs:"Cuidarte a ti mismo no es egoísta — es tu inversión más rentable. Un vendedor bien descansado, bien alimentado y bien ejercitado es una máquina de hacer dinero.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"How does sleep deprivation specifically affect sales performance?",options:["It only makes you feel tired but doesn't affect sales","It reduces emotional resilience, verbal fluency, and facial expressiveness","It actually improves performance because you're more desperate for commission","It only affects your ability to close big sales"],correctIndex:1,explanation:"Sleep deprivation affects the prefrontal cortex, reducing emotional resilience, verbal fluency, and making facial expressions flatter. These are exactly the skills needed for sales."},{question:"Why is exercise particularly valuable for salespeople?",options:["It helps you look better in the uniform","It builds energy, lung capacity for voice projection, and confidence","It's required by company policy","It gives you something to talk about with customers"],correctIndex:1,explanation:"Exercise builds baseline energy, improves breathing for better voice projection, and builds confidence through physical capability — all directly relevant to sales performance."},{question:"What type of lunch should you eat to maintain afternoon energy?",options:["Pizza or pasta for satisfaction","A heavy meal to feel full","Light protein, salad, and fruit","Skip lunch and power through"],correctIndex:2,explanation:"Heavy meals redirect blood from the brain to the stomach, causing afternoon fog. Light protein, salads, and fruit provide sustained energy without the crash."}]},"psych-7":{id:"psych-7",categoryId:"psychology",title:"The Science of Persuasion",titleEs:"La Ciencia de la Persuasión",subtitle:"Cialdini's 6 principles applied to YOUR floor — with real examples for each",subtitleEs:"Los 6 principios de Cialdini aplicados a TU calle — con un ejemplo real de cada uno",duration:"10 min",icon:"Brain",order:7,xpReward:150,sections:[{type:"header",text:"The 6 Weapons of Influence — On Your Floor, Today",textEs:"Las 6 Armas de la Influencia — En Tu Piso, Hoy"},{type:"paragraph",text:"Dr. Robert Cialdini spent decades researching what makes people say 'yes.' He identified six universal principles of persuasion that work across all cultures and contexts. Every single one of them is happening on your sales floor — either by accident or by design. Master them, and you control the conversation.",textEs:"El Dr. Robert Cialdini pasó décadas investigando qué hace que la gente diga 'sí'. Identificó seis principios universales de la persuasión que funcionan en todas las culturas y contextos. Cada uno de ellos está ocurriendo en tu piso de ventas — ya sea por accidente o a propósito. Domínalos y controlarás la conversación."},{type:"keypoint",text:"None of this is new. Every trader in every market on earth has been using these six since long before anybody gave them names — Cialdini just wrote them down and got famous for it. You are already doing three of them by accident. Here is what all six sound like on your pavement.",textEs:"Nada de esto es nuevo. Todos los vendedores de todos los mercados del mundo llevan usando estas seis desde mucho antes de que nadie les pusiera nombre — Cialdini solo las escribió y se hizo famoso. Tres de ellas ya las estás haciendo sin darte cuenta. Aquí tienes cómo suenan las seis en tu acera."},{type:"divider"},{type:"subheader",text:"1. Reciprocity — People Feel Obliged to Give Back",textEs:"1. Reciprocidad — La Gente Se Siente Obligada a Devolver"},{type:"paragraph",text:"When someone gives us something, we feel a psychological pull to return the favor. It's hardwired into human social behavior. On your floor, this principle is activated constantly:",textEs:"Cuando alguien nos da algo, sentimos un impulso psicológico a devolver el favor. Está grabado en nuestro comportamiento social humano. En tu piso, este principio se activa constantemente:"},{type:"bullets",items:["THE FREE SAMPLE: When you give someone a hand massage with the scrub or buff their nail, you've given them something of value. They now feel a subtle obligation to reciprocate — by listening to your pitch, considering your offer, or making a purchase.","YOUR TIME AND ATTENTION: When you spend 5 minutes explaining, demonstrating, and educating, you've invested in them. Most people feel uncomfortable walking away after someone has invested energy in them.","THE COMPLIMENT: A genuine compliment ('I love your jacket') is a small gift. It creates warmth and openness because the person feels you've given them something positive."],itemsEs:["LA MUESTRA GRATIS: Cuando le das a alguien un masaje de manos con el exfoliante o le pulis la uña, le has dado algo de valor. Ahora sienten una obligación sutil a reciprocar — escuchando tu presentación, considerando tu oferta o haciendo una compra.","TU TIEMPO Y ATENCIÓN: Cuando pasas 5 minutos explicando, demostrando y educando, has invertido en ellos. La mayoría de las personas se sienten incómodas yéndose después de que alguien ha invertido energía en ellos.","EL CUMPLIDO: Un cumplido genuino ('me encanta tu chamarra') es un pequeño regalo. Crea calidez y apertura porque la persona siente que le has dado algo positivo."]},{type:"script",text:"'Let me give you a small gift — this hand treatment takes just one minute and you'll feel the difference immediately.' By framing it as a GIFT, you activate reciprocity before the demo even begins.",textEs:"'Déjame darte un pequeño regalo — este tratamiento de manos toma solo un minuto y sentirás la diferencia de inmediato.' Al presentarlo como un REGALO, activas la reciprocidad antes de que la demostración siquiera comience."},{type:"tip",text:"The key to ethical reciprocity: give GENUINE value first. A fake compliment or a rushed demo doesn't create reciprocity — it creates distrust. Invest real time and energy, and the principle works naturally.",textEs:"La clave de la reciprocidad ética: da valor GENUINO primero. Un cumplido falso o una demostración apresurada no crean reciprocidad — crean desconfianza. Invierte tiempo y energía reales, y el principio funciona naturalmente."},{type:"divider"},{type:"subheader",text:"2. Scarcity — We Want What Is Rare",textEs:"2. Escasez — Queremos Lo Que Es Raro"},{type:"paragraph",text:"Opportunities seem more valuable when their availability is limited. This is why 'limited edition' products, flash sales, and countdown timers are so effective. On your floor, scarcity is built into your location:",textEs:"Las oportunidades parecen más valiosas cuando su disponibilidad es limitada. Por eso los productos 'edición limitada', las ventas flash y los temporizadores de cuenta regresiva son tan efectivos. En tu piso, la escasez está integrada en tu ubicación:"},{type:"bullets",items:["THE PRICE GAP: 'Around Europe this is {currency}500, but here in {locationName}, it's only {currency}300.' The scarcity of that {currency}300 price creates urgency — they can't get it at home.","SEASONAL OFFERS: 'This Christmas offer ends soon, and I'd hate for you to miss it.' Time-limited scarcity pushes decision-making.","LIMITED STOCK: 'I only have two samples left' or 'These sell out every weekend.' Physical scarcity increases perceived value.","THE VOUCHER CLOSE: 'I can only do this once, just for you.' Personal scarcity — a unique opportunity that won't repeat."],itemsEs:["LA DIFERENCIA DE PRECIO: 'En toda Europa esto cuesta {currency}500, pero aquí en {locationName}, cuesta solo {currency}300.' La escasez de ese precio de {currency}300 crea urgencia — no pueden conseguirlo en su país.","OFERTAS DE TEMPORADA: 'Esta oferta de Navidad termina pronto, y odiaría que te la pierdas.' La escasez de tiempo limitado empuja la toma de decisiones.","STOCK LIMITADO: 'Solo me quedan dos muestras' o 'Estos se agotan cada fin de semana.' La escasez física aumenta el valor percibido.","EL CIERRE CON CUPÓN: 'Solo puedo hacer esto una vez, solo para ti.' Escasez personal — una oportunidad única que no se repetirá."]},{type:"comparison",left:{label:"Weak Scarcity",text:"'You should buy this while you're here.' Vague, generic, no specific reason to act now. Customers ignore it."},leftEs:{label:"Escasez Débil",text:"'Deberías comprar esto mientras estás aquí.' Vago, genérico, sin razón específica para actuar ahora. Los clientes lo ignoran."},right:{label:"Strong Scarcity",text:"'This price only exists in {locationName}. When you cross the border, it goes back to {currency}500. That's a {currency}200 savings you only get today, right here.' Specific, verifiable, personal."},rightEs:{label:"Escasez Fuerte",text:"'Este precio solo existe en {locationName}. En cuanto cruzas la frontera, vuelve a {currency}500. Son {currency}200 de ahorro que solo consigues hoy, aquí mismo.' Concreto, comprobable, personal."}},{type:"divider"},{type:"subheader",text:"3. Authority — We Trust Experts",textEs:"3. Autoridad — Confiamos en los Expertos"},{type:"paragraph",text:"People listen to whoever clearly knows what they are doing. Authority on a kiosk is not a certificate on the wall — it is volume and hands. You have done this a hundred times today and it shows in how you hold their wrist. Authority is built through:",textEs:"La gente escucha a quien se ve claramente que sabe lo que hace. La autoridad en un puesto de calle no es un título en la pared — son volumen y manos. Hoy has hecho esto cien veces y se te nota en cómo les coges la muñeca. La autoridad se construye con:"},{type:"bullets",items:["KNOWLEDGE: Knowing what is in it without having to check. 'This is Dead Sea mineral salt — lowest place on Earth, highest mineral concentration there is.'","CONFIDENT DELIVERY: Experts don't hesitate. They don't say 'um' and 'I think.' They state facts clearly: 'This is our #1 seller across Europe.'","VISUAL CREDIBILITY: Looking professional, well-groomed, and polished. Your appearance IS your authority signal.","SOCIAL PROOF: 'I've done this demo over 20 times today, and the reaction is always the same.' Your experience IS authority."],itemsEs:["CONOCIMIENTO: Saberte lo que lleva sin tener que mirarlo. 'Esto es sal mineral del Mar Muerto — el sitio más bajo de la Tierra, la mayor concentración de minerales que hay.'","ENTREGA CON CONFIANZA: Los expertos no dudan. No dicen 'emmm' ni 'yo creo'. Enuncian hechos con claridad: 'Este es nuestro producto #1 en toda Europa.'","CREDIBILIDAD VISUAL: Verse profesional, bien arreglado y pulido. Tu apariencia ES tu señal de autoridad.","PRUEBA SOCIAL: 'He hecho esta demostración más de 20 veces hoy, y la reacción siempre es la misma.' Tu experiencia ES autoridad."]},{type:"script",text:"'I have done this on about forty faces today. I know exactly how it goes on skin like yours.' That is your authority, and nobody can argue with it — it happened, they watched you do it, and it is nobody's opinion but your own hands.",textEs:"'Hoy lo he hecho en unas cuarenta caras. Sé exactamente cómo queda en una piel como la tuya.' Esa es tu autoridad, y no hay quien la discuta — ha pasado, te han visto hacerlo, y no es la opinión de nadie más que de tus propias manos."},{type:"divider"},{type:"subheader",text:"4. Consistency — People Want to Act in Alignment",textEs:"4. Consistencia — La Gente Quiere Actuar en Concordancia"},{type:"paragraph",text:"Once people commit to something, they want to act in ways that are consistent with that commitment. Small initial agreements lead to larger ones. This is incredibly powerful on the sales floor:",textEs:"Una vez que las personas se comprometen con algo, quieren actuar de manera consistente con ese compromiso. Los acuerdos iniciales pequeños llevan a acuerdos mayores. Esto es increíblemente poderoso en el piso de ventas:"},{type:"bullets",items:["THE AGREEMENT FRAME: 'You take care of your skin, right?' They say yes. Now they've committed to the identity of someone who cares about skincare. Buying becomes consistent with that identity.","THE SMALL YES: 'Can I show you something quickly?' Small agreement. Then: 'Can I try this on your hand?' Another small agreement. Each yes makes the next yes more likely.","SELF-IMAGE CONSISTENCY: When someone says 'I believe in investing in quality,' they've created a standard for themselves. Passing on a high-quality product would be inconsistent with that self-image."],itemsEs:["EL MARCO DE ACUERDO: 'Tú cuidas tu piel, ¿o no?' Dicen que sí. Ahora se han comprometido con la identidad de alguien que se preocupa por el cuidado de la piel. Comprar se vuelve consistente con esa identidad.","EL PEQUEÑO SÍ: '¿Te muestro algo rápido?' Pequeño acuerdo. Luego: '¿Puedo probarte esto en la mano?' Otro pequeño acuerdo. Cada sí hace que el siguiente sí sea más probable.","CONSISTENCIA DE AUTOIMAGEN: Cuando alguien dice 'creo en invertir en calidad', ha creado un estándar para sí mismo. Dejar pasar un producto de alta calidad sería inconsistente con esa autoimagen."]},{type:"tip",text:"Get small agreements early. 'You have amazing skin — you clearly take care of yourself, right?' When they agree, they've anchored their identity as a skincare-conscious person. Everything that follows should reinforce that identity.",textEs:"Obtén acuerdos pequeños temprano. 'Tienes una piel increíble — claramente te cuidas, ¿o no?' Cuando aceptan, han anclado su identidad como una persona consciente del cuidado de la piel. Todo lo que sigue debe reforzar esa identidad."},{type:"divider"},{type:"subheader",text:"5. Liking — We Say Yes to People We Like",textEs:"5. Simpatía — Decimos Sí a las Personas que Nos Gustan"},{type:"paragraph",text:"This seems obvious, but it's profound. People buy from people they like, trust, and feel connected to. Liking is built through:",textEs:"Parece obvio, pero es profundo. La gente compra a personas que les gustan, en quienes confían y con quienes se sienten conectados. La simpatía se construye a través de:"},{type:"bullets",items:["SIMILARITY: 'Oh, you're from Barcelona? I love it there!' Shared backgrounds, interests, or experiences create instant rapport.","COMPLIMENTS: Genuine, specific compliments make people feel seen and appreciated. 'That scarf is beautiful — is it from a local designer?'","COOPERATION: Working together on the demo ('Rub this in gently') creates a sense of teamwork. You're not seller and buyer — you're collaborators.","POSITIVE ENERGY: Smiling, warmth, humor — these make you likable. People don't buy from grumpy salespeople, even if the product is great."],itemsEs:["SIMILITUD: 'Oh, ¾res de Barcelona? Me encanta ese lugar!' Los antecedentes, intereses o experiencias compartidos crean conexión instantánea.","CUMPLIDOS: Los cumplidos genuinos y específicos hacen que la gente se sienta vista y apreciada. 'Esa bufanda es hermosa — ¿es de un diseñador local?'","COOPERACIÓN: Trabajar juntos en la demostración ('Frota esto suavemente') crea un sentido de trabajo en equipo. No son vendedor y comprador — son colaboradores.","ENERGÍA POSITIVA: Sonreír, calidez, humor — esto te hace agradable. La gente no compra a vendedores gruñones, aunque el producto sea excelente."]},{type:"divider"},{type:"subheader",text:"6. Consensus — We Follow What Others Do",textEs:"6. Consenso — Seguimos Lo Que Hacen los Demás"},{type:"paragraph",text:"When uncertain, people look to what others are doing. Social proof is one of the most powerful persuasion tools:",textEs:"Cuando hay incertidumbre, la gente observa lo que otros están haciendo. La prueba social es una de las herramientas de persuasión más poderosas:"},{type:"bullets",items:["POPULARITY: 'This is our #1 best-seller.' If everyone else is buying it, it must be good.","TESTIMONIALS: 'My customer from last week texted me saying her husband noticed the difference immediately.' Real stories are more powerful than statistics.","VISIBLE DEMAND: When customers see other customers in the shop being served, it validates the shop's credibility. A busy shop is an attractive shop.","'ALREADY BOUGHT' SIGNAL: 'Most people who try the demo end up taking at least the Scrub. It's hard to resist once you feel it.' This normalizes buying as the expected outcome."],itemsEs:["POPULARIDAD: 'Este es nuestro producto #1 más vendido.' Si todos los demás lo compran, debe ser bueno.","TESTIMONIOS: 'Mi cliente de la semana pasada me mandó un mensaje diciendo que su esposo notó la diferencia de inmediato.' Las historias reales son más poderosas que las estadísticas.","DEMANDA VISIBLE: Cuando los clientes ven a otros clientes siendo atendidos en la tienda, valida la credibilidad de la tienda. Una tienda ocupada es una tienda atractiva.","SEÑAL DE 'YA COMPRADO': 'La mayoría de las personas que prueban la demostración terminan llevándose al menos el Exfoliante. Es difícil resistirse una vez que lo sientes.' Esto normaliza comprar como el resultado esperado."]},{type:"script",text:"'I did this exact demo an hour ago, that chair you are sitting in. She looked in the mirror, said 'go on then', and took two.' A real person, an hour ago, right here — it makes buying the normal thing to do rather than the brave thing. Note where the story ENDS: she bought, in the chair. Never tell one about somebody who went away and came back, because you have just told your customer that going away works.",textEs:"'Esta misma demo la hice hace una hora, en esa silla en la que estás. Se miró al espejo, dijo 'venga, va', y se llevó dos.' Una persona de verdad, hace una hora, justo aquí — hace que comprar sea lo normal y no lo valiente. Fíjate dónde ACABA la historia: compró, sentada ahí. No cuentes nunca una en la que alguien se va y vuelve, porque le acabas de decir a tu clienta que irse funciona."},{type:"quote",text:"Understanding these six principles transforms selling from a battle of wills into a dance of psychology. You're not fighting the customer — you're guiding them through a decision-making process that feels natural and comfortable.",textEs:"Entender estos seis principios transforma la venta de una batalla de voluntades en una danza de psicología. No estás luchando contra el cliente — lo estás guiando a través de un proceso de toma de decisiones que se siente natural y cómodo.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Which Cialdini principle is activated when you give a customer a free hand massage before pitching?",options:["Scarcity","Authority","Reciprocity","Consensus"],correctIndex:2,explanation:"Reciprocity is the principle that people feel obliged to give back when they receive something. A free hand massage is a gift that creates a psychological pull to reciprocate by listening to your pitch or making a purchase."},{question:"How does the {locationName} price activate the scarcity principle?",options:["It makes the product seem rare and hard to find in any other shop","It is a price that only exists in {locationName}, nowhere else","It makes customers feel special","It creates time pressure"],correctIndex:1,explanation:"The {currency}300 price only exists in {locationName} — back home the same product is {currency}500. Customers cannot get this price once they cross the border, making the opportunity geographically limited and rare."},{question:"Why is getting a small 'yes' early in the interaction powerful?",options:["It tricks the customer","It activates consistency — people want to act in alignment with their commitments","It's just a nice way to start","It shows you're in control"],correctIndex:1,explanation:"The principle of consistency means that once people commit to something (even a small yes), they want to act in alignment with that commitment. Small initial agreements make larger agreements more likely."}]},"psych-8":{id:"psych-8",categoryId:"psychology",title:"Developing Your Sales Intuition",titleEs:"Desarrollando tu Intuición de Ventas",subtitle:"How experience becomes instinct. Pattern recognition. Reading micro-signals.",subtitleEs:"Aprende a leer clientes como un libro",duration:"10 min",icon:"Compass",order:8,xpReward:150,sections:[{type:"header",text:"From Thinking to Knowing: The Path to Sales Instinct",textEs:"Del Pensamiento al Conocimiento: El Camino al Instinto de Ventas"},{type:"paragraph",text:"Watch a master salesperson work, and it looks like magic. They seem to just KNOW who will buy, when to push, when to back off, what to say. But it's not magic — it's pattern recognition developed through hundreds of interactions. Every customer you've ever stopped has taught you something. The question is: are you paying attention?",textEs:"Observa a un vendedor maestro trabajar, y parece magia. Parece que simplemente SABEN quién comprará, cuándo presionar, cuándo retroceder, qué decir. Pero no es magia — es reconocimiento de patrones desarrollado a través de cientos de interacciones. Cada cliente que alguna vez detuviste te ha enseñado algo. La pregunta es: ¿estás prestando atención?"},{type:"keypoint",text:"Sales intuition is the ability to read a situation and know the right move without consciously thinking through it. It comes from deliberate practice + active reflection on every interaction.",textEs:"La intuición de ventas es la capacidad de leer una situación y saber el movimiento correcto sin pensarlo conscientemente. Viene de la práctica deliberada + la reflexión activa sobre cada interacción."},{type:"divider"},{type:"subheader",text:"How Experience Becomes Instinct",textEs:"Cómo la Experiencia se Convierte en Instinto"},{type:"paragraph",text:"Your brain is a pattern-recognition machine. When you encounter a situation repeatedly, your brain starts building mental models. Over time, these models become so ingrained that you recognize patterns instantly, without conscious thought. This is how a chess grandmaster 'sees' the right move in seconds, or how a doctor 'feels' a diagnosis before the tests come back.",textEs:"Tu cerebro es una máquina de reconocimiento de patrones. Cuando encuentras una situación repetidamente, tu cerebro empieza a construir modelos mentales. Con el tiempo, estos modelos se vuelven tan arraigados que reconoces patrones instantáneamente, sin pensamiento consciente. Así es como un gran maestro de ajedrez 've' la jugada correcta en segundos, o cómo un doctor 'siente' un diagnóstico antes de que lleguen los resultados."},{type:"numbered",items:["STAGE 1 — CONSCIOUS INCOMPETENCE: You're new. You don't know what you don't know. Every interaction requires intense focus. You think through every word.","STAGE 2 — CONSCIOUS COMPETENCE: You've had enough interactions to start seeing patterns. You can read some customers, but it still takes effort. You're thinking AND doing.","STAGE 3 — UNCONSCIOUS COMPETENCE: The magic stage. Patterns jump out at you. You just KNOW. Your body moves before your brain decides. This is where top sellers live.","STAGE 4 — MASTERY: Not only do you intuitively read situations, but you can ALSO explain your intuition to others. You can teach. This is the level of a true sales leader."],itemsEs:["ETAPA 1 — INCOMPETENCIA CONSCIENTE: Eres nuevo. No sabes lo que no sabes. Cada interacción requiere enfoque intenso. Piensas cada palabra.","ETAPA 2 — COMPETENCIA CONSCIENTE: Has tenido suficientes interacciones para empezar a ver patrones. Puedes leer a algunos clientes, pero aún requiere esfuerzo. Estás pensando Y haciendo.","ETAPA 3 — COMPETENCIA INCONSCIENTE: La etapa mágica. Los patrones saltan a la vista. Simplemente SABES. Tu cuerpo se mueve antes de que tu cerebro decida. Aquí es donde viven los mejores vendedores.","ETAPA 4 — MAESTRÍA: No solo lees las situaciones intuitivamente, sino que TAMBIÉN puedes explicar tu intuición a otros. Puedes enseñar. Este es el nivel de un verdadero líder de ventas."]},{type:"tip",text:"Most salespeople reach Stage 2 and stop growing. They get good enough to make money and plateau. The ones who reach Stage 3 and 4 are those who actively reflect on every interaction, seeking patterns rather than just counting wins.",textEs:"La mayoría de los vendedores llegan a la Etapa 2 y dejan de crecer. Se vuelven lo suficientemente buenos para ganar dinero y se estancan. Los que llegan a la Etapa 3 y 4 son quienes reflexionan activamente sobre cada interacción, buscando patrones en lugar de solo contar victorias."},{type:"divider"},{type:"subheader",text:"Building Pattern Recognition Deliberately",textEs:"Construyendo el Reconocimiento de Patrones de Forma Deliberada"},{type:"paragraph",text:"Intuition isn't just 'experience' — it's EXPERIENCE THAT YOU'VE PROCESSED. Here's how to accelerate the process:",textEs:"La intuición no es solo 'experiencia' — es EXPERIENCIA QUE HAS PROCESADO. Aquí te decimos cómo acelerar el proceso:"},{type:"bullets",items:["THE AFTER-ACTION REVIEW: After every interaction — yes OR no — ask yourself three questions: What did I notice about this person? What did I do? What was the result? Write it down. This forces your brain to process patterns.","THE ONE THAT GOT AWAY: At the end of the shift, write down two — the one that got away and the one that landed. Not their age, not what they were wearing. The moment. The exact second she went from 'no thanks' to laughing, or the exact second you lost her. That is the only bit worth keeping.","STUDY YOUR WINS FOR WHAT YOU DID, NOT WHO THEY WERE: not couples, not luxury bags, not an age range. The line you opened with. The second you shut up. The moment you put the mirror in her hand. Those are the bits you can do again tomorrow — you cannot order in more forty-year-olds.","STUDY YOUR LOSSES THE SAME WAY: again, what YOU did. Wrong words, skipped step, filled the silence, went lazy halfway, stopped early on the ladder. If the honest answer is none of those, then that one was not on you. What this will never give you is a profile of the person who was never going to pay — nobody can see that from the outside, and the sellers who think they can are the ones talking themselves out of the next demo."],itemsEs:["LA REVISIÓN POST-ACCIÓN: Después de cada interacción — sí O no — hazte tres preguntas: ¿Qué noté de esta persona? ¿Qué hice? ¿Cuál fue el resultado? Escríbelo. Esto obliga a tu cerebro a procesar patrones.","LA QUE SE TE ESCAPÓ: Al final del turno apunta dos — la que se te escapó y la que entró. Ni la edad, ni la ropa. El momento. El segundo exacto en que pasó de 'no, gracias' a reírse, o el segundo exacto en que la perdiste. Eso es lo único que merece la pena guardar.","ESTUDIA TUS VICTORIAS POR LO QUE HICISTE TÚ, NO POR QUIÉNES ERAN: ni parejas, ni bolsas de lujo, ni una franja de edad. La frase con la que abriste. El segundo en que te callaste. El momento en que le pusiste el espejo en la mano. Eso es lo que puedes repetir mañana — no puedes encargar más gente de cuarenta años.","ESTUDIA TUS DERROTAS IGUAL: otra vez, lo que hiciste TÚ. Palabras equivocadas, un paso saltado, llenaste el silencio, te relajaste a mitad, te paraste pronto en la escalera. Si la respuesta honesta es que ninguna, esa no iba contigo. Lo que esto no te va a dar nunca es el retrato del cliente que no iba a pagar jamás — eso no se ve desde fuera, y los vendedores que creen que sí son los que se están quitando de encima la siguiente demo."]},{type:"divider"},{type:"subheader",text:"Watch Her Hands, Not Her Mouth",textEs:"Mírale las Manos, No la Boca"},{type:"paragraph",text:"People tell you what they have decided long before they say it, and almost never with words. Four tells, and you can catch all four while you are still talking:",textEs:"La gente te dice lo que ha decidido mucho antes de decirlo, y casi nunca con palabras. Cuatro señales, y las pillas todas mientras sigues hablando:"},{type:"bullets",items:["SHE HASN'T STOPPED TOUCHING HER OWN HANDS: Or the spot you treated, or the mirror. She is already yours. You just have not said the number yet.","SHE ASKS THE PRICE BEFORE YOU OFFER IT: That is not a question. That is a yes with a price attached. Answer it straight away and go to the two options.","THE ARMS FOLD THE SECOND YOU SAY THE NUMBER: That is the price, not the product. Do not explain the product again — go down a rung and put something in the bag.","THE PHONE COMES OUT TWICE: you have lost the room, not the sale. Stop talking, put something in her hand, and ask her a question she has to look up to answer. What it is not is your cue to open the door for her — she came in, she is still sitting there, and a phone is a habit, not a verdict."],itemsEs:["NO HA PARADO DE TOCARSE LAS MANOS: O la zona que le has tratado, o el espejo. Ya es tuya. Lo único que falta es que digas el número.","TE PREGUNTA EL PRECIO ANTES DE QUE SE LO DIGAS: Eso no es una pregunta. Es un sí con un precio pegado. Contéstale al momento y ve a las dos opciones.","SE CRUZA DE BRAZOS EN CUANTO DICES EL NÚMERO: Es el precio, no el producto. No le vuelvas a explicar el producto — baja un escalón y mete algo en la bolsa.","SACA EL MÓVIL DOS VECES: has perdido la sala, no la venta. Cállate, ponle algo en la mano y hazle una pregunta que le obligue a levantar la vista. Lo que no es, es tu señal para abrirle la puerta — ha entrado, sigue ahí sentada, y un móvil es una costumbre, no un veredicto."]},{type:"tip",text:"Do not try to watch all four at once. Take the hands first — it is the easiest one to see and the one that tells you the most. Once you catch that without thinking about it, add the next.",textEs:"No intentes fijarte en las cuatro a la vez. Empieza por las manos — es la más fácil de ver y la que más te dice. Cuando la pilles sin pensarlo, añade la siguiente."},{type:"divider"},{type:"subheader",text:"When to Push and When to Back Off",textEs:"Cuándo Presionar y Cuándo Retroceder"},{type:"paragraph",text:"This is the million-euro question. The answer lies in reading the customer's buying temperature:",textEs:"Esta es la pregunta del millón de euros. La respuesta está en leer la temperatura de compra del cliente:"},{type:"numbered",items:["GREEN LIGHTS (PUSH): Leaning in, touching the product, asking unprompted questions about usage or price, involving their partner positively, smiling with genuine eye crinkles, touching their face while looking at the product. These customers are warm — close with confidence.","YELLOW LIGHTS (GENTLE): Hesitant questions, looking at partner for approval, saying 'it's nice but...', touching the product but not committing. These customers need reassurance, not pressure. Use emotional connection and logic together.","RED LIGHTS (BACK OFF): Crossed arms after price, stepping back, checking phone repeatedly, flat responses, looking around for exit, partner shaking head subtly. She is not saying no, she is saying not at that number. Stop selling the product and start moving the price: drop your voice, take something out, give her a reason. Crossed arms after a price is the ladder asking to be walked, not a customer asking to leave."],itemsEs:["LUCES VERDES (PRESIONA): Inclinarse hacia adelante, tocar el producto, hacer preguntas espontáneas sobre uso o precio, involucrar positivamente a su pareja, sonreír con arrugas genuinas alrededor de los ojos, tocarse la cara mientras miran el producto. Estos clientes están calientes — cierra con confianza.","LUCES AMARILLAS (SUAVE): Preguntas vacilantes, mirar a la pareja para aprobación, decir 'está bonito pero...', tocar el producto pero no comprometerse. Estos clientes necesitan tranquilidad, no presión. Usa la conexión emocional y la lógica juntas.","LUCES ROJAS (RETROCEDE): Brazos cruzados después del precio, dar un paso atrás, revisar el teléfono repetidamente, respuestas planas, buscando la salida, pareja moviendo la cabeza sutilmente. No está diciendo que no, está diciendo que a ese número no. Deja de vender el producto y empieza a mover el precio: baja la voz, quita algo, dale un motivo. Los brazos cruzados después de un precio son la escalera pidiendo que la bajes, no una clienta pidiendo irse."]},{type:"script",text:"'I can see you're thinking about it — so tell me what about. You told me you like it. You told me you'd use it. So it's the price, my love. Say the number out loud and let me see what I can do.' Read the signals, absolutely — but read them so you know which line to reach for, not so you know when to open the door for her.",textEs:"'Veo que lo estás pensando — pues dime en qué. Me has dicho que te gusta. Me has dicho que lo usarías. Entonces es el precio, cariño. Dime tú el número en voz alta y a ver qué puedo hacer.' Lee las señales, por supuesto — pero léelas para saber qué frase sacar, no para saber cuándo abrirle la puerta."},{type:"divider"},{type:"subheader",text:"Learning from Every Interaction",textEs:"Aprendiendo de Cada Interacción"},{type:"paragraph",text:"The fastest way to develop intuition is to extract a lesson from EVERY customer — even the ones who ignore you completely:",textEs:"La forma más rápida de desarrollar intuición es extraer una lección de CADA cliente — incluso de los que te ignoran por completo:"},{type:"bullets",items:["THE IGNORE: 'They never even looked up.' → Lesson: the line went out too late, or too quietly, or you were looking at your own shoes when it did. Fix the bit you control. What it is not is proof they were the wrong person to stop — you have no idea who they were, and neither does anybody else.","THE 'NO THANKS': 'They smiled but kept walking. Good energy but bad timing.' → Lesson: My approach was warm but they're in a rush. Speed up the opener next time.","THE DEMO, NO BUY: 'They loved the nail kit demo but said it was too expensive even at {currency}30.' → Lesson: Either a price objection to work through, or genuinely no budget. Note the signals for future reference.","THE CLOSE: 'They bought the syringe after I involved the husband in the demo.' → Lesson: Partner engagement was the key factor. Replicate that approach with couples."],itemsEs:['EL QUE IGNORA: "Ni levantó la vista." → Lección: la frase salió tarde, o floja, o estabas mirándote los zapatos cuando salió. Arregla la parte que controlas tú. Lo que no es, es la prueba de que no había que pararlos — no tienes ni idea de quiénes eran, y nadie la tiene.',"EL 'NO GRACIAS': 'Sonrieron pero siguieron caminando. Buena energía pero mal timing.' → Lección: Mi acercamiento fue cálido pero están con prisa. Acelera el acercamiento la próxima vez.","LA DEMO, SIN COMPRA: 'Les encantó la demostración del kit de uñas pero dijeron que era muy caro incluso a {currency}30.' → Lección: O es una objeción de precio para trabajar, o genuinamente no tienen presupuesto. Toma nota de las señales para referencia futura.","EL CIERRE: 'Compraron la jeringa después de involucrar al esposo en la demostración.' → Lección: El compromiso de la pareja fue el factor clave. Replica ese acercamiento con parejas."]},{type:"tip",text:"At the end of each day, write down the ONE most important lesson you learned. Just one sentence. After 6 months, you'll have 180 lessons. That's more accumulated wisdom than most salespeople acquire in years.",textEs:"Al final de cada día, escribe la lección más importante que aprendiste. Solo una oración. Después de 6 meses, tendrás 180 lecciones. Eso es más sabiduría acumulada que la mayoría de los vendedores adquiere en años."},{type:"quote",text:"Intuition is not magic. It is pattern recognition that has been practiced until it becomes automatic. Every customer is a teacher — if you're willing to learn.",textEs:"La intuición no es magia. Es reconocimiento de patrones que se ha practicado hasta volverse automático. Cada cliente es un maestro — si estás dispuesto a aprender.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"stop-1":{id:"stop-1",categoryId:"stopping",title:"The First Sequence",titleEs:"La Primera Secuencia",subtitle:"Stood ready, get the look, close the gap, the gift, turn and walk, and sit them down — the order everything else is built on",subtitleEs:"Colocado, consigue la mirada, acorta la distancia, el regalo, date la vuelta y anda, y siéntalos — el orden sobre el que se construye todo lo demás",duration:"12 min",icon:"Target",order:1,xpReward:100,sections:[{type:"header",text:"The basics of the basics",textEs:"Lo básico de lo básico"},{type:"paragraph",text:"This is the first thing you learn and the last thing you stop using. It is one move from start to finish: you are stood ready, you get their attention while they are still walking, they look, you go, you give them a reason to follow you, and you walk in. Every other lesson in this app — the compliments, the demo, the ladder, the objections — is built on top of this one. Learn it in order and the rest has somewhere to sit. Skip it and you are just a person talking on a walkway.",textEs:"Esto es lo primero que aprendes y lo último que dejas de usar. Es un solo movimiento de principio a fin: estás colocado, les llamas la atención mientras todavía andan, te miran, vas, les das un motivo para seguirte, y entras. Todo lo demás en esta app — los cumplidos, la demo, la escalera, las objeciones — se construye encima de esto. Apréndetelo en orden y el resto tiene dónde apoyarse. Sáltatelo y solo eres alguien hablando en medio del pasillo."},{type:"keypoint",text:"The whole technique is an order of operations. Do the steps in the wrong order and each one stops working.",textEs:"Toda la técnica es un orden de operaciones. Haz los pasos en el orden equivocado y cada uno deja de funcionar."},{type:"divider"},{type:"subheader",text:"Step 1 — Be stood ready before anybody is near you",textEs:"Paso 1 — Estate colocado antes de que nadie se acerque"},{type:"paragraph",text:"None of the rest works if you are flat against the wall with your hands in your pockets. Before anybody is in range you want to be somewhere they can see you, with the sample already in your hand, and the way past you clear.",textEs:"Nada de lo demás funciona si estás pegado a la pared con las manos en los bolsillos. Antes de que nadie esté a tiro tienes que estar donde te vean, con la muestra ya en la mano, y el paso libre."},{type:"bullets",items:["WHERE THEY CAN SEE YOU: Out in front of the kiosk, not tucked against the wall. If they have to find you, you have already lost the first second.","SAMPLE ALREADY IN YOUR HAND: Loaded before you need it, every time. You do not want to be rummaging for it while the one you wanted walks past.","NOT IN THE DOORWAY: Beside the entrance, never filling it. A person who has to squeeze past you has already decided something about you.","HANDS DOING SOMETHING: Holding the sample, sorting the stand, moving. Hands in pockets reads as bored, and bored is invisible."],itemsEs:["DONDE TE VEAN: Delante del kiosco, no metido contra la pared. Si te tienen que buscar, ya has perdido el primer segundo.","LA MUESTRA YA EN LA MANO: Lista antes de que haga falta, siempre. No quieres estar rebuscándola mientras la que te interesaba te pasa de largo.","NO EN LA PUERTA: Al lado de la entrada, nunca tapándola. Quien tiene que colarse por un hueco para pasar ya ha decidido algo sobre ti.","LAS MANOS HACIENDO ALGO: Sujeta la muestra, coloca el expositor, muévete. Las manos en los bolsillos se leen como aburrimiento, y el aburrimiento es invisible."]},{type:"divider"},{type:"subheader",text:"Step 2 — Get their attention from four or five metres",textEs:"Paso 2 — Llámales la atención a cuatro o cinco metros"},{type:"paragraph",text:"Before you approach anybody with the sample, get their attention. You want them looking at you BEFORE you take a single step. Not while you walk — before. And do it early, while they are still four or five metres off and still walking. Wait until they are a couple of metres away and you have left it too late: by the time they have registered you and turned their head they are already level with you, and then they are past you.",textEs:"Antes de acercarte a nadie con la muestra, consigue su atención. Quieres que te estén mirando ANTES de dar un solo paso. No mientras andas — antes. Y hazlo pronto, cuando todavía están a cuatro o cinco metros y siguen andando. Si esperas a que estén a un par de metros, ya llegas tarde: para cuando te han visto y han girado la cabeza ya están a tu altura, y acto seguido te han pasado de largo."},{type:"script",...o},{type:"paragraph",text:"A greeting or a compliment — either one does the job. What matters is that it goes out while they are still coming towards you, and that you stay exactly where you are while you say it. You do not move a foot yet. You are buying one thing with that sentence: their eyes.",textEs:"Un saludo o un cumplido — cualquiera de los dos vale. Lo que importa es que salga mientras todavía vienen hacia ti, y que tú no te muevas del sitio al decirlo. Todavía no vas a ninguna parte. Con esa frase estás comprando una sola cosa: su mirada."},{type:"bullets",items:["EYES UP: They have to be able to catch your eye. A seller looking at their own shoes has given them nothing to look back at.","SMILE WITH YOUR EYES: A second, maybe two, and warm. Long enough to be a person, not long enough to be a stare.","IF THERE ARE TWO OF THEM, GREET BOTH: Do not lock onto one and leave the other one standing there bored. The bored one is the one who takes her away.","READ WHAT COMES BACK: Eyes that come to yours, go. Eyes that slide off and keep going, let them go and get set for the next one — you have lost nothing, because you have not moved."],itemsEs:["LA MIRADA ARRIBA: Tienen que poder cruzarla contigo. Un vendedor mirándose los zapatos no les ha dejado nada a lo que mirar.","SONRÍE CON LOS OJOS: Un segundo, o dos, y con buen rollo. Lo justo para parecer una persona, no tanto como para quedarte clavado mirándola.","SI VAN DOS, SALUDA A LOS DOS: No te enganches a una y dejes al otro ahí plantado aburriéndose. El aburrido es el que se la lleva.","LEE LO QUE TE DEVUELVEN: Ojos que van a los tuyos, adelante. Ojos que se escurren y siguen, déjalos ir y prepárate para el siguiente — no has perdido nada, porque no te has movido."]},{type:"divider"},{type:"subheader",text:"Step 3 — They look. Now you move.",textEs:"Paso 3 — Te miran. Ahora te mueves."},{type:"paragraph",text:"If they look at you, now you raise the sample and start walking towards them. If they do not look, you have lost nothing — you did not commit. Walking at someone who has not looked at you is how you become a person to avoid.",textEs:"Si te miran, ahora levantas la muestra y empiezas a andar hacia ellos. Si no te miran, no has perdido nada — no te has comprometido. Andar hacia alguien que no te ha mirado es cómo te conviertes en una persona a evitar."},{type:"keypoint",text:"The 3-second rule: the look is the WHEN. From the moment their eyes come to you, you have about three seconds to be moving. Longer than that and it cools — they have filed you as shop staff and put the 'just looking' wall up before you get a second sentence out, and the pause gives your own hesitation time to grow. Three seconds is not a rush. It is just not a wobble.",textEs:"La regla de los 3 segundos: la mirada es el CUÁNDO. Desde que sus ojos van a ti tienes unos tres segundos para estar ya en movimiento. Más de eso y se enfría — ya te han catalogado como personal de tienda y han levantado el muro del 'solo miro' antes de que te salga la segunda frase, y esa pausa le da tiempo a tu propia duda para crecer. Tres segundos no es ir con prisa. Es simplemente no dudar."},{type:"keypoint",text:"And come at them a bit from the side. Not planted square in front of them, not up in their face, and never standing in the line they were walking. You want it to feel like somebody stepping in beside them for a second — not a checkpoint.",textEs:"Y ve hacia ellos un poco de lado. No plantado enfrente, no encima de su cara, y nunca en la línea por la que iban andando. Quieres que parezca que alguien se pone a su lado un segundo — no un control policial."},{type:"divider"},{type:"subheader",text:"Step 4 — The sample is a coin toss",textEs:"Paso 4 — La muestra es cara o cruz"},{type:"keypoint",text:"And when you do reach them, the sample itself is a coin toss — it does not matter which way it lands. They take it, lovely. They wave it away, nothing happens. You have not been rejected, because you never asked them for anything. Either way you are still stood in front of them and you carry straight on into the next step, exactly the same. Sellers lose people here by treating a refused sample as an answer. It is not an answer, it is a hand not moving.",textEs:"Y cuando llegues a su altura, la muestra es cara o cruz — da igual de qué lado caiga. Si la cogen, genial. Si la apartan con la mano, no pasa nada. No te han rechazado, porque no les has pedido nada. En los dos casos sigues plantado delante de ellos y pasas al siguiente paso igual. Aquí es donde los vendedores pierden gente: se toman una muestra rechazada como una respuesta. No es una respuesta, es una mano que no se ha movido."},{type:"divider"},{type:"subheader",text:"Step 5 — Say the rush before they can",textEs:"Paso 5 — Di lo de la prisa antes que ellos"},{type:"paragraph",text:`The single most common thing a person says to get away from you is "sorry, I'm in a rush." So say it first. Once it has come out of your mouth, it is no longer available as an escape — they cannot use a reason you have already accepted.`,textEs:'Lo que más dice la gente para escaparse de ti es "perdona, voy con prisa". Así que dilo tú primero. Una vez que ha salido de tu boca, ya no les sirve de escape — no pueden usar una razón que tú ya has aceptado.'},{type:"script",...t},{type:"paragraph",text:'Two things are doing work in that sentence. The rush is pre-killed. And the question is a genuine compliment that they have to answer with a real answer — you cannot say yes or no to "what do you use?".',textEs:'Hay dos cosas trabajando en esa frase. La prisa está desactivada. Y la pregunta es un cumplido de verdad que les obliga a dar una respuesta real — a "¿qué usas?" no puedes contestar sí o no.'},{type:"keypoint",text:"This line runs whether they took the sample or not. Took it, waved it away, did not even look at it — same words, same warmth, same second. The sample was never the point. It was the excuse to be stood in front of them saying this.",textEs:"Esta frase va igual hayan cogido la muestra o no. La han cogido, la han apartado, ni la han mirado — las mismas palabras, el mismo buen rollo, el mismo segundo. La muestra nunca era el objetivo. Era la excusa para estar plantado delante de ellos diciendo esto."},{type:"divider"},{type:"subheader",text:"Step 6 — Be impressed, whatever they say",textEs:"Paso 6 — Que te impresione, digan lo que digan"},{type:"paragraph",text:"Whatever they answer, you are impressed by it. A big brand, olive oil, a cream her sister brought back, nothing at all — it does not matter. You are not marking her homework, you are finding a bit of common ground and handing her three seconds of feeling good about herself.",textEs:"Contesten lo que contesten, te parece impresionante. Una marca grande, aceite de oliva, una crema que le trajo su hermana, nada de nada — da igual. No le estás corrigiendo los deberes, estás buscando algo en común y regalándole tres segundos de sentirse bien."},{type:"script",text:'"Really? No way."',textEs:'"¿En serio? No me lo creo."'},{type:"paragraph",text:"Then top it. Your mother uses the same one, your sister swears by it, you have heard of it and always wanted to try it. It costs you nothing and it turns a stranger being polite into two people having a conversation.",textEs:"Y luego remátalo. Tu madre usa la misma, tu hermana no la cambia por nada, la conoces y siempre has querido probarla. No te cuesta nada y convierte a una desconocida siendo educada en dos personas teniendo una conversación."},{type:"divider"},{type:"subheader",text:"Step 7 — The gift, then turn around",textEs:"Paso 7 — El regalo, y date la vuelta"},{type:"paragraph",text:"Now you give them a reason to move that costs them nothing.",textEs:"Ahora les das un motivo para moverse que no les cuesta nada."},{type:"script",text:`"You know what — just because you look so amazing, I'm going to give you a small gift. I think you're going to love it."`,textEs:'"¿Sabes qué? Solo porque estás guapísima, te voy a hacer un regalito. Creo que te va a encantar."'},{type:"keypoint",text:"Now turn around and walk into the shop. Do NOT check whether they are following you. Checking asks permission, and asking permission gives them the chance to say no. You do not give a damn whether they walk your route — you walk it, and you find out afterwards.",textEs:"Ahora date la vuelta y entra en la tienda. NO compruebes si te están siguiendo. Comprobar es pedir permiso, y pedir permiso les da la oportunidad de decir que no. Te da exactamente igual si hacen tu mismo camino — tú lo haces, y ya te enteras después."},{type:"divider"},{type:"subheader",text:"Step 8 — If they do not follow, nothing happens",textEs:"Paso 8 — Si no te siguen, no pasa nada"},{type:"paragraph",text:"Same as the sample: nothing happens. You keep going, you get inside the shop, and only then do you turn your head and see who came. If they are still out on the pavement, call them in warmly. You are not begging; you are holding a door open.",textEs:"Igual que con la muestra: no pasa nada. Sigues andando, entras en la tienda, y solo entonces giras la cabeza y miras quién ha venido. Si siguen fuera en la acera, llámalos con buen rollo. No estás suplicando; estás sujetando una puerta abierta."},{type:"script",...n},{type:"keypoint",text:"Then turn back round and keep walking. Do not stand there watching them decide. Say it, turn, walk — and the walking is what does the persuading, because now there is nothing to say no to. A seller frozen with a hopeful face is asking permission again, and you have just spent seven steps not asking permission.",textEs:"Y date la vuelta otra vez y sigue andando. No te quedes ahí mirando cómo lo deciden. Lo dices, te giras, andas — y lo que convence es el andar, porque ya no hay nada a lo que decir que no. Un vendedor congelado con cara de ilusión está pidiendo permiso otra vez, y te acabas de pasar siete pasos sin pedir permiso."},{type:"paragraph",text:"You never walk beside them and you never escort them. You walk first and you call them to come.",textEs:"Nunca andas a su lado y nunca los acompañas. Andas tú primero y los llamas."},{type:"keypoint",text:"And if they still do not come — it is what it is. You did the sequence, you did it properly, you gave it everything you had. That one is not on you. Do not carry her to the next person; the next person has not done anything wrong. This is the one bit of comfort in this job you are allowed to reach for, and you are only allowed to reach for it because you actually did the work.",textEs:"Y si aun así no vienen — pues es lo que hay. Has hecho la secuencia, la has hecho bien, le has puesto todo lo que tenías. Esa no va contigo. No te la lleves a la siguiente persona; la siguiente no te ha hecho nada. Este es el único consuelo que te puedes permitir en este trabajo, y te lo puedes permitir solo porque de verdad has hecho el trabajo."},{type:"divider"},{type:"subheader",text:"Step 9 — They came in. Now the day starts.",textEs:"Paso 9 — Han entrado. Ahora empieza el día."},{type:"paragraph",text:"The chairs are ready before anybody reaches them. Not pulled out while she stands there watching you clear a seat — ready, because the ten seconds you spend sorting furniture is the ten seconds she uses to remember she was going somewhere.",textEs:"Las sillas están listas antes de que nadie llegue. No las saques mientras ella está ahí de pie mirando cómo despejas un sitio — listas, porque los diez segundos que pasas colocando muebles son los diez segundos que ella usa para acordarse de que iba a algún sitio."},{type:"bullets",items:["FACING INTO THE SHOP: never facing the street. If she can see the pavement moving past, she starts thinking about being back out on it.",'A CHAIR FOR HIM TOO: if there are two of them, both sit. A partner left standing behind her gets bored, and the bored one is the one who says "come on, we should go".','SIT HER DOWN AND START — OR HAND HER OVER: no pause, no "so…", no shuffling. She is in the chair and somebody has her hand and is already talking. For your first two weeks that somebody is a colleague: you stop them and you pass them on, and that IS your job. Later on it is you in that chair. The handover is quick and warm and it happens while she is sitting, never at the door.'],itemsEs:["MIRANDO HACIA DENTRO: nunca hacia la calle. Si ve la acera pasando por delante, empieza a pensar en volver a salir a ella.",'UNA SILLA PARA ÉL TAMBIÉN: si son dos, se sientan los dos. Una pareja que se queda de pie detrás se aburre, y el aburrido es el que dice "venga, que nos tenemos que ir".','SIÉNTALA Y EMPIEZA — O PÁSALA: sin pausa, sin "bueno…", sin dar vueltas. Está en la silla y alguien le tiene la mano cogida y ya está hablando. Durante tus primeras dos semanas ese alguien es un compañero: tú paras y pasas, y ESE es tu trabajo. Más adelante en esa silla estarás tú. El traspaso es rápido y con buen rollo, y pasa con ella sentada, nunca en la puerta.']},{type:"keypoint",text:"That is the sequence finished and the sale not yet started. Everything from here — the demo, the two yeses, the number, the ladder — is a different lesson, and for your first two weeks it is also a different person: a new seller stops and hands over, and does not run the demo at all. Two weeks of nothing but this. Nobody has ever regretted it, because none of the rest ever happens for a seller who cannot do these nine steps.",textEs:"Ahí se acaba la secuencia y todavía no ha empezado la venta. Todo lo que viene ahora — la demo, los dos síes, el número, la escalera — es otra lección, y durante tus primeras dos semanas también es otra persona: el vendedor nuevo para y pasa, y no hace la demo. Dos semanas de esto y nada más. Nadie se ha arrepentido nunca, porque nada de lo demás le pasa a un vendedor que no sabe hacer estos nueve pasos."},{type:"divider"},{type:"subheader",text:"The whole thing, in order",textEs:"Todo seguido, en orden"},{type:"numbered",items:["STOOD READY: sample in your hand, path clear, out where they can see you.","ATTENTION FROM FOUR OR FIVE METRES, while they are still walking. You do not move.","THEY LOOK: now you go. Sample up, and come at them a bit from the side.","THE SAMPLE: taken or waved away, it changes nothing at all.",`THE RUSH, THEN THE QUESTION: "I know you're in a rush — what do you normally use on your skin?"`,'"REALLY? NO WAY.": be impressed, top it, find the common ground.',"THE SMALL GIFT: say it, turn around, walk in. Do not check.",`INSIDE THE SHOP: look back and call them — "it's two seconds, I promise."`,"TURN ROUND AND WALK AGAIN. If they still do not come, it is what it is — you did it all.","THEY CAME IN: chairs already set, backs to the street, one for him as well. Start — or, in your first two weeks, hand them to a colleague and go back out for the next one."],itemsEs:["COLOCADO: la muestra en la mano, el paso libre, fuera donde te vean.","LES LLAMAS LA ATENCIÓN A CUATRO O CINCO METROS, mientras todavía andan. Tú no te mueves.","TE MIRAN: ahora vas. La muestra en alto, y acércate un poco de lado.","LA MUESTRA: la cojan o la aparten, no cambia absolutamente nada.",'LA PRISA, Y LUEGO LA PREGUNTA: "sé que vas con prisa — ¿qué usas normalmente para la piel?"','"¿EN SERIO? NO ME LO CREO.": que te impresione, remátalo, busca algo en común.',"EL REGALITO: lo dices, te giras, entras. No compruebes nada.",'YA DENTRO: mira atrás y llámalos — "son dos segundos, os lo prometo".',"TE GIRAS Y ANDAS OTRA VEZ. Si aun así no vienen, es lo que hay — lo has hecho todo.","HAN ENTRADO: las sillas ya puestas, de espaldas a la calle, una para él también. A empezar — o, en tus primeras dos semanas, se los pasas a un compañero y vuelves a salir a por el siguiente."]},{type:"tip",text:'Do not practise this in bits. Say the whole thing out loud before your shift, in order — greeting, sample, the rush line, "really? no way", the gift, turn, walk. Then the chairs. It is about twenty seconds start to finish. You run it whole because the order IS the technique: any one of those lines on its own is just a nice thing said to a stranger.',textEs:'No practiques esto a trozos. Dilo entero en voz alta antes del turno, en orden — saludo, muestra, lo de la prisa, "¿en serio? no me lo creo", el regalo, te giras y andas. Son unos veinte segundos de principio a fin. Se hace entero porque el orden ES la técnica: cualquiera de esas frases suelta es solo algo majo que le dices a un desconocido.'},{type:"quote",text:"Everything else in this app is a variation on this one sequence. Learn the spine first, and then the compliments, the demo and the price all have somewhere to hang.",textEs:"Todo lo demás en esta app es una variación de esta misma secuencia. Apréndete la columna vertebral primero, y luego los cumplidos, la demo y el precio ya tienen dónde apoyarse.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"stop-2":{id:"stop-2",categoryId:"stopping",title:"The Compliment Stop",titleEs:"La Parada del Cumplido",subtitle:"15 compliment openers for different situations, plus when compliments backfire",subtitleEs:"El cumplido específico es tu mejor abridor",duration:"8 min",icon:"Star",order:2,xpReward:100,sections:[{type:"header",text:"A Genuine Compliment Opens More Doors Than Any Pitch",textEs:"Un Cumplido Genuino Abre Más Puertas Que Cualquier Pitch"},{type:"paragraph",text:"The compliment stop is the most versatile stopping technique because it works on everyone. Who doesn't like being noticed? A well-delivered compliment creates an instant positive emotion, breaks the stranger barrier, and gives the customer a reason to engage. But it MUST be genuine. Fake compliments are detected instantly and destroy trust before it begins.",textEs:"La parada del cumplido es la técnica de detención más versátil porque funciona con todos. ¿A quién no le gusta ser notado? Un cumplido bien entregado crea una emoción positiva instantánea, rompe la barrera del desconocido y le da al cliente una razón para conectar. Pero DEBE ser genuino. Los cumplidos falsos se detectan al instante y destruyen la confianza antes de que empiece."},{type:"keypoint",text:"The compliment stop formula: Specific observation + Genuine warmth + Immediate transition to product. The compliment is the hook; the smooth transition to the demo is the catch.",textEs:"La fórmula de la parada del cumplido: Observación específica + Calidez genuina + Transición inmediata al producto. El cumplido es el anzuelo; la transición fluida a la demo es el gancho."},{type:"divider"},{type:"subheader",text:"15 Compliment Openers by Situation",textEs:"15 Abridores de Cumplido por Situación"},{type:"paragraph",text:"These are word-for-word openers you can adapt. The key is specificity — the more specific, the more real it feels.",textEs:"Estos son abridores palabra por palabra que puedes adaptar. La clave es la especificidad — mientras más específico, más real se siente."},{type:"bullets",items:["ACCESSORY FOCUS: 'That scarf is gorgeous — the color is perfect on you! Let me show you something that would complement your style...'","GROOMING: 'Your skin is absolutely glowing! What do you use? ... Actually, let me show you my secret weapon for keeping that glow...'","NAIL FOCUS: 'I love that you keep your nails natural — they look so healthy! Speaking of nails, I have something you'll adore...'","STYLE: 'That jacket is incredible — you clearly know quality. Speaking of quality, let me show you something amazing...'","ENERGY: 'You have such a warm smile! I can tell you're having a great day. Can I make it even better with a quick gift?'","COUPLE COMPLIMENT: 'You two look like you're having the best vacation! I have something that will make your {locationName} trip even more memorable...'","BAG COMPLEMENT: 'That bag is stunning — is it [brand]? You clearly appreciate the finer things. Let me show you my favorite luxury find here...'","CONFIDENCE: 'I love your confidence — you walk like you own the street! Quick question: do you ever get dry skin from the mountain air?'","EYE FOCUS: 'You have beautiful eyes! Let me show you something that makes them look even more incredible...'","SHOE APPRECIATION: 'Those boots are perfect for a day walking around {locationName}! Stylish AND practical. Let me give you a quick spa moment for your hands to match...'","FAMILY WARMTH: 'Your family is adorable! Are you all having a wonderful time? I have something that makes an amazing family gift...'","ELEGANCE: 'You look so elegant — like you just stepped out of a magazine! Let me show you the secret to that just-returned-from-spa glow...'","VITAMIN D (TAN): 'That vacation glow is everything! Where were you? ... Let me show you how to keep that skin looking incredible...'","WATCH: 'Beautiful watch — you clearly appreciate quality craftsmanship. Let me show you a skincare tool with the same level of precision...'","HAIR: 'Your hair is stunning! What do you use? ... You clearly invest in yourself. Let me show you what I invest in for my skin...'"],itemsEs:["FOCO EN ACCESORIO: '¡Esa bufanda es preciosa — el color te queda perfecto! Déjame mostrarte algo que complementaría tu estilo...'","CUIDADO PERSONAL: '¡Tu piel está absolutamente radiante! ¿Qué usas? ... En realidad, déjame mostrarte mi arma secreta para mantener ese brillo...'","FOCO EN UÑAS: 'Me encanta que mantengas tus uñas naturales — ¡se ven tan saludables! Hablando de uñas, tengo algo que te va a encantar...'","ESTILO: 'Esa chaqueta es increíble — claramente conoces de calidad. Hablando de calidad, déjame mostrarte algo asombroso...'","ENERGÍA: '¡Tienes una sonrisa tan cálida! Se nota que estás teniendo un gran día. ¿Puedo hacerlo aún mejor con un regalito rápido?'","CUMPLIDO A PAREJA: '¡Vosotros dos parecéis estar teniendo las mejores vacaciones! Tengo algo que hará tu viaje a {locationName} aún más memorable...'","COMPLEMENTO DE BOLSA: 'Esa bolsa es impresionante — ¿es [brand]? Claramente aprecias las cosas finas. Déjame mostrarte mi hallazgo de lujo favorito aquí...'","CONFIANZA: 'Me encanta tu confianza — ¡caminas como si la calle fuera tuya! Pregunta rápida: ¿alguna vez se te reseca la piel por el aire de la montaña?'","FOCO EN OJOS: '¡Tienes unos ojos hermosos! Déjame mostrarte algo que los hace ver aún más increíbles...'","APRECIACIÓN DE ZAPATOS: '¡Esas botas son perfectas para un día andando por {locationName}! Estilosas Y prácticas. Déjame darte un momento spa rápido para tus manos a juego...'","CALIDEZ FAMILIAR: '¡Tu familia es adorable! ¿Todos la están pasando maravillosamente? Tengo algo que es un regalo familiar increíble...'","ELEGANCIA: '¡Te ves tan elegante — como si salieras de una revista! Déjame mostrarte el secreto para ese brillo de recién salida del spa...'","VITAMINA D (BRONCEADO): '¡Ese bronceado vacacional lo es todo! ¿Dónde estuviste? ... Déjame mostrarte cómo mantener esa piel luciendo increíble...'","RELOJ: 'Hermoso reloj — claramente aprecias la artesanía de calidad. Déjame mostrarte una herramienta de cuidado de piel con el mismo nivel de precisión...'","CABELLO: '¡Tu cabello es deslumbrante! ¿Qué usas? ... Claramente inviertes en ti mismo. Déjame mostrarte en qué invierto yo para mi piel...'"]},{type:"divider"},{type:"subheader",text:"The Anatomy of a Compliment That Works",textEs:"La Anatomía de un Cumplido Que Funciona"},{type:"numbered",items:["IT'S SPECIFIC: 'Nice jacket' is weak. 'That olive green jacket brings out your eyes perfectly' is strong. Specificity = observation = real.","IT'S ABOUT THEIR CHOICE: Compliment things they chose (clothes, accessories, grooming) not things they were born with (unless it's eyes — those work universally).","IT LEADS NATURALLY TO PRODUCT: The best compliments have a bridge. 'Beautiful nails' → Nail Kit. 'Glowing skin' → Peeling. 'Quality taste' → Any product. The bridge must feel natural, not forced.","IT'S DELIVERED WITH EYE CONTACT: Look them in the eye. Smile genuinely. Pause for 1 second after the compliment. Let it land. Then transition."],itemsEs:["ES ESPECÍFICO: 'Qué chaqueta más bonita' es débil. 'Esa chaqueta verde oliva resalta tus ojos perfectamente' es fuerte. Especificidad = observación = real.","ES SOBRE SU ELECCIÓN: Cumplimenta cosas que eligieron (ropa, accesorios, cuidado personal) no cosas con las que nacieron (a menos que sean ojos — esos funcionan universalmente).","CONDUCE NATURALMENTE AL PRODUCTO: Los mejores cumplidos tienen un puente. 'Uñas hermosas' → Kit de Uñas. 'Piel radiante' → Peeling. 'Gusto de calidad' → Cualquier producto. El puente debe sentirse natural, no forzado.","SE ENTREGA CON CONTACTO VISUAL: Míralos a los ojos. Sonríe genuinamente. Pausa 1 segundo después del cumplido. Déjalo caer. Luego transiciona."]},{type:"divider"},{type:"subheader",text:"Complimenting Men vs. Women",textEs:"Cumplimentando Hombres vs. Mujeres"},{type:"paragraph",text:"Compliments to men require a different approach. Many men are less accustomed to receiving compliments from strangers, so the technique must be adjusted:",textEs:"Los cumplidos a hombres requieren un enfoque diferente. Muchos hombres están menos acostumbrados a recibir cumplidos de desconocidos, así que la técnica debe ajustarse:"},{type:"bullets",items:["FOR MEN: Focus on style choices, accessories (watch, shoes), or partner compliments. 'Sir, your wife clearly has amazing taste — look at how she glows after this treatment!' This includes him through his partner.","FOR WOMEN: Broader range works — style, grooming, accessories, energy. Women typically receive more compliments, so yours needs to be specific and genuine to stand out.","FOR COUPLES: Complimenting the woman and engaging the man works better than the reverse. Most couples are comfortable with the woman receiving attention; the man feels included through his role as observer and validator."],itemsEs:["PARA HOMBRES: Enfócate en elecciones de estilo, accesorios (reloj, zapatos), o cumplidos a la pareja. 'Señor, su esposa claramente tiene un gusto increíble — ¡mire cómo brilla después de este tratamiento!' Esto lo incluye a él a través de su pareja.","PARA MUJERES: Funciona un rango más amplio — estilo, cuidado personal, accesorios, energía. Las mujeres típicamente reciben más cumplidos, así que el tuyo necesita ser específico y genuino para destacar.","PARA PAREJAS: Cumplimentar a la mujer y enganchar al hombre funciona mejor que al revés. La mayoría de las parejas se sienten cómodas con que la mujer reciba atención; el hombre se siente incluido a través de su rol como observador y validador."]},{type:"divider"},{type:"subheader",text:"When Compliments Backfire",textEs:"Cuando los Cumplidos Fallan"},{type:"paragraph",text:"Compliments can work against you if done poorly. Here are the danger zones:",textEs:"Los cumplidos pueden jugar en tu contra si se hacen mal. Aquí están las zonas de peligro:"},{type:"bullets",items:["GENERIC COMPLIMENTS: 'You're beautiful' feels like a line. 'That emerald scarf is perfect with your coloring' feels like an observation. Specificity is the difference between charm and creepiness.","TOO MANY COMPLIMENTS: One genuine compliment opens the door. Three compliments feels like flattery. Move on after the first one.","INAPPROPRIATE FOCUS: Never compliment body parts, weight, or anything that could feel objectifying. Stick to choices they've made — clothes, accessories, grooming, style.","FAKE ENTHUSIASM: If you don't mean it, don't say it. Customers can detect false compliments instantly. It's better to skip the compliment and use a different opener than to deliver a fake one."],itemsEs:["CUMPLIDOS GENÉRICOS: 'Eres hermosa' se siente como una frase hecha. 'Esa bufanda esmeralda es perfecta con tu tono de piel' se siente como una observación. La especificidad es la diferencia entre encanto y incomodidad.","DEMASIADOS CUMPLIDOS: Un cumplido genuino abre la puerta. Tres cumplidos se sienten como halago. Sigue adelante después del primero.","FOCO INAPROPIADO: Nunca cumplimentes partes del cuerpo, peso, o algo que pueda sentirse como objetificación. Quédate en las elecciones que han hecho — ropa, accesorios, cuidado personal, estilo.","ENTUSIASMO FALSO: Si no lo sientes, no lo digas. Los clientes pueden detectar cumplidos falsos al instante. Es mejor saltarte el cumplido y usar un abridor diferente que entregar uno falso."]},{type:"script",text:"'I love your nails — you keep them so natural and healthy! Speaking of nails, I have the most amazing little gift for you. Just two minutes, I promise you'll be shocked.' Compliment → Bridge → Time-bound invitation → Intrigue. That's the formula.",textEs:"'Me encantan tus uñas — ¡las mantienes tan naturales y saludables! Hablando de uñas, tengo el regalito más increíble para ti. Solo dos minutos, te prometo que te va a sorprender.' Cumplido → Puente → Invitación con tiempo límite → Intriga. Esa es la fórmula."},{type:"quote",text:"A genuine compliment is the only opening line that makes the customer feel good about themselves before they feel anything about you. That's a powerful place to start.",textEs:"Un cumplido genuino es la única línea de apertura que hace que el cliente se sienta bien consigo mismo antes de sentir algo sobre ti. Ese es un punto de partida poderoso.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What makes a compliment feel genuine rather than fake?",options:["Using elaborate and flowery language","Being specific about something the person chose","Complimenting their physical appearance generically","Giving multiple compliments rapidly"],correctIndex:1,explanation:"Specific compliments about choices people make (clothes, accessories, grooming) feel like real observations. Generic or physical compliments often feel like lines or flattery."},{question:"What is the recommended approach when complimenting men?",options:["Compliment their body or physique","Focus on style choices, accessories, or partner compliments that include them indirectly","Avoid complimenting men entirely","Use the same approach as for women"],correctIndex:1,explanation:"Men are often less accustomed to receiving compliments from strangers. Focus on style choices, accessories, or compliment their partner while engaging them as the observer."},{question:"When should you avoid using a compliment opener?",options:["When the customer looks angry or rushed","When you cannot find something genuinely specific to compliment","When the customer is in a group","When it is raining"],correctIndex:1,explanation:"If you cannot find something genuinely specific to compliment, it is better to use a different stopping technique. Fake compliments are detected instantly and destroy trust."}]},"stop-3":{id:"stop-3",categoryId:"stopping",title:"The Humor Stop",titleEs:"La Parada del Humor",subtitle:"Making them smile before they can say no — funny openers that actually work",subtitleEs:"Ríe primero, vende después",duration:"8 min",icon:"Smile",order:3,xpReward:100,sections:[{type:"header",text:"If They Smile, They Stop. If They Stop, You Sell.",textEs:"Si Sonríen, Paran. Si Paran, Vendes."},{type:"paragraph",text:"Humor is the ultimate disarmer. When someone laughs, their guard drops. They're no longer in 'defend against salesperson' mode — they're in 'this person is fun' mode. A smile creates a micro-moment of connection that buys you the 10 seconds you need to deliver your pitch. But humor is a scalpel, not a hammer. Use it precisely.",textEs:"El humor es el mejor desarmador. Cuando alguien se ríe, baja la guardia. Ya no está en modo 'defenderse del vendedor' — está en modo 'esta persona es divertida'. Una sonrisa crea un micro-momento de conexión que te compra los 10 segundos que necesitas para lanzar tu pitch. Pero el humor es un bisturí, no un martillo. Úsalo con precisión."},{type:"keypoint",text:"The humor stop formula: Light observational humor + Self-awareness about selling + Quick transition to value. You're not doing stand-up comedy — you're just breaking the tension with a smile.",textEs:"La fórmula de la parada del humor: Humor observacional ligero + Autoconciencia sobre vender + Transición rápida al valor. No estás haciendo stand-up comedy — solo estás rompiendo la tensión con una sonrisa."},{type:"divider"},{type:"subheader",text:"Funny Openers That Work",textEs:"Abridores Divertidos Que Funcionan"},{type:"paragraph",text:"These openers acknowledge the awkwardness of street selling and turn it into a shared joke:",textEs:"Estos abridores reconocen lo incómodo de vender en la calle y lo convierten en una broma compartida:"},{type:"bullets",items:["THE HONEST APPROACH: 'I know, I know — another salesperson. But I promise, this is the one time today you'll actually be glad someone stopped you.'","THE SELF-DEPRECATING: 'I'm clearly not very good at this because you're still walking, but give me 30 seconds and I'll change your mind.'","THE CHALLENGE: 'Two minutes. If you don't love it, you can tell me I'm terrible at my job. Deal?'","THE OVERDRAMATIC: 'STOP! Don't make me chase you! ... Okay, I won't chase you because that would be creepy. But seriously, two seconds.'","THE REALITY CHECK: 'I know you're thinking 'not another one.' I think the same thing when I walk down this street on my day off.'","THE CURIOSITY HOOK: 'Can I ask you something? What made you look over here just now? ... Exactly! Your instincts are good. Come see why.'"],itemsEs:["EL ENFOQUE HONESTO: 'Lo sé, lo sé — otro vendedor. Pero te prometo que esta es la única vez hoy que vas a agradecer que alguien te detuviera.'","EL AUTODEPRECATIVO: 'Claramente no soy muy bueno en esto porque sigues caminando, pero dame 30 segundos y te haré cambiar de opinión.'","EL RETO: 'Dos minutos. Si no te encanta, me puedes decir que soy terrible en mi trabajo. ¿Trato?'","EL DRAMÁTICO: '¡ALTO! ¡No me hagas perseguirte! ... Ok, no te voy a perseguir porque sería raro. Pero en serio, dos segundos.'","EL TOQUE DE REALIDAD: 'Sé que estás pensando 'otro más.' Yo pienso lo mismo cuando camino por esta calle en mi día libre.'","EL GANCHO DE CURIOSIDAD: '¿Te puedo preguntar algo? ¿Qué te ha hecho girarte ahora mismo? ... ¡Exacto! Tus instintos son buenos. Ven a ver por qué.'"]},{type:"divider"},{type:"subheader",text:"Humor by Product",textEs:"Humor por Producto"},{type:"paragraph",text:"Product-specific humor that connects the joke to what you're selling:",textEs:"Humor específico por producto que conecta la broma con lo que estás vendiendo:"},{type:"bullets",items:["SYRINGE: 'Don't worry, it's not that kind of syringe! No needles, just magic for your eyes. Promise.'","NAIL KIT: 'I promise not to scream when I show you this. My last customer did, and her husband got jealous.'","SCRUB: 'This will make your hands softer than a baby's... actually, that's a weird comparison. Just trust me, they're going to feel incredible.'","PEELING: 'This is my favourite trick for glowing skin. And by trick I mean miracle. But trick sounds cooler.'"],itemsEs:["JERINGA: '¡No te preocupes, no es ese tipo de jeringa! Sin agujas, solo magia para tus ojos. Prometido.'","KIT DE UÑAS: 'Prometo no gritar cuando te muestre esto. Mi última clienta sí gritó, y su esposo se puso celoso.'","EXFOLIANTE: 'Esto va a dejar tus manos más suaves que las de un bebé... bueno, esa comparación está rara. Solo confía en mí, van a sentirse increíbles.'","PEELING: 'Este es mi truco favorito para piel radiante. Y por truco me refiero a un milagro. Pero truco suena más cool.'"]},{type:"divider"},{type:"subheader",text:"Reading Humor Receptivity",textEs:"Leyendo la Receptividad al Humor"},{type:"paragraph",text:"Not everyone responds to humor. Here's how to read who will:",textEs:"No todo el mundo responde al humor. Así es como leer a quién sí le funcionará:"},{type:"bullets",items:["GREEN FOR HUMOR: Smiling already, laughing with their companion, playful energy, eye contact with a twinkle, young or young-at-heart vibe, casual relaxed clothing.","RED FOR HUMOR: Frowning, intense purpose in their walk, formal business attire with serious demeanor, on a phone call, visibly stressed or angry.","YELLOW FOR HUMOR: Neutral expression but not negative, solo traveler (harder to read), older customer (test with gentle humor first)."],itemsEs:["VERDE PARA HUMOR: Ya sonriendo, riendo con su acompañante, energía juguetona, contacto visual con brillo en los ojos, vibra joven o joven de corazón, ropa casual y relajada.","ROJO PARA HUMOR: Frunciendo el ceño, caminando con propósito intenso, atuendo formal de negocios con comportamiento serio, en una llamada, visiblemente estresado o enojado.","AMARILLO PARA HUMOR: Expresión neutral pero no negativa, viajero solo (más difícil de leer), cliente mayor (prueba con humor suave primero)."]},{type:"tip",text:"Try a light one first. If they smile, go further. If the joke dies, don't chase it — just go straight and quick instead. 'Fair enough. Thirty seconds, then, and I'll let you get on.' Warm, fast, no sulking. The dead joke costs you nothing; going stiff about it costs you the sale.",textEs:"Prueba primero con algo ligero. Si sonríen, sube la apuesta. Si el chiste se muere, no lo persigas — ve directo y rápido. 'Vale, vale. Treinta segundos y te dejo seguir.' Cálido, rápido, sin enfurruñarte. El chiste muerto no te cuesta nada; ponerte tieso por eso te cuesta la venta."},{type:"divider"},{type:"subheader",text:"Cultural Humor Differences",textEs:"Diferencias Culturales de Humor"},{type:"paragraph",text:"Humor doesn't translate equally across cultures:",textEs:"El humor no se traduce igual entre culturas:"},{type:"bullets",items:["SPANISH: Appreciate warmth and playful energy. Physical humor and exaggeration work. Self-deprecating humor is charming.","FRENCH: Subtle, witty humor works better than slapstick. Intellectual observations are appreciated. Avoid overly silly humor.","BRITISH: Self-deprecating humor is the national sport. They LOVE it. Dry wit and understatement are their love language.","EASTERN EUROPEAN: Direct humor works. Bold statements with a smile. They appreciate confidence more than subtlety.","GENERAL RULE: Physical comedy (demonstrative gestures, funny faces during the demo) transcends language barriers. Actions are funnier than words."],itemsEs:["ESPAÑOLES: Aprecian la calidez y la energía juguetona. El humor físico y la exageración funcionan. El humor autodepreciativo es encantador.","FRANCESES: El humor sutil e ingenioso funciona mejor que el slapstick. Las observaciones intelectuales se aprecian. Evita el humor demasiado tonto.","BRITÁNICOS: El humor autodepreciativo es el deporte nacional. ¡LO ADORAN! El ingenio seco y la understatement son su lenguaje del amor.","EUROPEOS ORIENTALES: El humor directo funciona. Declaraciones atrevidas con una sonrisa. Aprecian la confianza más que la sutileza.","REGLA GENERAL: La comedia física (gestos demostrativos, caras graciosas durante la demo) trasciende barreras del idioma. Las acciones son más divertidas que las palabras."]},{type:"divider"},{type:"subheader",text:"When Humor Backfires",textEs:"Cuando el Humor Falla"},{type:"bullets",items:["FORCED HUMOR: If it doesn't come naturally to you, don't force it. Awkward humor is worse than no humor.","TOO MUCH: One joke opens the door. Three jokes makes you a comedian trying to sell something. Keep it light and move on.","AT SOMEONE'S EXPENSE: Never joke about the customer's appearance, clothing, or companion. Self-deprecating humor ONLY.","INAPPROPRIATE TOPICS: Stay away from politics, religion, crude humor, or anything edgy. Keep it universally safe.","IGNORING SIGNALS: If they don't laugh at your first attempt, pivot. Don't keep trying to 'win them over' with humor."],itemsEs:["HUMOR FORZADO: Si no te sale natural, no lo fuerces. El humor incómodo es peor que ningún humor.","DEMASIADO: Una broma abre la puerta. Tres bromas te convierten en un comediante intentando vender algo. Manténlo ligero y sigue adelante.","A COSTA DE ALGUIEN: Nunca bromees sobre la apariencia, ropa o acompañante del cliente. Humor autodepreciativo SOLAMENTE.","TÓPICOS INAPROPIADOS: Mantente alejado de política, religión, humor vulgar o cualquier cosa controversial. Mantenlo universalmente seguro.","IGNORAR SEÑALES: Si no se ríen en tu primer intento, pivotea. No sigas intentando 'conquistarlos' con humor."]},{type:"script",text:"'I know what you're thinking — not another salesperson! I think the same thing when I'm shopping. But here's the thing — this demo takes literally two minutes, and everyone who tries it walks out smiling. Even the people who don't buy. Want to see why?' Humor → relatability → value proposition → invitation.",textEs:"'Sé lo que estás pensando — ¡otro vendedor! Yo pienso lo mismo cuando voy de compras. Pero mira — esta demo toma literalmente dos minutos, y todos los que la prueban se van sonriendo. Hasta los que no compran. ¿Quieres ver por qué?' Humor → empatía → propuesta de valor → invitación."},{type:"quote",text:"Laughter is the shortest distance between two strangers. Cross that distance, and the rest of the sale becomes a conversation.",textEs:"La risa es la distancia más corta entre dos desconocidos. Cruza esa distancia, y el resto de la venta se convierte en una conversación.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What is the humor stop formula?",options:["Tell as many jokes as possible","Light observational humor + self-awareness about selling + quick transition to value","Make fun of the customer gently","Use physical comedy only"],correctIndex:1,explanation:"The humor stop uses light observational humor, acknowledges the awkwardness of street selling, and quickly transitions to value. You're not doing stand-up — you're breaking tension with a smile."},{question:"Which type of humor is universally safest in sales?",options:["Political humor","Self-deprecating humor","Sarcasm about the customer","Edgy jokes"],correctIndex:1,explanation:"Self-deprecating humor is safest because it shows confidence and vulnerability without risking offense. You're the punchline, never the customer."},{question:"The joke dies. What do you do?",options:["Try harder and land a bigger joke on them","Go straight and quick instead","Give up on that customer","Make a more extreme joke"],correctIndex:1,explanation:"Don't chase a dead joke. 'Fair enough. Thirty seconds, then, and I'll let you get on.' The dead joke costs you nothing; going stiff about it costs you the sale."}]},"stop-4":{id:"stop-4",categoryId:"stopping",title:"The Urgency Stop",titleEs:"La Parada de Urgencia",subtitle:"Urgency that lands and urgency that dies",subtitleEs:"La urgencia que entra y la urgencia que se muere",duration:"8 min",icon:"Clock",order:4,xpReward:100,sections:[{type:"header",text:"Make Them Feel the Moment",textEs:"Hazles Sentir el Momento"},{type:"paragraph",text:"Urgency is the oldest tool on the street, and it works because a decision with no deadline never gets made. 'I'll think about it' is not a maybe, it is a no with better manners. Give them a reason for it to be today and they decide today.",textEs:"La urgencia es la herramienta más antigua de la calle, y funciona porque una decisión sin fecha límite no se toma nunca. 'Me lo pienso' no es un quizá, es un no con mejores modales. Dales un motivo para que sea hoy y deciden hoy."},{type:"keypoint",text:"Urgency is a performance and everybody knows it. 'Two left.' 'That's gone at closing.' 'I've already done this once today.' That is the street, and they are enjoying it every bit as much as you are. The one line you never cross: never promise something the shop has to honour after they have walked out. Everything else is yours to play with.",textEs:"La urgencia es un espectáculo y todo el mundo lo sabe. 'Me quedan dos.' 'Eso se acaba al cerrar.' 'Hoy ya lo he hecho una vez.' Eso es la calle, y ellos lo disfrutan tanto como tú. La única línea que no se cruza: no prometas nunca algo que la tienda tenga que cumplir cuando ya se hayan ido. Todo lo demás es tuyo para jugar."},{type:"divider"},{type:"subheader",text:"Types of Urgency That Work",textEs:"Tipos de Urgencia Que Funcionan"},{type:"numbered",items:["TIME: 'We're closing in half an hour.' 'That offer's gone tonight.' A deadline turns a maybe into a decision, which is the only thing you are after.","QUANTITY: 'I've only got two left.' 'That scent went in a weekend.' Nobody wants to be the one who missed it. Say it flat, like it is just information.","LOCATION: 'The syringe is {currency}300 here. Cross the border and it is back to {currency}500.' The strongest one you have, because it does not even need selling.","SEASON: 'Christmas is in two weeks and this is the easiest present you will buy all month.' The calendar does the pushing for you.","THE DEMO ITSELF: 'You have already felt it. You know what it does. What exactly are you going to think about?' The best urgency of the lot, because they made it themselves."],itemsEs:["TIEMPO: 'Cerramos en media hora.' 'Esa oferta se acaba esta noche.' Una fecha límite convierte un quizá en una decisión, que es lo único que buscas.","CANTIDAD: 'Solo me quedan dos.' 'Ese aroma voló en un fin de semana.' Nadie quiere ser el que se lo pierde. Dilo a pelo, como si fuera información y ya está.","SITIO: 'La jeringa son {currency}300 aquí. Cruzas la frontera y vuelve a {currency}500.' La más fuerte que tienes, porque ni siquiera hay que venderla.","TEMPORADA: 'La Navidad es en dos semanas y este es el regalo más fácil que vas a comprar este mes.' El calendario empuja por ti.","LA PROPIA DEMO: 'Ya lo has notado. Ya sabes lo que hace. ¿Qué te tienes que pensar exactamente?' La mejor de todas, porque se la han montado ellos solos."]},{type:"divider"},{type:"subheader",text:"Urgency Openers by Situation",textEs:"Abridores de Urgencia por Situación"},{type:"bullets",items:["'I only have two samples of our best-seller left — want to see what everyone's been talking about?' (Quantity scarcity)","'We're closing soon, but I can squeeze you in for a 2-minute demo that'll blow your mind.' (Time pressure + value)","'This offer's gone when we close tonight. I know, I know, it sounds like a sales line — have a look at the sign.' (Naming the trick and doing it anyway lands better than either on its own)","'The last customer bought our last two scrubs in this scent. Want to see what the hype is about before the rest are gone?' (Social proof + scarcity)","'You're here at the perfect time — we just restocked the syringe after selling out all weekend. But they go fast.' (Fresh availability creates urgency)"],itemsEs:["'Solo me quedan dos muestras de nuestro más vendido — ¿quieres ver de qué ha estado hablando todo el mundo?' (Escasez por cantidad)","'Cerramos pronto, pero te puedo hacer espacio para una demo de 2 minutos que te volará la cabeza.' (Presión de tiempo + valor)","'Esta oferta se acaba cuando cerremos esta noche. Ya lo sé, ya lo sé, suena a frase de vendedor — mira el cartel.' (Cantar el truco y hacerlo igual entra mejor que cualquiera de las dos cosas por separado)","'El último cliente se llevó nuestros últimos dos exfoliantes de este aroma. ¿Quieres ver de qué va el hype antes de que se acaben el resto?' (Prueba social + escasez)","'Llegaste en el momento perfecto — acabamos de reabastecer la jeringa después de agotarse todo el fin de semana. Pero se van rápido.' (La disponibilidad fresca crea urgencia)"]},{type:"divider"},{type:"subheader",text:"Urgency That Lands vs. Urgency That Dies",textEs:"La Urgencia Que Entra vs. La Que Se Muere"},{type:"comparison",left:{label:"Urgency That Lands",text:"Specific, and said straight. 'Two left.' 'That's gone at closing.' Straight face, half a smile, then you carry on as if you had mentioned the weather. And the second they say no you drop it completely — 'Fine, fine, I tried. Enjoy your day.' Dropping it instantly is what makes the next one land."},leftEs:{label:"La Urgencia Que Entra",text:"Concreta, y dicha a pelo. 'Me quedan dos.' 'Eso se acaba al cerrar.' Cara seria, media sonrisa, y sigues como si hubieras hablado del tiempo. Y en cuanto te dicen que no, lo sueltas del todo — 'Vale, vale, lo he intentado. Que disfrutes del día.' Soltarlo al momento es lo que hace que funcione la siguiente."},right:{label:"Urgency That Dies",text:"Vague and limp — 'you should really get it while you are here.' Nothing to take hold of. Or said apologetically, eyes down, like you do not believe it yourself. Or worst of all, repeated after they have already said no, which turns two seconds of theatre into somebody following them up the street."},rightEs:{label:"La Urgencia Que Se Muere",text:"Vaga y sin fuerza — 'deberías llevártelo ya que estás aquí'. No hay de dónde coger. O dicha pidiendo perdón, con la mirada baja, como si tú tampoco te lo creyeras. O peor todavía, repetida después de que ya te han dicho que no, que convierte dos segundos de teatro en alguien siguiéndolos por la calle."}},{type:"tip",text:"It is all in the delivery. Same six words land or die depending on whether you say them like a fact or like a favour you are begging for. And there is one hard line underneath all of it: never promise anything the shop has to honour once they are out of the door — no coming back tomorrow, no ask-for-me-by-name, no money back. You will be on a different pitch and somebody else has to have that argument.",textEs:"Todo está en cómo lo dices. Las mismas seis palabras entran o se mueren según las sueltes como un dato o como un favor que estás suplicando. Y debajo de todo hay una línea que no se cruza: no prometas nada que la tienda tenga que cumplir cuando ya estén fuera — nada de vuelve mañana, nada de pregunta por mí, nada de te devuelvo el dinero. Tú estarás en otro sitio y la discusión se la come otro."},{type:"divider"},{type:"subheader",text:"Seasonal Urgency: Christmas & Peak Season",textEs:"Urgencia Estacional: Navidad y Temporada Alta"},{type:"paragraph",text:"Peak season (November-February) creates natural urgency that you should leverage:",textEs:"La temporada alta (noviembre-febrero) crea urgencia natural que debes aprovechar:"},{type:"bullets",items:["CHRISTMAS SHOPPING: 'This is the easiest Christmas gift you'll buy. Everyone loves it, it's unisex, and it actually gets used.' Gift purchases have a natural deadline — December 25th.","LAST-MINUTE GIFTS: 'Christmas is in 5 days. If you're still looking for gifts, this is your answer. Small, elegant, and under {currency}60.'","SKI SEASON (mountain shops only): 'After a day on the slopes, your skin is so dry from the mountain air. This is what the locals use to recover.' Seasonal relevance creates immediate need.","WEEKEND RUSH: 'Weekends are crazy here. I'd hate for you to come back and find your scent sold out.' Weekend timing creates shopping pressure."],itemsEs:["COMPRAS NAVIDEÑAS: 'Este es el regalo de Navidad más fácil que vas a comprar. A todos les encanta, es unisex, y de verdad se usa.' Las compras de regalo tienen una fecha límite natural — el 25 de diciembre.","REGALOS DE ÚLTIMO MINUTO: 'La Navidad es en 5 días. Si todavía buscas regalos, esta es tu respuesta. Pequeño, elegante, y menos de {currency}60.'","TEMPORADA DE ESQUÍ (solo tiendas de montaña): 'Después de un día en las pistas, tu piel queda súper seca por el aire de la montaña. Esto es lo que usan los locales para recuperarse.' La relevancia de temporada crea necesidad inmediata.","LOCURA DE FIN DE SEMANA: 'Los fines de semana son una locura aquí. Me sabría fatal que volvieras y encontraras tu aroma agotado.' El timing de fin de semana crea presión de compra."]},{type:"script",text:"'Look, I'm not going to do the whole hard sell on you. I'll just tell you where we are: I had a pile of these yesterday and I have got eight left. The weekend starts tomorrow. If you want it, take it now. If you're not sure, honestly, no pressure — but I can't promise it'll be here tomorrow.' Notice how it works: you take the pressure off with one hand and put the deadline down with the other, and they hear the second half.",textEs:"'Mira, no te voy a dar el rollo de vendedor. Te digo dónde estamos y ya: ayer tenía un montón de estos y me quedan ocho. El fin de semana empieza mañana. Si lo quieres, llévatelo ahora. Si no lo tienes claro, de verdad, sin presión — pero no te puedo prometer que mañana siga aquí.' Fíjate en cómo funciona: con una mano les quitas la presión y con la otra les pones la fecha límite, y lo que oyen es la segunda parte."},{type:"quote",text:"Urgency isn't about pressuring people. It's about helping them overcome procrastination. The customer who genuinely wants your product but leaves to 'think about it' often never returns. Urgency helps them make the decision they already want to make.",textEs:"La urgencia no se trata de presionar a la gente. Se trata de ayudarles a superar la procrastinación. El cliente que genuinamente quiere tu producto pero se va a 'pensarlo' a menudo nunca vuelve. La urgencia les ayuda a tomar la decisión que ya quieren tomar.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"What separates urgency that lands from urgency that dies?",options:["Whether the customer already wanted the product before you spoke","The delivery, and dropping it the moment they say no","How many different urgency lines you manage to use in a row","Whether you say it before or after you have given them the price"],correctIndex:1,explanation:"Same six words land or die on the delivery. Specific, straight face, half a smile — and dropped the second they say no. 'Fine, fine, I tried. Enjoy your day.'"},{question:"Which type of urgency is the {locationName} price gap?",options:["Time-based urgency","Location-based urgency","Quantity-based urgency","Seasonal urgency"],correctIndex:1,explanation:"The price gap is location-based urgency. The syringe is {currency}300 in {locationName}. Once the customer crosses the border, it goes back to {currency}500. This is genuine, verifiable scarcity."},{question:"Why does urgency help customers who genuinely want your product?",options:["It tricks them into buying","It helps them overcome procrastination and make a decision they already want to make","It makes them feel guilty","It confuses them"],correctIndex:1,explanation:"Urgency helps customers overcome natural procrastination. Many customers who leave to 'think about it' never return. Ethical urgency helps them make the decision they already want to make."}]},"stop-5":{id:"stop-5",categoryId:"stopping",title:"Product-Specific Stops",titleEs:"Paradas Según el Producto",subtitle:"Detailed scripts for each product matched to the person's visible traits",subtitleEs:"Guiones para cada producto según lo que ves en la persona",duration:"10 min",icon:"Sparkles",order:5,xpReward:150,sections:[{type:"header",text:"Match the Product to the Person",textEs:"Empareja el Producto con la Persona"},{type:"paragraph",text:"A generic stop works. A specific one works better. When your first line connects to something you can actually see about the person, it lands like somebody noticing them instead of somebody working. Beautiful natural nails give you a nail-kit line. Tired eyes give you a syringe line. Same job, better sentence.",textEs:"Una parada genérica funciona. Una concreta funciona mejor. Cuando tu primera frase conecta con algo que de verdad le ves a la persona, suena a que alguien se ha fijado en ella y no a que alguien está currando. Unas uñas naturales bonitas te dan una frase de kit de uñas. Unos ojos cansados te dan una frase de jeringa. El mismo trabajo, mejor frase."},{type:"keypoint",text:"The formula: see something → connect it to a product → open with that. And read the lists below for what they are: they tell you WHICH LINE to use, never WHO to bother with. You stop everybody. Nothing on this page is permission to let somebody walk past because they did not match a bullet point.",textEs:"La fórmula: ves algo → lo conectas con un producto → abres por ahí. Y lee las listas de abajo por lo que son: te dicen QUÉ FRASE usar, nunca CON QUIÉN molestarte. Paras a todo el mundo. Nada de esta página es permiso para dejar pasar a nadie porque no encaje con una viñeta."},{type:"divider"},{type:"subheader",text:"The Syringe Stop (Eye Treatment)",textEs:"La Parada de la Jeringa (Tratamiento para Ojos)"},{type:"paragraph",text:"Where this line lands hardest: visible under-eye bags, crow's feet, tired-looking eyes, anybody who mentions a long trip. It is also the line you use when you can see nothing at all, because the eyes are what this shop sells and everybody has got two.",textEs:"Dónde pega más fuerte esta frase: bolsas visibles, patas de gallo, ojos con cara de cansancio, cualquiera que mencione un viaje largo. Y también es la frase que usas cuando no ves nada de nada, porque los ojos son lo que vende esta tienda y todo el mundo tiene dos."},{type:"bullets",items:["THE DIRECT APPROACH: 'You look amazing — but the eyes... maybe we can make them look even more relaxed?' Said with a cheeky smile. This opener acknowledges their overall appearance while pinpointing the improvement area.","THE TIRED TRAVELER: 'Long trip? I can see it in your eyes — and not in a good way. Let me fix that in two minutes.' For people who genuinely look tired from travel.","THE AGE-APPROPRIATE: 'You clearly take great care of yourself. Want to see what I can do around the eyes? It's like a spa treatment in two minutes.' Positions it as enhancement, not correction.","THE COMPLEMENT TO MAKEUP: 'Your makeup is flawless! Let me show you something that makes the eyes pop even more without any makeup.' Appeals to beauty enthusiasts."],itemsEs:["EL ENFOQUE DIRECTO: 'Te ves increíble, pero los ojos... ¿quizá podemos hacer que se vean más relajados?' Dicho con una sonrisa pícara. Esta apertura reconoce su apariencia general mientras señala el área de mejora.","EL VIAJERO CANSADO: '¿Viaje largo? Se te nota en los ojos, y no de buena manera. Déjame arreglar eso en dos minutos.' Para personas que genuinamente se ven cansadas por el viaje.","EL ENFOQUE POR EDAD: 'Claramente te cuidas mucho. ¿Quieres ver qué puedo hacer alrededor de los ojos? Es como un tratamiento de spa en dos minutos.' Lo posiciona como una mejora, no como una corrección.","EL COMPLEMENTO AL MAQUILLAJE: '¡Tu maquillaje está impecable! Déjame mostrarte algo que hace que los ojos resalten aún más sin ningún maquillaje.' Atrae a los entusiastas de la belleza."]},{type:"script",text:"'You have beautiful eyes — but I can see the travel fatigue. Let me show you our secret weapon. Two minutes, one eye, and you'll see the difference yourself in the mirror. It's honestly shocking.' Specific observation + time promise + intrigue.",textEs:"'Tienes unos ojos hermosos, pero se nota el cansancio del viaje. Déjame mostrarte nuestro arma secreta. Dos minutos, un ojo, y verás la diferencia tú misma en el espejo. Es honestamente impactante.' Observación específica + promesa de tiempo + intriga."},{type:"divider"},{type:"subheader",text:"The Peeling Stop (Glow Treatment)",textEs:"La Parada del Peeling (Tratamiento de Brillo)"},{type:"paragraph",text:"Where this line lands hardest: dull or dry skin, anybody who asks you about routines, somebody young who is chasing glow rather than years, anybody who says they want to look 'fresher'.",textEs:'Dónde pega más fuerte esta frase: piel apagada o seca, quien te pregunta por rutinas, alguien joven que va detrás del brillo y no de los años, quien dice que quiere verse "más fresca".'},{type:"bullets",items:["THE GLOW HOOK: 'Your skin is nice, but I can give you that 'just got back from vacation' glow in two minutes. Want to see?'","THE SKINCARE ENTHUSIAST: 'I can tell you care about your skin. Let me show you my favorite weekly treatment — it's completely different from daily cream.'","THE DRY SKIN ANGLE: 'The mountain air here is so drying. Let me show you something that removes all the dead skin instantly — your cream will work 10 times better.'","THE AGE-DEFYING: 'This is what I use once a week to keep my skin looking fresh. Want to try it? It's like a facial at home.' Peer recommendation works especially well from younger staff."],itemsEs:["EL GANCHO DEL BRILLO: 'Tu piel está bien, pero puedo darte ese brillo de 'acabo de volver de vacaciones' en dos minutos. ¿Quieres ver?'","EL ENTUSIASTA DEL CUIDADO DE LA PIEL: 'Se nota que te importa tu piel. Déjame mostrarte mi tratamiento semanal favorito, es completamente diferente de la crema diaria.'","EL ÁNGULO DE LA PIEL SECA: 'El aire de la montaña aquí reseca mucho. Déjame mostrarte algo que elimina toda la piel muerta al instante, tu crema funcionará 10 veces mejor.'","EL ANTI-EDAD: 'Esto es lo que uso una vez por semana para mantener mi piel fresca. ¿Quieres probarlo? Es como un facial en casa.' La recomendación de un igual funciona especialmente bien con el personal más joven."]},{type:"script",text:"'Let me show you my favorite quick trick for glowing skin. It's a weekly treatment that removes all the dead layers — your regular cream will work so much better after. Two minutes, and you'll feel the difference immediately.' Quick, friendly, no pressure.",textEs:"'Déjame mostrarte mi truco rápido favorito para piel radiante. Es un tratamiento semanal que elimina todas las capas muertas, tu crema regular funcionará mucho mejor después. Dos minutos, y sentirás la diferencia de inmediato.' Rápido, amigable, sin presión."},{type:"divider"},{type:"subheader",text:"The Scrub & Body Butter Stop",textEs:"La Parada del Exfoliante y Body Butter"},{type:"paragraph",text:"Where this line lands hardest: dry or cracked hands (especially in winter), anybody who mentions the mountain air, people shopping for presents, couples — it is unisex and nobody is embarrassed to touch it.",textEs:"Dónde pega más fuerte esta frase: manos secas o agrietadas (sobre todo en invierno), quien menciona el aire de la montaña, quien va comprando regalos, parejas — es unisex y a nadie le da corte tocarlo."},{type:"bullets",items:["THE DRY SKIN QUESTION: 'Do you ever get dry skin? Ugh, I know — it's the worst. You know what? Let me give you something amazing. Come!' This classic opener works because almost everyone has dry skin, especially after a day of travelling.","THE SENSORY HOOK: 'Want to feel something incredible? This is from the Dead Sea — lowest place on Earth, highest mineral concentration. Your hands have never felt this soft.'","THE GIFT ANGLE: 'Looking for Christmas gifts? This is our most popular one — everyone loves it, it's unisex, and it's actually useful. Feel this...'","THE COVID LEGACY: 'Since Covid, everyone's hands are so dry from sanitizer. This became our #1 seller — people were like, 'Finally something that actually helps!''"],itemsEs:["LA PREGUNTA DE LA PIEL SECA: '¿Alguna vez te reseca la piel? Uf, lo sé, es lo peor. ¿Sabes qué? Déjame darte algo increíble. ¡Ven!' Esta apertura clásica funciona porque casi todo el mundo tiene la piel seca, especialmente después de un día viajando.","EL GANCHO SENSORIAL: '¿Quieres sentir algo increíble? Esto es del Mar Muerto, el lugar más bajo de la Tierra, la concentración mineral más alta. Tus manos nunca se han sentido tan suaves.'","EL ÁNGULO DEL REGALO: '¿Buscas regalos de Navidad? Este es el más popular, a todo el mundo le encanta, es unisex, y de verdad es útil. Siente esto...'","EL LEGADO DEL COVID: 'Desde el Covid, las manos de todos están muy resecas por el sanitizante. Este se convirtió en nuestro #1 en ventas, la gente decía, '¡Por fin algo que de verdad ayuda!''"]},{type:"script",text:"'Do you ever get dry skin, especially in winter? Let me show you something from the Dead Sea. Rub this on your hand... now add water... feel that? That's not just soft — that's mineral-treated skin. And it lasts even after you wash your hands.' Interactive demo + education.",textEs:"'¿Te reseca la piel a veces, especialmente en invierno? Déjame mostrarte algo del Mar Muerto. Frota esto en tu mano... ahora agrega agua... ¿sientes eso? Eso no es solo suavidad, es piel tratada con minerales. Y dura incluso después de lavarte las manos.' Demo interactiva + educación."},{type:"divider"},{type:"subheader",text:"The Nail Kit Stop",textEs:"La Parada del Kit de Uñas"},{type:"paragraph",text:"Where this line lands hardest: natural nails with no heavy polish, nails somebody clearly looks after, people shopping for presents, anybody who tells you they hate what the salon does to them.",textEs:"Dónde pega más fuerte esta frase: uñas naturales sin esmalte grueso, uñas que alguien se cuida claramente, quien va comprando regalos, cualquiera que te diga que odia lo que le hacen en el salón."},{type:"bullets",items:["THE NATURAL NAIL APPRECIATION: 'Wow! You always keep your nails natural? That's awesome. Let me give you a small gift — you're gonna love this.'","THE CONTRAST APPROACH: 'I see you have polish on — that's pretty! But you know what? Let me show you how gorgeous your natural nail can look without any chemicals.'","THE GIFT APPROACH: 'These make the perfect gifts — small, elegant, and everyone actually uses them. Watch this...'","THE SALON ALTERNATIVE: 'This replaces salon visits. Natural shine that lasts two weeks, no chemicals, lifetime warranty. Look at this...'"],itemsEs:["LA APRECIACIÓN DE UÑAS NATURALES: '¡Wow! ¿Siempre llevas tus uñas naturales? Eso es genial. Déjame darte un pequeño regalo, te va a encantar esto.'","EL ENFOQUE DE CONTRASTE: 'Veo que llevas esmalte, ¡está bonito! Pero ¿sabes qué? Déjame mostrarte qué tan hermosa puede verse tu uña natural sin ningún químico.'","EL ENFOQUE DE REGALO: 'Estos son los regalos perfectos, pequeños, elegantes, y todo el mundo de verdad los usa. Mira esto...'","LA ALTERNATIVA AL SALÓN: 'Esto reemplaza las visitas al salón. Brillo natural que dura dos semanas, sin químicos, garantía de por vida. Mira esto...'"]},{type:"script",text:"'Wow, you keep your nails so natural and healthy! Let me show you something — this isn't a regular buffer. It brings out your natural shine without any polish or chemicals. Watch... see? Nothing yet. Now the last step... WOW. That is YOUR natural nail. No polish. It stays like this for two weeks.' Build anticipation, deliver the reveal.",textEs:"'¡Wow, mantienes tus uñas tan naturales y saludables! Déjame mostrarte algo, este no es un pulidor común. Saca tu brillo natural sin ningún esmalte ni químicos. Mira... ¿ves? Aún nada. Ahora el último paso... WOW. Esa es TU uña natural. Sin esmalte. Se queda así por dos semanas.' Genera anticipación, entrega la revelación."},{type:"divider"},{type:"subheader",text:"One Line In. Then You Let Go.",textEs:"Una Frase para Entrar. Y Luego Sueltas."},{type:"paragraph",text:"Never open with two products. Two options at four metres is a decision, and a stranger walking past does not want to make one — they want to be pulled in by one clear thing. So you pick your line, you get them through the door, and then you are done with the choosing.",textEs:"Nunca abras con dos productos. Dos opciones a cuatro metros son una decisión, y un desconocido que va pasando no quiere tomar ninguna — quiere que algo claro tire de él. Así que eliges tu frase, los metes por la puerta, y ahí se te acaba lo de elegir."},{type:"bullets",items:["THE LINE IS A DOOR, NOT A CONTRACT: you opened on nails and the demo goes to the eyes? Perfect. Nobody sat down expecting a menu. Whatever got them in has done its whole job.","THE EYES ARE WHAT THE SHOP SELLS: whichever line worked, the syringe is what the day is counted in. The scrub and the nail kit are how you learn to sell and how you keep the energy up — they are not the target.","IN YOUR FIRST TWO WEEKS YOU DO NOT DEMO AT ALL: you stop, you bring them in, you hand them to a colleague and you go straight back out. That is the entire job and it is the hardest part of it.","COMBOS ARE NOT A STOPPING TOOL: the small products share one ladder — two for {currency}60, three for {currency}120 — and that belongs to whoever is sitting in the chair with them, not to your opening line on the pavement."],itemsEs:["LA FRASE ES UNA PUERTA, NO UN CONTRATO: ¿has abierto por las uñas y la demo se va a los ojos? Perfecto. Nadie se ha sentado esperando un menú. Lo que los ha metido dentro ya ha hecho todo su trabajo.","LO QUE VENDE LA TIENDA SON LOS OJOS: haya funcionado la frase que sea, la jeringa es lo que cuenta en el día. El exfoliante y el kit de uñas son cómo aprendes a vender y cómo mantienes la energía — no son el objetivo.","EN TUS PRIMERAS DOS SEMANAS NO HACES DEMOS: paras, los metes dentro, se los pasas a un compañero y sales otra vez. Ese es el trabajo entero y es la parte más difícil.","LOS COMBOS NO SON UNA HERRAMIENTA DE PARADA: los productos pequeños comparten escalera — dos por {currency}60, tres por {currency}120 — y eso es de quien esté sentado con ellos, no de tu frase de apertura en la acera."]},{type:"tip",text:"If you catch yourself listing things on the pavement, you have already lost the stop. One line, one product, one reason to follow you in. Everything else happens sitting down.",textEs:"Si te pillas enumerando cosas en la acera, ya has perdido la parada. Una frase, un producto, un motivo para entrar detrás de ti. Todo lo demás pasa sentados."},{type:"quote",text:"The best stops don't feel like stops. They feel like a friend noticing something about you. Notice something true, say it, and walk them in — the rest of the shop can take it from there.",textEs:"Las mejores paradas no parecen paradas. Parecen un amigo que se ha fijado en algo tuyo. Fíjate en algo de verdad, dilo, y mételes dentro — el resto de la tienda ya sigue desde ahí.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}]},"stop-6":{id:"stop-6",categoryId:"stopping",title:"The Recovery Stop",titleEs:"La Parada de Recuperación",subtitle:"What to do when they say 'no' — the second attempt, and when it is genuinely over",subtitleEs:"Qué hacer cuando dicen 'no' — el segundo intento, y cuándo se acabó de verdad",duration:"8 min",icon:"RotateCcw",order:6,xpReward:100,sections:[{type:"header",text:"'No' Is Not the End. It's Just the Beginning.",textEs:"El 'No' No Es el Final. Es Solo el Principio."},{type:"paragraph",text:"Most sellers hear 'no thanks' and that is the end of it. But 'no' out here usually means 'not yet', or 'not that one', or 'you caught me mid-thought'. The recovery is the one more line you throw after the no — not to wear anybody down, but to find out whether the no was real.",textEs:"La mayoría de los vendedores oyen 'no, gracias' y ahí se acaba todo. Pero aquí fuera el 'no' casi siempre quiere decir 'ahora no', o 'ese no', o 'me has pillado pensando en otra cosa'. La recuperación es esa frase de más que sueltas después del no — no para desgastar a nadie, sino para averiguar si el no iba en serio."},{type:"keypoint",text:"That first 'no thanks' is not a decision. They said it before they had even heard you — it is a reflex, the same as saying 'fine' when somebody asks how you are. It costs you one more line to find out whether they meant it. Most sellers on this street never spend that line. That is your edge.",textEs:"Ese primer 'no, gracias' no es una decisión. Lo han dicho antes incluso de escucharte — es un acto reflejo, igual que decir 'bien' cuando te preguntan qué tal estás. Te cuesta una frase más averiguar si lo decían en serio. Casi ningún vendedor de esta calle gasta esa frase. Ahí está tu ventaja."},{type:"divider"},{type:"subheader",text:"Why They Said No (And What to Do About It)",textEs:"Por Qué Dijeron No (Y Qué Hacer Al Respecto)"},{type:"paragraph",text:"Not all 'nos' are equal. Understanding which type you're dealing with determines your recovery strategy:",textEs:"No todos los 'nos' son iguales. Entender con cuál tipo te enfrentas determina tu estrategia de recuperación:"},{type:"bullets",items:["THE REFLEX NO: Automatic, without thinking. They didn't even process what you said. Response: Acknowledge and re-engage with humor or curiosity.","THE RUSH NO: 'No thanks, I'm in a hurry.' They have somewhere to be. Response: Respect the time constraint, offer a faster alternative.","THE SKEPTICAL NO: 'I don't believe you.' They've been burned before. Response: Social proof, evidence, or a no-risk trial.","THE BUDGET NO: 'I can't afford it.' Nobody says this at the top of the ladder — by the time it lands you have already walked her down, so you are not defending {currency}300 any more, you are fighting for {currency}140 and sometimes {currency}100. Response: say the number you are actually standing on, put a reason on the next rung down, and make that last price sound like something you bent for her — not something that was sitting there. Never say 'come back when you can' — she does not come back.","THE POLITE NO: 'No thank you.' Said gently, often with a smile. They are not interested YET and they are being polite about it. Response: they have not heard a price, a product or a reason — so you have not been turned down, you have been brushed past. Give them the one line you have not used and put something in their hand."],itemsEs:["EL NO REFLEJO: Automático, sin pensar. Ni siquiera procesaron lo que dijiste. Respuesta: Reconoce y vuelve a interactuar con humor o curiosidad.","EL NO POR PRISA: 'No gracias, tengo prisa.' Tienen algún lugar al que ir. Respuesta: Respeta la limitación de tiempo, ofrece una alternativa más rápida.","EL NO ESCÉPTICO: 'No te creo.' Los han quemado antes. Respuesta: Prueba social, evidencia, o una prueba sin riesgo.","EL NO POR DINERO: 'No me lo puedo permitir.' Esto no lo dice nadie arriba de la escalera — cuando llega ya la has bajado, así que ya no estás defendiendo {currency}300, estás peleando por {currency}140 y a veces por {currency}100. Respuesta: di el número en el que estás de verdad, pon un motivo en el escalón siguiente y haz que ese último precio suene a algo que has doblado por ella — no a algo que ya estaba ahí. Nunca 'vuelve cuando puedas'. No vuelve.","EL NO EDUCADO: 'No, gracias.' Dicho suavemente, a menudo con una sonrisa. TODAVÍA no están interesados y encima son educados. Respuesta: no han oído ni precio, ni producto, ni motivo — así que no te han dicho que no, te han esquivado con buenos modales. Suelta la frase que aún no has usado y ponles algo en la mano."]},{type:"divider"},{type:"subheader",text:"Second Attempt Techniques",textEs:"Técnicas de Segundo Intento"},{type:"paragraph",text:"When the first stop fails, try one of these recovery approaches:",textEs:"Cuando la primera parada falla, prueba uno de estos enfoques de recuperación:"},{type:"numbered",items:["THE HUMOR RECOVERY: 'I know, I know — you weren't planning to stop today. But I promise you, this is the one time you'll be glad you did. Thirty seconds?' Humor disarms the automatic 'no.'","THE CURIOSITY HOOK: 'I get it — you're busy. But can I ask you something? When was the last time a stranger showed you something that actually impressed you?' Curiosity overrides rejection.","THE TIME RECOVERY: 'Ah, don't worry about it. How about this — I won't even explain anything. Just let me do it. If you don't love it in thirty seconds, you walk off. Deal?' Takes away the fear of being stuck with you for ten minutes.","THE SOCIAL PROOF RECOVERY: 'You know what? Every single person who just walked past me said the same thing. And every single one who came back to try it bought something. I'm just saying...' Creates intrigue through social proof.","THE GIFT REFRAME: 'I know you weren't looking for it, but I want to GIVE you something. No purchase, no catch. Just a free hand treatment because your hands deserve it.' Reframing as a gift removes the sales pressure."],itemsEs:["LA RECUPERACIÓN CON HUMOR: 'Lo sé, lo sé, no planeabas parar hoy. Pero te prometo que esta es la única vez en la que te alegrarás de haberlo hecho. ¿Treinta segundos?' El humor desarma el 'no' automático.","EL GANCHO DE LA CURIOSIDAD: 'Lo entiendo, estás ocupado. Pero ¿puedo preguntarte algo? ¿Cuándo fue la última vez que un desconocido te mostró algo que realmente te impresionó?' La curiosidad anula el rechazo.","LA RECUPERACIÓN POR TIEMPO: 'Ah, no te preocupes por eso. ¿Qué tal esto? No te explico nada. Déjame hacerlo y ya está. Si no te encanta en treinta segundos, te vas. ¿Trato?' Les quita el miedo a quedarse contigo diez minutos.","LA RECUPERACIÓN CON PRUEBA SOCIAL: '¿Sabes qué? Cada persona que acaba de pasar a mi lado dijo lo mismo. Y cada una de las que volvieron a probarlo compró algo. Solo digo...' Crea intriga a través de la prueba social.","EL replanteo COMO REGALO: 'Sé que no lo estabas buscando, pero quiero DARTE algo. Sin compra, sin truco. Solo un tratamiento de manos gratis porque tus manos lo merecen.' Replantearlo como un regalo elimina la presión de venta."]},{type:"divider"},{type:"subheader",text:"Humorous Recovery Lines",textEs:"Líneas de Recuperación Humorísticas"},{type:"paragraph",text:"These work best with customers who smiled or seemed friendly even while saying no:",textEs:"Estas funcionan mejor con clientes que sonrieron o parecieron amigables incluso mientras decían que no:"},{type:"bullets",items:["'You're breaking my heart! Just kidding — but seriously, you're missing out.'","'Okay, but when you walk past our shop later and see everyone smiling inside, you'll wonder what you missed.'","'Go on then. But I'm telling you now — you'll be thinking about me over dinner.' (Cheeky, and it does not hand them a reason to postpone.)","'My manager is watching — can you at least pretend to be interested for 10 seconds?' (Self-deprecating humor that creates connection.)","'That's the fourth 'no' in a row. You're all going to make me cry!' (Playful, not desperate.)"],itemsEs:["'¡Me estás rompiendo el corazón! Es broma, pero en serio, te estás perdiendo de algo.'","'Está bien, pero cuando pases frente a nuestra tienda más tarde y veas a todos sonriendo adentro, te preguntarás qué te perdiste.'","'Venga, vale. Pero te aviso — vas a estar pensando en mí durante la cena.' (Con guasa, y sin darles una excusa para dejarlo para luego.)","'Mi encargado está viendo, ¿puedes al menos fingir interés por 10 segundos?' (Humor autocrítico que crea conexión.)","'Ese es el cuarto 'no' seguido. ¡Todos me van a hacer llorar!' (Juguetón, no desesperado.)"]},{type:"tip",text:"Recovery humor only works if your energy is genuinely playful, not needy. If you feel desperate, customers sense it. Recover from a place of abundance ('I have something great to show you') not scarcity ('Please, I need this sale').",textEs:"El humor de recuperación solo funciona si tu energía es genuinamente juguetona, no necesitada. Si te sientes desesperado, los clientes lo sienten. Recupérate desde un lugar de abundancia ('Tengo algo genial para mostrarte') no de escasez ('Por favor, necesito esta venta')."},{type:"divider"},{type:"subheader",text:"The Last Line You Leave Them With",textEs:"La Última Frase Que Les Dejas"},{type:"paragraph",text:"If the second attempt lands, you are back in business. If it genuinely does not, the last line still matters — but it is a line that buys you one more second here, never one that arms them to deal with you some other day:",textEs:"Si el segundo intento entra, ya estás otra vez dentro. Y si de verdad no entra, la última frase sigue importando — pero es una frase que te compra un segundo más aquí, nunca una que les dé con qué dejarte para otro día:"},{type:"script",text:"'No problem at all! Enjoy your day in {locationName}. But hey — when you see someone walk out of our shop with that 'wow' look on their face, remember I offered!' Said with a grin over your shoulder, this turns people round on the spot more often than any pitch does. Deliver it like a joke, not like a goodbye.",textEs:"'¡No pasa nada! Disfruta el día en {locationName}. Pero oye — cuando veas a alguien salir de nuestra tienda con esa cara de 'guau', ¡acuérdate de que te lo ofrecí!' Dicho con una sonrisa por encima del hombro, esto hace que se den la vuelta ahí mismo más que ningún discurso. Suéltalo como una broma, no como una despedida."},{type:"bullets",items:["NOTHING GOES IN THEIR POCKET: No card, no flyer, no price written on anything. It feels helpful and it is the most expensive thing you can hand a person — you have just given them permission to go and think about it somewhere you are not standing.","POINT AT THE TABLE, NOT AT TOMORROW: 'It is two steps. Put your hand on it and then tell me no.' A tiny, specific ask beats an open invitation every single time.","NAME THE THING THEY WERE LOOKING AT: 'You did not take your eyes off that peeling. Sixty seconds and you will know.' Being properly seen is what turns a walker around.","IF THE NO IS REAL, MEAN IT: 'Fair enough, gorgeous — have a lovely day.' Warm, quick, nothing attached to it. Then straight back to the pavement, because the next one is already walking past you."],itemsEs:["QUE NO SE LLEVEN NADA EN EL BOLSILLO: Ni tarjeta, ni folleto, ni el precio apuntado en ningún sitio. Parece un detalle y es lo más caro que le puedes dar a nadie — acabas de darle permiso para irse a pensarlo donde tú no estás.","SEÑALA LA MESA, NO EL MAÑANA: 'Si son dos pasos. Pon la mano aquí y luego me dices que no.' Una petición pequeña y concreta gana siempre a una invitación abierta.","NOMBRA LO QUE ESTABAN MIRANDO: 'No le has quitado el ojo de encima al peeling. Sesenta segundos y lo sabes.' Que se sientan vistos de verdad es lo que hace que se den la vuelta.","SI EL NO ES DE VERDAD, QUE SEA DE VERDAD: 'Nada, guapa, que tengas buen día.' Con cariño, rápido y sin nada colgando. Y vuelta a la acera, que el siguiente ya está pasando por delante."]},{type:"divider"},{type:"subheader",text:"Knowing When to Let Go",textEs:"Saber Cuándo Soltar"},{type:"paragraph",text:"This is critical: recovery stops work, but pushy persistence doesn't. There's a line between persistence and harassment. Here's how to know when to stop:",textEs:"Esto es crítico: las paradas de recuperación funcionan, pero la persistencia agresiva no. Hay una línea entre la persistencia y el acoso. Aquí te decimos cuándo detenerte:"},{type:"bullets",items:["ONE RECOVERY ATTEMPT: One more line after the no. That is the whole point of this lesson and it costs you nothing.","TWO RECOVERY ATTEMPTS: If the first recovery fails and they seem receptive, a second (different) approach is acceptable.","THREE OR MORE: This is pushing. If two attempts fail, let them go gracefully. Pursuing further damages your reputation and the shop's reputation.","BODY LANGUAGE SIGNALS: Crossed arms, stepping away, flat expression, no engagement — these are definitive 'stop' signals. Respect them immediately.","VERBAL SHUTDOWN: 'Please leave me alone,' 'I said no,' or aggressive language means immediate disengagement. Smile, apologize, and step back."],itemsEs:["UN INTENTO DE RECUPERACIÓN: Una frase más después del no. De eso va toda esta lección y no te cuesta nada.","DOS INTENTOS DE RECUPERACIÓN: Si la primera recuperación falla y parecen receptivos, un segundo enfoque (diferente) es aceptable.","TRES O MÁS: Esto es ser insistente. Si dos intentos fallan, déjalos ir con elegancia. Seguir insistiendo daña tu reputación y la reputación de la tienda.","SEÑALES DE LENGUAJE CORPORAL: Brazos cruzados, alejarse, expresión plana, sin interacción, estas son señales definitivas de 'detente.' respétalas de inmediato.","CIERRE VERBAL: 'Por favor déjame en paz,' 'Ya te dije que no,' o lenguaje agresivo significa desvinculación inmediata. Sonríe, discúlpate, y retrocede."]},{type:"quote",text:"Two lines after the no, and then you are done — not because they might come back tomorrow, they will not, but because you gave that one everything it was worth and the next one is already walking towards you. A desperate chase costs you the person behind them.",textEs:"Dos frases después del no y se acabó — no porque vayan a volver mañana, que no van a volver, sino porque a esa le has dado todo lo que valía y la siguiente ya viene andando hacia ti. Perseguir a la desesperada te cuesta la persona que venía detrás.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Why is the first 'no thanks' worth one more line?",options:["Because most people give in if you keep at them long enough","Because it is usually a reflex, said before they heard you","Because the shop counts every approach you make in a shift","Because a customer who says no twice is ready to be closed"],correctIndex:1,explanation:"The first no comes out before they have processed a word you said — the same as saying 'fine' when somebody asks how you are. One more line finds out whether they meant it, and most sellers never spend it."},{question:"How many recovery attempts should you generally make before letting go?",options:["As many as it takes","One, or two if they are still smiling — then let it go","Never attempt recovery — respect the first no","Five or more, because insisting is what wears people down"],correctIndex:1,explanation:"One more line is free. A second one is fine if they are still with you. A third turns a bit of banter into somebody following them up the street, and that is the shop's reputation, not just yours."}]},"stop-7":{id:"stop-7",categoryId:"stopping",title:"Finding YOUR Stopping Style",titleEs:"Encontrando TU Estilo de Parada",subtitle:"Why copying others does not work — assessing your personality and building your unique approach",subtitleEs:"Descubre qué funciona para ti",duration:"8 min",icon:"Compass",order:7,xpReward:100,sections:[{type:"header",text:"Your Best Style Is the One That Fits YOU",textEs:"Tu Mejor Estilo Es el Que Te Queda a TI"},{type:"paragraph",text:"New salespeople often try to copy the top performer verbatim. They use the same words, the same gestures, the same energy. And it falls flat. Why? Because the top performer has found a style that fits THEIR personality — their humor, their energy, their body language, their voice. You need to find YOURS. The goal isn't to be a clone. It's to be the best version of yourself on the floor.",textEs:"Los vendedores nuevos a menudo intentan copiar al mejor vendedor palabra por palabra. Usan las mismas palabras, los mismos gestos, la misma energía. Y cae plano. ¿Por qué? Porque el mejor vendedor ha encontrado un estilo que se ajusta a SU personalidad, su humor, su energía, su lenguaje corporal, su voz. Tú necesitas encontrar el TUYO. La meta no es ser un clon. Es ser la mejor versión de ti mismo en el piso."},{type:"keypoint",text:"There is no single 'best' stopping style. The best style is the one that feels authentic to YOU while being effective with customers. A calm, warm seller can outsell a high-energy seller — if they lean into their strengths.",textEs:"No existe un único estilo de parada 'mejor.' El mejor estilo es el que se siente auténtico para TI mientras es efectivo con los clientes. Un vendedor tranquilo y cálido puede vender más que uno de alta energía, si aprovechan sus fortalezas."},{type:"divider"},{type:"subheader",text:"Personality Assessment: Who Are You on the Floor?",textEs:"Evaluación de Personalidad: ¿Quién Eres en el Piso?"},{type:"paragraph",text:"Before choosing your style, honestly assess your natural tendencies:",textEs:"Antes de elegir tu estilo, evalúa honestamente tus tendencias naturales:"},{type:"bullets",items:["HIGH ENERGY or CALM? Do you naturally speak fast, move quickly, and radiate enthusiasm? Or are you more measured, warm, and steady? Both work — but forcing calm when you're energetic (or vice versa) feels fake.","DIRECT or INDIRECT? Straight to the point, or a bit of chat first? Some of you go in hard and some of you need to warm them up. Both work. Faking the other one does not.","HUMOUR or STRAIGHT? Are you actually funny? Do people laugh around you? If yes, that is your weapon. If not, do not force it — warm and straight sells just as much, and a forced joke sells nothing.","VERBAL or PHYSICAL? Some sellers captivate with words — smooth talkers. Others captivate with the demo — the product does the talking. Know which one you are."],itemsEs:["¿ALTA ENERGÍA o CALMA? ¿Hablas rápido naturalmente, te mueves con rapidez, y irradias entusiasmo? ¿O eres más mesurado, cálido, y constante? Ambos funcionan, pero forzar la calma cuando eres enérgico (o viceversa) se siente falso.","¿DIRECTO o CON RODEOS? ¿Al grano, o un poco de charla primero? Algunos entráis a saco y otros necesitáis calentarlo antes. Las dos cosas funcionan. Fingir la otra no.","¿HUMOR o SERIEDAD? ¿Eres gracioso de verdad? ¿La gente se ríe contigo? Si sí, esa es tu arma. Si no, no lo fuerces — cálido y directo vende igual, y un chiste forzado no vende nada.","¿VERBAL o FÍSICO? Algunos vendedores cautivan con palabras, grandes conversadores. Otros cautivan con la demo, el producto habla por sí mismo. Saber cuál eres tú."]},{type:"divider"},{type:"subheader",text:"Four Stopping Archetypes",textEs:"Cuatro Arquetipos de Parada"},{type:"paragraph",text:"These archetypes aren't boxes — they're starting points. Most people blend two:",textEs:"Estos arquetipos no son cajas, son puntos de partida. La mayoría de las personas combina dos:"},{type:"numbered",items:["THE ENERGIZER: High energy, fast-paced, loud and proud. Uses humor, excitement, and enthusiasm to draw people in. Best for: young crowds, groups, holiday shoppers, anybody already in a good mood. Risk: can overwhelm a quiet customer, and it burns you out by four o'clock if you never come down.","THE WARM INVITER: Calm, warm, genuinely caring. Builds rapport quickly and quietly. Uses gentle curiosity and kindness. Best for: couples, older customers, wary customers, the person who wants to ask you things. Risk: without real attention behind it, calm just reads as flat.","THE EXPERT: Knowledgeable, confident, authority-driven. Leads with facts and lets the product speak. Best for: Analytical buyers, French tourists, skeptical customers. Risk: Can feel cold without enough warmth.","THE CHAMELEON: Adapts to each customer. High energy with energetic people, calm with calm people. Flexible and observant. Best for: Sellers with strong empathy and reading skills. Risk: Can feel inconsistent if not grounded in authenticity."],itemsEs:["EL ENERGIZADOR: Alta energía, ritmo rápido, fuerte y orgulloso. Usa humor, emoción y entusiasmo para atraer gente. Ideal para: gente joven, grupos, compradores navideños, cualquiera que ya venga de buen humor. Riesgo: puede abrumar a un cliente callado, y te deja frito a las cuatro de la tarde si no bajas nunca.","EL INVITADOR CÁLIDO: Tranquilo, cálido, cercano de verdad. Construye conexión rápido y sin ruido. Usa curiosidad amable y buen trato. Ideal para: parejas, clientes mayores, gente desconfiada, quien quiere preguntarte cosas. Riesgo: sin atención real detrás, la calma solo parece desgana.","EL EXPERTO: Conocedor, confiado, guiado por la autoridad. Lidera con hechos y deja que el producto hable. Ideal para: Compradores analíticos, turistas franceses, clientes escépticos. Riesgo: Puede sentirse frío sin suficiente calidez.","EL CAMALEÓN: Se adapta a cada cliente. Alta energía con gente enérgica, calmado con gente tranquila. Flexible y observador. Ideal para: Vendedores con fuerte empatía y habilidad de lectura. Riesgo: Puede sentirse inconsistente si no está anclado en la autenticidad."]},{type:"comparison",left:{label:"High-Energy Approach",text:"'HEY! Oh my gosh, you have to see this! Come here, come here — two minutes, I promise you'll freak out!' Works brilliantly for some. Exhausting and off-putting for others. Use when the situation matches your natural enthusiasm."},leftEs:{label:"Enfoque de Alta Energía",text:"'¡HEY! ¡Dios mío, tienes que ver esto! ¡Ven aquí, ven aquí, dos minutos, te prometo que te vas a alucinar!' Funciona brillantemente para algunos. Agotador y repelente para otros. Úsalo cuando la situación coincida con tu entusiasmo natural."},right:{label:"Calm Approach",text:"'Excuse me — I know you're busy, but I have something that might surprise you. Just two minutes, and if you don't love it, no hard feelings.' Warm, respectful, confident. Some customers prefer this 100% of the time."},rightEs:{label:"Acercamiento Tranquilo",text:"'Perdona — sé que vas liado, pero tengo algo que a lo mejor te sorprende. Solo dos minutos, y si no te encanta, no pasa nada.' Cálido, respetuoso, seguro. Hay clientes que prefieren esto el 100% de las veces."}},{type:"keypoint",text:"Your style is yours. What the day does change is how hard you work each person. A dead morning is when you try HARDER — you go after the ones you would let walk on a Saturday, because the four people who come past might be the whole day. A packed afternoon is the opposite: keep it tight, do not grind water with one person, because the moment you finish there is another one right outside.",textEs:"Tu estilo es tuyo. Lo que sí cambia con el día es lo fuerte que trabajas a cada persona. Una mañana muerta es cuando MÁS lo intentas — vas a por los que un sábado dejarías pasar, porque las cuatro personas que pasen igual son el día entero. Una tarde a tope es lo contrario: al grano, no le des vueltas al agua con una sola persona, porque en cuanto termines hay otra ahí fuera."},{type:"divider"},{type:"subheader",text:"One Morning, Two Hours",textEs:"Una Mañana, Dos Horas"},{type:"paragraph",text:"You can find this out in a morning. You do not need a month of it:",textEs:"Esto lo averiguas en una mañana. No hace falta un mes:"},{type:"numbered",items:["DO AN HOUR LOUD: Big, fast, straight in. Louder than is comfortable. Count how many came through the door.","DO AN HOUR QUIET: Slow it right down, warm it up, get them talking before you get to the product. Count again.","READ YOUR OWN NUMBERS: One of those two hours beat the other, and it will not always be the one you expected. That is your answer, and it took you a morning.","THEN STOP TESTING AND GO: Lean into whichever won and stop worrying about the other one. You can borrow bits off it later, once the main thing is second nature."],itemsEs:["HAZ UNA HORA A LO GRANDE: Alto, rápido, entrando a saco. Más alto de lo que te resulta cómodo. Cuenta cuántos entraron por la puerta.","HAZ UNA HORA TRANQUILA: Baja el ritmo del todo, ponlo cálido, hazles hablar antes de llegar al producto. Cuenta otra vez.","LEE TUS PROPIOS NÚMEROS: Una de esas dos horas le ha ganado a la otra, y no siempre es la que esperabas. Esa es tu respuesta, y te ha costado una mañana.","Y AHORA DEJA DE PROBAR Y VE: Tira por la que ha ganado y olvídate de la otra. Ya le cogerás cosas más adelante, cuando lo principal te salga solo."]},{type:"tip",text:"Two numbers at the end of each hour: how many you stopped, and how many sat down. That is all the tracking you need. The feeling lies about which hour went better — you will swear the loud one flopped and then find it did not. The numbers do not lie.",textEs:"Dos números al final de cada hora: a cuántos paraste y cuántos se sentaron. Con eso te sobra. La sensación miente sobre qué hora ha ido mejor — jurarías que la hora a lo grande fue un desastre y luego resulta que no. Los números no mienten."},{type:"divider"},{type:"subheader",text:"Recording Yourself",textEs:"Grábate a Ti Mismo"},{type:"paragraph",text:"This is uncomfortable but incredibly valuable. Ask a teammate to record a few of your stops on your phone. Then watch the footage. You'll notice things you never knew you did:",textEs:"Esto es incómodo pero increíblemente valioso. Pídele a un compañero que te grabe algunas de tus paradas con el móvil. Luego mira el video. Notarás cosas que nunca supiste que hacías:"},{type:"bullets",items:["BODY LANGUAGE: Are your arms crossed? Are you leaning away? Is your posture confident or collapsed?","FACIAL EXPRESSION: Are you genuinely smiling or forcing it? Do your eyes match your mouth?","VOICE: Do you sound confident? Do you speak too fast? Do you end statements like questions (upspeak)?","TIMING: Are you giving them space to respond? Or are you rushing through your pitch?","TRANSITION: How do you move from opener to demo? Is it smooth or awkward?"],itemsEs:["LENGUAJE CORPORAL: ¿Tienes los brazos cruzados? ¿Te estás inclinando hacia atrás? ¿Tu postura es confiada o encogida?","EXPRESIÓN FACIAL: ¿Estás sonriendo genuinamente o forzándolo? ¿Tus ojos coinciden con tu boca?","VOZ: ¿Suenas confiado? ¿Hablas demasiado rápido? ¿Terminas las afirmaciones como si fueran preguntas (entonación ascendente)?","RITMO: ¿Les estás dando espacio para responder? ¿O estás apurando tu pitch?","TRANSICIÓN: ¿Cómo pasas de la apertura a la demo? ¿Es suave o torpe?"]},{type:"tip",text:"Record yourself once per month. It's the fastest way to see your progress. Most people are shocked by how much they've improved after just one month of recording and adjusting.",textEs:"Grábate una vez por mes. Es la forma más rápida de ver tu progreso. La mayoría de las personas se sorprende de cuánto han mejorado después de solo un mes de grabarse y ajustarse."},{type:"divider"},{type:"subheader",text:"Getting Feedback from Teammates",textEs:"Obtener Retroalimentación de tus Compañeros"},{type:"paragraph",text:"Your teammates see you from the outside. Their feedback is gold. Here's how to get useful feedback:",textEs:"Tus compañeros te ven desde afuera. Su retroalimentación es oro. Aquí te decimos cómo obtener retroalimentación útil:"},{type:"bullets",items:["ASK SPECIFIC QUESTIONS: Not 'How am I doing?' but 'Did my energy seem high or low during that last stop?' or 'Was my opener clear?' Specific questions get specific answers.","ASK YOUR TOP PERFORMER: 'What do you think is my biggest opportunity for improvement?' Top performers usually have sharp observational skills.","ASK SOMEONE YOU TRUST: Feedback feels safer from someone who cares about you. Find a teammate you trust and ask for honest input.","RECEIVE WITHOUT DEFENSIVENESS: When someone gives feedback, say 'Thank you' and process it. Defensive reactions shut down future feedback."],itemsEs:["HAZ PREGUNTAS ESPECÍFICAS: No '¿Cómo me va?' sino '¿Mi energía pareció alta o baja durante esa última parada?' o '¿Mi apertura fue clara?' Las preguntas específicas obtienen respuestas específicas.","PREGÚNTALE A TU MEJOR VENDEDOR: '¿Qué crees que es mi mayor oportunidad de mejora?' Los mejores vendedores suelen tener habilidades de observación agudas.","PREGÚNTALE A ALGUIEN EN QUIEN CONFÍES: La retroalimentación se siente más segura de alguien que se preocupa por ti. Encuentra un compañero en quien confíes y pídele una opinión honesta.","RECIBE SIN DEFENSIVIDAD: Cuando alguien te da retroalimentación, di 'Gracias' y procésala. Las reacciones defensivas cierran la puerta a futura retroalimentación."]},{type:"quote",text:"The best stopping style isn't the one that looks best on someone else. It's the one that makes you feel confident, authentic, and effective. Find it, refine it, own it.",textEs:"El mejor estilo de parada no es el que se ve mejor en alguien más. Es el que te hace sentir confiado, auténtico, y efectivo. Encuéntralo, reflínelo, aduéñate de él.",attribution:"Zero Lines Method",attributionEs:"Método Zero Lines"}],quiz:[{question:"Why is copying the top performer's style verbatim usually ineffective?",options:["Because the top performer is naturally talented","Because the top performer's style fits THEIR personality, not yours","Because customers prefer new approaches","Because it's unethical"],correctIndex:1,explanation:"The top performer has found a style that fits their unique personality, humor, energy, and voice. Your style should be the best version of YOU, not a clone of someone else."},{question:"What is the fastest way to find your own stopping style?",options:["Copy whatever the top seller on the street does","An hour loud, an hour quiet, then count","Stick with whichever one feels most comfortable","Try a different style every hour for a month"],correctIndex:1,explanation:"Do an hour loud, do an hour quiet, count how many came through the door. One of those hours beat the other, and it took you a morning instead of a month."},{question:"Why is recording yourself valuable for style development?",options:["To post on social media","To see your blind spots — body language, voice, timing, and facial expressions you don't notice in the moment","To show the manager you're working","To send to customers"],correctIndex:1,explanation:"Recording reveals blind spots you can't see yourself — posture, facial expressions, voice tone, pacing, and awkward transitions. Watching footage is the fastest way to spot improvement opportunities."}]},...r,...l,...u};for(const[e,i]of Object.entries(d)){const a=s[e];a&&(a.quiz=i)}function h(e){return s[e]}export{h as g,s as l};
